        linear-gradient(90deg, rgba(var(--accent-rgb), .16), rgba(255,255,255,.03));
    box-shadow:
        0 0 0 1px rgba(var(--accent-rgb), .08),
        inset 0 1px 0 rgba(255,255,255,.05),
        0 16px 30px rgba(var(--accent-rgb), .06);
}

.server-modal-nav-btn[hidden] {
