    background:
        linear-gradient(180deg, rgba(var(--accent-rgb), .035), rgba(255,255,255,.015)),
        rgba(255,255,255,.02);
    box-shadow: inset 0 1px 0 rgba(255,255,255,.03);
}

.server-channel-create-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding-bottom: 2px;
