}

.recent-account-switch:disabled {
    border-color: rgba(var(--accent-rgb), .28);
    background: rgba(var(--accent-rgb), .08);
    color: var(--text2);
    cursor: default;
    opacity: 1;
}

.recent-account-remove {
    width: 36px;
    padding: 0;
    border-radius: 14px;
    border-color: rgba(255,255,255,.095);
    background: rgba(255,255,255,.035);
    color: var(--text3);
    font-size: 18px;
    line-height: 1;
}

.recent-account-remove:hover {
    border-color: rgba(255,77,109,.34);
    color: var(--red);
    box-shadow: 0 0 0 2px rgba(255,77,109,.08);
}

.settings-logout {
    position: relative;
    z-index: 1;
    width: 100%;
    justify-content: center;
    border-radius: 12px;
    background: rgba(255,77,109,.08);
    border-color: rgba(255,77,109,.18);
    transition: transform .18s var(--ease-out), box-shadow .18s var(--ease-out), border-color .18s var(--ease-out), color .18s var(--ease-out), background .18s var(--ease-out);
}

.settings-logout:hover {
    border-color: var(--red);
    color: var(--red);
    box-shadow: 0 0 0 2px rgba(255,77,109,.12);
}

.settings-toggle {
    margin-top: 4px;
}

.settings-body .log-body {
    padding: 14px;
    font-size: 11px;
}

.msgs {
    min-height: 0;
    overflow-y: auto;
    padding: 18px 22px;
    overflow-anchor: none;
}

.msg-window-spacer {
    display: block;
    width: 100%;
    flex: 0 0 auto;
    pointer-events: none;
}

.msg {
    display: flex;
    gap: 9px;
    align-items: flex-end;
    position: relative;
    margin: 0 0 calc(var(--msg-gap) * 1px);
    /* Same containment .contact already carries: it caps how far a single row's
       layout invalidation can propagate, so editing/hydrating one bubble stops
       costing a relayout of the entire list inside the blurred panel.
       `paint` is deliberately NOT in the list — .msg.group-start::before sits at
       top:-7px, outside the row's own box, and paint containment would clip that
       separator away. layout+style clip nothing, and .msg is already
       position:relative + a flex container, so neither the containing block for
       absolute descendants nor the formatting context changes here. */
    contain: layout style;
}

.server-msg {
    display: flex;
    gap: 10px;
    align-items: flex-start;
    justify-content: flex-start;
    margin: 0 0 calc(var(--msg-gap) * 1px);
}

.msg.out {
    justify-content: flex-end;
}

.msg.call-msg .bwrap {
    width: fit-content;
    max-width: min(560px, 74%);
}

.msg.single,
.msg.group-start {
    margin-top: 12px;
}

.msg.group-mid,
.msg.group-end {
    margin-top: 2px;
}

.msg.group-start::before {
    content: "";
    position: absolute;
    left: 34px;
    right: 34px;
    top: -7px;
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,.09) 18%, rgba(255,255,255,.09) 82%, transparent);
    pointer-events: none;
}

.msg.out.group-start::before {
    background: linear-gradient(90deg, transparent, rgba(var(--accent-rgb),.10) 18%, rgba(var(--accent-rgb),.10) 82%, transparent);
}

.msg-ava {
    width: 28px;
    height: 28px;
    margin-top: 0;
    font-size: 11px;
}

.server-msg-ava {
    width: 34px;
    height: 34px;
    margin-top: 2px;
    font-size: 12px;
}

.msg-ava-spacer {
    visibility: hidden;
}

.server-msg-ava-spacer {
    visibility: hidden;
}

.bwrap {
    display: inline-flex;
    flex-direction: column;
    align-items: flex-start;
    width: fit-content;
    max-width: min(620px, 74%);
}

.msg.out .bwrap {
    align-items: flex-end;
}

.msg-time-anchor {
    position: relative;
}

.msg-time {
    position: absolute;
    left: calc(100% + 12px);
    right: auto;
    top: 50%;
    bottom: auto;
    z-index: 2;
    display: inline-flex;
    align-items: center;
    flex: none;
    width: max-content;
    min-height: 14px;
    padding: 0;
    color: var(--text3);
    font-size: 10px;
    font-weight: 700;
    line-height: 1;
    white-space: nowrap;
    word-break: normal;
    overflow-wrap: normal;
    writing-mode: horizontal-tb;
    text-orientation: mixed;
    font-variant-numeric: tabular-nums;
    opacity: 0;
    transform: translateY(-50%);
    transition: opacity .16s var(--ease-out), color .16s var(--ease-out);
    pointer-events: none;
}

.msg.time-visible .msg-time {
    opacity: .56;
}

.msg:hover .msg-time,
.msg:focus-within .msg-time {
    opacity: .68;
}

.msg.out .msg-time {
    left: auto;
    right: calc(100% + 12px);
    color: var(--text3);
}

.call-card {
    display: grid;
    gap: 10px;
    padding: 10px 12px;
    border: 1px solid var(--border);
    border-radius: 16px;
    background: rgba(255,255,255,.03);
    box-shadow: inset 0 1px 0 rgba(255,255,255,.04);
