    align-items: center;
    gap: 10px;
}

.call-card-icon {
    display: grid;
    place-items: center;
    width: 30px;
    height: 30px;
    border-radius: 10px;
    background: rgba(255,255,255,.06);
    font-size: 15px;
    flex: 0 0 auto;
}

