}

.call-card-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 6px 12px;
    color: var(--text3);
    font-size: 10px;
}

.server-msg-main {
    display: inline-flex;
    flex-direction: column;
    align-items: flex-start;
    width: fit-content;
    max-width: min(820px, 88%);
}

.server-msg-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin: 0 0 6px;
    min-width: 0;
}

.server-msg-name {
    color: var(--text);
    font-weight: 900;
    line-height: 1.2;
}

.server-msg-time {
    color: var(--text3);
    font-size: 11px;
    font-weight: 700;
    white-space: nowrap;
}

.server-msg .bubble {
    max-width: 100%;
}

.server-msg .reaction-row {
    margin-top: 6px;
}

.bubble {
    position: relative;
    isolation: isolate;
    overflow-wrap: anywhere;
    padding: 10px 13px;
    border: 1px solid var(--border);
    border-radius: var(--r-msg);
    background: linear-gradient(180deg, rgba(255,255,255,.08), rgba(255,255,255,.04));
    color: var(--text);
    line-height: 1.45;
    box-shadow: 0 10px 24px rgba(0,0,0,.12);
}

.out .bubble {
    border: 1px solid transparent;
    background:
        linear-gradient(180deg, rgba(var(--accent-rgb),.98), rgba(var(--accent-rgb),.90)) padding-box,
        linear-gradient(180deg, rgba(255,255,255,.28), rgba(95,110,0,.18)) border-box;
    color: #111100;
    box-shadow:
        0 10px 24px rgba(0,0,0,.12),
        inset 0 1px 0 rgba(255,255,255,.24),
        inset 0 -1px 0 rgba(85, 104, 0, .10);
}

.bubble.media-card {
    padding: 10px;
    border-color: rgba(255,255,255,.06);
    background: #2b2d31;
    color: #dbdee1;
}

.out .bubble.media-card {
    border-color: rgba(255,255,255,.06);
    background: #2b2d31;
    color: #dbdee1;
}

.media-only {
    display: inline-flex;
    flex-direction: column;
    align-items: flex-start;
    padding: 0;
    border: 0;
    background: transparent;
    max-width: min(360px, 72vw);
}

.msg.gif-only .bwrap {
    max-width: min(380px, 74%);
}

.msg.gif-only .msg-attachments {
    display: block;
    margin-top: 0;
    max-width: 100%;
}

.msg.gif-only .discord-media-shell {
    display: inline-grid;
    width: auto;
    max-width: 100%;
}

/* Photo/gif/sticker with a caption: bare media on top (square-bottomed, so it
   visually continues into what's below) and a normal text bubble underneath,
   separated by a small gap. `align-items: stretch` + the wrap's own
   `width: fit-content` is what makes the bubble's width track the media's
   rendered width — the wrap shrinks to its widest child (the media), and the
   stretched bubble then fills that same width. */
.bwrap.image-caption-wrap {
    align-items: stretch;
    max-width: min(420px, 74%);
}

.image-caption-media {
    display: block;
}

.image-caption-media .discord-media-shell {
    display: block;
    width: 100%;
    border-bottom-left-radius: 0;
    border-bottom-right-radius: 0;
}

.image-caption-text {
    margin-top: 4px;
    width: 100%;
    border-top-left-radius: 0;
    border-top-right-radius: 0;
}

.reaction-row {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    margin-top: 6px;
    align-self: flex-start;
}

.msg.out .reaction-row {
    align-self: flex-end;
    justify-content: flex-end;
}

.reaction-chip {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    min-height: 22px;
    padding: 2px 8px 2px 7px;
    border: 1px solid var(--border);
    border-radius: 999px;
    background: rgba(255,255,255,.06);
    color: var(--text);
    cursor: pointer;
    box-shadow: inset 0 1px 0 rgba(255,255,255,.04);
}

.reaction-chip:hover,
.reaction-chip:focus-visible {
    border-color: var(--lime);
    box-shadow: 0 0 0 2px var(--lime-dim);
    outline: 0;
}

.reaction-chip.mine {
    border-color: rgba(var(--accent-rgb),.45);
    background: rgba(var(--accent-rgb),.14);
}

.reaction-emoji {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 15px;
    height: 15px;
    font-family: "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", sans-serif;
    font-size: 13px;
    line-height: 1;
    text-align: center;
}

.reaction-count {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 7px;
    color: rgba(255,255,255,.94);
    font-size: 11px;
    font-weight: 900;
    line-height: 1;
    text-align: center;
}

.reaction-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    padding: 0;
    overflow: hidden;
    border: 1px solid var(--border);
    border-radius: 999px;
    background: rgba(255,255,255,.06);
    color: var(--text);
    cursor: pointer;
    line-height: 1;
    box-shadow: inset 0 1px 0 rgba(255,255,255,.04);
}

.reaction-btn-emoji {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    font-family: "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", sans-serif;
    font-size: 18px;
    line-height: 1;
    text-align: center;
}

.reaction-btn:hover,
.reaction-btn:focus-visible {
    border-color: var(--lime);
    box-shadow: 0 0 0 2px var(--lime-dim);
    outline: 0;
}

.reaction-btn.active {
    border-color: rgba(var(--accent-rgb),.55);
    background: rgba(var(--accent-rgb),.16);
}

/* Пикер реакций и действий над сообщением. Внутри пикера у кнопок нет ни
   рамки, ни заливки: девять обведённых кружков подряд — это девять рамок
   в объекте высотой 42 px, и глаз читает сетку, а не эмодзи. Обводка тут
   лишняя ещё и потому, что у всей полосы уже есть своя. */
.reaction-menu {
    position: fixed;
    z-index: 140;
    display: none;
    align-items: center;
    gap: 1px;
    padding: 5px;
    border: 1px solid var(--menu-border);
    border-radius: 999px;
    background: var(--menu-bg);
    box-shadow: var(--menu-shadow);
    backdrop-filter: var(--menu-blur);
    -webkit-backdrop-filter: var(--menu-blur);
    transform: translateY(3px) scale(.96);
    transform-origin: center bottom;
    opacity: 0;
    pointer-events: none;
}

.reaction-menu.visible {
    display: flex;
    opacity: 1;
    pointer-events: auto;
    transform: translateY(0) scale(1);
    transition: opacity .14s var(--ease-out), transform .14s var(--ease-out);
}

.reaction-menu .reaction-btn {
    flex: none;
    width: 34px;
    height: 34px;
    border: 1px solid transparent;
    border-radius: 50%;
    background: transparent;
    box-shadow: none;
    transition: background .12s var(--ease-out), transform .12s var(--ease-out), color .12s var(--ease-out);
}

/* Эмодзи подрастает под курсором — это и есть подтверждение попадания,
   поэтому подсветка под ним может остаться едва заметной. */
.reaction-menu .reaction-btn:hover,
.reaction-menu .reaction-btn:focus-visible {
    border-color: transparent;
    background: var(--menu-hover);
    box-shadow: none;
    outline: 0;
    transform: scale(1.14);
}

.reaction-menu .reaction-btn:active {
    transform: scale(1.02);
}

.reaction-menu .reaction-btn .ui-icon {
    width: 18px;
    height: 18px;
}

/* Ответ / правка — линейные иконки того же набора, что и везде в
   интерфейсе. Раньше это были типографские глифы ↩ ✎ 🗑, которые каждая
   ОС рисует своим шрифтом: рядом с цветными эмодзи они выглядели то
   бледной палочкой, то вторым эмодзи. */
.reaction-btn-action {
    color: var(--text2);
}

.reaction-menu .reaction-btn-action:hover,
.reaction-menu .reaction-btn-action:focus-visible {
    color: var(--text);
}

/* Trash icon appended to the same popup, shown only when canDeleteMessage()
   allows it (own message, or manage rights on the channel it's in) — kept in
   the reaction picker rather than a separate menu so there's one place to
   long-press/right-click a message for any per-message action. */
.reaction-btn-delete {
    color: rgba(255, 92, 118, .82);
}

/* Единственный цветной пункт в меню — и цвет тут несёт смысл (действие
   необратимое), а не украшает. */
.reaction-menu .reaction-btn-delete:hover,
.reaction-menu .reaction-btn-delete:focus-visible {
    border-color: transparent;
    background: rgba(255, 92, 118, .16);
    box-shadow: none;
    color: rgb(255, 108, 132);
}

/* Reply / edit actions live in the same popup as the reactions — one
   long-press/right-click surface for every per-message action, rather than a
   second menu the user has to discover separately. */
.reaction-menu-sep {
    flex: none;
    align-self: center;
    width: 1px;
    height: 20px;
    margin: 0 5px;
    background: var(--menu-border);
}

/* Quote of the message being replied to, rendered at the top of the bubble.
   The accent bar on the leading edge is what separates it from the body at a
   glance; it is inside the bubble, so it inherits the bubble's own colour. */
.msg-quote {
    display: flex;
    flex-direction: column;
    gap: 1px;
    max-width: 100%;
    margin: 0 0 6px;
    padding: 4px 8px;
    border-left: 3px solid currentColor;
    border-radius: 6px;
    background: rgba(255,255,255,.07);
    cursor: pointer;
    opacity: .82;
    transition: opacity .12s var(--ease-out), background .12s var(--ease-out);
}

/* The outgoing bubble is lime, so a translucent-WHITE tint on it is invisible —
   darken instead, matching the dark text the bubble already uses. */
.msg.out .msg-quote {
    background: rgba(0,0,0,.10);
}

.msg.out .msg-quote:hover,
.msg.out .msg-quote:focus-visible {
    background: rgba(0,0,0,.16);
}

.msg-quote:hover,
.msg-quote:focus-visible {
    outline: none;
    opacity: 1;
    background: rgba(255,255,255,.12);
}

.msg-quote-author {
    font-size: 11.5px;
    font-weight: 700;
    letter-spacing: .01em;
}

/* One line, clipped: a quote must never out-grow the message quoting it. */
.msg-quote-text {
    overflow: hidden;
    font-size: 12.5px;
    line-height: 1.35;
    text-overflow: ellipsis;
    white-space: nowrap;
    opacity: .82;
}

/* Flash used when jumping to a quoted original, so the eye lands on it. */
@keyframes msg-flash-pulse {
    0%   { background: rgba(var(--accent-rgb), .26); }
    100% { background: transparent; }
}

.msg.msg-flash .bubble {
    animation: msg-flash-pulse 1.6s var(--ease-out);
}

/* Composer context bar: shown while replying or editing. */
.composer-context {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 12px;
    border: 1px solid var(--border);
    border-left: 3px solid var(--lime);
    border-radius: 12px;
    background: rgba(255,255,255,.04);
}

.composer-context[hidden] {
    display: none;
}

.composer-context-body {
    display: flex;
    /* min-width:0 is what actually lets the ellipsis below work — without it a
       flex item refuses to shrink past its content and the bar grows instead. */
    min-width: 0;
    flex: 1;
    flex-direction: column;
    gap: 1px;
}

.composer-context-title {
    color: var(--lime);
    font-size: 11.5px;
    font-weight: 700;
}

.composer-context-text {
    overflow: hidden;
    color: var(--text2);
    font-size: 12.5px;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.composer-context-close {
    flex: none;
    width: 26px;
    height: 26px;
    padding: 0;
    border: 0;
    border-radius: 999px;
    background: transparent;
    color: var(--text2);
    cursor: pointer;
    font-size: 13px;
    line-height: 1;
}

.composer-context-close:hover,
.composer-context-close:focus-visible {
    outline: none;
    background: rgba(255,255,255,.08);
    color: var(--text);
}

.msg-text {
    white-space: pre-wrap;
}

.msg-text a,
.msg-attachments a,
.msg-link-previews a {
    color: inherit;
    text-decoration: underline;
    text-underline-offset: 2px;
}

.msg-attachments {
    display: grid;
    gap: 10px;
    margin-top: 8px;
}

.msg-attachments:first-child {
    margin-top: 0;
}

.media,
.media-tenor iframe {
    display: block;
    width: 100%;
    border: 0;
    border-radius: calc(var(--r-msg) - 6px);
    background: rgba(0,0,0,.18);
}

.media-img,
.media-video {
    max-width: 100%;
}

.media-video {
    width: 100%;
    max-height: 360px;
}

/* Animated .tgs stickers — rendered into .media-sticker-stage by
   web/src/modules/tgs.js. Square, transparent and deliberately NOT stretched to
   the bubble width: a sticker is an emoji-sized object, not an attachment card. */
.media.media-sticker {
    width: 180px;
    height: 180px;
    max-width: 100%;
    background: transparent;
    border-radius: 0;
}

.media.media-sticker.compact {
    width: 100%;
    height: 84px;
    min-height: 84px;
}

.media-sticker-stage {
    width: 100%;
    height: 100%;
}

/* lottie-web writes inline width/height onto the <svg> it creates, so the only
   way to keep it inside the stage is to out-specify it. */
.media-sticker-stage svg {
    display: block;
    width: 100% !important;
    height: 100% !important;
}

/* Reserve the square while the animation is being fetched and inflated, so the
   message list does not jump once it appears. */
.media-sticker:not([data-tgs-state="ready"]) .media-sticker-stage {
    border-radius: 12px;
    background: rgba(255,255,255,.04);
}

/* Decode failed: collapse to the plain download chip that was hidden underneath. */
.media.media-sticker-failed {
    width: auto;
    height: auto;
    min-height: 0;
}

.media-sticker-failed .media-sticker-stage {
    display: none;
}

.media-tenor {
    overflow: hidden;
    min-height: 220px;
}

.media-tenor iframe {
    width: 100%;
    height: 100%;
}

.media-tenor-pending {
    display: grid;
    place-items: center;
    gap: 8px;
    padding: 18px;
    background: linear-gradient(145deg, rgba(255,255,255,.08), rgba(255,255,255,.03));
}

.tenor-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 120px;
    padding: 10px 14px;
    border: 1px solid rgba(0,0,0,.14);
    border-radius: 10px;
    background: rgba(0,0,0,.28);
    color: #fff;
    font-size: 13px;
    font-weight: 800;
    box-shadow: 0 6px 18px rgba(0,0,0,.14);
}

.tenor-hint {
    color: var(--text2);
    font-size: 12px;
}

.discord-media-shell {
    overflow: hidden;
    border-radius: calc(var(--r-msg) - 6px);
    background: #000;
    border: 1px solid rgba(255,255,255,.14);
    box-shadow: 0 1px 0 rgba(0,0,0,.35), inset 0 0 0 1px rgba(255,255,255,.02);
}

.discord-media-shell video,
.discord-media-shell img {
    display: block;
    width: 100%;
    max-width: 100%;
    height: auto;
}

.discord-media-shell-video {
    min-height: 0;
}

.discord-media-shell-video video {
    width: 100%;
    height: 100%;
    max-height: 360px;
    object-fit: contain;
}

.discord-media-shell-gif {
    display: inline-grid;
    width: auto;
    max-width: min(360px, 72vw);
    background: transparent;
    min-height: 0;
    height: auto;
}

.discord-media-shell-gif video {
    width: auto !important;
    max-width: min(360px, 72vw);
    height: auto !important;
    max-height: 340px;
    object-fit: contain;
    background: transparent !important;
}

.discord-media-shell-image.discord-media-shell-gif img,
.discord-media-shell-image .media-gif-like {
    width: auto;
    max-width: min(360px, 72vw);
    height: auto;
    max-height: 340px;
    object-fit: contain;
    background: transparent;
}

.discord-media-shell-image img {
    object-fit: cover;
}

.discord-media-shell-video video {
    background: #000;
}

.discord-media-shell-gif {
    background: transparent;
}

.media-unknown {
    padding: 10px 12px;
    border: 1px dashed var(--border);
    border-radius: calc(var(--r-msg) - 6px);
    color: var(--text2);
}

/* Format-specific icon shown when there's no richer preview for an attachment
   (a .pdf, .docx, .zip, ...): a sheet-of-paper shape (taller than wide, like
   an actual page, not a generic square) with a folded top-right corner, so it
   reads as "a document" even when the extension text is empty (no dot in the
   filename). One flat neutral fill for every type — no per-category color —
   and the fill is opaque, so the icon's own (fixed, not inherited) dark text
   stays legible whether it lands in a dark incoming bubble or a light
   outgoing one; inheriting the bubble's text color doesn't work once the fill
   itself stops being translucent. */
.file-icon {
    position: relative;
    display: flex;
    flex: none;
    align-items: flex-end;
    justify-content: center;
    width: 32px;
    height: 40px;
    padding-bottom: 5px;
    border-radius: 5px;
    background: rgba(235,236,240,.92);
    color: rgba(30,32,38,.72);
    font-size: 8px;
    font-weight: 900;
    letter-spacing: .3px;
    line-height: 1;
    overflow: hidden;
}

.file-icon::after {
    content: "";
    position: absolute;
    top: 0;
    right: 0;
    width: 0;
    height: 0;
    border-style: solid;
    border-width: 0 13px 13px 0;
    border-color: transparent rgba(30,32,38,.16) transparent transparent;
}

.file-chip.compact .file-icon,
.draft-att .file-icon {
    width: 28px;
    height: 35px;
}

.file-chip {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 10px 12px;
    border: 1px solid transparent;
    border-radius: var(--r-msg);
    background:
        linear-gradient(180deg, rgba(255,255,255,.08), rgba(255,255,255,.04)) padding-box,
        linear-gradient(180deg, rgba(255,255,255,.16), rgba(255,255,255,.05)) border-box;
    color: var(--text);
    text-decoration: none;
    box-shadow:
        0 10px 24px rgba(0,0,0,.10),
        inset 0 1px 0 rgba(255,255,255,.06);
}

.file-chip:hover,
.file-chip:focus-visible {
    box-shadow:
        0 10px 24px rgba(0,0,0,.10),
        inset 0 1px 0 rgba(255,255,255,.08),
        0 0 0 2px rgba(var(--accent-rgb),.10);
    outline: 0;
}

.file-message-info {
    display: flex;
    flex-direction: column;
    gap: 3px;
    min-width: 0;
}

.file-chip-name,
.file-message-name {
    font-weight: 700;
    line-height: 1.25;
    overflow-wrap: anywhere;
}

.file-chip-size,
.file-message-size {
    color: var(--text2);
    font-size: 11px;
    line-height: 1.2;
}

.file-chip.compact {
    padding: 9px 11px;
}

/* No box of its own — this sits inside a normal chat `.bubble`, which already
   supplies the padding/background/border. Wrapping it in a second bordered
   card on top of that read as a bubble nested inside a bubble. */
.media-audio {
    display: flex;
    flex-direction: column;
    gap: 6px;
    min-width: 200px;
    max-width: 100%;
}

.media-audio-player {
    width: 100%;
    height: 32px;
}

.media-audio-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
    min-width: 0;
}

.media-audio-name {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: 12px;
    font-weight: 700;
    min-width: 0;
}

.media-audio-size {
    flex: none;
    color: var(--text2);
    font-size: 11px;
}

/* No box of its own, same reasoning as .media-audio above — this always sits
   inside a normal chat `.bubble`, so its own border/background just doubled
   the bubble it was already inside. */
.file-message {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    max-width: 100%;
    color: inherit;
}

/* Beats `.msg-attachments a { text-decoration: underline }` (interface.js always
   wraps this in a .msg-attachments block) on specificity — a plain `.file-message`
   rule alone loses to that two-class-plus-tag selector. */
.msg-attachments .file-message,
.msg-attachments .file-message:hover,
.msg-attachments .file-message:focus-visible {
    text-decoration: none;
}

.file-message:hover .file-message-name,
.file-message:focus-visible .file-message-name {
    text-decoration: underline;
}

.file-message:focus-visible {
    outline: 1px solid rgba(var(--accent-rgb),.5);
    outline-offset: 2px;
}


.btime {
    margin-top: 2px;
    color: var(--text3);
    font-size: 10px;
}

.out .btime {
    text-align: right;
}

.date-sep {
    display: flex;
    justify-content: center;
    margin: 18px 0;
}

.date-sep span {
    padding: 5px 10px;
    border-radius: 999px;
    background: rgba(255,255,255,.06);
    color: var(--text2);
    font-size: 11px;
    font-weight: 800;
    /* No entry animation: the message list is rebuilt wholesale on every new
       message, so an animation here replayed on every separator each time a
       message arrived — a list-wide flicker rather than a one-off flourish. */
}

/* System notices (ZaliCoin transfer receipts, decryption/download placeholders):
   centered pills, deliberately unlike either chat bubble side so they read as
   "the app said this", not "a person typed this". */
.msg.notice {
    display: flex;
    justify-content: center;
    margin: 10px 0;
}

.notice-pill {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    max-width: min(560px, 84%);
    padding: 7px 14px;
    border-radius: 999px;
    border: 1px dashed rgba(255,255,255,.14);
    background: rgba(255,255,255,.04);
    color: var(--text2);
    font-size: 12px;
    font-weight: 700;
    line-height: 1.35;
    text-align: center;
    overflow-wrap: anywhere;
}

.notice-icon {
    flex: none;
    font-size: 13px;
    line-height: 1;
}

.notice-text {
    min-width: 0;
}

.msg.notice-transfer .notice-pill {
    border-color: rgba(var(--accent-rgb),.35);
    background: rgba(var(--accent-rgb),.10);
    color: var(--text);
}

.msg.notice-decrypt-error .notice-pill {
    border-color: rgba(255,107,107,.35);
    background: rgba(255,107,107,.08);
    color: var(--text2);
}

.input-area {
    display: flex;
    flex-direction: column;
    gap: 14px;
    padding: 14px 18px 16px;
    border-top: 1px solid rgba(255,255,255,.08);
    background: transparent;
}

.draft-attachments {
    display: none;
    flex-wrap: wrap;
    gap: 10px;
}

.draft-attachments.has-items {
    display: flex;
}

.draft-att {
    position: relative;
    width: 128px;
    padding: 8px;
    border: 1px solid var(--border);
    border-radius: 14px;
    background: rgba(255,255,255,.03);
    animation: card-rise .22s cubic-bezier(.2,.8,.2,1) both;
    content-visibility: auto;
    contain-intrinsic-size: 140px;
}

.draft-att-remove {
    position: absolute;
    top: 6px;
    right: 6px;
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: rgba(0,0,0,.6);
    color: #fff;
    cursor: pointer;
    transition: transform .18s var(--ease-out), background .18s var(--ease-out), color .18s var(--ease-out);
}

.draft-att-remove:hover {
    background: rgba(0,0,0,.8);
    color: var(--lime);
}

.draft-att .media,
.draft-att .file-chip {
    width: 100%;
    max-height: 84px;
    min-height: 84px;
    object-fit: cover;
}

.draft-att .discord-media-shell {
    width: 100%;
    height: 84px;
}

.draft-att .discord-media-shell video,
.draft-att .discord-media-shell img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* The outer .draft-att square already is the card (border + background) —
   the .file-chip inside it doesn't need its own on top of that, that was a
   card nested inside a card. Keep only the icon + size, centered; the
   filename lives in .draft-att-name below instead. */
.draft-att .file-chip {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 10px;
    gap: 6px;
    border: 0;
    background: none;
    box-shadow: none;
}

.draft-att .file-chip:hover,
.draft-att .file-chip:focus-visible {
    box-shadow: none;
    outline: 0;
}

.draft-att-name {
    margin-top: 8px;
    overflow: hidden;
    color: var(--text2);
    font-size: 11px;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.input-bar {
    display: grid;
    grid-template-columns: 40px 40px 1fr 40px;
    align-items: center;
    gap: 10px;
    width: calc(100% - (var(--composer-inline-inset) * 2));
    margin: 0 var(--composer-inline-inset);
    height: 54px;
    padding: 8px 8px;
    border: 1px solid rgba(255,255,255,.055);
    border-radius: 12px;
    background:
        linear-gradient(180deg, rgba(255,255,255,.035), rgba(255,255,255,.012)),
        rgba(8,10,13,.9);
    box-shadow:
        inset 0 1px 0 rgba(255,255,255,.035);
}

#msgInput {
    min-width: 0;
    height: 36px;
    max-height: 140px;
    resize: none;
    border: 0;
    outline: 0;
    background: transparent;
    color: var(--text);
    line-height: 1.35;
    padding: 7px 0 5px;
}

.attach-btn,
.send-btn {
    width: 40px;
    height: 36px;
    border-radius: 11px;
    display: grid;
    place-items: center;
    cursor: pointer;
    transition: transform .18s var(--ease-out), box-shadow .18s var(--ease-out), border-color .18s var(--ease-out), background .18s var(--ease-out), color .18s var(--ease-out);
}

.attach-btn {
    background: rgba(255,255,255,.04);
    color: var(--text);
    border: 1px solid var(--border);
    box-shadow: inset 0 1px 0 rgba(255,255,255,.04);
}

.attach-btn:hover,
.input-bar.drop-active {
    border-color: var(--lime);
    box-shadow: 0 0 0 2px var(--lime-dim);
}

.send-btn {
    background: var(--lime);
    color: #050505;
    box-shadow: 0 0 18px rgba(var(--accent-rgb),.28);
    transform-origin: bottom right;
}

.send-btn:hover {
    box-shadow: 0 0 0 2px rgba(var(--accent-rgb),.12);
}

.send-btn:disabled {
    cursor: default;
    opacity: .35;
}

.log-body,
.settings-body {
    min-height: 0;
    overflow-y: auto;
}

.log-body {
    padding: 14px 18px;
    font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
    font-size: 12px;
}

.log-entry {
    padding: 7px 0;
    border-bottom: 1px solid rgba(255,255,255,.04);
    color: var(--text2);
}

.log-SUCCESS {
    color: var(--lime);
}

.log-ERROR {
    color: var(--red);
}

.log-WARN {
    color: #ffcc66;
}

.ts {
    margin-right: 8px;
    color: var(--text3);
}

@media (max-width: 1100px) {
    .settings-hero,
    .settings-grid {
        grid-template-columns: 1fr;
    }

    .server-modal-shell {
        grid-template-columns: 1fr;
    }

    .settings-chips {
        justify-content: flex-start;
    }

    .settings-control-row {
        grid-template-columns: 72px minmax(0, 1fr) 56px;
    }

    .server-perm-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 760px) {
    #viewSettings {
        grid-template-rows: auto 1fr;
    }

    #viewHub {
        padding: 12px;
    }

    .hub-hero {
        grid-template-columns: 1fr;
        padding: 18px;
        border-radius: 20px;
    }

    .hub-orb {
        width: 110px;
        border-radius: 32%;
    }

    .hub-grid {
        grid-template-columns: 1fr;
    }

    .hub-components {
        padding: 14px;
        border-radius: 18px;
    }

    .hub-components-head,
    .hub-component-item {
        grid-template-columns: 1fr;
    }

    .hub-components-head {
        display: grid;
    }

    .hub-component-meta {
        justify-items: start;
        text-align: left;
    }

    .settings-topbar {
        flex-direction: column;
        align-items: stretch;
    }

    .settings-body {
        padding: 16px;
    }

    .settings-card {
        padding: 16px;
        border-radius: 16px;
    }

    .server-modal {
        padding: 14px;
    }

    .server-modal-head {
        flex-direction: column;
    }

    .server-modal-shell {
        gap: 12px;
    }

    .server-modal-sidebar {
        padding: 14px;
    }

    .server-modal-grid {
        max-height: none;
        overflow: visible;
        padding-right: 0;
    }

    .server-member-add {
        grid-template-columns: 1fr;
    }

    .server-role-create {
        grid-template-columns: 1fr;
    }

    .server-link-row {
        grid-template-columns: 1fr;
    }

    .server-member-row {
        grid-template-columns: 1fr;
    }

    .server-asset-card,
    .server-banner-card {
        grid-template-columns: 1fr;
    }

    .server-avatar-preview,
    .server-banner-preview {
        width: 100%;
    }

    .settings-theme-grid {
        grid-template-columns: 1fr;
    }

    .avatar-editor {
        grid-template-columns: 1fr;
        justify-items: start;
    }

    .chat-hdr.server-mode {
        flex-wrap: wrap;
    }

    .chat-hdr.server-mode .server-channel-list {
        margin-left: 0;
        max-width: 100%;
        width: 100%;
    }

    .settings-control-row {
        grid-template-columns: 1fr;
        gap: 8px;
    }

    .settings-value {
        text-align: left;
    }
}

.empty-state,
.contacts-loading {
    display: grid;
    place-items: center;
    min-height: 100%;
    color: var(--text3);
    text-align: center;
    gap: 4px;
    animation: fade-up .28s cubic-bezier(.2,.8,.2,1) both;
}

.empty-ttl {
    color: var(--text);
    font-weight: 900;
}

.empty-sub {
    color: var(--text2);
    font-size: 12px;
}

.sk {
    position: relative;
    overflow: hidden;
    border-radius: 8px;
    background: rgba(255,255,255,.06);
}

.sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(90deg, transparent, rgba(255,255,255,.09), transparent);
    animation: shimmer 1.8s linear 1;
    animation-fill-mode: both;
}

.sk-contact {
    width: calc(100% - 20px);
    height: 50px;
    margin: 8px 10px;
}

.sk-bubble {
    height: 38px;
    margin: 10px 0;
}

.sk-w1 { width: 34%; }
.sk-w2 { width: 52%; }
.sk-w3 { width: 66%; }
.sk-self { margin-left: auto; }

.auth-overlay {
    position: fixed;
    inset: 0;
    z-index: 50;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
    background: rgba(4, 6, 10, .76);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transition:
        opacity .24s var(--ease-out),
        visibility 0s linear .24s;
}

.auth-overlay.visible {
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
    transition:
        opacity .24s var(--ease-out),
        visibility 0s linear 0s;
}

.auth-card {
    width: min(460px, 100%);
    padding: 28px;
    border: 1px solid rgba(255,255,255,.08);
    border-radius: 24px;
    background:
        radial-gradient(circle at top left, rgba(var(--accent-rgb),.1), transparent 28%),
        linear-gradient(180deg, rgba(26,28,32,.96), rgba(12,14,18,.97));
    box-shadow: 0 30px 90px rgba(0,0,0,.52), 0 0 0 1px rgba(var(--accent-rgb),.06);
    transform: translateY(18px) scale(.98);
    opacity: 0;
    transition:
        transform .36s cubic-bezier(.2,.8,.2,1),
        opacity .24s var(--ease-out),
        box-shadow .24s var(--ease-out);
    position: relative;
    overflow: hidden;
}

.auth-card::before {
    content: "";
    position: absolute;
    inset: 0;
    background:
        radial-gradient(circle at top right, rgba(var(--accent-rgb),.14), transparent 32%),
        radial-gradient(circle at bottom left, rgba(255,255,255,.05), transparent 26%);
    pointer-events: none;
    opacity: .8;
}

.auth-overlay.visible .auth-card {
    transform: translateY(0) scale(1);
    opacity: 1;
    animation: auth-pop .42s cubic-bezier(.2,.9,.18,1) both;
}

.auth-brand {
    color: var(--lime);
    font-size: 12px;
    font-weight: 900;
    letter-spacing: .18em;
    text-transform: uppercase;
}

.auth-card h1 {
    margin: 10px 0 8px;
    font-size: 28px;
    line-height: 1.1;
    position: relative;
    z-index: 1;
}

.auth-card p {
    margin: 0 0 20px;
    color: var(--text2);
    line-height: 1.5;
    position: relative;
    z-index: 1;
}

.auth-vault-sync {
    margin-top: -10px;
    margin-bottom: 16px;
    color: var(--lime);
    font-size: 12px;
    font-weight: 700;
    line-height: 1.4;
}

.auth-form {
    display: flex;
    flex-direction: column;
    gap: 12px;
    position: relative;
    z-index: 1;
}

.auth-input {
    width: 100%;
    height: 44px;
    padding: 0 14px;
    border: 1px solid var(--border);
    border-radius: 12px;
    outline: none;
    background: rgba(255,255,255,.03);
    color: var(--text);
    box-shadow: inset 0 1px 0 rgba(255,255,255,.04);
    transition:
        border-color .2s var(--ease-out),
        box-shadow .2s var(--ease-out),
        transform .2s var(--ease-out),
        background .2s var(--ease-out);
}

.auth-input:focus {
    border-color: var(--lime);
    box-shadow: 0 0 0 3px var(--lime-dim);
    background: rgba(255,255,255,.06);
}

.auth-input--compact {
    flex: 1 1 auto;
    min-width: 0;
}

.auth-actions {
    display: grid;
    grid-template-columns: 1fr;
    gap: 10px;
}

.auth-network {
    display: grid;
    gap: 10px;
    padding: 14px;
    border: 1px solid rgba(255,255,255,.06);
    border-radius: 16px;
    background: rgba(255,255,255,.02);
    box-shadow: inset 0 1px 0 rgba(255,255,255,.03);
}

.auth-network-head {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 12px;
    flex-wrap: wrap;
}

.auth-network-title {
    color: var(--text);
    font-size: 12px;
    font-weight: 900;
    letter-spacing: .08em;
    text-transform: uppercase;
}

.auth-network-note {
    color: var(--text2);
    font-size: 11px;
    font-weight: 700;
}

.auth-network-row {
    display: flex;
    gap: 10px;
    align-items: center;
}

.auth-network-help {
    margin: 0;
    color: var(--text2);
    font-size: 12px;
    line-height: 1.45;
}

.auth-btn {
    min-height: 40px;
    border-radius: 12px;
    border: 1px solid transparent;
    cursor: pointer;
    font-weight: 800;
    transition:
        transform .2s var(--ease-out),
        box-shadow .2s var(--ease-out),
        background .2s var(--ease-out),
        border-color .2s var(--ease-out),
        opacity .2s var(--ease-out);
    position: relative;
    z-index: 1;
}

.auth-btn:hover {
    box-shadow: 0 0 0 2px rgba(0,0,0,.16);
}

.auth-btn:active {
    transform: translateY(1px) scale(.99);
}

.auth-btn.primary {
    background: var(--lime);
    color: #050505;
    box-shadow: 0 14px 28px rgba(var(--accent-rgb),.2);
}

.auth-btn--ghost {
    min-width: 108px;
    border: 1px solid rgba(var(--accent-rgb), .16);
    background: rgba(255,255,255,.04);
    color: var(--text);
}

.auth-btn.secondary {
    border: 1px solid var(--border);
    background: rgba(255,255,255,.04);
    color: var(--text);
}

.auth-footer {
    display: flex;
    justify-content: space-between;
    gap: 10px;
    flex-wrap: wrap;
}

.auth-link {
    min-height: 28px;
    padding: 0;
    background: none;
    color: var(--lime);
    cursor: pointer;
    font-weight: 700;
    transition: transform .2s var(--ease-out), opacity .2s var(--ease-out);
}

.auth-link:hover {
    opacity: .92;
}

.auth-error {
    min-height: 18px;
    color: var(--red);
    font-size: 12px;
    position: relative;
    z-index: 1;
}

.auth-overlay.visible .auth-form > * {
    animation: auth-field-in .42s cubic-bezier(.2,.8,.2,1) both;
}

.auth-overlay.visible .auth-form > *:nth-child(1) { animation-delay: .05s; }
.auth-overlay.visible .auth-form > *:nth-child(2) { animation-delay: .09s; }
.auth-overlay.visible .auth-form > *:nth-child(3) { animation-delay: .13s; }
.auth-overlay.visible .auth-form > *:nth-child(4) { animation-delay: .17s; }
.auth-overlay.visible .auth-form > *:nth-child(5) { animation-delay: .21s; }
.auth-overlay.visible .auth-form > *:nth-child(6) { animation-delay: .25s; }
.auth-overlay.visible .auth-form > *:nth-child(7) { animation-delay: .29s; }

.settings-shell > .settings-card:nth-child(1),
.settings-theme-grid .btn-theme:nth-child(1),
.draft-attachments .draft-att:nth-child(1) { animation-delay: .02s; }

.settings-shell > .settings-card:nth-child(2),
.settings-theme-grid .btn-theme:nth-child(2),
.draft-attachments .draft-att:nth-child(2) { animation-delay: .05s; }

.settings-shell > .settings-card:nth-child(3),
.settings-theme-grid .btn-theme:nth-child(3),
.draft-attachments .draft-att:nth-child(3) { animation-delay: .08s; }

.settings-shell > .settings-card:nth-child(4),
.settings-theme-grid .btn-theme:nth-child(4),
.draft-attachments .draft-att:nth-child(4) { animation-delay: .11s; }

.settings-shell > .settings-card:nth-child(5),
.settings-theme-grid .btn-theme:nth-child(5),
.draft-attachments .draft-att:nth-child(5) { animation-delay: .14s; }

.settings-shell > .settings-card:nth-child(6),
.settings-theme-grid .btn-theme:nth-child(6),
.draft-attachments .draft-att:nth-child(6) { animation-delay: .17s; }

.settings-shell > .settings-card:nth-child(7),
.settings-theme-grid .btn-theme:nth-child(7),
.draft-attachments .draft-att:nth-child(7) { animation-delay: .20s; }

.settings-shell > .settings-card:nth-child(8),
.settings-theme-grid .btn-theme:nth-child(8),
.draft-attachments .draft-att:nth-child(8) { animation-delay: .23s; }

/* NB: .contact and .msg deliberately carry no entrance animation — both lists
   are rebuilt wholesale with innerHTML, so a per-item entrance would re-fire on
   every row each time anything changed. The staggered animation-delay rules
   above therefore list only the elements that actually animate; .msg/.contact
   were still in that selector list long after their animation was removed,
   which cost a :nth-child match against every bubble on every style recalc for
   nothing. */

@keyframes shimmer {
    to {
        transform: translateX(100%);
    }
}

@keyframes view-enter {
    from {
        opacity: 0;
        transform: translateY(6px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes row-fade {
    from {
        opacity: 0;
        transform: translateY(4px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes contact-in {
    from {
        opacity: 0;
        transform: translateX(-4px);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}

@keyframes contact-active {
    0% {
        transform: scale(.995);
    }
    100% {
        transform: scale(1);
    }
}

@keyframes avatar-pulse {
    0% {
        box-shadow:
            0 0 0 1px rgba(var(--accent-rgb), .10),
            0 0 0 0 rgba(var(--accent-rgb), .18);
    }
    100% {
        box-shadow:
            0 0 0 1px rgba(var(--accent-rgb), .18),
            0 0 0 4px rgba(var(--accent-rgb), .08);
    }
}

@keyframes badge-pop {
    0% {
        opacity: 0;
        transform: scale(.88);
    }
    100% {
        opacity: 1;
        transform: scale(1);
    }
}

@keyframes card-rise {
    from {
        opacity: 0;
        transform: translateY(8px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes chip-pop {
    from {
        opacity: 0;
        transform: translateY(4px) scale(.98);
    }
    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

@keyframes segment-icon-pop {
    0% {
        transform: translateY(0) scale(.92);
    }
    58% {
        transform: translateY(-1px) scale(1.14);
    }
    100% {
        transform: translateY(0) scale(1);
    }
}

@keyframes msg-in {
    from {
        opacity: 0;
        transform: translateY(8px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes bubble-pop {
    from {
        opacity: 0;
        transform: scale(.98);
    }
    to {
        opacity: 1;
        transform: scale(1);
    }
}

@keyframes fade-up {
    from {
        opacity: 0;
        transform: translateY(6px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes auth-pop {
    0% {
        transform: translateY(22px) scale(.96);
        filter: blur(2px);
    }
    70% {
        transform: translateY(-2px) scale(1.01);
        filter: blur(0);
    }
    100% {
        transform: translateY(0) scale(1);
        filter: blur(0);
    }
}

@keyframes auth-field-in {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes suggest-drop {
    from {
        opacity: 0;
        transform: translateY(-6px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@media (prefers-reduced-motion: reduce) {
    .auth-overlay,
    .auth-card,
    .auth-input,
    .auth-btn,
    .auth-link,
    .contacts-suggest,
    .contact-suggest-item,
    .peer-context-menu-item,
    .reaction-menu,
    .reaction-menu .reaction-btn,
    .view.active,
    .contact,
    .msg,
    .bubble,
    .settings-card,
    .settings-theme-grid .btn-theme,
    .hub-segment-indicator,
    .hub-segment-btn,
    .hub-segment-btn svg,
    .draft-att,
    .badge,
    .date-sep span,
    .empty-state,
    .contacts-loading {
        transition: none !important;
    }

    .auth-overlay.visible .auth-card,
    .auth-overlay.visible .auth-form > *,
    .contacts-suggest,
    .peer-context-menu,
    .view.active,
    .contact,
    .msg,
    .bubble,
    .settings-card,
    .settings-theme-grid .btn-theme,
    .hub-segment-btn.active svg,
    .draft-att,
    .badge,
    .date-sep span,
    .empty-state,
    .contacts-loading {
        animation: none !important;
    }
}

@media (max-width: 760px) {
    .titlebar {
        grid-template-columns: 1fr auto;
    }

    .tb-l {
        display: none;
    }

    .tb-c {
        text-align: left;
    }

    .body {
        grid-template-columns: 96px 1fr;
    }

    .voice-meter-grid,
    .voice-health-grid {
        grid-template-columns: 1fr;
    }

    /* Keep two participants side by side on a phone instead of one giant tile
       per row — the desktop 190px floor would force a single column here. */
    .voice-tiles {
        grid-template-columns: repeat(auto-fit, minmax(128px, 1fr));
    }

    .voice-tile-avatar {
        width: 52px;
        height: 52px;
        font-size: 18px;
    }

    .sidebar-head,
    .search-wrap,
    .nav-label,
    .contact-info,
    .me > div,
    .badge,
    .contact-remove {
        display: none;
    }

    .server-channel {
        min-height: 32px;
        padding: 0 10px;
    }

    .server-channel-name {
        font-size: 10px;
    }

    .contact {
        grid-template-columns: 38px;
        justify-content: center;
    }

    .bwrap {
        max-width: 86%;
    }

    .draft-att {
        width: calc(50% - 5px);
    }
}

@media (max-width: 760px) {
    .titlebar {
        grid-template-columns: 44px 1fr auto;
        gap: 8px;
        padding: 0 10px;
    }

    .tb-l {
        display: flex;
    }

    .mobile-menu-btn {
        display: inline-flex;
    }

    .tb-c {
        text-align: left;
        font-size: 11px;
    }

    .tb-brand {
        display: inline-block;
        max-width: 42vw;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    .tb-chat {
        display: inline-block;
        max-width: 50vw;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
        vertical-align: bottom;
    }

    .tb-r {
        justify-content: flex-end;
    }

    .body {
        grid-template-columns: 1fr;
        gap: 0;
        padding: 12px 12px calc(152px + var(--m-safe-bottom));
    }

    /* Mobile list<->chat push navigation. #viewChat sits ABOVE .sidebar
       (higher z-index) and slides on the X axis (progress 0 = list screen,
       1 = chat screen, written as a plain inline transform by
       setMobileNavProgress() in interface.js) — it visually covers/uncovers
       the list like a card, so the list itself never needs to move
       sideways. The list's Y position is a separate, discrete "parked"
       state (body.mobile-list-visible): it snaps to Y=0 the instant it can
       become visible (tap-open or swipe-start) and only animates back down
       (park) once the chat transition has fully settled — so a swipe-back
       reveals the list already sitting there on the left (as the chat
       slides right off of it), never rising up from the bottom. See
       setMobileSidebarOpen()/setupMobileNavGestures() in interface.js. */
    .sidebar {
        position: fixed;
        top: 52px;
        left: 12px;
        right: 12px;
        bottom: calc(12px + 82px + var(--m-safe-bottom));
        z-index: 20;
        width: auto;
        transform: translateY(115%);
        /* This declared transform value only matters for the very first
           paint, before any JS has run — from then on
           setMobileListParked() in interface.js always writes both the
           parked and unparked position as an explicit inline style (never
           clears it to fall back on this rule), for the same reason
           #viewChat's own transform is inline-driven: falling back to a
           cascade value on inline-style removal was tried and measured
           unreliable — after clearing the override, the element kept
           reporting its old computed transform indefinitely instead of
           transitioning to this rule's value. Only the transition DURATION
           is still controlled here/by the class below: none while becoming
           visible (tap-open or swipe-start — the list must be sitting at
           Y=0 instantly, not visibly rising while #viewChat's own .24s
           slide, see further down, is still covering it), this rule's fast
           .12s once parking (once scheduleMobileListPark() confirms the
           chat has fully covered the list again). */
        transition: transform .12s ease-out, box-shadow .12s var(--ease-out);
        /* See #viewChat below: promoted per gesture, not permanently. */
    }

    body.mobile-list-visible .sidebar {
        transition: none;
        box-shadow: 0 18px 48px rgba(0,0,0,.32), inset 0 1px 0 rgba(255,255,255,.02);
    }

    body.mobile-nav-instant #viewChat,
    body.mobile-nav-dragging #viewChat,
    body.mobile-nav-instant .mobile-dock,
    body.mobile-nav-dragging .mobile-dock {
        transition: none;
    }

    body.mobile-nav-dragging #viewChat,
    body.mobile-nav-dragging .mobile-dock,
    body.mobile-nav-dragging .sidebar {
        will-change: transform;
    }

    .main {
        width: 100%;
        min-height: calc(100vh - 76px);
        border-radius: 20px;
    }

    #viewChat {
        z-index: 21;
        /* .view.active's view-enter keyframe animation ends on
           transform: translateY(0) with fill-mode: both, which — being a
           CSS Animation — otherwise wins the cascade over this rule's plain
           transform and permanently pins it to identity. Kill the
           animation here; the push-nav transform below is #viewChat's own
           entrance/exit motion on mobile. */
        animation: none;
        /* Default: chat visible (matches --mnav's old default of 1). The
           actual value is written as a plain inline style by
           setMobileNavProgress() in interface.js — see the comment there
           for why this isn't calc(var(--mnav)) driven. */
        transform: translateX(0);
        transition: transform .24s cubic-bezier(.2,.8,.2,1);
        /* Promoted only while a gesture is actually driving the transform.
           A permanent will-change keeps a full-screen composited layer alive
           for the whole session — two of them, with .sidebar below — which on
           a phone is GPU memory spent on something that moves for a quarter of
           a second at a time. The running .24s transition promotes the element
           by itself. */
    }

    .mobile-backdrop {
        display: none;
    }

    .mobile-dock {
        display: flex;
    }

    #viewChat,
    #viewSettings {
        padding-left: 12px;
        padding-right: 12px;
    }

    #viewChat {
        padding-top: 12px;
        padding-bottom: 14px;
        gap: 14px;
    }

    #viewChat .chat-hdr {
        padding: 12px 14px;
        border-radius: 18px 18px 0 0;
    }

    #viewChat .voice-panel {
        padding: 0 14px 0;
        /* Tighter than the 50vh desktop cap — a phone's viewport is already
           shared with the header and the message composer below, so the same
           fraction would leave barely any room for either. */
        max-height: 44vh;
    }

    #viewChat .voice-panel.has-stage {
        max-height: 90vh;
    }

    #viewChat .msgs {
        padding: 14px 12px calc(208px + var(--kbd-inset, 0px));
        scroll-padding-bottom: calc(208px + var(--kbd-inset, 0px));
    }

    #viewChat .input-area {
        left: 12px;
        right: 12px;
        bottom: calc(14px + var(--kbd-inset, 0px));
        min-height: auto;
        margin: 0;
        padding: 12px 12px 24px;
        border-radius: 0 0 18px 18px;
        transition: bottom .18s var(--ease-out);
    }

    .input-bar {
        width: 100%;
        margin: 0;
    }

    #viewChat .input-area::before {
        left: 12px;
        right: 12px;
    }

    #viewSettings {
        grid-template-rows: auto 1fr;
        padding-top: 12px;
        padding-bottom: 14px;
    }

    .settings-topbar {
        padding: 14px;
        border-radius: 18px 18px 0 0;
    }

    .settings-body {
        padding: 12px 12px 0;
    }

    .settings-shell {
        gap: 12px;
    }

    .settings-card {
        border-radius: 18px;
    }

    .sidebar-head {
        display: flex;
    }

    .sidebar-brand-stack {
        width: 100%;
    }

    .search-wrap {
        width: calc(100% - 24px);
        align-self: stretch;
        display: flex;
        padding-top: 10px;
    }

    .me-ava {
        font-size: 15px;
        line-height: 1;
    }

    .nav-label {
        display: block;
    }

    .contacts {
        padding: 6px 0 10px;
    }

    .contact-info,
    .me > div,
    .badge,
    .contact-remove {
        display: block;
    }

    .me {
        padding: 14px 16px;
    }

    .contact {
        grid-template-columns: 40px minmax(0, 1fr) auto auto;
        align-items: center;
        gap: 10px;
    }

    .contact-info {
        display: block;
        min-width: 0;
    }

    .contact-remove {
        width: 30px;
        height: 30px;
        border-radius: 10px;
        font-size: 18px;
        display: inline-grid;
        place-items: center;
    }

    .badge {
        min-width: 28px;
        height: 20px;
        padding: 0 6px;
        justify-self: end;
    }

    .server-item {
        gap: 10px;
    }

    .server-meta {
        min-width: 0;
    }

    .server-channel-list {
        padding-bottom: 22px;
    }

    /* ── Touch ergonomics ─────────────────────────────────────── */
    /* Remove the 300ms tap delay + the grey/blue tap flash, and the
       iOS long-press text callout on interactive controls. */
    button, a, [role="button"], .contact, .server-item, .server-channel,
    .mobile-dock-btn, .hub-segment-btn, .settings-input, .search-input {
        -webkit-tap-highlight-color: transparent;
        touch-action: manipulation;
    }
    button, a, [role="button"], .mobile-dock-btn, .hub-segment-btn {
        -webkit-touch-callout: none;
    }

    /* Momentum scrolling; keep overscroll from bouncing the whole page. */
    .contacts, .msgs, .settings-body, .sidebar, .server-channel-list,
    .server-modal-content, .color-picker-body {
        -webkit-overflow-scrolling: touch;
        overscroll-behavior: contain;
    }

    /* Never let the page scroll sideways on a phone. */
    html, body {
        overflow-x: hidden;
    }
    img, video {
        max-width: 100%;
    }

    /* iOS zooms the layout when a focused field renders below 16px.
       Force 16px on every text field so focusing an input never zooms. */
    input:not([type="range"]):not([type="checkbox"]):not([type="radio"]):not([type="color"]),
    textarea, select {
        font-size: 16px;
    }

    /* Comfortable touch targets (~44px, per Apple HIG / Material). */
    .contact-remove {
        width: 36px;
        height: 36px;
    }
    .settings-input, .search-input {
        min-height: 44px;
    }

    /* Stack the two-column modals so nothing squeezes off-screen. */
    .server-modal-shell {
        grid-template-columns: 1fr;
    }
    .color-picker {
        grid-template-columns: 1fr;
    }
}

/* ── Small phones ─────────────────────────────────────────────── */
@media (max-width: 400px) {
    .mobile-dock {
        gap: 2px;
        padding: 5px;
    }
    .mobile-dock-btn {
        min-height: 44px;
        padding: 5px 2px;
        border-radius: 18px;
    }
    .mobile-dock-btn svg {
        width: 21px;
        height: 21px;
    }
    .mobile-dock-label {
        font-size: 9px;
        letter-spacing: 0;
    }
    .body {
        padding-left: 8px;
        padding-right: 8px;
    }
    #viewChat,
    #viewSettings {
        padding-left: 8px;
        padding-right: 8px;
    }
}

/* ─── Flat Theme — original look, gradients & glows removed ─── */

/* Lift the near-black base a couple of steps */
body[data-experimental-design="on"] {
    --bg: #0c0e12;
    --sidebar: #0c0e12;
    /* Плоский режим — без стекла и свечения, поэтому всплывающие
       поверхности становятся непрозрачными: полупрозрачный фон без
       backdrop-filter это не «плоско», это грязно — сквозь меню видно
       текст под ним. */
    --menu-bg: rgb(21, 23, 28);
    --menu-blur: none;
    --menu-shadow: 0 0 0 1px rgba(0,0,0,.4);
}

/* App background — solid, no accent bloom, no grid overlay */
body[data-experimental-design="on"] .app {
    background: var(--bg);
}
body[data-experimental-design="on"] .app::before {
    display: none !important;
}

/* Titlebar */
body[data-experimental-design="on"] .titlebar {
    background: rgba(255, 255, 255, 0.03);
}

/* Sidebar */
body[data-experimental-design="on"] .sidebar {
    background: var(--sidebar);
    box-shadow: none;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
}

/* Segment nav + indicator */
body[data-experimental-design="on"] .hub-segment-nav {
    background: rgba(0, 0, 0, 0.18);
    box-shadow: none;
}
body[data-experimental-design="on"] .hub-segment-indicator {
    background: rgb(var(--accent-rgb));
    box-shadow: none;
}

/* Search input */
body[data-experimental-design="on"] .search-input {
    background: rgba(255, 255, 255, 0.04);
    box-shadow: none;
}

/* Lime/accent solid fills (were gradients) */
body[data-experimental-design="on"] .mode-btn.active,
body[data-experimental-design="on"] .contact-add-btn,
body[data-experimental-design="on"] .server-channel.active,
body[data-experimental-design="on"] .voice-btn,
body[data-experimental-design="on"] .voice-meter-fill,
body[data-experimental-design="on"] .server-avatar-preview,
body[data-experimental-design="on"] .server-banner-preview,
body[data-experimental-design="on"] .hub-orb {
    background: rgb(var(--accent-rgb));
    box-shadow: none;
}
body[data-experimental-design="on"] .contact-add-btn.is-active {
    background: rgba(255, 255, 255, 0.06);
    color: var(--lime);
}
body[data-experimental-design="on"] .voice-btn.danger {
    background: rgb(255, 77, 109);
}

/* Main panel */
body[data-experimental-design="on"] .main {
    background: var(--bg);
    box-shadow: none;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
}

/* Hub */
body[data-experimental-design="on"] #viewHub {
    background: rgba(0, 0, 0, 0.16);
}
body[data-experimental-design="on"] .hub-hero,
body[data-experimental-design="on"] .hub-card {
    background: rgba(255, 255, 255, 0.035);
    box-shadow: none;
}
body[data-experimental-design="on"] .hub-card:hover {
    box-shadow: none;
}
body[data-experimental-design="on"] .hub-components {
    background: rgba(255, 255, 255, 0.025);
    box-shadow: none;
}

/* Message bubbles — flat */
body[data-experimental-design="on"] .bubble {
    background: rgba(255, 255, 255, 0.06);
    box-shadow: none;
}
body[data-experimental-design="on"] .out .bubble {
    background: rgb(var(--accent-rgb));
    border: 1px solid rgb(var(--accent-rgb));
    box-shadow: none;
}
body[data-experimental-design="on"] .msg.group-start::before,
body[data-experimental-design="on"] .msg.out.group-start::before {
    background: none;
}

/* Input bar */
body[data-experimental-design="on"] .input-bar {
    background: rgba(8, 10, 13, 0.9);
    box-shadow: none;
}

/* Settings cards */
body[data-experimental-design="on"] .settings-card {
    background: rgba(255, 255, 255, 0.02);
    box-shadow: none;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
}
body[data-experimental-design="on"] .settings-card::before {
    display: none;
}

/* Server modals & cards — flat */
body[data-experimental-design="on"] .server-modal {
    background: rgb(16, 18, 22);
    box-shadow: none;
}
body[data-experimental-design="on"] .server-modal::before,
body[data-experimental-design="on"] .server-modal-card::before {
    display: none;
}
body[data-experimental-design="on"] .server-modal-sidebar,
body[data-experimental-design="on"] .server-modal-card,
body[data-experimental-design="on"] .server-asset-card,
body[data-experimental-design="on"] .server-link-card,
body[data-experimental-design="on"] .server-channel-card,
body[data-experimental-design="on"] .server-role-card,
body[data-experimental-design="on"] .server-channel-create,
body[data-experimental-design="on"] .server-role-create {
    background: rgba(255, 255, 255, 0.025);
    box-shadow: none;
}

/* Recent accounts */
body[data-experimental-design="on"] .recent-account-row {
    background: rgba(255, 255, 255, 0.035);
    box-shadow: none;
}
body[data-experimental-design="on"] .recent-account-row.is-active {
    background: rgba(255, 255, 255, 0.05);
    box-shadow: none;
}

/* Auth */
body[data-experimental-design="on"] .auth-card {
    background: rgb(18, 20, 24);
    box-shadow: none;
}
body[data-experimental-design="on"] .auth-card::before {
    display: none;
}
body[data-experimental-design="on"] .auth-btn.primary {
    box-shadow: none;
}

/* Misc flats */
body[data-experimental-design="on"] .btn-flat {
    background: rgba(255, 255, 255, 0.05);
}
/* Danger buttons must stay filled red in flat mode too — the blanket
   .btn-flat background override above would otherwise wipe out their
   red tint and leave only the red border. */
body[data-experimental-design="on"] .settings-logout {
    background: rgb(255, 77, 109);
    border-color: rgb(255, 77, 109);
    color: #fff;
}
body[data-experimental-design="on"] .settings-logout:hover {
    border-color: rgb(255, 77, 109);
    color: #fff;
    filter: brightness(1.1);
}
body[data-experimental-design="on"] .file-chip {
    background: rgba(255, 255, 255, 0.06);
    box-shadow: none;
}

/* Kill remaining accent glows (box-shadow / drop-shadow) */
body[data-experimental-design="on"] .mobile-dock-btn.active,
body[data-experimental-design="on"] .mode-btn.active,
body[data-experimental-design="on"] .contact-add-btn,
body[data-experimental-design="on"] .contact-add-btn:hover,
body[data-experimental-design="on"] .contact.active,
body[data-experimental-design="on"] .server-item.active,
body[data-experimental-design="on"] .btn-flat:hover,
body[data-experimental-design="on"] .send-btn,
body[data-experimental-design="on"] .send-btn:hover,
body[data-experimental-design="on"] .voice-room-card,
body[data-experimental-design="on"] .voice-health-card {
    box-shadow: none;
}
body[data-experimental-design="on"] .server-settings-btn .ui-icon-phone,
body[data-experimental-design="on"] .attach-btn .ui-icon-paperclip {
    filter: none;
}

/* Scrollbar — solid */
body[data-experimental-design="on"] ::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.12);
}
body[data-experimental-design="on"] ::-webkit-scrollbar-thumb:hover {
    background: rgba(255, 255, 255, 0.2);
}

/* Installed as a home-screen app (iOS/Android standalone PWA): the OS status bar
   overlaps the top of the viewport instead of pushing it down, so pad it ourselves. */
@media (display-mode: standalone) {
    .titlebar {
        padding-top: var(--m-safe-top);
    }
}

/* One-time "Add to Home Screen" hint for iOS Safari (no beforeinstallprompt API there). */
.a2hs-banner {
    position: fixed;
    left: 12px;
    right: 12px;
    bottom: calc(12px + var(--m-safe-bottom));
    z-index: 60;
    display: none;
    align-items: center;
    gap: 10px;
    padding: 12px 14px;
    border-radius: 14px;
    background: rgba(20, 22, 28, 0.96);
    border: 1px solid var(--border);
    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.4);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
}
.a2hs-banner.visible {
    display: flex;
}
.a2hs-banner-text {
    flex: 1;
    min-width: 0;
    font-size: 13px;
    line-height: 1.4;
    color: var(--text2);
}
.a2hs-banner-text b {
    color: var(--text);
}
.a2hs-banner-close {
    flex: none;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    border: none;
    background: rgba(255, 255, 255, 0.08);
    color: var(--text2);
    font-size: 16px;
    line-height: 1;
    cursor: pointer;
}

/* ============================================================
   ZALICOIN — this app has no multi-hue categorical palette anywhere;
   every themed surface (10 swappable themes in styler.js) is shades/
   opacity of one accent color (--accent-rgb). The distribution bar
   below follows that convention instead of a foreign rainbow palette:
   rank-ordered opacity steps of the *current* theme's accent, so it
   reads as "how much of the single accent hue this holder owns" and
   re-themes automatically with the rest of the app.
   ============================================================ */
:root {
    --zc-series-1: rgba(var(--accent-rgb), .95);
    --zc-series-2: rgba(var(--accent-rgb), .78);
    --zc-series-3: rgba(var(--accent-rgb), .62);
    --zc-series-4: rgba(var(--accent-rgb), .48);
    --zc-series-5: rgba(var(--accent-rgb), .36);
    --zc-series-6: rgba(var(--accent-rgb), .26);
    --zc-series-7: rgba(var(--accent-rgb), .18);
    --zc-series-8: rgba(var(--accent-rgb), .12);
    --zc-series-other: rgba(255,255,255,.14);
    --zc-series-unassigned: rgba(255,255,255,.05);
}

.zc-view {
    max-width: 880px;
    margin: 0 auto;
    width: 100%;
}

.zc-orb {
    font-weight: 800;
    letter-spacing: -.03em;
}

.zc-balance-card {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 14px;
}

.zc-balance-card > * {
    position: relative;
    z-index: 1;
}

.zc-balance-main {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

.zc-balance-label {
    color: var(--text2);
    font-size: 13px;
}

.zc-balance-value {
    font-size: 34px;
    font-weight: 800;
    letter-spacing: -.03em;
    color: var(--text);
    font-variant-numeric: tabular-nums;
}

.zc-balance-unit {
    color: var(--lime);
    font-weight: 700;
    font-size: 14px;
}

.zc-balance-share {
    color: var(--text2);
    font-size: 13px;
    margin-right: auto;
}

.zc-distribution-card {
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.zc-distribution-card > * {
    position: relative;
    z-index: 1;
}

.zc-bar {
    display: flex;
    align-items: stretch;
    gap: 2px;
    height: 28px;
    border-radius: 999px;
    overflow: hidden;
    background: var(--zc-series-unassigned);
}

.zc-segment {
    flex-grow: 0;
    flex-shrink: 0;
    min-width: 3px;
    border: none;
    padding: 0;
    cursor: pointer;
    transition: filter .15s var(--ease-out), transform .15s var(--ease-out);
}

.zc-segment:first-child {
    border-top-left-radius: 999px;
    border-bottom-left-radius: 999px;
}

.zc-segment:last-child {
    border-top-right-radius: 999px;
    border-bottom-right-radius: 999px;
}

.zc-segment:hover,
.zc-segment:focus-visible {
    filter: brightness(1.18);
    transform: scaleY(1.08);
}

.zc-segment--me {
    box-shadow: inset 0 0 0 2px rgba(255,255,255,.55);
}

.zc-legend {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.zc-legend-item {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 13px;
}

.zc-legend-swatch {
    flex: none;
    width: 11px;
    height: 11px;
    border-radius: 3px;
}

.zc-legend-label {
    color: var(--text);
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.zc-legend-value {
    color: var(--text2);
    font-variant-numeric: tabular-nums;
    flex: none;
}

.zc-legend-empty {
    color: var(--text2);
    font-size: 13px;
}

.coin-transfer-modal {
    /* Внутри .main, как и остальные модальные слои — см. .profile-overlay. */
    position: absolute;
    inset: 0;
    z-index: 70;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 12px;
    background: rgba(4, 6, 10, .78);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
}

.coin-transfer-modal[hidden] {
    display: none;
}

.coin-transfer-box {
    width: min(100%, 380px);
    display: flex;
    flex-direction: column;
    gap: 14px;
    padding: 22px;
    border: 1px solid rgba(255,255,255,.08);
    border-radius: 20px;
    background: linear-gradient(180deg, rgba(22,24,28,.98), rgba(10,12,16,.98));
    box-shadow: 0 30px 90px rgba(0,0,0,.52), 0 0 0 1px rgba(var(--accent-rgb),.06);
}

.coin-transfer-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}

.coin-transfer-head h2 {
    margin: 0;
    font-size: 18px;
    color: var(--text);
}

.coin-transfer-field {
    display: flex;
    flex-direction: column;
    gap: 6px;
    font-size: 13px;
    color: var(--text2);
}

.coin-transfer-field input {
    height: var(--control-h);
    padding: 0 12px;
    border-radius: 11px;
    border: 1px solid var(--border);
    background: rgba(255,255,255,.04);
    color: var(--text);
    font-size: 14px;
}

.coin-transfer-field input:focus {
    outline: none;
    border-color: var(--lime);
    box-shadow: 0 0 0 2px var(--lime-dim);
}

.coin-transfer-status {
    margin: 0;
    font-size: 13px;
    color: var(--text2);
}

.coin-transfer-actions {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
}

/* ============================================================================
   MOBILE REDESIGN 2026 — Telegram-class shell, Zali brand (dark + neon-lime)
   Scoped to <=760px and appended last so it wins equal-specificity cascades.
   Phase A: navigation shell (app-bars, full-bleed frame, dock, reconnect strip).
   ========================================================================== */
@media (max-width: 760px) {
    :root {
        /* --m-safe-top / --m-safe-bottom are defined at the top of this file
           (and may be overridden inline by a native shell) — redefining them
           here would clobber that override. */
        --m-appbar-h: 54px;
        --m-dock-h: 64px;
        --m-net-h: 26px;
        --m-spring: cubic-bezier(.22, .9, .24, 1);
        --m-surface: #0c0f14;
        --m-surface-2: #12161d;
        --m-hairline: rgba(255,255,255,.07);
        /* The frosted material behind the sticky app-bar and the docked input.
           A token, not four copies of a literal, because it has to be switched
           off in one place while the push-nav gesture runs — see below.

           Was blur(18px) saturate(160%). Both halves cost per frame, and unlike
           the desktop panels these two sit over a list that is *moving*: a
           backdrop filter is recomputed whenever what is behind it changes, so
           on mobile that is twice per scroll frame, full screen width. The
           saturate() pass is dropped outright (it is composited on top of the
           app's own near-monochrome background, where it reads as almost
           nothing) and the radius is trimmed; the material still reads as
           frosted glass. */
        --m-glass: blur(12px);
    }

    /* During the back-swipe #viewChat is being translated with both frosted
       surfaces inside it, so every frame of the drag re-blurs a full-width
       strip against content that is itself moving — the single most expensive
       thing the client does on a phone. The gesture is the one moment the
       material is not being looked at, so drop it for the duration. */
    body.mobile-nav-dragging {
        --m-glass: none;
    }

    /* ── Kill desktop chrome: the global titlebar is replaced by per-screen
       app-bars (list = .sidebar-head, chat = .chat-hdr). ─────────────────── */
    .titlebar { display: none !important; }

    /* .titlebar is gone here, so the fullscreen overlays' top offset (reserved
       for it — and the macOS traffic lights over it — on desktop) would just
       expose whatever per-screen app-bar sits underneath. No desktop window
       chrome on mobile, so go back to true edge-to-edge. */


    /* Full-bleed app frame — no desktop card insets / rounded panels. */
    .body {
        grid-template-columns: 1fr;
        gap: 0;
        padding: 0;
        min-height: 100vh;
    }
    .main {
        width: 100%;
        min-height: 100vh;
        border-radius: 0;
        border: 0;
        background: transparent;
        /* MUST drop the desktop glass here, and not only for looks: any
           backdrop-filter other than `none` turns .main into a *stacking
           context*, which traps #viewChat's `z-index: 21` inside it. .main
           itself has `z-index: auto` (paints at 0), so the whole chat subtree
           was painted BELOW the fixed `.sidebar` (z-index: 20) no matter how
           high #viewChat's own z-index went. That is what made the back-swipe
           look wrong: instead of the chat sliding right off a list that is
           already sitting underneath it, the list — unparked instantly, by
           design, with `transition: none` — slammed on top of everything the
           moment the drag/tap started, reading as "popping up from the
           bottom and covering the chat". Verified live via elementFromPoint:
           with the blur on, the topmost element over the still-visible half
           of the translated #viewChat was .sidebar's #contacts; with it off,
           it is #viewChat, and only the uncovered strip hits the sidebar.
           .main's background is already transparent on mobile, so there is
           nothing left for the blur to do anyway. */
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
        box-shadow: none;
    }

    /* ── LIST SCREEN: sidebar becomes a full-bleed panel with a sticky
       app-bar (brand title + search) over a scrolling dialog list. ──────── */
    .sidebar {
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        width: 100%;
        border-radius: 0;
        border: 0;
        background: var(--bg);
        display: flex;
        flex-direction: column;
        padding: 0;
        box-shadow: none;
    }
    body.mobile-list-visible .sidebar { box-shadow: none; }

    .sidebar-head {
        position: sticky;
        top: 0;
        z-index: 5;
        flex-direction: column;
        align-items: stretch;
        gap: 0;
        padding: calc(var(--m-safe-top) + 8px) 16px 8px;
        margin: 0;
        background: color-mix(in srgb, var(--bg) 88%, transparent);
        -webkit-backdrop-filter: var(--m-glass);
        backdrop-filter: var(--m-glass);
        border-bottom: 1px solid var(--m-hairline);
    }
    .sidebar-brand-stack { width: 100%; }
    .sidebar-head .brand {
        font-size: 22px;
        font-weight: 900;
        letter-spacing: .2px;
        line-height: 1.1;
        margin: 0;
    }
    /* Section switching lives in the bottom dock on mobile — hide the
       in-sidebar duplicate switches. */
    .sidebar-head .mode-switch,
    .sidebar-head .hub-segment-nav { display: none !important; }
    /* Settings live in the dock too — drop the desktop "me" footer row. */
    .sidebar .me { display: none !important; }

    .search-wrap {
        width: 100%;
        align-self: stretch;
        display: flex;
        gap: 10px;
        padding: 10px 16px 8px;
        margin: 0;
        background: color-mix(in srgb, var(--bg) 88%, transparent);
        -webkit-backdrop-filter: var(--m-glass);
        backdrop-filter: var(--m-glass);
        position: sticky;
        top: calc(var(--m-safe-top) + 46px);
        z-index: 4;
        border-bottom: 1px solid var(--m-hairline);
    }
    .search-box {
        flex: 1 1 auto;
        border-radius: 12px;
        background: var(--m-surface-2);
    }
    .nav-label {
        display: block;
        padding: 12px 16px 6px;
        margin: 0;
        font-size: 12px;
    }
    .contacts {
        flex: 1 1 auto;
        min-height: 0;
        overflow-y: auto;
        padding: 0 0 calc(var(--m-dock-h) + var(--m-safe-bottom) + 22px);
    }

    /* ── CHAT SCREEN: #viewChat is a full-bleed column with a sticky
       app-bar; back chevron returns to the list. ────────────────────────── */
    #viewChat,
    #viewSettings {
        padding-left: 0;
        padding-right: 0;
    }
    #viewChat {
        padding: 0;
        gap: 0;
        background: var(--bg);
    }
    /* MUST stay scoped to .active. `.view { display: none }` is a class
       selector (0,1,0), so an *unconditional* `#viewChat { display: flex }`
       (1,0,0) outranks it and pins the chat visible even when it isn't the
       active view — and since #viewChat is `position: absolute; inset: 0`
       with z-index 21, it then permanently covers #viewSettings/#viewHub,
       which is why the Settings and Hub screens could never be seen on
       mobile (confirmed live via DevTools: both #viewChat and #viewSettings
       reported a non-none display at the same time).

       Why flex at all: the base rule makes .view.active a 3-row grid
       (auto auto 1fr); with the voice-panel hidden the message list lands in
       the 2nd auto row and an empty 1fr track eats the space below it (dead
       gap + a seam line). A flex column lets .msgs stretch to fill the whole
       chat area. */
    #viewChat.active {
        display: flex;
        flex-direction: column;
    }
    #viewChat > .msgs { flex: 1 1 auto; min-height: 0; }
    #viewChat .chat-hdr {
        position: sticky;
        top: 0;
        z-index: 6;
        padding: calc(var(--m-safe-top) + 8px) 10px 8px;
        border-radius: 0;
        border: 0;
        border-bottom: 1px solid var(--m-hairline);
        background: color-mix(in srgb, var(--bg) 86%, transparent);
        -webkit-backdrop-filter: var(--m-glass);
        backdrop-filter: var(--m-glass);
        gap: 8px;
        align-items: center;
    }
    .chat-back-btn {
        display: inline-grid !important;
        place-items: center;
        width: 38px;
        height: 38px;
        flex: 0 0 auto;
        border: 0;
        border-radius: 12px;
        background: transparent;
        color: var(--text);
        cursor: pointer;
        -webkit-tap-highlight-color: transparent;
        transition: background .18s var(--ease-out), transform .12s var(--ease-out);
    }
    .chat-back-btn svg { width: 24px; height: 24px; }
    .chat-back-btn:active { background: rgba(255,255,255,.06); transform: scale(.92); }
    #viewChat .chat-hdr-ava { width: 40px; height: 40px; font-size: 16px; }
    #viewChat .msgs {
        padding: 12px 10px calc(96px + var(--kbd-inset, 0px) + var(--m-safe-bottom));
        scroll-padding-bottom: calc(96px + var(--kbd-inset, 0px) + var(--m-safe-bottom));
    }
    #viewChat .input-area {
        left: 0;
        right: 0;
        bottom: 0;
        padding: 8px 10px calc(8px + var(--m-safe-bottom));
        border-radius: 0;
        border-top: 1px solid var(--m-hairline);
        background: color-mix(in srgb, var(--bg) 92%, transparent);
        -webkit-backdrop-filter: var(--m-glass);
        backdrop-filter: var(--m-glass);
    }
    #viewChat .input-area::before { display: none; }

    /* The other full-screen sections have no sticky app-bar of their own to
       absorb the top inset the way .sidebar-head / .chat-hdr do, and the bottom
       bar (the web dock, or a native shell's own bar) floats over their content
       — so they reserve both insets themselves. Without this the Settings
       heading rendered under the clock and its last card under the bar. */
    #viewSettings,
    #viewHub,
    #viewZaliCoin {
        padding-top: calc(var(--m-safe-top) + 12px);
        padding-bottom: calc(var(--m-dock-h) + var(--m-safe-bottom) + 16px);
    }

    /* ── Bottom dock: keep the existing glass pill, only widen touch area
       and let it hug the safe-area. Transform stays JS-driven. ──────────── */
    .mobile-dock {
        width: min(100vw - 20px, 480px);
        bottom: calc(10px + var(--m-safe-bottom));
    }

    /* Desktop status pill is hidden; the mobile reconnect strip takes over. */
    .ws-pill { display: none; }

    /* When the reconnect strip is up, push the sticky app-bars below it so it
       never overlaps the title / chat header. */
    body.ws-offline .sidebar-head,
    body.ws-offline #viewChat .chat-hdr {
        padding-top: calc(var(--m-safe-top) + var(--m-net-h) + 8px);
    }
    body.ws-offline .search-wrap { top: calc(var(--m-safe-top) + var(--m-net-h) + 46px); }
}

/* The chat app-bar back chevron is mobile-only (the mobile media query
   force-shows it); hide it on desktop where the sidebar is always present. */
.chat-back-btn { display: none; }

/* Mobile reconnect strip — a slim animated banner shown under the app-bar
   only while the socket is down. Hidden on desktop and while connected. */
.m-net-strip { display: none; }
@media (max-width: 760px) {
    body.ws-offline .m-net-strip {
        position: fixed;
        top: 0;
        left: 0;
        right: 0;
        z-index: 40;
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 8px;
        padding: calc(var(--m-safe-top) + 5px) 12px 5px;
        font-size: 12px;
        font-weight: 700;
        color: #05210b;
        background: linear-gradient(180deg, rgba(var(--accent-rgb),.96), rgba(var(--accent-rgb),.82));
        animation: m-net-slide .28s var(--m-spring) both;
    }
    .m-net-spin {
        width: 12px;
        height: 12px;
        border-radius: 50%;
        border: 2px solid rgba(5,33,11,.35);
        border-top-color: #05210b;
        animation: m-net-rot .7s linear infinite;
    }
}
@keyframes m-net-slide { from { transform: translateY(-100%); } to { transform: translateY(0); } }
@keyframes m-net-rot { to { transform: rotate(360deg); } }

/* ============================================================================
   MOBILE REDESIGN 2026 — Phase C: conversation (bubbles, time, composer)
   ========================================================================== */
@media (max-width: 760px) {
    /* Bubbles hug their content a bit tighter and use softer shadows. */
    .bwrap { max-width: 80%; }
    #viewChat .bubble {
        padding: 7px 12px 6px;
        border-radius: 19px;
        box-shadow: 0 1px 1.5px rgba(0,0,0,.16);
    }

    /* Telegram-style grouped corners: the side facing the avatar squares off on
       stacked / last bubbles, giving a subtle tail without a triangle. */
    .msg.in .bubble  { border-radius: 19px; }
    .msg.out .bubble { border-radius: 19px; }
    .msg.in.group-start  .bubble { border-bottom-left-radius: 7px; }
    .msg.in.group-mid    .bubble { border-top-left-radius: 7px; border-bottom-left-radius: 7px; }
    .msg.in.group-end    .bubble { border-top-left-radius: 7px; border-bottom-left-radius: 7px; }
    .msg.in.group-single .bubble { border-bottom-left-radius: 7px; }
    .msg.out.group-start  .bubble { border-bottom-right-radius: 7px; }
    .msg.out.group-mid    .bubble { border-top-right-radius: 7px; border-bottom-right-radius: 7px; }
    .msg.out.group-end    .bubble { border-top-right-radius: 7px; border-bottom-right-radius: 7px; }
    .msg.out.group-single .bubble { border-bottom-right-radius: 7px; }

    /* Timestamp INSIDE the bubble (the desktop design floats it in the margin,
       which clips off-screen on a phone). Render it as a compact right-aligned
       line at the bottom of the bubble — never overlapping the text. */
    #viewChat .msg-time {
        position: static;
        left: auto; right: auto; top: auto; bottom: auto;
        transform: none;
        display: block;
        width: 100%;
        text-align: right;
        margin: 1px 0 -1px;
        padding: 0;
        font-size: 10.5px;
        opacity: .5;
        pointer-events: none;
"""#,
    #"""
    }
    .msg.in .msg-time  { color: var(--text3); }
    .msg.out .msg-time { color: rgba(15,20,0,.5); }
    .msg.time-visible .msg-time { opacity: .6; }

    /* Received-message avatar sits at the bottom of the last bubble in a group. */
    #viewChat .msg-ava { width: 30px; height: 30px; font-size: 12px; }

    /* Composer becomes a single rounded pill: round attach / coin / send inside. */
    #viewChat .input-bar {
        grid-template-columns: auto auto 1fr auto;
        align-items: center;
        gap: 2px;
        height: auto;
        min-height: 48px;
        width: 100%;
        margin: 0;
        padding: 4px 5px 4px 6px;
        border-radius: 26px;
        border: 1px solid var(--m-hairline);
        background: var(--m-surface-2);
        box-shadow: none;
    }
    #viewChat .attach-btn,
    #viewChat .coin-transfer-btn {
        width: 38px;
        height: 38px;
        border-radius: 50%;
        border: 0;
        background: transparent;
        color: var(--text2);
        box-shadow: none;
    }
    #viewChat .attach-btn:hover,
    #viewChat .coin-transfer-btn:hover { background: rgba(255,255,255,.06); }
    #viewChat #msgInput {
        height: auto;
        min-height: 24px;
        padding: 8px 6px;
        font-size: 16px;
    }
    #viewChat .send-btn {
        width: 42px;
        height: 42px;
        border-radius: 50%;
        box-shadow: 0 4px 14px rgba(var(--accent-rgb),.30);
    }
    #viewChat .send-btn:disabled { box-shadow: none; }

    /* Day separator: neat centered pill. */
    #viewChat .date-sep span {
        background: rgba(255,255,255,.06);
        border-radius: 12px;
        padding: 3px 12px;
        font-size: 11px;
    }
}

/* Mobile chat header: presence-style subtitle, drop the crypto-debug key line
   and the redundant "Диалог с …" prefix clutter to a single quiet line. */
@media (max-width: 760px) {
    #viewChat .chat-hdr-key { display: none; }
    #viewChat .chat-hdr-info { gap: 1px; }
    #viewChat .chat-hdr-name { font-size: 16px; font-weight: 800; }
    #viewChat .chat-hdr-sub,
    #viewChat .chat-hdr-desc { font-size: 12px; color: var(--text2); }
    #viewChat .chat-hdr-actions .server-settings-btn { width: 40px; height: 40px; }
}

/* Row last-message time is a mobile-only affordance; hidden on desktop. */
.contact-time { display: none; }

/* ============================================================================
   MOBILE REDESIGN 2026 — Phase B: dialog list rows (Telegram-style density)
   ========================================================================== */
@media (max-width: 760px) {
    .contacts .contact,
    .contact {
        grid-template-columns: 52px minmax(0, 1fr) auto;
        gap: 12px;
        min-height: 68px;
        padding: 8px 16px;
        border-radius: 0;
        animation: none;
    }
    .contact:active { background: rgba(255,255,255,.06); }
    .contact.active {
        background: rgba(var(--accent-rgb), .12);
        box-shadow: none;
    }
    /* Bigger avatars, and drop the heavy glow/pulse the desktop active row uses. */
    .contact .ava { width: 52px; height: 52px; }
    .contact.active .ava { box-shadow: 0 0 0 1px rgba(255,255,255,.05); animation: none; }

    .contact-name { font-size: 16px; font-weight: 700; }
    .contact-prev { font-size: 13.5px; margin-top: 2px; }

    /* Right column: time on top, unread pill below — the classic list layout. */
    .contact-actions {
        flex-direction: column;
        align-items: flex-end;
        justify-content: center;
        gap: 6px;
        min-height: 52px;
        align-self: center;
    }
    .contact-time {
        display: block;
        font-size: 12px;
        font-weight: 600;
        color: var(--text3);
        line-height: 1;
    }
    .contact.active .contact-time { color: var(--text2); }

    /* Unread pill — compact lime counter, right aligned. */
    .contact .badge {
        min-width: 20px;
        height: 20px;
        padding: 0 6px;
        border-radius: 10px;
        font-size: 12px;
        font-weight: 700;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        background: var(--lime);
        color: #05210b;
    }

    /* Deleting a dialog is this button, not a gesture: swipe-to-reveal-Delete
       used to hide it here, but the left-swipe now belongs to the forward
       navigation gesture (list → last open chat), so the button is back — and
       sized for a finger. */
    .contact .contact-remove {
        /* Sizing/touch target already come from the earlier mobile blocks
           (inline-grid, 36×36); this only undoes the old `display: none`. */
        display: inline-grid;
        opacity: .55;
    }

    /* Row separators like a native list (indented past the avatar). */
    .contacts .contact + .contact::before {
        content: "";
        position: absolute;
        left: 80px;
        right: 0;
        top: 0;
        height: 1px;
        background: var(--m-hairline);
    }
    .contacts .contact { position: relative; }

    /* Section caption ("Диалоги") — quieter, uppercase. */
    .nav-label {
        color: var(--text3);
        text-transform: uppercase;
        letter-spacing: .08em;
        font-weight: 700;
    }
}

/* Hide custom scrollbars on mobile scroll areas — native mobile lists auto-hide
   their scrollbars; the desktop lime scrollbar looks out of place on a phone. */
@media (max-width: 760px) {
    .contacts, #viewChat .msgs, .server-channel-list {
        scrollbar-width: none;
        -ms-overflow-style: none;
    }
    .contacts::-webkit-scrollbar,
    #viewChat .msgs::-webkit-scrollbar,
    .server-channel-list::-webkit-scrollbar { width: 0; height: 0; display: none; }
}

/* ============================================================================
   MOBILE REDESIGN 2026 — Phase D: gestures (long-press)
   Horizontal row gestures were removed here: a left-swipe on the list screen
   now navigates forward to the last open chat (setupMobileForwardNavGesture in
   interface.js), so a row can no longer claim the same drag for a destructive
   reveal-Delete action.
   ========================================================================== */
@media (max-width: 760px) {
    .contacts { overflow-x: hidden; }

    /* Long-press feedback on a message before the reaction menu opens. */
    .msg.press-hold .bubble {
        transform: scale(.97);
        transition: transform .18s cubic-bezier(.2,.9,.24,1);
    }
    .msg .bubble { transition: transform .18s cubic-bezier(.2,.9,.24,1); }

    /* То же самое для строки диалога и канала: долгое нажатие по ним теперь
       открывает контекстное меню (bindMobileLongPress в mobile.js), а без
       обратной связи такое нажатие неотличимо от подвисшего тапа — человек
       отпускает палец раньше, чем меню успевает появиться.

       Только transform: у .contact и .server-channel уже объявлен собственный
       transition (строки ~1560 и ~1850), и он включает transform вместе с
       цветом, фоном и тенью. Дописать здесь свой `transition` значило бы
       заменить их шорткат целиком и молча выключить на мобильном всю остальную
       анимацию этих строк. */
    .contact.press-hold,
    .server-channel.press-hold { transform: scale(.975); }

    /* Reaction menu: bigger touch targets on a phone. */
    /* Шесть эмодзи, разделитель и три действия — это девять кнопок в один
       ряд. По 44 px ряд занимает 388 px и на 375-пиксельном экране просто
       уезжает за край: showReactionMenu прижимает меню к левому отступу, а
       «Удалить» оказывается за границей экрана. 36 укладывает весь ряд в
       352 px, а max-width + горизонтальная прокрутка страхуют экраны уже
       375 px и любую будущую кнопку. */
    .reaction-menu {
        padding: 5px;
        border-radius: 999px;
        max-width: calc(100vw - 16px);
        overflow-x: auto;
        overscroll-behavior-x: contain;
        scrollbar-width: none;
    }
    .reaction-menu::-webkit-scrollbar { display: none; }
    .reaction-menu .reaction-btn { width: 36px; height: 36px; font-size: 21px; }
    .reaction-menu .reaction-btn .ui-icon { width: 19px; height: 19px; }
    .reaction-menu-sep { height: 22px; margin: 0 3px; }
}

/* ============================================================================
   MOBILE REDESIGN 2026 — Phase E: motion & micro-interactions
   (The existing prefers-reduced-motion block disables these with !important.)
   ========================================================================== */
@media (max-width: 760px) {
    /* NOTE: deliberately no entrance animation on .contact / .msg here.
       renderContacts() and _renderMessagesNow() rebuild their lists with
       innerHTML on every update, so a per-item entrance would re-fire on every
       row and bubble each time a message arrives — the desktop rule neutralises
       its own `contact-in` for the same reason. Motion below is limited to
       states that only change on real interaction. */

    /* Press feedback on the primary touch targets. */
    .mobile-dock-btn:active { transform: scale(.92); }
    .chat-hdr-actions .server-settings-btn:active { transform: scale(.9); }
    .send-btn:active { transform: scale(.9); }
    .attach-btn:active,
    .coin-transfer-btn:active { transform: scale(.88); }

    /* App-bars settle in when a screen becomes visible. */
    .sidebar-head,
    #viewChat .chat-hdr { transition: padding-top .2s var(--m-spring); }
}


/* ============================================================
   ПРОФИЛИ ЛЮДЕЙ
   Оверлей профиля, вкладки, комментарии, друзья и векторная
   стена автографов.
   ============================================================ */

.me-ava-btn {
    position: relative;
    display: block;
    padding: 0;
    border: none;
    background: none;
    cursor: pointer;
    line-height: 0;
}

.me-friend-badge {
    position: absolute;
    /* .ava (the avatar right behind it) sets z-index:1 and creates its own
       stacking context — without a z-index here higher than that, the badge
       (z-index:auto) paints BELOW the avatar despite coming later in the DOM,
       so it was getting covered instead of overlapping the corner. */
    z-index: 2;
    top: -4px;
    right: -4px;
    min-width: 18px;
    height: 18px;
    padding: 0 5px;
    border-radius: 999px;
    background: var(--lime);
    color: #0b0d10;
    font-size: 11px;
    font-weight: 700;
    line-height: 18px;
    text-align: center;
    pointer-events: none;
}

.profile-overlay {
    /* Слой живёт внутри .main (см. разметку index.html) и потому кроется
       по области чата: левая навигация остаётся видимой и кликабельной,
       пока открыт диалог. Раньше это был fixed-слой на весь экран с
       ручным `top: var(--titlebar-h)`, чтобы не прятать титлбар; теперь
       титлбар и боковая панель просто вне коробки. На телефоне слой
       возвращается к fixed на весь экран — там боковой панели рядом с
       чатом нет. */
    position: absolute;
    inset: 0;
    z-index: 620;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    background: rgba(4,6,9,.72);
    backdrop-filter: blur(6px);
    opacity: 0;
    transition: opacity .18s var(--ease, ease);
}

.profile-overlay.visible { opacity: 1; }

.profile-modal {
    position: relative;
    width: 100%;
    height: 100%;
    /* 100%, а не 100vh: коробкой теперь служит панель чата, а не окно. */
    max-height: 100%;
    /* Not the scroll container itself (was `overflow: auto` here) — that made
       .profile-close, an absolutely-positioned child of THIS box, scroll away
       with the content: absolute positioning is relative to the padding box,
       but rendering still follows the scroll offset of whatever box actually
       has the overflow. Only .profile-body scrolls now (below), so the close
       button — a flex sibling, not a descendant of the scrolling box — stays
       pinned at the same spot on screen no matter how far the profile is
       scrolled. */
    overflow: hidden;
    display: flex;
    flex-direction: column;
    border-radius: 0;
    border: none;
    background: var(--sidebar);
    box-shadow: none;
    transform: translateY(8px);
    transition: transform .18s var(--ease, ease);
}

.profile-overlay.visible .profile-modal { transform: translateY(0); }

.profile-close {
    position: absolute;
    top: 14px;
    right: 14px;
    z-index: 2;
    width: 34px;
    height: 34px;
    display: grid;
    place-items: center;
    border-radius: 50%;
    border: 1px solid var(--border);
    background: rgba(255,255,255,.04);
    color: var(--text2);
    cursor: pointer;
}

.profile-close:hover { color: var(--text); background: rgba(255,255,255,.09); }
.profile-close svg { width: 18px; height: 18px; }

.profile-body {
    padding: 26px;
    display: grid;
    gap: 18px;
    /* The actual scroll container now (see .profile-modal) — flex:1 to fill
       whatever space .profile-modal doesn't need for anything else (it needs
       none, .profile-close is out of flow, but this is what makes the grid
       take the full height rather than shrinking to its content), and
       min-height:0 because a flex item's default min-height:auto would
       otherwise refuse to shrink below its content size and defeat the
       overflow entirely. */
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    /* start, а не значение по умолчанию. У грида `align-content: normal`
       ведёт себя как stretch и раздаёт свободную высоту ВСЕМ auto-строкам
       поровну. Пока содержимое вкладки было выше коробки («Стена» с
       холстом), свободной высоты не оставалось и этого никто не замечал; на
       «Комментариях», «Модерации» и «Друзьях» содержимое короче — и лишние
       248 px делились на три, раздувая шапку (210 → 293), полосу вкладок
       (40 → 123), кнопку «Редактировать профиль» (40 → 81) и саму активную
       вкладку (31 → 114). Строки должны держать свою высоту, а остаток —
       оставаться пустым внизу. */
    align-content: start;
}
.profile-loading { display: grid; gap: 10px; }
.profile-error { color: var(--red); font-size: 13px; margin: 0; }
.profile-help { color: var(--text2); font-size: 12px; margin: 0; }

/* --- Шапка --- */

.profile-head {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    gap: 18px;
    /* stretch (not start): the avatar has no fixed size of its own anymore —
       height:100% on .profile-head-ava below makes it match whatever height
       .profile-head-copy's content (name/handle/bio/counters) naturally
       takes, so its bottom edge lines up with that column, with the actions
       row (edit button) sitting below both via this grid's own `gap`. */
    align-items: stretch;
    padding-right: 44px;
    --profile-accent: var(--lime);
}

.profile-head-ava {
    width: auto;
    height: 100%;
    aspect-ratio: 1;
    min-width: 86px;
    min-height: 86px;
    /* Потолок обязателен, и вот почему. Колонка шапки — `auto`, её ширину
       задаёт max-content содержимого, а содержимое здесь <img>: при
       измерении max-content проценты на картинке не разрешаются, и в расчёт
       идёт СОБСТВЕННЫЙ размер файла. Аватарка 600×800 давала колонку в
       604 px, aspect-ratio делал квадрат такой же высоты, строка шапки
       распухала до 662 px — и всё, что лежит в тех же строках грида
       (кнопка «Редактировать профиль», вкладки), растягивалось следом.
       Высота брала своё и от .profile-head-copy: 100 % от раздутой строки.
       Проверено на 0.2b32 — там ровно те же 604×604, это не регрессия
       переноса модалок в .main, просто в узкой панели чата оно наконец
       перестало помещаться и полезло на имя. */
    max-width: 152px;
    max-height: 152px;
    border-radius: 26px;
    overflow: hidden;
    display: grid;
    place-items: center;
    background: rgba(255,255,255,.05);
    border: 2px solid var(--profile-accent);
    font-size: 30px;
    font-weight: 700;
    color: var(--profile-accent);
}

.profile-head-ava .avatar-img { width: 100%; height: 100%; object-fit: cover; }

.profile-name { margin: 0; font-size: 24px; line-height: 1.2; }
.profile-handle { color: var(--text2); font-size: 13px; margin-top: 2px; }

/* Bio, shown in the header in place of a separate "About" section/tab. */
.profile-bio-inline {
    margin-top: 8px;
    font-size: 14px;
    line-height: 1.5;
    color: var(--text);
    white-space: pre-wrap;
}

.profile-counters { display: flex; flex-wrap: wrap; gap: 16px; margin-top: 12px; }
.profile-counter { display: flex; align-items: baseline; gap: 5px; font-size: 13px; color: var(--text2); }
.profile-counter strong { font-size: 17px; color: var(--text); }

/* Sites/socials entered in the editor (.profile-links-editor below) — was
   saved and returned by the server all along, but never rendered anywhere
   until now. Same row as bio/counters, on every tab. */
.profile-links { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }
.profile-link-chip {
    display: inline-flex;
    align-items: center;
    max-width: 220px;
    padding: 5px 12px;
    border-radius: 999px;
    background: rgba(255,255,255,.04);
    border: 1px solid var(--border);
    color: var(--lime);
    font-size: 12px;
    text-decoration: none;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.profile-link-chip:hover { background: rgba(255,255,255,.08); border-color: var(--lime); }

.profile-head-actions {
    grid-column: 1 / -1;
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.profile-follow-btn.following { background: transparent; color: var(--lime); border: 1px solid var(--lime); }
.profile-friend-btn.is-friend { color: var(--lime); }

/* --- Вкладки --- */

.profile-tabs {
    display: flex;
    gap: 4px;
    flex-wrap: wrap;
    border-bottom: 1px solid var(--border);
    padding-bottom: 8px;
}

.profile-tab {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 14px;
    border-radius: 10px;
    border: none;
    background: transparent;
    color: var(--text2);
    font-size: 13px;
    cursor: pointer;
}

.profile-tab:hover { background: rgba(255,255,255,.04); color: var(--text); }
.profile-tab.active { background: var(--lime-dim); color: var(--lime); }

.profile-tab-badge {
    min-width: 18px;
    padding: 0 5px;
    border-radius: 999px;
    background: var(--lime);
    color: #0b0d10;
    font-size: 11px;
    font-weight: 700;
    line-height: 18px;
    text-align: center;
}

.profile-tab-body { min-height: 200px; }

.profile-policy-chip {
    padding: 5px 10px;
    border-radius: 999px;
    background: rgba(255,255,255,.04);
    border: 1px solid var(--border);
    font-size: 11px;
    color: var(--text2);
}
.profile-policy-chip strong { color: var(--text); }

/* --- Редактор ---
   Карточки повторяют язык .settings-card/.server-modal-card (та же рамка,
   градиентная подложка и тень), чтобы редактор профиля не выглядел отдельным
   от остального приложения экраном. */

.profile-editor { display: grid; gap: 16px; }

.profile-editor-section {
    position: relative;
    padding: 20px;
    display: grid;
    gap: 16px;
    border: 1px solid var(--border);
    border-radius: 18px;
    background:
        linear-gradient(180deg, rgba(255,255,255,.03), rgba(255,255,255,.015)),
        rgba(255,255,255,.02);
    box-shadow: 0 18px 48px rgba(0,0,0,.16);
}

.profile-editor-section-head { display: grid; gap: 4px; }

.profile-editor-kicker {
    color: var(--lime);
    font-size: 10px;
    font-weight: 900;
    text-transform: uppercase;
    letter-spacing: .14em;
}

.profile-editor-title {
    margin: 0;
    color: var(--text);
    font-size: 15px;
    font-weight: 900;
}

.profile-editor-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px;
}

.profile-field { display: grid; gap: 6px; font-size: 13px; }
.profile-field > span { color: var(--text2); font-size: 12px; }

.profile-field input[type="text"],
.profile-field input[type="url"],
.profile-field textarea {
    width: 100%;
    min-height: var(--control-h);
    padding: 12px 14px;
    border-radius: 12px;
    border: 1px solid var(--border);
    background: rgba(255,255,255,.03);
    color: var(--text);
    font: inherit;
    font-size: 13px;
    box-shadow: inset 0 1px 0 rgba(255,255,255,.04);
    transition: border-color .18s var(--ease-out), box-shadow .18s var(--ease-out);
}

.profile-field textarea { resize: vertical; min-height: 90px; }
.profile-field input:focus, .profile-field textarea:focus {
    outline: none;
    border-color: var(--lime);
    box-shadow: 0 0 0 3px var(--lime-dim);
}

.profile-field-color input[type="color"] {
    width: 100%;
    height: var(--control-h);
    padding: 2px;
    border-radius: 10px;
    border: 1px solid var(--border);
    background: rgba(255,255,255,.03);
    cursor: pointer;
}

.profile-avatar-editor { display: flex; align-items: center; gap: 14px; }
.profile-avatar-preview {
    width: 56px;
    height: 56px;
    border-radius: 18px;
    overflow: hidden;
    display: grid;
    place-items: center;
    background: rgba(255,255,255,.05);
}
.profile-avatar-preview .avatar-img { width: 100%; height: 100%; object-fit: cover; }

.profile-links-editor { display: grid; gap: 10px; }
/* Named areas rather than relying on DOM order + implicit auto-placement:
   the row mixes a spanning full-width element (url, on its own line on
   mobile) with narrow fixed-size ones (color swatch, remove button) whose
   auto-placement interacts with that span in ways that are easy to get
   wrong and hard to eyeball-verify. Naming each cell makes the desktop and
   mobile layouts below independently correct by construction instead of by
   accident of source order. */
.profile-link-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.6fr) auto auto;
    grid-template-areas: "label url color remove";
    gap: 8px;
    align-items: center;
}
.profile-link-row input[type="text"] { grid-area: label; }
.profile-link-row input[type="url"] { grid-area: url; }
.profile-link-row .profile-link-color-input { grid-area: color; }
.profile-link-row .profile-link-remove { grid-area: remove; }
.profile-link-row input {
    padding: 11px 13px;
    border-radius: 10px;
    border: 1px solid var(--border);
    background: rgba(255,255,255,.03);
    color: var(--text);
    font: inherit;
    font-size: 12px;
    transition: border-color .18s var(--ease-out);
}
.profile-link-row input:focus { outline: none; border-color: var(--lime); }

.profile-link-color-input {
    width: 34px;
    height: 34px;
    cursor: pointer;
    flex: 0 0 auto;
}

/* Квадрат, залитый цветом целиком, а не точка в середине кнопки.
   Мешали два независимых слоя:
   1) `.profile-link-row input` задаёт padding 11px/13px и по специфичности
      (0,1,1 против 0,1,0) побеждал собственное правило поля — в коробке
      34×34 на сам цвет оставалось 6×10 px. Отсюда селектор в две
      степени: `.profile-link-row .profile-link-color-input`.
   2) При `appearance: auto` WebKit рисует не заливку, а «колодец» со своей
      рамкой и отступами — их убирает только стилизация
      ::-webkit-color-swatch. Firefox — ::-moz-color-swatch. */
.profile-field-color input[type="color"],
.profile-link-row .profile-link-color-input {
    -webkit-appearance: none;
    appearance: none;
    padding: 0;
    border: 1px solid var(--border);
    border-radius: 10px;
    background: transparent;
    overflow: hidden;
}

.profile-field-color input[type="color"]::-webkit-color-swatch-wrapper,
.profile-link-row .profile-link-color-input::-webkit-color-swatch-wrapper {
    padding: 0;
}

.profile-field-color input[type="color"]::-webkit-color-swatch,
.profile-link-row .profile-link-color-input::-webkit-color-swatch {
    border: none;
    border-radius: 9px;
}

.profile-field-color input[type="color"]::-moz-color-swatch,
.profile-link-row .profile-link-color-input::-moz-color-swatch {
    border: none;
    border-radius: 9px;
}

.profile-link-remove {
    width: 34px;
    height: 34px;
    display: grid;
    place-items: center;
    border-radius: 10px;
    border: 1px solid var(--border);
    background: rgba(255,255,255,.04);
    color: var(--text2);
    cursor: pointer;
    flex: 0 0 auto;
    transition: border-color .16s var(--ease-out), background .16s var(--ease-out), color .16s var(--ease-out);
}
.profile-link-remove:hover { color: var(--red); border-color: rgba(255,77,109,.3); background: rgba(255,77,109,.12); }
.profile-link-remove .ui-icon { width: 14px; height: 14px; }

/* Ряд кнопок вместо системного <select> — активный вариант подсвечен
   тем же акцентным тонированием, что и .server-modal-nav-btn.active. */
.profile-audience-field { display: grid; gap: 9px; font-size: 13px; }
.profile-audience-field > span { color: var(--text2); font-size: 12px; }

.profile-audience-group { display: flex; flex-wrap: wrap; gap: 8px; }

.profile-audience-btn {
    min-height: 38px;
    padding: 0 16px;
    border: 1px solid var(--border);
    border-radius: 10px;
    background: rgba(255,255,255,.03);
    color: var(--text2);
    font-size: 12px;
    font-weight: 700;
    cursor: pointer;
    transition: border-color .16s var(--ease-out), background .16s var(--ease-out), color .16s var(--ease-out), transform .16s var(--ease-out);
}
.profile-audience-btn:hover { color: var(--text); background: rgba(255,255,255,.06); }
.profile-audience-btn:active { transform: translateY(1px); }
.profile-audience-btn.active {
    color: var(--text);
    border-color: rgba(var(--accent-rgb), .55);
    background: rgba(var(--accent-rgb), .14);
    box-shadow: inset 0 0 0 1px rgba(var(--accent-rgb), .18);
}

/* --- Комментарии --- */

.profile-comments { display: grid; gap: 16px; }
.profile-comment-composer { display: grid; gap: 8px; }
.profile-comment-composer textarea {
    width: 100%;
    min-height: 74px;
    padding: 11px 13px;
    border-radius: 14px;
    border: 1px solid var(--border);
    background: rgba(255,255,255,.03);
    color: var(--text);
    font: inherit;
    font-size: 13px;
    resize: vertical;
}
.profile-comment-composer textarea:focus { outline: none; border-color: var(--lime); }
.profile-comment-actions { display: flex; align-items: center; justify-content: space-between; gap: 10px; }

.profile-comment-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; }
.profile-comment { display: grid; grid-template-columns: 38px minmax(0, 1fr); gap: 10px; }

.profile-comment-ava {
    width: 38px;
    height: 38px;
    border-radius: 12px;
    overflow: hidden;
    display: grid;
    place-items: center;
    background: rgba(255,255,255,.05);
    font-size: 14px;
    font-weight: 700;
    color: var(--lime);
    cursor: pointer;
}
.profile-comment-ava .avatar-img { width: 100%; height: 100%; object-fit: cover; }

.profile-comment-body {
    padding: 10px 13px;
    border-radius: 14px;
    background: rgba(255,255,255,.03);
    border: 1px solid var(--border);
}
.profile-comment-head { display: flex; align-items: center; gap: 8px; margin-bottom: 4px; }
.profile-comment-author { font-size: 13px; font-weight: 600; cursor: pointer; }
.profile-comment-author:hover { color: var(--lime); }
.profile-comment-date { font-size: 11px; color: var(--text3); margin-right: auto; }
.profile-comment-text { margin: 0; font-size: 13px; line-height: 1.5; white-space: pre-wrap; word-break: break-word; }

/* --- Люди (друзья и заявки) --- */

.profile-friends { display: grid; gap: 22px; }
.profile-friends-block { display: grid; gap: 10px; }
.profile-friends-block h3 { margin: 0; font-size: 14px; color: var(--text2); font-weight: 600; }

.profile-invite { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px; }
.profile-invite input {
    padding: 10px 12px;
    border-radius: 12px;
    border: 1px solid var(--border);
    background: rgba(255,255,255,.03);
    color: var(--text);
    font: inherit;
    font-size: 13px;
}
.profile-invite input:focus { outline: none; border-color: var(--lime); }

.profile-people { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.profile-person {
    display: grid;
    grid-template-columns: 38px minmax(0, 1fr) auto;
    gap: 10px;
    align-items: center;
    padding: 8px 10px;
    border-radius: 14px;
    background: rgba(255,255,255,.03);
    border: 1px solid var(--border);
}
.profile-person-ava {
    width: 38px;
    height: 38px;
    border-radius: 12px;
    overflow: hidden;
    display: grid;
    place-items: center;
    background: rgba(255,255,255,.05);
    font-size: 14px;
    font-weight: 700;
    color: var(--lime);
    cursor: pointer;
}
.profile-person-ava .avatar-img { width: 100%; height: 100%; object-fit: cover; }
.profile-person-copy { display: grid; gap: 2px; min-width: 0; }
.profile-person-name { font-size: 13px; font-weight: 600; cursor: pointer; }
.profile-person-name:hover { color: var(--lime); }
.profile-person-note { font-size: 11px; color: var(--text2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.profile-person-actions { display: flex; gap: 6px; flex-wrap: wrap; }

/* --- Стена автографов (полностью векторная) --- */

.profile-wall { display: grid; gap: 12px; }

.autograph-toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.autograph-toolbar > .profile-error, .autograph-toolbar > .profile-help { flex-basis: 100%; }

.autograph-colors { display: flex; gap: 6px; }
.autograph-color {
    width: 24px;
    height: 24px;
    border-radius: 50%;
    border: 2px solid transparent;
    background: var(--swatch, #cbff00);
    cursor: pointer;
    padding: 0;
}
.autograph-color.active { border-color: var(--text); transform: scale(1.12); }

.autograph-width { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--text2); }
.autograph-width .settings-range { width: 110px; }
.autograph-tool-actions { display: flex; gap: 6px; flex-wrap: wrap; margin-left: auto; }

/* Соотношение сторон обязано совпадать с viewBox стены (WALL_W×WALL_H в
   autographs.js): вместе с preserveAspectRatio="none" это даёт точное и
   обратимое соответствие «пиксель указателя ↔ единица стены», без чего
   штрих ложился бы не туда, куда ведут рукой. */
.autograph-wall {
    position: relative;
    aspect-ratio: 1000 / 600;
    width: 100%;
    border-radius: 18px;
    overflow: hidden;
    border: 1px solid var(--border);
    background:
        radial-gradient(120% 100% at 50% 0%, rgba(203,255,0,.06), transparent 60%),
        rgba(255,255,255,.02);
}

.autograph-wall-svg { display: block; width: 100%; height: 100%; color: var(--text3); }
.autograph-wall.drawing { border-color: var(--lime); }
/* touch-action обязателен: без него первый же росчерк пальцем прокручивает
   страницу вместо рисования, а pointermove перестаёт приходить. */
.autograph-wall.drawing .autograph-wall-svg { cursor: crosshair; touch-action: none; }

.autograph-wall-empty-text { fill: var(--text3); font-size: 26px; }

.autograph-legend { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 8px; }
.autograph-legend li {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 10px;
    border-radius: 999px;
    background: rgba(255,255,255,.03);
    border: 1px solid var(--border);
    font-size: 11px;
}
.autograph-legend-author { color: var(--text); font-weight: 600; }
.autograph-legend-date { color: var(--text3); }

/* --- Модерация --- */

.profile-moderation { display: grid; gap: 12px; }
.moderation-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); }
.moderation-card {
    display: grid;
    gap: 10px;
    padding: 12px;
    border-radius: 16px;
    border: 1px solid var(--border);
    background: rgba(255,255,255,.03);
}
.moderation-preview {
    height: 120px;
    border-radius: 12px;
    background: rgba(255,255,255,.02);
    display: grid;
    place-items: center;
    overflow: hidden;
}
.autograph-preview-svg { width: 100%; height: 100%; }
.moderation-meta { display: flex; justify-content: space-between; gap: 8px; font-size: 11px; }
.moderation-author { font-weight: 600; }
.moderation-date { color: var(--text3); }
.moderation-actions { display: flex; gap: 6px; }
.moderation-actions button { flex: 1; }

/* Во всю ширину меню (отрицательные поля гасят падинг контейнера) — 
   вставленный по центру разделитель короче пунктов читается как ещё
   один элемент списка, а не как граница между группами. */
.peer-context-menu-sep { height: 1px; background: var(--menu-border); margin: 5px -6px; }

@media (max-width: 720px) {
    .profile-overlay { padding: 0; }
    .profile-modal { width: 100%; max-height: 100vh; height: 100%; border-radius: 0; }
    .profile-body { padding: 20px 16px 32px; }
    .profile-head { grid-template-columns: 1fr; justify-items: center; text-align: center; padding-right: 0; }
    /* Single-column stack here, so the avatar's height:100% trick (matching
       .profile-head-copy's height) has nothing to stretch against — pin it
       back to a fixed size instead of letting it collapse to near-zero. */
    .profile-head-ava { width: 86px; height: 86px; }
    .profile-head-copy { text-align: center; }
    .profile-counters { justify-content: center; }
    .profile-head-actions { justify-content: center; }
    .profile-link-row {
        grid-template-columns: minmax(0, 1fr) auto auto;
        grid-template-areas:
            "label color remove"
            "url url url";
    }
    .autograph-tool-actions { margin-left: 0; width: 100%; }
    .profile-editor-section { padding: 16px; }
    .profile-editor-row { grid-template-columns: 1fr; }
}

/* ════════════════════════════════════════════════════════════════════════
   DESIGN MODE PICKER (Settings → «Стиль оформления»)
   The three modes are mutually exclusive, so this is a radio group rendered
   as buttons (renderDesignModeSettings() in web/src/interface/prefs.js), not
   the checkbox the flat mode used to be.
   ════════════════════════════════════════════════════════════════════════ */

.design-mode-options {
    position: relative;
    z-index: 1;
    display: grid;
    gap: 10px;
}

.design-mode-option {
    display: grid;
    grid-template-columns: 56px minmax(0, 1fr) auto;
    align-items: center;
    gap: 14px;
    padding: 12px 14px;
    border: 1px solid var(--border);
    border-radius: 14px;
    background: rgba(255,255,255,.025);
    color: var(--text);
    text-align: left;
    cursor: pointer;
    transition: border-color .18s var(--ease-out), background .18s var(--ease-out), box-shadow .18s var(--ease-out), transform .18s var(--ease-out);
}

.design-mode-option:hover {
    background: rgba(255,255,255,.045);
    border-color: rgba(255,255,255,.16);
}

.design-mode-option:active {
    transform: translateY(1px);
}

.design-mode-option.active {
    border-color: rgba(var(--accent-rgb), .55);
    background: rgba(var(--accent-rgb), .09);
    box-shadow: inset 0 0 0 1px rgba(var(--accent-rgb), .18);
}

/* Tiny abstract mock of each mode: a top bar, a neutral row and an accent
   row — enough to read the difference (glow / matte / soft) at a glance
   without shipping three screenshots. */
.design-mode-preview {
    display: grid;
    align-content: center;
    gap: 4px;
    width: 56px;
    height: 42px;
    padding: 6px;
    border-radius: 10px;
    overflow: hidden;
    background: #0b0d11;
}

.design-mode-preview-bar,
.design-mode-preview-row {
    display: block;
    height: 6px;
    border-radius: 3px;
    background: rgba(255,255,255,.16);
}

.design-mode-preview-bar {
    width: 100%;
    height: 5px;
}

.design-mode-preview-row {
    width: 78%;
}

.design-mode-preview-row--accent {
    width: 58%;
    justify-self: end;
    background: rgb(var(--accent-rgb));
}

.design-mode-preview--classic {
    background:
        radial-gradient(circle at 18% 12%, rgba(var(--accent-rgb),.35), transparent 52%),
        linear-gradient(180deg, #12151b, #08090c);
}

.design-mode-preview--classic .design-mode-preview-row--accent {
    box-shadow: 0 0 8px rgba(var(--accent-rgb), .7);
}

.design-mode-preview--flat {
    background: #0c0e12;
}

.design-mode-copy {
    min-width: 0;
    display: grid;
    gap: 3px;
}

.design-mode-copy strong {
    color: var(--text);
    font-size: 13px;
    font-weight: 800;
}

.design-mode-copy small {
    color: var(--text2);
    font-size: 11px;
    line-height: 1.4;
}

.design-mode-note {
    flex: none;
    align-self: start;
    color: var(--text3);
    font-size: 10px;
    font-weight: 800;
    letter-spacing: .08em;
    text-transform: uppercase;
}

.design-mode-option.active .design-mode-note {
    color: var(--lime);
}

@media (max-width: 760px) {
    .design-mode-option {
        grid-template-columns: 44px minmax(0, 1fr);
        gap: 12px;
    }

    .design-mode-preview {
        width: 44px;
        height: 36px;
    }

    .design-mode-note {
        display: none;
    }
}


/* ════════════════════════════════════════════════════════════════════════
   КЕШ АССЕТОВ — режим, потолок и сводка обращений
   Разметку рисует renderCacheSettings() (web/src/interface/cache.js).
   Кнопки режимов повторяют геометрию .design-mode-option, но без превью:
   у режимов кеша нечего показывать картинкой, разница выражается словами.
   ════════════════════════════════════════════════════════════════════════ */

.cache-settings {
    display: grid;
    gap: 12px;
}

.cache-mode-options {
    display: grid;
    gap: 8px;
}

.cache-mode-option {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 14px;
    padding: 11px 13px;
    border: 1px solid var(--border);
    border-radius: 13px;
    background: rgba(255,255,255,.025);
    color: var(--text);
    text-align: left;
    cursor: pointer;
    transition: border-color .18s var(--ease-out), background .18s var(--ease-out), box-shadow .18s var(--ease-out), transform .18s var(--ease-out);
}

.cache-mode-option:hover {
    background: rgba(255,255,255,.045);
    border-color: rgba(255,255,255,.16);
}

.cache-mode-option:active { transform: translateY(1px); }

.cache-mode-option.active {
    border-color: rgba(var(--accent-rgb), .55);
    background: rgba(var(--accent-rgb), .09);
    box-shadow: inset 0 0 0 1px rgba(var(--accent-rgb), .18);
}

.cache-mode-copy {
    min-width: 0;
    display: grid;
    gap: 3px;
}

.cache-mode-copy strong { color: var(--text); font-size: 13px; font-weight: 800; }
.cache-mode-copy small { color: var(--text2); font-size: 11px; line-height: 1.4; }

.cache-mode-note {
    flex: none;
    align-self: start;
    color: var(--text3);
    font-size: 10px;
    font-weight: 800;
    letter-spacing: .08em;
    text-transform: uppercase;
}

.cache-mode-option.active .cache-mode-note { color: var(--lime); }

.cache-limit-field { gap: 6px; }

/* Полоса заполнения. Ширина ставится инлайном из посчитанного процента —
   это единственное значение здесь, зависящее от данных. */
.cache-usage-bar {
    height: 6px;
    border-radius: 3px;
    overflow: hidden;
    background: rgba(255,255,255,.07);
}

.cache-usage-bar > span {
    display: block;
    height: 100%;
    border-radius: 3px;
    background: rgb(var(--accent-rgb));
    transition: width .25s var(--ease-out);
}

.cache-usage-status { margin: 0; }

.cache-summary-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 12px;
}

.cache-summary-block {
    display: grid;
    gap: 6px;
    align-content: start;
    padding: 10px 12px;
    border: 1px solid var(--border);
    border-radius: 12px;
    background: rgba(255,255,255,.02);
}

.cache-kind-list,
.cache-top-list {
    display: grid;
    gap: 4px;
    margin: 0;
    padding: 0;
    list-style: none;
}

.cache-kind-row,
.cache-top-row {
    display: grid;
    align-items: baseline;
    gap: 8px;
    font-size: 11px;
    color: var(--text2);
}

.cache-kind-row { grid-template-columns: minmax(0, 1fr) auto; }
.cache-top-row { grid-template-columns: minmax(0, 1fr) auto auto; }

.cache-kind-name,
.cache-top-name {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--text);
}

.cache-kind-meta,
.cache-top-size { color: var(--text3); font-variant-numeric: tabular-nums; }

/* Вид записи перед именем: аватарка и карточка профиля одного человека
   называются одинаково, и без метки список читается как дубликаты. */
.cache-top-kind {
    display: inline-block;
    margin-right: 6px;
    padding: 0 5px;
    border-radius: 5px;
    background: rgba(255,255,255,.06);
    color: var(--text3);
    font-size: 9px;
    font-weight: 800;
    letter-spacing: .04em;
    text-transform: uppercase;
    vertical-align: 1px;
}

/* Счётчик обращений — то, чем этот список полезен: он объясняет, почему
   вытеснение выбирает именно эти файлы. Поэтому он акцентный, а не серый. */
.cache-top-hits {
    color: var(--lime);
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.cache-kind-row--empty,
.cache-top-row--empty {
    grid-template-columns: 1fr;
    color: var(--text3);
}

@media (max-width: 760px) {
    .cache-mode-note { display: none; }
    .cache-mode-option { grid-template-columns: minmax(0, 1fr); }
}


/* ════════════════════════════════════════════════════════════════════════
   МОДАЛЬНЫЕ СЛОИ НА ТЕЛЕФОНЕ — снова во весь экран
   Блок держится В КОНЦЕ файла намеренно. Базовые правила этих четырёх
   слоёв разбросаны по style.css, и часть из них (.profile-overlay, 8653)
   объявлена ПОЗЖЕ основного мобильного @media — оттуда переопределение
   не срабатывало вовсе: та же специфичность, кто ниже, тот и прав.
   Одно место в самом низу перекрывает их все, где бы они ни стояли.

   Почему на телефоне не absolute: там нет боковой панели рядом с чатом,
   ограничивать диалог нечем и незачем, а .main выше вьюпорта
   (min-height:100vh внутри строки грида) — absolute-слой оказался бы
   длиннее экрана.
   ════════════════════════════════════════════════════════════════════════ */
@media (max-width: 760px) {
    .profile-overlay,
    .server-overlay,
    .avatar-crop-overlay,
    .coin-transfer-modal {
        position: fixed;
        inset: 0;
    }
}

