        requests: apiRoute('/friends/requests'),
        request: (id) => apiRoute(`/friends/requests/${encodeURIComponent(id)}`),
    },
    coins: {
        balance: apiRoute('/coins/balance'),
        distribution: apiRoute('/coins/distribution'),
        transfer: apiRoute('/coins/transfer'),
    },
});

/**
 * ZaliInterface — весь клиентский UI. Здесь только каркас: конструктор и init().
 * Тело класса разложено по web/src/interface/ и подключается через ZaliMixin
 * (см. web/src/mixin.js). Порядок загрузки — web/src/manifest.json, группа
 * "interface"; тот же список читают харнессы scripts/*_doctor и bridge_check.sh.
 *
 * Добавляя функциональность, кладите метод в подходящую часть, а новый файл
 * впишите в манифест — больше нигде список файлов не продублирован.
 *
 * Карта частей (строк / методов — ориентировочно, счётчики не обновляются сами):
 *
 *   format.js               104 /  11  Экранирование, иконки, форматирование времени и дат.
 *   native_bridge.js        300 /  24  Мост к нативной оболочке: доступность, IPC, разрешения, трассировка.
 *   viewport.js             324 /  17  Окно прокрутки списка сообщений, класс производительности, якоря скролла.
 *   mobile.js               575 /  20  Мобильная раскладка, жесты навигации, переключение экранов.
 *   zalicoin.js             270 /  10  Экран ZaliCoin: баланс, распределение, переводы.
 *   prefs.js                452 /  39  Пользовательские настройки: тема, звук, устройства ввода/вывода, сегменты хаба.
 *   storage.js              405 /  31  Ключи localStorage, кэш сообщений, персист контактов.
 *   conversation_keys.js    762 /  44  Реестр ключей разговоров и облачный vault-снапшот.
 *   key_resolution.js       771 /  28  Разрешение ключа разговора, идентичность устройства, крипто-примитивы конвертов и vault.
 *   key_envelopes.js        749 /  21  Публикация/приём ключевых конвертов, доверие устройств.
 *   session.js              463 /  23  Сессия и токен, недавние аккаунты, снапшот здоровья звонка.
 *   outbox.js               632 /  25  Очередь неотправленных сообщений и её досылка.
 *   network_config.js       515 /  40  Сетевая конфигурация: API/WS адреса, ICE/TURN.
 *   servers_model.js        391 /  31  Модель серверов и ролей, работа с цветом.
 *   server_modal.js        1361 /  52  Модалка настроек сервера: роли, каналы, участники, инвайты.
 *   voice_transport.js      505 /  17  Голосовые комнаты и транспорт сигналинга.
 *   voice_media.js         1482 /  45  Захват микрофона/камеры/экрана, треки, индикаторы уровня.
 *   voice_negotiation.js    664 /  18  Жизненный цикл пира: offer/answer, рестарты, супервизор связи.
 *   voice_call.js           440 /  19  Управление звонком и записи о звонках.
 *   voice_signal.js         768 /   4  Обработка входящих voice_* сигналов и событий.
 *   voice_ui.js             396 /  10  Отрисовка голосовой панели, плиток и развёрнутого звонка.
 *   server_messages.js      700 /  15  Загрузка сообщений серверов/каналов, синхронизация активного разговора.
 *   avatars.js              771 /  31  Аватары и ассеты серверов: кэш, загрузка, кроппер, даунскейл.
 *   api.js                  198 /   8  HTTP-конвейер: заголовки, слоты параллелизма, apiFetch.
 *   auth.js                1157 /  31  Бутстрап сессии, вход/регистрация, контакты.
 *   attachments.js          349 /  24  Вложения, Tenor, предпросмотр медиа.
 *   message_render.js       861 /  29  Отрисовка тела сообщения, реакции, статусы.
 *   render_shell.js         460 /   9  Отрисовка списков контактов, хаба и серверов.
 *   updates.js              261 /  16  Встроенный апдейтер клиента.
 *   message_list.js         466 /   7  Окно сообщений, рендер списка, переключение чата.
 *   message_send.js         719 /  10  Отправка сообщений и приём в браузерном режиме.
 *   notifications.js        455 /  24  Мьюты, звуки, уведомления, бейдж непрочитанного.
 *   state_sync.js           529 /  15  Приём состояния от нативного слоя: пользователи, история, статус связи.
 *   message_edit.js         376 /  15  Ответы, редактирование и удаление сообщений.
 *   profiles.js             470 /  25  Профили людей: состояние, подписки, дружба, комментарии.
 *   profile_ui.js           520 /  20  Отрисовка профиля: шапка, вкладки, редактор, модерация.
 *   autographs.js           420 /  20  Векторная стена автографов: рисование, публикация, модерация.
 *   diagnostics.js          157 /   5  Журнал диагностики и голосовая телеметрия.
 *   events.js              1651 /  16  Привязка DOM-событий и инерция прокрутки.
 */
class ZaliInterface {
    constructor() {
        this.name = 'zali_interface';
        // Must run before ANY stored state is read below (message cache, conversation
        // keys, session, device identity) — the server database was reset at this
        // instant, so everything written before it refers to accounts, message ids and
        // key envelopes that no longer exist.
        this.localResetApplied = this.applyLocalDataResetIfNeeded();

        const stateSlices = window.ZaliStateSlices || {};
        /** @type {ZaliInterfaceState} */
        this.S = Object.assign(
            {},
            stateSlices.auth?.createState?.() || {},
            stateSlices.contacts?.createState?.() || {},
            stateSlices.messaging?.createState?.() || {},
            stateSlices.servers?.createState?.() || {},
        );
        // Профиль лежит отдельным срезом состояния — см. interface/profiles.js.
        this.S.profile = ZaliInterface.emptyProfileState;
        this.tenorCache = new Map();
        this.tenorPending = new Set();
        this.nativeAuthRequests = new Map();
        this.nativeRequests = new Map();
        this.avatarCache = new Map();
        this.avatarRequests = new Map();
        // Когда можно снова пробовать скачать то, что не скачалось —
        // см. ZALI_ASSET_RETRY_COOLDOWN_MS в interface/avatars.js.
        this.avatarRetryAt = new Map();
        this.avatarFetchSeq = new Map();
        this.serverAssetCache = new Map();
        this.serverAssetRequests = new Map();
        this.serverAssetRetryAt = new Map();
        this.serverAssetFetchSeq = new Map();
        // Постоянный кеш ассетов (interface/cache.js). Индекс сводок и счётчик
        // занятого места живут здесь, чтобы решение о вытеснении не читало диск;
        // сама база открывается лениво, первым обращением.
        this._cacheStats = new Map();
        this._cacheDirtyStats = new Set();
        this._cacheBytes = 0;
        this._cacheDb = null;
        this._cacheReady = null;
        this.colorWheelBindings = new Set();
        this.messageAnimSeen = new Set();
        this.mediaSizeCache = new Map();
        this.storageWarningSeen = new Set();
        this.reactionOptions = ['👍', '❤️', '😂', '😮', '😢', '🔥'];
        this.voiceSocketGeneration = 0;
        this.voiceSocketReconnectTimer = null;
        this.voiceSocketReconnectDelayMs = 1000;
        this.voiceSocketPingTimer = null;
        this.pendingMessagesScroll = null;
        this.pendingOutboxFlushTimer = null;
        this.sendWatchdogTimers = new Map();
        this.messageSyncTimer = null;
        this.energyMaintenanceBound = false;
        this.conversationSyncAt = new Map();
        this.conversationRefreshTimers = new Map();
        this.historyLoadSeq = 0;
        this.serverHistoryLoadSeq = new Map();
        this.messageScrollRaf = 0;
        this.messageRenderRaf = 0;
        this.sessionBootstrapInProgress = false;
        this.cloudVaultSyncTimer = 0;
        this.cloudVaultSyncInFlight = false;
        this.bridgeProtocol = window.__ZALI_BRIDGE_PROTOCOL__ || null;
        this.apiRoutes = window.ZaliApiRoutes || DefaultApiRoutes;
        this.clearLegacyKeyMaterial();
        this.S.auth.cloudVaultSyncEnabled = this.loadVaultCloudSyncEnabled();
        /** @type {ZaliMessageWindowState} */
        this.messageWindow = {
            conversationKey: '',
            start: 0,
            end: 0,
            avgHeight: 92,
        };
        this.postAuthSetupInFlight = false;
        this.postAuthSetupRunId = 0;
        this.lastNativeConversationKeySignature = '';
        this.voice = stateSlices.voice?.createState?.() || {
            supported: !!(window.RTCPeerConnection && navigator.mediaDevices && navigator.mediaDevices.getUserMedia),
            roomId: '',
            roomType: '',
            serverId: '',
            channelId: '',
            targetUser: '',
            inviter: '',
            status: 'idle',
            muted: false,
            deafened: false,
            expanded: false,
            activeSince: 0,
            barTimerInterval: 0,
            localStream: null,
            localStreamInFlight: null,
            micError: '',
            peerConnections: new Map(),
            remoteAudios: new Map(),
            participants: [],
            outgoingInvite: null,
            incomingInvite: null,
            socket: null,
            socketReady: false,
            callTrack: null,
            audioContext: null,
            playbackUnlocked: false,
            meterRaf: 0,
            meterLocal: null,
            meterRemote: new Map(),
            meterLevels: {
                local: 0,
                remote: 0,
            },
            traceLines: [],
        };
        this.audioPrefs = this.loadAudioPrefs();
        // Independent of this.voice.audioContext (which lives only for the
        // duration of an active call, see resetVoiceState) — UI sounds (message
        // chime, ringtone) need a context that survives across calls and can
        // fire while the window is minimized/unfocused. Created lazily and
        // unlocked on the first user gesture (see installSoundUnlock) since
        // AudioContext.resume() silently stays 'suspended' without one.
        this.sound = { ctx: null, bus: null, unlocked: false, ringTimer: null, ringing: false };
        this.installSoundUnlock();

        const cachedMessages = this.loadStoredMessageCache();
        this.S.chats = cachedMessages.chats || {};
        this.S.serverChats = cachedMessages.serverChats || {};
        this.S.mutedChats = this.loadStoredMutedChats();
        // Per-peer/per-channel "have we already synced this at least once this
        // session" markers. A history merge (catch-up sweep, active-conversation
        // refresh, etc.) only fires a notification for a NEWLY inserted message once
        // the peer/channel has been primed once already — otherwise the very first
        // history load (login, opening a new chat) would replay the entire backlog
        // as a flood of notifications instead of being silently primed as baseline.
        this._historyPrimedPeers = new Set();
        this._historyPrimedChannels = new Set();
        this.uiV2Enabled = this.loadUiV2Enabled();
        this.uiV2Segments = this.loadUiV2Segments();
        this.designMode = this.loadDesignMode();
        this.experimentalDesign = this.designMode === 'flat';
        this.voiceTraceEnabled = this.loadVoiceTraceEnabled();
    }

    init(loader) {
        this.bus = loader.bus;
        try {
            window.__ZALI_INTERFACE = this;
        } catch (e) {}
        this.S.navMode = this.loadStoredNavMode();

        // Register UI update commands on the bus
        const E = window.ZaliBusEvents || {};
        this.bus.registerCommand('zali_interface', E.RECEIVE_MESSAGE || 'receive_message', (data) => this.receiveMessage(data));
        this.bus.registerCommand('zali_interface', E.SET_USERS || 'set_users', (users) => this.setUsers(users));
        this.bus.registerCommand('zali_interface', E.SET_CONTACTS || 'set_contacts', (contacts) => this.setContacts(contacts));
        this.bus.registerCommand('zali_interface', E.SET_SESSION || 'set_session', (session) => this.setSession(session));
        this.bus.registerCommand('zali_interface', E.LOAD_HISTORY || 'load_history', (messages) => this.loadHistory(messages));
        this.bus.registerCommand('zali_interface', E.LOAD_SERVER_HISTORY || 'load_server_history', (payload) => this.loadServerHistory(payload));
        this.bus.registerCommand('zali_interface', E.REFRESH_AFTER_KEY || 'refresh_after_key', () => this.refreshAfterKey());
        this.bus.registerCommand('zali_interface', E.RETRY_PUBLISH_KEYS || 'retry_publish_keys', () => this.retryPublishConversationKeys({ reason: 'device_approved_push' }));
        // Scope-targeted, and deliberately NOT folded into the sweep above. Both
        // native shells used to route `key_republish_request` into retryPublishKeys()
        // on the theory that the sweep is a superset — it is not. The sweep publishes
        // each scope's ACTIVE key only, while the requester is asking precisely
        // because the messages it cannot read were encrypted under a key we have
        // since demoted to an `alt:` candidate. handleKeyRepublishRequest answers
        // with every candidate, so it is the only path that can deliver a historical
        // key — and on macOS/Windows it was unreachable, which is why "перебрано
        // ключей N, ни один не подошёл" survived every previous fix.
        this.bus.registerCommand('zali_interface', E.KEY_REPUBLISH_REQUEST || 'key_republish_request', (payload) => this.handleKeyRepublishRequest(payload));
        this.bus.registerCommand('zali_interface', E.SYNC_ACTIVE_CONVERSATION || 'sync_active_conversation', (payload) => this.syncConversationFromNative(payload));
        this.bus.registerCommand('zali_interface', E.SET_LOADING || 'set_loading', (on) => this.setLoading(on));
        this.bus.registerCommand('zali_interface', E.SET_CONNECTION_STATUS || 'set_connection_status', (connected) => this.setConnectionStatus(connected));
        this.bus.registerCommand('zali_interface', E.ON_SEND_SUCCESS || 'on_send_success', (clientId) => this.onSendSuccess(clientId));
        this.bus.registerCommand('zali_interface', E.ON_SEND_ERROR || 'on_send_error', (payload) => this.onSendError(payload));
        this.bus.registerCommand('zali_interface', E.REACTION_UPDATED || 'reaction_updated', (data) => this.onReactionUpdated(data));
        this.bus.registerCommand('zali_interface', E.MESSAGE_DELETED || 'message_deleted', (data) => this.onMessageDeleted(data));
        this.bus.registerCommand('zali_interface', E.MESSAGE_EDITED || 'message_edited', (data) => this.onMessageEdited(data));
        this.bus.registerCommand('zali_interface', E.AVATAR_UPDATED || 'avatar_updated', (data) => this.handleAvatarUpdated(data));
        this.bus.registerCommand('zali_interface', E.REALTIME_EVENT || 'realtime_event', (data) => this.dispatchRealtimeEvent(data));
        this.bus.registerCommand('zali_interface', E.TENOR_RESOLVED || 'tenor_resolved', (payload) => this.onTenorResolved(payload));
        this.bus.registerCommand('zali_interface', E.AUTH_RESPONSE || 'auth_response', (payload) => this.onNativeAuthResponse(payload));
        this.bus.registerCommand('zali_interface', E.NATIVE_RESPONSE || 'native_response', (payload) => this.onNativeResponse(payload));
        this.bus.registerCommand('zali_interface', E.ADD_LOG_ENTRY || 'add_log_entry', (data) => this.addLogEntry(data));
        this.bus.registerCommand('zali_interface', E.VOICE_EVENT || 'voice_event', (payload) => this.handleVoiceEvent(payload));
        this.bus.registerCommand('zali_interface', E.UPDATE_EVENT || 'update_event', (payload) => this.handleUpdateEvent(payload));
        this.bus.registerCommand('zali_interface', E.SCREEN_CAPTURE_FRAME || 'screen_capture_frame', (payload) => this.onNativeScreenCaptureFrame(payload));
        this.bus.registerCommand('zali_interface', E.SCREEN_CAPTURE_ERROR || 'screen_capture_error', (payload) => this.onNativeScreenCaptureError(payload));

        // Bind events after DOM is loaded
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', () => this.bindEvents());
        } else {
            this.bindEvents();
        }

        this.bootstrapSession();
        setTimeout(() => this.syncNativeConversationKeys(), 0);
        this.startEnergyAwareMaintenance();
        // Resolves the tier once and stamps data-perf-tier on <html> before the
        // first message list is built, so the very first render already uses the
        // right window size instead of re-windowing a frame later.
        this.perfTier();
        this.probeDisplayRefreshRate();
    }
}
window.ZaliInterface = ZaliInterface;


// --- MODULE: interface/format.js ---
// --- ZaliInterface: Экранирование, иконки, форматирование времени и дат. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
const ZALI_ESCAPE_MAP = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' };
const ZALI_ESCAPE_PATTERN = /[&<>"']/g;
const ZALI_ESCAPE_PROBE = /[&<>"']/;

ZaliMixin(ZaliInterface, class {

    // --- HTML Helper Utilities ---
    // One pass, not five. esc() is called several hundred times per render of the
    // message list and once per rendered character of every attachment URL that
    // still reaches it; five chained .replace() calls meant five full regex scans
    // of every string, and for anything without a special character all five
    // found nothing. Same output, same escapes, one traversal.
    esc(s) {
        if (s == null) return '';
        const value = String(s);
        // Fast path: the overwhelming majority of strings (names, timestamps,
        // ids, URLs) contain nothing to escape, and this test bails on the first
        // character that could matter instead of building a new string.
        // Two regexes on purpose: a /g/ one carries lastIndex across .test()
        // calls, which would make every second call lie.
        if (!ZALI_ESCAPE_PROBE.test(value)) return value;
        return value.replace(ZALI_ESCAPE_PATTERN, (ch) => ZALI_ESCAPE_MAP[ch]);
    }

    ruPlural(n, one, few, many) {
        const abs = Math.abs(Math.trunc(Number(n) || 0));
        const d10 = abs % 10;
        const d100 = abs % 100;
        if (d10 === 1 && d100 !== 11) return one;
        if (d10 >= 2 && d10 <= 4 && (d100 < 12 || d100 > 14)) return few;
        return many;
    }

    safeCssColor(value) {
        if (!value) return '';
        const trimmed = String(value).trim();
        if (/^(#[0-9a-fA-F]{3,8}|rgb\([^)]+\)|rgba\([^)]+\)|hsl\([^)]+\)|hsla\([^)]+\)|linear-gradient\([^<>"'`\n]+\)|[a-zA-Z]{2,30})$/.test(trimmed)) return trimmed;
        return '';
    }

    uiIcon(name, extraClass = '') {
        const cls = `ui-icon ui-icon-${this.esc(name)}${extraClass ? ` ${this.esc(extraClass)}` : ''}`;
        const attrs = `class="${cls}" viewBox="0 0 24 24" aria-hidden="true" focusable="false"`;
        const icons = {
            phone: `<svg ${attrs} fill="none"><path d="M7.3 4.75 9.2 8.9c.28.6.13 1.31-.36 1.75l-1.23 1.1c1.09 2.08 2.78 3.75 4.9 4.83l1.04-1.2a1.52 1.52 0 0 1 1.75-.39l4.05 1.74c.65.28 1.03.96.91 1.66l-.37 2.16c-.13.76-.8 1.3-1.57 1.25C9.4 21.25 2.77 14.68 2.22 5.75a1.5 1.5 0 0 1 1.26-1.58l2.18-.41c.69-.13 1.35.26 1.64.99Z" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/></svg>`,
            paperclip: `<svg ${attrs} fill="none"><path d="m8.15 12.55 5.42-5.42a3.26 3.26 0 0 1 4.62 4.61l-6.53 6.53a5.2 5.2 0 0 1-7.35-7.35l6.45-6.45a7.05 7.05 0 0 1 9.98 9.97l-6.52 6.53" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`,
            gear: `<svg ${attrs} fill="none"><path d="M10.4 3.25h3.2l.55 2.32c.54.2 1.05.5 1.5.87l2.27-.72 1.6 2.76-1.72 1.62c.05.3.08.6.08.9s-.03.6-.08.9l1.72 1.62-1.6 2.76-2.27-.72c-.45.37-.96.67-1.5.87l-.55 2.32h-3.2l-.55-2.32a5.78 5.78 0 0 1-1.5-.87l-2.27.72-1.6-2.76L6.2 11.9a5.6 5.6 0 0 1 0-1.8L4.48 8.48l1.6-2.76 2.27.72c.45-.37.96-.67 1.5-.87l.55-2.32Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><circle cx="12" cy="11" r="2.65" stroke="currentColor" stroke-width="1.8"/></svg>`,
            speaker: `<svg ${attrs} fill="none"><path d="M4 9.4v5.2h3.1l4.4 3.35V6.05L7.1 9.4H4Z" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/><path d="M15.2 8.25a5 5 0 0 1 0 7.5M17.85 5.6a8.75 8.75 0 0 1 0 12.8" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>`,
            hash: `<svg ${attrs} fill="none"><path d="M9.3 4.5 7.8 19.5M16.2 4.5l-1.5 15M4.75 9h14.5M4.25 15h14.5" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>`,
            close: `<svg ${attrs} fill="none"><path d="m7 7 10 10M17 7 7 17" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg>`,
            bell: `<svg ${attrs} fill="none"><path d="M12 3.5a4.2 4.2 0 0 0-4.2 4.2v2.3c0 .78-.28 1.53-.79 2.12l-1.2 1.4c-.7.82-.12 2.08.96 2.08h10.46c1.08 0 1.66-1.26.96-2.08l-1.2-1.4a3.2 3.2 0 0 1-.79-2.12V7.7A4.2 4.2 0 0 0 12 3.5Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><path d="M9.9 18.5a2.1 2.1 0 0 0 4.2 0" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>`,
            'bell-off': `<svg ${attrs} fill="none"><path d="M12 3.5a4.2 4.2 0 0 0-4.2 4.2v2.3c0 .78-.28 1.53-.79 2.12l-1.2 1.4c-.7.82-.12 2.08.96 2.08h10.46c1.08 0 1.66-1.26.96-2.08l-1.2-1.4a3.2 3.2 0 0 1-.79-2.12V7.7A4.2 4.2 0 0 0 12 3.5Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><path d="M9.9 18.5a2.1 2.1 0 0 0 4.2 0" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><path d="M4.5 4.5l15 15" stroke="currentColor" stroke-width="2.1" stroke-linecap="round"/></svg>`,
            // Пункты контекстных меню и действия над сообщением. Один
            // стиль со всеми иконками выше: 24×24, обводка 1.8, круглые
            // концы — иначе строка меню с иконкой выглядит склеенной из
            // двух разных наборов.
            user: `<svg ${attrs} fill="none"><circle cx="12" cy="8.4" r="3.6" stroke="currentColor" stroke-width="1.8"/><path d="M5 19.6c.55-3.4 3.45-5.7 7-5.7s6.45 2.3 7 5.7" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>`,
            'user-plus': `<svg ${attrs} fill="none"><circle cx="10.2" cy="8.4" r="3.6" stroke="currentColor" stroke-width="1.8"/><path d="M3.4 19.6c.5-3.3 3.3-5.7 6.8-5.7 1.05 0 2.05.18 2.95.52" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><path d="M17.6 14.1v5.9M14.65 17.05h5.9" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>`,
            eye: `<svg ${attrs} fill="none"><path d="M2.9 12S6.7 5.9 12 5.9 21.1 12 21.1 12 17.3 18.1 12 18.1 2.9 12 2.9 12Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><circle cx="12" cy="12" r="2.85" stroke="currentColor" stroke-width="1.8"/></svg>`,
            'eye-off': `<svg ${attrs} fill="none"><path d="M6.4 6.9C4.2 8.4 2.9 12 2.9 12s3.8 6.1 9.1 6.1c1.7 0 3.2-.63 4.45-1.5M9.6 5.35A8.9 8.9 0 0 1 12 5.9c5.3 0 9.1 6.1 9.1 6.1s-.86 1.4-2.35 2.85" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><path d="M9.98 9.98a2.85 2.85 0 0 0 4.04 4.04" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><path d="M4.6 4.6l14.8 14.8" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>`,
            reply: `<svg ${attrs} fill="none"><path d="M9.4 6.6 4.2 11.8l5.2 5.2" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"/><path d="M4.8 11.8h8.9a5.9 5.9 0 0 1 5.9 5.9v.9" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"/></svg>`,
            pencil: `<svg ${attrs} fill="none"><path d="M15.05 5.5 18.5 8.95" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><path d="m16.05 4.5 1.5 1.5a1.6 1.6 0 0 1 0 2.26L9.4 16.4l-3.4 1.1 1.1-3.4 8.14-8.15a1.6 1.6 0 0 1 2.26 0Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><path d="M4.9 20.3h14.2" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>`,
            trash: `<svg ${attrs} fill="none"><path d="M4.9 6.9h14.2" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><path d="M9.7 6.9V5.5a1.4 1.4 0 0 1 1.4-1.4h1.8a1.4 1.4 0 0 1 1.4 1.4v1.4" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><path d="m6.8 6.9.75 11.5a1.6 1.6 0 0 0 1.6 1.5h5.7a1.6 1.6 0 0 0 1.6-1.5l.75-11.5" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/></svg>`,
        };
        return icons[name] || '';
    }

    channelKindIcon(kind, extraClass = '') {
        return this.normalizeChannelKind(kind) === 'voice'
            ? this.uiIcon('speaker', extraClass)
            : this.uiIcon('hash', extraClass);
    }

    fmtTime(iso) {
        if (!iso) return '';
        try { return new Date(iso).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}); }
        catch(e) { return ''; }
    }

    // Numbers are handled explicitly, not as an afterthought: the browser
    // receive path stores `unpacked.timestamp * 1000`, i.e. a number of
    // milliseconds, while history rows carry an ISO string. Date.parse() of a
    // number is NaN, so a value-based comparator that only parsed strings would
    // silently sort every browser-delivered message to the epoch.
    messageTimestampValue(value) {
        if (typeof value === 'number') return Number.isFinite(value) ? value : 0;
        const ts = Date.parse(value || '');
        return Number.isFinite(ts) ? ts : 0;
    }

    // Comparator for chronological message order. Exists so the sort sites stop
    // writing `new Date(a.timestamp) - new Date(b.timestamp)`, which allocated
    // two Date objects per comparison — tens of thousands of them per history
    // merge, all thrown away immediately.
    compareMessagesByTime(a, b) {
        return this.messageTimestampValue(a?.timestamp) - this.messageTimestampValue(b?.timestamp);
    }

    messageHoverTimeLabel(msg) {
        const iso = msg?.timestamp || '';
        const time = this.fmtTime(iso);
        if (!time) return '';
        const date = this.fmtDate(iso);
        return date ? `${date}, ${time}` : time;
    }

    messageInlineTimeLabel(msg) {
        return this.fmtTime(msg?.timestamp || '');
    }

    // Sidebar sorting calls this once per contact on every renderContacts(), so a
    // full scan of every conversation was O(contacts × messages) per sidebar paint
    // — tens of thousands of Date parses per incoming message on a busy account.
    // Messages are appended chronologically, so the newest timestamp lives at the
    // tail; scan backwards over a small bounded tail to stay tolerant of the slight
    // out-of-order that reconciliation can leave behind, and stop there.
    conversationLastMessageAt(peer) {
        const msgs = Array.isArray(this.S.chats?.[peer]) ? this.S.chats[peer] : [];
        const TAIL_SCAN = 24;
        let lastTs = 0;
        let scanned = 0;
        for (let i = msgs.length - 1; i >= 0 && scanned < TAIL_SCAN; i -= 1, scanned += 1) {
            const ts = this.messageTimestampValue(msgs[i]?.timestamp);
            if (ts > lastTs) lastTs = ts;
        }
        return lastTs;
    }

    fmtDate(iso) {
        if (!iso) return '';
        try {
            const messageDate = new Date(iso), now = new Date();
            const yesterday = new Date(); yesterday.setDate(yesterday.getDate()-1);
            if (messageDate.toDateString() === now.toDateString())       return 'Сегодня';
            if (messageDate.toDateString() === yesterday.toDateString()) return 'Вчера';
            return messageDate.toLocaleDateString('ru-RU',{day:'numeric',month:'long'});
        } catch(e) { return ''; }
    }
});


// --- MODULE: interface/native_bridge.js ---
// --- ZaliInterface: Мост к нативной оболочке: доступность, IPC, разрешения, трассировка. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    nativeBridge() {
        return window.__ZALI_NATIVE || null;
    }

    hasNativeBridge() {
        return !!this.nativeBridge()?.available;
    }

    nativeSupports(capability) {
        return !!this.nativeBridge()?.supports?.[capability];
    }

    // Native shells (macOS WKWebView, Windows WebView2) either silently swallow
    // target="_blank" navigation or try to load it inside the app's own webview
    // — there is no separate "browser" for it to land in. Routes the click
    // through the native bridge instead, which hands it to the OS's configured
    // default browser (NSWorkspace.shared.open / ShellExecuteW). Returns false
    // (and does nothing) in plain-browser/PWA mode, where target="_blank"
    // already does the right thing on its own.
    openExternalLink(url) {
        const href = String(url || '').trim();
        if (!/^https?:\/\//i.test(href)) return false;
        if (!this.nativeSupports('openExternalUrl')) return false;
        return this.postNativeMessage({ type: NativeMessageTypes.OPEN_EXTERNAL_URL, url: href });
    }

    isStandalonePwa() {
        return window.matchMedia?.('(display-mode: standalone)')?.matches
            || window.navigator?.standalone === true;
    }

    isIosSafariBrowserTab() {
        if (this.hasNativeBridge() || this.isStandalonePwa()) return false;
        const ua = window.navigator?.userAgent || '';
        const isIos = /iphone|ipad|ipod/i.test(ua)
            || (ua.includes('Macintosh') && navigator.maxTouchPoints > 1);
        const isSafari = /safari/i.test(ua) && !/crios|fxios|edgios|opios/i.test(ua);
        return isIos && isSafari;
    }

    urlBase64ToUint8Array(base64) {
        const padding = '='.repeat((4 - (base64.length % 4)) % 4);
        const base64Safe = (base64 + padding).replace(/-/g, '+').replace(/_/g, '/');
        const raw = atob(base64Safe);
        const output = new Uint8Array(raw.length);
        for (let i = 0; i < raw.length; i += 1) output[i] = raw.charCodeAt(i);
        return output;
    }

    // Asks for OS notification permission. Deliberately separate from (and ahead of)
    // the Web Push subscription: showBrowserNotification() needs only this permission,
    // so gating it behind a configured VAPID keypair left a server without
    // VAPID_PUBLIC_KEY/VAPID_PRIVATE_KEY with no browser notifications whatsoever —
    // not even the local ones that work fine with no push service involved.
    async ensureNotificationPermission() {
        if (this.hasNativeBridge()) return false;
        if (typeof Notification === 'undefined') return false;
        try {
            if (Notification.permission === 'default') {
                await Notification.requestPermission();
            }
        } catch (e) {
            this.trace(`ensureNotificationPermission failed: ${e?.message || e}`);
        }
        return Notification.permission === 'granted';
    }

    async subscribeWebPush() {
        if (this.hasNativeBridge()) return;
        if (!('serviceWorker' in navigator)) return;
        if (!this.S.session?.token) return;
        const granted = await this.ensureNotificationPermission();
        if (!('PushManager' in window)) return;
        if (!granted) return;
        try {
            const keyRes = await fetch(this.apiUrl('/api/push/vapid-public-key'));
            if (!keyRes.ok) return;
            const { publicKey } = await keyRes.json();
            if (!publicKey) return;

            const registration = await navigator.serviceWorker.ready;
            let subscription = await registration.pushManager.getSubscription();
            if (!subscription) {
                subscription = await registration.pushManager.subscribe({
                    userVisibleOnly: true,
                    applicationServerKey: this.urlBase64ToUint8Array(publicKey),
                });
            }
            await this.apiFetch('/api/push/subscribe', {
                method: 'POST',
                body: JSON.stringify(subscription.toJSON()),
            });
            this.trace('subscribeWebPush ok');
        } catch (e) {
            this.trace(`subscribeWebPush failed: ${e?.message || e}`);
        }
    }

    initA2hsBanner() {
        if (!this.isIosSafariBrowserTab()) return;
        if (localStorage.getItem('zali_a2hs_dismissed') === '1') return;
        const banner = document.getElementById('a2hsBanner');
        const text = document.getElementById('a2hsBannerText');
        const closeBtn = document.getElementById('a2hsBannerClose');
        if (!banner || !text || !closeBtn) return;
        text.innerHTML = 'Установите <b>ZaliMessenger</b> на экран «Домой»: нажмите <b>Поделиться</b>&nbsp;↑ внизу экрана, затем «На экран «Домой»».';
        banner.classList.add('visible');
        closeBtn.addEventListener('click', () => {
            banner.classList.remove('visible');
            localStorage.setItem('zali_a2hs_dismissed', '1');
        });
    }

    setKey(key) {
        if (this.bus?.send) {
            return this.bus.send('zali_styler:set_key', key);
        }
        return false;
    }

    isWindowsNativeAuth() {
        const transport = this.nativeBridge()?.transport;
        return transport === 'ipc' || transport === 'webview2';
    }

    hasNativeAvatarBridge() {
        // 'android' входит сюда наравне с остальными, и это не расширение
        // возможностей, а починка: Android объявляет avatarFetch и обрабатывает
        // UPLOAD_AVATAR_REQUEST / DELETE_AVATAR_REQUEST у себя в мосте — просто эта
        // проверка его не пускала, и обработчики никогда не вызывались. Загрузка
        // уходила в браузерный фолбэк с FormData, то есть мимо моста, из
        // `file://`-документа с `Origin: null`, который сервер отвергает по CORS.
        // Итог: поставить или снять аватар с телефона было нельзя вообще.
        const transport = this.nativeBridge()?.transport;
        return transport === 'ipc' || transport === 'webview2' || transport === 'webkit' || transport === 'android';
    }

    startEnergyAwareMaintenance() {
        if (!this.energyMaintenanceBound) {
            this.energyMaintenanceBound = true;
            const onVisibilityChange = () => {
                if (document.hidden) {
                    this.stopVoiceMeterLoop();
                    // Счётчики обращений копятся в памяти и уходят на диск по
                    // таймеру (см. interface/cache.js). Уход в фон — последний
                    // момент, когда таймер ещё точно сработает: дальше его
                    // душит браузер, а на мобильных вкладку могут и выгрузить,
                    // и тогда кеш забудет, чем пользовались весь сеанс.
                    void this.flushCacheStats();
                    return;
                }
                this.refreshVisibleAvatars();
                this.syncActiveConversation({ force: !this.nativeSupports('sendMessage') });
                if (this.voice.roomId || this.voice.localStream || this.voice.peerConnections.size > 0) {
                    this.ensureVoiceMeterLoop();
                    // Timers were throttled while hidden, so the voice socket's own
                    // ping is overdue and a link that died meanwhile hasn't been
                    // noticed yet. Probe now instead of waiting out the next tick.
                    this.probeVoiceSocketLiveness();
                }
            };
            document.addEventListener('visibilitychange', onVisibilityChange);
            window.addEventListener('focus', onVisibilityChange);
            // Debounced message-cache saves must land before the page goes away.
            window.addEventListener('pagehide', () => { this.flushTrace(); this.flushPendingMessageCacheSave(); void this.flushCacheStats(); });
            window.addEventListener('beforeunload', () => { this.flushTrace(); this.flushPendingMessageCacheSave(); void this.flushCacheStats(); });
            window.addEventListener('error', () => this.flushTrace());
        }

        this.scheduleAvatarRefreshPolling();
        this.scheduleConversationSyncPolling();
    }

    scheduleAvatarRefreshPolling() {
        if (this.avatarRefreshTimer) {
            clearTimeout(this.avatarRefreshTimer);
            this.avatarRefreshTimer = null;
        }

        const delay = document.hidden ? 60 * 60 * 1000 : 15 * 60 * 1000;
        this.avatarRefreshTimer = setTimeout(() => {
            this.avatarRefreshTimer = null;
            if (!document.hidden) {
                this.refreshVisibleAvatars();
            }
            this.scheduleAvatarRefreshPolling();
        }, delay);
    }

    scheduleConversationSyncPolling() {
        if (this.messageSyncTimer) {
            clearTimeout(this.messageSyncTimer);
            this.messageSyncTimer = null;
        }

        const hasNativeWs = this.nativeSupports('sendMessage');
        const delay = document.hidden || hasNativeWs ? 5 * 60 * 1000 : 15 * 1000;
        this.messageSyncTimer = setTimeout(() => {
            this.messageSyncTimer = null;
            this.syncActiveConversation({ force: !document.hidden && !hasNativeWs });
            this.scheduleConversationSyncPolling();
        }, delay);
    }

    postNativeMessage(payload) {
        const bridge = this.nativeBridge();
        if (!bridge || typeof bridge.postMessage !== 'function') return false;
        if (!this.validateNativePayload(payload)) return false;
        return !!bridge.postMessage(payload);
    }

    validateNativePayload(payload) {
        if (!payload || typeof payload !== 'object') {
            console.error('[bridge] Invalid native payload:', payload);
            return false;
        }

        const type = String(payload.type || '').trim();
        if (!type) {
            console.error('[bridge] Native payload missing type:', payload);
            return false;
        }

        if (!this.bridgeProtocol) {
            return true;
        }

        const schema = this.bridgeProtocol?.messages?.[type];
        if (!schema) {
            console.error('[bridge] Unknown native message type:', type);
            return false;
        }

        const fields = Array.isArray(schema.fields) ? schema.fields : [];
        if (fields.length > 0 && typeof console !== 'undefined' && console.warn) {
            const missing = fields.filter((field) => !(field in payload));
            if (missing.length > 0) {
                console.warn('[bridge] Missing fields for', type, ':', missing);
            }
        }

        return true;
    }

    // Every console.log is mirrored to zali-debug.log through the native bridge on
    // the macOS/iOS shells, so each trace used to cost a synchronous IPC hop. The
    // hot paths (history batches, per-message decrypt, key resolution) emit these in
    // bursts, which showed up as stutter. Coalesce a frame's worth of traces into one
    // console call — same lines, same order, one hop.
    trace(message) {
        const line = `[ZALI][WEB] ${message}`;
        this._traceBuffer = this._traceBuffer || [];
        this._traceBuffer.push(line);
        if (this._traceBuffer.length >= 64) {
            this.flushTrace();
            return;
        }
        if (this._traceFlushScheduled) return;
        this._traceFlushScheduled = true;
        const schedule = typeof requestAnimationFrame === 'function'
            ? requestAnimationFrame
            : (cb) => setTimeout(cb, 16);
        schedule(() => {
            this._traceFlushScheduled = false;
            this.flushTrace();
        });
    }

    flushTrace() {
        const buffer = this._traceBuffer;
        if (!buffer || buffer.length === 0) return;
        this._traceBuffer = [];
        try {
            console.log(buffer.length === 1 ? buffer[0] : buffer.join('\n'));
        } catch (e) {}
    }

    // Per-call correlation ID for apiFetch — logged locally and sent as the
    // X-Request-ID header, which the server echoes back and tags every one of
    // its own log lines for that request with. `grep request_id=<id>` across
    // both the browser console and the server log then shows one request's
    // entire lifecycle end to end, instead of guessing which server-side log
    // line matches which client-side action.
    newRequestId() {
        return (window.crypto && window.crypto.randomUUID)
            ? window.crypto.randomUUID()
            : `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
    }

    nowMs() {
        return (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
    }

    async timeStage(label, fn) {
        const t0 = this.nowMs();
        try {
            return await fn();
        } finally {
            const ms = Math.round(this.nowMs() - t0);
            this.addLogEntry({ type: ms > 1500 ? 'WARN' : 'INFO', msg: `⏱ ${label}: ${ms} мс`, ts: new Date().toLocaleTimeString() });
        }
    }

    myName() {
        return this.S.session?.username || '';
    }
});


// --- MODULE: interface/viewport.js ---
// --- ZaliInterface: Окно прокрутки списка сообщений, класс производительности, якоря скролла. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    requestMessagesScroll(position = 'bottom') {
        this.pendingMessagesScroll = position === 'top' ? 'top' : 'bottom';
    }

    resetMessageWindow() {
        this.messageWindow = {
            conversationKey: '',
            start: 0,
            end: 0,
            count: 0,
            useWindow: false,
            avgHeight: this.messageWindow?.avgHeight || 92,
        };
    }

    scheduleMessagesRender() {
        this.scheduleRenderMessages();
    }

    // Any scrollTop we assign ourselves fires a scroll event a frame later. Without
    // this marker that event was indistinguishable from the user scrolling, so it
    // cancelled the queued "open at the bottom" of a chat we had just switched to —
    // leaving the new conversation parked at an arbitrary offset.
    markProgrammaticScroll() {
        this._programmaticScrollUntil = (typeof performance !== 'undefined' ? performance.now() : Date.now()) + 200;
    }

    isProgrammaticScroll() {
        const now = typeof performance !== 'undefined' ? performance.now() : Date.now();
        return now <= Number(this._programmaticScrollUntil || 0);
    }

    onMessagesScroll() {
        const box = document.getElementById('msgs');
        if (!box) return;
        if (!this.isProgrammaticScroll()) {
            this.pendingMessagesScroll = null;
            this._bottomIntent = false;
        }
        if (this.messageScrollRaf) return;
        this.messageScrollRaf = requestAnimationFrame(() => {
            this.messageScrollRaf = 0;
            const msgs = this.getCurrentMessages();
            const conversationKey = this.S.navMode === 'servers'
                ? this.currentServerChatKey()
                : String(this.S.current || '').trim();
            const nextWindow = this.computeMessageWindow(msgs, box, {
                conversationChanged: conversationKey !== (this.messageWindow?.conversationKey || ''),
                stickToBottom: this.isMessagesNearBottom(box),
            });
            const current = this.messageWindow || {};
            if (
                current.conversationKey === conversationKey &&
                current.start === nextWindow.start &&
                current.end === nextWindow.end &&
                current.count === msgs.length &&
                (!!current.useWindow) === (!!nextWindow.useWindow)
            ) {
                return;
            }
            this.scheduleRenderMessages();
        });
    }

    computeMessageWindow(msgs, box, { conversationChanged = false, stickToBottom = false } = {}) {
        const total = Array.isArray(msgs) ? msgs.length : 0;
        const baseAvg = Math.max(56, Math.min(160, Number(this.messageWindow?.avgHeight || 92)));
        // Windowing threshold by tier. Every mounted bubble costs layout, paint and
        // a share of the blurred panel it sits inside, so a budget phone starts
        // virtualising sooner than a desktop does. Purely a cost knob: the spacers
        // below reproduce the exact scroll geometry of the unmounted rows, so the
        // list looks and scrolls identically no matter where the threshold sits.
        const tier = this.perfTier();
        const windowThreshold = tier === 'weak' ? 100 : tier === 'mid' ? 140 : 180;
        if (total <= windowThreshold || !box) {
            return {
                useWindow: false,
                start: 0,
                end: total,
                topSpacer: 0,
                bottomSpacer: 0,
                avgHeight: baseAvg,
            };
        }

        const viewportCount = Math.max(18, Math.ceil(Math.max(1, box.clientHeight) / baseAvg) + 8);
        // Overscan is deliberately NOT cut hard on weak devices. It is what keeps a
        // fast fling from outrunning the render and exposing bare spacer — trimming
        // it to save paint would trade a frame-rate win for visible blank gaps on
        // exactly the devices least able to refill them. 0.55/24 is a modest trim,
        // still well over a screenful either side of the viewport.
        const overscanFactor = tier === 'weak' ? 0.55 : 0.7;
        const overscanFloor = tier === 'weak' ? 24 : 30;
        const overscan = Math.max(overscanFloor, Math.floor(viewportCount * overscanFactor));
        const windowSize = Math.min(total, viewportCount + overscan * 2);
        const nearTop = box.scrollTop <= baseAvg * 4;
        const nearBottom = this.isMessagesNearBottom(box, baseAvg * 2);

        let start = Math.max(0, Math.floor(box.scrollTop / baseAvg) - overscan);
        let end = Math.min(total, start + windowSize);

        if (conversationChanged || stickToBottom || nearBottom) {
            start = Math.max(0, total - windowSize);
            end = total;
        } else if (nearTop) {
            start = 0;
            end = Math.min(total, windowSize);
        }

        if (end - start < windowSize) {
            if (start === 0) {
                end = Math.min(total, windowSize);
            } else if (end === total) {
                start = Math.max(0, total - windowSize);
            }
        }

        return {
            useWindow: true,
            start,
            end,
            topSpacer: start * baseAvg,
            bottomSpacer: Math.max(0, (total - end) * baseAvg),
            avgHeight: baseAvg,
        };
    }

    // Frame-rate tiering.
    //
    // What the display can do and what the device can afford per frame are two
    // different facts, and both matter: a 120 Hz panel on a budget phone still
    // misses frames if we ask it to lay out a thousand off-screen nodes, while a
    // fast desktop pinned to a 60 Hz panel gains nothing from extra headroom.
    //
    // Hard rule for everything keyed off this: the tier may only scale work the
    // user cannot see — how many *off-screen* message rows stay mounted. It must
    // never change a colour, a size, a blur, a shadow or a duration, so the
    // rendered result is byte-identical across tiers and only the cost differs.
    perfTier() {
        if (this._perfTier) return this._perfTier;
        const nav = typeof navigator !== 'undefined' ? navigator : {};
        const cores = Number(nav.hardwareConcurrency || 0);
        const memory = Number(nav.deviceMemory || 0);
        // A coarse primary pointer is the most reliable "this is a phone/tablet"
        // signal available to us; UA sniffing is not.
        const coarsePointer = typeof window.matchMedia === 'function'
            && window.matchMedia('(pointer: coarse)').matches;
        let tier;
        if (!coarsePointer && (cores === 0 || cores >= 8)) {
            tier = 'high';
        } else if ((memory && memory <= 3) || (cores && cores <= 4)) {
            tier = 'weak';
        } else {
            tier = coarsePointer ? 'mid' : 'high';
        }
        this._perfTier = tier;
        try {
            document.documentElement.dataset.perfTier = tier;
        } catch (e) {}
        this.trace(`perf tier=${tier} cores=${cores || '?'} memory=${memory || '?'} coarse=${coarsePointer}`);
        return tier;
    }

    // Measured refresh ceiling, from real rAF cadence rather than assumption —
    // a 120 Hz phone whose panel is currently running at 60 (battery saver, an
    // OEM policy that ignored our request) must be treated as 60. Diagnostics
    // only today: nothing renders differently because of it, it exists so the
    // frame ceiling is observable in the log instead of guessed at.
    probeDisplayRefreshRate() {
        if (this._displayHzProbeStarted) return;
        this._displayHzProbeStarted = true;
        if (typeof requestAnimationFrame !== 'function') return;
        const samples = [];
        let last = 0;
        const tick = (now) => {
            if (last) samples.push(now - last);
            last = now;
            if (samples.length < 20) {
                requestAnimationFrame(tick);
                return;
            }
            const sorted = samples.slice().sort((a, b) => a - b);
            const median = sorted[Math.floor(sorted.length / 2)] || 16.7;
            this._displayHz = Math.round(1000 / median);
            this.trace(`perf displayHz≈${this._displayHz} tier=${this.perfTier()}`);
        };
        requestAnimationFrame(tick);
    }

    mobileLayoutQuery() {
        if (!this._mobileLayoutQuery && typeof window.matchMedia === 'function') {
            this._mobileLayoutQuery = window.matchMedia('(max-width: 760px)');
        }
        return this._mobileLayoutQuery || null;
    }

    isMobileLayout() {
        if (typeof window.matchMedia === 'function') {
            return window.matchMedia('(max-width: 760px)').matches;
        }
        return !!this.mobileLayoutQuery()?.matches;
    }

    applyPendingMessagesScroll(box) {
        if (!box || !this.pendingMessagesScroll) return;
        const target = this.pendingMessagesScroll;
        this.pendingMessagesScroll = null;
        this.markProgrammaticScroll();
        if (target === 'bottom') {
            box.scrollTop = box.scrollHeight;
            this.pinToBottomAfterLayout(box);
        } else {
            // Jumping to the top is an explicit "don't follow the bottom" intent —
            // otherwise the next viewport change would re-pin and undo it.
            this._bottomIntent = false;
            box.scrollTop = 0;
        }
    }

    // Height is not final at the moment we scroll: the virtual window's spacers are
    // sized from an average message height that this very render recalibrates, and
    // avatars/images/fonts settle a frame later. Scrolling once therefore left the
    // newly opened chat a screen or two above the last message. Re-pin on the next
    // frame — once, and only while nothing else has claimed the scroll position.
    pinToBottomAfterLayout(box) {
        if (!box) return;
        // A real user scroll clears this intent (see onMessagesScroll), so the
        // correction can never fight someone who has started reading history.
        this._bottomIntent = true;
        if (this._pinBottomRaf) return;
        this._pinBottomRaf = requestAnimationFrame(() => {
            this._pinBottomRaf = 0;
            if (!this._bottomIntent || this.pendingMessagesScroll) return;
            if (box.scrollHeight - (box.scrollTop + box.clientHeight) <= 1) return;
            this.markProgrammaticScroll();
            box.scrollTop = box.scrollHeight;
        });
    }

    captureMessageScrollAnchor(box) {
        if (!box) return null;
        const boxRect = box.getBoundingClientRect?.();
        if (!boxRect) return null;
        const nodes = box.querySelectorAll('.msg[data-message-id]');
        if (!nodes.length) return null;
        // Binary search on offsetTop for the first node at or below the viewport top,
        // instead of walking the list front-to-back measuring every node. Nodes are in
        // document order, so offsetTop is monotonic.
        const viewportTop = box.scrollTop;
        let lo = 0;
        let hi = nodes.length - 1;
        let candidate = 0;
        while (lo <= hi) {
            const mid = (lo + hi) >> 1;
            const node = nodes[mid];
            if (node.offsetTop + node.offsetHeight >= viewportTop) {
                candidate = mid;
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }
        for (let i = candidate; i < nodes.length; i += 1) {
            const node = nodes[i];
            const messageId = String(node.dataset?.messageId || '').trim();
            if (!messageId) continue;
            const rect = node.getBoundingClientRect?.();
            if (!rect || rect.bottom < boxRect.top) continue;
            if (rect.top > boxRect.bottom) break;
            return {
                messageId,
                topOffset: rect.top - boxRect.top,
            };
        }
        return null;
    }

    restoreMessageScrollAnchor(box, anchor) {
        if (!box || !anchor?.messageId) return false;
        // Selector lookup instead of materialising every .msg node and comparing
        // datasets in JS — this runs inside the render path on every scroll-preserving
        // update.
        let node = null;
        try {
            const escaped = (typeof CSS !== 'undefined' && typeof CSS.escape === 'function')
                ? CSS.escape(anchor.messageId)
                : null;
            if (escaped) node = box.querySelector(`.msg[data-message-id="${escaped}"]`);
        } catch (e) {
            node = null;
        }
        if (!node) {
            const nodes = Array.from(box.querySelectorAll('.msg[data-message-id]'));
            node = nodes.find(item => String(item.dataset?.messageId || '').trim() === anchor.messageId) || null;
        }
        if (!node) return false;
        const boxRect = box.getBoundingClientRect?.();
        const rect = node.getBoundingClientRect?.();
        if (!boxRect || !rect) return false;
        box.scrollTop += (rect.top - boxRect.top) - Number(anchor.topOffset || 0);
        return true;
    }

    // Called when the viewport itself changes size (rotation, window resize, the
    // mobile keyboard). A resize does not move scrollTop, so a list that was pinned
    // to its newest message silently ends up scrolled away from it.
    repinMessagesAfterViewportChange() {
        if (!this._bottomIntent) return;
        const box = document.getElementById('msgs');
        if (!box) return;
        this.pinToBottomAfterLayout(box);
    }

    isMessagesNearBottom(box, threshold = 56) {
        if (!box) return true;
        return (box.scrollHeight - (box.scrollTop + box.clientHeight)) <= threshold;
    }
});


// --- MODULE: interface/mobile.js ---
// --- ZaliInterface: Мобильная раскладка, жесты навигации, переключение экранов. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    // Drives .sidebar's parked/unparked position as a plain inline style —
    // mirroring setMobileNavProgress()'s #viewChat/.mobile-dock handling —
    // always writing an explicit value, never clearing the inline style to
    // fall back on the CSS rule's own translateY(115%). That fallback was
    // tried first and measured unreliable: after clearing the inline
    // override, getComputedStyle kept reporting the identity matrix
    // indefinitely instead of transitioning to the cascade's parked value —
    // even a full second later, nothing had moved. Writing both states
    // explicitly (like #viewChat already does) sidesteps that fallback path
    // entirely; only the transition duration is still gated by class
    // (transition: none while becoming visible, so the reveal is instant;
    // the class removed, so the .12s park plays once the caller sets the
    // parked value).
    setMobileListParked(parked) {
        const sidebar = document.querySelector('.sidebar');
        if (sidebar) sidebar.style.transform = parked ? 'translateY(115%)' : 'translateY(0)';
    }

    setMobileSidebarOpen(open, { animate = true } = {}) {
        const isOpen = !!open;
        document.body?.classList.toggle('mobile-sidebar-open', isOpen);
        // isOpen === list/picker screen visible (--mnav 0); closed === chat screen visible (--mnav 1)
        if (isOpen) {
            document.body?.classList.add('mobile-list-visible');
            this.setMobileListParked(false);
        }
        this.setMobileNavProgress(isOpen ? 0 : 1, { animate });
        if (!isOpen) {
            this.scheduleMobileListPark();
        }
        const btn = document.getElementById('mobileMenuBtn');
        if (btn) btn.setAttribute('aria-expanded', String(isOpen));
        const backdrop = document.getElementById('mobileBackdrop');
        if (backdrop) backdrop.hidden = !isOpen;
        return isOpen;
    }

    // Parks the list back down (translateY, out of the way of the input
    // area) only once the chat has actually finished covering it — never
    // while any part of the list might still be visible on screen.
    scheduleMobileListPark() {
        const chatEl = document.getElementById('viewChat');
        if (!chatEl) return;
        let done = false;
        const attemptPark = () => {
            // A back-swipe may have started (and re-shown the list) after this
            // park was scheduled but before its 340ms fallback fired — at drag
            // activation progress is still ~1, so the progress check alone
            // would yank the list out from under the user's finger.
            if (document.body?.classList.contains('mobile-nav-dragging')) return;
            // The window may have grown to the desktop layout between scheduling
            // and firing; parking there would translate the always-visible
            // desktop sidebar off the bottom of the screen.
            if (!this.isMobileLayout()) return;
            if (this.currentMobileNavProgress() >= 0.98 && !document.body?.classList.contains('mobile-sidebar-open')) {
                document.body?.classList.remove('mobile-list-visible');
                // Class removal switches .sidebar back to its normal .12s
                // transition; writing the parked value now (not clearing to
                // fall back on it) animates the park — harmless either way
                // visually since the chat is already fully covering it.
                this.setMobileListParked(true);
            }
        };
        const finish = () => {
            if (done) return;
            done = true;
            chatEl.removeEventListener('transitionend', onEnd);
            attemptPark();
        };
        const onEnd = (e) => {
            if (e.target === chatEl && e.propertyName === 'transform') finish();
        };
        chatEl.addEventListener('transitionend', onEnd);
        // Fallback in case the transform didn't actually change (transitionend
        // never fires) or something else interrupts the transition.
        setTimeout(finish, 340);
    }

    // Drives the mobile list<->chat push navigation. p=0 shows the fullscreen
    // chat/server picker, p=1 shows the chat. animate=false is used while a
    // touch drag is in progress so the transform tracks the finger with zero
    // transition lag.
    //
    // #viewChat/.mobile-dock's transform is written here directly as an
    // inline style (plain px/percent), NOT via a CSS custom property + calc()
    // — a `calc(var(--mnav))`-driven transform was observed to permanently
    // stick at its pre-change value after any transition:none phase ended,
    // regardless of how the re-enable was sequenced (classList timing,
    // forced reflow, rAF, setTimeout). A literal, non-var()-dependent inline
    // transform value does not have this problem.
    setMobileNavProgress(p, { animate = true } = {}) {
        const body = document.body;
        if (!body) return;
        const clamped = Math.max(0, Math.min(1, Number(p) || 0));
        this._mobileNavProgress = clamped;
        body.classList.toggle('mobile-nav-instant', !animate);
        const vc = document.getElementById('viewChat');
        if (vc) vc.style.transform = `translateX(${((1 - clamped) * 100).toFixed(4)}%)`;
        const dock = document.querySelector('.mobile-dock');
        if (dock) dock.style.transform = `translate(-50%, ${(clamped * 140).toFixed(4)}%)`;
        this.notifyNativeMobileNav(clamped, animate);
    }

    // The Android shell hides the web .mobile-dock and draws its own native bar
    // over the WebView, so that bar can't see the transform above — it has to be
    // told, or it keeps sitting on top of the chat's message input. `animate`
    // separates a finger-tracked drag (native must follow instantly, frame by
    // frame) from a committed transition (native runs its own ~240ms slide).
    // Re-reports the current position from the DOM. Needed wherever the position
    // itself didn't change but what it *means* for the native bar did:
    // setMobileNavProgress() only fires on an actual move, so a session that
    // lands straight on a screen (guest login opening the chat placeholder, a
    // restored conversation, the login overlay closing) would never report
    // anything and the bar would stay wherever it was — parked over the message
    // input, or floating over a chat. Derived from the DOM, not from
    // _mobileNavProgress, which is undefined until the first navigation.
    syncNativeMobileNav() {
        if (!this.nativeSupports('mobileNav')) return;
        // Never yank the bar out from under a finger mid-swipe.
        if (document.body?.classList.contains('mobile-nav-dragging')) return;
        const listVisible = !!document.body?.classList.contains('mobile-sidebar-open');
        this.notifyNativeMobileNav(listVisible ? 0 : this.currentMobileNavProgress(), true);
    }

    notifyNativeMobileNav(progress, animate) {
        if (!this.nativeSupports('mobileNav')) return;
        // Only the chat screen wants the bar gone. Settings/Хаб/ZaliCoin close
        // the mobile sidebar too — which drives progress to 1 — but they are
        // full screens the user navigates *between* with that very bar, so
        // report 0 for them regardless of the nav transform.
        // The login overlay covers whichever view is active underneath (normally
        // the chat one) — leave the bar alone there, as it was before.
        const authUp = !!document.getElementById('authOverlay')?.classList.contains('visible');
        const chatScreen = !authUp
            && !!document.getElementById('viewChat')?.classList.contains('active');
        const value = chatScreen ? (Number(progress) || 0) : 0;
        const flag = !!animate;
        // Какая секция активна сейчас. Нативная панель (Android) рисуется поверх
        // вебвью и прячет веб-док, поэтому подсветку своей активной вкладки она
        // взять неоткуда не может: её собственный `selected` — это локальное
        // состояние, меняющееся только от тапа по ней самой. А в Хаб и Настройки
        // можно уйти и другим путём (сегмент-контрол внутри настроек), после чего
        // подсветка начинала врать. Считается ровно теми же условиями, что и
        // класс .active на кнопках веб-дока в syncMobileChrome().
        const section = this.activeMobileNavSection();
        // Drag frames arrive at display rate; only the visible steps are worth
        // a bridge hop.
        if (this._lastNativeNavProgress != null
            && Math.abs(value - this._lastNativeNavProgress) < 0.01
            && flag === this._lastNativeNavAnimate
            && section === this._lastNativeNavSection) return;
        this._lastNativeNavProgress = value;
        this._lastNativeNavAnimate = flag;
        this._lastNativeNavSection = section;
        this.postNativeMessage({
            type: NativeMessageTypes.MOBILE_NAV_PROGRESS,
            progress: value,
            animate: flag,
            section,
        });
    }

    /** 'chats' | 'servers' | 'hub' | 'settings' — источник истины для подсветки
     * и веб-дока, и нативной панели. */
    activeMobileNavSection() {
        if (document.getElementById('viewSettings')?.classList.contains('active')) return 'settings';
        if (document.getElementById('viewHub')?.classList.contains('active')) return 'hub';
        return this.S.navMode === 'servers' ? 'servers' : 'chats';
    }

    currentMobileNavProgress() {
        return typeof this._mobileNavProgress === 'number' ? this._mobileNavProgress : 1;
    }

    // Interactive back-swipe: dragging from the left edge of the open chat
    // drags it to the right, revealing the fullscreen picker underneath
    // (mirror of the forward transition driven by setMobileSidebarOpen).
    setupMobileNavGestures() {
        const chatEl = document.getElementById('viewChat');
        if (!chatEl || chatEl.__mobileSwipeNavBound) return;
        chatEl.__mobileSwipeNavBound = true;

        const EDGE_ZONE = 28;
        const DRAG_ACTIVATE = 8;
        let tracking = false;
        let dragging = false;
        let startX = 0;
        let startY = 0;
        let viewportWidth = 1;
        let velocity = 0;
        let lastT = 0;
        let lastDx = 0;

        const reset = () => {
            tracking = false;
            dragging = false;
            velocity = 0;
            lastT = 0;
            lastDx = 0;
        };

        chatEl.addEventListener('touchstart', (e) => {
            if (!this.isMobileLayout() || this.currentMobileNavProgress() < 0.98) return;
            const touch = e.touches[0];
            if (!touch || touch.clientX > EDGE_ZONE) return;
            tracking = true;
            dragging = false;
            startX = touch.clientX;
            startY = touch.clientY;
            viewportWidth = window.innerWidth || 1;
        }, { passive: true });

        chatEl.addEventListener('touchmove', (e) => {
            if (!tracking) return;
            const touch = e.touches[0];
            if (!touch) return;
            const dx = touch.clientX - startX;
            const dy = touch.clientY - startY;
            if (!dragging) {
                if (Math.abs(dy) > Math.abs(dx) + 4) { reset(); return; }
                if (dx < DRAG_ACTIVATE) return;
                dragging = true;
                document.body?.classList.add('mobile-nav-dragging');
                // Unpark the list — see setMobileListParked() — so it's
                // sitting at Y=0 as the chat starts moving: the reveal must
                // look like the chat sliding off the list on the left, not
                // the list rising from below.
                document.body?.classList.add('mobile-list-visible');
                this.setMobileListParked(false);
            }
            if (dragging) {
                if (e.cancelable) e.preventDefault();
                const now = (e.timeStamp || Date.now());
                if (lastT && now > lastT) velocity = (dx - lastDx) / (now - lastT); // px/ms
                lastT = now;
                lastDx = dx;
                const progress = Math.max(0, Math.min(1, 1 - dx / viewportWidth));
                this.setMobileNavProgress(progress, { animate: false });
            }
        }, { passive: false });

        const finish = () => {
            if (!tracking) return;
            document.body?.classList.remove('mobile-nav-dragging');
            if (dragging) {
                // Commit on a fast flick even when the drag is short — matching
                // native back-swipes — otherwise fall back to the 40% position.
                const flicked = velocity > 0.45;
                const openList = flicked || this.currentMobileNavProgress() < 0.6;
                this.setMobileSidebarOpen(openList, { animate: true });
            }
            reset();
        };

        chatEl.addEventListener('touchend', finish);
        chatEl.addEventListener('touchcancel', finish);
    }

    // True when sliding the chat screen back in would actually show something:
    // the chat view is the active one AND it has a conversation loaded. Without
    // this the forward-swipe would drag in an empty "Выберите чат" placeholder.
    hasOpenMobileConversation() {
        if (!document.getElementById('viewChat')?.classList.contains('active')) return false;
        if (this.S?.navMode === 'servers') return !!this.currentServerChatKey();
        return !!String(this.S?.current || '').trim();
    }

    // Interactive forward-swipe: dragging left anywhere on the list screen pulls
    // the last open chat back in from the right — the mirror of the back-swipe
    // above, and the reason dialog rows no longer own a horizontal gesture of
    // their own (swipe-to-delete was removed; the row's × button deletes).
    //
    // Bound on .sidebar rather than #viewChat because while the list is showing
    // it is the sidebar that's under the finger — #viewChat is parked off-screen
    // to the right at that point.
    setupMobileForwardNavGesture() {
        const sidebarEl = document.querySelector('.sidebar');
        if (!sidebarEl || sidebarEl.__mobileForwardSwipeBound) return;
        sidebarEl.__mobileForwardSwipeBound = true;

        const DRAG_ACTIVATE = 8;
        let tracking = false;
        let dragging = false;
        let startX = 0;
        let startY = 0;
        let viewportWidth = 1;
        let velocity = 0;
        let lastT = 0;
        let lastDx = 0;

        const reset = () => {
            tracking = false;
            dragging = false;
            velocity = 0;
            lastT = 0;
            lastDx = 0;
        };

        sidebarEl.addEventListener('touchstart', (e) => {
            if (!this.isMobileLayout()) return;
            // Only from the settled list screen, and only when there is a chat
            // to come back to.
            if (this.currentMobileNavProgress() > 0.02) return;
            if (!this.hasOpenMobileConversation()) return;
            const touch = e.touches[0];
            if (!touch) return;
            // Anything that owns horizontal dragging itself (text fields, the
            // horizontally scrolling server rail) keeps its gesture.
            if (e.target?.closest?.('input, textarea, [contenteditable="true"], .server-rail, .mode-switch')) return;
            tracking = true;
            dragging = false;
            startX = touch.clientX;
            startY = touch.clientY;
            viewportWidth = window.innerWidth || 1;
        }, { passive: true });

        sidebarEl.addEventListener('touchmove', (e) => {
            if (!tracking) return;
            const touch = e.touches[0];
            if (!touch) return;
            const dx = touch.clientX - startX;
            const dy = touch.clientY - startY;
            if (!dragging) {
                // Vertical intent wins — never fight the dialog list's scroll.
                if (Math.abs(dy) > Math.abs(dx) + 4) { reset(); return; }
                if (dx > -DRAG_ACTIVATE) return;
                dragging = true;
                document.body?.classList.add('mobile-nav-dragging');
                // The list must stay put at Y=0 for the whole drag — the chat
                // slides in over it, the list never moves.
                document.body?.classList.add('mobile-list-visible');
                this.setMobileListParked(false);
            }
            if (dragging) {
                if (e.cancelable) e.preventDefault();
                const now = (e.timeStamp || Date.now());
                if (lastT && now > lastT) velocity = (dx - lastDx) / (now - lastT); // px/ms
                lastT = now;
                lastDx = dx;
                const progress = Math.max(0, Math.min(1, -dx / viewportWidth));
                this.setMobileNavProgress(progress, { animate: false });
            }
        }, { passive: false });

        const finish = () => {
            if (!tracking) return;
            document.body?.classList.remove('mobile-nav-dragging');
            if (dragging) {
                // Mirror of the back-swipe: a fast flick commits regardless of
                // distance, otherwise the 40%-travelled position decides.
                const flicked = velocity < -0.45;
                const openChat = flicked || this.currentMobileNavProgress() > 0.4;
                this.setMobileSidebarOpen(!openChat, { animate: true });
                // A drag that ended over a dialog row must not also count as a
                // tap on it (which would open that chat instead of the last one).
                this._suppressNextSidebarClick = true;
                setTimeout(() => { this._suppressNextSidebarClick = false; }, 400);
            }
            reset();
        };

        sidebarEl.addEventListener('touchend', finish);
        sidebarEl.addEventListener('touchcancel', finish);
        sidebarEl.addEventListener('click', (e) => {
            if (!this._suppressNextSidebarClick) return;
            this._suppressNextSidebarClick = false;
            e.preventDefault();
            e.stopPropagation();
        }, true);
    }

    // Raises the message input above the on-screen keyboard on mobile by
    // exposing the keyboard inset as a CSS var; style.css shifts
    // #viewChat .input-area/.msgs by it.
    setupMobileKeyboardAvoidance() {
        const vv = window.visualViewport;
        if (!vv || this._mobileKeyboardBound) return;
        this._mobileKeyboardBound = true;
        const apply = () => {
            if (!this.isMobileLayout()) {
                document.body?.style.setProperty('--kbd-inset', '0px');
                return;
            }
            const inset = Math.max(0, (window.innerHeight - vv.height - vv.offsetTop));
            document.body?.style.setProperty('--kbd-inset', `${Math.round(inset)}px`);
            // The keyboard opening/closing resizes the message list under a fixed
            // scrollTop, which pushed the newest message off-screen exactly when the
            // user was about to reply to it. Re-pin, but only if we were the ones
            // holding the view at the bottom.
            this.repinMessagesAfterViewportChange();
        };
        vv.addEventListener('resize', apply);
        vv.addEventListener('scroll', apply);
        apply();
    }

    // Mobile touch gestures, delegated on the persistent containers (#msgs /
    // #contacts / #serverChannelList) so they survive the innerHTML re-renders
    // those lists do.
    //
    //  • Long-press a message  → opens the existing reaction menu.
    //  • Long-press a contact  → opens the contact context menu (профиль,
    //    подписка, заявка в друзья, глушилка, громкость собеседника).
    //  • Long-press a channel  → глушилка канала.
    //
    // Всё это на десктопе висит на `contextmenu`, которого на тач-устройствах
    // просто нет: браузеры его либо не шлют, либо шлют непредсказуемо, а iOS
    // вместо него показывает собственное системное меню. Долгое нажатие для
    // сообщений было сделано ещё тогда, а для контактов и каналов — нет, и
    // комментарий выше про «#contacts» описывал намерение, а не код. То есть
    // всё меню контакта было с телефона недостижимо в принципе.
    //
    // Dialog rows deliberately have NO horizontal gesture of their own: a
    // left-swipe on the list screen belongs to the forward navigation gesture
    // (setupMobileForwardNavGesture → return to the last open chat). Deleting a
    // dialog is the row's own × button (.contact-remove), which the mobile
    // stylesheet used to hide in favour of swipe-to-reveal-Delete.
    setupMobileTouchGestures() {
        const msgsEl = document.getElementById('msgs');
        if (msgsEl) {
            this.bindMobileLongPress(msgsEl, '.msg[data-message-id]', (msgEl, x, y) => {
                const id = msgEl.getAttribute('data-message-id');
                if (id) this.showReactionMenu(msgEl, id, x, y);
            });
        }

        const contactsEl = document.getElementById('contacts');
        if (contactsEl) {
            this.bindMobileLongPress(contactsEl, '.contact', (row, x, y) => {
                if (!row.dataset.name) return;
                this.openContactContextMenu(row.dataset.name, x, y);
            });
        }

        const channelsEl = document.getElementById('serverChannelList');
        if (channelsEl) {
            this.bindMobileLongPress(channelsEl, '.server-channel[data-channel-id]', (btn) => {
                if (btn.getAttribute('data-channel-kind') === 'voice') return;
                const sid = btn.getAttribute('data-server-id');
                const cid = btn.getAttribute('data-channel-id');
                if (sid && cid) this.toggleMuteChannel(sid, cid);
            });
        }
    }

    /**
     * Долгое нажатие с делегированием на постоянном контейнере.
     *
     * @param {HTMLElement} container контейнер, переживающий перерисовки списка
     * @param {string} selector       что считать «строкой» внутри него
     * @param {(el: HTMLElement, x: number, y: number) => void} onLongPress
     */
    bindMobileLongPress(container, selector, onLongPress) {
        if (!container || container.__mobileLongPressBound) return;
        container.__mobileLongPressBound = true;

        const LONG_PRESS_MS = 420;
        const MOVE_CANCEL = 10;
        let timer = null;
        let startX = 0;
        let startY = 0;
        let held = null;
        let fired = false;

        const cancelPress = () => {
            if (timer) { clearTimeout(timer); timer = null; }
            if (held) { held.classList.remove('press-hold'); held = null; }
        };

        container.addEventListener('touchstart', (e) => {
            if (!this.isMobileLayout()) return;
            const touch = e.touches[0];
            const target = e.target?.closest?.(selector);
            if (!touch || !target) return;
            fired = false;
            startX = touch.clientX;
            startY = touch.clientY;
            held = target;
            target.classList.add('press-hold');
            timer = setTimeout(() => {
                fired = true;
                onLongPress(target, startX, startY);
                if (navigator.vibrate) { try { navigator.vibrate(12); } catch (err) { /* no haptics */ } }
                cancelPress();
            }, LONG_PRESS_MS);
        }, { passive: true });

        container.addEventListener('touchmove', (e) => {
            const touch = e.touches[0];
            if (!touch || !timer) return;
            if (Math.abs(touch.clientX - startX) > MOVE_CANCEL || Math.abs(touch.clientY - startY) > MOVE_CANCEL) cancelPress();
        }, { passive: true });

        container.addEventListener('touchend', cancelPress);
        container.addEventListener('touchcancel', cancelPress);

        // Долгое нажатие по строке диалога иначе доигрывалось обычным кликом: меню
        // открывалось и тут же уезжало вместе с переключением чата. Перехват в фазе
        // погружения, до делегированного обработчика в events.js.
        container.addEventListener('click', (e) => {
            if (!fired) return;
            fired = false;
            e.preventDefault();
            e.stopPropagation();
        }, true);
    }

    syncMobileChrome() {
        const isMobile = this.isMobileLayout();
        document.body?.classList.toggle('is-mobile-layout', isMobile);

        // The mobile push-nav drives .sidebar / #viewChat with inline transforms
        // (see setMobileListParked / setMobileNavProgress). Those are meaningless
        // on desktop and actively harmful — a parked translateY(115%) pushes the
        // always-visible desktop sidebar off-screen — so clear them on the way out.
        if (!isMobile) {
            const sidebar = document.querySelector('.sidebar');
            if (sidebar) sidebar.style.transform = '';
            const viewChat = document.getElementById('viewChat');
            if (viewChat) viewChat.style.transform = '';
            document.body?.classList.remove('mobile-list-visible', 'mobile-nav-instant', 'mobile-nav-dragging');
        }

        const dock = document.getElementById('mobileDock');
        if (dock) {
            dock.classList.toggle('visible', isMobile);
        }

        if (isMobile) this.syncNativeMobileNav();

        // Одна функция на обе панели — веб-док и нативную: разъехаться им теперь
        // негде, потому что подсветка считается в одном месте.
        const section = this.activeMobileNavSection();
        const chatsBtn = document.getElementById('mobileChatsBtn');
        const serversBtn = document.getElementById('mobileServersBtn');
        const hubBtn = document.getElementById('mobileHubBtn');
        const settingsBtn = document.getElementById('mobileSettingsBtn');

        if (chatsBtn) chatsBtn.classList.toggle('active', section === 'chats');
        if (serversBtn) serversBtn.classList.toggle('active', section === 'servers');
        if (hubBtn) hubBtn.classList.toggle('active', section === 'hub');
        if (settingsBtn) settingsBtn.classList.toggle('active', section === 'settings');

        const mobileMenuBtn = document.getElementById('mobileMenuBtn');
        if (mobileMenuBtn) {
            mobileMenuBtn.classList.toggle('active', !!document.body?.classList.contains('mobile-sidebar-open'));
        }

        const backdrop = document.getElementById('mobileBackdrop');
        if (backdrop) backdrop.hidden = !(isMobile && document.body?.classList.contains('mobile-sidebar-open'));
    }

    closeMobileSidebar() {
        this.setMobileSidebarOpen(false);
    }

    openMobileSidebar() {
        this.setMobileSidebarOpen(true);
    }

    toggleMobileSidebar(force = null) {
        const next = force == null ? !document.body?.classList.contains('mobile-sidebar-open') : !!force;
        return this.setMobileSidebarOpen(next);
    }

    // The sidebar (contact list, mode-switch, server/channel list) stays visible
    // and clickable across every top-level view — Hub, ZaliCoin, Settings — not
    // just the chat screen. Before this, picking a conversation from there while
    // one of those was open silently updated S.current/activeServer/activeChannel
    // and re-rendered #msgs behind the scenes, but #viewChat itself stayed
    // display:none: the click looked like it did nothing at all. Called by
    // switchChat/setActiveServer/setActiveChannel; guarded so re-selecting the
    // already-open conversation from the chat view itself doesn't replay
    // #viewChat's .24s enter animation on every call.
    ensureChatViewOpen() {
        if (document.getElementById('viewChat')?.classList.contains('active')) return;
        this.openChatView();
    }

    // showList=true lands on the mobile list/picker screen instead of the
    // chat screen — pass it when the caller is about to show the list right
    // after, so we settle on the final state in one step instead of closing
    // then reopening the sidebar (which used to flash the chat screen before
    // sliding back, because renderHubSegmentNav()'s layout reads in between
    // forced the browser to commit the intermediate transform).
    openChatView({ showList = false } = {}) {
        const cv = document.getElementById('viewChat');
        const hv = document.getElementById('viewHub');
        const sv = document.getElementById('viewSettings');
        const zv = document.getElementById('viewZaliCoin');
        if (sv) sv.classList.remove('active');
        if (hv) hv.classList.remove('active');
        if (zv) zv.classList.remove('active');
        if (cv) cv.classList.add('active');
        this.setMobileSidebarOpen(showList);
        this.renderServerToolbar();
        this.renderHubSegmentNav();
        this.syncMobileChrome();
    }

    openSettingsView() {
        const cv = document.getElementById('viewChat');
        const hv = document.getElementById('viewHub');
        const sv = document.getElementById('viewSettings');
        const zv = document.getElementById('viewZaliCoin');
        this.collapseActiveCallView();
        if (cv) cv.classList.remove('active');
        if (hv) hv.classList.remove('active');
        if (zv) zv.classList.remove('active');
        if (sv) sv.classList.add('active');
        const tbChat = document.getElementById('tbChat');
        if (tbChat) tbChat.textContent = 'Настройки';
        this.applyNetworkConfigToInputs();
        this.renderUiV2Settings();
        this.renderAudioDeviceSettings();
        this.renderRecentAccounts();
        this.renderVaultCloudSyncControls();
        // Индекс сводок кеша поднимается лениво, первым обращением. Открытие
        // настроек — как раз такое обращение: без него карточка на свежем
        // запуске показала бы пустой кеш при полном диске. Рисуем сразу (чтобы
        // не мигало) и ещё раз, когда база ответит.
        this.renderCacheSettings();
        void this.ensureCacheReady().then(() => this.renderCacheSettings());
        this.closeMobileSidebar();
        this.renderHubSegmentNav();
        this.syncMobileChrome();
    }

    openHubView() {
        const cv = document.getElementById('viewChat');
        const hv = document.getElementById('viewHub');
        const sv = document.getElementById('viewSettings');
        const zv = document.getElementById('viewZaliCoin');
        this.collapseActiveCallView();
        if (cv) cv.classList.remove('active');
        if (sv) sv.classList.remove('active');
        if (zv) zv.classList.remove('active');
        if (hv) hv.classList.add('active');
        const tbChat = document.getElementById('tbChat');
        if (tbChat) tbChat.textContent = 'Хаб';
        this.closeMobileSidebar();
        this.renderHub();
        this.renderHubSegmentNav();
        this.syncMobileChrome();
    }

    openZaliCoinView() {
        const cv = document.getElementById('viewChat');
        const hv = document.getElementById('viewHub');
        const sv = document.getElementById('viewSettings');
        const zv = document.getElementById('viewZaliCoin');
        this.collapseActiveCallView();
        if (cv) cv.classList.remove('active');
        if (hv) hv.classList.remove('active');
        if (sv) sv.classList.remove('active');
        if (zv) zv.classList.add('active');
        const tbChat = document.getElementById('tbChat');
        if (tbChat) tbChat.textContent = 'ZaliCoin';
        this.closeMobileSidebar();
        this.renderHubSegmentNav();
        this.syncMobileChrome();
        this.refreshZaliCoinView();
    }
});


// --- MODULE: interface/zalicoin.js ---
// --- ZaliInterface: Экран ZaliCoin: баланс, распределение, переводы. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    // ============================================================
    // ZALICOIN — fixed-supply (100 000) in-app currency. Balance/distribution
    // come from /api/coins/*; transfers are server-authoritative (balance
    // checks + double-spend protection live in server/src/coins.rs), this is
    // just presentation + the idempotency key that makes a retried submit safe.
    // ============================================================

    async refreshZaliCoinView() {
        await Promise.all([this.loadZaliCoinBalance(), this.loadZaliCoinDistribution()]);
        this.renderZaliCoinView();
    }

    async loadZaliCoinBalance() {
        try {
            const res = await this.apiFetch(this.apiRoutes.coins.balance, { interactive: true });
            if (!res.ok) return;
            const data = await res.json();
            this.S.zaliCoinBalance = Number(data.balance) || 0;
        } catch (e) {
            this.trace(`loadZaliCoinBalance error=${e}`);
        }
    }

    async loadZaliCoinDistribution() {
        try {
            const res = await this.apiFetch(this.apiRoutes.coins.distribution, { interactive: true });
            if (!res.ok) return;
            const data = await res.json();
            this.S.zaliCoinTotalSupply = Number(data.totalSupply) || 100000;
            this.S.zaliCoinHolders = Array.isArray(data.holders) ? data.holders : [];
        } catch (e) {
            this.trace(`loadZaliCoinDistribution error=${e}`);
        }
    }

    // Fixed categorical order (never reassigned by rank) — a holder keeps its
    // slot as long as it stays in the top-8-by-balance ranking; overflow folds
    // into a single muted "other" bucket instead of generating a 9th hue.
    zaliCoinSeriesVar(index) {
        const slot = (index % 8) + 1;
        return `var(--zc-series-${slot})`;
    }

    renderZaliCoinView() {
        const view = document.getElementById('viewZaliCoin');
        if (!view) return;
        const totalSupply = this.S.zaliCoinTotalSupply || 100000;
        const balance = this.S.zaliCoinBalance || 0;
        const holders = Array.isArray(this.S.zaliCoinHolders) ? this.S.zaliCoinHolders : [];
        const me = this.myName();

        const balanceValue = document.getElementById('zaliCoinBalanceValue');
        if (balanceValue) balanceValue.textContent = balance.toLocaleString('ru-RU');
        const balanceShare = document.getElementById('zaliCoinBalanceShare');
        if (balanceShare) {
            const pct = totalSupply > 0 ? (balance / totalSupply) * 100 : 0;
            // Never round a partial share to a whole 100/0 — that reads as
            // "all" or "none" when it's actually e.g. 99.97% or 0.04%. toFixed
            // alone would do exactly that at the extremes, so clamp the
            // formatted value away from the whole numbers unless exact.
            let shareText;
            if (pct === 0 || pct === 100) {
                shareText = String(pct);
            } else {
                shareText = pct.toFixed(1);
                if (shareText === '100.0') shareText = '>99.9';
                if (shareText === '0.0') shareText = '<0.1';
            }
            balanceShare.textContent = `${shareText}% от эмиссии`;
        }

        const MAX_SEGMENTS = 8;
        const top = holders.slice(0, MAX_SEGMENTS);
        const rest = holders.slice(MAX_SEGMENTS);
        const restTotal = rest.reduce((sum, h) => sum + (Number(h.balance) || 0), 0);
        const accounted = top.reduce((sum, h) => sum + (Number(h.balance) || 0), 0) + restTotal;
        const unassigned = Math.max(0, totalSupply - accounted);

        const segments = top.map((holder, index) => ({
            label: holder.username,
            value: Number(holder.balance) || 0,
            isMe: holder.username === me,
            color: this.zaliCoinSeriesVar(index),
        }));
        if (restTotal > 0) {
            segments.push({ label: `Остальные (${rest.length})`, value: restTotal, isMe: false, color: 'var(--zc-series-other)' });
        }
        if (unassigned > 0) {
            segments.push({ label: 'Не распределено', value: unassigned, isMe: false, color: 'var(--zc-series-unassigned)' });
        }

        const bar = document.getElementById('zaliCoinBar');
        if (bar) {
            bar.innerHTML = segments.map(seg => {
                const pct = totalSupply > 0 ? (seg.value / totalSupply) * 100 : 0;
                if (pct <= 0) return '';
                const title = `${seg.label}: ${seg.value.toLocaleString('ru-RU')} ZC (${pct.toFixed(1)}%)`;
                return `<button type="button" class="zc-segment${seg.isMe ? ' zc-segment--me' : ''}" style="flex-basis:${pct}%;background:${seg.color}" title="${this.esc(title)}" data-zc-label="${this.esc(seg.label)}" data-zc-value="${seg.value}" data-zc-pct="${pct.toFixed(2)}"></button>`;
            }).join('');
        }

        const legend = document.getElementById('zaliCoinLegend');
        if (legend) {
            legend.innerHTML = segments.map(seg => {
                const pct = totalSupply > 0 ? (seg.value / totalSupply) * 100 : 0;
                return `<div class="zc-legend-item">
                    <span class="zc-legend-swatch" style="background:${seg.color}"></span>
                    <span class="zc-legend-label">${this.esc(seg.label)}${seg.isMe ? ' (вы)' : ''}</span>
                    <span class="zc-legend-value">${seg.value.toLocaleString('ru-RU')} · ${pct.toFixed(1)}%</span>
                </div>`;
            }).join('') || '<div class="zc-legend-empty">Пока никто не держит ZaliCoin</div>';
        }
    }

    zaliCoinNewIdempotencyKey() {
        return this.randomBase64(16).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
    }

    openCoinTransferModal(prefillRecipient = '') {
        const modal = document.getElementById('coinTransferModal');
        if (!modal) return;
        this._coinTransferIdempotencyKey = this.zaliCoinNewIdempotencyKey();
        // The key above is only valid for one exact (to, amount) payload — see
        // submitCoinTransfer, which rotates it whenever the payload changes.
        this._coinTransferLastPayload = '';
        this._coinTransferInFlight = false;
        this._coinTransferFromWallet = !prefillRecipient;
        const recipientInput = document.getElementById('coinTransferRecipientInput');
        const amountInput = document.getElementById('coinTransferAmountInput');
        const submitBtn = document.getElementById('coinTransferSubmitBtn');
        const status = document.getElementById('coinTransferStatus');
        if (recipientInput) {
            recipientInput.value = prefillRecipient || '';
            recipientInput.disabled = !!prefillRecipient;
        }
        if (amountInput) amountInput.value = '';
        if (submitBtn) submitBtn.disabled = false;
        if (status) { status.textContent = ''; status.hidden = true; }
        modal.hidden = false;
        (prefillRecipient ? amountInput : recipientInput)?.focus();
    }

    closeCoinTransferModal() {
        const modal = document.getElementById('coinTransferModal');
        if (modal) modal.hidden = true;
    }

    async submitCoinTransfer() {
        const modal = document.getElementById('coinTransferModal');
        if (!modal || modal.hidden) return;
        // The Enter-key path calls this directly, bypassing the disabled submit
        // button — without this guard a held/repeated Enter fires concurrent
        // submits (server-side idempotency makes the money safe, but the client
        // would close/re-log/post the chat notice once per call).
        if (this._coinTransferInFlight) return;
        const recipientInput = document.getElementById('coinTransferRecipientInput');
        const amountInput = document.getElementById('coinTransferAmountInput');
        const submitBtn = document.getElementById('coinTransferSubmitBtn');
        const status = document.getElementById('coinTransferStatus');
        const setStatus = (msg) => { if (status) { status.textContent = msg; status.hidden = !msg; } };

        const to = String(recipientInput?.value || '').trim();
        const amount = Math.trunc(Number(amountInput?.value));
        if (!to) { setStatus('Укажите получателя'); return; }
        if (!Number.isFinite(amount) || amount <= 0) { setStatus('Укажите сумму больше нуля'); return; }
        if (to === this.myName()) { setStatus('Нельзя перевести самому себе'); return; }

        // The idempotency key must identify one exact payload. If the user got a
        // transport error, then edited the recipient/amount and resubmitted, the
        // old key could replay a transfer that DID commit server-side — the server
        // would answer "success" for the old payload while the user believes the
        // edited one went through. Rotate the key whenever the payload changes;
        // keep it only for a true retry of the identical payload.
        const payloadSignature = `${to}\0${amount}`;
        if (this._coinTransferLastPayload && this._coinTransferLastPayload !== payloadSignature) {
            this._coinTransferIdempotencyKey = this.zaliCoinNewIdempotencyKey();
        }
        this._coinTransferLastPayload = payloadSignature;

        this._coinTransferInFlight = true;
        if (submitBtn) submitBtn.disabled = true;
        setStatus('Отправка...');

        // The network call is isolated from everything after it: a timeout or
        // dropped connection here doesn't tell us whether the server already
        // committed the transfer, so a transport-level failure gets one safe
        // automatic retry with the *same* idempotencyKey before we tell the
        // user anything failed — the server's UNIQUE (from_user, idempotencyKey)
        // constraint makes a resubmit a no-op if the first attempt actually
        // landed, and returns the definitive current balance either way.
        let res;
        try {
            res = await this.transferCoinsRequest(to, amount);
        } catch (e) {
            setStatus('Не удалось связаться с сервером, попробуйте ещё раз');
            this.trace(`submitCoinTransfer transport_error=${e}`);
            this._coinTransferInFlight = false;
            if (submitBtn) submitBtn.disabled = false;
            return;
        }

        if (!res.ok) {
            const text = await res.text().catch(() => '');
            setStatus(text || 'Не удалось выполнить перевод');
            this._coinTransferInFlight = false;
            if (submitBtn) submitBtn.disabled = false;
            return;
        }

        // From here on the transfer is authoritatively done — nothing below
        // should be able to make this look like a failed transfer anymore.
        const data = await res.json().catch(() => null);
        if (data && Number.isFinite(Number(data.balance))) {
            this.S.zaliCoinBalance = Number(data.balance);
        }
        this._coinTransferInFlight = false;
        if (submitBtn) submitBtn.disabled = false;
        this.closeCoinTransferModal();
        this.addLogEntry({ type: 'INFO', msg: `Отправлено ${amount} ZaliCoin пользователю ${to}`, ts: new Date().toLocaleTimeString() });
        this.refreshZaliCoinView();

        // Post a normal chat message so the transfer shows up in the
        // conversation — only when it's the peer of the chat the button
        // was opened from; a wallet-tab transfer to an arbitrary user may
        // have no open conversation to post into, so it's skipped there.
        // Its own failure (e.g. a flaky send right after) is logged, not
        // surfaced as a transfer error — the money already moved.
        if (!this._coinTransferFromWallet && to === this.S.current) {
            const input = document.getElementById('msgInput');
            // A half-typed draft may be sitting in the composer — the transfer
            // notice must not silently destroy (or worse, replace-and-send) it.
            const draft = input ? input.value : '';
            try {
                if (input) {
                    // Named explicitly: this renders as a centered system pill
                    // (detectSystemNotice), not a left/right bubble, so there's no
                    // avatar or sender-side layout to imply who sent it — without
                    // the name in the text itself it read as anonymous.
                    input.value = `💰 ${this.myName()} перевёл(а) ${amount} ZaliCoin`;
                    this.updateSendButtonState?.();
                    await this.sendInputMessage();
                }
            } catch (e) {
                this.trace(`submitCoinTransfer chat_message_post_failed=${e}`);
                this.addLogEntry({ type: 'WARN', msg: 'ZaliCoin переведён, но не удалось отправить сообщение об этом в чат', ts: new Date().toLocaleTimeString() });
            } finally {
                if (input && draft) {
                    input.value = draft;
                    this.updateSendButtonState?.();
                }
            }
        }
    }

    async transferCoinsRequest(to, amount) {
        const body = JSON.stringify({ to, amount, idempotencyKey: this._coinTransferIdempotencyKey });
        try {
            return await this.apiFetch(this.apiRoutes.coins.transfer, { method: 'POST', body });
        } catch (firstError) {
            this.trace(`transferCoinsRequest retrying after transport error=${firstError}`);
            return await this.apiFetch(this.apiRoutes.coins.transfer, { method: 'POST', body });
        }
    }
});


// --- MODULE: interface/prefs.js ---
// --- ZaliInterface: Пользовательские настройки: тема, звук, устройства ввода/вывода, сегменты хаба. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    navModeStorageKey() {
        return 'zali_nav_mode_v1';
    }

    uiV2EnabledStorageKey() {
        return 'zali_ui_v2_enabled_v1';
    }

    uiV2SegmentsStorageKey() {
        return 'zali_ui_v2_segments_v1';
    }

    experimentalDesignStorageKey() {
        return 'zali_experimental_design_v1';
    }

    // ============================================================
    // DESIGN MODE — оформление интерфейса целиком: classic | flat.
    //
    // Раньше это был одиночный чекбокс «плоский режим»
    // (`zali_experimental_design_v1`, атрибут `data-experimental-design`).
    // Режимов стало три, и они взаимоисключающие, поэтому источник правды —
    // `zali_design_mode_v1`, а старый ключ остаётся ЗЕРКАЛОМ: его продолжают
    // читать CSS-правила плоской темы (`body[data-experimental-design="on"]`,
    // ~66 селекторов) и старые сборки нативных шеллов, у которых в
    // localStorage уже лежит выбор пользователя. Поэтому saveDesignMode()
    // пишет оба ключа, а loadDesignMode() умеет поднять старый выбор.
    // ============================================================

    designModeStorageKey() {
        return 'zali_design_mode_v1';
    }

    designModeCatalog() {
        return [
            { id: 'classic', label: 'Классический', note: 'default', hint: 'Исходное оформление: градиенты, свечения, стеклянные панели.' },
            { id: 'flat', label: 'Плоский', note: 'flat', hint: 'Тот же интерфейс без градиентов и свечений — матовые поверхности.' },
        ];
    }

    normalizeDesignMode(value) {
        const id = String(value || '').trim().toLowerCase();
        return this.designModeCatalog().some(m => m.id === id) ? id : 'classic';
    }

    loadDesignMode() {
        try {
            const stored = localStorage.getItem(this.designModeStorageKey());
            if (stored) return this.normalizeDesignMode(stored);
            // Миграция с одиночного чекбокса: включённый плоский режим —
            // это ровно режим 'flat', всё остальное — 'classic'.
            return localStorage.getItem(this.experimentalDesignStorageKey()) === '1' ? 'flat' : 'classic';
        } catch (e) {
            return 'classic';
        }
    }

    saveDesignMode(mode) {
        this.designMode = this.normalizeDesignMode(mode);
        this.experimentalDesign = this.designMode === 'flat';
        try {
            localStorage.setItem(this.designModeStorageKey(), this.designMode);
            localStorage.setItem(this.experimentalDesignStorageKey(), this.experimentalDesign ? '1' : '0');
        } catch (e) {}
        this.applyDesignMode();
    }

    applyDesignMode() {
        this.designMode = this.normalizeDesignMode(this.designMode || this.loadDesignMode());
        this.experimentalDesign = this.designMode === 'flat';
        const body = document.body;
        if (body) {
            body.setAttribute('data-design-mode', this.designMode);
            body.setAttribute('data-experimental-design', this.experimentalDesign ? 'on' : 'off');
        }
        // Легаси-чекбокс мог остаться в чужой сборке HTML — держим его в курсе.
        const legacyToggle = document.getElementById('inputExperimentalDesign');
        if (legacyToggle) legacyToggle.checked = !!this.experimentalDesign;
        this.renderDesignModeSettings();
    }

    renderDesignModeSettings() {
        const host = document.getElementById('designModeOptions');
        if (!host) return;
        const active = this.normalizeDesignMode(this.designMode);
        const html = this.designModeCatalog().map(mode => `
            <button type="button" class="design-mode-option${mode.id === active ? ' active' : ''}" data-design-mode="${this.esc(mode.id)}" aria-pressed="${mode.id === active}">
                <span class="design-mode-preview design-mode-preview--${this.esc(mode.id)}" aria-hidden="true">
                    <span class="design-mode-preview-bar"></span>
                    <span class="design-mode-preview-row"></span>
                    <span class="design-mode-preview-row design-mode-preview-row--accent"></span>
                </span>
                <span class="design-mode-copy">
                    <strong>${this.esc(mode.label)}</strong>
                    <small>${this.esc(mode.hint)}</small>
                </span>
                <span class="design-mode-note">${this.esc(mode.note)}</span>
            </button>
        `).join('');
        if (host.innerHTML !== html) host.innerHTML = html;
    }

    // Обратная совместимость: старый API продолжает работать, но теперь это
    // просто «переключить между classic и flat» поверх designMode.
    loadExperimentalDesign() {
        return this.loadDesignMode() === 'flat';
    }

    saveExperimentalDesign(enabled) {
        this.saveDesignMode(enabled ? 'flat' : 'classic');
    }

    applyExperimentalDesign() {
        this.applyDesignMode();
    }

    voiceTraceStorageKey() {
        return 'zali_voice_trace_enabled_v1';
    }

    loadVoiceTraceEnabled() {
        try {
            return localStorage.getItem(this.voiceTraceStorageKey()) === '1';
        } catch (e) {
            return false;
        }
    }

    saveVoiceTraceEnabled(enabled) {
        this.voiceTraceEnabled = !!enabled;
        try {
            localStorage.setItem(this.voiceTraceStorageKey(), this.voiceTraceEnabled ? '1' : '0');
        } catch (e) {}
        this.applyVoiceTraceEnabled();
    }

    applyVoiceTraceEnabled() {
        const toggle = document.getElementById('inputVoiceTrace');
        if (toggle) toggle.checked = !!this.voiceTraceEnabled;
        if (!this.voiceTraceEnabled && this.voice) {
            this.voice.traceLines = [];
        }
        if (typeof this.renderVoicePanel === 'function') {
            this.renderVoicePanel();
        }
    }

    // ============================================================
    // AUDIO DEVICE + VOLUME PREFERENCES — mic/speaker selection and playback
    // volume (master + per-contact). Device/volume choices persist across
    // sessions in localStorage; the actual WebAudio gain nodes they drive
    // live on this.voice and only exist while a call is active.
    // ============================================================

    audioPrefsStorageKey() {
        return 'zali_audio_prefs_v1';
    }

    loadAudioPrefs() {
        const fallback = { micDeviceId: '', speakerDeviceId: '', masterVolumePercent: 100, peerVolumePercents: {} };
        try {
            const raw = localStorage.getItem(this.audioPrefsStorageKey());
            if (!raw) return fallback;
            const parsed = JSON.parse(raw);
            return {
                micDeviceId: String(parsed?.micDeviceId || ''),
                speakerDeviceId: String(parsed?.speakerDeviceId || ''),
                masterVolumePercent: Number.isFinite(parsed?.masterVolumePercent) ? Math.max(0, Math.min(200, parsed.masterVolumePercent)) : 100,
                peerVolumePercents: (parsed?.peerVolumePercents && typeof parsed.peerVolumePercents === 'object') ? parsed.peerVolumePercents : {},
            };
        } catch (e) {
            return fallback;
        }
    }

    saveAudioPrefs() {
        try {
            localStorage.setItem(this.audioPrefsStorageKey(), JSON.stringify(this.audioPrefs));
        } catch (e) {}
    }

    getPeerVolumePercent(peer) {
        const name = String(peer || '').trim();
        if (!name) return 100;
        const value = this.audioPrefs?.peerVolumePercents?.[name];
        return Number.isFinite(value) ? Math.max(0, Math.min(200, value)) : 100;
    }

    setPeerVolumePercent(peer, percent) {
        const name = String(peer || '').trim();
        if (!name) return;
        const clamped = Math.max(0, Math.min(200, Math.round(Number(percent) || 0)));
        this.audioPrefs.peerVolumePercents[name] = clamped;
        this.saveAudioPrefs();
        this.applyPeerVolume(name);
    }

    setMasterVolumePercent(percent) {
        const clamped = Math.max(0, Math.min(200, Math.round(Number(percent) || 0)));
        this.audioPrefs.masterVolumePercent = clamped;
        this.saveAudioPrefs();
        this.applyMasterVolume();
        const label = document.getElementById('masterVolumeValue');
        if (label) label.textContent = `${clamped}%`;
    }

    // Both sliders end up as one element volume. HTMLMediaElement.volume saturates
    // at 1.0, so the >100 % half can no longer boost — only the WebAudio graph could
    // do that, and that graph was the single unfallback-able playback path. Being
    // audible beats a boost that depended on it.
    effectiveRemoteVolume(peer) {
        const peerPercent = this.getPeerVolumePercent(peer);
        const masterPercent = this.audioPrefs.masterVolumePercent || 100;
        return Math.max(0, Math.min(1, (peerPercent / 100) * (masterPercent / 100)));
    }

    applyMasterVolume() {
        for (const peer of this.voice.remoteAudios.keys()) this.applyPeerVolume(peer);
    }

    applyPeerVolume(peer) {
        const name = String(peer || '').trim();
        const audio = this.voice.remoteAudios.get(name);
        if (audio) audio.volume = this.effectiveRemoteVolume(name);
    }

    async refreshAudioDeviceOptions() {
        const micSelect = document.getElementById('inputAudioMic');
        const speakerSelect = document.getElementById('inputAudioSpeaker');
        if (!micSelect && !speakerSelect) return;
        if (!navigator.mediaDevices?.enumerateDevices) return;
        try {
            // Device labels are only populated after a getUserMedia grant; until
            // then they just show as "Микрофон N" / "Динамики N" placeholders.
            const devices = await navigator.mediaDevices.enumerateDevices();
            const mics = devices.filter(d => d.kind === 'audioinput');
            const speakers = devices.filter(d => d.kind === 'audiooutput');
            if (micSelect) {
                const current = this.audioPrefs.micDeviceId;
                micSelect.innerHTML = ['<option value="">Системный микрофон по умолчанию</option>']
                    .concat(mics.map((d, i) => `<option value="${this.esc(d.deviceId)}">${this.esc(d.label || `Микрофон ${i + 1}`)}</option>`))
                    .join('');
                micSelect.value = mics.some(d => d.deviceId === current) ? current : '';
            }
            if (speakerSelect) {
                const current = this.audioPrefs.speakerDeviceId;
                const supported = typeof HTMLMediaElement !== 'undefined' && 'setSinkId' in HTMLMediaElement.prototype;
                speakerSelect.disabled = !supported;
                speakerSelect.innerHTML = ['<option value="">Системные динамики по умолчанию</option>']
                    .concat(speakers.map((d, i) => `<option value="${this.esc(d.deviceId)}">${this.esc(d.label || `Динамики ${i + 1}`)}</option>`))
                    .join('');
                speakerSelect.value = speakers.some(d => d.deviceId === current) ? current : '';
            }
        } catch (error) {
            this.voiceTrace?.('device-enumerate-failed', { error: error?.message || String(error) }, 'WARN');
        }
    }

    renderAudioDeviceSettings() {
        const volumeInput = document.getElementById('inputMasterVolume');
        if (volumeInput) volumeInput.value = String(this.audioPrefs.masterVolumePercent);
        const volumeLabel = document.getElementById('masterVolumeValue');
        if (volumeLabel) volumeLabel.textContent = `${this.audioPrefs.masterVolumePercent}%`;
        this.refreshAudioDeviceOptions();
    }

    async setAudioInputDevice(deviceId) {
        this.audioPrefs.micDeviceId = String(deviceId || '');
        this.saveAudioPrefs();
        if (!this.voice.localStream) return;
        try {
            const constraints = this.audioPrefs.micDeviceId
                ? { audio: { deviceId: { exact: this.audioPrefs.micDeviceId } }, video: false }
                : { audio: true, video: false };
            const newStream = await navigator.mediaDevices.getUserMedia(constraints);
            const newTrack = newStream.getAudioTracks()[0];
            if (!newTrack) return;
            const oldTrack = this.voice.localStream.getAudioTracks()[0];
            for (const entry of this.voice.peerConnections.values()) {
                if (entry.audioSender) {
                    await entry.audioSender.replaceTrack(newTrack);
                }
            }
            if (oldTrack) {
                this.voice.localStream.removeTrack(oldTrack);
                try { oldTrack.stop(); } catch (e) {}
            }
            this.voice.localStream.addTrack(newTrack);
            this.ensureMeterEntry('local', this.voice.localStream);
            this.voiceTrace('mic-switched', { deviceId: this.audioPrefs.micDeviceId || 'default' }, 'SUCCESS');
        } catch (error) {
            this.addLogEntry({ type: 'ERROR', msg: error?.message || 'Не удалось переключить микрофон', ts: new Date().toLocaleTimeString() });
            this.voiceTrace('mic-switch-failed', { error: error?.message || String(error) }, 'ERROR');
        }
    }

    async setAudioOutputDevice(deviceId) {
        this.audioPrefs.speakerDeviceId = String(deviceId || '');
        this.saveAudioPrefs();
        await this.applyAudioOutputDevice();
    }

    async applyAudioOutputDevice() {
        const id = this.audioPrefs.speakerDeviceId || '';
        for (const audio of this.voice.remoteAudios.values()) {
            if (typeof audio.setSinkId === 'function') {
                try { await audio.setSinkId(id); } catch (error) {
                    this.voiceTrace?.('speaker-sink-failed', { error: error?.message || String(error) }, 'WARN');
                }
            }
        }
        // AudioContext.setSinkId is a newer API (not universally supported) — the
        // per-<audio>-element setSinkId above already covers the fallback
        // 'element' playback route from syncRemoteAudioPlaybackMode.
        const ctx = this.voice.audioContext;
        if (ctx && typeof ctx.setSinkId === 'function') {
            try { await ctx.setSinkId(id || 'default'); } catch (error) {
                this.voiceTrace?.('speaker-sink-context-failed', { error: error?.message || String(error) }, 'WARN');
            }
        }
    }

    hubSegmentCatalog() {
        return [
            { id: 'dm', label: 'ЛС', eyebrow: 'Direct', description: 'Личные диалоги и контакты' },
            { id: 'servers', label: 'Сервера', eyebrow: 'Guilds', description: 'Каналы, роли и сообщества' },
            { id: 'zalicoin', label: 'ZaliCoin', eyebrow: 'Economy', description: 'Баланс и переводы ZaliCoin' },
        ];
    }

    loadUiV2Enabled() {
        try {
            const raw = localStorage.getItem(this.uiV2EnabledStorageKey());
            // ZaliCoin ships as the 3rd segment of this nav (see hubSegmentCatalog),
            // so this is now the default chrome — `null` (never explicitly toggled)
            // means "on"; an explicit '0' from before this change stays respected.
            return raw === null ? true : raw === '1';
        } catch (e) {
            return true;
        }
    }

    saveUiV2Enabled(enabled) {
        this.uiV2Enabled = !!enabled;
        try {
            localStorage.setItem(this.uiV2EnabledStorageKey(), this.uiV2Enabled ? '1' : '0');
        } catch (e) {}
        this.applyUiV2Chrome();
    }

    normalizeUiV2Segments(value) {
        const allowed = new Set(this.hubSegmentCatalog().map(item => item.id));
        const source = Array.isArray(value) ? value : [];
        const next = [];
        for (const item of source) {
            const id = String(item || '').trim();
            if (!allowed.has(id) || next.includes(id)) continue;
            next.push(id);
            if (next.length >= 3) break;
        }
        return next.length ? next : ['dm', 'servers', 'zalicoin'];
    }

    loadUiV2Segments() {
        try {
            const raw = localStorage.getItem(this.uiV2SegmentsStorageKey());
            return this.normalizeUiV2Segments(raw ? JSON.parse(raw) : ['dm', 'servers', 'zalicoin']);
        } catch (e) {
            return ['dm', 'servers', 'zalicoin'];
        }
    }

    saveUiV2Segments(segments) {
        this.uiV2Segments = this.normalizeUiV2Segments(segments);
        try {
            localStorage.setItem(this.uiV2SegmentsStorageKey(), JSON.stringify(this.uiV2Segments));
        } catch (e) {}
        this.applyUiV2Chrome();
    }

    activeHubSegmentId() {
        if (document.getElementById('viewHub')?.classList.contains('active')) return 'hub';
        if (document.getElementById('viewSettings')?.classList.contains('active')) return 'settings';
        if (document.getElementById('viewZaliCoin')?.classList.contains('active')) return 'zalicoin';
        return this.S.navMode === 'servers' ? 'servers' : 'dm';
    }

    handleHubSegment(segmentId) {
        const id = String(segmentId || '').trim();
        if (id === 'hub') {
            this.openHubView();
            return;
        }
        if (id === 'settings') {
            this.openSettingsView();
            return;
        }
        if (id === 'zalicoin') {
            this.openZaliCoinView();
            return;
        }
        if (id === 'servers') {
            this.setNavMode('servers', { refresh: true });
            this.openChatView();
            return;
        }
        this.setNavMode('dm', { refresh: true });
        this.openChatView();
    }

    hubSegmentIcon(id) {
        const key = String(id || '').trim();
        const icons = {
            dm: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5.25 5.75h13.5a2 2 0 0 1 2 2v7.1a2 2 0 0 1-2 2H11.4l-4.75 3.4v-3.4h-1.4a2 2 0 0 1-2-2v-7.1a2 2 0 0 1 2-2Z"/><path d="M7.4 9.3h9.2M7.4 12.6h6.4"/></svg>',
            servers: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6.2 4.6h11.6a2 2 0 0 1 2 2v2.8a2 2 0 0 1-2 2H6.2a2 2 0 0 1-2-2V6.6a2 2 0 0 1 2-2Z"/><path d="M6.2 12.6h11.6a2 2 0 0 1 2 2v2.8a2 2 0 0 1-2 2H6.2a2 2 0 0 1-2-2v-2.8a2 2 0 0 1 2-2Z"/><path d="M7.6 8h.05M7.6 16h.05M10.4 8h6M10.4 16h6"/></svg>',
            settings: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 7h8.2"/><path d="M16.8 7H19"/><path d="M15 5.1a1.9 1.9 0 1 1 0 3.8 1.9 1.9 0 0 1 0-3.8Z"/><path d="M5 17h2.2"/><path d="M10.8 17H19"/><path d="M9 15.1a1.9 1.9 0 1 1 0 3.8 1.9 1.9 0 0 1 0-3.8Z"/><path d="M5 12h4.2"/><path d="M12.8 12H19"/><path d="M11 10.1a1.9 1.9 0 1 1 0 3.8 1.9 1.9 0 0 1 0-3.8Z"/></svg>',
            hub: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3.75 20.25 9v9.25a2 2 0 0 1-2 2h-4.1v-5.35h-4.3v5.35h-4.1a2 2 0 0 1-2-2V9L12 3.75Z"/></svg>',
            zalicoin: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8.25"/><path d="M12 7.4v9.2M14.6 9.4c0-1.05-1.16-1.9-2.6-1.9-1.44 0-2.6.85-2.6 1.9 0 1.05 1.16 1.55 2.6 1.9 1.44.35 2.6.85 2.6 1.9 0 1.05-1.16 1.9-2.6 1.9-1.44 0-2.6-.85-2.6-1.9"/></svg>',
        };
        return icons[key] || icons.hub;
    }

    renderHubSegmentNav() {
        const nav = document.getElementById('hubSegmentNav');
        if (!nav) return;
        const catalog = new Map(this.hubSegmentCatalog().map(item => [item.id, item]));
        const active = this.activeHubSegmentId();
        const items = this.normalizeUiV2Segments(this.uiV2Segments)
            .map(id => catalog.get(id))
            .filter(Boolean);
        items.push({ id: 'hub', label: 'Хаб', eyebrow: 'Home', description: 'Новости и подприложения' });
        const signature = items.map(item => item.id).join('|');
        const hasStableButtons = nav.dataset.segmentSignature === signature
            && nav.querySelector('.hub-segment-indicator')
            && nav.querySelectorAll('.hub-segment-btn').length === items.length;
        if (hasStableButtons) {
            this.updateHubSegmentNavActive(active);
            return;
        }
        nav.innerHTML = '<span class="hub-segment-indicator" aria-hidden="true"></span>' + items.map(item => `
            <button class="hub-segment-btn ${active === item.id ? 'active' : ''}" type="button" data-hub-segment="${this.esc(item.id)}" title="${this.esc(item.label)} · ${this.esc(item.description)}" aria-label="${this.esc(item.label)}" aria-pressed="${active === item.id ? 'true' : 'false'}">
                ${this.hubSegmentIcon(item.id)}
            </button>
        `).join('');
        nav.dataset.segmentSignature = signature;
        this.syncHubSegmentIndicator(null);
    }

    updateHubSegmentNavActive(active) {
        const nav = document.getElementById('hubSegmentNav');
        if (!nav) return;
        const previousActive = nav.querySelector('.hub-segment-btn.active');
        const previousPosition = previousActive
            ? {
                x: previousActive.offsetLeft,
                width: previousActive.offsetWidth,
            }
            : null;
        nav.querySelectorAll('.hub-segment-btn').forEach(btn => {
            const isActive = String(btn.getAttribute('data-hub-segment') || '') === active;
            btn.classList.toggle('active', isActive);
            btn.setAttribute('aria-pressed', String(isActive));
        });
        this.syncHubSegmentIndicator(previousPosition);
    }

    syncHubSegmentIndicator(previousPosition = null) {
        const nav = document.getElementById('hubSegmentNav');
        const indicator = nav?.querySelector('.hub-segment-indicator');
        const activeBtn = nav?.querySelector('.hub-segment-btn.active');
        if (!nav || !indicator || !activeBtn) return;
        const applyTarget = (withTransition = true) => {
            if (withTransition) indicator.style.transition = '';
            indicator.style.width = `${activeBtn.offsetWidth}px`;
            indicator.style.transform = `translate3d(${activeBtn.offsetLeft}px, 0, 0)`;
        };
        const samePosition = previousPosition
            && Math.abs(Number(previousPosition.x || 0) - activeBtn.offsetLeft) < 0.5
            && Math.abs(Number(previousPosition.width || 0) - activeBtn.offsetWidth) < 0.5;
        if (samePosition) {
            return;
        }
        if (previousPosition) {
            indicator.getBoundingClientRect();
            requestAnimationFrame(() => applyTarget(true));
        } else {
            indicator.style.transition = 'none';
            applyTarget(false);
            requestAnimationFrame(() => {
                indicator.style.transition = '';
            });
        }
    }

    renderUiV2Settings() {
        const toggle = document.getElementById('inputUiV2Enabled');
        if (toggle) toggle.checked = !!this.uiV2Enabled;
        const box = document.getElementById('hubSegmentSettings');
        const count = document.getElementById('hubSegmentsCount');
        if (!box) return;
        const selected = new Set(this.normalizeUiV2Segments(this.uiV2Segments));
        const total = selected.size + 1;
        if (count) count.textContent = `${total} / 4`;
        box.innerHTML = this.hubSegmentCatalog().map(item => `
            <label class="hub-segment-option">
                <input type="checkbox" value="${this.esc(item.id)}" ${selected.has(item.id) ? 'checked' : ''}>
                <span>
                    <strong>${this.esc(item.label)}</strong>
                    <small>${this.esc(item.description)}</small>
                </span>
            </label>
        `).join('');
    }

    applyUiV2Chrome() {
        document.body?.setAttribute('data-ui-v2', this.uiV2Enabled ? 'on' : 'off');
        if (!this.uiV2Enabled && document.getElementById('viewHub')?.classList.contains('active')) {
            this.openChatView();
        }
        this.renderHubSegmentNav();
        this.renderUiV2Settings();
        this.syncMobileChrome();
    }
});


// --- MODULE: interface/storage.js ---
// --- ZaliInterface: Ключи localStorage, кэш сообщений, персист контактов. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    _userSuffix() {
        const u = this.S.session?.username;
        return u ? `_${u}` : '';
    }

    activeServerStorageKey() {
        return `zali_active_server_v1${this._userSuffix()}`;
    }

    activeChannelStorageKey() {
        return `zali_active_channel_v1${this._userSuffix()}`;
    }

    currentContactStorageKey() {
        return `zali_current_contact_v1${this._userSuffix()}`;
    }

    contactsStorageKey() {
        return `zali_contacts_v1${this._userSuffix()}`;
    }

    serverChatsStorageKey() {
        return `zali_server_chats_v1${this._userSuffix()}`;
    }

    mutedChatsStorageKey() {
        return `zali_muted_chats_v1${this._userSuffix()}`;
    }

    // Server-side reset boundary: the production database, uploads and assets were
    // wiped at this moment, so every locally cached account, message, attachment
    // reference and E2E key from before it is dangling. Bumping this string performs
    // exactly one purge per client; clients that already purged carry the same value
    // in `zali_local_reset_v1` and skip it forever after.
    //
    // 2026-09-05: production migrated from `zms` to `ms` with no data carried over
    // (old host lost/inaccessible) — a second, unrelated reset boundary, same purge.
    localResetEpoch() {
        return '2026-09-05T21:00:00Z';
    }

    localResetMarkerKey() {
        return 'zali_local_reset_v1';
    }

    // Wipes every local trace of the pre-reset world: localStorage/sessionStorage,
    // the values the native shells inject at document-start (they come from native
    // storage, not from localStorage, so clearing localStorage alone would leave the
    // old crypto key and message cache live for this session), and the native copies
    // themselves via CLEAR_LOCAL_DATA. Network settings survive on purpose — a client
    // pointed at a non-default server must not silently jump back to the default.
    applyLocalDataResetIfNeeded() {
        const epoch = this.localResetEpoch();
        const marker = this.localResetMarkerKey();
        let stored = null;
        try {
            stored = localStorage.getItem(marker);
        } catch (e) {
            return false;
        }
        if (stored === epoch) return false;

        const preserved = new Map();
        const keepKeys = ['zali_network_config_v1'];
        for (const key of keepKeys) {
            try {
                const value = localStorage.getItem(key);
                if (value !== null) preserved.set(key, value);
            } catch (e) {}
        }
        for (const store of [localStorage, sessionStorage]) {
            try {
                const doomed = [];
                for (let i = 0; i < store.length; i += 1) {
                    const key = store.key(i);
                    if (key && key.startsWith('zali_')) doomed.push(key);
                }
                doomed.forEach(key => { try { store.removeItem(key); } catch (e) {} });
            } catch (e) {}
        }
        for (const [key, value] of preserved) {
            try { localStorage.setItem(key, value); } catch (e) {}
        }
        try { localStorage.setItem(marker, epoch); } catch (e) {}

        // Постоянный кеш ассетов живёт в IndexedDB, а не в localStorage, и
        // цикл выше его не видит — а в нём лежат аватарки и вложения, снятые
        // с сервера, которого больше нет. Удаляется целиком, вместе со схемой.
        try { this.destroyAssetCacheDatabase(); } catch (e) {}

        // Injected at document-start from native storage — already in memory by now.
        try { window.__ZALI_SAVED_KEY = ''; } catch (e) {}
        try { window.__ZALI_MESSAGE_CACHE = { chats: {}, serverChats: {} }; } catch (e) {}
        try { window.__ZALI_CONVERSATION_KEYS = {}; } catch (e) {}
        try { window.__ZALI_PENDING_OUTBOX = []; } catch (e) {}
        try { window.__ZALI_INJECTED_DEVICE_IDENTITY = null; } catch (e) {}
        try { window.__ZALI_SAVED_SESSION = null; } catch (e) {}
        try { window.__ZALI_ACTIVE_CONVERSATION_SCOPE = null; } catch (e) {}

        try {
            if (window.__ZALI_NATIVE?.available) {
                this.postNativeMessage({ type: NativeMessageTypes.CLEAR_LOCAL_DATA, payload: {} });
            }
        } catch (e) {}

        try {
            console.log('[ZALI] local data reset applied for epoch', epoch);
        } catch (e) {}
        return true;
    }

    messageCacheStorageKey() {
        return `zali_message_cache_v1${this._userSuffix()}`;
    }

    networkConfigStorageKey() {
        return 'zali_network_config_v1';
    }

    cryptoKeyStorageKey() {
        return `zali_crypto_key_v2${this._userSuffix()}`;
    }

    deviceIdentityStorageKey() {
        return `zali_device_identity_v1${this._userSuffix()}`;
    }

    authStorageKey() {
        return 'zali_session_v1';
    }

    lastAuthStorageKey() {
        return 'zali_last_session_v1';
    }

    recentAccountsStorageKey() {
        return 'zali_recent_accounts_v1';
    }

    pendingOutboxStorageKey() {
        return `zali_pending_outbox_v1${this._userSuffix()}`;
    }

    loadStoredMessageCache() {
        try {
            // Deliberately does NOT fall back to the old unsuffixed 'zali_message_cache_v1'
            // key: that was a one-time migration for the pre-per-account-storage era, but
            // left active it means every brand-new account's first load silently adopts
            // whatever chats a DIFFERENT previous account left behind on this browser —
            // "ghost" conversations with people this account never talked to. Same reasoning
            // applies to the crypto key / conversation keys / device identity loaders below.
            let raw = localStorage.getItem(this.messageCacheStorageKey());
            if (!raw) return this.loadInjectedMessageCache();
            const parsed = JSON.parse(raw);
            const chats = parsed && typeof parsed === 'object' && parsed.chats && typeof parsed.chats === 'object'
                ? parsed.chats
                : {};
            const serverChats = parsed && typeof parsed === 'object' && parsed.serverChats && typeof parsed.serverChats === 'object'
                ? parsed.serverChats
                : {};
            if (!Object.keys(chats).length && !Object.keys(serverChats).length) {
                return this.loadInjectedMessageCache();
            }
            return this.restoreAttachmentPayloads({
                chats: Object.fromEntries(Object.entries(chats).filter(([, msgs]) => Array.isArray(msgs)).map(([peer, msgs]) => [peer, msgs.filter(msg => msg && typeof msg === 'object')])),
                serverChats: Object.fromEntries(Object.entries(serverChats).filter(([, msgs]) => Array.isArray(msgs)).map(([peer, msgs]) => [peer, msgs.filter(msg => msg && typeof msg === 'object')])),
            });
        } catch (e) {
            return this.loadInjectedMessageCache();
        }
    }

    // localStorage wins over the native-injected cache, so once an archive stops
    // fitting the quota and the payload-free copy takes over (see
    // writeMessageCacheToStorage), the winning copy is the one WITHOUT the
    // attachment bytes — that would silently turn every photo in history into a
    // name-only placeholder on the next native launch. The native cache file has
    // no quota and still holds the payloads: fold them back in, by message id.
    //
    // No-op in a plain browser tab (nothing is injected) and no-op when nothing
    // is missing, which is the normal case — the probe below stops at the first
    // attachment that already has its payload.
    restoreAttachmentPayloads(cache) {
        const needsPayload = (store) => Object.values(store || {}).some(msgs => (msgs || []).some(
            msg => (msg?.attachments || []).some(att => att && !att.dataUrl && !att.data_url),
        ));
        if (!needsPayload(cache.chats) && !needsPayload(cache.serverChats)) return cache;

        let injected;
        try {
            injected = this.loadInjectedMessageCache();
        } catch (e) {
            return cache;
        }
        const byId = new Map();
        for (const store of [injected.chats, injected.serverChats]) {
            for (const msgs of Object.values(store || {})) {
                for (const msg of msgs || []) {
                    const id = String(msg?.id || msg?.clientId || '').trim();
                    if (id && (msg.attachments || []).length) byId.set(id, msg.attachments);
                }
            }
        }
        if (!byId.size) return cache;

        let restored = 0;
        for (const store of [cache.chats, cache.serverChats]) {
            for (const msgs of Object.values(store || {})) {
                for (const msg of msgs || []) {
                    const attachments = msg?.attachments || [];
                    if (!attachments.length) continue;
                    const source = byId.get(String(msg.id || msg.clientId || '').trim());
                    if (!source) continue;
                    attachments.forEach((att, index) => {
                        if (!att || att.dataUrl || att.data_url) return;
                        const from = source[index];
                        // Position AND name must agree: a message edited on
                        // another device can carry a different attachment set
                        // under the same id.
                        if (!from || from.name !== att.name) return;
                        const payload = from.dataUrl || from.data_url || '';
                        if (payload) { att.dataUrl = payload; restored += 1; }
                    });
                }
            }
        }
        if (restored) this.trace(`restoreAttachmentPayloads restored=${restored}`);
        return cache;
    }

    loadInjectedMessageCache() {
        try {
            const raw = window.__ZALI_MESSAGE_CACHE;
            if (!raw) return { chats: {}, serverChats: {} };
            const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
            if (!parsed || typeof parsed !== 'object') return { chats: {}, serverChats: {} };
            const chats = parsed.chats && typeof parsed.chats === 'object' ? parsed.chats : {};
            const serverChats = parsed.serverChats && typeof parsed.serverChats === 'object' ? parsed.serverChats : {};
            return {
                chats: Object.fromEntries(Object.entries(chats).filter(([, msgs]) => Array.isArray(msgs)).map(([peer, msgs]) => [peer, msgs.filter(msg => msg && typeof msg === 'object')])),
                serverChats: Object.fromEntries(Object.entries(serverChats).filter(([, msgs]) => Array.isArray(msgs)).map(([peer, msgs]) => [peer, msgs.filter(msg => msg && typeof msg === 'object')])),
            };
        } catch (e) {
            return { chats: {}, serverChats: {} };
        }
    }

    // Debounced wrapper for saveStoredMessageCache(). The full save serializes EVERY
    // chat (JSON.stringify of the whole store), writes localStorage AND ships the whole
    // payload over the native bridge — doing that once per received message made bursts
    // (history merge, reconnect catch-up, busy group chat) quadratic in total work.
    // Trailing-edge coalesce: bursts collapse into one save ≤400ms after the first call.
    scheduleSaveStoredMessageCache(delayMs = 400) {
        if (this._messageCacheSaveTimer) return;
        this._messageCacheSaveTimer = setTimeout(() => {
            this._messageCacheSaveTimer = null;
            this.saveStoredMessageCache();
        }, Math.max(0, Number(delayMs) || 0));
    }

    // Flush a pending debounced save immediately (page hide, logout, account switch) so
    // the last ≤400ms of messages are never lost to a teardown racing the timer.
    flushPendingMessageCacheSave() {
        if (!this._messageCacheSaveTimer) return;
        clearTimeout(this._messageCacheSaveTimer);
        this._messageCacheSaveTimer = null;
        this.saveStoredMessageCache();
    }

    // The persisted shape of an attachment. Deliberately NOT the render shape:
    // normalizeAttachment() also returns `src`, a blob: URL that is dead the
    // moment the page reloads, and writing it to disk would both waste space and
    // leave a dangling reference in the cache.
    persistableAttachment(att) {
        return {
            id: att.id,
            name: att.name,
            mimeType: att.mimeType,
            kind: att.kind,
            size: att.size,
            dataUrl: att.dataUrl,
            archivePath: att.archivePath,
        };
    }

    // The same store with every attachment payload removed. This — not the full
    // copy — is what localStorage normally receives, and it is also the change
    // detector for the whole save. See saveStoredMessageCache().
    stripMessageCachePayloads(payload) {
        const strip = (store) => Object.fromEntries(Object.entries(store || {}).map(([key, msgs]) => [
            key,
            (msgs || []).map(msg => (
                (msg.attachments || []).length
                    ? { ...msg, attachments: msg.attachments.map(att => ({ ...att, dataUrl: '' })) }
                    : msg
            )),
        ]));
        return { chats: strip(payload.chats), serverChats: strip(payload.serverChats) };
    }

    // True when the attachment payloads are safe to leave out of the localStorage
    // copy, because something else on this platform is keeping them.
    //
    //   macOS  — declares saveMessageCache, so the full payload goes to the
    //            native cache file (no quota) and loadStoredMessageCache() folds
    //            it back in.
    //   browser— the payload is a blob: URL that is already dead on the next page
    //            load, so persisting it never achieved anything; history is
    //            repaired by the network resync instead.
    //   Windows/iOS/Android — no native cache file, so localStorage is the only
    //            copy there is. Payloads are kept until they stop fitting, and
    //            writeMessageCacheToStorage() drops them at that point.
    messageCachePayloadsHeldElsewhere() {
        if (this.nativeSupports('saveMessageCache')) return true;
        return !this.hasNativeBridge();
    }

    saveStoredMessageCache() {
        const sanitizeMessages = (store) => Object.fromEntries(Object.entries(store || {}).map(([key, msgs]) => [
            key,
            Array.isArray(msgs) ? msgs.map(msg => ({
                ...msg,
                attachments: this.normalizeAttachments(msg.attachments).map(att => this.persistableAttachment(att)),
            })) : [],
        ]));
        const payload = {
            chats: sanitizeMessages(this.S.chats),
            serverChats: sanitizeMessages(this.S.serverChats),
        };
        const storageKey = this.messageCacheStorageKey();

        // The change detector is the PAYLOAD-FREE serialisation, not the full one.
        //
        // This used to be JSON.stringify() of the entire store, attachment base64
        // and all: ~9 ms of main-thread work on a modest conversation with photos,
        // paid on every save including the many that change nothing (a status flip
        // that normalises away, a re-merge of already-known history). Attachment
        // bytes are immutable once received — a message whose attachments change
        // is a different message, with different ids and sizes, and those ARE in
        // this string — so the payload adds nothing a change detector can use.
        const json = JSON.stringify(this.stripMessageCachePayloads(payload));
        const unchanged = this._lastSavedMessageCacheJson === json
            && this._lastSavedMessageCacheKey === storageKey;
        // Вложения уезжают в постоянный кеш (interface/cache.js), а не в
        // localStorage: там они перестают помещаться задолго до того, как
        // переписка станет большой, и клиент переходит на копию без байтов
        // (см. writeMessageCacheToStorage). Раньше на Windows/iOS/Android это
        // значило «фотографии в истории навсегда превращаются в имена файлов».
        // Проверка «уже лежит» идёт по индексу сводок в памяти, поэтому цена
        // прохода пропорциональна новым вложениям, а не всему архиву.
        if (!unchanged) {
            for (const store of [payload.chats, payload.serverChats]) {
                for (const msgs of Object.values(store || {})) {
                    for (const msg of msgs || []) this.cacheStoreMessageAttachments(msg);
                }
            }
        }
        // The object, not a string: loadInjectedMessageCache() accepts either, and
        // handing it the object skips a second full serialisation of the archive.
        this.saveInjectedMessageCache(payload);
        if (unchanged) return;

        this.writeMessageCacheToStorage(storageKey, json, payload);
        if (this.nativeSupports('saveMessageCache')) {
            this.postNativeMessage({
                type: NativeMessageTypes.SAVE_MESSAGE_CACHE,
                cache: payload,
            });
        }
    }

    // Writes the cache, and — this is the point — never gets stuck retrying a
    // write that cannot succeed.
    //
    // An archive with photos in it passes the localStorage quota (5–10 MB
    // everywhere) long before the account gets big. The write then throws, and
    // the old code answered that by clearing the "already saved" latch, so the
    // very next message rebuilt the entire archive, threw again, and copied the
    // whole thing over the native bridge again. Measured: ten consecutive
    // messages cost 80 MB of bridge traffic, ~8 MB each, permanently, for the
    // rest of the session. That is the shape of "it gets slower the longer you
    // use it".
    //
    // Two changes. Once a full write fails the client switches to a payload-free
    // copy for localStorage (text and history survive a reload; the attachment
    // bytes live on in the native cache file, and loadStoredMessageCache() folds
    // them back in). And a failed attempt is still recorded against the JSON it
    // failed on, so an unchanged store is not retried — a genuinely new message
    // produces different JSON and is always attempted.
    writeMessageCacheToStorage(storageKey, liteJson, payload) {
        // Platforms that keep the payloads elsewhere write the payload-free copy
        // outright — nothing is lost, and the write stays proportional to the
        // text of the conversation instead of to the photos in it.
        if (this._messageCacheLiteMode || this.messageCachePayloadsHeldElsewhere()) {
            try {
                localStorage.setItem(storageKey, liteJson);
            } catch (e) {
                this.trace(`saveStoredMessageCache localStorage failed reason=${e?.name || e?.message || e}`);
            }
            this._lastSavedMessageCacheJson = liteJson;
            this._lastSavedMessageCacheKey = storageKey;
            return;
        }

        // Windows, iOS and Android have no native cache file, so localStorage is
        // the only copy of an attachment there is — keep the payloads for as long
        // as they fit, then stop trying.
        try {
            localStorage.setItem(storageKey, JSON.stringify(payload));
        } catch (e) {
            this._messageCacheLiteMode = true;
            this.trace(`saveStoredMessageCache localStorage full, dropping attachment payloads reason=${e?.name || e?.message || e}`);
            this.warnStorageFallback('message_cache', 'Вложения не помещаются в локальный кеш — сохраняются только тексты сообщений.');
            try {
                localStorage.setItem(storageKey, liteJson);
            } catch (inner) {
                this.trace(`saveStoredMessageCache localStorage failed even without payloads reason=${inner?.name || inner?.message || inner}`);
            }
        }
        // Recorded whatever happened. The old code cleared this latch on failure
        // so the "retry" would not be skipped — but the retry was byte-identical
        // and failed identically, so every subsequent message re-serialised and
        // re-copied the entire archive for nothing: measured at 80 MB of bridge
        // traffic across ten messages, permanently, for the rest of the session.
        // A genuinely new message produces a different string and is always tried.
        this._lastSavedMessageCacheJson = liteJson;
        this._lastSavedMessageCacheKey = storageKey;
    }

    // Stored as the object it already is. loadInjectedMessageCache() accepts
    // either shape, and stringifying here meant a second full serialisation of
    // every attachment in the archive on every save, purely to hand the result
    // back to a JSON.parse() later in the same page.
    saveInjectedMessageCache(value) {
        try {
            window.__ZALI_MESSAGE_CACHE = value || { chats: {}, serverChats: {} };
        } catch (e) {}
    }

    normalizeDmChatStore() {
        const me = String(this.myName() || '').trim();
        if (!me) return false;

        const normalized = {};
        let changed = false;

        const pushMessage = (peer, msg, originalKey) => {
            const nextPeer = String(peer || '').trim();
            if (!nextPeer) return;
            if (!normalized[nextPeer]) normalized[nextPeer] = [];
            normalized[nextPeer].push(msg);
            if (String(originalKey || '').trim() !== nextPeer) {
                changed = true;
            }
        };

        Object.entries(this.S.chats || {}).forEach(([key, msgs]) => {
            if (!Array.isArray(msgs)) return;
            msgs.forEach(msg => {
                if (!msg || typeof msg !== 'object') return;
                const sender = String(msg.sender || '').trim();
                const receiver = String(msg.receiver || '').trim();
                const canonicalPeer = sender === me
                    ? receiver
                    : (receiver === me ? sender : '');

                if (canonicalPeer) {
                    pushMessage(canonicalPeer, msg, key);
                } else {
                    pushMessage(String(key || '').trim(), msg, key);
                }
            });
        });

        Object.keys(normalized).forEach(peer => {
            normalized[peer].sort((a, b) => this.compareMessagesByTime(a, b));
        });

        const before = JSON.stringify(this.S.chats || {});
        const after = JSON.stringify(normalized);
        if (before !== after) {
            this.S.chats = normalized;
            this.saveStoredMessageCache();
            this.trace(`normalizeDmChatStore changed peers=${Object.keys(normalized).length}`);
            return true;
        }

        this.S.chats = normalized;
        return changed;
    }

    loadStoredCurrentContact() {
        try {
            const raw = localStorage.getItem(this.currentContactStorageKey());
            const value = String(raw || '').trim();
            return value || null;
        } catch (e) {
            return null;
        }
    }

    saveStoredCurrentContact(name) {
        try {
            const value = String(name || '').trim();
            if (value) {
                localStorage.setItem(this.currentContactStorageKey(), value);
            } else {
                localStorage.removeItem(this.currentContactStorageKey());
            }
        } catch (e) {}
    }

    loadStoredContacts() {
        try {
            const raw = localStorage.getItem(this.contactsStorageKey());
            const parsed = raw ? JSON.parse(raw) : [];
            return Array.isArray(parsed)
                ? parsed.map(item => String(item || '').trim()).filter(Boolean)
                : [];
        } catch (e) {
            return [];
        }
    }

    saveStoredContacts(contacts) {
        try {
            const list = Array.isArray(contacts)
                ? contacts.map(item => String(item || '').trim()).filter(Boolean)
                : [];
            localStorage.setItem(this.contactsStorageKey(), JSON.stringify(list));
        } catch (e) {}
    }

    localConversationContacts() {
        const me = String(this.myName() || '').trim();
        const names = new Set();
        const add = (name) => {
            const value = String(name || '').trim();
            if (value && value !== me) names.add(value);
        };
        Object.entries(this.S.chats || {}).forEach(([peer, msgs]) => {
            if (Array.isArray(msgs) && msgs.length > 0) add(peer);
        });
        add(this.S.current);
        add(this.loadStoredCurrentContact());
        return Array.from(names);
    }

    loadStoredCryptoKey() {
        try {
            const scope = String(this.activeConversationScope || window.__ZALI_ACTIVE_CONVERSATION_SCOPE || '').trim();
            if (scope) {
                const scoped = this.getStoredConversationKey(scope);
                if (scoped) return scoped;
            }
            // No fallback to the legacy unsuffixed 'zali_crypto_key_v2' key — see the
            // comment in loadStoredMessageCache() for why: it would hand a brand-new
            // account a previous, unrelated account's leftover E2E key.
            let stored = (sessionStorage.getItem(this.cryptoKeyStorageKey()) || localStorage.getItem(this.cryptoKeyStorageKey()) || '').trim();
            this.trace(`loadStoredCryptoKey stored=${!!stored}`);
            if (stored) {
                try {
                    sessionStorage.setItem(this.cryptoKeyStorageKey(), stored);
                    localStorage.removeItem(this.cryptoKeyStorageKey());
                } catch (e) {}
                return stored;
            }
            return '';
        } catch (e) {
            this.trace('loadStoredCryptoKey error fallback empty');
            return '';
        }
    }
});


// --- MODULE: interface/cache.js ---
// --- ZaliInterface: Постоянный кеш бинарных ассетов: аватарки, ассеты серверов, профили, вложения. ---
// Часть класса ZaliInterface (см. web/src/interface.js).
//
// Зачем это вообще появилось
// --------------------------
// До этого файла кеш ассетов был `new Map()` в конструкторе — то есть жил ровно
// до перезагрузки страницы. Каждый запуск клиента заново скачивал аватарку
// КАЖДОГО контакта, иконку и баннер каждого сервера, а профиль перезапрашивался
// на каждом открытии (см. шапку profiles.js — там это было записано как
// осознанное решение). Отсюда «многие аватарки и раздел профиля требуют
// подгрузки»: не медленная сеть, а отсутствие диска под кешем.
//
// Здесь появляется диск — IndexedDB — и политика, которая решает, что на него
// класть и что с него выкидывать.
//
// Три вещи, вокруг которых построен файл
// --------------------------------------
//  1. СВОДКА ДЕШЕВЛЕ САМОГО ФАЙЛА. На каждый файл хранится один компактный
//     stat-объект (~60 байт, однобуквенные поля) в ОТДЕЛЬНОМ object store.
//     Весь индекс сводок целиком поднимается в память ОДНИМ getAll() при
//     открытии базы, дальше попадание в кеш меняет только Map в памяти, а на
//     диск дирти-записи уходят пачкой раз в ZALI_CACHE_STAT_FLUSH_MS. Иначе
//     каждое обращение к аватарке стоило бы отдельной транзакции записи —
//     дороже, чем сама аватарка.
//  2. РЕШЕНИЕ О ВЫТЕСНЕНИИ ПРИНИМАЕТСЯ БЕЗ ЕДИНОГО ЧТЕНИЯ С ДИСКА. Индекс уже
//     в памяти, поэтому выбор жертвы — это сортировка массива, а не обход базы.
//  3. ЦЕНА ПРОПОРЦИОНАЛЬНА ДЕЙСТВИЮ (общий принцип раздела «Производительность»
//     в CLAUDE.md). Запись одного файла трогает один blob и один stat, а не
//     пересобирает индекс; вытеснение трогает ровно столько записей, сколько
//     нужно освободить.
//
// Чего здесь СОЗНАТЕЛЬНО нет
// --------------------------
// Нативного слоя. Всё живёт в вебвью и работает одинаково во всех четырёх
// оболочках — как и голосовые звонки (см. исключение в CLAUDE.md), правку
// дублировать в macOS/Windows/Android не нужно, достаточно bundle_web.py.
// Плата: там, где IndexedDB недоступна (документ с opaque-origin — это про
// Android с его file:///android_asset/), кеш деградирует до сегодняшнего
// поведения «только память», а не ломается. Проверять доступность обязательно
// через реальное открытие базы: наличие window.indexedDB ещё ничего не значит,
// на file:// оно есть и бросает SecurityError на open().

const ZALI_CACHE_DB_NAME = 'zali_asset_cache_v1';
const ZALI_CACHE_DB_VERSION = 1;
const ZALI_CACHE_BLOB_STORE = 'blobs';
const ZALI_CACHE_STAT_STORE = 'stats';

// Дирти-сводки сбрасываются пачкой. Число подобрано так, чтобы всплеск
// обращений (первая отрисовка списка контактов трогает все аватарки разом)
// уложился в одну транзакцию.
const ZALI_CACHE_STAT_FLUSH_MS = 4000;

// Потолок «лёгкого» режима: картинка/стикер крупнее этого считается тяжёлой и
// в режиме «Кешировать легковесное» на диск не попадает.
const ZALI_CACHE_LIGHT_MAX_BYTES = 2 * 1024 * 1024;

// Сколько blob:-ссылок разрешено создать при прогреве. Прогрев существует ради
// первого кадра, а не ради полноты: остальное подтянется обычным путём по мере
// обращения. Без потолка аккаунт с тысячей контактов создавал бы тысячу
// object URL'ов до того, как нарисован первый экран.
const ZALI_CACHE_PRIME_LIMIT = 400;

// Через сколько кешированный ассет перепроверяется в фоне. Аватарки штатно
// инвалидируются событием avatar_updated (handleAvatarUpdated), поэтому срок
// длинный — это страховка на случай пропущенного события, а не основной путь.
const ZALI_CACHE_REVALIDATE_MS = 24 * 60 * 60 * 1000;

// Окно дедупликации показов: см. cacheNoteAssetUse(). Аватарка, весь день
// висящая в списке контактов, набирает столько обращений, сколько минут
// приложение было открыто, — а не сколько раз перерисовался список.
const ZALI_CACHE_USE_WINDOW_MS = 60_000;

// Потолок ожидания открытия базы — см. openCacheDb(). Это не «медленный диск»,
// а «открытие может не завершиться никогда»; секунды хватает с запасом на любое
// честное открытие, а всё, что дольше, для отрисовки уже неотличимо от отказа.
const ZALI_CACHE_OPEN_TIMEOUT_MS = 4000;

// Вес класса в формуле полезности. Аватарка в 8 КБ, к которой обращаются на
// каждой отрисовке, обязана переживать видео в 40 МБ, открытое однажды, —
// и без веса это уже вытекало бы из деления на размер, но вес делает
// приоритет явным и настраиваемым.
const ZALI_CACHE_CLASS_WEIGHT = { essential: 8, light: 2, bulk: 1 };

// Сколько сверх необходимого освобождать за один проход вытеснения. Освобождать
// ровно столько, сколько нужно под текущий файл, — значит запускать вытеснение
// на каждой следующей записи; 12% дают запас на серию.
const ZALI_CACHE_EVICT_HEADROOM = 0.12;

ZaliMixin(ZaliInterface, class {

    // ============================================================
    // Настройки: режим и потолок
    // ============================================================

    // Настройка устройства, а не аккаунта: потолок кеша — про свободное место
    // на этой машине, и переживать переключение аккаунта он обязан.
    cachePrefsStorageKey() {
        return 'zali_cache_prefs_v1';
    }

    static get cacheModeCatalog() {
        return [
            {
                id: 'all',
                label: 'Кешировать всё',
                note: 'all',
                hint: 'Аватарки, ассеты серверов, профили, стикеры и любые вложения — включая видео и файлы.',
            },
            {
                id: 'light',
                label: 'Кешировать легковесное',
                note: 'default',
"""#,
    #"""
                hint: 'Всё необходимое плюс стикеры и медиа до 2 МБ. Тяжёлые вложения качаются заново.',
            },
            {
                id: 'essential',
                label: 'Кешировать необходимое',
                note: 'min',
                hint: 'Только аватарки, иконки и баннеры серверов и карточки профилей.',
            },
            {
                id: 'off',
                label: 'Не кешировать',
                note: 'off',
                hint: 'Ничего не хранится между запусками. Всё подгружается заново при каждом открытии.',
            },
        ];
    }

    // Остановки слайдера. Последняя — Infinity: «безлимитно» здесь означает
    // «клиент сам не вытесняет», а не «место бесконечно» — реальный потолок
    // тогда ставит браузерная квота, и запись, не влезшая в неё, всё равно
    // запускает вытеснение (см. cachePut).
    static get cacheLimitStops() {
        return [
            { bytes: 512 * 1024 * 1024, label: '512 МБ' },
            { bytes: 1024 * 1024 * 1024, label: '1 ГБ' },
            { bytes: 2 * 1024 * 1024 * 1024, label: '2 ГБ' },
            { bytes: 4 * 1024 * 1024 * 1024, label: '4 ГБ' },
            { bytes: 8 * 1024 * 1024 * 1024, label: '8 ГБ' },
            { bytes: 16 * 1024 * 1024 * 1024, label: '16 ГБ' },
            { bytes: Infinity, label: 'Без ограничения' },
        ];
    }

    static get defaultCacheMode() { return 'light'; }

    /** 2 ГБ — третья остановка. Индекс, а не значение: слайдер работает по индексу. */
    static get defaultCacheLimitIndex() { return 2; }

    normalizeCacheMode(value) {
        const id = String(value || '').trim().toLowerCase();
        return ZaliInterface.cacheModeCatalog.some(mode => mode.id === id)
            ? id
            : ZaliInterface.defaultCacheMode;
    }

    normalizeCacheLimitIndex(value) {
        // `null` отдельно от прочего мусора: Number(null) — это 0, то есть
        // самый маленький потолок. Отсутствующее значение в сохранённых
        // настройках должно давать значение ПО УМОЛЧАНИЮ, а не 512 МБ.
        if (value === null || value === undefined || value === '') {
            return ZaliInterface.defaultCacheLimitIndex;
        }
        const index = Number(value);
        if (!Number.isFinite(index)) return ZaliInterface.defaultCacheLimitIndex;
        const max = ZaliInterface.cacheLimitStops.length - 1;
        return Math.min(max, Math.max(0, Math.round(index)));
    }

    loadCachePrefs() {
        if (this._cachePrefs) return this._cachePrefs;
        let parsed = null;
        try {
            const raw = localStorage.getItem(this.cachePrefsStorageKey());
            parsed = raw ? JSON.parse(raw) : null;
        } catch (e) {
            parsed = null;
        }
        this._cachePrefs = {
            mode: this.normalizeCacheMode(parsed?.mode),
            limitIndex: this.normalizeCacheLimitIndex(
                parsed?.limitIndex === undefined ? ZaliInterface.defaultCacheLimitIndex : parsed.limitIndex,
            ),
        };
        return this._cachePrefs;
    }

    saveCachePrefs(partial = {}) {
        const current = this.loadCachePrefs();
        const next = {
            mode: partial.mode === undefined ? current.mode : this.normalizeCacheMode(partial.mode),
            limitIndex: partial.limitIndex === undefined
                ? current.limitIndex
                : this.normalizeCacheLimitIndex(partial.limitIndex),
        };
        const modeChanged = next.mode !== current.mode;
        const limitLowered = next.limitIndex < current.limitIndex;
        this._cachePrefs = next;
        try {
            localStorage.setItem(this.cachePrefsStorageKey(), JSON.stringify(next));
        } catch (e) {}
        this.trace(`saveCachePrefs mode=${next.mode} limit=${this.cacheLimitBytes()}`);
        // Ужесточение настройки применяется сразу, а не «когда-нибудь при
        // следующей записи»: человек, выкрутивший потолок с 16 ГБ до 512 МБ,
        // ждёт, что место освободится сейчас.
        if (next.mode === 'off') {
            void this.clearAssetCache();
        } else if (modeChanged || limitLowered) {
            void this.enforceCachePolicy();
        }
        this.renderCacheSettings();
        return next;
    }

    cacheMode() {
        return this.loadCachePrefs().mode;
    }

    cacheLimitBytes() {
        return ZaliInterface.cacheLimitStops[this.loadCachePrefs().limitIndex].bytes;
    }

    cacheLimitLabel() {
        return ZaliInterface.cacheLimitStops[this.loadCachePrefs().limitIndex].label;
    }

    // ============================================================
    // Политика: что вообще кладём на диск
    // ============================================================

    /**
     * Класс ассета. Определяет и вес при вытеснении, и режим, начиная с
     * которого ассет вообще попадает на диск.
     *   essential — маленькое и переиспользуемое на каждой отрисовке.
     *   light     — заметное, но всё ещё дешёвое.
     *   bulk      — тяжёлое, ради чего и существует потолок кеша.
     */
    cacheClassOf(kind, size = 0) {
        switch (kind) {
            case 'avatar':
            case 'server_asset':
            case 'profile':
                return 'essential';
            case 'sticker':
                return 'light';
            case 'attachment':
                return Number(size || 0) <= ZALI_CACHE_LIGHT_MAX_BYTES ? 'light' : 'bulk';
            default:
                return 'bulk';
        }
    }

    /** Пускает ли текущий режим ассет этого класса на диск. */
    cachePolicyAllows(kind, size = 0) {
        const mode = this.cacheMode();
        if (mode === 'off') return false;
        const cls = this.cacheClassOf(kind, size);
        if (mode === 'all') return true;
        if (mode === 'light') return cls !== 'bulk';
        return cls === 'essential';
    }

    // ============================================================
    // Хранилище
    // ============================================================

    /**
     * Ключ записи. Аккаунт входит в ключ, и это не перестраховка: список
     * контактов, состав серверов и карточки профилей — это то, с кем аккаунт
     * общается. Оставлять их видимыми следующему аккаунту на той же машине
     * незачем, а очистка по префиксу выходит бесплатной.
     */
    cacheEntryKey(kind, id) {
        const account = String(this.S?.session?.username || 'anon').trim().toLowerCase() || 'anon';
        return `${account}|${kind}|${String(id || '')}`;
    }

    cacheAccountPrefix() {
        const account = String(this.S?.session?.username || 'anon').trim().toLowerCase() || 'anon';
        return `${account}|`;
    }

    /**
     * Открывает базу ровно один раз за сессию и запоминает РЕЗУЛЬТАТ, включая
     * отказ: там, где IndexedDB закрыта origin'ом документа, open() бросает на
     * каждой попытке, и без запоминания клиент дёргал бы её на каждой аватарке.
     */
    ensureCacheStorage() {
        if (this._cacheReady) return this._cacheReady;
        this._cacheReady = (async () => {
            let db = null;
            try {
                db = await this.openCacheDb();
            } catch (e) {
                this.trace(`assetCache unavailable reason=${e?.name || e?.message || e}`);
                db = null;
            }
            if (!db) {
                this._cacheDisabledReason = 'IndexedDB недоступна в этой оболочке';
                this._cacheStats = new Map();
                this._cacheBytes = 0;
                return null;
            }
            this._cacheDb = db;
            await this.loadCacheStatIndex(db);
            return db;
        })();
        return this._cacheReady;
    }

    /**
     * То же самое, но с оглядкой на режим. Разделено намеренно: memo стоит на
     * ОТКРЫТИИ базы, а не на режиме, иначе выключение кеша в настройках
     * запоминало бы «базы нет» на весь сеанс, и обратное включение не
     * заработало бы до перезагрузки. Очистка и удаление базы, наоборот,
     * обязаны работать и при выключенном кеше — им нужно добраться до того,
     * что записали, пока он был включён.
     */
    ensureCacheReady() {
        if (this.cacheMode() === 'off') return Promise.resolve(null);
        return this.ensureCacheStorage();
    }

    /**
     * Открытие базы ОБЯЗАНО завершаться. Это не перестраховка — без таймаута
     * подсистема кеша умеет подвесить отрисовку.
     *
     * `indexedDB.open()` не даёт никаких гарантий по времени и не обязан
     * завершиться вообще: пока по этой базе висит незавершённый
     * `deleteDatabase()` (а он висит, пока хоть одна другая вкладка держит
     * соединение открытым), запрос на открытие просто ждёт — не `success`, не
     * `error`, и `blocked` тоже нет, потому что это событие только про смену
     * версии. Две вкладки веб-клиента — совершенно обычное дело, а
     * `destroyAssetCacheDatabase()` вызывается из конструктора при смене
     * localResetEpoch, то есть ровно в тот момент, когда вкладок может быть
     * несколько.
     *
     * Цена такого зависания непропорциональна: `ensureAvatarLoaded()` ждёт
     * `cacheGet()`, тот ждёт открытия базы — и промис аватарки не резолвится
     * НИКОГДА, оставаясь в `avatarRequests`. То есть аватарки перестают
     * грузиться совсем, включая сетевой путь, к которому кеш отношения не
     * имеет. Проверено вживую: `deleteDatabase` из второй вкладки → аватарка
     * висит в PENDING бесконечно.
     *
     * Поэтому: истёк таймаут — считаем, что диска нет, и работаем как на
     * платформе без IndexedDB. Соединение, если оно всё-таки откроется позже,
     * закрывается, чтобы не мешать чужому `deleteDatabase`.
     */
    openCacheDb() {
        return new Promise((resolve, reject) => {
            let request;
            try {
                if (!window.indexedDB) { resolve(null); return; }
                request = window.indexedDB.open(ZALI_CACHE_DB_NAME, ZALI_CACHE_DB_VERSION);
            } catch (e) {
                reject(e);
                return;
            }
            let done = false;
            const settle = (value) => {
                if (done) return;
                done = true;
                clearTimeout(timer);
                resolve(value);
            };
            const timer = setTimeout(() => {
                if (done) return;
                done = true;
                this.trace('assetCache open timed out — работаем без диска');
                // Опоздавшее соединение закрываем: держать его открытым значит
                // блокировать deleteDatabase той вкладки, которая нас и ждёт.
                request.onsuccess = () => { try { request.result.close(); } catch (e) {} };
                resolve(null);
            }, ZALI_CACHE_OPEN_TIMEOUT_MS);

            request.onupgradeneeded = () => {
                const db = request.result;
                if (!db.objectStoreNames.contains(ZALI_CACHE_BLOB_STORE)) {
                    db.createObjectStore(ZALI_CACHE_BLOB_STORE);
                }
                if (!db.objectStoreNames.contains(ZALI_CACHE_STAT_STORE)) {
                    db.createObjectStore(ZALI_CACHE_STAT_STORE);
                }
            };
            request.onsuccess = () => settle(request.result);
            request.onerror = () => {
                if (done) return;
                done = true;
                clearTimeout(timer);
                reject(request.error || new Error('indexedDB open failed'));
            };
            // Другая вкладка держит старую версию базы. Ждать нечего — работаем
            // без диска, но не висим на промисе вечно.
            request.onblocked = () => settle(null);
        });
    }

    /**
     * Весь индекс сводок — одним чтением. Это и есть «максимально ресурсно
     * оптимизированная сводка»: дальше ни одно обращение к кешу не читает с
     * диска ничего, кроме самого файла.
     */
    async loadCacheStatIndex(db) {
        const stats = new Map();
        let bytes = 0;
        try {
            const rows = await this.cacheIdbRequest(
                db.transaction(ZALI_CACHE_STAT_STORE, 'readonly').objectStore(ZALI_CACHE_STAT_STORE).getAll(),
            );
            for (const row of rows || []) {
                if (!row || !row.k) continue;
                stats.set(row.k, row);
                bytes += Number(row.s || 0);
            }
        } catch (e) {
            this.trace(`assetCache stat index read failed reason=${e?.name || e?.message || e}`);
        }
        this._cacheStats = stats;
        this._cacheBytes = bytes;
        this.trace(`assetCache ready entries=${stats.size} bytes=${bytes}`);
        return stats;
    }

    /** Промис вокруг IDBRequest — весь остальной файл говорит на async/await. */
    cacheIdbRequest(request) {
        return new Promise((resolve, reject) => {
            request.onsuccess = () => resolve(request.result);
            request.onerror = () => reject(request.error || new Error('indexedDB request failed'));
        });
    }

    cacheStats() {
        if (!this._cacheStats) this._cacheStats = new Map();
        return this._cacheStats;
    }

    cacheUsedBytes() {
        return Number(this._cacheBytes || 0);
    }

    // ============================================================
    // Чтение / запись
    // ============================================================

    /**
     * Достаёт файл и засчитывает обращение. Возвращает Blob или null.
     *
     * Обращение засчитывается ТОЛЬКО при попадании: промах — это не
     * использование файла, и накручивать им счётчик значило бы поднимать
     * ценность записи, которой в кеше нет.
     */
    async cacheGet(kind, id) {
        const db = await this.ensureCacheReady();
        if (!db) return null;
        const key = this.cacheEntryKey(kind, id);
        const stat = this.cacheStats().get(key);
        if (!stat) return null;
        try {
            const row = await this.cacheIdbRequest(
                db.transaction(ZALI_CACHE_BLOB_STORE, 'readonly').objectStore(ZALI_CACHE_BLOB_STORE).get(key),
            );
            if (!row || !row.b) {
                // Сводка есть, файла нет — рассинхрон после прерванной
                // транзакции. Чинится удалением сводки, иначе она вечно
                // занимает место в учёте и мешает вытеснению.
                this.cacheForgetStat(key, { purgeDisk: true });
                return null;
            }
            this.cacheNoteHit(key);
            return new Blob([row.b], { type: row.t || stat.t || 'application/octet-stream' });
        } catch (e) {
            this.trace(`cacheGet failed key=${key} reason=${e?.name || e?.message || e}`);
            return null;
        }
    }

    /**
     * Пакетное чтение — одна транзакция на весь набор.
     *
     * Прогрев поднимает до ZALI_CACHE_PRIME_LIMIT записей; отдельная
     * транзакция на каждую — это столько же обращений к движку хранилища, а в
     * WKWebView/WebView2 ещё и столько же переходов через границу процесса,
     * на самом старте приложения.
     *
     * Обращения здесь НЕ засчитываются, и это принципиально. Прогрев берёт
     * самые используемые записи — если бы он их же и повышал, счётчик
     * подтверждал бы сам себя: однажды популярная аватарка вечно попадала бы
     * в прогрев, вечно обновляла время обращения и никогда бы не устаревала,
     * даже если человек уже год с ней не разговаривает. Использование
     * засчитывает тот, кто действительно показывает картинку, —
     * cacheNoteAssetUse() из loadStoredAvatar()/loadServerAsset().
     */
    async cacheReadBatch(keys) {
        const out = new Map();
        const db = this._cacheDb;
        if (!db || !keys.length) return out;
        try {
            const tx = db.transaction(ZALI_CACHE_BLOB_STORE, 'readonly');
            const store = tx.objectStore(ZALI_CACHE_BLOB_STORE);
            const reads = keys.map(key => this.cacheIdbRequest(store.get(key)).then(row => [key, row]));
            const rows = await Promise.all(reads);
            for (const [key, row] of rows) {
                if (row && row.b) out.set(key, new Blob([row.b], { type: row.t || 'application/octet-stream' }));
                else this.cacheForgetStat(key, { purgeDisk: true });
            }
        } catch (e) {
            this.trace(`cacheReadBatch failed count=${keys.length} reason=${e?.name || e?.message || e}`);
        }
        return out;
    }

    /**
     * Засчитывает показ ассета — но не чаще раза в ZALI_CACHE_USE_WINDOW_MS
     * на ключ.
     *
     * Вызывается из loadStoredAvatar(), то есть из отрисовки каждой строки
     * контакта и каждой группы сообщений: считать там КАЖДЫЙ вызов значило бы
     * мерить не «как часто нужен файл», а «сколько раз перерисовался список»,
     * и одна прокрутка ленты дала бы аватарке больше обращений, чем все
     * вложения переписки вместе. Окно превращает это в понятную величину:
     * сколько минут работы приложения файл реально был на экране.
     *
     * Цена — одна проверка Set на пути, где уже есть проверка Map.
     */
    cacheNoteAssetUse(kind, id) {
        if (!this._cacheStats || !this._cacheStats.size) return;
        const now = Date.now();
        if (!this._cacheUseWindow || now - this._cacheUseWindowAt > ZALI_CACHE_USE_WINDOW_MS) {
            this._cacheUseWindow = new Set();
            this._cacheUseWindowAt = now;
        }
        const key = this.cacheEntryKey(kind, id);
        if (this._cacheUseWindow.has(key)) return;
        this._cacheUseWindow.add(key);
        this.cacheNoteHit(key);
    }

    /** Свежесть записи — для фоновой перепроверки. */
    cacheIsStale(kind, id, maxAgeMs = ZALI_CACHE_REVALIDATE_MS) {
        const stat = this.cacheStats().get(this.cacheEntryKey(kind, id));
        if (!stat) return true;
        return (Date.now() - Number(stat.c || 0)) > maxAgeMs;
    }

    /**
     * Кладёт файл. Молча ничего не делает, если политика его не пускает —
     * вызывающему не нужно знать про режимы.
     */
    async cachePut(kind, id, source, { contentType = '' } = {}) {
        const blob = await this.toCacheBlob(source, contentType);
        if (!blob || !blob.size) return false;
        if (!this.cachePolicyAllows(kind, blob.size)) return false;
        const db = await this.ensureCacheReady();
        if (!db) return false;

        const key = this.cacheEntryKey(kind, id);
        // Удаление того же ключа, начатое раньше, должно ЗАВЕРШИТЬСЯ раньше —
        // см. cacheDelete(). Обе операции фоновые, и без этого порядок решает
        // то, кому первым досталось открытое соединение.
        const pendingDelete = this._cachePendingDeletes?.get(key);
        if (pendingDelete) {
            try { await pendingDelete; } catch (e) {}
        }
        const previous = this.cacheStats().get(key);
        const delta = blob.size - Number(previous?.s || 0);
        // Освобождаем место ДО записи: запись, не влезающая в потолок, иначе
        // сначала превысила бы его, а потом сама себя и вытеснила.
        if (delta > 0) await this.cacheEvictFor(delta);

        let buffer;
        try {
            buffer = await this.blobToArrayBuffer(blob);
        } catch (e) {
            return false;
        }
        // ArrayBuffer, а не Blob: Blob в IndexedDB исторически ломался в
        // WKWebView, а буфер лежит везде одинаково. Тип хранится рядом.
        const row = { b: buffer, t: blob.type || contentType || 'application/octet-stream' };
        const now = Date.now();
        const stat = {
            k: key,
            s: blob.size,
            // Свежая запись стартует с одним обращением: файл, который только
            // что понадобился, уже один раз использован.
            h: Number(previous?.h || 0) + 1,
            u: now,
            c: now,
            g: this.cacheClassOf(kind, blob.size),
            n: kind,
            t: row.t,
        };

        const write = async () => {
            const tx = db.transaction([ZALI_CACHE_BLOB_STORE, ZALI_CACHE_STAT_STORE], 'readwrite');
            tx.objectStore(ZALI_CACHE_BLOB_STORE).put(row, key);
            tx.objectStore(ZALI_CACHE_STAT_STORE).put(stat, key);
            await this.cacheTransactionDone(tx);
        };

        try {
            await write();
        } catch (e) {
            // Квота браузера может оказаться меньше выбранного потолка (и
            // всегда меньше «без ограничения»). Один раз освобождаем заметную
            // долю и пробуем снова; второй отказ — просто не кешируем.
            const quota = e?.name === 'QuotaExceededError' || /quota/i.test(String(e?.message || ''));
            if (!quota) {
                this.trace(`cachePut failed key=${key} reason=${e?.name || e?.message || e}`);
                return false;
            }
            // ignoreLimit: место кончилось по квоте браузера, а не по нашему
            // потолку — при «Без ограничения» обычное вытеснение не сработало бы.
            await this.cacheEvictFor(
                Math.max(delta, Math.ceil(this.cacheUsedBytes() * 0.25)),
                { ignoreLimit: true },
            );
            try {
                await write();
            } catch (inner) {
                this.trace(`cachePut quota-bound key=${key} reason=${inner?.name || inner?.message || inner}`);
                return false;
            }
        }

        // Учёт сводится по ТЕКУЩЕМУ состоянию индекса, а не по delta, посчитанной
        // до await'ов. Между ними стоит cacheEvictFor(), и вытеснение вправе
        // выбрать жертвой ровно ту запись, которую мы сейчас перезаписываем, —
        // тогда cacheForgetStat() уже вычел её размер, и прибавление старой
        // delta теряет previous.s безвозвратно. Замер: 81920 против реальных
        // 92160 после одной такой перезаписи, и дрейф копится, пока индекс не
        // будет перечитан с диска, — то есть выбранный потолок молча превышается.
        const current = this.cacheStats().get(key);
        this._cacheBytes = Math.max(0, this.cacheUsedBytes() - Number(current?.s || 0)) + blob.size;
        this.cacheStats().set(key, stat);
        this.scheduleCacheSummaryRefresh();
        return true;
    }

    // Через ensureCacheStorage(), а не ensureCacheReady(): инвалидация обязана
    // доходить до диска и при выключенном кеше — иначе снятая аватарка
    // осталась бы лежать там до включения кеша обратно.
    //
    // Удаление регистрируется в _cachePendingDeletes, и cachePut() по тому же
    // ключу его дожидается. Иначе инвалидация и перезакачка — две несвязанные
    // фоновые операции: handleAvatarUpdated() вызывает clearStoredAvatar()
    // (delete) и тут же ensureAvatarLoaded(force) (put), а delete успевает
    // раньше открыть базу, то есть приходит ВТОРЫМ и стирает только что
    // сохранённую новую аватарку.
    async cacheDelete(kind, id) {
        const key = this.cacheEntryKey(kind, id);
        if (!this._cachePendingDeletes) this._cachePendingDeletes = new Map();
        const pending = (async () => {
            const db = await this.ensureCacheStorage();
            if (!db) return;
            await this.cacheDeleteKeys([key]);
        })();
        this._cachePendingDeletes.set(key, pending);
        try {
            await pending;
        } finally {
            if (this._cachePendingDeletes.get(key) === pending) {
                this._cachePendingDeletes.delete(key);
            }
        }
    }

    async cacheDeleteKeys(keys) {
        const db = this._cacheDb;
        if (!db || !keys.length) return;
        try {
            const tx = db.transaction([ZALI_CACHE_BLOB_STORE, ZALI_CACHE_STAT_STORE], 'readwrite');
            const blobs = tx.objectStore(ZALI_CACHE_BLOB_STORE);
            const stats = tx.objectStore(ZALI_CACHE_STAT_STORE);
            keys.forEach(key => { blobs.delete(key); stats.delete(key); });
            await this.cacheTransactionDone(tx);
        } catch (e) {
            this.trace(`cacheDeleteKeys failed count=${keys.length} reason=${e?.name || e?.message || e}`);
            return;
        }
        keys.forEach(key => this.cacheForgetStat(key));
        this.scheduleCacheSummaryRefresh();
    }

    /**
     * Забывает запись в памяти. `purgeDisk` — когда сводка осиротела (файла под
     * ней нет): без него строка остаётся в object store и на КАЖДОМ следующем
     * запуске снова попадает в индекс, продолжая занимать место в учёте и
     * вытеснять настоящие записи. Из cacheDeleteKeys() приходит false —
     * там строка уже удалена той же транзакцией.
     */
    cacheForgetStat(key, { purgeDisk = false } = {}) {
        const stat = this.cacheStats().get(key);
        if (!stat) return;
        this._cacheBytes = Math.max(0, this.cacheUsedBytes() - Number(stat.s || 0));
        this.cacheStats().delete(key);
        this._cacheDirtyStats?.delete(key);
        if (!purgeDisk || !this._cacheDb) return;
        try {
            const tx = this._cacheDb.transaction(ZALI_CACHE_STAT_STORE, 'readwrite');
            tx.objectStore(ZALI_CACHE_STAT_STORE).delete(key);
        } catch (e) {
            this.trace(`cacheForgetStat purge failed key=${key} reason=${e?.name || e?.message || e}`);
        }
    }

    cacheTransactionDone(tx) {
        return new Promise((resolve, reject) => {
            tx.oncomplete = () => resolve();
            tx.onerror = () => reject(tx.error || new Error('indexedDB transaction failed'));
            tx.onabort = () => reject(tx.error || new Error('indexedDB transaction aborted'));
        });
    }

    // ============================================================
    // Сводка обращений
    // ============================================================

    /**
     * Обращение к файлу. Самый горячий путь во всём кеше — поэтому здесь
     * НЕТ ни одной операции с диском: правится объект в памяти, ключ
     * попадает в дирти-набор, а запись уходит пачкой по таймеру.
     */
    cacheNoteHit(key) {
        const stat = this.cacheStats().get(key);
        if (!stat) return;
        stat.h = Number(stat.h || 0) + 1;
        stat.u = Date.now();
        if (!this._cacheDirtyStats) this._cacheDirtyStats = new Set();
        this._cacheDirtyStats.add(key);
        this.scheduleCacheStatFlush();
    }

    scheduleCacheStatFlush() {
        if (this._cacheStatFlushTimer) return;
        this._cacheStatFlushTimer = setTimeout(() => {
            this._cacheStatFlushTimer = null;
            void this.flushCacheStats();
        }, ZALI_CACHE_STAT_FLUSH_MS);
    }

    /** Пишет только изменившиеся сводки, одной транзакцией. */
    async flushCacheStats() {
        const dirty = this._cacheDirtyStats;
        if (!dirty || !dirty.size) return;
        const db = this._cacheDb;
        if (!db) { dirty.clear(); return; }
        // Снимаем ровно те ключи, что уносим (а не весь набор): обращения,
        // случившиеся во время самой записи, обязаны остаться дирти.
        const keys = Array.from(dirty);
        keys.forEach(key => dirty.delete(key));
        try {
            const tx = db.transaction(ZALI_CACHE_STAT_STORE, 'readwrite');
            const store = tx.objectStore(ZALI_CACHE_STAT_STORE);
            keys.forEach(key => {
                const stat = this.cacheStats().get(key);
                if (stat) store.put(stat, key);
            });
            await this.cacheTransactionDone(tx);
        } catch (e) {
            // Неудачная запись — не повод забыть, чем пользовались: счётчики
            // решают, кого вытеснять, и потерянная пачка занижает ценность
            // ровно тех файлов, которые человек и открывал. Возвращаем в
            // дирти-набор и пробуем следующим тиком.
            keys.forEach(key => { if (this.cacheStats().has(key)) dirty.add(key); });
            this.scheduleCacheStatFlush();
            this.trace(`flushCacheStats failed count=${keys.length} reason=${e?.name || e?.message || e}`);
        }
    }

    /**
     * Полезность записи — она же ответ на вопрос «кого выкинуть первым».
     *
     *   полезность = обращения × вес класса / размер в КБ
     *   счёт       = полезность / (1 + возраст обращения в днях)
     *
     * Три свойства, ради которых формула именно такая:
     *   - обращения в числителе: то, чем пользуются, остаётся (прямое
     *     требование — счётчики обращений решают, кого удалить);
     *   - деление на размер: аватарка в 8 КБ с двумя обращениями ценнее
     *     видео в 40 МБ с двумя обращениями, потому что за то же место
     *     помещаются пять тысяч аватарок;
     *   - старение: иначе запись, набравшая обращений полгода назад,
     *     держалась бы вечно и кеш застыл бы на прошлогоднем составе.
     */
    cacheEntryScore(stat, now = Date.now()) {
        const sizeKb = Math.max(1, Number(stat?.s || 0) / 1024);
        const weight = ZALI_CACHE_CLASS_WEIGHT[stat?.g] || 1;
        const hits = Math.max(1, Number(stat?.h || 1));
        const ageDays = Math.max(0, (now - Number(stat?.u || 0)) / 86400000);
        return (hits * weight) / sizeKb / (1 + ageDays);
    }

    /** Записи, отсортированные от наименее полезной к наиболее. */
    cacheEvictionOrder(now = Date.now()) {
        return Array.from(this.cacheStats().values())
            .map(stat => ({ stat, score: this.cacheEntryScore(stat, now) }))
            .sort((a, b) => a.score - b.score);
    }

    /**
     * Освобождает место под `needBytes`, выкидывая наименее полезное.
     *
     * `ignoreLimit` — для случая, когда место кончилось НЕ по нашему потолку, а
     * по квоте браузера. Без него ветка восстановления в cachePut() при
     * выбранном «Без ограничения» не освобождала ничего (потолок Infinity —
     * выходим первой же строкой) и повторяла байт-в-байт ту же запись, которая
     * только что упала: после первого QuotaExceededError кеш переставал
     * принимать что-либо до конца сеанса.
     */
    async cacheEvictFor(needBytes, { ignoreLimit = false } = {}) {
        const limit = this.cacheLimitBytes();
        const used = this.cacheUsedBytes();
        let over;
        if (ignoreLimit || !Number.isFinite(limit)) {
            // Освобождаем ровно столько, сколько попросили: ориентира в виде
            // потолка здесь нет.
            if (!ignoreLimit) return 0;
            over = Number(needBytes || 0);
            if (over <= 0) return 0;
        } else {
            over = (used + Number(needBytes || 0)) - limit;
            if (over <= 0) return 0;
            over += Math.ceil(limit * ZALI_CACHE_EVICT_HEADROOM);
        }

        const doomed = [];
        let freed = 0;
        for (const { stat } of this.cacheEvictionOrder()) {
            if (freed >= over) break;
            doomed.push(stat.k);
            freed += Number(stat.s || 0);
        }
        if (!doomed.length) return 0;
        this.trace(`cacheEvict entries=${doomed.length} freed=${freed} limit=${limit}`);
        await this.cacheDeleteKeys(doomed);
        return freed;
    }

    /**
     * Приводит кеш в соответствие с текущими настройками. Вызывается, когда
     * настройки ужесточили: сначала выкидывается всё, что новый режим больше
     * не пускает (класс записи уже посчитан и лежит в сводке — обходить
     * файлы не нужно), потом добивается потолок.
     */
    async enforceCachePolicy() {
        const db = await this.ensureCacheStorage();
        if (!db) return;
        const mode = this.cacheMode();
        if (mode === 'off') { await this.clearAssetCache(); return; }
        const forbidden = [];
        for (const stat of this.cacheStats().values()) {
            const allowed = mode === 'all'
                || (mode === 'light' && stat.g !== 'bulk')
                || (mode === 'essential' && stat.g === 'essential');
            if (!allowed) forbidden.push(stat.k);
        }
        if (forbidden.length) await this.cacheDeleteKeys(forbidden);
        await this.cacheEvictFor(0);
        this.renderCacheSettings();
    }

    /**
     * Сводка для настроек. Считается по индексу в памяти — ни одного чтения
     * с диска, поэтому её не страшно пересчитывать на каждой отрисовке.
     */
    cacheSummary({ topLimit = 12 } = {}) {
        const now = Date.now();
        const evictionOrder = this.cacheEvictionOrder(now);
        // Всё, что несёт ИМЯ, показывается только по текущему аккаунту. Метка
        // записи — это ключ без префикса, то есть логин собеседника: без
        // фильтра карточка настроек перечисляла бы контакты предыдущего
        // аккаунта на той же машине. Ровно от этого префикс в ключе и заведён
        // (см. cacheEntryKey). Суммарные же цифры остаются общими: место на
        // диске и потолок — device-wide, вытеснение ходит по всем записям, и
        // показать здесь только «свою» долю значило бы соврать о занятом месте.
        const prefix = this.cacheAccountPrefix();
        const isMine = (stat) => String(stat?.k || '').startsWith(prefix);
        const kinds = new Map();
        let hits = 0;
        let bytes = 0;
        const entries = [];
        for (const stat of this.cacheStats().values()) {
            const size = Number(stat.s || 0);
            const hit = Number(stat.h || 0);
            bytes += size;
            hits += hit;
            const bucket = kinds.get(stat.n) || { kind: stat.n, count: 0, bytes: 0, hits: 0 };
            bucket.count += 1;
            bucket.bytes += size;
            bucket.hits += hit;
            kinds.set(stat.n, bucket);
            entries.push(stat);
        }
        const top = entries
            .filter(isMine)
            .sort((a, b) => (Number(b.h || 0) - Number(a.h || 0)) || (Number(b.s || 0) - Number(a.s || 0)))
            .slice(0, Math.max(0, topLimit))
            .map(stat => ({
                key: stat.k,
                kind: stat.n,
                label: this.cacheEntryLabel(stat),
                hits: Number(stat.h || 0),
                size: Number(stat.s || 0),
                lastUsed: Number(stat.u || 0),
                score: this.cacheEntryScore(stat, now),
            }));
        return {
            available: !!this._cacheDb,
            // База открывается лениво, поэтому «ещё не открывали» и «открыть
            // не удалось» — разные состояния. Без этого различия карточка
            // настроек на первом кадре сообщала бы, что кеш не работает,
            // на платформе, где он работает прекрасно.
            probed: !!this._cacheReady,
            reason: this._cacheDisabledReason || '',
            count: entries.length,
            bytes,
            hits,
            limit: this.cacheLimitBytes(),
            mode: this.cacheMode(),
            kinds: Array.from(kinds.values()).sort((a, b) => b.bytes - a.bytes),
            top,
            // Следующий кандидат на вылет — самое понятное объяснение того,
            // как счётчики обращений влияют на кеш.
            nextEvicted: (() => {
                const next = evictionOrder.find(entry => isMine(entry.stat));
                return next ? this.cacheEntryLabel(next.stat) : '';
            })(),
            // Сколько из общего объёма занимают другие аккаунты этого
            // устройства — числом, без имён.
            foreignCount: entries.length - entries.filter(isMine).length,
        };
    }

    /** Человекочитаемое имя записи: ключ без служебного префикса аккаунта. */
    cacheEntryLabel(stat) {
        const key = String(stat?.k || '');
        const parts = key.split('|');
        return parts.length > 2 ? parts.slice(2).join('|') : key;
    }

    /**
     * Короткая метка вида в списке «чаще всего используются». Без неё аватарка
     * bob и карточка профиля bob — две разные записи с одинаковой подписью, и
     * список выглядит так, будто в нём дубликаты.
     */
    cacheEntryKindTag(kind) {
        switch (kind) {
            case 'avatar': return 'ава';
            case 'server_asset': return 'сервер';
            case 'profile': return 'профиль';
            case 'sticker': return 'стикер';
            case 'attachment': return 'файл';
            default: return 'прочее';
        }
    }

    cacheKindLabel(kind) {
        switch (kind) {
            case 'avatar': return 'Аватарки';
            case 'server_asset': return 'Иконки серверов';
            case 'profile': return 'Профили';
            case 'sticker': return 'Стикеры';
            case 'attachment': return 'Вложения';
            default: return String(kind || 'Прочее');
        }
    }

    async clearAssetCache() {
        const db = this._cacheDb || await this.ensureCacheStorage();
        this._cacheDirtyStats?.clear();
        if (db) {
            try {
                const tx = db.transaction([ZALI_CACHE_BLOB_STORE, ZALI_CACHE_STAT_STORE], 'readwrite');
                tx.objectStore(ZALI_CACHE_BLOB_STORE).clear();
                tx.objectStore(ZALI_CACHE_STAT_STORE).clear();
                await this.cacheTransactionDone(tx);
            } catch (e) {
                this.trace(`clearAssetCache failed reason=${e?.name || e?.message || e}`);
            }
        }
        this._cacheStats = new Map();
        this._cacheBytes = 0;
        this.renderCacheSettings();
    }

    /**
     * Полное удаление базы — для сброса локальных данных (localResetEpoch).
     * Отдельно от clearAssetCache(): там база остаётся открытой и рабочей,
     * здесь исчезает вместе со схемой.
     */
    destroyAssetCacheDatabase() {
        try {
            this._cacheDb?.close?.();
        } catch (e) {}
        this._cacheDb = null;
        this._cacheReady = null;
        this._cacheStats = new Map();
        this._cacheBytes = 0;
        try {
            const request = window.indexedDB?.deleteDatabase?.(ZALI_CACHE_DB_NAME);
            // Удаление блокируется, пока другая вкладка держит соединение, и
            // остаётся висеть — а висящее удаление подвешивает ЧУЖИЕ открытия
            // этой базы (см. openCacheDb). Помешать этому отсюда нельзя, но
            // молча такое расследовать невозможно.
            if (request) {
                request.onblocked = () => this.trace('assetCache delete blocked — база открыта в другой вкладке');
            }
        } catch (e) {}
    }

    // ============================================================
    // Преобразования
    // ============================================================

    async toCacheBlob(source, contentType = '') {
        if (!source) return null;
        if (typeof Blob !== 'undefined' && source instanceof Blob) return source;
        if (source instanceof ArrayBuffer) {
            return new Blob([source], { type: contentType || 'application/octet-stream' });
        }
        if (typeof source === 'string') {
            if (source.startsWith('data:')) return this.dataUrlToBlob(source);
            return new Blob([source], { type: contentType || 'text/plain' });
        }
        return null;
    }

    // Blob.arrayBuffer() есть везде, куда мы целимся, но FileReader страхует
    // старые WKWebView — эта ветка дешевле, чем выяснять версию Safari в
    // каждой оболочке.
    blobToArrayBuffer(blob) {
        if (typeof blob.arrayBuffer === 'function') return blob.arrayBuffer();
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => resolve(reader.result);
            reader.onerror = () => reject(reader.error || new Error('blob read failed'));
            reader.readAsArrayBuffer(blob);
        });
    }

    // ============================================================
    // Прогрев: ради него всё и затевалось
    // ============================================================

    /**
     * Поднимает аватарки и ассеты серверов с диска в память ДО первой
     * отрисовки. Это и есть ответ на «аватарки требуют подгрузки»: без
     * прогрева каждая из них ждала бы своего ensureAvatarLoaded(), то есть
     * сетевого ответа, и первый экран рисовался бы буквами-заглушками.
     *
     * Один проход, один набор транзакций, и только для текущего аккаунта.
     */
    async primeAssetCacheFromDisk() {
        const prefix = this.cacheAccountPrefix();
        // applySession() зовут на каждом применении сессии, включая повторные
        // с тем же аккаунтом. Прогрев — полный обход индекса, повторять его
        // на каждый вызов незачем: всё, что он поднял, уже в памяти.
        if (this._cachePrimedFor === prefix) return 0;
        const db = await this.ensureCacheReady();
        // Защёлка ставится ПОСЛЕ ответа базы. Раньше она стояла до await'а, и
        // один неудачный проход (открытие упёрлось в таймаут, потому что чужая
        // вкладка держит незавершённый deleteDatabase) навсегда отменял прогрев
        // для этого аккаунта — аватарки весь сеанс шли по сети, хотя база
        // открылась при следующем же cacheGet.
        if (!db) return 0;
        if (this._cachePrimedFor === prefix) return 0;
        this._cachePrimedFor = prefix;
        // Прогреваем самое используемое: если записей больше потолка, буквы
        // получат те, к кому обращаются реже всех.
        const candidates = Array.from(this.cacheStats().values())
            .filter(stat => String(stat.k || '').startsWith(prefix)
                && (stat.n === 'avatar' || stat.n === 'server_asset'))
            .sort((a, b) => Number(b.h || 0) - Number(a.h || 0))
            .slice(0, ZALI_CACHE_PRIME_LIMIT);
        if (!candidates.length) return 0;

        const wanted = candidates.filter(stat => {
            const id = String(stat.k).split('|').slice(2).join('|');
            if (!id) return false;
            return stat.n === 'avatar'
                ? !this.avatarCache.has(this.avatarCacheKey(id))
                : !this.serverAssetCache.has(id);
        });
        const blobs = await this.cacheReadBatch(wanted.map(stat => stat.k));

        let primed = 0;
        const stale = [];
        for (const stat of wanted) {
            const blob = blobs.get(stat.k);
            if (!blob) continue;
            const id = String(stat.k).split('|').slice(2).join('|');
            if (stat.n === 'avatar') {
                this.saveStoredAvatar(id, URL.createObjectURL(blob));
            } else {
                this.serverAssetCache.set(id, URL.createObjectURL(blob));
            }
            if (this.cacheIsStale(stat.n, id)) stale.push(stat);
            primed += 1;
        }
        if (primed) {
            this.trace(`primeAssetCacheFromDisk primed=${primed} stale=${stale.length}`);
            this.scheduleAvatarRefresh();
            this.scheduleServerAssetRefresh();
        }
        // Прогретую запись больше НИКТО не перепроверит, если не сделать этого
        // здесь: прогрев кладёт картинку прямо в avatarCache, после чего
        // loadStoredAvatar() возвращает значение, ensureAvatarLoaded() не
        // вызывается вовсе — а проверка свежести живёт только внутри неё.
        // То есть аватарка, поменянная, пока приложение было закрыто (события
        // avatar_updated не было и не будет), оставалась бы прошлогодней
        // навсегда. Фоновая перепроверка идёт после отрисовки: картинка уже
        // на экране, обновится под рукой.
        if (stale.length) this.revalidateStaleAssets(stale);
        return primed;
    }

    /** Фоновая перепроверка прогретых записей, у которых вышел срок. */
    revalidateStaleAssets(stats) {
        setTimeout(() => {
            for (const stat of stats) {
                const id = String(stat.k).split('|').slice(2).join('|');
                if (!id) continue;
                if (stat.n === 'avatar') {
                    void this.ensureAvatarLoaded(id, { force: true });
                    continue;
                }
                // Ключ ассета сервера — `${serverId}:${kind}`, а kind всегда
                // последний сегмент: id сервера сам может содержать ':'.
                const cut = id.lastIndexOf(':');
                if (cut <= 0) continue;
                void this.loadServerAsset(id.slice(0, cut), id.slice(cut + 1), { force: true });
            }
        }, 0);
    }

    /**
     * Досыпает вложения из кеша в уже загруженную историю. Работает после
     * восстановления истории, а не вместо него: loadStoredMessageCache()
     * синхронный, а диск — нет.
     *
     * Смысл в том, что localStorage перестаёт вмещать вложения задолго до
     * того, как переписка станет большой (см. writeMessageCacheToStorage —
     * там клиент переходит на копию без байтов). Раньше на Windows/iOS/Android
     * это означало «фотографии в истории превращаются в имена файлов
     * навсегда»; теперь байты лежат здесь.
     */
    async hydrateAttachmentPayloadsFromCache() {
        if (this.cacheMode() === 'off') return 0;
        // Обход всей истории — не то, что стоит делать дважды за сеанс на один
        // аккаунт: живая доставка приносит вложения уже с байтами.
        const prefix = this.cacheAccountPrefix();
        if (this._cacheHydratedFor === prefix) return 0;
        const db = await this.ensureCacheReady();
        // Защёлка — после ответа базы, по той же причине, что и в
        // primeAssetCacheFromDisk().
        if (!db) return 0;
        if (this._cacheHydratedFor === prefix) return 0;
        this._cacheHydratedFor = prefix;
        let restored = 0;
        for (const store of [this.S.chats, this.S.serverChats]) {
            for (const msgs of Object.values(store || {})) {
                for (const msg of msgs || []) {
                    const attachments = msg?.attachments || [];
                    if (!attachments.length) continue;
                    for (let index = 0; index < attachments.length; index += 1) {
                        const att = attachments[index];
                        if (!att || att.dataUrl || att.data_url) continue;
                        const id = this.attachmentCacheId(msg, att, index);
                        if (!id) continue;
                        const blob = await this.cacheGet(this.attachmentCacheKind(att), id);
                        if (!blob) continue;
                        att.dataUrl = await this.blobToDataUrl(blob);
                        restored += 1;
                    }
                }
            }
        }
        if (restored) {
            // Мемо normalizeAttachments() ключуется по строкам payload'ов и
            // само заметит подставленные байты — сбрасывать его не нужно.
            this.trace(`hydrateAttachmentPayloadsFromCache restored=${restored}`);
            this.scheduleRenderMessages();
        }
        return restored;
    }

    /**
     * Кладёт вложения в кеш. Идентичность записи — id сообщения + позиция +
     * имя: ровно тот же тройной ключ, по которому restoreAttachmentPayloads()
     * сверяет вложения, потому что отредактированное сообщение может нести
     * под тем же id другой набор файлов.
     */
    attachmentCacheId(msg, att, index) {
        const id = String(msg?.id || msg?.clientId || '').trim();
        if (!id) return '';
        return `${id}#${index}#${String(att?.name || '')}`;
    }

    /**
     * Вид записи для вложения — ОДНА функция на запись и на чтение.
     *
     * Вид входит в ключ (cacheEntryKey), поэтому расхождение здесь не роняет
     * ничего и не пишет в лог: стикер просто ложится под `sticker|…`, а
     * hydrateAttachmentPayloadsFromCache ищет его под `attachment|…` и не
     * находит — стикеры после перезагрузки остаются чипом с именем файла.
     * Вторая половина той же ошибки дороже: проверка «уже лежит» тоже
     * промахивается, поэтому каждый стикер архива переписывался на диск при
     * КАЖДОМ сохранении кеша сообщений — ровно та квадратичная работа на
     * горячем пути, которую эта проверка и должна была убрать.
     */
    attachmentCacheKind(att) {
        return att?.kind === 'sticker' ? 'sticker' : 'attachment';
    }

    /**
     * Сохраняет вложения сообщения. Ничего не читает с диска, чтобы понять,
     * лежит ли файл уже там: индекс сводок в памяти отвечает на это сразу,
     * а без такой проверки каждое сохранение кеша переписывало бы весь архив
     * заново (та самая «квадратичная работа на горячем пути»).
     */
    cacheStoreMessageAttachments(msg) {
        if (this.cacheMode() === 'off') return;
        const attachments = msg?.attachments || [];
        if (!attachments.length) return;
        attachments.forEach((att, index) => {
            const payload = att?.dataUrl || att?.data_url || '';
            if (!payload || !String(payload).startsWith('data:')) return;
            const id = this.attachmentCacheId(msg, att, index);
            if (!id) return;
            const kind = this.attachmentCacheKind(att);
            if (this.cacheStats().has(this.cacheEntryKey(kind, id))) return;
            void this.cachePut(kind, id, payload, { contentType: att.mimeType || '' });
        });
    }

    // Blob.text() — Safari 14+; FileReader страхует старые WKWebView так же,
    // как в blobToArrayBuffer().
    blobToText(blob) {
        if (typeof blob.text === 'function') return blob.text();
        return new Promise((resolve) => {
            try {
                const reader = new FileReader();
                reader.onload = () => resolve(String(reader.result || ''));
                reader.onerror = () => resolve('');
                reader.readAsText(blob);
            } catch (e) {
                resolve('');
            }
        });
    }

    blobToDataUrl(blob) {
        return new Promise((resolve) => {
            try {
                const reader = new FileReader();
                reader.onload = () => resolve(String(reader.result || ''));
                reader.onerror = () => resolve('');
                reader.readAsDataURL(blob);
            } catch (e) {
                resolve('');
            }
        });
    }

    // ============================================================
    // Отрисовка сводки в настройках
    // ============================================================

    // Сводка меняется на каждой записи в кеш, а карточка настроек чаще всего
    // не открыта. Поэтому перерисовка коалесцируется и сама проверяет, есть
    // ли кому смотреть.
    scheduleCacheSummaryRefresh() {
        if (this._cacheSummaryRefreshTimer) return;
        this._cacheSummaryRefreshTimer = setTimeout(() => {
            this._cacheSummaryRefreshTimer = null;
            // Перерисовка заменяет контейнер целиком, вместе со слайдером. Если
            // его сейчас тащат, новый элемент теряет захват указателя, и
            // значение отскакивает к сохранённому — незавершённый жест просто
            // пропадает. А поводов для перерисовки в этот момент сколько
            // угодно: любая запись в кеш (аватарки ещё догружаются) меняет
            // цифры в сводке, так что защита равенством html не спасает.
            if (this.cacheLimitSliderBusy()) {
                this.scheduleCacheSummaryRefresh();
                return;
            }
            this.renderCacheSettings();
        }, 600);
    }

    /** Тащат ли прямо сейчас слайдер потолка. */
    cacheLimitSliderBusy() {
        if (this._cacheLimitDragging) return true;
        const slider = document.getElementById('inputCacheLimit');
        return !!slider && document.activeElement === slider;
    }

    renderCacheSettings() {
        const host = document.getElementById('cacheSettings');
        if (!host) return;
        const prefs = this.loadCachePrefs();
        const summary = this.cacheSummary();

        const modes = ZaliInterface.cacheModeCatalog.map(mode => `
            <button type="button" class="cache-mode-option${mode.id === prefs.mode ? ' active' : ''}" data-cache-mode="${this.esc(mode.id)}" aria-pressed="${mode.id === prefs.mode}">
                <span class="cache-mode-copy">
                    <strong>${this.esc(mode.label)}</strong>
                    <small>${this.esc(mode.hint)}</small>
                </span>
                <span class="cache-mode-note">${this.esc(mode.note)}</span>
            </button>
        `).join('');

        const stops = ZaliInterface.cacheLimitStops
            .map((stop, index) => `<option value="${index}" label="${this.esc(stop.label)}"></option>`)
            .join('');

        const limitLabel = this.cacheLimitLabel();
        const usedLabel = this.formatFileSize(summary.bytes);
        const fill = Number.isFinite(summary.limit) && summary.limit > 0
            ? Math.min(100, Math.round((summary.bytes / summary.limit) * 100))
            : 0;

        const kinds = summary.kinds.length
            ? summary.kinds.map(bucket => `
                <li class="cache-kind-row">
                    <span class="cache-kind-name">${this.esc(this.cacheKindLabel(bucket.kind))}</span>
                    <span class="cache-kind-meta">${bucket.count} шт · ${this.esc(this.formatFileSize(bucket.bytes))} · ${bucket.hits} обр.</span>
                </li>
            `).join('')
            : '<li class="cache-kind-row cache-kind-row--empty">Кеш пуст</li>';

        const top = summary.top.length
            ? summary.top.map(entry => `
                <li class="cache-top-row">
                    <span class="cache-top-name" title="${this.esc(`${this.cacheKindLabel(entry.kind)}: ${entry.label}`)}"><span class="cache-top-kind">${this.esc(this.cacheEntryKindTag(entry.kind))}</span>${this.esc(entry.label)}</span>
                    <span class="cache-top-hits">${entry.hits}×</span>
                    <span class="cache-top-size">${this.esc(this.formatFileSize(entry.size))}</span>
                </li>
            `).join('')
            : '<li class="cache-top-row cache-top-row--empty">Обращений пока не было</li>';

        let status;
        if (summary.reason && !summary.available) {
            status = `Постоянный кеш недоступен: ${this.esc(summary.reason)}. Ассеты живут только до перезагрузки.`;
        } else if (prefs.mode === 'off') {
            status = 'Кеширование выключено — ассеты подгружаются заново при каждом открытии.';
        } else if (!summary.probed) {
            status = 'Кеш ещё не открывался в этом сеансе — сводка появится после первого обращения.';
        } else {
            const foreign = summary.foreignCount
                ? ` · из них ${summary.foreignCount} от других аккаунтов на этом устройстве`
                : '';
            status = `Занято ${this.esc(usedLabel)} из ${this.esc(limitLabel)} · ${summary.count} файлов · ${summary.hits} обращений${this.esc(foreign)}`;
        }

        const nextOut = summary.nextEvicted && prefs.mode !== 'off'
            ? `<p class="settings-help">Следующим освободит место: <code>${this.esc(summary.nextEvicted)}</code> — реже всего используется относительно своего размера.</p>`
            : '';

        const html = `
            <div class="cache-mode-options">${modes}</div>
            <label class="settings-field cache-limit-field">
                <span>Потолок кеша: <strong id="cacheLimitValue">${this.esc(limitLabel)}</strong></span>
                <input type="range" min="0" max="${ZaliInterface.cacheLimitStops.length - 1}" step="1" value="${prefs.limitIndex}" id="inputCacheLimit" class="settings-range" list="cacheLimitStops">
                <datalist id="cacheLimitStops">${stops}</datalist>
            </label>
            <div class="cache-usage-bar" role="presentation"><span style="width:${fill}%"></span></div>
            <p class="settings-help cache-usage-status">${status}</p>
            ${nextOut}
            <div class="cache-summary-grid">
                <div class="cache-summary-block">
                    <span class="settings-kicker">По типам</span>
                    <ul class="cache-kind-list">${kinds}</ul>
                </div>
                <div class="cache-summary-block">
                    <span class="settings-kicker">Чаще всего используются</span>
                    <ul class="cache-top-list">${top}</ul>
                </div>
            </div>
            <button class="btn-flat" id="cacheClearBtn" type="button">Очистить кеш</button>
        `;
        if (host.innerHTML !== html) host.innerHTML = html;
    }
});


// --- MODULE: interface/conversation_keys.js ---
// --- ZaliInterface: Реестр ключей разговоров и облачный vault-снапшот. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    conversationKeysStorageKey() {
        return `zali_conversation_keys_v2${this._userSuffix()}`;
    }

    cloudVaultSnapshotStorageKey() {
        return `zali_cloud_vault_snapshot_v2${this._userSuffix()}`;
    }

    vaultUnlockStorageKey() {
        return `zali_vault_unlock_v2${this._userSuffix()}`;
    }

    keyMaterialEpochStorageKey() {
        return `zali_key_material_epoch${this._userSuffix()}`;
    }

    vaultResetPendingStorageKey() {
        return `zali_vault_reset_pending_v2${this._userSuffix()}`;
    }

    vaultCloudSyncEnabledStorageKey() {
        return `zali_vault_cloud_sync_enabled_v1${this._userSuffix()}`;
    }

    // Scopes queued by resetEncryptionKeys that still owe the registry a forced claim.
    //
    // On disk, not in a Set on the instance. A reset queues every scope the account
    // holds, but each one is only claimed when that conversation is next resolved —
    // so quitting the app before every chat has been opened left the rest to make an
    // ordinary claim, lose to the pre-reset row, and go on asking the peer to
    // republish a key the user had deliberately thrown away. The reset silently did
    // not apply to exactly the conversations the user had not visited.
    forceClaimScopesStorageKey() {
        return `zali_force_claim_scopes_v1${this._userSuffix()}`;
    }

    // Per-scope timestamp of the first time the registry named a key this device
    // could not obtain. See requestStaleCanonicalTakeover for what it is for; it
    // lives on disk because the window it measures is longer than a session.
    staleCanonicalStorageKey() {
        return `zali_stale_canonical_v1${this._userSuffix()}`;
    }

    /// A claim must have been unobtainable for at least this long before this device
    /// offers to take the scope over. Deliberately generous: the point is to outlast
    /// every transient reason a republish can come up empty — the holder being asleep,
    /// offline, mid-reinstall, or simply not having opened the app today.
    static get STALE_CANONICAL_TAKEOVER_MS() { return 15 * 60 * 1000; }

    /// ...and at least this many separate failed attempts. See markStaleCanonical:
    /// the window alone would let one stale visit an hour after another take over a
    /// conversation that is working perfectly well for everyone else.
    static get STALE_CANONICAL_MIN_ATTEMPTS() { return 3; }

    /// Most candidate keys one republish answer may carry. `alt:` entries accumulate
    /// for the life of a conversation and nothing prunes them, while each candidate
    /// costs an envelope POST per device of every participant — so an unbounded
    /// answer turns one request into a fan-out proportional to the whole key history.
    /// Candidates come back newest-first (active key, then alts in insertion order),
    /// which is the order a requester is most likely to need.
    static get MAX_REPUBLISH_CANDIDATES() { return 6; }

    /// Most keys tried against one archive before giving up. Every candidate that does
    /// not fit costs two PBKDF2-SHA256 passes at 210 000 iterations (the archive
    /// session key, then the body), charged per message — so an account that has
    /// accumulated dozens of `alt:` keys was spending seconds of CPU on each
    /// unreadable message, and repeating it on every refresh. Kept identical to the
    /// native shells (`Coordinator.maxDecryptCandidates`, `MAX_DECRYPT_CANDIDATES`).
    static get MAX_DECRYPT_CANDIDATES() { return 12; }

    loadScopeMarkMap(storageKey) {
        try {
            const raw = localStorage.getItem(storageKey);
            if (!raw) return {};
            const parsed = JSON.parse(raw);
            return parsed && typeof parsed === 'object' ? parsed : {};
        } catch (e) {
            return {};
        }
    }

    saveScopeMarkMap(storageKey, map) {
        try {
            const entries = Object.entries(map || {});
            if (!entries.length) localStorage.removeItem(storageKey);
            else localStorage.setItem(storageKey, JSON.stringify(Object.fromEntries(entries)));
        } catch (e) {}
    }

    queueForceClaimScopes(scopes = []) {
        const map = this.loadScopeMarkMap(this.forceClaimScopesStorageKey());
        for (const scope of scopes) {
            const scoped = String(scope || '').trim();
            if (scoped) map[scoped] = Date.now();
        }
        this.saveScopeMarkMap(this.forceClaimScopesStorageKey(), map);
    }

    // Reads and clears in one step: a forced claim is a one-shot instruction, and
    // leaving it queued would keep overwriting the registry on every later resolve.
    consumeForceClaimScope(scope) {
        const scoped = String(scope || '').trim();
        if (!scoped) return false;
        const map = this.loadScopeMarkMap(this.forceClaimScopesStorageKey());
        if (!Object.prototype.hasOwnProperty.call(map, scoped)) return false;
        delete map[scoped];
        this.saveScopeMarkMap(this.forceClaimScopesStorageKey(), map);
        return true;
    }

    // Records that the canonical key for `scope` is still unobtainable, and reports
    // whether this device has now earned the right to take the scope over.
    //
    // Two conditions, both required, because either alone gives false positives:
    //
    //  * the window. Elapsed time since the FIRST failure, so a peer that is merely
    //    asleep, offline or mid-reinstall gets a long grace period;
    //  * the attempt count. Time alone is not evidence of anything — open a chat
    //    once, come back an hour later, and a single fresh failure would look
    //    "15 minutes old" and hijack a conversation that was never broken. Only a
    //    scope that keeps failing, across separate attempts, is genuinely stuck.
    markStaleCanonical(scope) {
        const scoped = String(scope || '').trim();
        if (!scoped) return false;
        const key = this.staleCanonicalStorageKey();
        const map = this.loadScopeMarkMap(key);
        const now = Date.now();
        const entry = map[scoped] && typeof map[scoped] === 'object' ? map[scoped] : null;
        // Number = the pre-attempt-count format. Treated as one attempt so an
        // upgrade in the middle of a stuck scope does not reset its progress.
        const legacyFirst = typeof map[scoped] === 'number' ? Number(map[scoped]) : 0;
        let first = Number(entry?.first || legacyFirst || 0);
        let attempts = Number(entry?.attempts || (legacyFirst ? 1 : 0));
        // A clock that moved backwards (or a stored value from the future) would
        // otherwise pin this scope as "not stale yet" forever.
        if (!first || first > now) first = now;
        attempts += 1;
        map[scoped] = { first, attempts };
        this.saveScopeMarkMap(key, map);
        return (now - first) >= ZaliInterface.STALE_CANONICAL_TAKEOVER_MS
            && attempts >= ZaliInterface.STALE_CANONICAL_MIN_ATTEMPTS;
    }

    clearStaleCanonical(scope) {
        const scoped = String(scope || '').trim();
        if (!scoped) return;
        const map = this.loadScopeMarkMap(this.staleCanonicalStorageKey());
        if (!Object.prototype.hasOwnProperty.call(map, scoped)) return;
        delete map[scoped];
        this.saveScopeMarkMap(this.staleCanonicalStorageKey(), map);
    }

    loadVaultCloudSyncEnabled() {
        try {
            const raw = localStorage.getItem(this.vaultCloudSyncEnabledStorageKey());
            if (raw == null) return false;
            return String(raw).trim().toLowerCase() !== 'false';
        } catch (e) {
            return false;
        }
    }

    saveVaultCloudSyncEnabled(enabled) {
        try {
            localStorage.setItem(this.vaultCloudSyncEnabledStorageKey(), enabled ? 'true' : 'false');
        } catch (e) {}
    }

    applyVaultCloudSyncEnabled(enabled, { persistLocal = true } = {}) {
        const next = !!enabled;
        this.S.auth.cloudVaultSyncEnabled = next;
        if (persistLocal) {
            this.saveVaultCloudSyncEnabled(next);
        }
        this.renderVaultCloudSyncControls();
        this.updateAuthView();
    }

    isVaultCloudSyncEnabled() {
        return !!this.S.auth?.cloudVaultSyncEnabled;
    }

    async saveAccountVaultCloudSyncEnabled(enabled) {
        if (!this.S.session?.token) return false;
        try {
            const res = await this.apiFetch(this.apiRoutes.auth.me, {
                method: 'PATCH',
                body: JSON.stringify({ cloudVaultSyncEnabled: !!enabled }),
            });
            if (!res.ok) {
                throw new Error(await res.text().catch(() => 'Не удалось сохранить настройку'));
            }
            const data = await res.json().catch(() => null);
            if (data && typeof data.cloudVaultSyncEnabled !== 'undefined') {
                this.applyVaultCloudSyncEnabled(!!data.cloudVaultSyncEnabled, { persistLocal: true });
            }
            return true;
        } catch (e) {
            this.trace(`saveAccountVaultCloudSyncEnabled failed error=${e?.message || e}`);
            this.S.auth.error = e?.message || 'Не удалось сохранить настройку облачной синхронизации ключей';
            this.updateAuthView();
            return false;
        }
    }

    async setVaultCloudSyncEnabled(enabled) {
        const next = !!enabled;
        const previous = this.isVaultCloudSyncEnabled();
        this.applyVaultCloudSyncEnabled(next, { persistLocal: true });
        if (this.S.session?.token) {
            const ok = await this.saveAccountVaultCloudSyncEnabled(next);
            if (!ok) {
                this.applyVaultCloudSyncEnabled(previous, { persistLocal: true });
                return;
            }
        }
        if (this.cloudVaultSyncTimer) {
            clearTimeout(this.cloudVaultSyncTimer);
            this.cloudVaultSyncTimer = 0;
        }
        if (this.S.auth.cloudVaultSyncEnabled && this.S.session?.token && this.S.auth?.vaultPassphrase) {
            void this.syncCloudVaultPackage({ passphrase: this.S.auth.vaultPassphrase, reason: 'vault-sync-enabled' });
        }
    }

    renderVaultCloudSyncControls() {
        const checkbox = document.getElementById('inputVaultCloudSyncEnabled');
        if (checkbox) {
            checkbox.checked = this.isVaultCloudSyncEnabled();
        }
    }

    // Canonical form of a conversation scope.
    //
    // The scope string used to be built from whatever casing the caller happened
    // to hold — a contact typed by hand, a username off a message, a roster entry
    // — while the registry, the envelope table and the server's participant check
    // all compare it byte-exactly. One differently-cased character therefore
    // forked a conversation into two scopes that could never converge: separate
    // registry claims, separate envelope buckets, and a 403 from the server for
    // whichever side held the mis-cased form (its own username no longer matches
    // either participant). Production carried both `dm:pivovarca:zalikus` and
    // `dm:Pivovarca:zalikus` in the registry although only `Pivovarca` exists as
    // an account, plus scopes naming users that never existed at all.
    //
    // `server:` scopes are left alone: their ids come from the server, so every
    // participant already derives the identical string.
    canonicalConversationScope(scope) {
        const value = String(scope || '').trim();
        if (!value.startsWith('dm:')) return value;
        const parts = value.split(':');
        if (parts.length !== 3) return value;
        const a = parts[1].trim().toLowerCase();
        const b = parts[2].trim().toLowerCase();
        if (!a || !b) return value;
        // Sorted on the lowercased form, not merely lowercased after sorting:
        // `Zulu` sorts before `test` by UTF-16 code unit but after it once
        // lowercased, so sorting the original casing would leave the participant
        // order itself case-dependent.
        return `dm:${[a, b].sort().join(':')}`;
    }

    // Scopes are canonically lowercased, but the API addresses users by their real
    // casing (`users.username` is a case-sensitive primary key), so a name taken
    // back out of a scope must be mapped to the casing the server knows before it
    // can be used in a request path.
    resolveKnownUsernameCasing(username) {
        const value = String(username || '').trim();
        if (!value) return '';
        const lower = value.toLowerCase();
        const me = String(this.myName() || '').trim();
        if (me && me.toLowerCase() === lower) return me;
        for (const pool of [this.S.contacts, this.S.users]) {
            if (!Array.isArray(pool)) continue;
            const hit = pool.find(item => String(item || '').trim().toLowerCase() === lower);
            if (hit) return String(hit).trim();
        }
        return value;
    }

    conversationScopeKey(peer = null, serverId = null, channelId = null) {
        const sid = String(serverId || '').trim();
        const cid = String(channelId || '').trim();
        if (sid && cid) {
            return `server:${sid}:${cid}`;
        }
        const me = String(this.myName() || '').trim();
        const other = String(peer || this.S.current || '').trim();
        if (!me || !other) return '';
        return this.canonicalConversationScope(`dm:${me}:${other}`);
    }

    isServerChannelScope(scope) {
        return /^server:[^:]+:.+$/.test(String(scope || '').trim());
    }

    // Ключ канала сервера ВЫВОДИТСЯ из его scope, а не разыгрывается случайно.
    //
    // Раньше канал жил по той же схеме, что и личная переписка: первый открывший
    // придумывал случайный ключ и рассылал его остальным участникам конвертами
    // ECDH, по одному на устройство. Для диалога двоих это работает, для канала —
    // нет: доставка конверта зависит от того, зарегистрировано ли устройство
    // получателя, дошёл ли до него конверт и не придумал ли он тем временем свой
    // ключ. На практике читать канал могли ровно те двое, у кого обмен случайно
    // сошёлся, а остальные видели «Зашифрованное сообщение недоступно».
    //
    // Теперь ключ = SHA-256 от префикса и scope. Его одинаково и мгновенно
    // вычисляет каждый участник, локально, без сети, без конвертов, без реестра —
    // и новый участник читает всю историю канала сразу, ничего не запрашивая.
    //
    // Плата названа прямо: это НЕ сквозное шифрование. Кто знает id сервера и
    // канала — знает и ключ, а сервер их знает по определению. Шифрование здесь
    // защищает архив в покое и на транспорте, но не от самого сервера. Для личных
    // переписок (`dm:`) всё остаётся как было — там сквозной обмен ключами имеет
    // смысл и работает.
    async deriveServerChannelKey(scope) {
        const scoped = String(scope || '').trim();
        if (!this.isServerChannelScope(scoped)) return '';
        if (!this._derivedChannelKeys) this._derivedChannelKeys = new Map();
        const cached = this._derivedChannelKeys.get(scoped);
        if (cached) return cached;
        const material = new TextEncoder().encode(`zali-channel-key-v1:${scoped}`);
        const digest = await crypto.subtle.digest('SHA-256', material);
        const key = this.base64FromBytes(new Uint8Array(digest))
            .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
        this._derivedChannelKeys.set(scoped, key);
        return key;
    }

    // Делает выводимый ключ активным для канала. Прежний случайный ключ не
    // выбрасывается, а уезжает в кандидаты (`alt:`) — иначе история, зашифрованная
    // до перехода, стала бы нечитаемой на этом же устройстве.
    async adoptDerivedChannelKey({ scope, serverId = null, channelId = null, reason = 'auto' } = {}) {
        const scoped = String(scope || '').trim();
        const derived = await this.deriveServerChannelKey(scoped);
        if (!derived) return '';
        let changed = false;
        await this.withConversationKeysWriteLock(() => {
            const stored = this.loadStoredConversationKeys();
            if (this.setActiveConversationKey(stored, scoped, derived)) {
                this.saveStoredConversationKeys(stored);
                changed = true;
            }
        });
        if (changed) this.trace(`adoptDerivedChannelKey reason=${reason} scope=${scoped} switched=true`);
        this.setKey(derived);
        this.syncNativeConversationKeys();
        this.updateCryptoKeyDisplay({ key: derived, serverId, channelId });
        return derived;
    }

    dmScopeOwner(scope) {
        // For a DM scope `dm:a:b` (participants sorted), the lexicographically
        // smaller participant is the canonical owner of the conversation key.
        // Lowercased, like the scope itself — compare it case-insensitively.
        const parts = String(scope || '').split(':');
        if (parts[0] !== 'dm') return '';
        return String(parts[1] || '').trim().toLowerCase();
    }

    addAltConversationKey(stored, scope, key) {
        // Store a non-active conversation key so it still appears in the candidate
        // pool used for decryption (native tries every value of the keys map), while
        // leaving stored[scope] — the active key used for sending — untouched.
        const value = String(key || '').trim();
        if (!value || !scope) return false;
        if (String(stored[scope] || '').trim() === value) return false;
        // Map key embeds the value, so re-adding the same key is idempotent.
        const altKey = `alt:${scope}:${value}`;
        if (Object.prototype.hasOwnProperty.call(stored, altKey)) return false;
        stored[altKey] = value;
        return true;
    }

    // Switches the active (sending) key for a scope while keeping the outgoing one
    // in the candidate pool.
    //
    // Every adoption site used to do this by hand as
    //     addAltConversationKey(stored, scope, current); stored[scope] = next;
    // which silently dropped `current` every single time: at that moment
    // stored[scope] IS current, so addAltConversationKey's "already the active key"
    // guard returned false without storing anything, and the next line overwrote it.
    // The device then could not decrypt its own already-sent messages — the exact
    // «перебрано ключей N (ни один не подошёл)» symptom, produced by the very code
    // meant to prevent it. Doing the demotion in one place makes the order
    // impossible to get wrong again.
    setActiveConversationKey(stored, scope, nextKey) {
        const scoped = String(scope || '').trim();
        const next = String(nextKey || '').trim();
        if (!scoped || !next) return false;
        const current = String(stored[scoped] || '').trim();
        if (current === next) return false;
        stored[scoped] = next;
        if (current) this.addAltConversationKey(stored, scoped, current);
        return true;
    }

    // ---------------------------------------------------------------------
    // Canonical conversation-key registry (server-backed, see
    // server/src/conversation_keys.rs).
    //
    // Historically "which key is the real one for this conversation" had no
    // answer anywhere: whoever opened a chat with an empty local key store
    // invented a random key and started encrypting with it, and convergence was
    // attempted after the fact with a lexicographic-owner tiebreak that did not
    // apply to channels at all. The registry replaces guessing with a fact: the
    // first claim for a scope wins, everyone else can see they hold the wrong
    // key and ask for a republish instead of silently forking the conversation.
    //
    // Only a SHA-256 fingerprint of the key ever leaves the device.
    // ---------------------------------------------------------------------

    async conversationKeyId(key) {
        const value = String(key || '').trim();
        if (!value) return '';
        if (!this._keyIdCache) this._keyIdCache = new Map();
        const cached = this._keyIdCache.get(value);
        if (cached) return cached;
        const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(value));
        const id = this.base64FromBytes(new Uint8Array(digest))
            .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
        this._keyIdCache.set(value, id);
        return id;
    }

    canonicalKeyIdCache() {
        if (!this._canonicalKeyIds) this._canonicalKeyIds = new Map();
        return this._canonicalKeyIds;
    }

    // Serializes read-modify-write cycles over the conversation-key store.
    //
    // promoteCanonicalConversationKey is fired in the background (not awaited)
    // from several places at once — resolveConversationCryptoKey for every chat
    // that already has a key, and reconcileVaultScopes after a vault sync. Each
    // call does loadStoredConversationKeys() → mutate → saveStoredConversationKeys(),
    // and without serializing them, two concurrent calls for different scopes can
    // race: the second one's load can miss the first one's not-yet-saved write,
    // and its save then clobbers it. The lost update is a promotion, not real key
    // material — self-heals on the next resolve/sync — but there is no reason to
    // leave the race in when queuing the callback is nearly free.
    withConversationKeysWriteLock(fn) {
        const previous = this._conversationKeysWriteLock || Promise.resolve();
        const run = previous.then(fn, fn);
        this._conversationKeysWriteLock = run.catch(() => {});
        return run;
    }

    // Every key this device could decrypt with for a scope: the active one plus
    // every `alt:` candidate. Used to promote an already-held key to active once
    // the registry tells us which one is canonical.
    conversationKeyCandidates(stored, scope) {
        const scoped = String(scope || '').trim();
        if (!scoped) return [];
        const out = [];
        const push = (value) => {
            const key = String(value || '').trim();
            if (key && !out.includes(key)) out.push(key);
        };
        push(stored[scoped]);
        const prefix = `alt:${scoped}:`;
        for (const [name, value] of Object.entries(stored || {})) {
            if (name.startsWith(prefix)) push(value);
        }
        return out;
    }

    // `allowCached` is opt-in and deliberately off by default: every other caller
    // uses this to decide whether a local key is a fork, and a stale answer there
    // is worse than a request. It exists for the decrypt-failure reporter, which
    // asks about the same scope once per undecryptable message on screen — one
    // batched lookup up front, then cache hits for the rest of the batch.
    async fetchCanonicalKeyIds(scopes = [], { allowCached = false } = {}) {
        const list = Array.from(new Set(
            (Array.isArray(scopes) ? scopes : [scopes])
                .map(scope => String(scope || '').trim())
                .filter(Boolean)
        )).slice(0, 200);
        if (!list.length || !this.S.session?.token) return new Map();
        if (allowCached) {
            const cache = this.canonicalKeyIdCache();
            if (list.every(scope => cache.has(scope))) return cache;
        }
        try {
            const res = await this.apiFetch(this.apiRoutes.conversationKeys.lookup(list.join(',')), { includeDeviceId: true });
            if (!res.ok) throw new Error(await res.text().catch(() => 'lookup failed'));
            const rows = await res.json();
            const cache = this.canonicalKeyIdCache();
            if (Array.isArray(rows)) {
                for (const row of rows) {
                    const scope = String(row?.scope || '').trim();
                    const keyId = String(row?.keyId || '').trim();
                    if (scope && keyId) cache.set(scope, keyId);
                }
            }
            // The answer arrived, so for these scopes "not in the cache" now means
            // "the registry has no claim", not "we could not ask". Callers must not
            // have to guess between the two: an absent entry looks identical either
            // way, and a caller deciding whether it is safe to stop waiting for a key
            // needs to know which it is. See canonicalLookupSucceeded.
            for (const scope of list) this.canonicalLookupAnswered().add(scope);
            return cache;
        } catch (e) {
            // A failed lookup must never be read as "no canonical key exists" —
            // that is exactly the mistake that made clients invent keys. Callers
            // check `has(scope)`, and an absent entry means "unknown", not "none".
            this.trace(`fetchCanonicalKeyIds failed error=${e?.message || e}`);
            for (const scope of list) this.canonicalLookupAnswered().delete(scope);
            return this.canonicalKeyIdCache();
        }
    }

    /// Scopes whose most recent registry lookup actually reached the server.
    ///
    /// Tracked as successes rather than failures on purpose: the default for a scope
    /// nobody has asked about must be "we do not know", and a set of failures would
    /// have made it "answered, and the answer was no claim" — the reading that lets a
    /// client stop waiting for a key it never asked about. Bounded by the number of
    /// scopes an account has.
    canonicalLookupAnswered() {
        if (!this._canonicalLookupAnswered) this._canonicalLookupAnswered = new Set();
        return this._canonicalLookupAnswered;
    }

    /// True when the last lookup for `scope` actually reached the server — so an
    /// empty answer really does mean "nobody has claimed this conversation".
    canonicalLookupSucceeded(scope) {
        const scoped = String(scope || '').trim();
        if (!scoped) return false;
        return this.canonicalLookupAnswered().has(scoped);
    }

    // Returns { keyId, mine, claimedBy } or null when the claim could not be made.
    // `mine === false` means another device already owns this scope's key and the
    // caller is holding a fork.
    async claimConversationKey(scope, key, { force = false, takeover = false, reason = 'auto' } = {}) {
        const scoped = String(scope || '').trim();
        const secret = String(key || '').trim();
        if (!scoped || !secret || !this.S.session?.token) return null;
        try {
            const keyId = await this.conversationKeyId(secret);
            const res = await this.apiFetch(this.apiRoutes.conversationKeys.claim, {
                method: 'POST',
                includeDeviceId: true,
                body: JSON.stringify({ scope: scoped, keyId, force: !!force, takeover: !!takeover }),
            });
            if (!res.ok) throw new Error(await res.text().catch(() => 'claim failed'));
            const data = await res.json();
            const winner = String(data?.keyId || '').trim();
            if (winner) this.canonicalKeyIdCache().set(scoped, winner);
            this.trace(`claimConversationKey reason=${reason} scope=${scoped} mine=${!!data?.mine} claimedBy=${data?.claimedBy || ''}`);
            return { keyId: winner, mine: !!data?.mine, claimedBy: String(data?.claimedBy || '') };
        } catch (e) {
            this.trace(`claimConversationKey failed reason=${reason} scope=${scoped} error=${e?.message || e}`);
            return null;
        }
    }

    async requestKeyRepublish(scope, { reason = 'auto' } = {}) {
        const scoped = String(scope || '').trim();
        if (!scoped || !this.S.session?.token) return false;
        try {
            const res = await this.apiFetch(this.apiRoutes.conversationKeys.republish, {
                method: 'POST',
                includeDeviceId: true,
                body: JSON.stringify({ scope: scoped }),
            });
            if (!res.ok) throw new Error(await res.text().catch(() => 'republish request failed'));
            this.trace(`requestKeyRepublish reason=${reason} scope=${scoped}`);
            return true;
        } catch (e) {
            this.trace(`requestKeyRepublish failed reason=${reason} scope=${scoped} error=${e?.message || e}`);
            return false;
        }
    }

    // If one of the keys this device already holds for `scope` matches the
    // canonical key id, make it the active (sending) key. Returns the promoted
    // key, or '' when none of the local candidates is the canonical one.
    async promoteCanonicalConversationKey(scope, canonicalKeyId, { reason = 'auto' } = {}) {
        const scoped = String(scope || '').trim();
        const wanted = String(canonicalKeyId || '').trim();
        if (!scoped || !wanted) return '';
        // See withConversationKeysWriteLock: this fires unawaited from several
        // places at once, so its load-mutate-save must not race a concurrent call
        // for a different scope.
        return this.withConversationKeysWriteLock(async () => {
            const stored = this.loadStoredConversationKeys();
            const active = String(stored[scoped] || '').trim();
            if (active && await this.conversationKeyId(active) === wanted) return active;
            for (const candidate of this.conversationKeyCandidates(stored, scoped)) {
                if (await this.conversationKeyId(candidate) !== wanted) continue;
                this.setActiveConversationKey(stored, scoped, candidate);
                this.saveStoredConversationKeys(stored);
                this.trace(`promoteCanonicalConversationKey reason=${reason} scope=${scoped} promoted=true`);
                return candidate;
            }
            return '';
        });
    }

    // Reconcile the local active key for a scope with the server registry.
    // Returns the key that should be used for sending.
    async reconcileConversationKey(scope, localKey, { reason = 'auto' } = {}) {
        const scoped = String(scope || '').trim();
        const local = String(localKey || '').trim();
        if (!scoped || !local) return local;
        // У каналов канонический ключ не выбирается и не регистрируется: он выводится
        // из scope (см. deriveServerChannelKey), одинаков у всех и спорить о нём не с
        // кем. Заявка в реестр здесь только создавала бы гонку с самой собой.
        if (this.isServerChannelScope(scoped)) return local;
        // A scope queued by resetEncryptionKeys takes the registry over by force —
        // the user explicitly asked for new keys, so the old claim must not win.
        const force = this.consumeForceClaimScope(scoped);
        const claim = await this.claimConversationKey(scoped, local, { reason, force });
        if (!claim || claim.mine) {
            this.clearStaleCanonical(scoped);
            return local;
        }

        // Someone else claimed this scope first. Prefer a key we already hold
        // that matches, otherwise ask the holders to republish an envelope for
        // this device and pick it up on the next sync.
        const promoted = await this.promoteCanonicalConversationKey(scoped, claim.keyId, { reason });
        if (promoted) {
            this.clearStaleCanonical(scoped);
            this.setKey(promoted);
            this.updateCryptoKeyDisplay({ key: promoted });
            return promoted;
        }
        await this.requestKeyRepublish(scoped, { reason });
        await this.syncIncomingKeyEnvelopes({ reason: `reconcile:${reason}`, triggerRefresh: false });
        const afterSync = await this.promoteCanonicalConversationKey(scoped, claim.keyId, { reason: `${reason}:afterSync` });
        if (afterSync) {
            this.clearStaleCanonical(scoped);
            this.setKey(afterSync);
            this.updateCryptoKeyDisplay({ key: afterSync });
            return afterSync;
        }

        // Nothing we hold matches and asking the holders produced nothing. That is
        // normally transient, so it is only recorded here — but it can also be
        // permanent, and there was no path out of the permanent case at all.
        const takenOver = await this.requestStaleCanonicalTakeover(scoped, local, { reason });
        if (takenOver) return takenOver;

        // Still missing. Keep sending with the local key rather than blocking the
        // user — the peer stores every incoming envelope key as a decryption
        // candidate, so these messages stay readable on their side — and keep the
        // scope marked so a later sync can still promote the canonical key.
        this.addLogEntry({
            type: 'WARN',
            msg: `Канонический ключ диалога ещё не получен (scope=${scoped}), запрошена повторная публикация`,
            ts: new Date().toLocaleTimeString(),
        });
        return local;
    }

    // Last resort for a registry row that names a key nobody can supply any more.
    //
    // A `conversation_key_registry` row outlives the key material it fingerprints.
    // Reinstall on both sides of a DM, or wipe the one device that ever held a
    // channel key, and every participant is left claiming, failing to promote,
    // asking for a republish nobody can answer, and falling back to its own locally
    // invented key — forever, because the only way to replace a row was the user
    // pressing "сбросить ключи шифрования". Reproduced: two DM devices and three
    // channel members each kept a different active key indefinitely, readable only
    // through `alt:` candidates, with the union of live keys — and therefore the
    // PBKDF2 cost of every undecryptable message — growing on each new device.
    //
    // Which side decides what is split on purpose:
    //
    // * this device decides the claim is *unreachable*, because only it knows it
    //   asked, waited and synced with nothing to show. The mark is persisted and
    //   must be older than STALE_CANONICAL_TAKEOVER_MS, so a peer that is merely
    //   asleep, offline or mid-reinstall never triggers this;
    // * the server decides *who wins* (see STALE_CLAIM_TAKEOVER in
    //   conversation_keys.rs): the first takeover in its window replaces the row and
    //   refreshes `updated_at`, so simultaneous claimants are refused and handed the
    //   winner's key id instead. That is what makes this converge instead of
    //   ping-ponging between participants.
    //
    // Nothing becomes unreadable either way: the displaced key stays a decryption
    // candidate on every device that held it.
    async requestStaleCanonicalTakeover(scope, localKey, { reason = 'auto' } = {}) {
        const scoped = String(scope || '').trim();
        const local = String(localKey || '').trim();
        if (!scoped || !local) return '';
        if (!this.markStaleCanonical(scoped)) return '';

        const taken = await this.claimConversationKey(scoped, local, {
            reason: `${reason}:takeover`,
            takeover: true,
        });
        if (!taken) return '';

        if (taken.mine) {
            this.clearStaleCanonical(scoped);
            this.addLogEntry({
                type: 'WARN',
                msg: `Прежний ключ разговора недоступен ни у кого, зарегистрирован новый (scope=${scoped})`,
                ts: new Date().toLocaleTimeString(),
            });
            // The takeover only means the registry now names a key that exists. It
            // still has to reach everyone, or the next device to reconcile would find
            // the very same situation and take the scope over again.
            void this.publishConversationKeyToOwnDevices({ scope: scoped, key: local, reason: `takeover:${reason}` });
            const channel = this.channelFromConversationScope(scoped);
            if (channel) {
                void this.publishConversationKeyToServerMembers({
                    serverId: channel.serverId,
                    channelId: channel.channelId,
                    scope: scoped,
                    key: local,
                    reason: `takeover:${reason}`,
                });
            } else {
                const peer = this.peerFromConversationScope(scoped);
                if (peer) void this.publishConversationKeyToPeer({ peer, scope: scoped, key: local, reason: `takeover:${reason}` });
            }
            return local;
        }

        // Someone else won the window. Their key is the canonical one now, and it is
        // reachable by definition — they hold it — so adopt it if it already arrived.
        const adopted = await this.promoteCanonicalConversationKey(scoped, taken.keyId, { reason: `${reason}:takeoverLost` });
        if (adopted) {
            this.clearStaleCanonical(scoped);
            this.setKey(adopted);
            this.updateCryptoKeyDisplay({ key: adopted });
            return adopted;
        }
        // Not here yet — ask, and let the next reconcile pick it up. The mark stays
        // set, but the winner's fresh `updated_at` means the server refuses another
        // takeover for a full window, which is what gives convergence time to happen.
        await this.requestKeyRepublish(scoped, { reason: `${reason}:takeoverLost` });
        return '';
    }

    keyEnvelopeOverridesLocal(scope, payload) {
        // Only the canonical owner's envelope may replace an existing local key.
        // The owner always keeps its own key; the non-owner adopts the owner's,
        // so both peers converge on a single key regardless of who generated
        // a key first (otherwise each side keeps its own and decryption fails).
        const owner = this.dmScopeOwner(scope);
        if (!owner) return false;
        // Both sides lowercased: the owner comes out of a canonical scope, while
        // myName()/payload.sender carry the account's real casing.
        const me = String(this.myName() || '').trim().toLowerCase();
        const sender = String(payload?.sender || '').trim().toLowerCase();
        return sender === owner && me !== owner;
    }

    // Fold legacy, differently-cased scope strings onto their canonical form.
    //
    // Applied on every load rather than once: a legacy-cased scope can arrive at
    // any time from the cloud vault or from a peer still running a client that
    // predates canonicalConversationScope, and a key filed under a scope nobody
    // looks up any more is a key that has been silently lost.
    canonicalizeConversationKeyScopes(map) {
        const source = map && typeof map === 'object' ? map : {};
        const out = {};
        const demoted = [];
        for (const [rawScope, rawValue] of Object.entries(source)) {
            const value = String(rawValue || '').trim();
            if (!value) continue;
            const scope = String(rawScope || '');
            if (scope.startsWith('alt:')) {
                // `alt:<scope>:<value>`; both scope kinds are exactly 3 segments and
                // the value is base64url, so it never contributes a colon. The map
                // key embeds the value, so it is rebuilt rather than renamed.
                const parts = scope.split(':');
                const rebuilt = `alt:${this.canonicalConversationScope(parts.slice(1, 4).join(':'))}:${value}`;
                out[rebuilt] = value;
                continue;
            }
            const canonical = this.canonicalConversationScope(scope);
            if (!Object.prototype.hasOwnProperty.call(out, canonical)) {
                out[canonical] = value;
            } else if (out[canonical] !== value) {
                // Two casings of one conversation each carried a key. Neither may be
                // dropped: whichever loses the active slot still decrypts whatever
                // history was written under it, so it survives as a candidate.
                demoted.push([canonical, value]);
            }
        }
        for (const [canonical, value] of demoted) {
            this.addAltConversationKey(out, canonical, value);
        }
        return out;
    }

    loadStoredConversationKeys() {
        try {
            // No fallback to the legacy unsuffixed 'zali_conversation_keys_v2' key — see
            // the comment in loadStoredMessageCache() for why: this one is the most
            // severe case, since it would hand a brand-new account every per-DM E2E key
            // a previous, unrelated account on this browser ever had.
            // Both stores are read AND merged, never one-or-the-other. Conversation
            // keys used to live in sessionStorage with localStorage actively deleted
            // on every save, which meant every browser/PWA restart (and every native
            // shell without a key-injection bridge — iOS and Android have none) came
            // up with an empty key map. An empty map is indistinguishable from "this
            // conversation has no key yet", so the client invented a fresh random key
            // and encrypted real messages with it. Losing key material is strictly
            // worse than storing it at rest in a store the same origin already owns.
            const readStore = (store) => {
                try {
                    const raw = store.getItem(this.conversationKeysStorageKey());
                    if (!raw) return null;
                    const parsed = JSON.parse(raw);
                    return parsed && typeof parsed === 'object' ? parsed : null;
                } catch (e) {
                    return null;
                }
            };
            const injected = this.injectedMaterialMatchesAccount() && window.__ZALI_CONVERSATION_KEYS && typeof window.__ZALI_CONVERSATION_KEYS === 'object'
                ? window.__ZALI_CONVERSATION_KEYS
                : {};
            const persisted = readStore(localStorage);
            const session = readStore(sessionStorage);
            if (!persisted && !session) return this.canonicalizeConversationKeyScopes(injected);
            // sessionStorage last: within one session it is the freshest writer.
            const merged = this.canonicalizeConversationKeyScopes({
                ...injected,
                ...(persisted || {}),
                ...(session || {}),
            });
            // Write back ONLY when the merge actually produced something different.
            //
            // This is a read path with ~30 call sites, several of them inside render
            // and send, and it used to serialise the whole key map and write it to both
            // stores on every single call — two synchronous localStorage writes per
            // read, for a result that is normally byte-identical to what is already
            // there. The write still has to happen when it changes something (a legacy
            // scope folded onto its canonical form, or one store ahead of the other),
            // because a key filed under a name nobody looks up is a key that is lost.
            try {
                const encoded = JSON.stringify(merged || {});
                if (encoded !== this._lastConversationKeysEncoded) {
                    sessionStorage.setItem(this.conversationKeysStorageKey(), encoded);
                    localStorage.setItem(this.conversationKeysStorageKey(), encoded);
                    this._lastConversationKeysEncoded = encoded;
                }
            } catch (e) {}
            return merged && typeof merged === 'object' ? merged : {};
        } catch (e) {
            return {};
        }
    }

    getStoredConversationKey(scope) {
        const key = String(scope || '').trim();
        if (!key) return '';
        const stored = this.loadStoredConversationKeys();
        return String(stored[key] || '').trim();
    }

    syncNativeConversationKeys(keys = null) {
        if (!this.nativeSupports('setKey')) return;
        const conversationKeys = keys && typeof keys === 'object' ? keys : this.loadStoredConversationKeys();
        const scope = String(window.__ZALI_ACTIVE_CONVERSATION_SCOPE || this.activeConversationScope || '').trim();
        const key = scope
            ? String(conversationKeys[scope] || '').trim()
            : String(sessionStorage.getItem(this.cryptoKeyStorageKey()) || localStorage.getItem(this.cryptoKeyStorageKey()) || '').trim();
        let signature = '';
        try {
            signature = JSON.stringify({
                scope,
                key,
                conversationKeys: Object.keys(conversationKeys || {}).sort().reduce((acc, itemKey) => {
                    acc[itemKey] = String(conversationKeys[itemKey] || '').trim();
                    return acc;
                }, {}),
            });
        } catch (e) {
            signature = `${scope}:${key}:${Object.keys(conversationKeys || {}).length}`;
        }
        if (signature && signature === this.lastNativeConversationKeySignature) {
            return;
        }
        this.lastNativeConversationKeySignature = signature;
        this.postNativeMessage({
            type: NativeMessageTypes.SET_KEY,
            key,
            scope,
            conversationKeys,
        });
    }

    saveStoredConversationKeys(keys) {
        try {
            const encoded = JSON.stringify(keys || {});
            sessionStorage.setItem(this.conversationKeysStorageKey(), encoded);
            // Durable copy — see loadStoredConversationKeys() for why dropping this
            // was the single largest source of "сообщение зашифровано не тем ключом".
            localStorage.setItem(this.conversationKeysStorageKey(), encoded);
            // Keeps the read path's write-back guard honest about what is on disk.
            this._lastConversationKeysEncoded = encoded;
            this.syncNativeConversationKeys(keys || {});
            if (this.S.session?.token && this.S.auth?.vaultPassphrase && !this.cloudVaultSyncInFlight) {
                this.scheduleCloudVaultSync(300);
            }
        } catch (e) {}
    }

    clearLegacyKeyMaterial() {
        try {
            if (localStorage.getItem(this.keyMaterialEpochStorageKey()) === '2') return;
            [
                'zali_crypto_key_v1',
                'zali_conversation_keys_v1',
                'zali_cloud_vault_snapshot_v1',
                'zali_vault_unlock_v1',
            ].forEach(key => {
                try { localStorage.removeItem(key); } catch (e) {}
                try { sessionStorage.removeItem(key); } catch (e) {}
            });
            try { window.__ZALI_SAVED_KEY = ''; } catch (e) {}
            try { window.__ZALI_CONVERSATION_KEYS = {}; } catch (e) {}
            localStorage.setItem(this.vaultResetPendingStorageKey(), 'true');
            localStorage.setItem(this.keyMaterialEpochStorageKey(), '2');
            this.trace('clearLegacyKeyMaterial epoch=2 legacy_keys_cleared=true');
        } catch (e) {
            this.trace(`clearLegacyKeyMaterial failed error=${e?.message || e}`);
        }
    }

    async ensureServerVaultReset({ reason = 'auto' } = {}) {
        if (!this.S.session?.token) return false;
        try {
            if (localStorage.getItem(this.vaultResetPendingStorageKey()) !== 'true') return false;
            const res = await this.apiFetch(this.apiRoutes.vault.events, { method: 'DELETE' });
            if (!res.ok) {
                throw new Error(await res.text().catch(() => 'Не удалось очистить server vault'));
            }
            localStorage.removeItem(this.vaultResetPendingStorageKey());
            this.trace(`ensureServerVaultReset reason=${reason} cleared=true`);
            return true;
        } catch (e) {
            this.trace(`ensureServerVaultReset failed reason=${reason} error=${e?.message || e}`);
            return false;
        }
    }

    async encryptCloudVaultSnapshot(payload, secret) {
        const salt = new Uint8Array(16);
        const iv = new Uint8Array(12);
        crypto.getRandomValues(salt);
        crypto.getRandomValues(iv);
        const key = await this.deriveVaultAesKey(secret, salt);
        const plain = new TextEncoder().encode(JSON.stringify(payload || {}));
        const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, plain);
        return JSON.stringify({
            v: 1,
            kdf: 'PBKDF2-SHA256',
            iterations: 210000,
            aead: 'AES-256-GCM',
            salt: this.base64FromBytes(salt),
            iv: this.base64FromBytes(iv),
            ciphertext: this.base64FromBytes(ciphertext),
        });
    }

    async decryptCloudVaultSnapshot(packageText, secret) {
        const raw = String(packageText || '').trim();
        if (!raw) return null;
        const envelope = JSON.parse(raw);
        if (envelope.v !== 1) throw new Error('Unsupported vault version');
        if (typeof envelope.iterations === 'number' && envelope.iterations < 100000) {
            throw new Error('Vault KDF iterations too low');
        }
        const salt = this.bytesFromBase64(envelope.salt);
        const iv = this.bytesFromBase64(envelope.iv);
        const ciphertext = this.bytesFromBase64(envelope.ciphertext);
        const key = await this.deriveVaultAesKey(secret, salt);
        const plain = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, ciphertext);
        return JSON.parse(new TextDecoder().decode(new Uint8Array(plain)));
    }

    async saveCloudVaultSnapshot(payload, secret = null) {
        const token = String(secret || this.S.session?.token || '').trim();
        if (!token || !payload || typeof payload !== 'object') return false;
        try {
            const encrypted = await this.encryptCloudVaultSnapshot(payload, token);
            localStorage.setItem(this.cloudVaultSnapshotStorageKey(), encrypted);
            this._vaultSnapshotApplied = false; // invalidate cache so next restore re-decrypts
            return true;
        } catch (e) {
            this.trace(`saveCloudVaultSnapshot error=${e?.message || e}`);
            return false;
        }
    }

    async encryptVaultUnlockSecret(secret, token) {
        const passphrase = String(secret || '').trim();
        const guard = String(token || '').trim();
        if (!passphrase || !guard) return '';
        const salt = new Uint8Array(16);
        const iv = new Uint8Array(12);
        crypto.getRandomValues(salt);
        crypto.getRandomValues(iv);
        const key = await this.deriveVaultAesKey(guard, salt);
        const plain = new TextEncoder().encode(passphrase);
        const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, plain);
        return JSON.stringify({
            v: 1,
            kdf: 'PBKDF2-SHA256',
            iterations: 210000,
            aead: 'AES-256-GCM',
            salt: this.base64FromBytes(salt),
            iv: this.base64FromBytes(iv),
            ciphertext: this.base64FromBytes(ciphertext),
        });
    }

    async decryptVaultUnlockSecret(raw, token) {
        const guard = String(token || '').trim();
        const encoded = String(raw || '').trim();
        if (!guard || !encoded) return '';
        const envelope = JSON.parse(encoded);
        if (envelope.v !== 1) throw new Error('Unsupported vault version');
        if (typeof envelope.iterations === 'number' && envelope.iterations < 100000) {
            throw new Error('Vault KDF iterations too low');
        }
        const salt = this.bytesFromBase64(envelope.salt);
        const iv = this.bytesFromBase64(envelope.iv);
        const ciphertext = this.bytesFromBase64(envelope.ciphertext);
        const key = await this.deriveVaultAesKey(guard, salt);
        const plain = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, ciphertext);
        return new TextDecoder().decode(new Uint8Array(plain)).trim();
    }

    async saveVaultUnlockSecret(secret, token = null) {
        const passphrase = String(secret || '').trim();
        const guard = String(token || this.S.session?.token || '').trim();
        try {
            if (!passphrase || !guard) {
                localStorage.removeItem(this.vaultUnlockStorageKey());
                return false;
            }
            const encrypted = await this.encryptVaultUnlockSecret(passphrase, guard);
            localStorage.setItem(this.vaultUnlockStorageKey(), encrypted);
            return true;
        } catch (e) {
            this.trace(`saveVaultUnlockSecret error=${e?.message || e}`);
            return false;
        }
    }

    async loadVaultUnlockSecret(token = null) {
        const guard = String(token || this.S.session?.token || '').trim();
        if (!guard) return '';
        try {
            const raw = localStorage.getItem(this.vaultUnlockStorageKey());
            if (!raw) return '';
            return await this.decryptVaultUnlockSecret(raw, guard);
        } catch (e) {
            // Both this blob and the local vault snapshot are sealed with the session
            // JWT, and a password login mints a new one — so after a re-login the
            // stored copy is undecryptable for good. It used to be retried, and fail,
            // on every launch forever, with nothing but a trace to show for it. Drop
            // it: the caller then falls back to the network, and the password login
            // path re-saves a fresh copy under the new token.
            this.trace(`loadVaultUnlockSecret error=${e?.message || e} dropped=true`);
            try { localStorage.removeItem(this.vaultUnlockStorageKey()); } catch (err) {}
            return '';
        }
    }

    async restoreCloudVaultSnapshot({ reason = 'auto' } = {}) {
        const token = String(this.S.session?.token || '').trim();
        if (!token) return false;
        // Skip if already applied this session (vault snapshot doesn't change until saveCloudVaultSnapshot)
        if (this._vaultSnapshotApplied) return false;
        // Deduplicate concurrent calls — only one PBKDF2 derivation at a time
        if (this._restoreVaultInFlight) return this._restoreVaultInFlight;
        this._restoreVaultInFlight = (async () => {
            try {
                const raw = localStorage.getItem(this.cloudVaultSnapshotStorageKey());
                if (!raw) return false;
                const payload = await this.decryptCloudVaultSnapshot(raw, token);
                const count = this.applyVaultPlainPayload(payload);
                this.trace(`restoreCloudVaultSnapshot reason=${reason} count=${count}`);
                if (count >= 0) this._vaultSnapshotApplied = true;
                return count > 0;
            } catch (e) {
                // Sealed with the session JWT, which a password login rotates — so a
                // snapshot written before the last re-login can never be opened again.
                // Silently failing left this device paying a PBKDF2 derivation on every
                // cold start for a blob that was already dead. Drop it and let the
                // network path repopulate it.
                this.trace(`restoreCloudVaultSnapshot failed reason=${reason} error=${e?.message || e} dropped=true`);
                try { localStorage.removeItem(this.cloudVaultSnapshotStorageKey()); } catch (err) {}
                return false;
            } finally {
                this._restoreVaultInFlight = null;
            }
        })();
        return this._restoreVaultInFlight;
    }
});


// --- MODULE: interface/key_resolution.js ---
// --- ZaliInterface: Разрешение ключа разговора, идентичность устройства, крипто-примитивы конвертов и vault. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    async resolveConversationCryptoKey({ peer = null, serverId = null, channelId = null, reason = 'auto' } = {}) {
        const scope = this.conversationScopeKey(peer, serverId, channelId);
        if (!scope) return '';
        if (!this._resolveKeyInFlight) this._resolveKeyInFlight = new Map();
        if (this._resolveKeyInFlight.has(scope)) return this._resolveKeyInFlight.get(scope);
        const promise = this._resolveConversationCryptoKeyImpl({ peer, serverId, channelId, reason });
        this._resolveKeyInFlight.set(scope, promise);
        try { return await promise; } finally { this._resolveKeyInFlight.delete(scope); }
    }

    async _resolveConversationCryptoKeyImpl({ peer = null, serverId = null, channelId = null, reason = 'auto' } = {}) {
        const scope = this.conversationScopeKey(peer, serverId, channelId);
        if (!scope) return '';
        this.activeConversationScope = scope;
        try {
            window.__ZALI_ACTIVE_CONVERSATION_SCOPE = scope;
        } catch (e) {}

        // Канал сервера не проходит ничего из того, что ниже: ни реестр, ни конверты,
        // ни ожидание чужого ключа, ни генерацию случайного. Его ключ выводится из
        // scope и потому уже есть у каждого участника (см. deriveServerChannelKey).
        if (this.isServerChannelScope(scope)) {
            return await this.adoptDerivedChannelKey({ scope, serverId, channelId, reason });
        }

        const existing = this.getStoredConversationKey(scope);
        if (existing) {
            this.syncNativeConversationKeys();
            this.updateCryptoKeyDisplay({
                key: existing,
                peer,
                serverId,
                channelId,
            });
            // Reconcile with the server registry in the background: a key that is
            // present locally can still be a fork invented by this device before
            // the real one arrived. Not awaited — a stale-but-working key must not
            // delay opening the chat.
            void this.reconcileConversationKey(scope, existing, { reason: `existing:${reason}` });
            return existing;
        }

        if (this.S.session?.token) {
            const recoveredVaultPassphrase = this.S.auth?.vaultPassphrase || await this.loadVaultUnlockSecret(this.S.session.token);
            if (recoveredVaultPassphrase) {
                this.S.auth.vaultPassphrase = recoveredVaultPassphrase;
                await this.restoreCloudVaultSnapshot({ reason: `resolveConversationCryptoKey:${reason}` });
                // restoreCloudVaultSnapshot читает только локальный кэш — на свежем
                // устройстве он пуст, а фоновый sync из postAuthSetup ещё не успел
                // сходить в облако. Без этого await ключ генерировался временным,
                // хотя настоящий уже лежал в cloud vault (гонка на ~1 секунду).
                if (!this.getStoredConversationKey(scope) && !this._cloudVaultResolveFetchDone) {
                    this._cloudVaultResolveFetchDone = true;
                    await this.syncCloudVaultPackage({ passphrase: recoveredVaultPassphrase, reason: `resolveConversationCryptoKey:${reason}` });
                }
            }
            await this.syncIncomingKeyEnvelopes({ reason: `resolveConversationCryptoKey:${reason}`, triggerRefresh: false });

            // A timed-out/dropped vault or envelope fetch above looks identical to "this
            // conversation genuinely has no key yet" — both just leave the scope unresolved.
            // That distinction matters a lot here: inventing a local key below is NOT
            // reversible — it gets published to the peer as the new canonical key, silently
            // orphaning the real key (and all history encrypted under it) that a slower
            // network round-trip would have found. So retry a couple of times with backoff
            // before giving up, instead of inventing on the very first empty result.
            // Does a canonical key already exist for this scope? If so, inventing
            // one here would be strictly wrong — the answer is to make the holders
            // republish an envelope for this device, not to fork the conversation.
            await this.fetchCanonicalKeyIds([scope]);
            const knownCanonical = this.canonicalKeyIdCache().get(scope) || '';
            if (knownCanonical) {
                const promoted = await this.promoteCanonicalConversationKey(scope, knownCanonical, { reason });
                if (!promoted) await this.requestKeyRepublish(scope, { reason });
            }

            // Wait only when there is something to wait FOR.
            //
            // This used to sleep 1.5 s and then 3 s unconditionally, with a vault sync
            // and an envelope sync inside each round — up to 4.5 s of dead time plus
            // six round trips, awaited on the path that opens a chat and on the path
            // that sends a message. The reason for waiting at all is sound and stays:
            // inventing a key here is irreversible, it gets published as the scope's
            // key, and doing that because a slow round trip had not landed yet orphans
            // the real key along with every message under it.
            //
            // But that risk only exists when a key we do not have might be out there.
            // The registry answers exactly that question, and it has already been asked
            // above: `knownCanonical` set means somebody holds a key for this scope, so
            // waiting is warranted. Empty means the lookup succeeded and found no claim
            // — nothing to lose the race to — and the retries were pure latency.
            //
            // A FAILED lookup is not "no claim": fetchCanonicalKeyIds returns its cache
            // on error and an absent entry means "unknown". That case is treated as
            // worth waiting for, same as a known claim.
            //
            // Which is why this asks canonicalLookupSucceeded() rather than looking at
            // the cache: an absent cache entry is produced BOTH by "the registry has no
            // claim" and by "we never got an answer", so testing the cache would have
            // reported "unknown" every single time and this whole branch would have
            // waited exactly as long as before while looking like it did not.
            const worthWaiting = !!knownCanonical || !this.canonicalLookupSucceeded(scope);
            if (worthWaiting) {
                for (let attempt = 0; attempt < 2 && !this.getStoredConversationKey(scope); attempt += 1) {
                    this.trace(`resolveConversationCryptoKey reason=${reason} scope=${scope} retry=${attempt} canonical=${knownCanonical ? 'known' : 'unknown'}`);
                    await new Promise(resolve => setTimeout(resolve, 600 + attempt * 1200));
                    if (recoveredVaultPassphrase) {
                        await this.syncCloudVaultPackage({ passphrase: recoveredVaultPassphrase, reason: `resolveConversationCryptoKey:${reason}:retry${attempt}` });
                    }
                    await this.syncIncomingKeyEnvelopes({ reason: `resolveConversationCryptoKey:${reason}:retry${attempt}`, triggerRefresh: false });
                    if (knownCanonical && !this.getStoredConversationKey(scope)) {
                        await this.promoteCanonicalConversationKey(scope, knownCanonical, { reason: `${reason}:retry${attempt}` });
                    }
                }
            } else {
                this.trace(`resolveConversationCryptoKey reason=${reason} scope=${scope} no_wait=true registry_empty=true`);
            }
        }

        const restored = this.getStoredConversationKey(scope);
        if (restored) {
            this.syncNativeConversationKeys();
            this.updateCryptoKeyDisplay({
                key: restored,
                peer,
                serverId,
                channelId,
            });
            void this.reconcileConversationKey(scope, restored, { reason: `restored:${reason}` });
            return restored;
        }

        const localKey = this.randomBase64(32).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
        // Through the same write lock promoteCanonicalConversationKey uses below —
        // this scope's first write must not race a concurrent background
        // reconcile/promote running for a different scope at the same time.
        await this.withConversationKeysWriteLock(() => {
            const stored = this.loadStoredConversationKeys();
            stored[scope] = localKey;
            this.saveStoredConversationKeys(stored);
        });
        this.setKey(localKey);
        this.trace(`resolveConversationCryptoKey reason=${reason} scope=${scope} generated=true`);

        // Register the new key as this scope's canonical one. First-write-wins, so
        // if another device already claimed the scope while we were generating,
        // reconcileConversationKey adopts the winner (from a candidate we already
        // hold, or by asking the holders to republish) instead of leaving two live
        // keys behind. This is the step that makes divergence self-correcting
        // rather than permanent.
        const reconciled = await this.reconcileConversationKey(scope, localKey, { reason: `generated:${reason}` });
        if (reconciled && reconciled !== localKey) {
            this.updateCryptoKeyDisplay({ key: reconciled, peer, serverId, channelId });
            return reconciled;
        }

        const owner = this.dmScopeOwner(scope);
        const meName = String(this.myName() || '').trim().toLowerCase();
        const isChannelScope = !!(serverId && channelId);
        if (owner && meName && owner !== meName) {
            // Non-owner had to invent a key because the owner's envelope was not
            // available/decryptable yet — incoming messages from the peer will stay
            // unreadable until the owner's key is adopted.
            this.addLogEntry({ type: 'WARN', msg: `Ключ диалога не получен от собеседника, сгенерирован временный (scope=${scope})`, ts: new Date().toLocaleTimeString() });
        } else if (isChannelScope) {
            this.addLogEntry({ type: 'INFO', msg: `Сгенерирован новый ключ канала (scope=${scope})`, ts: new Date().toLocaleTimeString() });
        } else {
            this.addLogEntry({ type: 'INFO', msg: `Сгенерирован новый ключ диалога (scope=${scope})`, ts: new Date().toLocaleTimeString() });
        }
        this.updateCryptoKeyDisplay({ key: localKey, peer, serverId, channelId });

        // Own devices first, and for every scope kind: a channel key is just as
        // unreachable for our other devices as a DM key is, and they have no other
        // way back to it once the cloud vault lags.
        void this.publishConversationKeyToOwnDevices({ scope, key: localKey, reason });

        const requiresPeerEnvelope = !!(peer && !serverId && !channelId && String(peer).trim() !== this.myName());
        if (requiresPeerEnvelope) {
            void this.publishConversationKeyToPeer({ peer, scope, key: localKey, reason }).then((published) => {
                if (published === true) {
                    if (!this._publishedKeyScopes) this._publishedKeyScopes = new Set();
                    this._publishedKeyScopes.add(scope);
                } else {
                    // 'no_devices' included: the peer has no registered devices yet, so
                    // nothing was delivered — keep the scope unmarked so the next send
                    // retries once the peer's device appears.
                    this.trace(`resolveConversationCryptoKey reason=${reason} scope=${scope} publish_pending=true result=${published}`);
                }
            });
        } else if (isChannelScope) {
            // Channel keys used to only ever be generated locally and never handed
            // to the rest of the server — every member who opened the channel before
            // anyone else's envelope arrived invented their own random key, so only
            // members who happened to share crypto material some other way (e.g.
            // multi-device vault sync) could read each other. Fan the new key out to
            // every other current server member the same way DM keys are published.
            void this.publishConversationKeyToServerMembers({ serverId, channelId, scope, key: localKey, reason });
        }
        return localKey;
    }

    ensureConversationCryptoKey({ peer = null, serverId = null, channelId = null, reason = 'auto' } = {}) {
        const scope = this.conversationScopeKey(peer, serverId, channelId);
        if (!scope) return '';
        const stored = this.getStoredConversationKey(scope);
        if (stored) {
            this.activeConversationScope = scope;
            try {
                window.__ZALI_ACTIVE_CONVERSATION_SCOPE = scope;
            } catch (e) {}
            // На устройстве может лежать ещё старый, случайный ключ канала — один раз
            // за сессию переключаемся на выводимый (старый остаётся кандидатом на
            // расшифровку). Один раз, а не на каждый рендер шапки: этот метод зовут
            // и оттуда тоже.
            if (this.isServerChannelScope(scope)) {
                if (!this._derivedChannelScopesChecked) this._derivedChannelScopesChecked = new Set();
                if (!this._derivedChannelScopesChecked.has(scope)) {
                    this._derivedChannelScopesChecked.add(scope);
                    void this.resolveConversationCryptoKey({ peer, serverId, channelId, reason });
                }
            }
            this.syncNativeConversationKeys();
            this.updateCryptoKeyDisplay({
                key: stored,
                peer,
                serverId,
                channelId,
            });
            return stored;
        }

        this.trace(`ensureConversationCryptoKey reason=${reason} scope=${scope} missing`);
        void this.resolveConversationCryptoKey({ peer, serverId, channelId, reason });
        this.updateCryptoKeyDisplay({
            key: '',
            peer,
            serverId,
            channelId,
        });
        return '';
    }

    updateCryptoKeyDisplay({ key = null, peer = null, serverId = null, channelId = null } = {}) {
        const valueEl = document.getElementById('currentCryptoKeyValue');
        const metaEl = document.getElementById('currentCryptoKeyMeta');
        const currentKey = String(key || this.loadStoredCryptoKey() || '').trim();
        if (valueEl) valueEl.textContent = currentKey ? `задан (${currentKey.length} символов)` : 'не задан';
        if (metaEl) {
            if (serverId && channelId) {
                // Без идентификаторов: пользователю они ничего не говорят, а канал он
                // и так видит в шапке чата по имени.
                metaEl.textContent = 'Контекст: канал сервера';
            } else if (peer) {
                metaEl.textContent = `Контекст: диалог с ${peer}`;
            } else {
                metaEl.textContent = 'Контекст: общий ключ';
            }
        }
    }

    base64FromBytes(bytes) {
        const arr = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes || []);
        let binary = '';
        for (let i = 0; i < arr.length; i += 0x8000) {
            binary += String.fromCharCode(...arr.subarray(i, i + 0x8000));
        }
        return btoa(binary);
    }

    bytesFromBase64(value) {
        const binary = atob(String(value || ''));
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i += 1) {
            bytes[i] = binary.charCodeAt(i);
        }
        return bytes;
    }

    randomBase64(size = 32) {
        const bytes = new Uint8Array(size);
        if (window.crypto?.getRandomValues) {
            window.crypto.getRandomValues(bytes);
        } else {
            throw new Error('Secure random unavailable: window.crypto.getRandomValues is required');
        }
        return this.base64FromBytes(bytes);
    }

    defaultDeviceLabel() {
        const platform = navigator.userAgentData?.platform || navigator.platform || 'Web';
        const agent = /Windows/i.test(navigator.userAgent) ? 'Windows'
            : /Mac/i.test(navigator.userAgent) ? 'Mac'
                : /iPhone|iPad/i.test(navigator.userAgent) ? 'iOS'
                    : /Android/i.test(navigator.userAgent) ? 'Android'
                        : 'Browser';
        return `${agent} ${platform}`.trim();
    }

    loadDeviceIdentity() {
        try {
            const raw = localStorage.getItem(this.deviceIdentityStorageKey());
            const parsed = raw ? JSON.parse(raw) : null;
            if (parsed?.deviceId && parsed?.publicKey) return parsed;
            // Deliberately no fallback to the legacy unsuffixed 'zali_device_identity_v1'
            // key here — see the comment in loadStoredMessageCache() for why: it would
            // hand a brand-new account a previous, unrelated account's device identity
            // (and with it, that account's approved-device status on the server).
            // This WKWebView's own storage has no identity yet — before generating a
            // fresh one (which the server would treat as a brand-new, unapproved
            // device with no key envelopes), check for an identity exported by another
            // shell on the same machine (see native.rs's injected_device_identity).
            const injected = this.loadInjectedDeviceIdentity();
            if (injected?.deviceId && injected?.publicKey) {
                try { localStorage.setItem(this.deviceIdentityStorageKey(), JSON.stringify(injected)); } catch (e) {}
                this.trace(`loadDeviceIdentity adopted injected identity deviceId=${injected.deviceId}`);
                return injected;
            }
        } catch (e) {}
        const identity = {
            deviceId: `dev_${this.randomBase64(18).replace(/[+/=]/g, '').slice(0, 24)}`,
            label: this.defaultDeviceLabel(),
            publicKey: this.randomBase64(32),
            signingKey: this.randomBase64(32),
            keyPackage: {
                version: 1,
                kind: 'zali-device-key-package',
                createdAt: new Date().toISOString(),
            },
        };
        try {
            localStorage.setItem(this.deviceIdentityStorageKey(), JSON.stringify(identity));
        } catch (e) {}
        return identity;
    }

    saveDeviceIdentity(identity) {
        try {
            localStorage.setItem(this.deviceIdentityStorageKey(), JSON.stringify(identity || {}));
        } catch (e) {}
        // Mirror the identity to the native shell so it survives a WebView storage wipe
        // (rebuild / restart / cleared data dir). Without this the Rust/Windows shell had
        // no persistence beyond localStorage — every wipe minted a fresh device_id, which
        // orphaned all previously-published key envelopes (they are addressed to a specific
        // recipient_device_id) and broke key convergence. See persistDeviceIdentityToNative.
        this.persistDeviceIdentityToNative(identity);
    }

    // Push the full device identity (incl. privateKeyJwk + e2ee keyPackage) to the native
    // shell, which writes shared_device_identity_{username}.json and re-injects it on the
    // next launch via window.__ZALI_INJECTED_DEVICE_IDENTITY. Mirrors what the macOS Swift
    // client already does; makes the identity stable per (machine, account) on all shells.
    persistDeviceIdentityToNative(identity) {
        try {
            if (!this.hasNativeBridge()) return;
            const username = String(this.myName() || '').trim();
            const deviceId = String(identity?.deviceId || '').trim();
            // No username yet (pre-auth) → we cannot name the per-user file; a later
            // post-auth save (bootstrapDeviceTrust) will persist it once the user is known.
            if (!username || !deviceId) return;
            this.postNativeMessage({
                type: NativeMessageTypes.PERSIST_DEVICE_IDENTITY,
                username,
                identity: JSON.stringify(identity),
            });
        } catch (e) {}
    }

    // Whose account the native shell's document-start injection belongs to.
    //
    // macOS, Windows and Android all inject the LAST logged-in user's device
    // identity and conversation keys before the page script runs, and nothing
    // cleared them when a different account signed in — the globals live for the
    // lifetime of the document, while applySession only swaps the in-page session.
    // So logging in as B on a device that last ran as A merged A's conversation keys
    // into B's key store (from there into B's cloud vault) and, when B had no local
    // identity yet, handed B A's device identity including its private ECDH key.
    // The localStorage legacy fallbacks two functions below were removed for exactly
    // this hazard; the injected channel had no such guard.
    //
    // Shells that stamp `__ZALI_INJECTED_FOR_USER` get checked against it. Older
    // shells do not set it at all, and for them the pre-existing behaviour stands —
    // wrong only on the account-switch path, which is what the stamp fixes going
    // forward. An empty myName() means we are still booting and do not yet know who
    // we are; adopting is right there, and it is the normal single-account path.
    injectedMaterialMatchesAccount() {
        try {
            const stamped = String(window.__ZALI_INJECTED_FOR_USER || '').trim().toLowerCase();
            if (!stamped) return true;
            const me = String(this.myName() || '').trim().toLowerCase();
            if (!me) return true;
            return me === stamped;
        } catch (e) {
            return true;
        }
    }

    loadInjectedDeviceIdentity() {
        try {
            if (!this.injectedMaterialMatchesAccount()) return null;
            const raw = window.__ZALI_INJECTED_DEVICE_IDENTITY;
            if (!raw) return null;
            const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
            return (parsed && typeof parsed === 'object') ? parsed : null;
        } catch (e) {
            return null;
        }
    }

    currentDeviceId() {
        return String(this.S.deviceTrust?.current?.deviceId || this.loadDeviceIdentity()?.deviceId || '').trim();
    }

    async ensureDeviceCryptoIdentity() {
        const identity = this.loadDeviceIdentity();
        const e2ee = identity?.keyPackage?.e2ee;
        if (e2ee?.publicJwk && identity?.privateKeyJwk && e2ee?.alg === 'ECDH-P-256+A256GCM') {
            return identity;
        }
        if (!window.crypto?.subtle) {
            throw new Error('WebCrypto недоступен для E2E ключей устройства');
        }
        const keyPair = await crypto.subtle.generateKey(
            { name: 'ECDH', namedCurve: 'P-256' },
            true,
            ['deriveKey']
        );
        const publicJwk = await crypto.subtle.exportKey('jwk', keyPair.publicKey);
        const privateJwk = await crypto.subtle.exportKey('jwk', keyPair.privateKey);
        const next = {
            ...identity,
            publicKey: JSON.stringify(publicJwk),
            privateKeyJwk: privateJwk,
            keyPackage: {
                ...(identity.keyPackage && typeof identity.keyPackage === 'object' ? identity.keyPackage : {}),
                version: 2,
                kind: 'zali-device-key-package',
                createdAt: identity.keyPackage?.createdAt || new Date().toISOString(),
                e2ee: {
                    alg: 'ECDH-P-256+A256GCM',
                    publicJwk,
                    createdAt: new Date().toISOString(),
                },
            },
        };
        this.saveDeviceIdentity(next);
        this.S.deviceTrust.current = next;
        return next;
    }

    devicePublicJwk(device) {
        const kp = device?.keyPackage && typeof device.keyPackage === 'object' ? device.keyPackage : {};
        if (kp?.e2ee?.alg === 'ECDH-P-256+A256GCM' && kp?.e2ee?.publicJwk) {
            return kp.e2ee.publicJwk;
        }
        try {
            const parsed = JSON.parse(String(device?.publicKey || ''));
            if (parsed?.kty === 'EC' && parsed?.crv === 'P-256') return parsed;
        } catch (e) {}
        return null;
    }

    async importEcdhPublicKey(jwk) {
        return await crypto.subtle.importKey(
            'jwk',
            jwk,
            { name: 'ECDH', namedCurve: 'P-256' },
            false,
            []
        );
    }

    async importEcdhPrivateKey(jwk) {
        return await crypto.subtle.importKey(
            'jwk',
            jwk,
            { name: 'ECDH', namedCurve: 'P-256' },
            false,
            ['deriveKey']
        );
    }

    async deriveEnvelopeAesKey(privateKey, publicKey, usages) {
        return await crypto.subtle.deriveKey(
            { name: 'ECDH', public: publicKey },
            privateKey,
            { name: 'AES-GCM', length: 256 },
            false,
            usages
        );
    }

    async encryptConversationKeyEnvelope({ scope, key, recipientDevice, peer }) {
        const identity = await this.ensureDeviceCryptoIdentity();
        const recipientJwk = this.devicePublicJwk(recipientDevice);
        if (!recipientJwk) throw new Error('Устройство получателя без E2E public key');
        const recipientPublicKey = await this.importEcdhPublicKey(recipientJwk);
        const ephemeral = await crypto.subtle.generateKey(
            { name: 'ECDH', namedCurve: 'P-256' },
            true,
            ['deriveKey']
        );
        const aesKey = await this.deriveEnvelopeAesKey(ephemeral.privateKey, recipientPublicKey, ['encrypt']);
        const iv = new Uint8Array(12);
        crypto.getRandomValues(iv);
        const plain = new TextEncoder().encode(JSON.stringify({
            scope,
            key,
            sender: this.myName(),
            peer,
            senderDeviceId: identity.deviceId,
            recipientDeviceId: recipientDevice.deviceId,
            createdAt: new Date().toISOString(),
        }));
        const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, aesKey, plain);
        const ephemeralPublicJwk = await crypto.subtle.exportKey('jwk', ephemeral.publicKey);
        return JSON.stringify({
            version: 2,
            kind: 'zali-conversation-key-envelope',
            alg: 'ECDH-P-256+A256GCM',
            scope,
            sender: this.myName(),
            senderDeviceId: identity.deviceId,
            recipientDeviceId: recipientDevice.deviceId,
            ephemeralPublicJwk,
            iv: this.base64FromBytes(iv),
            ciphertext: this.base64FromBytes(ciphertext),
        });
    }

    async decryptConversationKeyEnvelope(encryptedKey) {
        const identity = await this.ensureDeviceCryptoIdentity();
        const envelope = JSON.parse(String(encryptedKey || ''));
        if (envelope?.version !== 2 || envelope?.kind !== 'zali-conversation-key-envelope') {
            throw new Error('Неподдерживаемый key envelope');
        }
        if (String(envelope.recipientDeviceId || '') !== String(identity.deviceId || '')) {
            throw new Error('Envelope предназначен другому устройству');
        }
        const privateKey = await this.importEcdhPrivateKey(identity.privateKeyJwk);
        const ephemeralPublicKey = await this.importEcdhPublicKey(envelope.ephemeralPublicJwk);
        const aesKey = await this.deriveEnvelopeAesKey(privateKey, ephemeralPublicKey, ['decrypt']);
        const plain = await crypto.subtle.decrypt(
            { name: 'AES-GCM', iv: this.bytesFromBase64(envelope.iv) },
            aesKey,
            this.bytesFromBase64(envelope.ciphertext)
        );
        const payload = JSON.parse(new TextDecoder().decode(new Uint8Array(plain)));
        return {
            scope: String(payload.scope || envelope.scope || '').trim(),
            key: String(payload.key || '').trim(),
            sender: String(payload.sender || envelope.sender || '').trim(),
        };
    }


    async deriveVaultAesKey(code, saltBytes) {
        const passphrase = String(code || '').trim();
        if (!passphrase) throw new Error('Введите одноразовый код vault');
        if (!window.crypto?.subtle) throw new Error('WebCrypto недоступен');
        const material = await crypto.subtle.importKey(
            'raw',
            new TextEncoder().encode(passphrase),
            'PBKDF2',
            false,
            ['deriveKey']
        );
        return crypto.subtle.deriveKey(
            {
                name: 'PBKDF2',
                salt: saltBytes,
                iterations: 210000,
                hash: 'SHA-256',
            },
            material,
            { name: 'AES-GCM', length: 256 },
            false,
            ['encrypt', 'decrypt']
        );
    }

    async encryptVaultPackage(payload, code) {
        const salt = new Uint8Array(16);
        const iv = new Uint8Array(12);
        crypto.getRandomValues(salt);
        crypto.getRandomValues(iv);
        const key = await this.deriveVaultAesKey(code, salt);
        const plain = new TextEncoder().encode(JSON.stringify(payload));
        const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, plain);
        return `zali-vault:${this.base64FromBytes(new TextEncoder().encode(JSON.stringify({
            v: 1,
            kdf: 'PBKDF2-SHA256',
            iterations: 210000,
            aead: 'AES-256-GCM',
            salt: this.base64FromBytes(salt),
            iv: this.base64FromBytes(iv),
            ciphertext: this.base64FromBytes(ciphertext),
        })))}`;
    }

    async decryptVaultPackage(packageText, code) {
        const raw = String(packageText || '').trim();
        const encoded = raw.startsWith('zali-vault:') ? raw.slice('zali-vault:'.length) : raw;
        const envelope = JSON.parse(new TextDecoder().decode(this.bytesFromBase64(encoded)));
        const salt = this.bytesFromBase64(envelope.salt);
        const iv = this.bytesFromBase64(envelope.iv);
        const ciphertext = this.bytesFromBase64(envelope.ciphertext);
        const key = await this.deriveVaultAesKey(code, salt);
        const plain = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, ciphertext);
        return JSON.parse(new TextDecoder().decode(new Uint8Array(plain)));
    }

    buildVaultPlainPayload(targetDeviceId = '') {
        const stored = this.loadStoredConversationKeys();
        const scopedKeys = {};
        for (const [scope, value] of Object.entries(stored)) {
            const key = String(value || '').trim();
            if (!key) continue;
            scopedKeys[scope] = key;
        }
        // Every scope goes into the cloud package, including DM keys whose
        // lexicographic "owner" is the peer.
        //
        // Those used to be excluded, on the theory that the owner's envelopes
        // deliver them canonically and a locally invented temporary key must not
        // spread. In practice that made the cloud vault useless exactly where it
        // was needed most: for an account whose username sorts late (`zalikus` vs
        // `GRIBOED`/`Pivovarca`/`test67`), the peer owns *every* DM, so a second
        // device of that account could never recover a single conversation key and
        // invented a fresh one for each chat instead. Spreading a provisional key
        // is now harmless: applyVaultPlainPayload keeps the previous key as a
        // decryption candidate, and the server registry — not whoever wrote last —
        // decides which key is canonical.
        return {
            version: 2,
            keyEpoch: 2,
            kind: 'zali-account-vault-bootstrap',
            accountId: this.myName(),
            issuedByDevice: this.currentDeviceId(),
            issuedToDevice: String(targetDeviceId || '').trim(),
            vaultEpoch: Date.now(),
            allowedHistoryPolicy: '30_days',
            createdAt: new Date().toISOString(),
            conversationKeys: scopedKeys,
        };
    }

    applyVaultPlainPayload(payload) {
        if (!payload || typeof payload !== 'object' || payload.kind !== 'zali-account-vault-bootstrap') {
            throw new Error('Это не Zali vault package');
        }
        if (Number(payload.version || 0) !== 2 || Number(payload.keyEpoch || 0) !== 2) {
            throw new Error('Vault package создан старой схемой ключей');
        }
        const accountId = String(payload.accountId || '').trim();
        if (accountId && accountId !== this.myName()) {
            throw new Error(`Vault предназначен для аккаунта ${accountId}`);
        }
        const nextKeys = this.loadStoredConversationKeys();
        const incomingKeys = payload.conversationKeys && typeof payload.conversationKeys === 'object'
            ? payload.conversationKeys
            : {};
        for (const [rawScope, value] of Object.entries(incomingKeys)) {
            // A vault package written by an older device carries legacy-cased scopes.
            const scope = this.canonicalConversationScope(String(rawScope || ''));
            const current = String(nextKeys[scope] || '').trim();
            const next = String(value || '').trim();
            if (!next) continue;
            // Ключ канала выводится из scope и активным остаётся всегда он. Снимок
            // облака (в том числе старый, снятый до перехода) кладём только в
            // кандидаты: иначе он перебивал активный, refreshAfterKey тут же
            // возвращал выводимый обратно — и канал ходил по кругу, флипая ключ на
            // каждой синхронизации хранилища.
            if (this.isServerChannelScope(scope)) {
                this.addAltConversationKey(nextKeys, scope, next);
                continue;
            }
            if (current && current !== next) {
                // Облачный ключ замещает локальный, но локальный сохраняется как
                // кандидат расшифровки: если в облако попал не тот ключ (например,
                // временный с нового устройства), история, зашифрованная прежним,
                // не должна стать нечитаемой.
                this.addAltConversationKey(nextKeys, scope, current);
            }
            nextKeys[scope] = next;
        }
        this.saveStoredConversationKeys(nextKeys);
        const displayKey = String(Object.values(nextKeys)[0] || '').trim();
        this.updateCryptoKeyDisplay({ key: displayKey });
        this.refreshAfterKey();
        // The vault merge above is last-writer-wins on the active key (the previous
        // one is kept as a decryption candidate, so nothing becomes unreadable).
        // That is fine as an interim state, but the registry has the final say —
        // reconcile in the background so the active/sending key converges on the
        // canonical one instead of on whichever device synced most recently.
        void this.reconcileVaultScopes(
            Object.keys(incomingKeys).map(scope => this.canonicalConversationScope(scope))
        );
        return Object.keys(nextKeys).length;
    }

    // Align the active key of each freshly merged vault scope with the server
    // registry. Runs off the critical path; a failure just leaves the interim
    // (still decryptable) state in place until the next sync.
    async reconcileVaultScopes(scopes = []) {
        const list = (Array.isArray(scopes) ? scopes : [])
            .map(scope => String(scope || '').trim())
            // `server:` намеренно исключён: у каналов канонического ключа в реестре
            // нет, он выводится из scope (deriveServerChannelKey).
            .filter(scope => scope.startsWith('dm:'))
            .slice(0, 200);
        if (!list.length || !this.S.session?.token) return 0;
        const canonical = await this.fetchCanonicalKeyIds(list);
        let promoted = 0;
        for (const scope of list) {
            const wanted = String(canonical.get(scope) || '').trim();
            if (!wanted) continue;
            if (await this.promoteCanonicalConversationKey(scope, wanted, { reason: 'vault' })) promoted += 1;
        }
        if (promoted) this.trace(`reconcileVaultScopes promoted=${promoted}`);
        return promoted;
    }

    // Does the vault event we just read already contain every key this device holds?
    //
    // Compared entry by entry over the whole stored map, `alt:` candidates included:
    // those are exactly the historical keys a second device needs in order to read
    // anything written before the conversation converged, and they are the ones the
    // republish sweep deliberately never sends (see retryPublishConversationKeys), so
    // the vault is their only route between an account's own devices.
    //
    // Note that `payload` is read BEFORE applyVaultPlainPayload merges it, or the
    // comparison would be against a map that just absorbed it and always match.
    vaultPayloadCoversLocalKeys(payload) {
        const remote = payload?.conversationKeys && typeof payload.conversationKeys === 'object'
            ? payload.conversationKeys
            : {};
        const local = this.loadStoredConversationKeys();
        for (const [scope, value] of Object.entries(local)) {
            const key = String(value || '').trim();
            if (!key) continue;
            if (String(remote[scope] || '').trim() !== key) return false;
        }
        return true;
    }

    scheduleCloudVaultSync(delayMs = 300) {
        if (!this.S.session?.token || !this.S.auth?.vaultPassphrase || !this.isVaultCloudSyncEnabled()) return;
        if (this.cloudVaultSyncTimer) {
            clearTimeout(this.cloudVaultSyncTimer);
        }
        this.cloudVaultSyncTimer = window.setTimeout(() => {
            this.cloudVaultSyncTimer = 0;
            void this.syncCloudVaultPackage({ reason: 'scheduled' });
        }, Math.max(0, Number(delayMs) || 0));
    }

    async syncCloudVaultPackage({ passphrase = null, reason = 'auto' } = {}) {
        if (!this.S.session?.token) return false;
        if (!this.isVaultCloudSyncEnabled()) {
            this.trace(`syncCloudVaultPackage skipped reason=${reason} disabled=true`);
            return false;
        }
        const code = String(passphrase || this.S.auth?.vaultPassphrase || '').trim();
        if (!code) return false;
        if (this.cloudVaultSyncInFlight) return false;

        this.cloudVaultSyncInFlight = true;
        try {
            this.S.auth.vaultPassphrase = code;
            await this.ensureServerVaultReset({ reason: `syncCloudVaultPackage:${reason}` });

            let imported = false;
            let sawCompatibleServerEvents = false;
            let serverAlreadyHasEverything = false;
            let undecryptableServerEvents = false;
            try {
                const res = await this.apiFetch(this.apiRoutes.vault.events);
                if (res.ok) {
                    const events = await res.json();
                    if (Array.isArray(events) && events.length > 0) {
                        // Scan backward for the newest event THIS passphrase can decrypt,
                        // instead of only ever looking at events[events.length-1]. The vault
                        // event stream is shared with one-time-code exports
                        // (approveDeviceAndExport/exportCurrentVaultPackage) that are never
                        // encrypted with the account passphrase — those used to permanently
                        // "poison" auto-sync the moment one landed after a real event, because
                        // the old code gave up for good the first time the single newest row
                        // failed to decrypt. Scanning a bounded window back makes this
                        // self-healing: any account already stuck on this recovers
                        // automatically once this ships, no server/data change needed.
                        const SCAN_WINDOW = 8;
                        const scanStart = Math.max(0, events.length - SCAN_WINDOW);
                        let matchIndex = -1;
                        let payload = null;
                        let anyDecryptAttempted = false;
                        for (let i = events.length - 1; i >= scanStart; i -= 1) {
                            const encrypted = String(events[i]?.encryptedVaultEvent || '').trim();
                            if (!encrypted) continue;
                            anyDecryptAttempted = true;
                            try {
                                payload = await this.decryptVaultPackage(encrypted, code);
                                matchIndex = i;
                                break;
                            } catch (e) {
                                this.trace(`syncCloudVaultPackage decrypt failed reason=${reason} index=${i} error=${e?.message || e}`);
                            }
                        }
                        if (payload) {
                            try {
                                // Measured against the key map as it stands BEFORE the merge:
                                // applyVaultPlainPayload folds this very payload into it, so
                                // asking afterwards would compare the server against a copy of
                                // itself for every scope it happened to carry.
                                const covers = this.vaultPayloadCoversLocalKeys(payload);
                                this.applyVaultPlainPayload(payload);
                                await this.saveCloudVaultSnapshot(payload, this.S.session?.token);
                                imported = true;
                                // Only skip republishing when the newest event itself was the
                                // match — an older match means newer, undecryptable rows
                                // (foreign-code exports) sit on top of it; falling through to
                                // publish below pushes "latest" back to something every device
                                // can read again instead of leaving it stuck behind them.
                                sawCompatibleServerEvents = matchIndex === events.length - 1;
                                // ...and only when that newest event actually carries everything
                                // this device holds. Position alone used to decide it, which
                                // froze the vault after its very first publish: from then on the
                                // newest event was always ours and always decryptable, so this
                                // returned before the publish below every single time, and no
                                // key created afterwards ever reached the cloud. A second device
                                // of the account then recovered the key set as it stood on day
                                // one and invented fresh keys for every conversation opened
                                // since. It only ever unstuck itself by accident, when a
                                // one-time-code export (approveDeviceAndExport) landed on top
                                // and pushed the match off the end of the stream.
                                serverAlreadyHasEverything = covers;
                                this.trace(`syncCloudVaultPackage imported reason=${reason} events=${events.length} matchIndex=${matchIndex} covers=${serverAlreadyHasEverything}`);
                            } catch (e) {
                                // Расшифровалось, но пакет старой схемы — публикация ниже
                                // выступает как upgrade до v2, это допустимо.
                                this.trace(`syncCloudVaultPackage import failed reason=${reason} error=${e?.message || e}`);
                            }
                        } else if (anyDecryptAttempted) {
                            undecryptableServerEvents = true;
                        }
                    }
                }
            } catch (e) {
                this.trace(`syncCloudVaultPackage fetch failed reason=${reason} error=${e?.message || e}`);
            }

            if (!this.isVaultCloudSyncEnabled()) {
                this.trace(`syncCloudVaultPackage aborted reason=${reason} disabled_after_fetch=true`);
                return imported;
            }

            if (sawCompatibleServerEvents && serverAlreadyHasEverything) {
                return imported;
            }

            if (undecryptableServerEvents) {
                // Ни одно из последних SCAN_WINDOW событий не расшифровалось этой
                // passphrase — похоже на реальную смену пароля на другом устройстве, а
                // не на one-time-code экспорт. Публиковать поверх нельзя: локальные
                // ключи здесь могут быть свежесгенерированными временными.
                this.trace(`syncCloudVaultPackage publish skipped reason=${reason} undecryptable_server_events=true`);
                this.addLogEntry({ type: 'WARN', msg: 'Cloud vault: события на сервере не расшифровались текущей passphrase, публикация ключей пропущена', ts: new Date().toLocaleTimeString() });
                return false;
            }

            const payload = this.buildVaultPlainPayload('');
            const hasKeys = Object.keys(payload.conversationKeys || {}).length > 0;
            if (!hasKeys) {
                return imported;
            }

            const encryptedVaultEvent = await this.encryptVaultPackage(payload, code);
            const vaultRes = await this.apiFetch(this.apiRoutes.vault.events, {
                method: 'POST',
                body: JSON.stringify({
                    issuedToDeviceId: null,
                    vaultEpoch: payload.vaultEpoch,
                    encryptedVaultEvent,
                }),
            });
            if (!vaultRes.ok) {
                throw new Error(await vaultRes.text().catch(() => 'Не удалось сохранить cloud vault event'));
            }
            await this.saveCloudVaultSnapshot(payload, this.S.session?.token);
            this.trace(`syncCloudVaultPackage published reason=${reason} imported=${imported}`);
            return true;
        } catch (e) {
            this.trace(`syncCloudVaultPackage error reason=${reason} error=${e?.message || e}`);
            return false;
        } finally {
            this.cloudVaultSyncInFlight = false;
        }
    }
});


// --- MODULE: interface/key_envelopes.js ---
// --- ZaliInterface: Публикация/приём ключевых конвертов, доверие устройств. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    // Fan a scope's key out to every non-revoked device of `recipient` that has a
    // usable public key — NOT only approved ones.
    //
    // The `approved` filter used to be here to limit envelope churn, but
    // device approval is a manual step almost nobody performs: production
    // showed one account with 11 registered devices and exactly 1 approved.
    // The other 10 received zero envelopes, so each of them invented its own
    // conversation key and encrypted real messages with it. Starving a
    // legitimately logged-in device of key material does not make anything
    // safer — the envelope is sealed to that device's own ECDH public key
    // and only that device can open it — it just breaks the conversation.
    // `keys` publishes several candidates for one scope in a single pass. It exists
    // because the per-recipient DEVICE lookup is the expensive part: calling this once
    // per candidate re-fetched `/api/users/<peer>/devices` for every one of them, so a
    // republish answer carrying six candidates to a twenty-member channel spent a
    // hundred and twenty directory round trips through a five-slot pool before it had
    // published anything. The envelope POSTs themselves are irreducible — one per key
    // per device — but the lookups are not.
    async publishConversationKeyEnvelopes({ recipient, scope, key, keys = null, reason = 'auto', excludeCurrentDevice = false } = {}) {
        const target = String(recipient || '').trim();
        const scoped = String(scope || '').trim();
        const secrets = Array.from(new Set(
            (Array.isArray(keys) ? keys : [key])
                .map(value => String(value || '').trim())
                .filter(Boolean)
        )).slice(0, ZaliInterface.MAX_REPUBLISH_CANDIDATES);
        if (!this.S.session?.token || !target || !scoped || !secrets.length) return false;
        try {
            await this.ensureDeviceCryptoIdentity();
            const res = await this.apiFetch(this.apiRoutes.devices.publicByUser(target));
            if (!res.ok) throw new Error(await res.text().catch(() => 'Не удалось получить устройства контакта'));
            const devices = await res.json();
            const selfDeviceId = String(this.currentDeviceId() || '');
            const usable = Array.isArray(devices)
                ? devices.filter(device => !device?.revoked
                    && this.devicePublicJwk(device)
                    // Publishing to ourselves would be a no-op envelope this very
                    // device would then re-import; skip it when fanning out to the
                    // account's own devices.
                    && !(excludeCurrentDevice && String(device?.deviceId || '') === selfDeviceId))
                : [];
            if (!usable.length) {
                this.trace(`publishConversationKeyEnvelopes skipped reason=${reason} recipient=${target} devices=0`);
                return 'no_devices';
            }
            // Non-secret SHA-256 fingerprint — the same id the registry stores, never
            // the key. It is part of the envelope row's identity on the server, so
            // several candidate keys for one scope reach one device as several
            // envelopes instead of overwriting each other down to the last one.
            const keyIds = await Promise.all(secrets.map(secret => this.conversationKeyId(secret)));
            const jobs = [];
            for (const device of usable) {
                secrets.forEach((secret, i) => jobs.push({ device, secret, keyId: keyIds[i] }));
            }
            const results = await Promise.allSettled(jobs.map(async ({ device, secret, keyId }) => {
                const encryptedKey = await this.encryptConversationKeyEnvelope({
                    scope: scoped,
                    key: secret,
                    recipientDevice: device,
                    peer: target,
                });
                const post = await this.apiFetch(this.apiRoutes.keyEnvelopes.base, {
                    method: 'POST',
                    includeDeviceId: true,
                    body: JSON.stringify({
                        recipient: target,
                        scope: scoped,
                        recipientDeviceId: device.deviceId,
                        senderDeviceId: selfDeviceId,
                        keyId,
                        encryptedKey,
                    }),
                });
                if (!post.ok) throw new Error(await post.text().catch(() => 'Не удалось сохранить key envelope'));
            }));
            const succeeded = results.filter(r => r.status === 'fulfilled').length;
            if (!succeeded) {
                const firstErr = results.find(r => r.status === 'rejected')?.reason;
                throw new Error(firstErr?.message || 'Не удалось опубликовать ни один key envelope');
            }
            this.trace(`publishConversationKeyEnvelopes reason=${reason} recipient=${target} devices=${usable.length} keys=${secrets.length}`);
            return true;
        } catch (e) {
            this.trace(`publishConversationKeyEnvelopes failed reason=${reason} recipient=${target} error=${e?.message || e}`);
            return false;
        }
    }

    async publishConversationKeyToPeer({ peer, scope, key, keys = null, reason = 'auto' } = {}) {
        const recipient = String(peer || '').trim();
        // Self is not a peer: own devices go through publishConversationKeyToOwnDevices,
        // which excludes this device and reports separately.
        if (!recipient || recipient === this.myName()) return false;
        return this.publishConversationKeyEnvelopes({ recipient, scope, key, keys, reason });
    }

    // The account's *other* devices need this key just as much as the peer's do,
    // and until this existed nothing delivered it to them: publishConversationKeyToPeer
    // refuses `recipient === myName()` by design, so own-device key sync rode
    // entirely on the cloud vault. A single device missing that one channel was
    // enough for it to invent its own key and encrypt real messages with it —
    // messages no other device of the same account could ever read. Observed in
    // production: a Mac holding the registry-canonical key for a DM could not
    // decrypt a message the same account had sent 14 seconds earlier from another
    // device, after trying all 19 keys it knew.
    //
    // This widens nothing: each envelope is sealed to one of our own devices'
    // ECDH public keys, and the cloud vault already hands every own device the
    // full key set — this is the same reach over a channel that actually works.
    async publishConversationKeyToOwnDevices({ scope, key, keys = null, reason = 'auto' } = {}) {
        const me = String(this.myName() || '').trim();
        if (!me) return false;
        return this.publishConversationKeyEnvelopes({
            recipient: me,
            scope,
            key,
            keys,
            reason: `self:${reason}`,
            excludeCurrentDevice: true,
        });
    }

    peerFromConversationScope(scope) {
        const parts = String(scope || '').trim().split(':');
        if (parts.length !== 3 || parts[0] !== 'dm') return '';
        const me = String(this.myName() || '').trim().toLowerCase();
        if (!me) return '';
        const a = String(parts[1] || '').trim().toLowerCase();
        const b = String(parts[2] || '').trim().toLowerCase();
        // Back to the casing the server stores — the result goes straight into
        // request paths (`/api/users/<peer>/devices`), which match exactly.
        if (a === me) return this.resolveKnownUsernameCasing(b);
        if (b === me) return this.resolveKnownUsernameCasing(a);
        return '';
    }

    channelFromConversationScope(scope) {
        const parts = String(scope || '').trim().split(':');
        if (parts.length !== 3 || parts[0] !== 'server') return null;
        const serverId = parts[1] || '';
        const channelId = parts[2] || '';
        if (!serverId || !channelId) return null;
        return { serverId, channelId };
    }

    // Fans a channel's conversation key out to every other current server member
    // via the same per-device key-envelope mechanism used for DMs. Unlike a DM
    // (single recipient), a channel can have any number of members and the
    // membership list can change, so this is re-run on every resolve/retry
    // rather than tracked with a one-shot "published" flag.
    // `keys` may carry several candidates for one scope (a republish request is
    // answered with every key we hold for it). They are fanned out per member in one
    // pass rather than by calling this once per key: each call costs a members
    // lookup and, inside publishConversationKeyToPeer, a devices lookup per member,
    // so the per-key loop it replaces multiplied both by the candidate count. A
    // twenty-member server answering one request with three candidates spent sixty
    // directory lookups before publishing anything — and every member that cannot
    // read the channel sends a request of its own.
    async publishConversationKeyToServerMembers({ serverId, channelId, scope, key, keys = null, reason = 'auto' } = {}) {
        // Больше не рассылает ничего. Ключ канала выводится из его scope
        // (deriveServerChannelKey), то есть уже есть у каждого участника до всякой
        // сети — а веерная рассылка конвертов «по устройству на участника» и была
        // тем механизмом, из-за которого канал читали только те двое, у кого обмен
        // случайно сошёлся. Метод оставлен заглушкой, чтобы не разбирать по всему
        // коду ветки republish/takeover, которые его зовут.
        const scopedForChannel = String(scope || '').trim() || (serverId && channelId ? `server:${String(serverId).trim()}:${String(channelId).trim()}` : '');
        if (this.isServerChannelScope(scopedForChannel)) {
            this.trace(`publishConversationKeyToServerMembers skipped reason=${reason} scope=${scopedForChannel} derived_key=true`);
            return 0;
        }
        const sid = String(serverId || '').trim();
        const cid = String(channelId || '').trim();
        const scoped = String(scope || '').trim();
        const secrets = Array.from(new Set(
            (Array.isArray(keys) ? keys : [key])
                .map(value => String(value || '').trim())
                .filter(Boolean)
        )).slice(0, ZaliInterface.MAX_REPUBLISH_CANDIDATES);
        if (!this.S.session?.token || !sid || !cid || !scoped || !secrets.length) return 0;
        const me = String(this.myName() || '').trim();
        let members = [];
        try {
            members = await this.loadServerMembers(sid);
        } catch (e) {
            this.trace(`publishConversationKeyToServerMembers failed reason=${reason} scope=${scoped} error=${e?.message || e}`, {}, 'WARN');
            return 0;
        }
        const recipients = members
            .map(member => String(member?.username || '').trim())
            .filter(username => username && username !== me);
        const results = await Promise.allSettled(recipients.map(peer =>
            this.publishConversationKeyToPeer({ peer, scope: scoped, keys: secrets, reason })
        ));
        const published = results.filter(r => r.status === 'fulfilled' && r.value === true).length;
        this.trace(`publishConversationKeyToServerMembers reason=${reason} scope=${scoped} members=${recipients.length} keys=${secrets.length} published=${published}`);
        return published;
    }

    // Someone in a conversation we share told the server they cannot decrypt it.
    // If we hold that scope's key, push it straight back to them — this is the
    // targeted counterpart of retryPublishConversationKeys' full sweep and is what
    // lets a brand-new device become readable in seconds instead of at next login.
    async handleKeyRepublishRequest(payload) {
        const scope = String(payload?.scope || '').trim();
        const requester = String(payload?.requester || '').trim();
        if (!scope || !this.S.session?.token) return false;
        // EVERY key we hold for this scope, not just the active one. The requester
        // is asking because something is unreadable for it, and the active key is
        // the one it is most likely to already have — the messages it cannot read
        // are exactly the ones encrypted under a key we have since demoted to an
        // `alt:` candidate. Sending only the active key answered the request with
        // the one key that could not possibly help.
        // Bounded. Every candidate costs an envelope POST per device of every
        // participant, and `alt:` entries accumulate without limit, so an old scope
        // could answer a single request with dozens of keys times dozens of devices.
        // The newest candidates are the ones a requester is most likely to be missing;
        // anything older is still reachable by asking again after this batch lands.
        const candidates = this
            .conversationKeyCandidates(this.loadStoredConversationKeys(), scope)
            .slice(0, ZaliInterface.MAX_REPUBLISH_CANDIDATES);
        if (!candidates.length) {
            this.trace(`handleKeyRepublishRequest scope=${scope} requester=${requester} noLocalKey=true`);
            return false;
        }
        const channel = this.channelFromConversationScope(scope);
        if (channel) {
            // One pass over the membership for all candidates, not one pass per key.
            await this.publishConversationKeyToServerMembers({
                serverId: channel.serverId,
                channelId: channel.channelId,
                scope,
                keys: candidates,
                reason: 'republish_request',
            });
            return true;
        }
        const peer = requester || this.peerFromConversationScope(scope);
        // A request from our own account is another of our devices asking for this
        // key. That used to be dropped on the floor here, which is precisely the
        // device that has no other way to obtain it.
        // Every candidate goes out in ONE call per recipient, not one call per key:
        // each call re-fetches that recipient's device list, and the answer to a
        // republish request is by definition several keys.
        if (peer === this.myName()) {
            const selfResult = await this.publishConversationKeyToOwnDevices({
                scope,
                keys: candidates,
                reason: 'republish_request',
            });
            this.trace(`handleKeyRepublishRequest scope=${scope} self=true keys=${candidates.length} result=${selfResult}`);
            return selfResult === true;
        }
        if (!peer) return false;
        const result = await this.publishConversationKeyToPeer({
            peer,
            scope,
            keys: candidates,
            reason: 'republish_request',
        });
        this.trace(`handleKeyRepublishRequest scope=${scope} peer=${peer} keys=${candidates.length} result=${result}`);
        return result === true;
    }

    // Collapses bursts of full-sweep requests into one sweep per cooldown window.
    //
    // The sweep itself is expensive — a devices lookup plus one envelope POST per
    // device for every scope this account holds — and it is driven by the
    // `device_approved` WS push, which the server fans out to *every* account that
    // has ever shared a key with the one whose device just registered
    // (notify_key_republish_peers). Several peers reconnecting therefore queued
    // several full sweeps back to back. Worse, the loop closes on itself: every
    // envelope POST makes the server push `key_envelope_available` to the recipient
    // — including straight back to this device for its own-device envelopes — and
    // each of those schedules another refreshAfterKey(). Once started it fed itself,
    // at a sustained ~100 envelope POSTs/minute for hours.
    //
    // Requests are coalesced, never dropped: anything arriving during the window
    // schedules exactly one trailing sweep, so a genuinely new device still gets its
    // envelopes — just once, after the burst, instead of once per notification.
    async retryPublishConversationKeys({ reason = 'auto', limit = 200, cooldownMs = 60000 } = {}) {
        if (!this.S.session?.token) return 0;
        const now = Date.now();
        const last = Number(this._lastKeyPublishSweepAt || 0);
        if (last && (now - last) < cooldownMs) {
            if (!this._keyPublishSweepTrailing) {
                this._keyPublishSweepTrailing = setTimeout(() => {
                    this._keyPublishSweepTrailing = null;
                    void this.retryPublishConversationKeys({ reason: `${reason}:trailing`, limit, cooldownMs });
                }, Math.max(0, cooldownMs - (now - last)));
            }
            this.trace(`retryPublishConversationKeys coalesced reason=${reason}`);
            return 0;
        }
        // The cooldown alone does not serialise anything: it is stamped here, before
        // the sweep starts, while the sweep itself runs for minutes (one devices
        // lookup plus an envelope POST per device for every scope, all queued through
        // a five-slot pool). A trailing timer armed during that run fires as soon as
        // the window elapses — with the first sweep still in flight — and a second
        // full sweep piles onto the same pool, doubling the storm this coalescing was
        // added to prevent. Anything arriving while one is running becomes a trailing
        // sweep instead, so nothing is dropped.
        if (this._keyPublishSweepInFlight) {
            if (!this._keyPublishSweepTrailing) {
                this._keyPublishSweepTrailing = setTimeout(() => {
                    this._keyPublishSweepTrailing = null;
                    void this.retryPublishConversationKeys({ reason: `${reason}:trailing`, limit, cooldownMs });
                }, cooldownMs);
            }
            this.trace(`retryPublishConversationKeys deferred reason=${reason} in_flight=true`);
            return 0;
        }
        this._lastKeyPublishSweepAt = now;
        this._keyPublishSweepInFlight = true;
        try {
            return await this._retryPublishConversationKeysImpl({ reason, limit });
        } finally {
            this._keyPublishSweepInFlight = false;
            // Stamped again on the way out: the window that matters is the gap between
            // sweeps, not the moment one happened to start.
            this._lastKeyPublishSweepAt = Date.now();
        }
    }

    async _retryPublishConversationKeysImpl({ reason = 'auto', limit = 200 } = {}) {
        if (!this.S.session?.token) return 0;
        const stored = this.loadStoredConversationKeys();
        const scopes = Object.keys(stored)
            .filter(scope => (String(scope || '').startsWith('dm:') || String(scope || '').startsWith('server:'))
                && String(stored[scope] || '').trim())
            .slice(0, Math.max(1, Number(limit) || 20));
        // ACTIVE key per scope only. This sweep briefly published every `alt:`
        // candidate too, so that a historical key whose first publish failed could
        // still reach the peer — correct in principle, ruinous in practice: each
        // (scope, key) pair costs a devices lookup plus one envelope POST per
        // device, every request is serialized through the API slot pool, and a real
        // account has ~18 scopes with several candidates each. The client spent
        // minutes saturating its own pool, `syncIncomingKeyEnvelopes` and history
        // loads timed out behind it, and the chat came up empty — observed in
        // production 2026-08-02 as a continuous POST /api/key-envelopes storm with
        // "The request timed out." on every envelope fetch.
        //
        // Historical keys still get out, but only down the targeted path:
        // handleKeyRepublishRequest answers a specific "I cannot decrypt this scope"
        // with every candidate. That fires once per affected scope instead of on
        // every login for every scope.
        const entries = scopes.map(scope => [scope, String(stored[scope] || '').trim()]);
        let published = 0;
        for (const [scope, key] of entries) {
            // Unconditional, and before the peer/channel split: this sweep is the
            // one path that can retroactively hand our other devices the keys they
            // never received, so it must cover every scope we hold — including
            // channel scopes and DMs whose peer is momentarily unresolvable.
            await this.publishConversationKeyToOwnDevices({ scope, key, reason: `retry:${reason}` });
            const channel = this.channelFromConversationScope(scope);
            if (channel) {
                published += await this.publishConversationKeyToServerMembers({
                    serverId: channel.serverId,
                    channelId: channel.channelId,
                    scope,
                    key,
                    reason: `retry:${reason}`,
                });
                continue;
            }
            const peer = this.peerFromConversationScope(scope);
            if (!peer) continue;
            const result = await this.publishConversationKeyToPeer({ peer, scope, key, reason: `retry:${reason}` });
            // 'no_devices' is truthy but means nothing was delivered — the peer has
            // no registered devices yet, so the envelope must be retried later.
            if (result === true) {
                published += 1;
            }
        }
        if (published) {
            this.trace(`retryPublishConversationKeys reason=${reason} published=${published}`);
        }
        return published;
    }

    // Concurrent callers (e.g. bootstrapDeviceTrust's background sync overlapping
    // postAuthSetup's own awaited call) used to each run an independent
    // load-mutate-save cycle over the same stored-conversation-keys object with no
    // locking, so a freshly generated local key from _resolveConversationCryptoKeyImpl
    // could be silently clobbered by whichever save landed last. Dedup to a single
    // in-flight run, mirroring _resolveKeyInFlight/_restoreVaultInFlight.
    async syncIncomingKeyEnvelopes(opts = {}) {
        if (this._syncEnvelopesInFlight) return this._syncEnvelopesInFlight;
        this._syncEnvelopesInFlight = this._syncIncomingKeyEnvelopesImpl(opts);
        try {
            return await this._syncEnvelopesInFlight;
        } finally {
            this._syncEnvelopesInFlight = null;
        }
    }

    async _syncIncomingKeyEnvelopesImpl({ reason = 'auto', triggerRefresh = true } = {}) {
        if (!this.S.session?.token) return 0;
        try {
            const identity = await this.ensureDeviceCryptoIdentity();
            // Priority slot, despite being background work. This fetch is the ONLY
            // step that can repair a key this device is missing, and it shares the
            // 5-slot pool with the envelope *publishing* sweep, which issues one POST
            // per device per scope. Measured on a real client: 11 098 envelope POSTs
            // against 689 fetches, 465 of the fetches (67%) timing out behind them.
            // Recovery was queued behind the storm it was supposed to end, so a device
            // holding the wrong key stayed that way and its messages stayed unreadable.
            const res = await this.apiFetch(this.apiRoutes.keyEnvelopes.list(identity.deviceId), {
                includeDeviceId: true,
                interactive: true,
            });
            if (!res.ok) throw new Error(await res.text().catch(() => 'Не удалось получить key envelopes'));
            const envelopes = await res.json();
            if (!Array.isArray(envelopes) || !envelopes.length) {
                this.addLogEntry({ type: 'INFO', msg: `Ключи: на сервере нет конвертов для этого устройства (${String(identity.deviceId || '').slice(0, 12)})`, ts: new Date().toLocaleTimeString() });
                return 0;
            }
            // One batched lookup of the canonical key id per scope in this batch.
            // With it, adoption is a fact ("this envelope carries the registered
            // key") instead of the old lexicographic-owner guess, which had no rule
            // at all for `server:` channel scopes — every channel member kept their
            // own key forever and only ever converged by luck.
            const batchScopes = Array.from(new Set(
                envelopes
                    .map(record => this.canonicalConversationScope(String(record?.scope || '').trim()))
                    .filter(Boolean)
            ));
            const canonical = await this.fetchCanonicalKeyIds(batchScopes);

            // Envelopes are never deleted server-side, and every sync re-downloads the
            // whole set for this device — a full ECDH derive plus AES open per row, on
            // a path that runs on login, on every key_envelope_available push, on every
            // refreshAfterKey and on every decrypt failure.
            //
            // The skip condition is deliberately the strongest one available: not "we
            // have seen this row" but "we already hold the exact key this row was
            // carrying, for the scope it named". Anything weaker can drop key material.
            // The first version of this skipped a row whenever its scope held *any*
            // key, which is wrong the moment a scope has more than one (the normal
            // state — that is what `alt:` candidates are), and the harness caught it as
            // devices ending up with one candidate out of thirty-seven envelopes.
            //
            // A row with no id or no timestamp is never memoised: a missing field must
            // degrade to "open it again", never to "skip everything".
            //
            // In memory only, so a relaunch re-imports the lot — that is the recovery
            // path for a device whose key store was wiped, and it must not be memoised
            // away.
            if (!this._openedEnvelopeStamps) this._openedEnvelopeStamps = new Map();
            const seen = this._openedEnvelopeStamps;

            // Opened OUTSIDE the write lock, on a snapshot of the key store used only
            // to answer "would re-opening this row tell us anything new?".
            //
            // Decryption is per-envelope ECDH: two key imports and a derive apiece, and
            // a real account fetches a few hundred rows. Doing that inside the lock
            // meant every other writer — the "generate a key for this new chat" write
            // on the chat-open path above all — queued behind the whole batch. The lock
            // exists to serialise the load-mutate-save cycle, and that is all it now
            // covers; the decrypted results are applied to a freshly loaded map inside
            // it, so nothing is decided from the snapshot.
            const snapshot = this.loadStoredConversationKeys();
            let decryptFailed = 0;
            let skippedKnown = 0;
            const opened = [];
            for (const record of envelopes) {
                try {
                    const envelopeId = String(record?.envelopeId || '').trim();
                    const createdAt = String(record?.createdAt || '').trim();
                    // A republish upserts the row with a fresh created_at, so an
                    // updated envelope misses the memo and is opened again.
                    const stamp = (envelopeId && createdAt) ? `${envelopeId}|${createdAt}` : '';
                    const memo = stamp ? seen.get(stamp) : null;
                    if (memo && this.conversationKeyCandidates(snapshot, memo.scope).includes(memo.key)) {
                        skippedKnown += 1;
                        continue;
                    }
                    const payload = await this.decryptConversationKeyEnvelope(record?.encryptedKey);
                    if (!payload.scope || !payload.key) continue;
                    // The sender may predate canonicalConversationScope, so fold
                    // its scope before it is used as a storage/registry key.
                    const scope = this.canonicalConversationScope(String(payload.scope));
                    // Remember exactly what this row was carrying, so the check
                    // above can prove the re-open would be a no-op before skipping.
                    if (stamp) {
                        seen.set(stamp, { scope, key: payload.key });
                        if (seen.size > 4000) seen.delete(seen.keys().next().value);
                    }
                    opened.push({ scope, payload });
                } catch (e) {
                    decryptFailed += 1;
                    this.trace(`syncIncomingKeyEnvelopes decrypt failed reason=${reason} error=${e?.message || e}`);
                }
            }

            // The load-mutate-save below must not race promoteCanonicalConversationKey
            // or the "generate a new key" write in _resolveConversationCryptoKeyImpl —
            // both can run concurrently in the background for a different scope. See
            // withConversationKeysWriteLock.
            const { imported, skippedSame } = await this.withConversationKeysWriteLock(async () => {
                const stored = this.loadStoredConversationKeys();
                let imported = 0;
                let skippedSame = 0;
                for (const { scope, payload } of opened) {
                    const current = String(stored[scope] || '').trim();
                    // Ключ канала выводится локально и активным остаётся всегда он.
                    // Конверт от старого клиента принимаем только как кандидата на
                    // расшифровку — иначе он снова уводил бы канал на случайный ключ,
                    // которого нет у остальных.
                    if (this.isServerChannelScope(scope)) {
                        if (this.addAltConversationKey(stored, scope, payload.key)) imported += 1;
                        else skippedSame += 1;
                        continue;
                    }
                    const wantedKeyId = String(canonical.get(scope) || '').trim();
                    const isCanonical = wantedKeyId
                        ? (await this.conversationKeyId(payload.key)) === wantedKeyId
                        : false;
                    if (!current) {
                        stored[scope] = payload.key;
                        imported += 1;
                    } else if (current !== payload.key && isCanonical) {
                        this.trace(`syncIncomingKeyEnvelopes adopt canonical key scope=${scope} sender=${payload.sender}`);
                        this.setActiveConversationKey(stored, scope, payload.key);
                        imported += 1;
                    } else if (current !== payload.key && !wantedKeyId && this.keyEnvelopeOverridesLocal(scope, payload)) {
                        // The canonical owner's key becomes the active (sending) key so
                        // both peers converge. Preserve the previous key as a decryption
                        // candidate so messages already encrypted with it stay readable.
                        this.trace(`syncIncomingKeyEnvelopes adopt owner key scope=${scope} sender=${payload.sender}`);
                        this.setActiveConversationKey(stored, scope, payload.key);
                        imported += 1;
                    } else if (current !== payload.key) {
                        // Not the canonical key, but keep it as a decryption candidate:
                        // the peer may have encrypted messages with it before convergence.
                        if (this.addAltConversationKey(stored, scope, payload.key)) imported += 1;
                        else skippedSame += 1;
                    } else {
                        skippedSame += 1;
                    }
                }
                if (imported > 0) {
                    this.saveStoredConversationKeys(stored);
                }
                return { imported, skippedSame };
            });
            // Surface the outcome in the in-app log panel. decryptFailed>0 means the
            // envelope was encrypted to a device key this client cannot open (device
            // identity mismatch) — that is why a delivered message stays unreadable.
            this.addLogEntry({
                type: decryptFailed > 0 ? 'WARN' : 'INFO',
                msg: `Ключи: получено ${envelopes.length}, принято ${imported}, совпало ${skippedSame}, уже разобрано ${skippedKnown}, не расшифровано ${decryptFailed} (reason=${reason})`,
                ts: new Date().toLocaleTimeString()
            });
            if (imported > 0) {
                this.trace(`syncIncomingKeyEnvelopes reason=${reason} imported=${imported}`);
                if (triggerRefresh) this.refreshAfterKey();
            }
            return imported;
        } catch (e) {
            this.trace(`syncIncomingKeyEnvelopes failed reason=${reason} error=${e?.message || e}`);
            return 0;
        }
    }

    async bootstrapDeviceTrust() {
        if (!this.S.session?.token) return;
        const identity = await this.timeStage('  ├ ensureDeviceCryptoIdentity', () => this.ensureDeviceCryptoIdentity());
        this.S.deviceTrust.current = identity;
        // Persist to the native shell now that the user is authenticated: ensureDeviceCryptoIdentity
        // returns early (no saveDeviceIdentity) when the identity is already complete, so the
        // in-memory identity might never have been mirrored to the native per-user file yet.
        this.persistDeviceIdentityToNative(identity);
        try {
            const res = await this.timeStage('  ├ devices.register(POST)', () => this.apiFetch(this.apiRoutes.devices.list, {
                method: 'POST',
                includeDeviceId: true,
                body: JSON.stringify({
                    deviceId: identity.deviceId,
                    label: identity.label,
                    publicKey: identity.publicKey,
                    signingKey: identity.signingKey,
                    keyPackage: identity.keyPackage,
                }),
            }));
            if (res.ok) {
                this.S.deviceTrust.current = await res.json();
            }
            // Neither the device-trust panel refresh nor a key-envelope sync is needed
            // before the chat can render, and postAuthSetup already syncs envelopes on
            // its critical path. Run these in the background so device registration does
            // not block startup (the sync could stall for the full request timeout).
            void this.timeStage('  ├ refreshDeviceTrust(bg)', () => this.refreshDeviceTrust());
            void this.timeStage('  └ syncIncomingKeyEnvelopes(bootstrap,bg)', () => this.syncIncomingKeyEnvelopes({ reason: 'bootstrapDeviceTrust' }));
        } catch (e) {
            this.S.deviceTrust.status = `Устройство не зарегистрировано: ${e?.message || e}`;
            this.renderDeviceTrustPanel();
        }
    }

    async resetEncryptionKeys() {
        this.trace('resetEncryptionKeys start');
        // 1. Clear local AES conversation keys
        this._publishedKeyScopes = new Set();
        this._vaultSnapshotApplied = false;
        // The key store is about to be emptied, so every envelope has to be openable
        // again — the memo would otherwise skip exactly the rows that refill it.
        this._openedEnvelopeStamps = null;
        // The user explicitly asked for new keys, so the sweep that fans them out
        // must not sit out retryPublishConversationKeys' coalescing window.
        this._lastKeyPublishSweepAt = 0;
        // Remember which scopes are being reset. Without this the registry would
        // defeat the reset: every regenerated key would lose the (non-forced)
        // claim to the pre-reset row and the client would keep asking the peer to
        // republish a key the user just deliberately threw away.
        //
        // Persisted, not held in a Set on the instance: a scope is only force-claimed
        // when that conversation is next resolved, so an in-memory queue silently
        // expired at the next relaunch and the reset never reached any chat the user
        // had not happened to open in that session.
        this.queueForceClaimScopes(
            Object.keys(this.loadStoredConversationKeys())
                .filter(scope => scope.startsWith('dm:') || scope.startsWith('server:'))
        );
        // Every scope is about to get a brand-new key of our own making, so no scope
        // is waiting on an unreachable canonical key any more.
        this.saveScopeMarkMap(this.staleCanonicalStorageKey(), {});
        this.canonicalKeyIdCache().clear();
        this.saveStoredConversationKeys({});
        try { sessionStorage.removeItem(this.cryptoKeyStorageKey()); } catch (e) {}
        try { localStorage.removeItem(this.cryptoKeyStorageKey()); } catch (e) {}

        // 2. Delete all server-side key envelopes (sent and received)
        try {
            await this.apiFetch(this.apiRoutes.keyEnvelopes.base, {
                method: 'DELETE',
                includeDeviceId: true,
            });
        } catch (e) {
            this.trace(`resetEncryptionKeys server delete failed: ${e?.message || e}`);
        }

        // 3. Regenerate ECDH keypair — strip e2ee from identity, let ensureDeviceCryptoIdentity rebuild it
        const identity = this.loadDeviceIdentity();
        const stripped = { ...identity, privateKeyJwk: undefined };
        if (stripped.keyPackage && typeof stripped.keyPackage === 'object') {
            stripped.keyPackage = { ...stripped.keyPackage };
            delete stripped.keyPackage.e2ee;
        }
        delete stripped.privateKeyJwk;
        this.saveDeviceIdentity(stripped);

        // 4. Generate new ECDH keypair and push new public key to server
        await this.bootstrapDeviceTrust();
        this.trace('resetEncryptionKeys done');
    }

    async refreshDeviceTrust() {
        if (!this.S.session?.token) return;
        try {
            const res = await this.apiFetch(this.apiRoutes.devices.list, { includeDeviceId: true });
            if (!res.ok) throw new Error(await res.text().catch(() => 'Не удалось загрузить устройства'));
            this.S.deviceTrust.devices = await res.json();
            this.renderDeviceTrustPanel();
        } catch (e) {
            this.S.deviceTrust.status = `Список устройств недоступен: ${e?.message || e}`;
            this.renderDeviceTrustPanel();
        }
    }

    async approveDeviceAndExport(deviceId) {
        const targetId = String(deviceId || '').trim();
        if (!targetId) return;
        if (!this.loadStoredCryptoKey() && !Object.keys(this.loadStoredConversationKeys()).length) {
            this.S.deviceTrust.status = 'Сначала задайте ключ шифрования или откройте чат с уже заданным ключом.';
            this.renderDeviceTrustPanel();
            return;
        }
        const code = this.randomBase64(12).replace(/[+/=]/g, '').slice(0, 16);
        try {
            const res = await this.apiFetch(this.apiRoutes.devices.approve, {
                method: 'POST',
                includeDeviceId: true,
                body: JSON.stringify({
                    deviceId: targetId,
                    approvedByDeviceId: this.currentDeviceId(),
                    historyDays: 30,
                }),
            });
            if (!res.ok) throw new Error(await res.text().catch(() => 'Не удалось подтвердить устройство'));

            const payload = this.buildVaultPlainPayload(targetId);
            const encryptedVaultEvent = await this.encryptVaultPackage(payload, code);
            const vaultRes = await this.apiFetch(this.apiRoutes.vault.events, {
                method: 'POST',
                body: JSON.stringify({
                    // Targeted at the new device specifically — it's encrypted with a
                    // one-time code, not the account passphrase, so it must not be
                    // mistaken for the regular auto-sync broadcast event by any client
"""#,
    #"""
                    // that filters on issuedToDeviceId.
                    issuedToDeviceId: targetId,
                    vaultEpoch: payload.vaultEpoch,
                    encryptedVaultEvent,
                }),
            });
            if (!vaultRes.ok) {
                throw new Error(await vaultRes.text().catch(() => 'Не удалось сохранить vault event'));
            }

            const now = new Date();
            const from = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
            const expires = new Date(now.getTime() + 60 * 60 * 1000);
            const scopes = Object.keys(payload.conversationKeys || {})
                .filter(scope => !String(scope).startsWith('alt:'));
            await Promise.all(scopes.slice(0, 50).map(async scope => {
                const res = await this.apiFetch(this.apiRoutes.historyTickets, {
                    method: 'POST',
                    includeDeviceId: true,
                    body: JSON.stringify({
                        issuedByDeviceId: this.currentDeviceId(),
                        issuedToDeviceId: targetId,
                        conversationId: scope,
                        fromTime: from.toISOString(),
                        toTime: now.toISOString(),
                        expiresAt: expires.toISOString(),
                        encryptedExportSecrets: encryptedVaultEvent,
                    }),
                });
                if (!res.ok) {
                    throw new Error(await res.text().catch(() => 'Не удалось сохранить history ticket'));
                }
                return res;
            }));

            this.S.deviceTrust.exportPackage = encryptedVaultEvent;
            this.S.deviceTrust.exportCode = code;
            this.S.deviceTrust.status = `Устройство подтверждено. Передайте bootstrap package и код ${code} на новое устройство.`;
            await this.refreshDeviceTrust();
        } catch (e) {
            this.S.deviceTrust.status = `Не удалось подтвердить устройство: ${e?.message || e}`;
            this.renderDeviceTrustPanel();
        }
    }

    async importVaultPackageFromInputs() {
        const packageText = String(document.getElementById('deviceVaultPackageInput')?.value || this.S.deviceTrust.importPackage || '').trim();
        const code = String(document.getElementById('deviceVaultCodeInput')?.value || this.S.deviceTrust.importCode || '').trim();
        if (!packageText || !code) {
            this.S.deviceTrust.status = 'Вставьте vault package и одноразовый код.';
            this.renderDeviceTrustPanel();
            return;
        }
        try {
            const payload = await this.decryptVaultPackage(packageText, code);
            const count = this.applyVaultPlainPayload(payload);
            this.S.deviceTrust.status = `Vault импортирован: ключей чатов ${count}. История перечитывается с учетом разрешенного окна.`;
            await this.refreshAfterKey();
            this.renderDeviceTrustPanel();
        } catch (e) {
            this.S.deviceTrust.status = `Vault не расшифрован: ${e?.message || e}`;
            this.renderDeviceTrustPanel();
        }
    }

    async exportCurrentVaultPackage() {
        const code = String(document.getElementById('deviceVaultManualCodeInput')?.value || '').trim() || this.randomBase64(12).replace(/[+/=]/g, '').slice(0, 16);
        try {
            const payload = this.buildVaultPlainPayload('');
            const encrypted = await this.encryptVaultPackage(payload, code);
            this.S.deviceTrust.exportPackage = encrypted;
            this.S.deviceTrust.exportCode = code;
            this.S.deviceTrust.status = `Vault package создан. Код: ${code}`;
            if (this.S.session?.token) {
                const vaultRes = await this.apiFetch(this.apiRoutes.vault.events, {
                    method: 'POST',
                    body: JSON.stringify({
                        vaultEpoch: payload.vaultEpoch,
                        encryptedVaultEvent: encrypted,
                    }),
                });
                if (!vaultRes.ok) {
                    throw new Error(await vaultRes.text().catch(() => 'Не удалось сохранить vault event'));
                }
            }
            this.renderDeviceTrustPanel();
        } catch (e) {
            this.S.deviceTrust.status = `Не удалось создать vault package: ${e?.message || e}`;
            this.renderDeviceTrustPanel();
        }
    }

    async revokeTrustedDevice(deviceId) {
        const id = String(deviceId || '').trim();
        if (!id || id === this.currentDeviceId()) {
            this.S.deviceTrust.status = 'Текущее устройство нельзя отозвать из этого блока.';
            this.renderDeviceTrustPanel();
            return;
        }
        try {
            const res = await this.apiFetch(this.apiRoutes.devices.byId(id), { method: 'DELETE', includeDeviceId: true });
            if (!res.ok) throw new Error(await res.text().catch(() => 'Не удалось отозвать устройство'));
            this.S.deviceTrust.status = 'Устройство отозвано, сервер создал новую эпоху device group.';
            await this.refreshDeviceTrust();
        } catch (e) {
            this.S.deviceTrust.status = `Отзыв не выполнен: ${e?.message || e}`;
            this.renderDeviceTrustPanel();
        }
    }

    renderDeviceTrustPanel() {
        const currentEl = document.getElementById('deviceTrustCurrent');
        const listEl = document.getElementById('deviceTrustList');
        const statusEl = document.getElementById('deviceTrustStatus');
        const packageEl = document.getElementById('deviceVaultExportPackage');
        const codeEl = document.getElementById('deviceVaultExportCode');
        if (currentEl) {
            const current = this.S.deviceTrust.current || this.loadDeviceIdentity();
            currentEl.textContent = current?.deviceId ? `${current.label || 'Устройство'} · ${current.deviceId}` : 'не зарегистрировано';
        }
        if (statusEl) statusEl.textContent = this.S.deviceTrust.status || '';
        if (packageEl && packageEl.value !== this.S.deviceTrust.exportPackage) packageEl.value = this.S.deviceTrust.exportPackage || '';
        if (codeEl) codeEl.textContent = this.S.deviceTrust.exportCode ? `Код: ${this.S.deviceTrust.exportCode}` : 'Код появится после экспорта';
        if (!listEl) return;
        const devices = Array.isArray(this.S.deviceTrust.devices) ? this.S.deviceTrust.devices : [];
        if (!devices.length) {
            listEl.innerHTML = '<p class="settings-help">После входа устройство зарегистрируется автоматически.</p>';
            return;
        }
        listEl.innerHTML = devices.map(device => {
            const id = String(device.deviceId || '').trim();
            const isCurrent = id === this.currentDeviceId();
            const state = device.revoked ? 'отозвано' : device.approved ? 'доверенное' : 'ожидает';
            const actions = device.revoked ? ''
                : !device.approved
                    ? `<button class="btn-flat" type="button" data-device-approve="${this.esc(id)}">Подтвердить</button>`
                    : (!isCurrent ? `<button class="btn-flat" type="button" data-device-revoke="${this.esc(id)}">Отозвать</button>` : '');
            return `
                <div class="device-row">
                    <div>
                        <strong>${this.esc(device.label || 'Устройство')}</strong>
                        <small>${this.esc(id)} · эпоха ${this.esc(device.groupEpoch || 1)} · ${this.esc(state)}</small>
                    </div>
                    <div class="settings-inline-actions">${actions}</div>
                </div>
            `;
        }).join('');
    }

    updateChatHeaderCryptoKey({ peer = null, serverId = null, channelId = null } = {}) {
        const chatHdrSub = document.getElementById('chatHdrSub');
        if (!chatHdrSub) return;
        const key = this.ensureConversationCryptoKey({ peer, serverId, channelId, reason: 'updateChatHeaderCryptoKey' });
        if (serverId && channelId) {
            // Раньше здесь печатались сырые uuid сервера и канала — пользователю они
            // не говорят ничего, а занимали две строки шапки. Показываем то же, что
            // ставит renderServerToolbar: имя сервера и тему канала.
            const server = this.currentServer();
            const channel = this.currentChannel();
            const desc = server
                ? `${String(server.name || '').trim()}${channel?.topic ? ` · ${String(channel.topic).trim()}` : ''}`
                : '';
            // Индикатор ключа тоже убран: у канала ключ выводится из его scope и есть
            // всегда, сообщать тут было бы не о чем.
            chatHdrSub.textContent = desc;
            return;
        }
        const desc = peer ? `Диалог с ${String(peer).trim()}` : 'Личное сообщение';
        chatHdrSub.innerHTML = `
            <span class="chat-hdr-desc">${this.esc(desc)}</span>
            <span class="chat-hdr-key">${this.esc(key ? 'Ключ: задан' : 'Ключ: не задан')}</span>
        `;
    }

    saveStoredCryptoKey(key) {
        try {
            const value = (key || '').trim();
            this.trace(`saveStoredCryptoKey keySet=${!!value} length=${value.length}`);
            if (value) {
                sessionStorage.setItem(this.cryptoKeyStorageKey(), value);
                localStorage.removeItem(this.cryptoKeyStorageKey());
            } else {
                sessionStorage.removeItem(this.cryptoKeyStorageKey());
                localStorage.removeItem(this.cryptoKeyStorageKey());
            }
            try {
                window.__ZALI_SAVED_KEY = value;
            } catch (e) {}
            try {
                const scope = String(window.__ZALI_ACTIVE_CONVERSATION_SCOPE || this.activeConversationScope || '').trim();
                if (scope) {
                    const stored = this.loadStoredConversationKeys();
                    if (value) {
                        stored[scope] = value;
                    } else {
                        delete stored[scope];
                    }
                    this.saveStoredConversationKeys(stored);
                }
            } catch (e) {}
            if (this.nativeSupports('setKey')) {
                this.trace(`saveStoredCryptoKey native setKey keySet=${!!value}`);
                this.syncNativeConversationKeys();
            }
            if (this.S.session?.token && this.S.auth?.vaultPassphrase && !this.cloudVaultSyncInFlight) {
                this.scheduleCloudVaultSync(300);
            }
        } catch (e) {}
    }
});


// --- MODULE: interface/session.js ---
// --- ZaliInterface: Сессия и токен, недавние аккаунты, снапшот здоровья звонка. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    loadStoredSession(key = null) {
        try {
            const raw = localStorage.getItem(key || this.authStorageKey());
            if (!raw) {
                const injected = key ? null : this.loadInjectedSession();
                this.trace(`loadStoredSession key=${key || 'auth'} local=no injected=${!!injected}`);
                return this.normalizeSession(injected);
            }
            const parsed = JSON.parse(raw);
            if (!parsed || typeof parsed !== 'object') return null;
            const normalized = this.normalizeSession(parsed);
            const token = String(normalized?.token || '').trim();
            if (!token) {
                const injected = key ? null : this.loadInjectedSession();
                this.trace(`loadStoredSession key=${key || 'auth'} local=tokenless injected=${!!injected}`);
                return this.normalizeSession(injected) || null;
            }
            this.trace(`loadStoredSession key=${key || 'auth'} local=yes`);
            return normalized;
        } catch (e) {
            this.trace(`loadStoredSession key=${key || 'auth'} error`);
            if (!key) {
                return this.normalizeSession(this.loadInjectedSession());
            }
            return null;
        }
    }

    normalizeSession(session) {
        if (!session || typeof session !== 'object') return null;
        const username = String(session.username || session.user || '').trim();
        const token = String(
            session.token
            || session.authToken
            || session.accessToken
            || session.sessionToken
            || session.jwt
            || ''
        ).trim();
        if (!token) return null;
        return {
            username,
            token,
            guest: !!session.guest || false,
            tokenExpiresAt: Number(session.tokenExpiresAt || this.tokenExpiresAt(token) || 0),
        };
    }

    decodeJwtPayload(token) {
        try {
            const parts = String(token || '').split('.');
            if (parts.length < 2) return null;
            const normalized = parts[1].replace(/-/g, '+').replace(/_/g, '/');
            const padded = normalized.padEnd(Math.ceil(normalized.length / 4) * 4, '=');
            return JSON.parse(atob(padded));
        } catch (e) {
            return null;
        }
    }

    tokenExpiresAt(token) {
        const payload = this.decodeJwtPayload(token);
        const exp = Number(payload?.exp || 0);
        return exp > 0 ? exp * 1000 : 0;
    }

    isTokenExpired(token, skewMs = 30000) {
        const expiresAt = this.tokenExpiresAt(token);
        return expiresAt > 0 && expiresAt <= Date.now() + skewMs;
    }

    loadInjectedSession() {
        try {
            const raw = window.__ZALI_SAVED_SESSION;
            if (!raw || typeof raw !== 'object') return null;
            if (raw.token && this.isTokenExpired(raw.token)) return null;
            return this.normalizeSession(raw);
        } catch (e) {
            return null;
        }
    }

    formatDuration(ms) {
        const total = Math.max(0, Math.floor(Number(ms || 0) / 1000));
        const hours = Math.floor(total / 3600);
        const minutes = Math.floor((total % 3600) / 60);
        const seconds = total % 60;
        const pad = (v) => String(v).padStart(2, '0');
        return hours > 0 ? `${hours}:${pad(minutes)}:${pad(seconds)}` : `${pad(minutes)}:${pad(seconds)}`;
    }

    formatBytes(bytes) {
        const value = Math.max(0, Number(bytes || 0));
        if (!value) return '0 B';
        const units = ['B', 'KB', 'MB', 'GB'];
        let idx = 0;
        let current = value;
        while (current >= 1024 && idx < units.length - 1) {
            current /= 1024;
            idx += 1;
        }
        const digits = current >= 100 || idx === 0 ? 0 : current >= 10 ? 1 : 2;
        return `${current.toFixed(digits)} ${units[idx]}`;
    }

    describeIceCandidate(candidateLine) {
        const parts = String(candidateLine || '').trim().split(/\s+/);
        const typIndex = parts.indexOf('typ');
        return {
            protocol: String(parts[2] || '').toLowerCase(),
            address: parts[4] && parts[5] ? `${parts[4]}:${parts[5]}` : '',
            type: typIndex >= 0 ? String(parts[typIndex + 1] || '') : '',
        };
    }

    getVoicePrimaryPeerName() {
        const peers = Array.from(this.voice.peerConnections.keys()).map(name => String(name || '').trim()).filter(Boolean);
        const me = String(this.myName() || '').trim();
        const preferred = String(this.voice.targetUser || this.voice.inviter || '').trim();
        if (preferred && peers.includes(preferred)) return preferred;
        if (this.voice.roomType === 'dm') {
            const nonMe = peers.find(name => name !== me);
            if (nonMe) return nonMe;
        }
        return peers[0] || preferred || '';
    }

    getVoiceHealthSnapshot() {
        const peer = this.getVoicePrimaryPeerName();
        const entry = peer ? this.voice.peerConnections.get(peer) : null;
        const stats = entry?.lastStats || {};
        const audio = peer ? this.voice.remoteAudios.get(peer) : null;
        const remoteStream = audio?.srcObject instanceof MediaStream ? audio.srcObject : null;
        const localStream = this.voice.localStream;
        const connectionState = String(entry?.pc?.connectionState || 'idle').trim() || 'idle';
        const iceState = String(entry?.pc?.iceConnectionState || 'idle').trim() || 'idle';
        const signalingState = String(entry?.pc?.signalingState || 'idle').trim() || 'idle';
        const hasOut = Number(stats.outBytes || 0) > 0 || Number(stats.outPackets || 0) > 0;
        const hasIn = Number(stats.inBytes || 0) > 0 || Number(stats.inPackets || 0) > 0;
        const candidatePair = stats.candidatePair || null;
        const localCandidates = Number(stats.localCandidateCount || entry?.generatedIceCandidates || 0);
        const remoteCandidates = Number(stats.remoteCandidateCount || entry?.receivedIceCandidates || 0);
        const remoteTrackCount = remoteStream ? remoteStream.getAudioTracks().length : 0;
        const routeValue = audio
            ? (audio.muted ? 'audio muted' : audio.paused ? 'audio paused' : 'audio ready')
            : remoteTrackCount
                ? 'stream only'
                : 'нет трека';
        const playbackValue = audio
            ? (audio.paused ? 'paused' : audio.readyState >= 2 ? 'playing' : 'waiting')
            : 'none';
        const micValue = localStream
            ? `${localStream.getAudioTracks().length} track${localStream.getAudioTracks().length === 1 ? '' : 's'}`
            : 'нет микрофона';

        const toneByState = (state, activeTone = 'good') => {
            const s = String(state || '').toLowerCase();
            if (['connected', 'completed', 'playing', 'ready', 'live'].includes(s)) return 'good';
            if (['connecting', 'checking', 'new', 'waiting', 'idle'].includes(s)) return 'warn';
            if (['disconnected', 'failed', 'closed', 'paused'].includes(s)) return 'bad';
            return activeTone;
        };

        return [
            {
                label: 'ICE',
                value: iceState,
                sub: connectionState === 'connected' ? 'канал поднят' : 'ожидаем согласование',
                tone: toneByState(iceState),
            },
            {
                label: 'RTP out',
                value: hasOut ? `${this.formatBytes(stats.outBytes || 0)} · ${stats.outPackets || 0} pkts` : '0 B',
                sub: hasOut ? 'уходит в сеть' : 'пока тишина',
                tone: hasOut ? 'good' : toneByState(connectionState, 'warn'),
            },
            {
                label: 'RTP in',
                value: hasIn ? `${this.formatBytes(stats.inBytes || 0)} · ${stats.inPackets || 0} pkts` : '0 B',
                sub: hasIn ? 'приходит с удалённой стороны' : 'не получаем RTP',
                tone: hasIn ? 'good' : 'bad',
            },
            {
                label: 'Candidate pair',
                value: candidatePair ? `${candidatePair.localLabel || candidatePair.local || 'local'} → ${candidatePair.remoteLabel || candidatePair.remote || 'remote'}` : 'не выбран',
                sub: candidatePair ? `rtt ${candidatePair.currentRoundTripTime ?? 'n/a'} · ${this.formatBytes(candidatePair.bytesSent || 0)} / ${this.formatBytes(candidatePair.bytesReceived || 0)}` : `local ${localCandidates} / remote ${remoteCandidates}`,
                tone: candidatePair ? 'good' : 'warn',
            },
            {
                label: 'Audio route',
                value: routeValue,
                sub: remoteTrackCount ? `tracks: ${remoteTrackCount}` : 'ждём remote-track',
                tone: remoteTrackCount ? 'good' : 'warn',
            },
            {
                label: 'Playback',
                value: playbackValue,
                sub: micValue,
                tone: audio ? (audio.paused ? 'warn' : 'good') : 'idle',
            },
        ];
    }

    saveStoredSession(session) {
        try {
            localStorage.setItem(this.authStorageKey(), JSON.stringify(session));
            localStorage.setItem(this.lastAuthStorageKey(), JSON.stringify(session));
            this.rememberRecentAccount(session);
            this.saveInjectedSession(session);
        } catch (e) {
            // ignore storage failures
        }
    }

    loadRecentAccounts() {
        try {
            const raw = localStorage.getItem(this.recentAccountsStorageKey());
            const parsed = raw ? JSON.parse(raw) : [];
            if (!Array.isArray(parsed)) return [];
            const seenUsers = new Set();
            const seenTokens = new Set();
            return parsed
                .map(item => ({
                    ...this.normalizeSession(item),
                    lastUsedAt: Number(item?.lastUsedAt || 0),
                }))
                .filter(item => item?.token && !item.guest && !this.isTokenExpired(item.token))
                .sort((a, b) => Number(b.lastUsedAt || 0) - Number(a.lastUsedAt || 0))
                .filter(item => {
                    const userKey = String(item.username || '').trim().toLowerCase();
                    const tokenKey = String(item.token || '').trim();
                    if (!userKey || !tokenKey || seenUsers.has(userKey) || seenTokens.has(tokenKey)) return false;
                    seenUsers.add(userKey);
                    seenTokens.add(tokenKey);
                    return true;
                })
                .slice(0, 6);
        } catch (e) {
            return [];
        }
    }

    saveRecentAccounts(accounts) {
        try {
            const seenUsers = new Set();
            const seenTokens = new Set();
            const normalized = [];
            for (const account of Array.isArray(accounts) ? accounts : []) {
                const session = this.normalizeSession(account);
                if (!session?.token || session.guest) continue;
                if (this.isTokenExpired(session.token)) continue;
                const key = String(session.username || '').trim().toLowerCase();
                const tokenKey = String(session.token || '').trim();
                if (!key || !tokenKey || seenUsers.has(key) || seenTokens.has(tokenKey)) continue;
                seenUsers.add(key);
                seenTokens.add(tokenKey);
                normalized.push({
                    username: session.username,
                    token: session.token,
                    guest: false,
                    lastUsedAt: Number(account?.lastUsedAt || Date.now()),
                    tokenExpiresAt: Number(session.tokenExpiresAt || this.tokenExpiresAt(session.token) || 0),
                });
                if (normalized.length >= 6) break;
            }
            localStorage.setItem(this.recentAccountsStorageKey(), JSON.stringify(normalized));
        } catch (e) {
            // ignore storage failures
        }
    }

    rememberRecentAccount(session) {
        const normalized = this.normalizeSession(session);
        if (!normalized?.token || normalized.guest) return;
        const key = String(normalized.username || '').trim().toLowerCase();
        if (!key) return;
        const rest = this.loadRecentAccounts()
            .filter(item => String(item.username || '').trim().toLowerCase() !== key);
        this.saveRecentAccounts([
            {
                username: normalized.username,
                token: normalized.token,
                guest: false,
                lastUsedAt: Date.now(),
                tokenExpiresAt: Number(normalized.tokenExpiresAt || this.tokenExpiresAt(normalized.token) || 0),
            },
            ...rest,
        ]);
        this.renderRecentAccounts();
    }

    forgetRecentAccount(username) {
        const key = String(username || '').trim().toLowerCase();
        if (!key) return;
        const next = this.loadRecentAccounts()
            .filter(item => String(item.username || '').trim().toLowerCase() !== key);
        this.saveRecentAccounts(next);
        this.renderRecentAccounts();
    }

    forgetRecentAccountEntry(username, token = '') {
        const userKey = String(username || '').trim().toLowerCase();
        const tokenKey = String(token || '').trim();
        if (!userKey && !tokenKey) return;
        const next = this.loadRecentAccounts()
            .filter(item => {
                const itemUser = String(item.username || '').trim().toLowerCase();
                const itemToken = String(item.token || '').trim();
                return (!userKey || itemUser !== userKey) && (!tokenKey || itemToken !== tokenKey);
            });
        this.saveRecentAccounts(next);
        this.renderRecentAccounts();
    }

    async verifyRecentAccountSession(session) {
        try {
            const token = String(session?.token || '').trim();
            if (!token) return { ok: false, invalidate: true };
            const res = await this.apiFetch(this.apiRoutes.auth.me, {
                timeoutMs: SESSION_RESTORE_TIMEOUT_MS,
                headers: {
                    Authorization: `Bearer ${token}`,
                },
            });
            if (!res.ok) {
                const status = Number(res.status || 0);
                return {
                    ok: false,
                    invalidate: status === 401 || status === 403,
                };
            }
            const data = await res.json();
            return {
                ok: true,
                invalidate: false,
                username: String(data?.username || session?.username || '').trim(),
                token,
                cloudVaultSyncEnabled: data?.cloudVaultSyncEnabled,
            };
        } catch (e) {
            return { ok: false, invalidate: false };
        }
    }

    formatRecentAccountTime(ts) {
        const value = Number(ts || 0);
        if (!value) return 'недавний вход';
        try {
            return `вход ${new Date(value).toLocaleDateString('ru-RU', {
                day: '2-digit',
                month: 'short',
                hour: '2-digit',
                minute: '2-digit',
            })}`;
        } catch (e) {
            return 'недавний вход';
        }
    }

    renderRecentAccounts() {
        const box = document.getElementById('recentAccounts');
        if (!box) return;
        const accounts = this.loadRecentAccounts();
        if (!accounts.length) {
            box.innerHTML = '<div class="recent-accounts-empty">После входа аккаунты появятся здесь для быстрого переключения на этом Mac.</div>';
            return;
        }
        const current = String(this.S.session?.username || '').trim().toLowerCase();
        const rows = accounts.map(account => {
            const username = String(account.username || '').trim();
            const active = username.toLowerCase() === current && !!this.S.session?.token;
            return `
                <div class="recent-account-row ${active ? 'is-active' : ''}">
                    <div class="recent-account-main">
                        <div class="recent-account-name">${this.esc(username)}</div>
                        <div class="recent-account-meta">${active ? 'текущий аккаунт' : this.esc(this.formatRecentAccountTime(account.lastUsedAt))}</div>
                    </div>
                    <div class="recent-account-actions">
                        <button class="btn-flat recent-account-switch" type="button" data-switch-account="${this.esc(username)}" ${active ? 'disabled' : ''}>${active ? 'Активен' : 'Войти'}</button>
                        <button class="btn-flat recent-account-remove" type="button" data-remove-recent-account="${this.esc(username)}" title="Убрать из быстрых аккаунтов">×</button>
                    </div>
                </div>
            `;
        }).join('');
        box.innerHTML = `<div class="recent-accounts-title">Недавние аккаунты</div>${rows}`;
    }

    async switchRecentAccount(username) {
        const key = String(username || '').trim().toLowerCase();
        if (!key) return;
        const account = this.loadRecentAccounts()
            .find(item => String(item.username || '').trim().toLowerCase() === key);
        if (!account?.token) {
            this.forgetRecentAccount(username);
            return;
        }
        if (this.isTokenExpired(account.token)) {
            this.forgetRecentAccountEntry(account.username, account.token);
            const expiredMsg = `Сохранённый вход ${account.username} истёк. Войдите заново.`;
            this.addLogEntry({ type: 'WARN', msg: expiredMsg, ts: new Date().toLocaleTimeString() });
            this.S.auth.error = expiredMsg;
            this.updateAuthView();
            return;
        }

        this.addLogEntry({ type: 'INFO', msg: `Входим как ${account.username}...`, ts: new Date().toLocaleTimeString() });
        // Токен проверен локально — применяем сессию напрямую без HTTP round-trip.
        // Если токен окажется невалидным на сервере, первый же API-запрос вернёт 401
        // и handleUnauthorizedApiResponse инвалидирует сессию.
        this.applySession({
            username: account.username,
            token: account.token,
            guest: false,
        }, { persist: true, syncNative: true });

        // Account switch must run the same post-auth setup as a normal login:
        // register the device, pull incoming key envelopes (so this account adopts
        // the peer's conversation key) and re-publish our own. Without this the
        // switched-in account cannot decrypt the peer's messages — they show up as
        // "🔒 зашифровано другим ключом".
        this.startPostAuthSetup({ reason: 'switchAccount', restoreStoredUnlockSecret: true });

        // Show the chat immediately. Previously the switch awaited loadContacts +
        // loadUsers + loadServers + key sync sequentially (4 round-trips) before
        // opening the chat, which caused a ~15s delay. None of the sidebar data is
        // needed to render the active conversation.
        this.openChatView();
        this.addLogEntry({ type: 'SUCCESS', msg: `Аккаунт переключён: ${this.myName()}`, ts: new Date().toLocaleTimeString() });

        // refreshAfterKey pulls incoming key envelopes, resolves the conversation key
        // and reloads the active chat history — this is the only thing needed to show
        // the peer's messages, so it runs on its own (non-blocking) path.
        void this.timeStage('switch→чат готов (refreshAfterKey)', () => this.refreshAfterKey());

        // Sidebar data fills in afterwards in the background.
        void Promise.allSettled([
            this.loadContacts(),
            this.loadUsers(),
            this.loadServers({ silent: true }),
        ]).then(() => this.renderRecentAccounts());
    }

    saveInjectedSession(session) {
        try {
            window.__ZALI_SAVED_SESSION = session && typeof session === 'object' ? session : null;
        } catch (e) {}
    }

    clearStoredSession() {
        try {
            localStorage.removeItem(this.authStorageKey());
            this.saveInjectedSession(null);
        } catch (e) {
            // ignore storage failures
        }
    }
});


// --- MODULE: interface/outbox.js ---
// --- ZaliInterface: Очередь неотправленных сообщений и её досылка. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    loadPendingOutbox() {
        try {
            const raw = localStorage.getItem(this.pendingOutboxStorageKey());
            if (!raw) {
                const injected = this.loadInjectedPendingOutbox();
                this.trace(`loadPendingOutbox local=no injected=${injected.length}`);
                return injected;
            }
            const parsed = JSON.parse(raw);
            this.trace(`loadPendingOutbox local=yes count=${Array.isArray(parsed) ? parsed.length : 0}`);
            return Array.isArray(parsed) ? parsed.filter(item => item && typeof item === 'object') : this.loadInjectedPendingOutbox();
        } catch (e) {
            this.trace('loadPendingOutbox error fallback injected');
            return this.loadInjectedPendingOutbox();
        }
    }

    savePendingOutbox(items) {
        const next = Array.isArray(items) ? items : [];
        try {
            localStorage.setItem(this.pendingOutboxStorageKey(), JSON.stringify(next));
        } catch (e) {
            this.trace(`savePendingOutbox localStorage failed reason=${e?.name || e?.message || e}`);
            this.warnStorageFallback('pending_outbox', `Не удалось сохранить очередь отправки в localStorage: ${e?.name || e?.message || e}`);
        }
        this.trace(`savePendingOutbox count=${next.length}`);
        this.saveInjectedPendingOutbox(next);
        if (this.nativeSupports('sessionSync')) {
            this.trace(`savePendingOutbox native sync count=${next.length}`);
            this.postNativeMessage({
                type: NativeMessageTypes.SAVE_PENDING_OUTBOX,
                items: next,
            });
        }
    }

    pendingOutboxNextRetryDelay() {
        const now = Date.now();
        const currentUser = String(this.myName() || '').trim();
        const pending = this.loadPendingOutbox()
            .filter(item => !currentUser || String(item?.sender || '').trim() === currentUser);
        if (!pending.length) return null;
        let nextDelay = Infinity;
        for (const item of pending) {
            const retryAt = Number(item?.nextRetryAt || 0);
            if (!retryAt) {
                nextDelay = 0;
                break;
            }
            const delta = Math.max(0, retryAt - now);
            if (delta < nextDelay) nextDelay = delta;
        }
        return Number.isFinite(nextDelay) ? nextDelay : null;
    }

    loadInjectedPendingOutbox() {
        try {
            const raw = window.__ZALI_PENDING_OUTBOX;
            if (!Array.isArray(raw)) return [];
            return raw.filter(item => item && typeof item === 'object');
        } catch (e) {
            return [];
        }
    }

    saveInjectedPendingOutbox(items) {
        try {
            window.__ZALI_PENDING_OUTBOX = Array.isArray(items) ? items : [];
        } catch (e) {}
    }

    warnStorageFallback(scope, message) {
        const key = String(scope || 'storage').trim();
        if (!key || this.storageWarningSeen.has(key)) return;
        this.storageWarningSeen.add(key);
        if (typeof this.addLogEntry === 'function') {
            this.addLogEntry({
                type: 'WARN',
                msg: message,
                ts: new Date().toLocaleTimeString(),
            });
        }
    }

    pendingOutboxConversationKey(item) {
        const serverId = String(item?.serverId || '').trim();
        const channelId = String(item?.channelId || '').trim();
        const sender = String(item?.sender || '').trim();
        const receiver = String(item?.receiver || '').trim();
        return serverId && channelId
            ? `server:${serverId}:${channelId}:${sender}:${receiver}`
            : `dm:${sender}:${receiver}`;
    }

    messageConversationKey(msg) {
        const serverId = String(msg?.serverId || msg?.server_id || '').trim();
        const channelId = String(msg?.channelId || msg?.channel_id || '').trim();
        const sender = String(msg?.sender || '').trim();
        const receiver = String(msg?.receiver || '').trim();
        return serverId && channelId
            ? `server:${serverId}:${channelId}:${sender}:${receiver}`
            : `dm:${sender}:${receiver}`;
    }

    pendingOutboxContentKey(item) {
        const attachmentsKey = this.normalizeAttachments(item?.attachments).map(att => `${att.name}:${att.kind}:${att.size}:${att.mimeType}`).join('|');
        return [
            String(item?.text || ''),
            attachmentsKey,
        ].join('::');
    }

    messageContentKey(msg) {
        const attachmentsKey = this.normalizeAttachments(msg?.attachments).map(att => `${att.name}:${att.kind}:${att.size}:${att.mimeType}`).join('|');
        const call = msg?.kind === 'call' ? msg.call || {} : {};
        return [
            String(msg?.kind || ''),
            String(msg?.text || ''),
            String(call.roomId || ''),
            String(call.direction || ''),
            String(call.outcome || ''),
            String(call.peer || ''),
            String(call.durationMs || ''),
            attachmentsKey,
        ].join('::');
    }

    matchPendingOutboxItem(msg) {
        const contentKey = this.messageContentKey(msg);
        const conversationKey = this.messageConversationKey(msg);
        const sender = String(msg?.sender || '').trim();
        const receiver = String(msg?.receiver || '').trim();
        const serverId = String(msg?.serverId || msg?.server_id || '').trim();
        const channelId = String(msg?.channelId || msg?.channel_id || '').trim();
        const pending = this.loadPendingOutbox();
        return pending.find(item => {
            if (!item || typeof item !== 'object') return false;
            if (this.pendingOutboxConversationKey(item) !== conversationKey) return false;
            if (String(item.sender || '').trim() !== sender) return false;
            if (String(item.receiver || '').trim() !== receiver) return false;
            if (serverId && String(item.serverId || '').trim() !== serverId) return false;
            if (channelId && String(item.channelId || '').trim() !== channelId) return false;
            return this.pendingOutboxContentKey(item) === contentKey;
        }) || null;
    }

    cachePendingOutboxAttachments(clientId, attachments) {
        const key = String(clientId || '').trim();
        if (!key) return;
        // localStorage persists outbox attachments without dataUrl (quota), so the
        // payload needed for a retry lives only in this in-session cache.
        const withData = this.normalizeAttachments(attachments).filter(att => att.dataUrl);
        if (!withData.length) return;
        if (!this._outboxAttachmentCache) this._outboxAttachmentCache = new Map();
        this._outboxAttachmentCache.set(key, withData);
    }

    getPendingOutboxAttachments(clientId) {
        const key = String(clientId || '').trim();
        if (!key || !this._outboxAttachmentCache) return [];
        return this._outboxAttachmentCache.get(key) || [];
    }

    enqueuePendingOutbox(message) {
        if (!message || typeof message !== 'object') return;
        const pending = this.loadPendingOutbox();
        const key = String(message.clientId || '').trim();
        if (!key) return;
        if (pending.some(item => String(item.clientId || '').trim() === key)) return;
        this.trace(`enqueuePendingOutbox clientId=${key} sender=${String(message.sender || '').trim()} receiver=${String(message.receiver || '').trim()} server=${String(message.serverId || '').trim()} channel=${String(message.channelId || '').trim()} textBytes=${String(message.text || '').length} attachments=${this.normalizeAttachments(message.attachments).length}`);
        pending.push({
            clientId: key,
            sender: String(message.sender || '').trim(),
            receiver: String(message.receiver || '').trim(),
            serverId: message.serverId ? String(message.serverId).trim() : '',
            channelId: message.channelId ? String(message.channelId).trim() : '',
            text: String(message.text || ''),
            // Opaque structured payload (call records). Rides the normal outbox so it
            // inherits retries, dedupe by clientId and offline queueing.
            call: String(message.call || ''),
            // Same treatment for the reply quote — a retried send that dropped it
            // would arrive as an ordinary message with no visible connection to
            // what it was answering.
            reply: String(message.reply || ''),
            attachments: this.normalizeAttachments(message.attachments).map(att => ({
                id: att.id,
                name: att.name,
                mimeType: att.mimeType,
                kind: att.kind,
                size: att.size,
                archivePath: att.archivePath,
            })),
            timestamp: String(message.timestamp || new Date().toISOString()),
            attemptCount: Number(message.attemptCount || 0),
            lastAttemptAt: Number(message.lastAttemptAt || 0),
            nextRetryAt: Number(message.nextRetryAt || 0),
            // Persist the encryption key (and its version) the optimistic message was
            // queued with. Previously this field was silently dropped, so every retry
            // re-derived the *current* conversation key via pendingOutboxItemKey — after
            // a key rotation a retry could ship under a different key than its bubble.
            key: message.key ? String(message.key) : '',
            keyVersion: Number(message.keyVersion || 2),
            inFlight: !!message.inFlight,
        });
        this.savePendingOutbox(pending);
    }

    updatePendingOutboxItem(clientId, patch = {}) {
        const pendingId = String(clientId || '').trim();
        if (!pendingId) return false;
        const pending = this.loadPendingOutbox();
        const index = pending.findIndex(item => String(item?.clientId || '').trim() === pendingId);
        if (index < 0) return false;
        pending[index] = {
            ...pending[index],
            ...(patch && typeof patch === 'object' ? patch : {}),
        };
        this.savePendingOutbox(pending);
        return true;
    }

    dropPendingOutbox(clientId) {
        const pendingId = String(clientId || '').trim();
        if (!pendingId) return;
        this.trace(`dropPendingOutbox clientId=${pendingId}`);
        this.clearSendWatchdog(pendingId);
        if (this._outboxAttachmentCache) this._outboxAttachmentCache.delete(pendingId);
        const pending = this.loadPendingOutbox().filter(item => String(item.clientId || '').trim() !== pendingId);
        this.savePendingOutbox(pending);
    }

    clearSendWatchdog(clientId) {
        const pendingId = String(clientId || '').trim();
        if (!pendingId) return;
        const timer = this.sendWatchdogTimers.get(pendingId);
        if (timer) {
            clearTimeout(timer);
            this.sendWatchdogTimers.delete(pendingId);
        }
    }

    scheduleSendWatchdog(message, key) {
        const clientId = String(message?.clientId || '').trim();
        if (!clientId) return;
        this.clearSendWatchdog(clientId);
        const timer = setTimeout(() => {
            this.sendWatchdogTimers.delete(clientId);
            const found = this.findMessageById(clientId);
            if (!found || String(found.msg?.status || '').trim() !== 'sending') return;
            const pending = this.loadPendingOutbox();
            const existing = pending.find(item => String(item?.clientId || '').trim() === clientId);
            if (!existing) {
                this.trace(`sendWatchdog requeue clientId=${clientId}`);
                this.enqueuePendingOutbox({
                    ...message,
                    key: '',
                    nextRetryAt: 0,
                    attemptCount: (message.attemptCount || 0) + 1,
                    lastAttemptAt: 0,
                });
                this.scheduleFlushPendingOutbox(150);
                return;
            }
            this.updatePendingOutboxItem(clientId, {
                inFlight: false,
                nextRetryAt: Date.now(),
            });
            this.scheduleFlushPendingOutbox(150);
        }, 20000);
        this.sendWatchdogTimers.set(clientId, timer);
    }

    scheduleFlushPendingOutbox(delayMs = 150) {
        if (this.pendingOutboxFlushTimer) {
            clearTimeout(this.pendingOutboxFlushTimer);
        }
        this.pendingOutboxFlushTimer = setTimeout(() => {
            this.pendingOutboxFlushTimer = null;
            this.flushPendingOutbox();
        }, Math.max(0, Number(delayMs || 0)));
    }

    rehydratePendingOutbox() {
        const currentUser = String(this.myName() || '').trim();
        if (!currentUser) return;
        const pending = this.loadPendingOutbox().filter(item => String(item?.sender || '').trim() === currentUser);
        this.trace(`rehydratePendingOutbox currentUser=${currentUser} count=${pending.length} tokenSet=${!!this.S.session?.token} navMode=${this.S.navMode}`);
        let changed = false;

        for (const item of pending) {
            if (!item || typeof item !== 'object') continue;
            const clientId = String(item.clientId || '').trim();
            if (!clientId) continue;
            if (this.findMessageById(clientId)) continue;

            const serverId = String(item.serverId || '').trim();
            const channelId = String(item.channelId || '').trim();
            const isServers = !!(serverId && channelId);
            const conversationKey = isServers ? `${serverId}:${channelId}` : String(item.receiver || '').trim();
            const message = {
                id: clientId,
                sender: String(item.sender || currentUser).trim() || currentUser,
                receiver: String(item.receiver || '').trim(),
                text: String(item.text || ''),
                attachments: this.normalizeAttachments(item.attachments),
                timestamp: String(item.timestamp || new Date().toISOString()),
                status: 'sending',
                clientId,
                serverId: isServers ? serverId : null,
                channelId: isServers ? channelId : null,
            };

            if (isServers) {
                if (!this.S.serverChats[conversationKey]) this.S.serverChats[conversationKey] = [];
                this.S.serverChats[conversationKey].push(message);
            } else {
                this.ensureContact(message.receiver);
                this.initChat(message.receiver);
                this.S.chats[message.receiver].push(message);
            }
            changed = true;
        }

        if (changed) {
            if (this.S.navMode !== 'servers') {
                const currentKey = String(this.S.current || '').trim();
                const currentMsgs = currentKey ? (this.S.chats[currentKey] || []) : [];
                if (!currentKey || !currentMsgs.length) {
                    const preferredPeer = pending
                        .map(item => String(item?.receiver || '').trim())
                        .find(peer => peer && (this.S.chats[peer] || []).length > 0);
                    if (preferredPeer && preferredPeer !== this.S.current) {
                        this.switchChat(preferredPeer);
                    }
                }
            }
            this.scheduleRenderMessages();
            this.renderContacts();
            this.renderServerInterface();
        }
    }

    recoverOrphanSendingMessages() {
        const currentUser = String(this.myName() || '').trim();
        if (!currentUser || !this.S.session?.token) return;
        const maxAgeMs = 2 * 60 * 60 * 1000;
        const now = Date.now();
        const pendingIds = new Set(this.loadPendingOutbox().map(item => String(item?.clientId || '').trim()).filter(Boolean));
        let recovered = 0;

        const shouldRecover = (msg) => {
            const clientId = String(msg?.clientId || '').trim();
            if (!clientId || pendingIds.has(clientId)) return false;
            if (String(msg?.sender || '').trim() !== currentUser) return false;
            if (String(msg?.status || '').trim() !== 'sending') return false;
            const timestamp = Date.parse(String(msg?.timestamp || ''));
            if (!Number.isFinite(timestamp) || (now - timestamp) > maxAgeMs) return false;
            return true;
        };

        const recoverMessage = (msg, serverId = null, channelId = null) => {
            const receiver = String(msg?.receiver || '').trim();
            if (!receiver) return;
            const key = serverId && channelId
                ? this.ensureConversationCryptoKey({ serverId, channelId, reason: 'recoverOrphanSendingMessages' })
                : this.ensureConversationCryptoKey({ peer: receiver, reason: 'recoverOrphanSendingMessages' });
            this.cachePendingOutboxAttachments(msg?.clientId, msg?.attachments);
            this.enqueuePendingOutbox({
                ...msg,
                receiver,
                serverId: serverId || null,
                channelId: channelId || null,
                key,
                keyVersion: Number(msg?.keyVersion || 2),
                nextRetryAt: 0,
                attemptCount: 0,
                lastAttemptAt: 0,
            });
            this.scheduleSendWatchdog(msg, key);
            recovered += 1;
        };

        for (const msgs of Object.values(this.S.chats || {})) {
            for (const msg of Array.isArray(msgs) ? msgs : []) {
                if (shouldRecover(msg)) recoverMessage(msg);
            }
        }
        for (const [key, msgs] of Object.entries(this.S.serverChats || {})) {
            const [serverId, channelId] = String(key || '').split(':');
            if (!serverId || !channelId) continue;
            for (const msg of Array.isArray(msgs) ? msgs : []) {
                if (shouldRecover(msg)) recoverMessage(msg, serverId, channelId);
            }
        }

        if (recovered > 0) {
            this.trace(`recoverOrphanSendingMessages recovered=${recovered}`);
            this.addLogEntry({ type: 'WARN', msg: `Восстановлено зависших сообщений: ${recovered}`, ts: new Date().toLocaleTimeString() });
            this.scheduleFlushPendingOutbox(150);
        }
    }

    isPendingMessageAlreadyLoaded(item) {
        const clientId = String(item.clientId || '').trim();
        const attachmentsKey = this.normalizeAttachments(item.attachments).map(att => `${att.name}:${att.kind}:${att.size}`).join('|');
        const text = String(item.text || '');
        const sender = String(item.sender || '');
        const receiver = String(item.receiver || '');
        const serverId = String(item.serverId || '').trim();
        const channelId = String(item.channelId || '').trim();

        const matchesDelivered = (msg) => {
            if (String(msg.status || '').trim() !== 'sent') return false;
            if (msg.error) return false;
            if (clientId) {
                // Only the same clientId echoed back by the server proves delivery.
                // Content equality is not proof: two distinct messages with identical
                // text/attachments would wrongly drop the second one from the outbox,
                // leaving its bubble stuck in "sending" forever.
                return String(msg.clientId || msg.client_id || '').trim() === clientId;
            }
            const msgAttachments = this.normalizeAttachments(msg.attachments).map(att => `${att.name}:${att.kind}:${att.size}`).join('|');
            return String(msg.sender || '') === sender &&
                String(msg.receiver || '') === receiver &&
                String(msg.text || '') === text &&
                msgAttachments === attachmentsKey;
        };

        if (serverId && channelId) {
            const msgs = this.S.serverChats[`${serverId}:${channelId}`] || [];
            return msgs.some(matchesDelivered);
        }

        const peer = sender === this.myName() ? receiver : sender;
        return (this.S.chats[peer] || []).some(matchesDelivered);
    }

    flushPendingOutbox() {
        // Deliberately NOT gated on nativeSupports('sendMessage') any more. The browser/PWA
        // client has its own send path (browserSendMessage, WASM-packed .zali over fetch),
        // but this whole retry queue used to bail out on the first line for it — so a send
        // that failed in a browser tab was logged once and never retried, and the message
        // sat in the UI as permanently "sending". The per-item branch below picks the
        // right transport; everything else (backoff, attempt cap, attachment recovery,
        // stall detection) is transport-independent and now applies to both.
        if (!this.S.session?.token) return;
        const currentUser = String(this.myName() || '').trim();
        const now = Date.now();
        const pending = this.loadPendingOutbox();
        if (!pending.length) return;
        this.trace(`flushPendingOutbox currentUser=${currentUser} count=${pending.length} tokenSet=${!!this.S.session?.token}`);
        let sentAny = false;

        // Cap concurrent sends. Firing the whole backlog at once saturates the
        // connection pool to the host, which makes unrelated API calls (device trust,
        // contacts, key sync) queue behind it and time out at 12s. The rest of the
        // queue goes out on the next flush cycle.
        const MAX_CONCURRENT_SENDS = 3;
        let inFlightCount = pending.reduce((n, it) => n + (it && it.inFlight ? 1 : 0), 0);

        for (const item of pending) {
            if (!item || typeof item !== 'object') continue;
            if (currentUser && String(item.sender || '').trim() !== currentUser) continue;
            if (Number(item.nextRetryAt || 0) > now) continue;
            if (item.inFlight) {
                // A native send result can get lost (bridge reloaded mid-send, response
                // dropped). Without this, the item stays inFlight forever and the message
                // is only retried after a WS reconnect kick or app restart.
                const stalledMs = now - Number(item.lastAttemptAt || 0);
                if (!Number.isFinite(stalledMs) || stalledMs < 45000) continue;
                this.trace(`flushPendingOutbox stalled inFlight cleared clientId=${String(item.clientId || '').trim()} stalledMs=${Math.round(stalledMs)}`);
                item.inFlight = false;
                // Reclaim the concurrency slot this stalled item was holding. Without
                // this, when MAX_CONCURRENT_SENDS items are all stalled at once,
                // inFlightCount never drops below the cap, so the throttle check below
                // always breaks the loop — the queue deadlocks and nothing is retried.
                inFlightCount = Math.max(0, inFlightCount - 1);
            }
            if (inFlightCount >= MAX_CONCURRENT_SENDS) {
                this.trace(`flushPendingOutbox throttled inFlight=${inFlightCount} cap=${MAX_CONCURRENT_SENDS}`);
                this.scheduleFlushPendingOutbox(800);
                break;
            }

            const itemKey = this.pendingOutboxItemKey(item);
            if (!itemKey) {
                this.trace(`flushPendingOutbox missing key clientId=${String(item.clientId || '').trim()}`);
                item.nextRetryAt = now + 5000;
                this.savePendingOutbox(pending);
                continue;
            }

            const MAX_OUTBOX_ATTEMPTS = 50;
            if ((item.attemptCount || 0) >= MAX_OUTBOX_ATTEMPTS) {
                this.markMessageStatus(item.clientId, 'error');
                this.dropPendingOutbox(item.clientId);
                continue;
            }

            if (this.isPendingMessageAlreadyLoaded(item)) {
                this.dropPendingOutbox(item.clientId);
                continue;
            }

            const declaredAttachments = this.normalizeAttachments(item.attachments);
            let outAttachments = declaredAttachments.filter(att => att.dataUrl);
            if (declaredAttachments.length && !outAttachments.length) {
                outAttachments = this.getPendingOutboxAttachments(item.clientId).filter(att => att.dataUrl);
            }
            if (declaredAttachments.length && !outAttachments.length) {
                // The attachment bytes are gone (dataUrl is not persisted across
                // restarts). Sending now would deliver the message without its files —
                // or completely empty for attachment-only messages. Fail it visibly
                // instead of silently delivering wrong content.
                this.trace(`flushPendingOutbox attachments lost clientId=${String(item.clientId || '').trim()} declared=${declaredAttachments.length}`);
                this.markMessageStatus(item.clientId, 'error');
                this.dropPendingOutbox(item.clientId);
                this.addLogEntry({ type: 'ERROR', msg: 'Вложения сообщения утеряны после перезапуска, отправка отменена. Прикрепите файлы заново.', ts: new Date().toLocaleTimeString() });
                continue;
            }

            item.attemptCount = Number(item.attemptCount || 0) + 1;
            item.lastAttemptAt = now;
            item.nextRetryAt = now + Math.min(30000, Math.max(1500, 1000 * Math.min(item.attemptCount, 6)));
            item.inFlight = true;
            inFlightCount += 1;
            this.savePendingOutbox(pending);
            sentAny = true;

            // Browser/PWA has no native shell to hand the send to — pack and upload it
            // here, the same way sendInputMessage's browser branch does. The item stays
            // in the queue either way: on success the server's own-device echo comes back
            // over the WS and finalizePendingMessage() drops it by clientId, exactly like
            // the native path; on failure it just becomes the next retry.
            if (!this.nativeSupports('sendMessage')) {
                const pendingId = String(item.clientId || '').trim();
                const requeue = () => this.updatePendingOutboxItem(pendingId, {
                    inFlight: false,
                    nextRetryAt: Date.now() + 2000,
                });
                this.browserSendMessage({
                    text: item.text,
                    key: itemKey,
                    keyVersion: Number(item.keyVersion || 2),
                    sender: item.sender || this.myName(),
                    receiver: item.serverId && item.channelId ? item.channelId : item.receiver,
                    serverId: item.serverId || '',
                    channelId: item.channelId || '',
                    clientId: item.clientId,
                    attachments: outAttachments,
                    reply: String(item.reply || ''),
                }).then(ok => {
                    if (!ok) {
                        this.trace(`flushPendingOutbox browserSendMessage failed clientId=${pendingId}`);
                        requeue();
                    }
                }).catch(error => {
                    this.trace(`flushPendingOutbox browserSendMessage error clientId=${pendingId} error=${error?.message || error}`);
                    requeue();
                });
                continue;
            }

            const sentToNative = this.postNativeMessage({
                type: NativeMessageTypes.SEND_MESSAGE,
                text: item.text,
                recipient: item.serverId && item.channelId ? item.channelId : item.receiver,
                serverId: item.serverId || '',
                channelId: item.channelId || '',
                sender: item.sender || this.myName(),
                key: itemKey,
                keyVersion: Number(item.keyVersion || 2),
                clientId: item.clientId,
                call: String(item.call || ''),
                reply: String(item.reply || ''),
                attachments: outAttachments.map(att => ({
                    name: att.name,
                    mimeType: att.mimeType,
                    kind: att.kind,
                    size: att.size,
                    dataUrl: att.dataUrl,
                })),
            });
            if (!sentToNative) {
                this.trace(`flushPendingOutbox native bridge rejected clientId=${String(item.clientId || '').trim()}`);
                item.inFlight = false;
                inFlightCount -= 1;
                item.nextRetryAt = Date.now() + 2000;
                this.savePendingOutbox(pending);
            }
            this.trace(`flushPendingOutbox send clientId=${String(item.clientId || '').trim()} receiver=${String(item.receiver || '').trim()} server=${String(item.serverId || '').trim()} channel=${String(item.channelId || '').trim()} attempt=${item.attemptCount}`);
        }

        const nextDelay = this.pendingOutboxNextRetryDelay();
        if (nextDelay !== null && this.loadPendingOutbox().some(item => String(item?.sender || '').trim() === currentUser)) {
            this.scheduleFlushPendingOutbox(Math.max(150, sentAny ? Math.min(3000, nextDelay) : nextDelay));
        }
    }

    pendingOutboxItemKey(item) {
        const stored = String(item?.key || '').trim();
        if (stored) return stored;
        const serverId = String(item?.serverId || '').trim();
        const channelId = String(item?.channelId || '').trim();
        const receiver = String(item?.receiver || item?.recipient || '').trim();
        try {
            if (serverId && channelId) {
                return this.ensureConversationCryptoKey({ serverId, channelId, reason: 'pendingOutboxItemKey' });
            }
            if (receiver) {
                return this.ensureConversationCryptoKey({ peer: receiver, reason: 'pendingOutboxItemKey' });
            }
            return this._getKey();
        } catch (e) {
            return '';
        }
    }

    clearLastStoredSession() {
        try {
            localStorage.removeItem(this.lastAuthStorageKey());
        } catch (e) {
            // ignore storage failures
        }
    }
});


// --- MODULE: interface/network_config.js ---
// --- ZaliInterface: Сетевая конфигурация: API/WS адреса, ICE/TURN. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    loadStoredNavMode() {
        try {
            const raw = localStorage.getItem(this.navModeStorageKey());
            return raw === 'servers' ? 'servers' : 'dm';
        } catch (e) {
            return 'dm';
        }
    }

    saveStoredNavMode(mode) {
        try {
            localStorage.setItem(this.navModeStorageKey(), mode);
        } catch (e) {
            // ignore storage failures
        }
    }

    loadStoredActiveServer() {
        try {
            const raw = localStorage.getItem(this.activeServerStorageKey());
            return raw ? String(raw) : null;
        } catch (e) {
            return null;
        }
    }

    saveStoredActiveServer(serverId) {
        try {
            if (serverId) {
                localStorage.setItem(this.activeServerStorageKey(), serverId);
            } else {
                localStorage.removeItem(this.activeServerStorageKey());
            }
        } catch (e) {
            // ignore storage failures
        }
    }

    loadStoredActiveChannel() {
        try {
            const raw = localStorage.getItem(this.activeChannelStorageKey());
            return raw ? String(raw) : null;
        } catch (e) {
            return null;
        }
    }

    saveStoredActiveChannel(channelId) {
        try {
            if (channelId) {
                localStorage.setItem(this.activeChannelStorageKey(), channelId);
            } else {
                localStorage.removeItem(this.activeChannelStorageKey());
            }
        } catch (e) {
            // ignore storage failures
        }
    }

    loadStoredServerChats() {
        return {};
    }

    saveStoredServerChats() {
        // Server history now comes from the backend; keep this as a no-op
        // so local optimistic state doesn't get duplicated after restart.
    }

    loadStoredMutedChats() {
        try {
            const raw = localStorage.getItem(this.mutedChatsStorageKey());
            if (!raw) return {};
            const parsed = JSON.parse(raw);
            return parsed && typeof parsed === 'object' ? parsed : {};
        } catch (e) {
            return {};
        }
    }

    saveStoredMutedChats() {
        try {
            localStorage.setItem(this.mutedChatsStorageKey(), JSON.stringify(this.S.mutedChats || {}));
        } catch (e) {
            // ignore storage failures
        }
    }

    loadStoredNetworkConfig() {
        try {
            const raw = localStorage.getItem(this.networkConfigStorageKey());
            if (!raw) return {};
            const parsed = JSON.parse(raw);
            return parsed && typeof parsed === 'object' ? parsed : {};
        } catch (e) {
            return {};
        }
    }

    // Только "по-настоящему мёртвый" адрес — голый IP прод-сервера на :3000,
    // оставшийся от эпохи до nginx/TLS (сейчас прод только по HTTPS через
    // msgs.zalikus.org). localhost/127.0.0.1/[::1] здесь раньше тоже считались
    // "дефолтными" и на каждой загрузке конфига незаметно подменялись обратно
    // на прод — именно на эти адреса рассчитана normalizeLocalApiAddress()
    // ниже (сама дописывает :3000, канонизирует localhost -> 127.0.0.1), так
    // что кнопка «Сохранить» на экране входа не могла сохранить локальный
    // адрес НИКОГДА: значение переживало один цикл рендера и тут же
    // откатывалось на прод при следующем applyNetworkConfigToInputs()/
    // loadNetworkConfig(). Явно сохранённый через форму адрес теперь всегда
    // уважается — эвристика восстановления актуальна только для мёртвого
    // IP-адреса ниже.
    isDefaultableNetworkUrl(value) {
        const raw = String(value || '').trim().toLowerCase();
        if (!raw) return true;
        return (
            raw.startsWith('http://89.108.76.89:3000') ||
            raw.startsWith('https://89.108.76.89:3000')
        );
    }

    trimTrailingSlash(value) {
        return String(value || '').trim().replace(/\/+$/, '');
    }

    isPlaceholderNetworkUrl(value) {
        const raw = String(value || '').trim().toLowerCase();
        if (!raw) return false;
        return (
            raw.includes('chat.example.com') ||
            raw.includes('turn.example.com') ||
            raw.includes('example.com')
        );
    }

    normalizeLocalApiAddress(value) {
        const raw = this.trimTrailingSlash(value);
        if (!raw) return '';
        try {
            const parsed = new URL(raw);
            const host = parsed.hostname.toLowerCase();
            const isLocalHost = ['localhost', '127.0.0.1', '::1'].includes(host);
            if (isLocalHost && !parsed.port) {
                parsed.port = '3000';
            }
            if (host === 'localhost' || host === '::1') {
                parsed.hostname = '127.0.0.1';
            }
            return parsed.toString().replace(/\/$/, '');
        } catch (e) {
            if (/^https?:\/\/(localhost|127\.0\.0\.1|\[::1\])(?:[\/?#]|$)/i.test(raw) && !/:\d+(?:[\/?#]|$)/.test(raw)) {
                return raw
                    .replace(/^(https?:\/\/(?:localhost|127\.0\.0\.1|\[::1\]))(?=[:\/?#]|$)/i, '$1:3000')
                    .replace(/^https?:\/\/(?:localhost|\[::1\])(?=:3000(?:[\/?#]|$))/i, 'http://127.0.0.1');
            }
            if (/^https?:\/\/(?:localhost|\[::1\])(?=[:\/?#]|$)/i.test(raw)) {
                return raw.replace(
                    /^(https?:\/\/)(?:localhost|\[::1\])(?=[:\/?#]|$)/i,
                    '$1127.0.0.1'
                );
            }
            return raw;
        }
    }

    normalizeApiBaseUrl(value) {
        const normalized = this.normalizeLocalApiAddress(value);
        if (!normalized) return '';
        if (this.isPlaceholderNetworkUrl(normalized)) return '';
        return normalized;
    }

    normalizeWsBaseUrl(value) {
        const normalized = this.trimTrailingSlash(value);
        if (!normalized) return '';
        if (this.isPlaceholderNetworkUrl(normalized)) return '';
        return normalized;
    }

    saveStoredNetworkConfig(config) {
        try {
            localStorage.setItem(this.networkConfigStorageKey(), JSON.stringify(config || {}));
        } catch (e) {
            // ignore storage failures
        }
    }

    hasStoredNetworkConfig() {
        try {
            return !!localStorage.getItem(this.networkConfigStorageKey());
        } catch (e) {
            return false;
        }
    }

    defaultApiBaseUrl() {
        if (window.__ZALI_CONFIG?.apiBaseUrl) {
            return this.normalizeApiBaseUrl(window.__ZALI_CONFIG.apiBaseUrl);
        }
        return 'https://msgs.zalikus.org';
    }

    defaultWsBaseUrl() {
        if (window.__ZALI_CONFIG?.wsBaseUrl) {
            return this.normalizeWsBaseUrl(window.__ZALI_CONFIG.wsBaseUrl);
        }
        const api = this.defaultApiBaseUrl();
        if (api.startsWith('https://')) return api.replace(/^https:\/\//, 'wss://') + '/ws';
        if (api.startsWith('http://')) return api.replace(/^http:\/\//, 'ws://') + '/ws';
        return 'wss://msgs.zalikus.org/ws';
    }

    deriveWsBaseUrl(apiBaseUrl) {
        const api = this.normalizeApiBaseUrl(apiBaseUrl || '');
        if (api.startsWith('https://')) return api.replace(/^https:\/\//, 'wss://') + '/ws';
        if (api.startsWith('http://')) return api.replace(/^http:\/\//, 'ws://') + '/ws';
        return this.defaultWsBaseUrl();
    }

    defaultTurnUrls() {
        const fromConfig = window.__ZALI_CONFIG?.turn?.url;
        if (fromConfig) {
            const urls = Array.isArray(fromConfig) ? fromConfig : [fromConfig];
            return urls.map(item => String(item || '').trim()).filter(Boolean);
        }

        const stored = this.loadStoredNetworkConfig();
        const apiBase = this.normalizeApiBaseUrl(stored.apiBaseUrl || '') || this.defaultApiBaseUrl();
        let host = '127.0.0.1';
        try {
            host = new URL(apiBase).hostname || host;
        } catch (e) {}

        if (host === 'localhost' || host === '127.0.0.1' || host === '::1') {
            return [
                'turn:127.0.0.1:3478?transport=udp',
                'turn:127.0.0.1:3478?transport=tcp',
                'turn:localhost:3478?transport=udp',
                'turn:localhost:3478?transport=tcp',
            ];
        }

        const safeHost = host.includes(':') && !host.startsWith('[') ? `[${host}]` : host;
        return [
            `turn:${safeHost}:3478?transport=udp`,
            `turn:${safeHost}:3478?transport=tcp`,
            // 3478 is the first port a corporate or guest network blocks, and with
            // only 3478 offered there is no relay at all on such a network — the call
            // simply fails for anyone who needs one. 5349 is the registered TURN-over-
            // TLS port; 443 is the one that survives a firewall that allows nothing
            // but web traffic. A port with nothing listening costs a failed gathering
            // attempt, which onicecandidateerror now records by name, so adding them
            // is safe whether or not the deployment answers there.
            `turns:${safeHost}:5349?transport=tcp`,
            `turns:${safeHost}:443?transport=tcp`,
        ];
    }

    defaultIceServers() {
        const injected = window.__ZALI_CONFIG?.iceServers;
        if (Array.isArray(injected) && injected.length) {
            return injected;
        }
        const turnConfig = window.__ZALI_CONFIG?.turn;
        if (turnConfig && turnConfig.url) {
            const urls = Array.isArray(turnConfig.url) ? turnConfig.url : [turnConfig.url];
            const turnServer = {
                urls: urls.map(item => String(item || '').trim()).filter(Boolean),
            };
            if (turnServer.urls.length) {
                if (turnConfig.username) turnServer.username = String(turnConfig.username).trim();
                if (turnConfig.credential) turnServer.credential = String(turnConfig.credential).trim();
                if (turnConfig.relayOnly !== undefined) turnServer.relayOnly = !!turnConfig.relayOnly;
                const servers = [turnServer];
                if (!turnServer.relayOnly) {
                    servers.push(
                        { urls: 'stun:stun.l.google.com:19302' },
                        { urls: 'stun:stun1.l.google.com:19302' },
                    );
                }
                return servers;
            }
        }
        return [
            {
                urls: this.defaultTurnUrls(),
                username: 'zali',
                credential: 'turnpass',
            },
            { urls: 'stun:stun.l.google.com:19302' },
            { urls: 'stun:stun1.l.google.com:19302' },
        ];
    }

    defaultTurnPreset() {
        const turn = window.__ZALI_CONFIG?.turn || {};
        const defaultUrls = this.defaultTurnUrls().join(', ');
        return {
            url: String(turn.url || defaultUrls).trim(),
            username: String(turn.username || 'zali').trim(),
            credential: String(turn.credential || 'turnpass').trim(),
            relayOnly: turn.relayOnly !== undefined ? !!turn.relayOnly : false,
        };
    }

    normalizeIceServers(value) {
        const list = Array.isArray(value) ? value : [];
        return list.map(item => {
            if (typeof item === 'string') {
                return { urls: item.trim() };
            }
            if (item && typeof item === 'object') {
                const urls = Array.isArray(item.urls) ? item.urls : item.urls ? [item.urls] : [];
                const next = { ...item, urls: urls.map(url => String(url || '').trim()).filter(Boolean) };
                return next.urls.length ? next : null;
            }
            return null;
        }).filter(Boolean);
    }

    parseIceServersText(raw) {
        const text = String(raw || '').trim();
        if (!text) return [];
        const parsed = JSON.parse(text);
        if (!Array.isArray(parsed)) {
            throw new Error('ICE servers должен быть JSON-массивом');
        }
        return this.normalizeIceServers(parsed);
    }

    loadNetworkConfig() {
        const stored = this.loadStoredNetworkConfig();
        const storedApiBaseUrl = this.normalizeApiBaseUrl(stored.apiBaseUrl || '');
        const storedWsBaseUrl = this.normalizeWsBaseUrl(stored.wsBaseUrl || '');
        const useDefaultApi = this.isDefaultableNetworkUrl(storedApiBaseUrl);
        const apiBaseUrl = useDefaultApi ? this.defaultApiBaseUrl() : (storedApiBaseUrl || this.defaultApiBaseUrl());
        const wsBaseUrl = useDefaultApi
            ? this.defaultWsBaseUrl()
            : (storedWsBaseUrl || this.defaultWsBaseUrl());
        let iceServers = this.normalizeIceServers(stored.iceServers);
        if (!iceServers.length) {
            iceServers = this.normalizeIceServers(this.defaultIceServers());
        }
        return { apiBaseUrl, wsBaseUrl, iceServers };
    }

    getApiBaseUrl() {
        return this.loadNetworkConfig().apiBaseUrl;
    }

    getWsBaseUrl() {
        return this.loadNetworkConfig().wsBaseUrl;
    }

    getIceServers() {
        return this.loadNetworkConfig().iceServers;
    }

    getVoiceRtcConfig() {
        const config = this.loadNetworkConfig();
        // Short-lived credentials issued by the server (RFC 5766 REST scheme) when
        // the deployment has coturn in use-auth-secret mode, otherwise the static
        // pair below. The static pair is shipped inside every client, so it is a
        // relay anyone who has ever opened the bundle can use for as long as it
        // exists, and rotating it means rebuilding every client. Rotating creds fix
        // that — but only where the TURN server is configured for them, so the
        // static pair stays as the fallback rather than being removed.
        const rotating = this.voiceTurnCredentials();
        const defaultTurn = rotating || {
            urls: this.defaultTurnUrls(),
            username: 'zali',
            credential: 'turnpass',
        };
        const iceServers = this.normalizeIceServers([defaultTurn, ...config.iceServers]);
        const seenUrls = new Set();
        const uniqueServers = iceServers.map(server => {
            const urls = Array.isArray(server?.urls) ? server.urls : [server?.urls];
            const nextUrls = urls
                .map(url => String(url || '').trim())
                .filter(Boolean)
                .filter(url => {
                    const key = url.toLowerCase();
                    if (seenUrls.has(key)) return false;
                    seenUrls.add(key);
                    return true;
                });
            return nextUrls.length ? { ...server, urls: nextUrls } : null;
        }).filter(Boolean);
        return {
            iceServers: uniqueServers.map(server => {
                const { relayOnly, ...iceServer } = server || {};
                return iceServer;
            }),
            // 1, not 4. The pool is pre-gathered per RTCPeerConnection, and a mesh
            // call builds one connection per participant — so a pool of 4 in an
            // eight-person room asks the TURN server for dozens of allocations
            // nobody will use, all against a single credential. One pre-gathered set
            // still covers the latency the pool exists for.
            iceCandidatePoolSize: 1,
            iceTransportPolicy: 'all',
        };
    }

    // Cached in memory only, never persisted: these expire, and a stale credential
    // read from disk on next launch would be worse than no credential at all (it
    // fails 401 at the TURN server, which looks exactly like a broken relay).
    voiceTurnCredentials() {
        const creds = this._voiceTurnCredentials;
        if (!creds) return null;
        if (!creds.urls?.length || !creds.username || !creds.credential) return null;
        if (Number(creds.expiresAt || 0) <= Date.now()) return null;
        return { urls: creds.urls, username: creds.username, credential: creds.credential };
    }

    // Fire-and-forget from the call-setup paths. Deliberately NOT awaited anywhere:
    // getVoiceRtcConfig is synchronous (it is called from `new RTCPeerConnection`),
    // so making credentials a precondition would mean putting a network round trip
    // in front of every call — and failing the call when it times out. If the fetch
    // lands first the rotating credential is used; if it does not, the static pair
    // is, and the call proceeds either way.
    async refreshVoiceTurnCredentials({ force = false } = {}) {
        if (!this.S?.session?.token) return null;
        // window.ZaliApiRoutes may come from an older cached bundle that predates
        // this route; reading through it unguarded would throw inside call setup.
        const route = this.apiRoutes?.voice?.turnCredentials;
        if (!route) return null;
        const existing = this.voiceTurnCredentials();
        // Refresh once the credential is inside its last quarter, so a call starting
        // now cannot outlive it by much.
        if (!force && existing && Number(this._voiceTurnCredentials?.refreshAfter || 0) > Date.now()) {
            return existing;
        }
        if (this._voiceTurnFetchInFlight) return this._voiceTurnFetchInFlight;
        const pending = (async () => {
            try {
                const res = await this.apiFetch(route, { method: 'GET' });
                if (res.status === 404) {
                    // Route absent or disabled: this deployment has no rotating
                    // credentials configured. Not an error, and not worth retrying
                    // hard — the static pair works.
                    this._voiceTurnCredentials = null;
                    this.voiceTrace('turn-credentials-unavailable', { status: res.status });
                    return null;
                }
                if (!res.ok) throw new Error(`HTTP ${res.status}`);
                const data = await res.json().catch(() => null);
                const urls = this.normalizeIceServers([{ urls: data?.urls }])[0]?.urls || [];
                const username = String(data?.username || '').trim();
                const credential = String(data?.credential || '').trim();
                const ttl = Math.max(60, Number(data?.ttl || 0) || 3600);
                if (!urls.length || !username || !credential) {
                    throw new Error('incomplete turn credentials');
                }
                const expiresAt = Date.now() + ttl * 1000;
                this._voiceTurnCredentials = {
                    urls,
                    username,
                    credential,
                    expiresAt,
                    refreshAfter: Date.now() + Math.floor(ttl * 0.75) * 1000,
                };
                this.voiceDiag('turn-credentials-refreshed', { urls: urls.length, ttl });
                return this.voiceTurnCredentials();
            } catch (error) {
                this.voiceDiag('turn-credentials-failed', { error: error?.message || String(error) }, 'WARN');
                return null;
            } finally {
                this._voiceTurnFetchInFlight = null;
            }
        })();
        this._voiceTurnFetchInFlight = pending;
        return pending;
    }

    apiUrl(path = '') {
        const base = String(this.getApiBaseUrl() || '').trim().replace(/\/+$/, '');
        const nextPath = String(path || '').trim();
        if (!base) return nextPath;
        if (!nextPath) return base;
        return `${base}${nextPath.startsWith('/') ? nextPath : `/${nextPath}`}`;
    }

    setNetworkConfig(config = {}) {
        const next = {
            apiBaseUrl: this.normalizeApiBaseUrl(config.apiBaseUrl || ''),
            wsBaseUrl: this.normalizeWsBaseUrl(config.wsBaseUrl || ''),
            iceServers: this.normalizeIceServers(config.iceServers),
        };
        this.saveStoredNetworkConfig(next);
        this.applyNetworkConfigToInputs();
        this.syncNativeNetworkConfig({ force: true });
        this.connectBrowserVoiceSocket();
        this.addLogEntry({ type: 'SUCCESS', msg: 'Network configuration updated', ts: new Date().toLocaleTimeString() });
    }

    resetNetworkConfig() {
        try {
            localStorage.removeItem(this.networkConfigStorageKey());
        } catch (e) {}
        this.applyNetworkConfigToInputs();
        this.syncNativeNetworkConfig({ force: true });
        this.connectBrowserVoiceSocket();
        this.addLogEntry({ type: 'WARN', msg: 'Network configuration reset to defaults', ts: new Date().toLocaleTimeString() });
    }

    applyNetworkConfigToInputs() {
        const config = this.loadNetworkConfig();
        const apiInput = document.getElementById('inputApiBaseUrl');
        const wsInput = document.getElementById('inputWsBaseUrl');
        const iceInput = document.getElementById('inputIceServers');
        const turnUrlInput = document.getElementById('inputTurnUrl');
        const turnUsernameInput = document.getElementById('inputTurnUsername');
        const turnCredentialInput = document.getElementById('inputTurnCredential');
        const turnRelayOnlyInput = document.getElementById('inputTurnRelayOnly');
        if (apiInput) apiInput.value = config.apiBaseUrl;
        if (wsInput) wsInput.value = config.wsBaseUrl;
        if (iceInput) iceInput.value = JSON.stringify(config.iceServers, null, 2);
        const turn = this.defaultTurnPreset();
        if (turnUrlInput) turnUrlInput.value = turn.url;
        if (turnUsernameInput) turnUsernameInput.value = turn.username;
        if (turnCredentialInput) turnCredentialInput.value = turn.credential;
        if (turnRelayOnlyInput) turnRelayOnlyInput.checked = turn.relayOnly;
        const authApiInput = document.getElementById('authApiBaseUrl');
        const authNote = document.getElementById('authNetworkNote');
        if (authApiInput && document.activeElement !== authApiInput && authApiInput.dataset.dirty !== '1') {
            authApiInput.value = config.apiBaseUrl;
        }
        if (authNote) {
            authNote.textContent = `Текущий API: ${config.apiBaseUrl || 'не задан'}`;
        }
    }

    syncAuthNetworkInput({ force = false } = {}) {
        const authApiInput = document.getElementById('authApiBaseUrl');
        const authNote = document.getElementById('authNetworkNote');
        if (!authApiInput) return;
        const config = this.loadNetworkConfig();
        const isTyping = document.activeElement === authApiInput;
        const isDirty = authApiInput.dataset.dirty === '1';
        if (force || (!isTyping && !isDirty)) {
            authApiInput.value = config.apiBaseUrl;
        }
        if (authNote) {
            authNote.textContent = `Текущий API: ${config.apiBaseUrl || 'не задан'}`;
        }
    }

    buildTurnIceServerFromInputs() {
        const turnUrlInput = document.getElementById('inputTurnUrl');
        const turnUsernameInput = document.getElementById('inputTurnUsername');
        const turnCredentialInput = document.getElementById('inputTurnCredential');
        const turnRelayOnlyInput = document.getElementById('inputTurnRelayOnly');
        const urls = String(turnUrlInput?.value || '').trim();
        if (!urls) {
            throw new Error('Укажите TURN URL');
        }
        const urlList = urls.split(',').map(item => item.trim()).filter(Boolean);
        if (!urlList.length) {
            throw new Error('TURN URL не должен быть пустым');
        }
        const entry = {
            urls: urlList.length === 1 ? urlList[0] : urlList,
        };
        const username = String(turnUsernameInput?.value || '').trim();
        const credential = String(turnCredentialInput?.value || '').trim();
        if (username) entry.username = username;
        if (credential) entry.credential = credential;
        if (turnRelayOnlyInput) entry.relayOnly = !!turnRelayOnlyInput.checked;
        return entry;
    }

    appendTurnPresetToIceServers(baseIceServers = null) {
        const iceInput = document.getElementById('inputIceServers');
        const current = Array.isArray(baseIceServers)
            ? this.normalizeIceServers(baseIceServers)
            : this.normalizeIceServers(this.loadNetworkConfig().iceServers);
        const turnEntry = this.buildTurnIceServerFromInputs();
        const next = [...current.filter(server => {
            const urls = Array.isArray(server.urls) ? server.urls : [server.urls];
            const turnUrls = Array.isArray(turnEntry.urls) ? turnEntry.urls : [turnEntry.urls];
            return !urls.some(url => turnUrls.includes(url));
        }), turnEntry];
        if (iceInput) {
            iceInput.value = JSON.stringify(next, null, 2);
        }
        return next;
    }

    syncNativeNetworkConfig({ force = false } = {}) {
        if (!this.nativeSupports('networkConfig')) return;
        const injected = window.__ZALI_CONFIG || {};
        const hasInjectedNetworkConfig = !!(injected.apiBaseUrl || injected.wsBaseUrl || (Array.isArray(injected.iceServers) && injected.iceServers.length));
        if (!force && !this.hasStoredNetworkConfig() && !hasInjectedNetworkConfig) return;
        const config = this.loadNetworkConfig();
        try {
            this.postNativeMessage({
                type: NativeMessageTypes.NETWORK_CONFIG,
                apiBaseUrl: config.apiBaseUrl,
                wsBaseUrl: config.wsBaseUrl,
                iceServers: config.iceServers,
            });
        } catch (error) {
            this.addLogEntry({
                type: 'WARN',
                msg: `Не удалось синхронизировать сеть с native app: ${error?.message || error}`,
                ts: new Date().toLocaleTimeString(),
            });
        }
    }
});


// --- MODULE: interface/servers_model.js ---
// --- ZaliInterface: Модель серверов и ролей, работа с цветом. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    getDefaultServers() {
        return [];
    }

    defaultServerChannels(serverId) {
        const sid = String(serverId || '').trim();
        return [
            { id: `${sid}-general`, name: 'general', topic: 'Общий чат', kind: 'text', position: 0 },
            { id: `${sid}-voice`, name: 'voice', topic: 'Голосовой канал', kind: 'voice', position: 1 },
        ];
    }

    ensureServerChannels(server = {}) {
        const next = { ...server };
        const channels = Array.isArray(next.channels) ? next.channels.filter(Boolean).map(channel => ({ ...channel })) : [];
        if (!channels.length && next.id) {
            next.channels = this.defaultServerChannels(next.id);
            return next;
        }
        next.channels = channels.map((channel, index) => ({
            ...channel,
            kind: String(channel.kind || 'text').trim().toLowerCase() || 'text',
            position: Number.isFinite(Number(channel.position)) ? Number(channel.position) : index,
        })).sort((a, b) => Number(a.position || 0) - Number(b.position || 0));
        return next;
    }

    ensureServersState() {
        this.S.servers = Array.isArray(this.S.servers)
            ? this.S.servers.map(server => this.ensureServerChannels(server))
            : [];
        const stored = this.loadStoredActiveServer();
        if (stored && this.S.servers.some(s => s.id === stored)) {
            this.S.activeServer = stored;
        } else if (!this.S.servers.some(s => s.id === this.S.activeServer)) {
            this.S.activeServer = null;
            this.S.activeChannel = null;
        }
    }

    updateSidebarModeLabel() {
        const label = document.querySelector('.nav-label');
        if (label) {
            label.textContent = this.S.navMode === 'servers' ? 'Сервера' : 'Диалоги';
        }
    }

    updateNavModeButtons() {
        const dmBtn = document.getElementById('modeDmBtn');
        const serversBtn = document.getElementById('modeServersBtn');
        const isServers = this.S.navMode === 'servers';
        if (dmBtn) {
            dmBtn.classList.toggle('active', !isServers);
            dmBtn.setAttribute('aria-pressed', String(!isServers));
        }
        if (serversBtn) {
            serversBtn.classList.toggle('active', isServers);
            serversBtn.setAttribute('aria-pressed', String(isServers));
        }
        document.body?.setAttribute('data-nav-mode', this.S.navMode);
        const viewChat = document.getElementById('viewChat');
        if (viewChat) viewChat.classList.toggle('server-mode', isServers);
        this.updateSidebarModeLabel();
        this.renderHubSegmentNav();
    }

    normalizeServers(servers) {
        return Array.isArray(servers) ? servers.map(server => ({
            ...server,
            channels: Array.isArray(server.channels) && server.channels.length ? server.channels.map(channel => ({ ...channel })) : [],
            myRole: server.myRole || server.my_role || null,
            memberCount: Number(server.memberCount || server.member_count || 0) || 0,
            joinLink: server.joinLink || server.join_link || '',
        })).map(server => this.ensureServerChannels(server)).filter(Boolean) : [];
    }

    normalizeMemberRole(role) {
        const value = String(role || '').trim().toLowerCase();
        if (value === 'owner') return 'owner';
        if (value === 'admin') return 'admin';
        return 'member';
    }

    roleLabel(role) {
        switch (this.normalizeMemberRole(role)) {
            case 'owner': return 'Владелец';
            case 'admin': return 'Админ';
            default: return 'Участник';
        }
    }

    serverRoleLabel(roleId) {
        const role = String(roleId || '').trim();
        if (!role) return 'Участник';
        if (role === 'owner') return 'Владелец';
        if (role === 'admin') return 'Админ';
        if (role === 'member') return 'Участник';
        const found = (this.S.serverModal.roles || []).find(item => String(item.roleId || '') === role);
        return found?.name || role;
    }

    serverRoleList() {
        return Array.isArray(this.S.serverModal.roles) ? this.S.serverModal.roles : [];
    }

    draftServerRoleList() {
        return Array.isArray(this.S.serverModal.draftRoles) ? this.S.serverModal.draftRoles : [];
    }

    serverRolePermissionDefs() {
        return [
            { key: 'can_view', label: 'Чтение каналов', hint: 'Видеть список и историю сообщений', group: 'Доступ', defaultCreate: true },
            { key: 'can_send', label: 'Отправка сообщений', hint: 'Писать в текстовые каналы', group: 'Доступ', defaultCreate: true },
            { key: 'can_react', label: 'Реакции', hint: 'Ставить реакции на сообщения', group: 'Доступ', defaultCreate: true },
            { key: 'can_attach', label: 'Файлы', hint: 'Прикреплять изображения и файлы', group: 'Доступ', defaultCreate: true },
            { key: 'can_embed', label: 'Ссылки и медиа', hint: 'Встраивать превью ссылок', group: 'Доступ', defaultCreate: true },
            { key: 'can_voice', label: 'Голосовые каналы', hint: 'Входить и говорить в voice', group: 'Доступ', defaultCreate: true },
            { key: 'can_manage', label: 'Управление сервером', hint: 'Общие админские действия', group: 'Управление', defaultCreate: false },
            { key: 'can_manage_channels', label: 'Каналы', hint: 'Создавать и менять каналы', group: 'Управление', defaultCreate: false },
            { key: 'can_manage_roles', label: 'Роли', hint: 'Создавать и менять роли', group: 'Управление', defaultCreate: false },
            { key: 'can_invite', label: 'Приглашения', hint: 'Генерировать инвайты', group: 'Управление', defaultCreate: true },
            { key: 'can_pin', label: 'Закреплять', hint: 'Закреплять важные сообщения', group: 'Управление', defaultCreate: false },
            { key: 'can_mention', label: '@everyone', hint: 'Упоминать всех участников', group: 'Управление', defaultCreate: false },
            { key: 'can_kick', label: 'Исключать', hint: 'Кикать участников из сервера', group: 'Управление', defaultCreate: false },
            { key: 'can_ban', label: 'Бан', hint: 'Блокировать участников', group: 'Управление', defaultCreate: false },
        ];
    }

    serverRolePermissionValue(role, key) {
        if (!role) return false;
        if (Object.prototype.hasOwnProperty.call(role, key)) return !!role[key];
        const camel = key.replace(/_([a-z])/g, (_, letter) => letter.toUpperCase());
        if (Object.prototype.hasOwnProperty.call(role, camel)) return !!role[camel];
        return false;
    }

    serverModalColorPickerState(key) {
        return !!this.S.serverModal?.colorPickers?.[key];
    }

    setServerModalColorPickerState(key, open) {
        const next = {
            ...(this.S.serverModal.colorPickers || {}),
            [key]: !!open,
        };
        this.setServerModalState({ colorPickers: next });
    }

    toggleServerModalColorPicker(key) {
        const next = !this.serverModalColorPickerState(key);
        this.setServerModalColorPickerState(key, next);
        this.renderServerModal();
    }

    serverRolePermissionsHtml(role, keyPrefix = '', attrName = 'data-role-perm') {
        const defs = this.serverRolePermissionDefs();
        const sections = defs.reduce((acc, def) => {
            if (!acc[def.group]) acc[def.group] = [];
            acc[def.group].push(def);
            return acc;
        }, {});
        return Object.entries(sections).map(([groupName, items]) => {
            const rows = items.map(def => {
                const key = def.key;
                const checked = this.serverRolePermissionValue(role, key) ? 'checked' : '';
                return `<label class="server-perm-row server-perm-row--stacked">
                    <span>
                        <strong>${this.esc(def.label)}</strong>
                        <small>${this.esc(def.hint)}</small>
                    </span>
                    <input type="checkbox" ${attrName}="${this.esc(key)}" ${checked}>
                </label>`;
            }).join('');
            return `<div class="server-perm-group">
                <div class="server-perm-group-title">${this.esc(groupName)}</div>
                <div class="server-perm-grid server-perm-grid--dense">${rows}</div>
            </div>`;
        }).join('');
    }

    serverRolePermissionsCount(role) {
        return this.serverRolePermissionDefs().reduce((total, def) => total + Number(!!this.serverRolePermissionValue(role, def.key)), 0);
    }

    serverRoleCreateDefaults() {
        const defaults = {};
        this.serverRolePermissionDefs().forEach(def => {
            defaults[def.key] = !!def.defaultCreate;
        });
        return defaults;
    }

    applyServerRoleCreateDefaults() {
        const defaults = this.serverRoleCreateDefaults();
        this.serverRolePermissionDefs().forEach(def => {
            const el = document.querySelector(`[data-server-role-perm="${CSS.escape(def.key)}"]`);
            if (el) el.checked = !!defaults[def.key];
        });
    }

    syncDraftServerRolesFromDom() {
        if (this.S.serverModal.mode !== 'create') return this.draftServerRoleList();
        const cards = Array.from(document.querySelectorAll('[data-draft-role-card]'));
        const roles = cards.map(card => {
            const draftId = String(card.getAttribute('data-draft-role-card') || '').trim();
            const permissions = {};
            this.serverRolePermissionDefs().forEach(def => {
                permissions[def.key] = !!card.querySelector(`[data-draft-role-perm="${CSS.escape(def.key)}"]`)?.checked;
            });
            return {
                draftId,
                collapsed: String(card.getAttribute('data-draft-role-collapsed') || '1') !== '0',
                name: String(card.querySelector('[data-draft-role-name]')?.value || '').trim(),
                color: this.normalizeColorValue(card.querySelector('[data-draft-role-color]')?.value || '#cbff00'),
                ...permissions,
            };
        }).filter(role => role.draftId);
        this.setServerModalState({ draftRoles: roles });
        return roles;
    }

    serverRoleOptionsHtml(selected = 'member') {
        const roles = [...this.serverRoleList(), ...this.draftServerRoleList()];
        const options = [
            { roleId: 'member', name: 'Участник' },
            { roleId: 'admin', name: 'Админ' },
            ...roles.filter(role => role.roleId && role.roleId !== 'member' && role.roleId !== 'admin' && role.roleId !== 'owner'),
        ];
        return options.map(role => {
            const roleId = String(role.roleId || '').trim();
            const label = this.esc(role.name || this.serverRoleLabel(roleId));
            const isSelected = roleId === String(selected || '').trim() ? 'selected' : '';
            return `<option value="${this.esc(roleId)}" ${isSelected}>${label}</option>`;
        }).join('');
    }

    normalizeColorValue(value) {
        const raw = String(value || '').trim();
        if (/^#[0-9a-fA-F]{6}$/.test(raw)) return raw.toLowerCase();
        return '#cbff00';
    }

    hexToRgb(hex) {
        const value = this.normalizeColorValue(hex).slice(1);
        const num = Number.parseInt(value, 16);
        return {
            r: (num >> 16) & 255,
            g: (num >> 8) & 255,
            b: num & 255,
        };
    }

    rgbToHex(r, g, b) {
        const toHex = (n) => Number(n || 0).toString(16).padStart(2, '0');
        return `#${toHex(Math.max(0, Math.min(255, Math.round(r))))}${toHex(Math.max(0, Math.min(255, Math.round(g))))}${toHex(Math.max(0, Math.min(255, Math.round(b))))}`;
    }

    rgbToHsl(r, g, b) {
        const rn = (r || 0) / 255;
        const gn = (g || 0) / 255;
        const bn = (b || 0) / 255;
        const max = Math.max(rn, gn, bn);
        const min = Math.min(rn, gn, bn);
        const delta = max - min;
        let h = 0;
        let s = 0;
        const l = (max + min) / 2;
        if (delta !== 0) {
            s = delta / (1 - Math.abs(2 * l - 1));
            switch (max) {
                case rn:
                    h = 60 * (((gn - bn) / delta) % 6);
                    break;
                case gn:
                    h = 60 * (((bn - rn) / delta) + 2);
                    break;
                default:
                    h = 60 * (((rn - gn) / delta) + 4);
                    break;
            }
        }
        return {
            h: (h + 360) % 360,
            s: s * 100,
            l: l * 100,
        };
    }

    hslToRgb(h, s, l) {
        const hue = ((h % 360) + 360) % 360;
        const sat = Math.max(0, Math.min(100, Number(s) || 0)) / 100;
        const lig = Math.max(0, Math.min(100, Number(l) || 0)) / 100;
        const c = (1 - Math.abs(2 * lig - 1)) * sat;
        const hp = hue / 60;
        const x = c * (1 - Math.abs((hp % 2) - 1));
        let r1 = 0, g1 = 0, b1 = 0;
        if (hp >= 0 && hp < 1) [r1, g1, b1] = [c, x, 0];
        else if (hp < 2) [r1, g1, b1] = [x, c, 0];
        else if (hp < 3) [r1, g1, b1] = [0, c, x];
        else if (hp < 4) [r1, g1, b1] = [0, x, c];
        else if (hp < 5) [r1, g1, b1] = [x, 0, c];
        else [r1, g1, b1] = [c, 0, x];
        const m = lig - c / 2;
        return {
            r: Math.round((r1 + m) * 255),
            g: Math.round((g1 + m) * 255),
            b: Math.round((b1 + m) * 255),
        };
    }

    hueToHex(hue) {
        const rgb = this.hslToRgb(hue, 100, 50);
        return this.rgbToHex(rgb.r, rgb.g, rgb.b);
    }

    bindColorWheel({ wheelId, hiddenId, hexId, initialValue = '#cbff00' }) {
        const wheel = document.getElementById(wheelId);
        const hidden = document.getElementById(hiddenId);
        const hexInput = document.getElementById(hexId);
        if (!wheel || this.colorWheelBindings.has(wheelId)) return;
        this.colorWheelBindings.add(wheelId);
        const updatePreview = (value) => {
            const normalized = this.normalizeColorValue(value);
            const picker = wheel.closest('.color-picker');
            const preview = picker?.querySelector('.color-picker-preview');
            if (preview) preview.style.background = normalized;
        };

        const setFromPoint = (clientX, clientY) => {
            const rect = wheel.getBoundingClientRect();
            if (!rect.width || !rect.height) return;
            const dx = clientX - rect.left - rect.width / 2;
            const dy = clientY - rect.top - rect.height / 2;
            const angle = Math.atan2(dy, dx) * 180 / Math.PI + 90;
            const nextValue = this.hueToHex(angle);
            this.applyColorWheelValue({ wheel, hidden, hexInput, value: nextValue });
            updatePreview(nextValue);
        };

        const onPointerDown = (e) => {
            e.preventDefault();
            try { wheel.setPointerCapture(e.pointerId); } catch (_) {}
            setFromPoint(e.clientX, e.clientY);
        };
        const onPointerMove = (e) => {
            if ((e.buttons || 0) === 0) return;
            setFromPoint(e.clientX, e.clientY);
        };
        const onClick = (e) => {
            if (typeof e.clientX !== 'number' || typeof e.clientY !== 'number') return;
            setFromPoint(e.clientX, e.clientY);
        };
        const onHexInput = () => {
            const nextValue = hexInput?.value || hidden?.value || initialValue;
            this.applyColorWheelValue({ wheel, hidden, hexInput, value: nextValue });
            updatePreview(nextValue);
        };

        wheel.addEventListener('pointerdown', onPointerDown);
        wheel.addEventListener('pointermove', onPointerMove);
        wheel.addEventListener('mousedown', onPointerDown);
        wheel.addEventListener('click', onClick);
        hexInput?.addEventListener('input', onHexInput);
        hidden?.addEventListener('input', () => {
            this.applyColorWheelValue({ wheel, hidden, hexInput, value: hidden.value });
            updatePreview(hidden.value);
        });
    }

    applyColorWheelValue({ wheel, hidden, hexInput, value }) {
        if (!wheel) return;
        const normalized = this.normalizeColorValue(value);
        const { h } = this.rgbToHsl(...Object.values(this.hexToRgb(normalized)));
        const rect = wheel.getBoundingClientRect();
        const radius = Math.max(20, Math.min(rect.width, rect.height) * 0.36);
        const angle = ((h - 90) * Math.PI) / 180;
        const x = (rect.width / 2) + Math.cos(angle) * radius;
        const y = (rect.height / 2) + Math.sin(angle) * radius;
        wheel.style.setProperty('--thumb-x', `${x}px`);
        wheel.style.setProperty('--thumb-y', `${y}px`);
        wheel.style.setProperty('--wheel-color', normalized);
        if (hidden && hidden.value !== normalized) hidden.value = normalized;
        if (hexInput && hexInput.value.toLowerCase() !== normalized) hexInput.value = normalized;
    }
});


// --- MODULE: interface/server_modal.js ---
// --- ZaliInterface: Модалка настроек сервера: роли, каналы, участники, инвайты. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    canManageServer(server = null) {
        const current = server || this.currentServer();
        const role = this.normalizeMemberRole(current?.myRole || current?.my_role || '');
        return role === 'owner' || role === 'admin';
    }

    openServerOverlay() {
        const overlay = document.getElementById('serverOverlay');
        if (overlay) {
            overlay.hidden = false;
            requestAnimationFrame(() => overlay.classList.add('visible'));
        }
    }

    closeServerOverlay() {
        const overlay = document.getElementById('serverOverlay');
        if (overlay) {
            overlay.classList.remove('visible');
            setTimeout(() => {
                overlay.hidden = true;
            }, 180);
        }
    }

    setServerModalState(partial = {}) {
        this.S.serverModal = {
            ...this.S.serverModal,
            ...partial,
        };
    }

    serverModalSectionsForMode(mode = this.S.serverModal.mode) {
        if (mode === 'discover') return ['discover'];
        if (mode === 'edit') return ['overview', 'channels', 'roles', 'members'];
        return ['overview', 'channels', 'roles', 'members'];
    }

    serverModalDefaultSection(mode = this.S.serverModal.mode) {
        return mode === 'discover' ? 'discover' : 'overview';
    }

    serverModalActiveSection(mode = this.S.serverModal.mode) {
        const allowed = this.serverModalSectionsForMode(mode);
        const current = String(this.S.serverModal.activeSection || '').trim() || this.serverModalDefaultSection(mode);
        return allowed.includes(current) ? current : this.serverModalDefaultSection(mode);
    }

    setServerModalSection(section) {
        const next = String(section || '').trim();
        if (!next) return;
        const allowed = this.serverModalSectionsForMode();
        if (!allowed.includes(next)) return;
        if (this.S.serverModal.activeSection === next) return;
        this.setServerModalState({ activeSection: next });
        this.renderServerModal();
    }

    renderServerModalMembers() {
        const list = document.getElementById('serverMembersList');
        const count = document.getElementById('serverMembersCount');
        const server = this.currentServer();
        const members = Array.isArray(this.S.serverModal.members) ? this.S.serverModal.members : [];
        const canManage = this.canManageServer(server);
        if (count) count.textContent = String(members.length || 0);
        if (!list) return;
        if (this.S.serverModal.loading && members.length === 0) {
            list.innerHTML = `<div class="empty-state">
                <div class="empty-ttl">Загрузка участников</div>
                <div class="empty-sub">Подождите секунду</div>
            </div>`;
            return;
        }
        if (this.S.serverModal.mode !== 'edit') {
            list.innerHTML = `<div class="empty-state">
                <div class="empty-ttl">После создания</div>
                <div class="empty-sub">Здесь появятся участники и роли</div>
            </div>`;
            return;
        }

        if (members.length === 0) {
            list.innerHTML = `<div class="empty-state">
                <div class="empty-ttl">Нет участников</div>
                <div class="empty-sub">Добавьте первых участников сервера</div>
            </div>`;
            return;
        }

        list.innerHTML = members.map(member => {
            const role = this.normalizeMemberRole(member.role);
            const isOwner = role === 'owner';
            const joined = member.joinedAt ? this.fmtDate(member.joinedAt) || this.fmtTime(member.joinedAt) : '';
            const select = `
                <select class="settings-input server-member-role" data-member-role="${this.esc(member.username)}" ${isOwner ? 'disabled' : ''}>
                    ${isOwner ? '<option value="owner" selected>Владелец</option>' : this.serverRoleOptionsHtml(role)}
                </select>
            `;
            return `<div class="server-member-row ${isOwner ? 'owner' : ''}">
                <div class="server-member-info">
                    <div class="server-member-name">${this.esc(member.username)}</div>
                    <div class="server-member-meta">${this.esc(this.serverRoleLabel(role))}${joined ? ` · ${this.esc(joined)}` : ''}</div>
                </div>
                ${select}
                <button class="server-member-remove" type="button" data-member-remove="${this.esc(member.username)}" ${isOwner || !canManage ? 'disabled' : ''} title="Удалить">×</button>
            </div>`;
        }).join('');
    }

    renderPublicServersModal() {
        const list = document.getElementById('serverDiscoverList');
        const count = document.getElementById('serverDiscoverCount');
        const refreshBtn = document.getElementById('serverDiscoverRefreshBtn');
        const servers = this.renderFilteredPublicServers();
        if (count) count.textContent = String(servers.length || 0);
        if (refreshBtn) refreshBtn.disabled = !!this.S.serverModal.loading;
        if (!list) return;
        if (this.S.serverModal.loading && servers.length === 0) {
            list.innerHTML = `<div class="empty-state">
                <div class="empty-ttl">Поиск серверов</div>
                <div class="empty-sub">Секунду, подбираем публичные сообщества</div>
            </div>`;
            return;
        }
        if (servers.length === 0) {
            list.innerHTML = `<div class="empty-state">
                <div class="empty-ttl">Публичных серверов нет</div>
                <div class="empty-sub">Пока что нечего открывать из меню</div>
            </div>`;
            return;
        }

        list.innerHTML = servers.map(server => {
            const memberCount = Number(server.memberCount || server.member_count || 0) || 0;
            const channelCount = Array.isArray(server.channels) ? server.channels.length : 0;
            const role = this.normalizeMemberRole(server.myRole || server.my_role || '');
            const alreadyJoined = role === 'owner' || role === 'admin' || role === 'member';
            const joinTarget = server.joinLink || server.join_link || server.id;
            const actionLabel = alreadyJoined ? 'Открыть' : 'Войти';
            return `<div class="server-discover-row">
                <button class="server-item server-discover-item" type="button" data-public-server-id="${this.esc(server.id)}" title="${this.esc(server.name)}">
                    ${this.renderServerAvatarHTML(server)}
                    <div class="server-meta">
                        <div class="server-name">${this.esc(server.name)}</div>
                        <div class="server-prev">${this.esc(server.description || 'Публичный сервер')}${channelCount ? ` · ${channelCount} каналов` : ''}${memberCount ? ` · ${memberCount} участников` : ''}</div>
                    </div>
                </button>
                <div class="server-discover-actions">
                    <button class="btn-flat" type="button" data-public-server-open="${this.esc(server.id)}">${actionLabel}</button>
                    <button class="btn-flat" type="button" data-public-server-join="${this.esc(joinTarget)}">${alreadyJoined ? 'Перейти' : 'Вступить'}</button>
                </div>
            </div>`;
        }).join('');
    }

    renderServerModal() {
        const server = this.currentServer();
        const mode = this.S.serverModal.mode;
        const isEdit = mode === 'edit';
        const isDiscover = mode === 'discover';
        const activeSection = this.serverModalActiveSection(mode);
        const createDraft = !isEdit && !isDiscover ? this.syncServerCreateDraftFromDom() : null;
        const createDraftView = !isEdit && !isDiscover ? (createDraft || this.serverCreateDraft()) : null;
        const grid = document.querySelector('.server-modal-grid');
        const nav = document.getElementById('serverModalNav');
        const sidebarTitle = document.getElementById('serverModalSidebarTitle');
        const sidebarHint = document.getElementById('serverModalSidebarHint');
        const basicsCard = document.getElementById('serverBasicsCard');
        const channelsCard = document.getElementById('serverChannelsCard');
        const membersCard = document.getElementById('serverMembersCard');
        const discoverCard = document.getElementById('serverDiscoverCard');
        const overviewPanel = document.getElementById('serverOverviewPanel');
        const channelsPanel = document.getElementById('serverChannelsPanel');
        const rolesPanel = document.getElementById('serverRolesPanel');
        const membersPanel = document.getElementById('serverMembersPanel');
        const discoverPanel = document.getElementById('serverDiscoverPanel');
        const title = document.getElementById('serverModalTitle');
        const hint = document.getElementById('serverModalHint');
        const kicker = document.getElementById('serverModalKicker');
        const modeNote = document.getElementById('serverModalModeNote');
        const saveBtn = document.getElementById('serverSaveBtn');
        const deleteBtn = document.getElementById('serverDeleteBtn');
        const serverModalCancel = document.getElementById('serverModalCancel');
        const nameInput = document.getElementById('serverNameInput');
        const descInput = document.getElementById('serverDescriptionInput');
        const iconInput = document.getElementById('serverIconInput');
        const colorInput = document.getElementById('serverColorInput');
        const publicInput = document.getElementById('serverPublicInput');
        const serverMembersList = document.getElementById('serverMembersList');
        const serverRolesCard = document.getElementById('serverRolesCard');
        const serverJoinLinkInput = document.getElementById('serverJoinLinkInput');
        const serverJoinLinkGenerateBtn = document.getElementById('serverJoinLinkGenerateBtn');
        const serverJoinLinkCopyBtn = document.getElementById('serverJoinLinkCopyBtn');
        const serverChannelCreate = document.querySelector('[data-server-channel-create]');
        const serverChannelCreateBody = document.querySelector('[data-server-channel-create-body]');
        const serverChannelCreateToggleBtn = document.getElementById('serverChannelCreateBtn');
        const serverChannelCreateSubmitBtn = document.getElementById('serverChannelCreateSubmitBtn');
        const serverChannelNameInput = document.getElementById('serverChannelNameInput');
        const serverChannelTopicInput = document.getElementById('serverChannelTopicInput');
        const serverChannelKindInput = document.getElementById('serverChannelKindInput');
        const serverAvatarUploadBtn = document.getElementById('serverAvatarUploadBtn');
        const serverAvatarRemoveBtn = document.getElementById('serverAvatarRemoveBtn');
        const serverBannerUploadBtn = document.getElementById('serverBannerUploadBtn');
        const serverBannerRemoveBtn = document.getElementById('serverBannerRemoveBtn');
        const serverRoleNameInput = document.getElementById('serverRoleNameInput');
        const serverRoleColorInput = document.getElementById('serverRoleColorInput');
        const serverRolePermView = document.getElementById('serverRolePermView');
        const serverRolePermSend = document.getElementById('serverRolePermSend');
        const serverRolePermManage = document.getElementById('serverRolePermManage');
        const serverRoleCreate = document.querySelector('[data-server-role-create]');
        const serverRoleCreateBody = document.querySelector('[data-server-role-create-body]');
        const serverRoleCreateToggleBtn = document.getElementById('serverRoleCreateBtn');
        const serverRoleCreateSubmitBtn = document.getElementById('serverRoleCreateSubmitBtn');
        const discoverQuery = document.getElementById('serverDiscoverQuery');
        const errorBox = document.getElementById('serverModalError');
        const canManage = this.canManageServer(server);
        const current = isEdit && this.S.serverModal.serverId
            ? (this.S.servers || []).find(s => s.id === this.S.serverModal.serverId)
            : null;

        this.S.serverModal.activeSection = activeSection;

        if (grid) grid.classList.toggle('is-discover', isDiscover);
        if (basicsCard) basicsCard.hidden = activeSection !== 'overview';
        if (channelsCard) channelsCard.hidden = activeSection !== 'channels';
        if (membersCard) membersCard.hidden = activeSection !== 'members';
        if (serverRolesCard) serverRolesCard.hidden = activeSection !== 'roles';
        if (discoverCard) discoverCard.hidden = activeSection !== 'discover';
        if (overviewPanel) overviewPanel.hidden = activeSection !== 'overview';
        if (channelsPanel) channelsPanel.hidden = activeSection !== 'channels';
        if (rolesPanel) rolesPanel.hidden = activeSection !== 'roles';
        if (membersPanel) membersPanel.hidden = activeSection !== 'members';
        if (discoverPanel) discoverPanel.hidden = activeSection !== 'discover';
        if (nav) {
            nav.querySelectorAll('[data-server-modal-section]').forEach(btn => {
                const section = btn.getAttribute('data-server-modal-section');
                const visible = isDiscover ? section === 'discover' : section !== 'discover';
                btn.hidden = !visible;
                btn.classList.toggle('active', visible && section === activeSection);
            });
        }
        if (sidebarTitle) sidebarTitle.textContent = isEdit ? (current?.name || server?.name || 'Настройки сервера') : isDiscover ? 'Поиск серверов' : 'Создание сервера';
        if (sidebarHint) sidebarHint.textContent = isEdit
            ? (activeSection === 'overview'
                ? 'Основные параметры сервера и внешний вид.'
                : activeSection === 'channels'
                    ? 'Создавайте, редактируйте и удаляйте каналы.'
                    : activeSection === 'roles'
                        ? 'Настройка ролей и прав доступа.'
                        : 'Управление участниками и их ролями.')
            : isDiscover
                ? 'Подберите сервер и войдите в него из каталога.'
                : activeSection === 'roles'
                    ? 'Соберите роли до создания сервера.'
                    : 'Имя, оформление и базовая конфигурация.';
        if (title) title.textContent = isEdit ? 'Настройки сервера' : isDiscover ? 'Публичные серверы' : 'Создать сервер';
        if (hint) hint.textContent = isEdit
            ? (activeSection === 'overview'
                ? 'Переименуйте сервер, измените оформление и код входа.'
                : activeSection === 'channels'
                    ? 'Управляйте каналами сервера.'
                : activeSection === 'roles'
                    ? 'Управляйте ролями и правами доступа.'
                    : 'Добавляйте участников и назначайте им роли.')
            : isDiscover
                ? 'Выберите публичный сервер и войдите в него через меню без автодобавления в список.'
            : activeSection === 'roles'
                ? 'Настройте роли и доступ перед созданием.'
                : 'Настройте имя, оформление и доступ перед созданием.';
        if (kicker) kicker.textContent = isEdit ? 'Settings' : isDiscover ? 'Discover' : 'Creation';
        if (modeNote) modeNote.textContent = isEdit ? 'edit' : isDiscover ? 'browse' : 'create';
        if (saveBtn) {
            saveBtn.hidden = isDiscover;
            saveBtn.textContent = this.S.serverModal.saving ? 'Сохранение...' : (isEdit ? 'Сохранить' : 'Создать');
            saveBtn.disabled = !!this.S.serverModal.saving || !!this.S.serverModal.loading;
        }
        if (deleteBtn) deleteBtn.hidden = !isEdit || !canManage || this.normalizeMemberRole(current?.myRole || current?.my_role || '') !== 'owner';
        if (serverModalCancel) serverModalCancel.textContent = isDiscover ? 'Закрыть' : 'Отмена';
        if (nameInput) nameInput.value = isEdit ? (current?.name || '') : (createDraftView?.name || '');
        if (descInput) descInput.value = isEdit ? (current?.description || '') : (createDraftView?.description || '');
        if (iconInput) iconInput.value = isEdit ? (current?.icon || '') : (createDraftView?.icon || '');
        const normalizedColor = this.normalizeColorValue(isEdit ? (current?.color || '#cbff00') : (createDraftView?.color || '#cbff00'));
        if (colorInput) colorInput.value = normalizedColor;
        const colorHexInput = document.getElementById('serverColorHexInput');
        if (colorHexInput) colorHexInput.value = normalizedColor;
        const serverColorPickerPreview = document.querySelector('[data-color-picker-key="server-basics"] .color-picker-preview');
        if (serverColorPickerPreview) serverColorPickerPreview.style.background = normalizedColor;
        this.applyColorWheelValue({
            wheel: document.getElementById('serverColorWheel'),
            hidden: colorInput,
            hexInput: colorHexInput,
            value: normalizedColor,
        });
        if (publicInput) publicInput.checked = isEdit ? !!current?.is_public : !!(createDraftView?.isPublic ?? true);
        if (discoverQuery && !discoverQuery.value) {
            discoverQuery.value = '';
        }
        const editLocked = !isEdit;
        const linkLocked = !!this.S.serverModal.saving || !!this.S.serverModal.loading;
        if (serverAvatarUploadBtn) serverAvatarUploadBtn.disabled = editLocked;
        if (serverAvatarRemoveBtn) serverAvatarRemoveBtn.disabled = editLocked;
        if (serverBannerUploadBtn) serverBannerUploadBtn.disabled = editLocked;
        if (serverBannerRemoveBtn) serverBannerRemoveBtn.disabled = editLocked;
        if (serverJoinLinkInput) serverJoinLinkInput.disabled = linkLocked;
        if (serverJoinLinkGenerateBtn) serverJoinLinkGenerateBtn.disabled = linkLocked;
        if (serverJoinLinkCopyBtn) serverJoinLinkCopyBtn.disabled = linkLocked;
        if (serverRoleNameInput) serverRoleNameInput.disabled = false;
        if (serverRoleColorInput) serverRoleColorInput.disabled = false;
        const serverRoleColorHexInput = document.getElementById('serverRoleColorHexInput');
        if (serverRoleColorHexInput) serverRoleColorHexInput.disabled = false;
        if (serverRolePermView) serverRolePermView.disabled = false;
        if (serverRolePermSend) serverRolePermSend.disabled = false;
        if (serverRolePermManage) serverRolePermManage.disabled = false;
        const roleCreateOpen = !!this.S.serverModal.roleCreateOpen;
        if (serverRoleCreate) serverRoleCreate.classList.toggle('is-collapsed', !roleCreateOpen);
        if (serverRoleCreateBody) serverRoleCreateBody.hidden = !roleCreateOpen;
        if (serverRoleCreateToggleBtn) serverRoleCreateToggleBtn.textContent = roleCreateOpen ? 'Свернуть' : 'Новая роль';
        if (serverRoleCreateSubmitBtn) serverRoleCreateSubmitBtn.disabled = !!this.S.serverModal.saving || !!this.S.serverModal.loading || !roleCreateOpen;
        if (serverAvatarUploadBtn) serverAvatarUploadBtn.title = isEdit ? 'Загрузить аватар' : 'Создать сервер сначала';
        if (serverAvatarRemoveBtn) serverAvatarRemoveBtn.title = isEdit ? 'Удалить аватар' : 'Создать сервер сначала';
        if (serverBannerUploadBtn) serverBannerUploadBtn.title = isEdit ? 'Загрузить баннер' : 'Создать сервер сначала';
        if (serverBannerRemoveBtn) serverBannerRemoveBtn.title = isEdit ? 'Удалить баннер' : 'Создать сервер сначала';
        if (errorBox) errorBox.textContent = this.S.serverModal.error || '';
        if (serverMembersList) {
            serverMembersList.classList.toggle('is-loading', !!this.S.serverModal.loading);
        }
        const roleSelect = document.getElementById('serverMemberRole');
        if (roleSelect) {
            roleSelect.innerHTML = this.serverRoleOptionsHtml(roleSelect.value || 'member');
        }
        if (serverRoleColorInput) {
            const roleColor = this.normalizeColorValue(serverRoleColorInput.value || '#cbff00');
            serverRoleColorInput.value = roleColor;
            if (serverRoleColorHexInput) serverRoleColorHexInput.value = roleColor;
            const createPicker = document.querySelector('[data-color-picker-key="server-role-create"]');
            const createPickerOpen = this.serverModalColorPickerState('server-role-create');
            const createPickerPreview = createPicker?.querySelector('.color-picker-preview');
            if (createPickerPreview) createPickerPreview.style.background = roleColor;
            if (createPicker) createPicker.classList.toggle('is-collapsed', !createPickerOpen);
            const createPickerToggle = createPicker?.querySelector('[data-color-picker-toggle="server-role-create"]');
            if (createPickerToggle) createPickerToggle.textContent = createPickerOpen ? 'Свернуть' : 'Развернуть';
            if (activeSection === 'roles') {
                this.applyColorWheelValue({
                    wheel: document.getElementById('serverRoleColorWheel'),
                    hidden: serverRoleColorInput,
                    hexInput: serverRoleColorHexInput,
                    value: roleColor,
                });
            }
        }
        const channelCreateOpen = !!this.S.serverModal.channelCreateOpen;
        if (serverChannelCreate) serverChannelCreate.classList.toggle('is-collapsed', !channelCreateOpen);
        if (serverChannelCreateBody) serverChannelCreateBody.hidden = !channelCreateOpen;
        if (serverChannelCreateToggleBtn) serverChannelCreateToggleBtn.textContent = channelCreateOpen ? 'Свернуть' : 'Новый канал';
        if (serverChannelCreateSubmitBtn) serverChannelCreateSubmitBtn.disabled = !!this.S.serverModal.saving || !!this.S.serverModal.loading || !channelCreateOpen;
        if (serverChannelNameInput) serverChannelNameInput.disabled = !!this.S.serverModal.saving || !!this.S.serverModal.loading;
        if (serverChannelTopicInput) serverChannelTopicInput.disabled = !!this.S.serverModal.saving || !!this.S.serverModal.loading;
        if (serverChannelKindInput) serverChannelKindInput.disabled = !!this.S.serverModal.saving || !!this.S.serverModal.loading;
        const serverColorPicker = document.querySelector('[data-color-picker-key="server-basics"]');
        if (serverColorPicker) {
            const open = this.serverModalColorPickerState('server-basics');
            serverColorPicker.classList.toggle('is-collapsed', !open);
            const toggle = serverColorPicker.querySelector('[data-color-picker-toggle="server-basics"]');
            if (toggle) toggle.textContent = open ? 'Свернуть' : 'Развернуть';
        }
        if (activeSection === 'overview') {
            this.renderServerJoinLink();
        } else if (activeSection === 'channels') {
            this.renderServerChannels();
        } else if (activeSection === 'roles') {
            this.renderServerRoles();
        } else if (activeSection === 'members') {
            this.renderServerModalMembers();
        } else if (activeSection === 'discover') {
            this.renderPublicServersModal();
        }
        if (isEdit && (this.S.serverModal.serverId || server?.id)) {
            this.syncServerAssetPreview(this.S.serverModal.serverId || server?.id || '');
        } else {
            this.resetServerAssetPreview();
        }
    }

    async loadServerMembers(serverId) {
        const sid = String(serverId || '').trim();
        if (!sid) return [];
        const res = await this.apiFetch(this.apiRoutes.servers.members(sid));
        if (!res.ok) {
            throw new Error(await res.text() || 'Не удалось загрузить участников сервера');
        }
        const data = await res.json();
        const members = Array.isArray(data) ? data : (Array.isArray(data?.members) ? data.members : []);
        return members.map(member => ({
            ...member,
            role: this.normalizeMemberRole(member.role),
        }));
    }

    async loadServerRoles(serverId) {
        const sid = String(serverId || '').trim();
        if (!sid) return [];
        const res = await this.apiFetch(this.apiRoutes.servers.roles(sid));
        if (!res.ok) {
            throw new Error(await res.text() || 'Не удалось загрузить роли сервера');
        }
        const data = await res.json();
        const roles = Array.isArray(data?.roles) ? data.roles : [];
        return roles.map(role => ({
            ...role,
            roleId: String(role.roleId || role.role_id || '').trim(),
            name: String(role.name || '').trim(),
            color: String(role.color || '#cbff00').trim(),
            canView: !!(role.canView ?? role.can_view),
            canSend: !!(role.canSend ?? role.can_send),
            canManage: !!(role.canManage ?? role.can_manage),
            canManageChannels: !!(role.canManageChannels ?? role.can_manage_channels),
            canManageRoles: !!(role.canManageRoles ?? role.can_manage_roles),
            canInvite: !!(role.canInvite ?? role.can_invite),
            canAttach: !!(role.canAttach ?? role.can_attach),
            canEmbed: !!(role.canEmbed ?? role.can_embed),
            canReact: !!(role.canReact ?? role.can_react),
            canPin: !!(role.canPin ?? role.can_pin),
            canMention: !!(role.canMention ?? role.can_mention),
            canVoice: !!(role.canVoice ?? role.can_voice),
            canKick: !!(role.canKick ?? role.can_kick),
            canBan: !!(role.canBan ?? role.can_ban),
            position: Number(role.position || 0) || 0,
        }));
    }

    async loadServerChannels(serverId) {
        const sid = String(serverId || '').trim();
        if (!sid) return [];
        const res = await this.apiFetch(this.apiRoutes.servers.channels(sid));
        if (!res.ok) {
            throw new Error(await res.text() || 'Не удалось загрузить каналы сервера');
        }
        const data = await res.json();
        const channels = Array.isArray(data) ? data : (Array.isArray(data?.channels) ? data.channels : []);
        return this.normalizeServerChannels(channels);
    }

    normalizeServerChannels(channels) {
        return (Array.isArray(channels) ? channels : [])
            .filter(Boolean)
            .map((channel, index) => ({
                ...channel,
                id: String(channel.id || '').trim(),
                name: String(channel.name || '').trim(),
                topic: String(channel.topic || '').trim(),
                kind: this.normalizeChannelKind(channel.kind),
                position: Number.isFinite(Number(channel.position)) ? Number(channel.position) : index,
            }))
            .sort((a, b) => Number(a.position || 0) - Number(b.position || 0) || String(a.name || '').localeCompare(String(b.name || '')));
    }

    normalizeChannelKind(kind) {
        return String(kind || 'text').trim().toLowerCase() === 'voice' ? 'voice' : 'text';
    }

    channelKindLabel(kind) {
        return this.normalizeChannelKind(kind) === 'voice' ? 'Голосовой' : 'Текстовый';
    }

    renderServerJoinLink() {
        const input = document.getElementById('serverJoinLinkInput');
        if (!input) return;
        const link = this.S.serverModal.mode === 'create'
            ? (this.serverCreateDraft()?.joinLink || this.S.serverModal.joinLink || '')
            : (this.S.serverModal.joinLink || '');
        input.value = link;
    }

    serverCreateDraftDefaults() {
        return {
            name: '',
            description: '',
            icon: '',
            color: '#cbff00',
            joinLink: '',
            isPublic: true,
        };
    }

    serverCreateDraft() {
        return {
            ...this.serverCreateDraftDefaults(),
            ...(this.S.serverModal.createDraft || {}),
        };
    }

    syncServerCreateDraftFromDom() {
        if (this.S.serverModal.mode !== 'create') {
            return this.serverCreateDraft();
        }
        const current = this.serverCreateDraft();
        const nameInput = document.getElementById('serverNameInput');
        const descInput = document.getElementById('serverDescriptionInput');
        const iconInput = document.getElementById('serverIconInput');
        const colorInput = document.getElementById('serverColorInput');
        const joinLinkInput = document.getElementById('serverJoinLinkInput');
        const publicInput = document.getElementById('serverPublicInput');
        const next = {
            ...current,
            name: String(nameInput?.value ?? current.name ?? ''),
            description: String(descInput?.value ?? current.description ?? ''),
            icon: String(iconInput?.value ?? current.icon ?? ''),
            color: this.normalizeColorValue(colorInput?.value || current.color || '#cbff00'),
            joinLink: String(joinLinkInput?.value ?? current.joinLink ?? ''),
            isPublic: publicInput ? !!publicInput.checked : !!current.isPublic,
        };
        this.setServerModalState({
            createDraft: next,
            joinLink: next.joinLink,
        });
        return next;
    }

    renderServerRoles() {
        const list = document.getElementById('serverRolesList');
        const count = document.getElementById('serverRolesCount');
        const isEdit = this.S.serverModal.mode === 'edit';
        const roles = isEdit ? this.serverRoleList() : this.draftServerRoleList();
        if (count) count.textContent = String(roles.length || 0);
        if (!list) return;
        if (roles.length === 0) {
            list.innerHTML = `<div class="empty-state">
                <div class="empty-ttl">${isEdit ? 'Ролей нет' : 'Черновики ролей'}</div>
                <div class="empty-sub">${isEdit ? 'Создайте первую роль' : 'Добавьте роли перед созданием сервера'}</div>
            </div>`;
            return;
        }
        const renderColorPicker = ({ pickerKey, wheelId, colorId, hexId, currentColor, isRoleCard = false }) => {
            const open = this.serverModalColorPickerState(pickerKey);
            return `<div class="color-picker color-picker--compact color-picker--collapsible ${open ? '' : 'is-collapsed'}" data-color-picker-key="${this.esc(pickerKey)}">
                <div class="color-picker-head">
                    <div class="color-picker-summary">
                        <span class="color-picker-preview" style="background:${this.safeCssColor(currentColor) || 'transparent'}"></span>
                        <div class="color-picker-copy">
                            <div class="color-picker-title">RGB</div>
                            <div class="color-picker-sub">${open ? 'Колесо открыто' : 'Свернуто по умолчанию'}</div>
                        </div>
                    </div>
                    <button class="btn-flat color-picker-toggle" type="button" data-color-picker-toggle="${this.esc(pickerKey)}">${open ? 'Свернуть' : 'Развернуть'}</button>
                </div>
                <div class="color-picker-body">
                    <div class="color-wheel ${isRoleCard ? 'color-wheel--tiny' : 'color-wheel--small'}" id="${this.esc(wheelId)}" tabindex="0" aria-label="Цвет роли">
                        <div class="color-wheel-thumb"></div>
                        <div class="color-wheel-center">${isRoleCard ? '' : 'RGB'}</div>
                    </div>
                    <div class="color-picker-side">
                        <input type="hidden" ${isRoleCard ? `data-role-color="${this.esc(pickerKey)}"` : `data-draft-role-color="${this.esc(pickerKey)}"`} id="${this.esc(colorId)}" value="${this.esc(currentColor)}">
                        <input class="settings-input color-hex-input" type="text" id="${this.esc(hexId)}" maxlength="7" value="${this.esc(currentColor)}" aria-label="HEX цвет роли">
                    </div>
                </div>
            </div>`;
        };
        list.innerHTML = roles.map(role => {
            if (!isEdit) {
                const draftId = String(role.draftId || '').trim();
                const safeDraftId = draftId.replace(/[^a-z0-9_-]/gi, '_');
                const wheelId = `draftRoleColorWheel-${safeDraftId}`;
                const colorId = `draftRoleColorInput-${safeDraftId}`;
                const hexId = `draftRoleColorHexInput-${safeDraftId}`;
                const currentColor = this.normalizeColorValue(role.color || '#cbff00');
                const collapsed = role.collapsed !== false;
                const draftPermCount = this.serverRolePermissionsCount(role);
                return `<div class="server-role-card draft-role ${collapsed ? 'collapsed' : ''}" data-draft-role-card="${this.esc(draftId)}" data-draft-role-collapsed="${collapsed ? '1' : '0'}">
                    <div class="server-role-head server-role-head--draft">
                        <span class="server-role-chip" style="background:${this.safeCssColor(currentColor) || 'transparent'}"></span>
                        <div>
                            <div class="server-role-name">${this.esc(role.name || 'Новая роль')}</div>
                            <div class="server-role-meta">черновик</div>
                        </div>
                        <button class="btn-flat server-role-toggle" type="button" data-draft-role-toggle="${this.esc(draftId)}">${collapsed ? 'Развернуть' : 'Свернуть'}</button>
                    </div>
                    <div class="server-role-body">
                        <div class="server-role-meta server-role-summary">Права: ${draftPermCount}/${this.serverRolePermissionDefs().length}</div>
                        <div class="server-role-controls">
                        <input class="settings-input" data-draft-role-name="${this.esc(draftId)}" value="${this.esc(role.name || '')}" placeholder="Название роли">
                        ${renderColorPicker({ pickerKey: draftId, wheelId, colorId, hexId, currentColor, isRoleCard: false })}
                        ${this.serverRolePermissionsHtml(role, draftId, 'data-draft-role-perm')}
                        <div class="server-role-actions">
                            <button class="btn-flat" type="button" data-draft-role-delete="${this.esc(draftId)}">Удалить</button>
                        </div>
                        </div>
                    </div>
                </div>`;
            }
            const locked = role.roleId === 'member' || role.roleId === 'admin';
            const safeRoleId = String(role.roleId || '').replace(/[^a-z0-9_-]/gi, '_');
            const wheelId = `roleColorWheel-${safeRoleId}`;
            const colorId = `roleColorInput-${safeRoleId}`;
            const hexId = `roleColorHexInput-${safeRoleId}`;
            const currentColor = this.normalizeColorValue(role.color || '#cbff00');
            const rolePermCount = this.serverRolePermissionsCount(role);
            const colorPickerKey = role.roleId || safeRoleId;
            const options = `
                <div class="server-role-controls">
                    <input class="settings-input" data-role-name="${this.esc(role.roleId)}" value="${this.esc(role.name || '')}">
                    ${renderColorPicker({ pickerKey: colorPickerKey, wheelId, colorId, hexId, currentColor, isRoleCard: true })}
                    <div class="server-role-actions">
                        <button class="btn-flat" type="button" data-role-save="${this.esc(role.roleId)}">Сохранить</button>
                        <button class="btn-flat" type="button" data-role-delete="${this.esc(role.roleId)}" ${locked ? 'disabled' : ''}>Удалить</button>
                    </div>
                </div>
            `;
            return `<div class="server-role-card ${locked ? 'owner-role' : ''}" data-role-card="${this.esc(role.roleId)}">
                <div class="server-role-head">
                    <span class="server-role-chip" style="background:${this.safeCssColor(role.color) || '#cbff00'}"></span>
                    <div>
                        <div class="server-role-name">${this.esc(role.name || role.roleId)}</div>
                        <div class="server-role-meta">${this.esc(role.roleId)}</div>
                    </div>
                    <span class="server-role-meta">${locked ? 'системная' : 'роль'}</span>
                </div>
                <div class="server-role-meta server-role-summary">Права: ${rolePermCount}/${this.serverRolePermissionDefs().length}</div>
                ${this.serverRolePermissionsHtml(role, role.roleId, 'data-role-perm')}
                ${options}
            </div>`;
        }).join('');
        requestAnimationFrame(() => {
            roles.forEach(role => {
                if (!isEdit) {
                    const draftId = String(role.draftId || '').trim();
                const safeDraftId = draftId.replace(/[^a-z0-9_-]/gi, '_');
                this.colorWheelBindings.delete(`draftRoleColorWheel-${safeDraftId}`);
                this.bindColorWheel({
                    wheelId: `draftRoleColorWheel-${safeDraftId}`,
                    hiddenId: `draftRoleColorInput-${safeDraftId}`,
                    hexId: `draftRoleColorHexInput-${safeDraftId}`,
                    initialValue: this.normalizeColorValue(role.color || '#cbff00'),
                });
                return;
            }
            const safeRoleId = String(role.roleId || '').replace(/[^a-z0-9_-]/gi, '_');
            const wheelId = `roleColorWheel-${safeRoleId}`;
            const colorId = `roleColorInput-${safeRoleId}`;
            const hexId = `roleColorHexInput-${safeRoleId}`;
            this.colorWheelBindings.delete(wheelId);
            this.bindColorWheel({
                wheelId,
                hiddenId: colorId,
                hexId,
                initialValue: this.normalizeColorValue(role.color || '#cbff00'),
            });
            });
        });
    }

    renderServerChannels() {
        const list = document.getElementById('serverChannelsList');
        const count = document.getElementById('serverChannelsCount');
        const isEdit = this.S.serverModal.mode === 'edit';
        const channels = isEdit ? this.normalizeServerChannels(this.S.serverModal.channels || []) : [];
        if (count) count.textContent = String(channels.length || 0);
        if (!list) return;
        if (this.S.serverModal.loading && channels.length === 0) {
            list.innerHTML = `<div class="empty-state">
                <div class="empty-ttl">Загрузка каналов</div>
                <div class="empty-sub">Подождите секунду</div>
            </div>`;
            return;
        }
        if (!isEdit) {
            list.innerHTML = '';
            return;
        }
        if (channels.length === 0) {
            list.innerHTML = `<div class="empty-state">
                <div class="empty-ttl">Каналов нет</div>
                <div class="empty-sub">Создайте первый канал</div>
            </div>`;
            return;
        }
        list.innerHTML = channels.map(channel => {
            const safeId = String(channel.id || '').replace(/[^a-z0-9_-]/gi, '_');
            const kind = this.normalizeChannelKind(channel.kind);
            return `<div class="server-channel-card" data-channel-card="${this.esc(channel.id)}">
                <div class="server-channel-head">
                    <span class="server-channel-chip ${kind}">${this.channelKindIcon(kind, 'server-channel-chip-icon')}</span>
                    <div class="server-channel-copy">
                        <input class="settings-input" data-channel-name="${this.esc(channel.id)}" value="${this.esc(channel.name || '')}" placeholder="Название канала">
                        <div class="server-channel-meta">ID: ${this.esc(channel.id || safeId)} · ${this.esc(this.channelKindLabel(kind))}</div>
                    </div>
                    <select class="settings-input server-channel-kind-select" data-channel-kind="${this.esc(channel.id)}">
                        <option value="text"${kind === 'text' ? ' selected' : ''}>Текстовый</option>
                        <option value="voice"${kind === 'voice' ? ' selected' : ''}>Голосовой</option>
                    </select>
                    <div class="server-channel-controls">
                        <button class="btn-flat" type="button" data-channel-save="${this.esc(channel.id)}">Сохранить</button>
                        <button class="btn-flat" type="button" data-channel-delete="${this.esc(channel.id)}">Удалить</button>
                    </div>
                </div>
                <div class="server-channel-body">
                    <input class="settings-input" data-channel-topic="${this.esc(channel.id)}" value="${this.esc(channel.topic || '')}" placeholder="Тема или описание">
                    <label class="server-channel-position">
                        <span class="server-channel-position-label">Позиция</span>
                        <input class="settings-input" data-channel-position="${this.esc(channel.id)}" type="number" min="0" step="1" value="${this.esc(String(Number.isFinite(Number(channel.position)) ? Number(channel.position) : 0))}" placeholder="0">
                    </label>
                </div>
            </div>`;
        }).join('');
    }

    async openServerModal(mode = 'create', serverId = null) {
        const nextMode = mode === 'edit' ? 'edit' : 'create';
        const sid = nextMode === 'edit' ? String(serverId || this.S.activeServer || '').trim() : null;
        const server = sid ? (this.S.servers || []).find(item => item.id === sid) : null;
        if (nextMode === 'edit' && (!server || !this.canManageServer(server))) {
            return;
        }
        const selectedChannelId = nextMode === 'edit'
            ? ((this.S.activeServer === sid ? this.S.activeChannel : null) || server?.channels?.[0]?.id || null)
            : null;

        this.setServerModalState({
            mode: nextMode,
            serverId: sid,
            activeSection: nextMode === 'edit' ? 'overview' : 'overview',
            colorPickers: {},
            roleCreateOpen: false,
            channelCreateOpen: false,
            members: nextMode === 'edit' ? (server?.members || []) : [],
            roles: [],
            channels: nextMode === 'edit' ? (server?.channels || []) : [],
            draftRoles: [],
            createDraft: nextMode === 'edit' ? null : this.serverCreateDraftDefaults(),
            joinLink: nextMode === 'edit' ? (server?.joinLink || server?.join_link || '') : '',
            selectedChannelId,
            channelPermissions: [],
            loading: nextMode === 'edit',
            saving: false,
            error: '',
        });
        this.openServerOverlay();
        this.renderServerModal();
        if (nextMode === 'create') {
            this.applyServerRoleCreateDefaults();
        }

        if (nextMode === 'edit' && sid) {
            try {
                const [members, roles, channels] = await Promise.all([
                    this.loadServerMembers(sid),
                    this.loadServerRoles(sid),
                    this.loadServerChannels(sid),
                ]);
                this.setServerModalState({
                    members,
                    roles,
                    channels,
                    loading: false,
                });
                this.renderServerModal();
            } catch (e) {
                this.setServerModalState({ loading: false, error: e?.message || 'Не удалось загрузить участников' });
                this.renderServerModal();
            }
        }
    }

    async openPublicServersModal() {
        const discoverQuery = document.getElementById('serverDiscoverQuery');
        if (discoverQuery) discoverQuery.value = '';
        this.setServerModalState({
            mode: 'discover',
            serverId: null,
            activeSection: 'discover',
            colorPickers: {},
            members: [],
            roles: [],
            channels: [],
            draftRoles: [],
            createDraft: null,
            joinLink: '',
            selectedChannelId: null,
            channelPermissions: [],
            channelCreateOpen: false,
            loading: true,
            saving: false,
            error: '',
        });
        this.openServerOverlay();
        this.renderServerModal();
        await this.loadPublicServers({ silent: true });
    }

    publicServerFilterValue() {
        const input = document.getElementById('serverDiscoverQuery');
        return String(input?.value || '').trim().toLowerCase();
    }

    renderFilteredPublicServers() {
        const q = this.publicServerFilterValue();
        const servers = Array.isArray(this.S.publicServers) ? this.S.publicServers : [];
        if (!q) return servers;
        return servers.filter(server => {
            const haystack = `${server.name || ''} ${server.description || server.hint || ''} ${server.joinLink || server.join_link || ''}`.toLowerCase();
            return haystack.includes(q);
        });
    }

    async loadPublicServers({ silent = false } = {}) {
        try {
            this.setServerModalState({ loading: true, error: '' });
            this.renderServerModal();
            const res = await this.apiFetch(this.apiRoutes.discover.servers);
            if (!res.ok) {
                throw new Error(await res.text() || 'Не удалось загрузить публичные серверы');
            }
            const data = await res.json();
            this.S.publicServers = this.normalizeServers(Array.isArray(data?.servers) ? data.servers : []);
            this.setServerModalState({ loading: false, error: '' });
            this.renderServerModal();
        } catch (e) {
            this.S.publicServers = [];
            this.setServerModalState({
                loading: false,
                error: e?.message || 'Не удалось загрузить публичные серверы',
            });
            this.renderServerModal();
            if (!silent) {
                this.addLogEntry({ type: 'ERROR', msg: e?.message || 'Не удалось загрузить публичные серверы', ts: new Date().toLocaleTimeString() });
            }
        }
    }

    async enterPublicServer(serverIdOrLink) {
        const raw = String(serverIdOrLink || '').trim();
        if (!raw) return;
        await this.joinServerByLink(raw);
        if (this.S.serverModal.mode === 'discover') {
            await this.loadPublicServers({ silent: true });
        }
    }

    async submitServerModal() {
        if (this.S.serverModal.saving) return;
        const mode = this.S.serverModal.mode;
        const serverId = this.S.serverModal.serverId;
        const createDraft = mode === 'edit' ? null : this.syncServerCreateDraftFromDom();
        const nameInput = document.getElementById('serverNameInput');
        const descInput = document.getElementById('serverDescriptionInput');
        const iconInput = document.getElementById('serverIconInput');
        const colorInput = document.getElementById('serverColorInput');
        const joinLinkInput = document.getElementById('serverJoinLinkInput');
        const publicInput = document.getElementById('serverPublicInput');
        const payloadSource = mode === 'edit'
            ? null
            : (createDraft || this.serverCreateDraft());
        const payload = {
            name: (payloadSource ? payloadSource.name : (nameInput?.value || '')).trim(),
            description: (payloadSource ? payloadSource.description : (descInput?.value || '')).trim(),
            icon: (payloadSource ? payloadSource.icon : (iconInput?.value || '')).trim(),
            color: this.normalizeColorValue(payloadSource ? payloadSource.color : (colorInput?.value || '#cbff00')),
            join_link: (payloadSource ? payloadSource.joinLink : (joinLinkInput?.value || '')).trim(),
            is_public: payloadSource ? !!payloadSource.isPublic : !!publicInput?.checked,
        };
        if (mode !== 'edit') {
            payload.roles = this.syncDraftServerRolesFromDom().map(role => {
                const rolePayload = {
                    name: role.name,
                    color: role.color,
                };
                this.serverRolePermissionDefs().forEach(def => {
                    rolePayload[def.key] = !!role[def.key];
                });
                return rolePayload;
            });
        }

        if (!payload.name) {
            this.setServerModalState({ error: 'Введите название сервера' });
            this.renderServerModal();
            return;
        }

        this.setServerModalState({ saving: true, error: '' });
        this.renderServerModal();

        try {
            const endpoint = mode === 'edit' && serverId
                ? this.apiRoutes.servers.byId(serverId)
                : this.apiRoutes.servers.list;
            const res = await this.apiFetch(endpoint, {
                method: mode === 'edit' ? 'PUT' : 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload),
            });
            if (!res.ok) {
                throw new Error(await res.text() || 'Не удалось сохранить сервер');
            }
            const data = await res.json();
            this.closeServerOverlay();
            await this.loadServers({ silent: true });
            if (data?.id) {
                this.setActiveServer(data.id, { persist: true });
            }
        } catch (e) {
            this.setServerModalState({ error: e?.message || 'Не удалось сохранить сервер' });
            this.renderServerModal();
        } finally {
            this.setServerModalState({ saving: false });
        }
    }

    async uploadServerAsset(kind, file) {
        const serverId = this.S.serverModal.serverId || this.S.activeServer;
        if (!serverId || !file || this.S.serverModal.mode !== 'edit') return;
        const downscaled = await this.downscaleServerAssetFile(file, kind);
        const dataUrl = await this.readFileAsDataURL(downscaled);
        const res = await this.apiFetch(this.apiRoutes.servers.assets(serverId, kind), {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            // Binary body (base64 data URL) — apiFetch only auto-detects FormData as a
            // bulk transfer, so a plain JSON body like this one silently got the 8s
            // default meant for ordinary calls instead of the 120s transfer budget
            // (see TRANSFER_REQUEST_TIMEOUT_MS in api.js) — exactly the slow-link
            // failure downscaleServerAssetFile's own comment warns about, just missed
            // here specifically. loadServerAsset (the GET side) already passes it.
            timeoutMs: TRANSFER_REQUEST_TIMEOUT_MS,
            body: JSON.stringify({ data_url: dataUrl }),
        });
        if (!res.ok && res.status !== 204) {
            throw new Error(await res.text() || `Не удалось обновить ${kind}`);
        }
        this.clearServerAssetCache(serverId, kind);
        await this.syncServerAssetPreview(serverId);
    }

    async removeServerAsset(kind) {
        const serverId = this.S.serverModal.serverId || this.S.activeServer;
        if (!serverId || this.S.serverModal.mode !== 'edit') return;
        const res = await this.apiFetch(this.apiRoutes.servers.assets(serverId, kind), {
            method: 'DELETE',
        });
        if (!res.ok && res.status !== 204) {
            throw new Error(await res.text() || `Не удалось удалить ${kind}`);
        }
        this.clearServerAssetCache(serverId, kind);
        await this.syncServerAssetPreview(serverId);
    }

    async generateServerJoinLink() {
        if (this.S.serverModal.saving) return '';
        const mode = this.S.serverModal.mode;
        const server = mode === 'edit'
            ? this.currentServer()
            : null;
        const fallback = mode === 'edit' && server?.id
            ? `zali://server/${server.id}`
            : `zali://server/${(document.getElementById('serverNameInput')?.value || 'server').trim().toLowerCase().replace(/[^a-z0-9]+/g, '-')}`;
        if (mode === 'edit') {
            this.setServerModalState({ joinLink: fallback, error: '' });
        } else {
            const draft = this.syncServerCreateDraftFromDom();
            this.setServerModalState({
                joinLink: fallback,
                createDraft: {
                    ...draft,
                    joinLink: fallback,
                },
                error: '',
            });
        }
        this.renderServerModal();
        return fallback;
    }

    async joinServerByLink(link) {
        const raw = String(link || '').trim();
        if (!raw) return;
        const inviteMatch = raw.match(/(?:zali:\/\/invite\/|invite\/)?([a-z0-9]{4,64})/i);
        if (inviteMatch && /invite/i.test(raw)) {
            const inviteCode = inviteMatch[1].toLowerCase();
            try {
                const res = await this.apiFetch(this.apiRoutes.invites.join(inviteCode), {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ code: inviteCode }),
                });
                if (!res.ok) {
                    throw new Error(await res.text() || 'Не удалось войти по ссылке');
                }
                const data = await res.json();
                await this.loadServers({ silent: true });
                this.closeServerOverlay();
                if (data?.serverId) {
                    this.setActiveServer(data.serverId, { persist: true });
                }
                this.addLogEntry({ type: 'SUCCESS', msg: `Вход по ссылке успешен: ${inviteCode}`, ts: new Date().toLocaleTimeString() });
            } catch (e) {
                this.addLogEntry({ type: 'ERROR', msg: e?.message || 'Не удалось войти по ссылке', ts: new Date().toLocaleTimeString() });
            }
            return;
        }

        try {
            const res = await this.apiFetch(this.apiRoutes.servers.join, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ link: raw }),
            });
            if (!res.ok) {
                throw new Error(await res.text() || 'Не удалось войти по ссылке');
            }
            const data = await res.json();
            await this.loadServers({ silent: true });
            this.closeServerOverlay();
            if (data?.serverId) {
                this.setActiveServer(data.serverId, { persist: true });
            }
            this.addLogEntry({ type: 'SUCCESS', msg: `Вход по ссылке успешен`, ts: new Date().toLocaleTimeString() });
        } catch (e) {
            this.addLogEntry({ type: 'ERROR', msg: e?.message || 'Не удалось войти по ссылке', ts: new Date().toLocaleTimeString() });
        }
    }

    openJoinCodeModal() {
        const existing = document.getElementById('joinCodeModalOverlay');
        if (existing) existing.remove();

        const overlay = document.createElement('div');
        overlay.id = 'joinCodeModalOverlay';
        overlay.className = 'modal-overlay';
        overlay.style.cssText = 'position:fixed;inset:0;z-index:10000;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.55);';
        overlay.innerHTML = `
            <div class="join-code-modal" style="background:var(--panel-bg,#1c1c1e);color:var(--text-color,#fff);border-radius:12px;padding:20px;min-width:280px;max-width:90vw;box-shadow:0 12px 40px rgba(0,0,0,0.4);">
                <div style="font-weight:600;margin-bottom:10px;">Войти по коду</div>
                <input type="text" id="joinCodeModalInput" placeholder="Код или ссылка сервера" autocomplete="off" spellcheck="false"
                    style="width:100%;box-sizing:border-box;padding:10px 12px;border-radius:8px;border:1px solid rgba(255,255,255,0.15);background:rgba(255,255,255,0.06);color:inherit;font-size:14px;margin-bottom:14px;">
                <div style="display:flex;justify-content:flex-end;gap:8px;">
                    <button type="button" id="joinCodeModalCancel" class="btn-flat">Отмена</button>
                    <button type="button" id="joinCodeModalSubmit" class="btn-flat">Войти</button>
                </div>
            </div>
        `;
        document.body.appendChild(overlay);

        const input = document.getElementById('joinCodeModalInput');
        const close = () => overlay.remove();
        const submit = () => {
            const link = this.extractInviteCode(input.value);
            close();
            if (link) this.joinServerByLink(link);
        };

        overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });
        document.getElementById('joinCodeModalCancel').addEventListener('click', close);
        document.getElementById('joinCodeModalSubmit').addEventListener('click', submit);
        input.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') submit();
            if (e.key === 'Escape') close();
        });
        input.focus();
    }

    extractInviteCode(value) {
        const raw = String(value || '').trim();
        if (!raw) return '';
        const match = raw.match(/(?:zali:\/\/invite\/|invite\/|zali:\/\/server\/|server\/)?([a-z0-9._-]{2,128})/i);
        return (match && match[1]) ? match[1].toLowerCase() : raw.toLowerCase();
    }

    rolePayloadFromCreateForm() {
        const nameInput = document.getElementById('serverRoleNameInput');
        const colorInput = document.getElementById('serverRoleColorInput');
        const colorHexInput = document.getElementById('serverRoleColorHexInput');
        const permissions = {};
        this.serverRolePermissionDefs().forEach(def => {
            permissions[def.key] = !!document.querySelector(`[data-server-role-perm="${CSS.escape(def.key)}"]`)?.checked;
        });
        return {
            name: (nameInput?.value || '').trim(),
            color: this.normalizeColorValue(colorInput?.value || colorHexInput?.value || '#cbff00'),
            ...permissions,
        };
    }

    rolePayloadFromCard(roleId) {
        const card = document.querySelector(`[data-role-card="${CSS.escape(String(roleId || ''))}"]`);
        if (!card) return null;
        const name = String(card.querySelector(`[data-role-name="${CSS.escape(String(roleId || ''))}"]`)?.value || '').trim();
        const color = this.normalizeColorValue(card.querySelector(`[data-role-color="${CSS.escape(String(roleId || ''))}"]`)?.value || '#cbff00');
        const permissions = {};
        this.serverRolePermissionDefs().forEach(def => {
            permissions[def.key] = !!card.querySelector(`[data-role-perm="${CSS.escape(def.key)}"]`)?.checked;
        });
        return {
            name,
            color,
            ...permissions,
        };
    }

    async createServerRole() {
        const payload = this.rolePayloadFromCreateForm();
        if (!payload.name) {
            this.setServerModalState({ error: 'Введите название роли' });
            this.renderServerModal();
            return;
        }
        if (this.S.serverModal.mode === 'create') {
            const draftRoles = this.syncDraftServerRolesFromDom();
            const draftPermissions = {};
            this.serverRolePermissionDefs().forEach(def => {
                draftPermissions[def.key] = !!payload[def.key];
            });
            draftRoles.push({
                draftId: `draft-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`,
                collapsed: true,
                name: payload.name,
                color: payload.color,
                ...draftPermissions,
            });
            this.setServerModalState({ draftRoles, error: '' });
            const nameInput = document.getElementById('serverRoleNameInput');
            if (nameInput) nameInput.value = '';
            this.applyServerRoleCreateDefaults();
            this.renderServerModal();
            return;
        }
        const serverId = this.S.serverModal.serverId;
        if (!serverId || this.S.serverModal.mode !== 'edit') return;
        const res = await this.apiFetch(this.apiRoutes.servers.roles(serverId), {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload),
        });
        if (!res.ok) {
            throw new Error(await res.text() || 'Не удалось создать роль');
        }
        const role = await res.json();
        const roles = [role, ...(this.S.serverModal.roles || [])].sort((a, b) => Number(a.position || 0) - Number(b.position || 0));
        this.setServerModalState({ roles, error: '' });
        const nameInput = document.getElementById('serverRoleNameInput');
        if (nameInput) nameInput.value = '';
        this.renderServerModal();
        this.applyServerRoleCreateDefaults();
        await this.loadServers({ silent: true });
    }

    async saveServerRole(roleId) {
        const serverId = this.S.serverModal.serverId;
        if (!serverId || this.S.serverModal.mode !== 'edit') return;
        const payload = this.rolePayloadFromCard(roleId);
        if (!payload) return;
        const res = await this.apiFetch(this.apiRoutes.servers.role(serverId, roleId), {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload),
        });
        if (!res.ok) {
            throw new Error(await res.text() || 'Не удалось сохранить роль');
        }
        const updated = await res.json();
        const roles = (this.S.serverModal.roles || []).map(role => String(role.roleId || '') === roleId ? updated : role);
        this.setServerModalState({ roles, error: '' });
        this.renderServerModal();
        await this.loadServers({ silent: true });
    }

    async deleteServerRole(roleId) {
        const serverId = this.S.serverModal.serverId;
        if (!serverId || this.S.serverModal.mode !== 'edit') return;
        const res = await this.apiFetch(this.apiRoutes.servers.role(serverId, roleId), {
            method: 'DELETE',
        });
        if (!res.ok && res.status !== 204) {
            throw new Error(await res.text() || 'Не удалось удалить роль');
        }
        const roles = (this.S.serverModal.roles || []).filter(role => String(role.roleId || '') !== roleId);
        this.setServerModalState({ roles, error: '' });
        this.renderServerModal();
        await this.loadServers({ silent: true });
    }

    async saveServerMembersFromModal() {
        const serverId = this.S.serverModal.serverId;
        if (!serverId || this.S.serverModal.mode !== 'edit') return;
        try {
            const members = await this.loadServerMembers(serverId);
            this.setServerModalState({ members });
            this.renderServerModal();
            await this.loadServers({ silent: true });
        } catch (e) {
            this.setServerModalState({ error: e?.message || 'Не удалось обновить участников' });
            this.renderServerModal();
        }
    }

    channelPayloadFromCreateForm() {
        const nameInput = document.getElementById('serverChannelNameInput');
        const topicInput = document.getElementById('serverChannelTopicInput');
        const kindInput = document.getElementById('serverChannelKindInput');
        return {
            name: (nameInput?.value || '').trim(),
            topic: (topicInput?.value || '').trim(),
            kind: this.normalizeChannelKind(kindInput?.value || 'text'),
        };
    }

    channelPayloadFromCard(channelId) {
        const card = document.querySelector(`[data-channel-card="${CSS.escape(String(channelId || ''))}"]`);
        if (!card) return null;
        const name = String(card.querySelector(`[data-channel-name="${CSS.escape(String(channelId || ''))}"]`)?.value || '').trim();
        const topic = String(card.querySelector(`[data-channel-topic="${CSS.escape(String(channelId || ''))}"]`)?.value || '').trim();
        const kind = this.normalizeChannelKind(card.querySelector(`[data-channel-kind="${CSS.escape(String(channelId || ''))}"]`)?.value || 'text');
        const positionValue = String(card.querySelector(`[data-channel-position="${CSS.escape(String(channelId || ''))}"]`)?.value || '').trim();
        const position = positionValue === '' ? undefined : Number(positionValue);
        return {
            name,
            topic,
            kind,
            position: Number.isFinite(position) ? position : undefined,
        };
    }

    async createServerChannel() {
        const serverId = this.S.serverModal.serverId;
        if (!serverId || this.S.serverModal.mode !== 'edit') return;
        const payload = this.channelPayloadFromCreateForm();
        if (!payload.name) {
            this.setServerModalState({ error: 'Введите название канала' });
            this.renderServerModal();
            return;
        }
        this.setServerModalState({ saving: true, error: '' });
        this.renderServerModal();
        try {
            const res = await this.apiFetch(this.apiRoutes.servers.channels(serverId), {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload),
            });
            if (!res.ok) {
                throw new Error(await res.text() || 'Не удалось создать канал');
            }
            const data = await res.json();
            const channels = this.normalizeServerChannels(Array.isArray(data) ? data : (Array.isArray(data?.channels) ? data.channels : []));
            const nameInput = document.getElementById('serverChannelNameInput');
            const topicInput = document.getElementById('serverChannelTopicInput');
            if (nameInput) nameInput.value = '';
            if (topicInput) topicInput.value = '';
            this.setServerModalState({ channels, error: '' });
            await this.loadServers({ silent: true });
            if (this.S.activeServer === serverId) {
                this.setActiveServer(serverId, { persist: true });
            }
            this.renderServerModal();
        } catch (e) {
            this.setServerModalState({ error: e?.message || 'Не удалось создать канал' });
            this.renderServerModal();
        } finally {
            this.setServerModalState({ saving: false });
        }
    }

    async saveServerChannel(channelId) {
        const serverId = this.S.serverModal.serverId;
        if (!serverId || this.S.serverModal.mode !== 'edit') return;
        const cid = String(channelId || '').trim();
        const payload = this.channelPayloadFromCard(cid);
        if (!payload || !payload.name) {
            this.setServerModalState({ error: 'Введите название канала' });
            this.renderServerModal();
            return;
        }
        this.setServerModalState({ saving: true, error: '' });
        this.renderServerModal();
        try {
            const res = await this.apiFetch(this.apiRoutes.servers.channel(serverId, cid), {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload),
            });
            if (!res.ok) {
                throw new Error(await res.text() || 'Не удалось сохранить канал');
            }
            const data = await res.json();
            const channels = this.normalizeServerChannels(Array.isArray(data) ? data : (Array.isArray(data?.channels) ? data.channels : []));
            this.setServerModalState({ channels, error: '' });
            await this.loadServers({ silent: true });
            if (this.S.activeServer === serverId) {
                this.setActiveServer(serverId, { persist: true });
            }
            this.renderServerModal();
        } catch (e) {
            this.setServerModalState({ error: e?.message || 'Не удалось сохранить канал' });
            this.renderServerModal();
        } finally {
            this.setServerModalState({ saving: false });
        }
    }

    async deleteServerChannel(channelId) {
        const serverId = this.S.serverModal.serverId;
        if (!serverId || this.S.serverModal.mode !== 'edit') return;
        const cid = String(channelId || '').trim();
        const channel = (this.S.serverModal.channels || []).find(item => String(item.id || '') === cid);
        const confirmDelete = confirm(`Удалить канал "${channel?.name || cid}"?`);
        if (!confirmDelete) return;
        this.setServerModalState({ saving: true, error: '' });
        this.renderServerModal();
        try {
            const res = await this.apiFetch(this.apiRoutes.servers.channel(serverId, cid), {
                method: 'DELETE',
            });
            if (!res.ok && res.status !== 204) {
                throw new Error(await res.text() || 'Не удалось удалить канал');
            }
            let channels = [];
            if (res.status !== 204) {
                const data = await res.json();
                channels = this.normalizeServerChannels(Array.isArray(data) ? data : (Array.isArray(data?.channels) ? data.channels : []));
            }
            this.setServerModalState({ channels, error: '' });
            await this.loadServers({ silent: true });
            if (this.S.activeServer === serverId) {
                this.setActiveServer(serverId, { persist: true });
            }
            this.renderServerModal();
        } catch (e) {
            this.setServerModalState({ error: e?.message || 'Не удалось удалить канал' });
            this.renderServerModal();
        } finally {
            this.setServerModalState({ saving: false });
        }
    }

    currentServer() {
        return (this.S.servers || []).find(server => server.id === this.S.activeServer) || null;
    }

    currentChannel() {
        const server = this.currentServer();
        if (!server) return null;
        return (server.channels || []).find(channel => channel.id === this.S.activeChannel) || null;
    }

    currentServerChatKey() {
        if (!this.S.activeServer || !this.S.activeChannel) return '';
        return `${this.S.activeServer}:${this.S.activeChannel}`;
    }

    currentConversationMode() {
        if (this.S.navMode === 'servers' && this.currentServerChatKey()) {
            return 'servers';
        }
        return 'dm';
    }

    clearActiveServerSelection({ persist = true } = {}) {
        this.S.activeServer = null;
        this.S.activeChannel = null;
        this.S.activeConversationType = 'dm';
        if (persist) {
            this.saveStoredActiveServer(null);
            this.saveStoredActiveChannel(null);
        }
    }
});


// --- MODULE: interface/voice_transport.js ---
// --- ZaliInterface: Голосовые комнаты и транспорт сигналинга. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    voiceRoomKeyForDm(peer) {
        const me = String(this.myName() || '').trim();
        const other = String(peer || '').trim();
        const pair = [me, other].filter(Boolean).sort();
        return pair.length === 2 ? `voice:dm:${pair.join(':')}` : '';
    }

    makeDmCallRoomId(peer) {
        const base = this.voiceRoomKeyForDm(peer);
        if (!base) return '';
        const stamp = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
        return `${base}:${stamp}`;
    }

    voiceRoomKeyForChannel(serverId, channelId) {
        const sid = String(serverId || '').trim();
        const cid = String(channelId || '').trim();
        return sid && cid ? `voice:channel:${sid}:${cid}` : '';
    }

    isVoiceChannel(channel = null) {
        return String(channel?.kind || '').trim().toLowerCase() === 'voice';
    }

    currentVoicePeer() {
        if (this.S.navMode === 'dm') {
            return String(this.S.current || '').trim();
        }
        return '';
    }

    shouldInitiateVoiceOffer(peer) {
        const me = String(this.myName() || '').trim();
        const other = String(peer || '').trim();
        if (!me || !other) return false;
        if (this.voice.roomType === 'dm') {
            if (this.voice.status !== 'connected') return false;
            const direction = String(this.voice.callTrack?.direction || '').trim();
            if (direction) return direction === 'outgoing';
            // callTrack is not guaranteed to still be here: recordVoiceCallHistory
            // nulls it, and a reset racing the accept drops it too. Keying the offerer
            // purely off it meant both sides could conclude "not me" and sit in a
            // connected call that nobody ever negotiates. voice.inviter is echoed to
            // both peers by the server (voice_call_accepted / voice_room_state), so it
            // still yields exactly one offerer; the name tie-break is the last resort.
            const inviter = String(this.voice.inviter || '').trim();
            if (inviter) return inviter === me;
            return this.compareVoicePeerNames(me, other) < 0;
        }
        return this.compareVoicePeerNames(me, other) < 0;
    }

    // The tie-break has to produce the SAME winner on both machines, and the two
    // machines are usually different engines. localeCompare cannot do that: with full
    // ICU 'apple' < 'Zebra' (letters first, case as a tiebreak), while an engine
    // without it falls back to code units, where 'Zebra' < 'apple' ('Z'=90 < 'a'=97).
    // Two peers disagreeing means both offer and both are impolite — each drops the
    // other's offer, no answer is ever sent, and the call is connected and silent.
    // Code-unit order is identical on every engine, which is the only property that
    // matters here; it is never shown to the user.
    compareVoicePeerNames(a, b) {
        const x = String(a || '');
        const y = String(b || '');
        if (x === y) return 0;
        return x < y ? -1 : 1;
    }

    // Deterministic per-pair role for resolving offer/offer glare. Polite means
    // "does not own the offer for this pair": on a collision this side rolls its own
    // offer back and answers the incoming one, while the offer owner keeps its offer
    // and waits to be answered.
    //
    // This MUST be the inverse of shouldInitiateVoiceOffer. Both used to return the
    // same `me.localeCompare(other) < 0`, which made the offer owner *polite*. When
    // both sides offered at once the result was that neither ever answered: the
    // impolite side dropped the incoming offer on the floor by design, and the
    // polite side — the one holding the offer the peer was waiting on — rolled it
    // back. Confirmed against the server's signal log for a dead call: two offers
    // one way, one the other, 30 ICE candidates, and zero answers in either
    // direction. ICE flows in that state, so the call looks connected while no
    // session is ever agreed and nobody hears anybody.
    isPoliteVoicePeer(peer) {
        const me = String(this.myName() || '').trim();
        const other = String(peer || '').trim();
        if (!me || !other) return false;
        if (this.voice.roomType === 'dm') {
            // Mirrors shouldInitiateVoiceOffer's ladder, negated at every rung.
            // Deliberately does NOT consult voice.status: that gates *when* to
            // offer, and folding it in here would make both sides polite during
            // setup, so a rollback could be attempted from a state that has no
            // local offer to roll back.
            const direction = String(this.voice.callTrack?.direction || '').trim();
            if (direction) return direction !== 'outgoing';
            const inviter = String(this.voice.inviter || '').trim();
            if (inviter) return inviter !== me;
            return this.compareVoicePeerNames(me, other) > 0;
        }
        return this.compareVoicePeerNames(me, other) > 0;
    }

    voiceEventPayload(payload = {}) {
        // vid lets the receiver dedupe: voice signaling on native shells travels
        // over a dedicated voice-only WebSocket (separate from the main message
        // socket, with its own reconnect/heartbeat cycle) — the server delivers
        // every voice_* event to ALL of a user's active connections, so as a
        // reliability fallback the main socket now also forwards voice_* events
        // instead of silently dropping them (see handleVoiceEvent's dedupe check).
        // Without vid, that redundant delivery would double-apply offers/answers.
        this.voice.eventSeq = (this.voice.eventSeq || 0) + 1;
        return {
            ...payload,
            type: payload.type || 'voice_signal',
            vid: `${this.myName() || 'me'}:${Date.now().toString(36)}:${this.voice.eventSeq}`,
        };
    }

    sendVoiceEvent(payload = {}) {
        const event = this.voiceEventPayload(payload);
        this.voiceTrace('send-event', {
            type: event.type || '',
            roomId: event.roomId || '',
            roomType: event.roomType || '',
            to: event.to || '',
            signalType: event.signal?.type || '',
            participants: Array.isArray(this.voice.participants) ? this.voice.participants : [],
        });
        if (!this.nativeSupports('voice')) {
            if (this.voice.socket && this.voice.socket.readyState === WebSocket.OPEN) {
                try {
                    this.voice.socket.send(JSON.stringify(event));
                } catch (error) {
                    this.voiceDiag('send-event-failed', { type: event.type || '', to: event.to || '', error: error?.message || String(error) }, 'ERROR');
                    return false;
                }
                return true;
            }
            // Always-on: a signal that never left the client is the single most
            // common cause of a call that looks connected and carries nothing, and
            // the socket's readyState at that moment is what says whether it was a
            // reconnect in progress or a socket that was never opened at all.
            this.voiceDiag('send-event-no-socket', {
                type: event.type || '',
                to: event.to || '',
                signalType: event.signal?.type || '',
                readyState: this.voice.socket ? this.voice.socket.readyState : 'no-socket',
                roomId: this.voice.roomId || '',
            }, 'WARN');
            this.addLogEntry({
                type: 'WARN',
                msg: `Voice signal skipped in browser mode: ${event.type}`,
                ts: new Date().toLocaleTimeString(),
            });
            return false;
        }
        this.postNativeMessage({
            type: NativeMessageTypes.VOICE_EVENT,
            payload: event,
        });
        return true;
    }

    disconnectBrowserVoiceSocket() {
        this.voiceTrace('socket-disconnect', { generation: this.voiceSocketGeneration, hadSocket: !!this.voice.socket });
        this.voiceSocketGeneration += 1;
        this.voiceSocketReconnectDelayMs = 1000;
        if (this.voiceSocketPingTimer) {
            clearInterval(this.voiceSocketPingTimer);
            this.voiceSocketPingTimer = null;
        }
        if (this.voiceSocketReconnectTimer) {
            clearTimeout(this.voiceSocketReconnectTimer);
            this.voiceSocketReconnectTimer = null;
        }
        if (this.voice.socket) {
            try {
                this.voice.socket.onopen = null;
                this.voice.socket.onmessage = null;
                this.voice.socket.onclose = null;
                this.voice.socket.onerror = null;
                this.voice.socket.close();
            } catch (e) {}
        }
        this.voice.socket = null;
        this.voice.socketReady = false;
    }

    scheduleBrowserVoiceSocketReconnect(generation, reason = 'retry') {
        if (this.nativeSupports('voice')) return;
        const baseDelay = this.voiceSocketReconnectDelayMs || 1000;
        const jitter = Math.floor(Math.random() * 500);
        const delay = Math.min(baseDelay + jitter, 30000);
        this.voiceSocketReconnectDelayMs = Math.min(baseDelay * 2, 30000);
        this.voiceDiag('socket-reconnect-scheduled', { generation, reason, delay }, 'WARN');
        if (this.voiceSocketReconnectTimer) {
            clearTimeout(this.voiceSocketReconnectTimer);
            this.voiceSocketReconnectTimer = null;
        }
        this.voiceSocketReconnectTimer = setTimeout(() => {
            if (generation === this.voiceSocketGeneration) {
                this.connectBrowserVoiceSocket();
            }
        }, delay);
    }

    // Sends an immediate app-level ping so the half-open watchdog in the socket's
    // ping interval has fresh evidence to judge by. Safe to call at any time.
    probeVoiceSocketLiveness() {
        if (this.nativeSupports('voice')) return;
        const socket = this.voice.socket;
        if (!socket || socket.readyState !== WebSocket.OPEN) return;
        try {
            this.voiceSocketLastPingAt = Date.now();
            socket.send(JSON.stringify({ type: 'ping' }));
        } catch (e) {}
    }

    async fetchBrowserVoiceSocketTicket() {
        if (!this.S.session?.token) return '';
        const res = await this.apiFetch(this.apiRoutes.auth.wsTicket, { method: 'POST' });
        if (!res.ok) {
            throw new Error(await res.text().catch(() => 'Не удалось получить ws-ticket'));
        }
        const data = await res.json().catch(() => null);
        return String(data?.ticket || '').trim();
    }

    async connectBrowserVoiceSocket() {
        if (this.nativeSupports('voice')) return;
        if (typeof WebSocket === 'undefined') return;
        // Without a session there is no ws-ticket to get, so this could only ever
        // fail — and it failed on a backoff loop, writing a reconnect line into the
        // journal every few seconds for as long as the login screen was open. Login
        // calls this again (applySession), and so does saving a server address.
        if (!this.S?.session?.token) {
            this.voiceTrace('socket-connect-skipped-no-session', {});
            return;
        }
        if (this.voice.socket && (this.voice.socket.readyState === WebSocket.OPEN || this.voice.socket.readyState === WebSocket.CONNECTING)) {
            return;
        }

        this.disconnectBrowserVoiceSocket();
        const generation = ++this.voiceSocketGeneration;
        let url;
        try {
            url = new URL(this.getWsBaseUrl());
        } catch (error) {
            this.addLogEntry({ type: 'ERROR', msg: `Неверный WS URL: ${error?.message || error}`, ts: new Date().toLocaleTimeString() });
            return;
        }

        let ticket = '';
        try {
            ticket = await this.fetchBrowserVoiceSocketTicket();
        } catch (error) {
            this.addLogEntry({ type: 'ERROR', msg: `Не удалось получить ws-ticket: ${error?.message || error}`, ts: new Date().toLocaleTimeString() });
            this.scheduleBrowserVoiceSocketReconnect(generation, 'ticket-fetch-error');
            return;
        }
        if (!ticket) {
            this.addLogEntry({ type: 'ERROR', msg: 'Не удалось получить ws-ticket для voice socket', ts: new Date().toLocaleTimeString() });
            this.scheduleBrowserVoiceSocketReconnect(generation, 'ticket-missing');
            return;
        }
        if (generation !== this.voiceSocketGeneration) {
            return;
        }
        url.searchParams.set('ticket', ticket);

        try {
            this.voiceTrace('socket-connect', { url: url.toString(), generation, auth: 'ws-ticket' });
            const socket = new WebSocket(url.toString());
            this.voice.socket = socket;
            this.voice.socketReady = false;

            socket.onopen = () => {
                if (generation !== this.voiceSocketGeneration) return;
                this.voice.socketReady = true;
                this.voiceSocketReconnectDelayMs = 1000;
                if (this.voiceSocketPingTimer) {
                    clearInterval(this.voiceSocketPingTimer);
                    this.voiceSocketPingTimer = null;
                }
                this.voiceSocketLastInboundAt = Date.now();
                this.voiceSocketLastPingAt = 0;
                this.voiceSocketPingTimer = setInterval(() => {
                    if (generation !== this.voiceSocketGeneration) return;
                    if (!this.voice.socket || this.voice.socket.readyState !== WebSocket.OPEN) return;
                    // Half-open detection. A network path that dies without a FIN
                    // (Wi-Fi drop, VPN re-key, NAT eviction) leaves readyState stuck
                    // at OPEN until TCP finally gives up — minutes during which the
                    // client believes it is in the call, sendVoiceEvent reports
                    // success, and nothing reconnects. The server answers our ping
                    // with a pong, so an unanswered ping is proof the link is gone.
                    // Keyed off ping-vs-reply rather than plain idle time, because a
                    // quiet call legitimately has no traffic for minutes and a
                    // background tab's timers are throttled.
                    const lastPing = this.voiceSocketLastPingAt || 0;
                    if (lastPing > (this.voiceSocketLastInboundAt || 0) && Date.now() - lastPing > 15000) {
                        this.voiceDiag('socket-ping-unanswered', {
                            generation,
                            silentMs: Date.now() - lastPing,
                        }, 'WARN');
                        try { this.voice.socket.close(); } catch (e) {}
                        return; // onclose schedules the reconnect
                    }
                    try {
                        this.voiceSocketLastPingAt = Date.now();
                        this.voice.socket.send(JSON.stringify({ type: 'ping' }));
                    } catch (e) {}
                }, 25000);
                this.voiceDiag('socket-open', { generation, url: url.toString() }, 'SUCCESS');
                this.addLogEntry({ type: 'SUCCESS', msg: 'Browser voice socket connected', ts: new Date().toLocaleTimeString() });
                // This socket doubles as the pure-browser client's only realtime connection
                // (messages + voice signaling both ride it — see onmessage below), so its
                // lifecycle IS the connection-status badge in that mode, same as native
                // shells driving it via SET_CONNECTION_STATUS over their own transport.
                this.setConnectionStatus(true);
                // The browser-side counterpart of the native shells'
                // voice_transport_state:'up'. iOS and Android both declare
                // `voice: false` and therefore run on THIS socket, so without it
                // they were the platforms with no reconnect handling at all: the
                // server evicts a participant whose socket stayed shut, every signal
                // sent while it was down is gone, and the only thing that noticed was
                // the 8-second presence keepalive.
                if (String(this.voice.roomId || '').trim()) {
                    this.voiceDiag('socket-reopened-in-call', {
                        roomId: this.voice.roomId || '',
                        status: this.voice.status || '',
                        peers: this.voice.peerConnections.size,
                    }, 'WARN');
                    this.sendVoiceRoomPresence();
                    this.scheduleVoiceNegotiationRetry('voice-socket-reopened');
                }
            };

            socket.onmessage = (event) => {
                if (generation !== this.voiceSocketGeneration) return;
                // Liveness evidence for the half-open watchdog above. Counts ANY
                // inbound frame, including the server's {"type":"pong"} — which had
                // no branch below and was silently dropped, so nothing ever noticed
                // whether the server was still answering.
                this.voiceSocketLastInboundAt = Date.now();
                let payload = null;
                try {
                    payload = JSON.parse(event.data);
                } catch (e) {
                    return;
                }
                if (payload && typeof payload === 'object' && String(payload.type || '').startsWith('voice_')) {
                    this.handleVoiceEvent(payload);
                } else if (payload && typeof payload === 'object' && payload.type === 'reaction_updated') {
                    // Native shells receive this over their own bridge (see the
                    // `zali_interface:reaction_updated` bus command); the browser has no
                    // such bridge, so this WS is the only path for it here.
                    this.onReactionUpdated(payload);
                } else if (payload && typeof payload === 'object' && payload.type === 'message_deleted') {
                    // Same story as reaction_updated above: native shells get this over
                    // their own bridge, the browser only has this WS.
                    this.onMessageDeleted(payload);
                } else if (payload && typeof payload === 'object' && payload.type === 'message_edited') {
                    this.onMessageEdited(payload);
                } else if (payload && typeof payload === 'object' && payload.type === 'key_envelope_available') {
                    // Native shells receive this over their own bridge (REFRESH_AFTER_KEY);
                    // the browser has no such bridge — without this branch a browser-tab
                    // user with a conversation open never picks up a freshly published key
                    // until they navigate away and back.
                    this.refreshAfterKey();
                } else if (payload && typeof payload === 'object' && payload.type === 'device_approved') {
                    // Pushed when one of our peers approves a new device — republish our
                    // side of any DM/channel keys we've already shared with them instead of
                    // waiting for our own next login. Also pushed when a peer (or one of
                    // our own accounts) simply *registers* a device — approval is a manual
                    // step almost nobody performs, and a keyless device is what makes
                    // messages end up encrypted with a key nobody else has.
                    void this.retryPublishConversationKeys({ reason: 'device_approved_push' });
                } else if (payload && typeof payload === 'object' && payload.type && this.dispatchRealtimeEvent(payload)) {
                    // Общий маршрутизатор (state_sync.js) — ТОТ ЖЕ, в который
                    // нативные оболочки отдают нераспознанные кадры. Ветка стоит
                    // до key_republish_request, но вреда нет: она возвращает false
                    // для всего, что разбирают ветки ниже, и цепочка идёт дальше.
                    // Так у браузера и у нативы одна и та же логика на новые типы.
                } else if (payload && typeof payload === 'object' && payload.type === 'key_republish_request') {
                    // A participant of a specific scope is telling us it holds the wrong
                    // key (or none). Republish just that scope straight away.
                    void this.handleKeyRepublishRequest(payload);
                } else if (payload && typeof payload === 'object' && !payload.type && payload.id && payload.sender && payload.receiver) {
                    // No `type` field = a raw `Message` row pushed by deliver_to_user/
                    // deliver_server_message (server/src/realtime.rs), not a voice/avatar
                    // event. Only reachable in pure-browser mode — native shells receive
                    // and decrypt these themselves over their own transport.
                    void this.handleIncomingBrowserMessage(payload);
                }
            };

            socket.onclose = () => {
                if (generation !== this.voiceSocketGeneration) return;
                this.voice.socketReady = false;
                this.voice.socket = null;
                if (this.voiceSocketPingTimer) {
                    clearInterval(this.voiceSocketPingTimer);
                    this.voiceSocketPingTimer = null;
                }
                this.voiceDiag('socket-close', { generation, url: url.toString(), roomId: this.voice.roomId || '', status: this.voice.status || '' }, 'WARN');
                this.setConnectionStatus(false);
                if (!this.nativeSupports('voice')) {
                    const baseDelay = this.voiceSocketReconnectDelayMs || 1000;
                    const jitter = Math.floor(Math.random() * 500);
                    const delay = Math.min(baseDelay + jitter, 30000);
                    this.voiceSocketReconnectDelayMs = Math.min(baseDelay * 2, 30000);
                    this.voiceSocketReconnectTimer = setTimeout(() => {
                        if (generation === this.voiceSocketGeneration) {
                            this.connectBrowserVoiceSocket();
                        }
                    }, delay);
                }
            };

            socket.onerror = () => {
                if (generation !== this.voiceSocketGeneration) return;
                this.voice.socketReady = false;
                this.voiceTrace('socket-error', { generation, url: url.toString() }, 'WARN');
            };
        } catch (error) {
            this.addLogEntry({ type: 'ERROR', msg: `Не удалось подключить browser voice socket: ${error?.message || error}`, ts: new Date().toLocaleTimeString() });
"""#,
    #"""
        }
    }

    voiceRoomSummary() {
        const roomLabel = this.voice.roomType === 'channel'
            ? (this.currentChannel() ? `#${this.currentChannel().name}` : 'Голосовой канал')
            : this.voice.roomType === 'dm'
                ? `Звонок с ${this.voice.targetUser || this.voice.inviter || ''}`.trim()
                : 'Голос';
        return roomLabel;
    }

    resetVoiceState({ preserveInvite = false } = {}) {
        // Written BEFORE anything is torn down: the per-peer counters, the last
        // stats sample and the selected candidate pair all live on entries this
        // method is about to close, and they are exactly what a post-mortem needs.
        this.logVoiceCallSummary(preserveInvite ? 'reset-keep-invite' : 'reset');
        this.voiceDiag('reset-state', { preserveInvite, roomId: this.voice.roomId || '', roomType: this.voice.roomType || '', status: this.voice.status || '' });
        if (this.voice.negotiationRetryTimer) {
            clearTimeout(this.voice.negotiationRetryTimer);
            this.voice.negotiationRetryTimer = null;
        }
        this.voice.negotiationRetries = 0;
        this.voice.rebuilds = 0;
        this.voice.peerRosterKey = '';
        this.stopVoicePresenceKeepalive();
        this.stopVoiceLinkSupervisor();
        for (const entry of this.voice.peerConnections.values()) {
            if (entry.reconnectTimer) {
                clearTimeout(entry.reconnectTimer);
                entry.reconnectTimer = null;
            }
            if (entry.healthTimer) {
                clearTimeout(entry.healthTimer);
                entry.healthTimer = null;
            }
            if (entry.statsTimer) {
                clearInterval(entry.statsTimer);
                entry.statsTimer = null;
            }
            this.clearVoiceAnswerWatchdog(entry);
            try { entry.pc?.close(); } catch (e) {}
        }
        this.voice.peerConnections.clear();
        this.voice.signalChains?.clear();
        for (const audio of this.voice.remoteAudios.values()) {
            try {
                audio.pause?.();
                if (audio.srcObject) {
                    audio.srcObject = null;
                }
                audio.remove?.();
            } catch (e) {}
        }
        this.voice.remoteAudios.clear();
        this.releaseVoicePlaybackGestureHook();
        for (const video of this.voice.remoteVideos.values()) {
            try { video.pause?.(); video.srcObject = null; video.remove?.(); } catch (e) {}
        }
        this.voice.remoteVideos.clear();
        for (const video of this.voice.remoteScreens.values()) {
            try { video.pause?.(); video.srcObject = null; video.remove?.(); } catch (e) {}
        }
        this.voice.remoteScreens.clear();
        this.detachLocalVideoPreview();
        this.detachLocalScreenPreview();
        this.voice.videoEnabled = false;
        this.voice.cameraOn = false;
        this.voice.screenSharing = false;
        if (this.voice.localStream) {
            for (const track of this.voice.localStream.getTracks()) {
                try { track.stop(); } catch (e) {}
            }
        }
        this.voice.localStream = null;
        // A capture still in flight when the session is torn down must not be
        // handed to the *next* call as its local stream.
        this.voice.localStreamInFlight = null;
        this.voice.micError = '';
        if (this.voice.localScreenStream) {
            for (const track of this.voice.localScreenStream.getTracks()) {
                try { track.stop(); } catch (e) {}
            }
        }
        this.voice.localScreenStream = null;
        if (this.voice.audioContext) {
            try { this.voice.audioContext.close?.(); } catch (e) {}
        }
        this.voice.audioContext = null;
        this.voice.audioResumePending = false;
        this.voice.audioResumeNextAttemptAt = 0;
        this.voice.playbackUnlocked = false;
        this.voice.meterUiRenderedOnce = false;
        this.voice.meterLevels = { local: 0, remote: 0 };
        this.voice.meterLocal = null;
        this.voice.meterRemote.clear();
        this.stopVoiceMeterLoop();
        this.voice.traceLines = [];
        this.voice.roomId = '';
        this.voice.roomType = '';
        this.voice.serverId = '';
        this.voice.channelId = '';
        this.voice.targetUser = '';
        this.voice.inviter = '';
        this.voice.participants = [];
        this.voice.status = 'idle';
        this.voice.muted = false;
        this.voice.deafened = false;
        this.voice.expanded = false;
        this.voice.activeSince = 0;
        this.stopVoiceCallBarTimer();
        this.voice.callTrack = null;
        if (!preserveInvite) {
            this.voice.incomingInvite = null;
            this.voice.outgoingInvite = null;
        }
        this.renderVoicePanel();
        this.scheduleRenderMessages();
    }
});


// --- MODULE: interface/voice_media.js ---
// --- ZaliInterface: Захват микрофона/камеры/экрана, треки, индикаторы уровня. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    // Full mesh has no server-side mixer: every camera is encoded and uploaded once
    // per other participant. Past this many peers a consumer uplink cannot carry
    // video without starving the audio that shares it, and audio is what the call is
    // for — so video is refused with a reason rather than allowed to break the call.
    // Audio alone stays fine well past this; see MAX_MESH_AUDIO_PEERS.
    static get MAX_MESH_VIDEO_PEERS() { return 6; }

    // Not enforced — a mesh audio call this large still works, it just stops being
    // comfortable, and refusing to connect people who asked to be connected is worse
    // than a warning in the log. Crossing it is recorded so that "звонок тормозил at
    // 11 people" is a fact in the journal rather than a recollection.
    static get MAX_MESH_AUDIO_PEERS() { return 8; }

    // Dedupes concurrent capture requests. In a group call every incoming offer
    // handler (and every voice_room_state) calls this, and handleVoiceEvent is
    // dispatched fire-and-forget — so with 3+ participants two or three offers
    // land while localStream is still null and each used to fire its own
    // getUserMedia(). Best case that opened several independent mic captures
    // (mute via track.enabled then only reached some peers, and the surplus
    // captures were never stopped); worst case the 2nd/3rd capture failed with
    // NotReadableError/AbortError because the device was already claimed, so
    // attachLocalVoiceTracks() no-oped for that peer and it answered recvonly —
    // exactly the "некоторые не слышат некоторых" symptom.
    async ensureVoiceLocalStream() {
        if (this.voice.localStream) return this.voice.localStream;
        if (this.voice.localStreamInFlight) return this.voice.localStreamInFlight;
        const pending = this.captureVoiceLocalStream();
        this.voice.localStreamInFlight = pending;
        try {
            return await pending;
        } catch (error) {
            // Without local tracks syncVoicePeers never sends an offer, so the call
            // stays in the room and silent forever. Keep the reason so the panel can
            // say why instead of leaving the user with a mute "connected" call.
            this.voice.micError = this.describeMicError(error);
            this.voiceTrace('local-stream-failed', { error: error?.message || String(error), name: error?.name || '' }, 'ERROR');
            this.renderVoicePanel();
            throw error;
        } finally {
            if (this.voice.localStreamInFlight === pending) {
                this.voice.localStreamInFlight = null;
            }
        }
    }

    // Resolves true once the local stream exists, false if the wait runs out first —
    // and still rejects if the capture itself failed, so a denied microphone stays
    // distinguishable from a slow one. For callers that must make progress on a
    // deadline (answering an offer) rather than block on a permission dialog.
    async awaitVoiceLocalStream(timeoutMs = 4000) {
        if (this.voice.localStream) return true;
        const pending = this.ensureVoiceLocalStream();
        let timer = null;
        // Promise.race attaches its own handlers to both, so a capture that fails
        // after the deadline already won is not an unhandled rejection.
        const deadline = new Promise(resolve => {
            timer = setTimeout(() => resolve(false), Math.max(0, Number(timeoutMs) || 0));
        });
        try {
            return await Promise.race([pending.then(() => true), deadline]);
        } finally {
            if (timer) clearTimeout(timer);
        }
    }

    // getUserMedia's DOMException names are the only reliable signal here (messages
    // differ per browser and are usually empty), and each one needs a different
    // action from the user, so they must not collapse into one generic string.
    describeMicError(error) {
        const name = String(error?.name || '').trim();
        if (name === 'NotAllowedError' || name === 'SecurityError') {
            return 'Доступ к микрофону запрещён. Разрешите его в настройках сайта и переподключитесь к звонку.';
        }
        if (name === 'NotFoundError' || name === 'OverconstrainedError') {
            return 'Микрофон не найден. Подключите устройство ввода и переподключитесь к звонку.';
        }
        if (name === 'NotReadableError' || name === 'AbortError') {
            return 'Микрофон занят другим приложением. Освободите его и переподключитесь к звонку.';
        }
        return error?.message ? `Микрофон недоступен: ${error.message}` : 'Микрофон недоступен.';
    }

    async captureVoiceLocalStream() {
        if (this.voice.localStream) return this.voice.localStream;
        if (!this.voice.supported) {
            throw new Error('Голосовые звонки не поддерживаются в этом окружении');
        }
        const micConstraint = this.audioPrefs?.micDeviceId
            ? { deviceId: { exact: this.audioPrefs.micDeviceId } }
            : true;
        const getAudioOnlyStream = async () => {
            try {
                return await navigator.mediaDevices.getUserMedia({ audio: micConstraint, video: false });
            } catch (error) {
                // Saved device id may no longer exist (unplugged/removed) — fall
                // back to the system default rather than failing the whole call.
                if (micConstraint === true) throw error;
                this.voiceTrace('mic-fallback-default', { error: error?.message || String(error) }, 'WARN');
                return navigator.mediaDevices.getUserMedia({ audio: true, video: false });
            }
        };
        let stream;
        if (this.voice.videoEnabled) {
            try {
                stream = await navigator.mediaDevices.getUserMedia({
                    audio: micConstraint,
                    video: { width: { ideal: 1280 }, height: { ideal: 720 } },
                });
                this.voice.cameraOn = true;
            } catch (error) {
                this.voiceTrace('camera-request-failed', { error: error?.message || String(error) }, 'WARN');
                this.addLogEntry({ type: 'WARN', msg: 'Камера недоступна — продолжаем аудиозвонком', ts: new Date().toLocaleTimeString() });
                this.voice.videoEnabled = false;
                stream = await getAudioOnlyStream();
            }
        } else {
            stream = await getAudioOnlyStream();
        }
        this.voice.localStream = stream;
        this.voice.micError = '';
        this.voice.muted = false;
        this.voiceDiag('local-stream-ready', {
            tracks: stream.getTracks().map(track => `${track.kind}:${track.readyState}:${track.enabled ? 'on' : 'off'}`),
        });
        this.ensureVoiceMeterLoop();
        this.attachLocalVideoPreview();
        return stream;
    }

    attachLocalVideoPreview() {
        if (!this.voice.localStream || !this.voice.localStream.getVideoTracks().length) return;
        let video = this.voice.localVideoEl;
        if (!video) {
            video = document.createElement('video');
            video.autoplay = true;
            video.playsInline = true;
            video.muted = true;
            this.voice.localVideoEl = video;
        }
        if (video.srcObject !== this.voice.localStream) {
            video.srcObject = this.voice.localStream;
        }
        video.play?.().catch(() => {});
        this.scheduleRenderVoicePanel();
    }

    detachLocalVideoPreview() {
        const video = this.voice.localVideoEl;
        if (video) {
            try { video.pause?.(); video.srcObject = null; video.remove?.(); } catch (e) {}
        }
        this.voice.localVideoEl = null;
    }

    async setVoiceCameraEnabled(enabled) {
        if (enabled) {
            await this.enableVoiceCamera();
        } else {
            this.disableVoiceCamera();
        }
    }

    async enableVoiceCamera() {
        // Guards the getUserMedia() call itself, not just the cameraOn result —
        // cameraOn only flips true once the call resolves, so without this a
        // fast double-click fires two concurrent capture requests; whichever
        // resolves last would silently overwrite this.voice.localStream's video
        // track, leaking the other's camera lock with no track.stop() ever called.
        if (this.voice.cameraOn || this.voice.cameraRequestInFlight) return;
        const peerCount = this.voice.peerConnections.size;
        if (peerCount > ZaliInterface.MAX_MESH_VIDEO_PEERS) {
            this.voiceDiag('camera-refused-mesh-size', {
                peers: peerCount,
                limit: ZaliInterface.MAX_MESH_VIDEO_PEERS,
                roomId: this.voice.roomId || '',
            }, 'WARN');
            this.addLogEntry({
                type: 'WARN',
                msg: `Камера недоступна: в звонке ${peerCount} собеседников, видео на всех сразу не поместится в канал`,
                ts: new Date().toLocaleTimeString(),
            });
            return;
        }
        this.voice.cameraRequestInFlight = true;
        try {
            if (!this.voice.localStream) {
                this.voice.videoEnabled = true;
                try {
                    await this.ensureVoiceLocalStream();
                    for (const peer of this.voice.peerConnections.keys()) {
                        await this.attachLocalVoiceTracks(peer);
                    }
                    await this.renegotiateAllVoicePeers();
                } catch (error) {
                    this.voiceTrace('camera-enable-failed', { error: error?.message || String(error) }, 'WARN');
                    this.addLogEntry({ type: 'WARN', msg: error?.message || 'Не удалось включить камеру', ts: new Date().toLocaleTimeString() });
                }
                this.renderVoicePanel();
                return;
            }
            try {
                const camStream = await navigator.mediaDevices.getUserMedia({
                    video: { width: { ideal: 1280 }, height: { ideal: 720 } },
                });
                const track = camStream.getVideoTracks()[0];
                if (!track) return;
                this.voice.localStream.addTrack(track);
                this.voice.videoEnabled = true;
                this.voice.cameraOn = true;
                this.attachLocalVideoPreview();
                for (const peer of this.voice.peerConnections.keys()) {
                    const entry = this.getVoicePeerEntry(peer);
                    if (entry.videoSender) {
                        await entry.videoSender.replaceTrack(track);
                    } else {
                        entry.videoSender = entry.pc.addTrack(track, this.voice.localStream);
                    }
                    await this.applyVoiceVideoBitrateLimit(entry.videoSender, 'camera');
                }
                await this.renegotiateAllVoicePeers();
                this.renderVoicePanel();
            } catch (error) {
                this.voiceTrace('camera-enable-failed', { error: error?.message || String(error) }, 'WARN');
                this.addLogEntry({ type: 'WARN', msg: error?.message || 'Не удалось включить камеру', ts: new Date().toLocaleTimeString() });
            }
        } finally {
            this.voice.cameraRequestInFlight = false;
        }
    }

    disableVoiceCamera() {
        if (!this.voice.cameraOn) return;
        const stream = this.voice.localStream;
        if (stream) {
            for (const track of stream.getVideoTracks()) {
                try { track.stop(); } catch (e) {}
                try { stream.removeTrack(track); } catch (e) {}
            }
        }
        this.voice.cameraOn = false;
        this.voice.videoEnabled = false;
        this.detachLocalVideoPreview();
        for (const entry of this.voice.peerConnections.values()) {
            if (entry.videoSender) {
                try { entry.pc.removeTrack(entry.videoSender); } catch (e) {}
                entry.videoSender = null;
            }
        }
        this.renegotiateAllVoicePeers();
        this.renderVoicePanel();
    }

    async renegotiateAllVoicePeers() {
        for (const peer of this.voice.peerConnections.keys()) {
            await this.renegotiateVoicePeer(peer);
        }
    }

    // Builds this peer's next offer. The only decision it makes is whether the
    // offer must restart ICE — and it must whenever the link is known to be down.
    //
    // Only restartVoicePeer used to pass iceRestart, and it is not the path that
    // ends up sending most recovery offers: a restart requested outside 'stable'
    // parks on renegotiationPending and drains through renegotiateVoicePeer, an
    // unanswered restart offer is retried by the answer watchdog through
    // renegotiateVoicePeer, and syncVoicePeers re-offers through sendVoiceOffer.
    // All three built a PLAIN offer, which re-agrees the media over the transport
    // that is already dead: negotiation completes, signalingState returns to
    // 'stable', both sides look fully negotiated — and not a single packet can
    // flow. Making the flag a property of the link instead of an argument to one
    // function is what keeps every path honest.
    createVoiceOfferFor(entry) {
        if (!entry?.pc) return Promise.reject(new Error('no peer connection'));
        if (entry.needsIceRestart) {
            // Counted so the end-of-call summary can say "this link was restarted
            // nine times" — one restart is a blip, nine is a network worth naming.
            entry.iceRestartCount = Number(entry.iceRestartCount || 0) + 1;
            return entry.pc.createOffer({ iceRestart: true });
        }
        return entry.pc.createOffer();
    }

    async renegotiateVoicePeer(peer) {
        const entry = this.getVoicePeerEntry(peer);
        if (!entry) return;
        // `entry.negotiating` is set synchronously below, before any `await` —
        // closing the race window that `signalingState` alone leaves open
        // (createOffer() doesn't flip signalingState; only setLocalDescription
        // does, so two renegotiations triggered back-to-back — e.g. disabling
        // the camera then immediately stopping screen share — could otherwise
        // both observe 'stable' and both proceed). A call arriving while busy,
        // or while the connection is already mid-negotiation for any other
        // reason (glare, an in-flight initial offer/answer), is queued instead
        // of dropped — onsignalingstatechange drains it once stable again.
        if (entry.negotiating || entry.pc.signalingState !== 'stable') {
            entry.renegotiationPending = true;
            this.voiceTrace('renegotiate-queued', { peer, state: entry.pc.signalingState, negotiating: !!entry.negotiating });
            return;
        }
        entry.negotiating = true;
        try {
            const offer = await this.createVoiceOfferFor(entry);
            await entry.pc.setLocalDescription(offer);
            this.voiceDiag('renegotiate-offer', { peer, roomId: this.voice.roomId || '', iceRestart: !!entry.needsIceRestart });
            const delivered = this.sendVoiceEvent({
                type: 'voice_signal',
                roomId: this.voice.roomId,
                roomType: this.voice.roomType,
                serverId: this.voice.serverId,
                channelId: this.voice.channelId,
                to: peer,
                signal: {
                    type: 'offer',
                    sdp: {
                        type: entry.pc.localDescription?.type || 'offer',
                        sdp: entry.pc.localDescription?.sdp || '',
                    },
                },
            });
            if (!delivered) {
                this.voiceDiag('renegotiate-send-failed', { peer, roomId: this.voice.roomId || '' }, 'WARN');
            }
            // Whether the offer was lost on the way out or its answer never came
            // back, the outcome is identical and equally invisible: this connection
            // stays in 'have-local-offer' and every later renegotiation for it
            // queues forever. The watchdog is the only thing that notices.
            this.armVoiceAnswerWatchdog(entry, peer);
        } catch (error) {
            this.voiceTrace('renegotiate-error', { peer, error: error?.message || String(error) }, 'WARN');
        } finally {
            entry.negotiating = false;
        }
    }

    attachLocalScreenPreview() {
        if (!this.voice.localScreenStream) return;
        let video = this.voice.localScreenVideoEl;
        if (!video) {
            video = document.createElement('video');
            video.autoplay = true;
            video.playsInline = true;
            video.muted = true;
            this.voice.localScreenVideoEl = video;
        }
        if (video.srcObject !== this.voice.localScreenStream) {
            video.srcObject = this.voice.localScreenStream;
        }
        video.play?.().catch(() => {});
        this.scheduleRenderVoicePanel();
    }

    detachLocalScreenPreview() {
        const video = this.voice.localScreenVideoEl;
        if (video) {
            try { video.pause?.(); video.srcObject = null; video.remove?.(); } catch (e) {}
        }
        this.voice.localScreenVideoEl = null;
    }

    toggleScreenShare() {
        if (this.voice.screenSharing) {
            this.stopScreenShare();
        } else {
            this.startScreenShare();
        }
    }

    // Announces which local MediaStream carries the screen share so the peer's
    // ontrack handler can tell it apart from the camera stream (both arrive as
    // separate video tracks from the same peer) — see handleVoiceSignal's
    // 'screen-meta' branch. Relayed through the existing voice_signal envelope,
    // no server changes needed since route_voice_signal is payload-agnostic.
    sendScreenShareMeta(peer, action) {
        this.sendVoiceEvent({
            type: 'voice_signal',
            roomId: this.voice.roomId,
            roomType: this.voice.roomType,
            serverId: this.voice.serverId,
            channelId: this.voice.channelId,
            to: peer,
            signal: {
                type: 'screen-meta',
                action,
                streamId: action === 'start' ? (this.voice.localScreenStream?.id || '') : '',
            },
        });
    }

    // Attaches the already-captured screen track to one peer's connection.
    // Shared by startScreenShare (existing peers) and syncVoicePeers (peers
    // that join/are created after screen sharing already started).
    attachLocalScreenTrackToPeer(peer) {
        if (!this.voice.screenSharing || !this.voice.localScreenStream) return false;
        const entry = this.getVoicePeerEntry(peer);
        if (!entry || entry.screenSender) return false;
        const track = this.voice.localScreenStream.getVideoTracks()[0];
        if (!track) return false;
        entry.screenSender = entry.pc.addTrack(track, this.voice.localScreenStream);
        void this.applyVoiceVideoBitrateLimit(entry.screenSender, 'screen');
        this.sendScreenShareMeta(peer, 'start');
        this.voiceTrace('screen-track-attached', { peer, streamId: this.voice.localScreenStream.id || '' });
        return true;
    }

    async startScreenShare() {
        // Guards the getDisplayMedia() call itself — screenSharing only flips
        // true once it resolves, so a fast double-click before the OS picker
        // even returns would otherwise fire two concurrent capture requests;
        // whichever resolves last silently overwrites localScreenStream,
        // leaking the other capture (its track.stop() never runs, so the OS's
        // "sharing your screen" indicator can stay on for it indefinitely).
        if (this.voice.screenSharing || this.voice.screenShareRequestInFlight) return;
        if (!navigator.mediaDevices?.getDisplayMedia) {
            // Android WebView has no getDisplayMedia() at all (Chromium/WebView
            // limitation, not a missing bridge hook) — route through native
            // MediaProjection capture instead when the platform offers it.
            if (this.nativeSupports('screenCapture')) {
                this.startNativeScreenCapture();
                return;
            }
            this.addLogEntry({ type: 'WARN', msg: 'Демонстрация экрана не поддерживается в этом окружении', ts: new Date().toLocaleTimeString() });
            return;
        }
        this.voice.screenShareRequestInFlight = true;
        try {
            const stream = await navigator.mediaDevices.getDisplayMedia({
                video: { cursor: 'always', frameRate: 30 },
                audio: false,
            });
            const track = stream.getVideoTracks()[0];
            if (!track) return;
            this.voice.localScreenStream = stream;
            this.voice.screenSharing = true;
            // Fires when the user stops sharing via the browser/OS's own
            // "Stop sharing" control, not just our in-app button.
            track.addEventListener('ended', () => this.stopScreenShare());
            this.attachLocalScreenPreview();
            this.voiceTrace('screen-share-start', { streamId: stream.id, label: track.label || '' });
            for (const peer of this.voice.peerConnections.keys()) {
                this.attachLocalScreenTrackToPeer(peer);
            }
            await this.renegotiateAllVoicePeers();
            // screen-meta travels as an independent signal from the SDP that
            // actually carries the track (see sendScreenShareMeta) — if that
            // first send is lost (e.g. a socket reconnect at exactly the wrong
            // moment), the peer's ontrack fires with no id to match and files
            // the screen under camera video with no way to self-correct. A
            // second, post-renegotiation send is cheap, idempotent insurance
            // against a single dropped message.
            for (const peer of this.voice.peerConnections.keys()) {
                if (this.voice.peerConnections.get(peer)?.screenSender) {
                    this.sendScreenShareMeta(peer, 'start');
                }
            }
            this.renderVoicePanel();
        } catch (error) {
            // AbortError/NotAllowedError just mean the user cancelled the
            // browser's screen/window/tab picker — not worth surfacing as a warning.
            if (error?.name !== 'NotAllowedError' && error?.name !== 'AbortError') {
                this.addLogEntry({ type: 'WARN', msg: error?.message || 'Не удалось начать демонстрацию экрана', ts: new Date().toLocaleTimeString() });
            }
            this.voiceTrace('screen-share-failed', { error: error?.message || String(error) }, 'WARN');
        } finally {
            this.voice.screenShareRequestInFlight = false;
        }
    }

    stopScreenShare() {
        if (!this.voice.screenSharing) return;
        if (this.voice.screenCaptureFromNative) {
            this.postNativeMessage({
                type: NativeMessageTypes.STOP_SCREEN_CAPTURE,
                requestId: this.voice.screenCaptureRequestId,
            });
        }
        const stream = this.voice.localScreenStream;
        if (stream) {
            for (const track of stream.getTracks()) {
                try { track.stop(); } catch (e) {}
            }
        }
        this.voice.localScreenStream = null;
        this.voice.screenSharing = false;
        this.resetNativeScreenCaptureState();
        this.detachLocalScreenPreview();
        for (const [peer, entry] of this.voice.peerConnections.entries()) {
            if (entry.screenSender) {
                try { entry.pc.removeTrack(entry.screenSender); } catch (e) {}
                entry.screenSender = null;
                this.sendScreenShareMeta(peer, 'stop');
            }
        }
        this.voiceTrace('screen-share-stop', {});
        this.renegotiateAllVoicePeers();
        this.renderVoicePanel();
    }

    // --- Android-only screen capture path (MediaProjection → <canvas> →
    // canvas.captureStream()). See CLAUDE.md / project_mobile_parity_effort
    // memory: Android WebView has no getDisplayMedia() at the engine level, so
    // native captures frames and this repaints them onto an offscreen canvas;
    // the resulting MediaStreamTrack then flows through the exact same
    // attach/renegotiate/sendScreenShareMeta code the browser path uses above.

    resetNativeScreenCaptureState() {
        this.voice.screenCaptureFromNative = false;
        this.voice.screenCaptureRequestId = '';
        this.voice.screenCaptureCanvas = null;
        this.voice.screenCaptureCtx = null;
        this.voice.screenShareRequestInFlight = false;
    }

    startNativeScreenCapture() {
        this.voice.screenShareRequestInFlight = true;
        const requestId = this.newRequestId();
        this.voice.screenCaptureRequestId = requestId;
        const canvas = document.createElement('canvas');
        this.voice.screenCaptureCanvas = canvas;
        this.voice.screenCaptureCtx = canvas.getContext('2d');
        const sent = this.postNativeMessage({ type: NativeMessageTypes.START_SCREEN_CAPTURE, requestId });
        if (!sent) {
            this.resetNativeScreenCaptureState();
            this.addLogEntry({ type: 'WARN', msg: 'Не удалось начать демонстрацию экрана', ts: new Date().toLocaleTimeString() });
        }
    }

    // Fires once per captured frame (~8fps) while native MediaProjection
    // capture is active. First frame sizes the canvas and turns it into a
    // real MediaStreamTrack via captureStream(); later frames just repaint.
    async onNativeScreenCaptureFrame(payload = {}) {
        const { requestId, dataUrl } = payload;
        if (!requestId || requestId !== this.voice.screenCaptureRequestId || !dataUrl) return;
        const canvas = this.voice.screenCaptureCanvas;
        const ctx = this.voice.screenCaptureCtx;
        if (!canvas || !ctx) return;

        let bitmap;
        try {
            const blob = await (await fetch(dataUrl)).blob();
            bitmap = await createImageBitmap(blob);
        } catch (error) {
            return;
        }
        if (canvas.width !== bitmap.width || canvas.height !== bitmap.height) {
            canvas.width = bitmap.width;
            canvas.height = bitmap.height;
        }
        ctx.drawImage(bitmap, 0, 0);
        bitmap.close?.();

        if (!this.voice.screenSharing) {
            await this.beginNativeScreenCaptureStream();
        }
    }

    async beginNativeScreenCaptureStream() {
        const canvas = this.voice.screenCaptureCanvas;
        if (!canvas) return;
        const stream = canvas.captureStream(8);
        const track = stream.getVideoTracks()[0];
        if (!track) return;
        this.voice.localScreenStream = stream;
        this.voice.screenSharing = true;
        this.voice.screenCaptureFromNative = true;
        this.voice.screenShareRequestInFlight = false;
        // Native-originated stream has no browser "Stop sharing" control, but
        // the track still ends if the underlying canvas stream is torn down.
        track.addEventListener('ended', () => this.stopScreenShare());
        this.attachLocalScreenPreview();
        this.voiceTrace('screen-share-start', { streamId: stream.id, label: 'native-capture' });
        for (const peer of this.voice.peerConnections.keys()) {
            this.attachLocalScreenTrackToPeer(peer);
        }
        await this.renegotiateAllVoicePeers();
        for (const peer of this.voice.peerConnections.keys()) {
            if (this.voice.peerConnections.get(peer)?.screenSender) {
                this.sendScreenShareMeta(peer, 'start');
            }
        }
        this.renderVoicePanel();
    }

    onNativeScreenCaptureError(payload = {}) {
        const { requestId, message } = payload;
        if (requestId && requestId !== this.voice.screenCaptureRequestId) return;
        this.resetNativeScreenCaptureState();
        // Native sends no `message` when the user just declined the system
        // screen-capture consent dialog — matches the browser path's silent
        // handling of getDisplayMedia()'s NotAllowedError/AbortError. A
        // non-empty message means a real failure worth surfacing.
        if (message) {
            this.addLogEntry({ type: 'WARN', msg: message, ts: new Date().toLocaleTimeString() });
        }
        this.voiceTrace('screen-share-failed', { error: message || 'native-capture-cancelled' }, 'WARN');
    }

    // Never awaits a raw ctx.resume(). Callers run this on the critical path of
    // starting, accepting and joining a call, and in WebKit a refused resume() is a
    // promise that never settles (see resumeVoiceAudioContext) — so `await ctx.resume()`
    // here did not merely fail to unlock audio, it stopped call setup dead: no
    // voice_call_invite, no voice_call_accept, no mic, no offer. What the user sees is
    // a call that is "in the room" and silent forever, and in acceptIncomingCall the
    // callSetupInFlight latch is never released either, so every later attempt to
    // answer is dropped as "busy" until the app is restarted. That is exactly what the
    // server log shows for the last sessions: voice_join and not a single voice_signal.
    //
    // Audio unlocking is best-effort by nature (it only ever succeeds when the browser
    // feels the call is user-initiated), so it must never be able to block the call.
    async unlockVoicePlayback() {
        if (this.voice.playbackUnlocked) return true;
        try {
            // Goes through ensureVoiceAudioContext rather than constructing the context
            // inline, so the state-change watcher that re-routes remote audio when the
            // context stalls is always installed.
            const ctx = this.ensureVoiceAudioContext();
            let resumed = true;
            if (ctx && ctx.state === 'suspended') {
                resumed = await this.resumeVoiceAudioContext(ctx);
            }
            // 'Unlocked' means "we spent our user-gesture credit here", not "the
            // context is running" — retrying on every later call would re-enter the
            // same deadline wait. The meter loop keeps retrying the resume in the
            // background, and syncRemoteAudioPlaybackMode routes remote audio through
            // the plain <audio> elements for as long as the graph is not running.
            this.voice.playbackUnlocked = true;
            this.ensureVoiceMeterLoop();
            this.syncRemoteAudioPlaybackMode();
            this.voiceTrace('audio-unlock', {
                contextState: this.voice.audioContext?.state || 'none',
                resumed,
            }, resumed ? 'SUCCESS' : 'WARN');
            return resumed;
        } catch (error) {
            this.voiceTrace('audio-unlock-failed', { error: error?.message || String(error) }, 'WARN');
            return false;
        }
    }

    getVoicePeerEntry(peer) {
        const name = String(peer || '').trim();
        if (!name) return null;
        let entry = this.voice.peerConnections.get(name);
        if (!entry) {
            this.voiceTrace('peer-create', {
                peer: name,
                roomId: this.voice.roomId || '',
                roomType: this.voice.roomType || '',
                supported: this.voice.supported,
            });
            entry = {
                pc: new RTCPeerConnection(this.getVoiceRtcConfig()),
                localTracksAttached: false,
                offerSent: false,
                pendingIceCandidates: [],
                statsTimer: null,
                healthTimer: null,
                answerWatchdog: null,
                answerRetries: 0,
                audioSender: null,
                videoSender: null,
                screenSender: null,
                remoteScreenStreamId: null,
                negotiating: false,
                renegotiationPending: false,
                generatedIceCandidates: 0,
                receivedIceCandidates: 0,
                // Sticky "this link's ICE transport is dead". Set the moment the
                // connection reports disconnected/failed, cleared only when it is
                // genuinely connected again. Every offer built while it is set
                // carries iceRestart — see createVoiceOfferFor.
                needsIceRestart: false,
                // Budget and spacing for the level-triggered supervisor below.
                linkRecoveryAttempts: 0,
                linkRecoverySkipTicks: 0,
            };
            const rtcConfig = entry.pc.getConfiguration?.() || this.getVoiceRtcConfig();
            this.voiceTrace('rtc-config', {
                peer: name,
                policy: rtcConfig.iceTransportPolicy || 'all',
                servers: (rtcConfig.iceServers || []).map(server => ({
                    urls: server.urls,
                    username: server.username ? 'set' : '',
                })),
            });
            this.ensureVoicePeerStatsTimer(name, entry, 5000);
            entry.pc.onicecandidate = (event) => {
                if (event.candidate) {
                    entry.generatedIceCandidates = (entry.generatedIceCandidates || 0) + 1;
                    // Which candidate *types* we managed to gather is the one fact that
                    // separates "TURN is unreachable/misconfigured" from "TURN is fine
                    // and the pairing failed" — no relay candidate here means the call
                    // can only ever work between NAT-friendly peers.
                    (entry.gatheredCandidateTypes || (entry.gatheredCandidateTypes = new Set()))
                        .add(this.describeIceCandidate(event.candidate.candidate).type || '?');
                    this.voiceTrace('ice-candidate', {
                        peer: name,
                        index: entry.generatedIceCandidates,
                        mid: event.candidate.sdpMid,
                        line: event.candidate.sdpMLineIndex,
                        protocol: this.describeIceCandidate(event.candidate.candidate).protocol,
                        candidateType: this.describeIceCandidate(event.candidate.candidate).type,
                        address: this.describeIceCandidate(event.candidate.candidate).address,
                    });
                    // ICE candidates arrive in bursts (dozens within a second); a full
                    // panel re-render per candidate is wasted work — coalesce them.
                    this.scheduleRenderVoicePanel();
                } else {
                    this.voiceDiag('ice-candidate-end', {
                        peer: name,
                        count: entry.generatedIceCandidates || 0,
                        types: entry.gatheredCandidateTypes ? Array.from(entry.gatheredCandidateTypes).join('/') : 'none',
                        state: entry.pc.iceGatheringState,
                    }, entry.gatheredCandidateTypes?.has('relay') ? 'INFO' : 'WARN');
                }
                if (!event.candidate || !this.voice.roomId) return;
                this.sendVoiceEvent({
                    type: 'voice_signal',
                    roomId: this.voice.roomId,
                    roomType: this.voice.roomType,
                    serverId: this.voice.serverId,
                    channelId: this.voice.channelId,
                    to: name,
                    signal: {
                        type: 'ice',
                        candidate: {
                            candidate: event.candidate.candidate,
                            sdpMid: event.candidate.sdpMid,
                            sdpMLineIndex: event.candidate.sdpMLineIndex,
                            usernameFragment: event.candidate.usernameFragment || null,
                        },
                    },
                });
            };
            entry.pc.onicecandidateerror = (event) => {
                // 401/403 from the TURN server, an unresolvable host, or a blocked port
                // all surface only here — and only as a warning nobody sees.
                this.voiceDiag('ice-candidate-error', {
                    peer: name,
                    errorCode: event?.errorCode || '',
                    errorText: event?.errorText || '',
                    url: event?.url || '',
                    roomId: this.voice.roomId || '',
                }, 'WARN');
            };
            entry.pc.onicegatheringstatechange = () => {
                this.voiceTrace('ice-gathering', { peer: name, state: entry.pc.iceGatheringState, roomId: this.voice.roomId || '' });
            };
            entry.pc.oniceconnectionstatechange = () => {
                this.voiceTrace('ice-connection', { peer: name, state: entry.pc.iceConnectionState, roomId: this.voice.roomId || '' });
            };
            entry.pc.onsignalingstatechange = () => {
                this.voiceTrace('signaling-state', { peer: name, state: entry.pc.signalingState, roomId: this.voice.roomId || '' });
                if (entry.pc.signalingState === 'stable' && entry.renegotiationPending && !entry.negotiating) {
                    entry.renegotiationPending = false;
                    this.renegotiateVoicePeer(name).catch(() => {});
                }
            };
            entry.pc.ontrack = (event) => {
                const stream = event.streams?.[0] || new MediaStream([event.track]);
                const track = event.track;
                // A remote camera/screen toggle-off doesn't remove the track from the
                // stream (browsers keep the transceiver, just mute it) — so the old
                // code (trace-only) left the last frame frozen on screen forever, and
                // a later toggle-on reused the same stream/track objects, which
                // attachRemoteVideoStream's reference-equality check then skipped as
                // "already attached", so the picture never resumed either. Route these
                // lifecycle events back through the same attach/detach helpers so the
                // element actually reflects live track state.
                const refreshRemoteVideoTrack = () => {
                    const isScreen = !!(entry.remoteScreenStreamId && stream.id === entry.remoteScreenStreamId);
                    if (isScreen) {
                        this.attachRemoteScreenStream(name, stream);
                    } else {
                        this.attachRemoteVideoStream(name, stream);
                    }
                };
                if (track) {
                    track.onunmute = () => {
                        this.voiceTrace('remote-track-unmute', { peer: name, kind: track.kind, readyState: track.readyState }, 'INFO');
                        if (track.kind === 'video') refreshRemoteVideoTrack();
                    };
                    track.onmute = () => {
                        this.voiceTrace('remote-track-mute', { peer: name, kind: track.kind, readyState: track.readyState }, 'WARN');
                        if (track.kind === 'video') refreshRemoteVideoTrack();
                    };
                    track.onended = () => {
                        this.voiceTrace('remote-track-ended', { peer: name, kind: track.kind, readyState: track.readyState }, 'WARN');
                        if (track.kind === 'video') refreshRemoteVideoTrack();
                    };
                }
                this.voiceTrace('remote-track', {
                    peer: name,
                    kind: event.track?.kind || 'unknown',
                    readyState: event.track?.readyState || '',
                    streamId: stream.id || '',
                    transceiverDirection: event.transceiver?.direction || '',
                    transceiverCurrentDirection: event.transceiver?.currentDirection || '',
                    receiverTrack: event.receiver?.track ? `${event.receiver.track.kind}:${event.receiver.track.readyState}:${event.receiver.track.enabled ? 'on' : 'off'}` : '',
                    tracks: stream.getTracks().map(t => `${t.kind}:${t.readyState}:${t.enabled ? 'on' : 'off'}`),
                });
                if (track && track.kind === 'video' && entry.remoteScreenStreamId && stream.id === entry.remoteScreenStreamId) {
                    this.attachRemoteScreenStream(name, stream);
                } else {
                    this.attachRemoteVoiceStream(name, stream);
                }
            };
            entry.pc.onconnectionstatechange = () => {
                const state = entry.pc.connectionState;
                if (entry.lastConnectionState !== state) {
                    this.voiceDiag('pc-state', {
                        peer: name,
                        from: entry.lastConnectionState || '',
                        to: state,
                        ice: entry.pc.iceConnectionState || '',
                        gathering: entry.pc.iceGatheringState || '',
                        localCand: entry.gatheredCandidateTypes ? Array.from(entry.gatheredCandidateTypes).join('/') : '',
                        remoteCand: entry.receivedIceCandidates || 0,
                    }, state === 'failed' ? 'ERROR' : 'INFO');
                    entry.lastConnectionState = state;
                }
                if (state === 'connected' || state === 'completed') {
                    // The link is genuinely carrying traffic again, so the next
                    // offer on it can be an ordinary one.
                    entry.needsIceRestart = false;
                    entry.linkRecoveryAttempts = 0;
                    entry.linkRecoverySkipTicks = 0;
                    entry.linkRecoveryExhausted = false;
                    if (entry.reconnectTimer) {
                        clearTimeout(entry.reconnectTimer);
                        entry.reconnectTimer = null;
                    }
                    if (entry.healthTimer) {
                        clearTimeout(entry.healthTimer);
                        entry.healthTimer = null;
                    }
                    // Re-armed unconditionally, NOT `if (!entry.statsTimer)`. The
                    // entry is created with a 5 s sampler that nothing on the healthy
                    // path ever cleared, so that guard was always false here and the
                    // health sampler was only ever installed on a link that had
                    // already failed once (statsTimer is cleared in the failed/
                    // disconnected branch below). Which is to say: the always-on
                    // "does RTP flow and can the sink play it" telemetry — written
                    // precisely for calls that look connected and carry no audio —
                    // never ran on the calls it was for, and neither did the sink
                    // self-heal it drives.
                    this.ensureVoicePeerStatsTimer(name, entry, 10000);
                    void this.reportVoiceSelectedPair(name);
                    this.voice.status = 'connected';
                    if (this.voice.callTrack && !this.voice.callTrack.connectedAt) {
                        this.voice.callTrack.connectedAt = Date.now();
                        this.voice.callTrack.outcome = 'connected';
                    }
                    this.renderVoicePanel();
                    return;
                }
                if (state === 'connecting' || state === 'checking') {
                    if (entry.reconnectTimer) {
                        clearTimeout(entry.reconnectTimer);
                        entry.reconnectTimer = null;
                    }
                    if (entry.healthTimer) {
                        clearTimeout(entry.healthTimer);
                        entry.healthTimer = null;
                    }
                    if (this.voice.status !== 'connected') {
                        this.voice.status = 'connecting';
                        this.renderVoicePanel();
                    }
                    const isDmCall = this.voice.roomType === 'dm';
                    const shouldWatchHealth = isDmCall;
                    if (shouldWatchHealth && !entry.healthTimer) {
                        entry.healthTimer = setTimeout(async () => {
                            entry.healthTimer = null;
                            const currentState = entry.pc?.connectionState || '';
                            const currentIce = entry.pc?.iceConnectionState || '';
                            const stats = entry.lastStats || {};
                            const hasTraffic = Number(stats.inBytes || 0) > 0 || Number(stats.outBytes || 0) > 0;
                            if (!this.voice.roomId) return;
                            if (['connected', 'completed'].includes(currentState)) return;
                            if (hasTraffic) return;
                            if (!['new', 'checking', 'connecting'].includes(currentState) && !['new', 'checking'].includes(currentIce)) return;
                            this.voiceDiag('health-restart', {
                                peer: name,
                                roomId: this.voice.roomId || '',
                                state: currentState,
                                ice: currentIce,
                                hasTraffic,
                            }, 'WARN');
                            try {
                                await this.restartVoicePeer(name);
                            } catch (error) {
                                this.addLogEntry({
                                    type: 'WARN',
                                    msg: error?.message || `Не удалось выполнить ICE restart для ${name}`,
                                    ts: new Date().toLocaleTimeString(),
                                });
                            }
                        }, 8000);
                    }
                    return;
                }
                if (state === 'disconnected' || state === 'failed') {
                    this.addLogEntry({ type: 'WARN', msg: `Voice peer ${name} connection ${state}`, ts: new Date().toLocaleTimeString() });
                    // From here on this link can only be revived by an ICE restart,
                    // and this is the LAST event it will ever emit unless something
                    // succeeds — so hand it to the supervisor rather than relying on
                    // the single reconnect timer armed below.
                    entry.needsIceRestart = true;
                    this.ensureVoiceLinkSupervisor();
                    if (entry.reconnectTimer) {
                        clearTimeout(entry.reconnectTimer);
                    }
                    if (entry.healthTimer) {
                        clearTimeout(entry.healthTimer);
                        entry.healthTimer = null;
                    }
                    // Slowed, not stopped. Clearing it outright meant that during
                    // the ~8 minutes the supervisor spends trying to revive a link
                    // there was no health telemetry at all — precisely the window
                    // where "did RTP ever come back" is the question being asked.
                    this.ensureVoicePeerStatsTimer(name, entry, 20000);
                    const isDmCall = this.voice.roomType === 'dm';
                    const allowAutoRestart = true;
                    if (allowAutoRestart) {
                        // Both ends of the pair see the same failure and both used to
                        // fire an ICE restart at the same moment — permanent glare on
                        // exactly the link that was already broken. The side that owns
                        // the offer for this pair (deterministic, both agree) retries
                        // first; the other only steps in later, if that didn't take.
                        const stagger = this.shouldInitiateVoiceOffer(name) ? 0 : 5000;
                        const delay = (state === 'failed' ? 8000 : 10000) + stagger;
                        entry.reconnectTimer = setTimeout(async () => {
                            entry.reconnectTimer = null;
                            if (!this.voice.roomId) return;
                            if (!['disconnected', 'failed'].includes(entry.pc.connectionState)) return;
                            try {
                                await this.restartVoicePeer(name);
                            } catch (error) {
                                this.addLogEntry({ type: 'WARN', msg: error?.message || `Не удалось восстановить голосовую связь с ${name}`, ts: new Date().toLocaleTimeString() });
                            }
                        }, delay);
                    }
                    if (!isDmCall && this.voice.status !== 'connected') {
                        this.voice.status = 'connecting';
                        this.renderVoicePanel();
                    }
                }
            };
            this.voice.peerConnections.set(name, entry);
        }
        return entry;
    }

    // Single owner of the per-peer sampling timer. Every call site used to install
    // its own interval and guess whether one was already running, which is how the
    // health sampler ended up unreachable on a healthy call. Idempotent for the same
    // cadence, so calling it from a state handler that fires repeatedly is free.
    ensureVoicePeerStatsTimer(peer, entry, intervalMs) {
        if (!entry) return;
        if (entry.statsTimer && entry.statsIntervalMs === intervalMs) return;
        if (entry.statsTimer) clearInterval(entry.statsTimer);
        entry.statsIntervalMs = intervalMs;
        entry.statsTimer = setInterval(() => {
            void this.sampleVoicePeerStats(peer);
            void this.reportVoiceAudioHealth(peer);
        }, intervalMs);
    }

    async flushPendingVoiceIceCandidates(entry, peer) {
        if (!entry || !entry.pendingIceCandidates?.length) return;
        const pending = entry.pendingIceCandidates.splice(0, entry.pendingIceCandidates.length);
        this.voiceTrace('ice-flush', { peer, count: pending.length, roomId: this.voice.roomId || '' });
        for (const candidate of pending) {
            try {
                await entry.pc.addIceCandidate(candidate);
            } catch (e) {
                console.warn(`Failed to flush ICE candidate for ${peer}`, e);
            }
        }
    }

    async sampleVoicePeerStats(peer) {
        const name = String(peer || '').trim();
        if (!name) return;
        const entry = this.voice.peerConnections.get(name);
        if (!entry?.pc) return;
        try {
            const stats = await entry.pc.getStats();
            const summary = {
                peer: name,
                connection: entry.pc.connectionState,
                ice: entry.pc.iceConnectionState,
                signaling: entry.pc.signalingState,
                localCandidateCount: entry.generatedIceCandidates || 0,
                remoteCandidateCount: entry.receivedIceCandidates || 0,
            };
            // The per-candidate map below is only ever read by the trace line, and
            // building it means one object plus one summary key for EVERY candidate
            // the connection knows — on a mesh call that is a few hundred short-lived
            // objects per peer per sampling tick, all of it thrown away when the dev
            // trace toggle is off, which it is by default. The compact half of this
            // summary is what the health timer and the call summary read, so that
            // part is always built.
            const verbose = !!this.voiceTraceEnabled;
            const candidatesById = {};
            stats.forEach(report => {
                if (report.type === 'outbound-rtp' && report.kind === 'audio') {
                    summary.outBytes = report.bytesSent;
                    summary.outPackets = report.packetsSent;
                    summary.outAudioLevel = report.audioLevel;
                    summary.outHeaderBytes = report.headerBytesSent;
                }
                if (report.type === 'inbound-rtp' && report.kind === 'audio') {
                    summary.inBytes = report.bytesReceived;
                    summary.inPackets = report.packetsReceived;
                    summary.inAudioLevel = report.audioLevel;
                    summary.inJitter = report.jitter;
                    summary.inHeaderBytes = report.headerBytesReceived;
                }
                if (report.type === 'track' && report.kind === 'audio') {
                    summary.trackAudioLevel = report.audioLevel;
                    summary.trackMuted = report.muted;
                    summary.trackEnded = report.ended;
                }
                if (report.type === 'candidate-pair' && report.state === 'succeeded' && report.nominated) {
                    summary.candidatePair = {
                        local: report.localCandidateId || '',
                        remote: report.remoteCandidateId || '',
                        currentRoundTripTime: report.currentRoundTripTime,
                        availableOutgoingBitrate: report.availableOutgoingBitrate,
                        bytesSent: report.bytesSent,
                        bytesReceived: report.bytesReceived,
                    };
                }
                if (report.type === 'local-candidate' || report.type === 'remote-candidate') {
                    const candidate = {
                        candidateType: report.candidateType,
                        ip: report.ip || report.address,
                        port: report.port,
                        protocol: report.protocol,
                        priority: report.priority,
                    };
                    // Kept either way: the selected pair is labelled from this map,
                    // and "host/udp vs relay/tcp" is the first thing anyone asks of a
                    // bad call. The flat per-candidate summary keys next to it are
                    // pure trace fodder and cost one more key each.
                    candidatesById[report.id] = candidate;
                    if (verbose) {
                        summary[`${report.type.replace('-', '')}_${report.id || 'unknown'}`] = candidate;
                    }
                }
            });
            if (summary.candidatePair) {
                const local = candidatesById[summary.candidatePair.local];
                const remote = candidatesById[summary.candidatePair.remote];
                summary.candidatePair.localLabel = local ? `${local.candidateType}/${local.protocol}/${local.ip || ''}:${local.port || ''}` : summary.candidatePair.local;
                summary.candidatePair.remoteLabel = remote ? `${remote.candidateType}/${remote.protocol}/${remote.ip || ''}:${remote.port || ''}` : summary.candidatePair.remote;
            }
            entry.lastStats = summary;
            entry.lastStatsAt = Date.now();
            this.voiceTrace('rtc-stats', summary);
        } catch (error) {
            this.voiceTrace('rtc-stats-error', { peer: name, error: error?.message || String(error) }, 'WARN');
        }
    }

    // WebKit (WKWebView — the macOS client, and every browser on iOS) does not
    // reject AudioContext.resume() when it refuses: it returns a promise that is
    // NEVER settled. Measured directly in a bare WKWebView: `new AudioContext()` →
    // state 'suspended', `resume()` still pending after 45 s, no rejection, no
    // state change. Every await of it therefore hangs its caller forever, and every
    // `.then()` chain that clears a latch leaves the latch stuck.
    //
    // resumeVoiceAudioContext returns a promise that ALWAYS settles: the real
    // resume if it ever lands, `false` once the deadline passes. Nothing on the
    // call-setup path may await the raw resume().
    resumeVoiceAudioContext(ctx, timeoutMs = 1500) {
        if (!ctx || typeof ctx.resume !== 'function') return Promise.resolve(false);
        let settled = false;
        return new Promise(resolve => {
            const finish = (value) => {
                if (settled) return;
                settled = true;
                resolve(value);
            };
            const timer = setTimeout(() => {
                this.voiceTrace('audio-context-resume-timeout', {
                    state: ctx.state || '',
                    timeoutMs,
                }, 'WARN');
                finish(false);
            }, timeoutMs);
            Promise.resolve(ctx.resume()).then(() => {
                clearTimeout(timer);
                finish(true);
            }).catch(error => {
                clearTimeout(timer);
                this.voiceTrace('audio-context-resume-failed', { error: error?.message || String(error) }, 'WARN');
                finish(false);
            });
        });
    }

    ensureVoiceAudioContext() {
        const AudioCtx = window.AudioContext || window.webkitAudioContext;
        if (!AudioCtx) return null;
        if (!this.voice.audioContext) {
            this.voice.audioContext = new AudioCtx();
            // Remote audio is rendered through this graph only (the <audio> elements
            // are muted so nothing is heard twice), so a context that is 'suspended'
            // — created outside a user gesture, or interrupted by the OS/WebView
            // mid-call — means a call that connects and carries RTP but plays nothing.
            this.voice.audioContext.onstatechange = () => {
                this.voiceTrace('audio-context-state', { state: this.voice.audioContext?.state || '' });
                this.syncRemoteAudioPlaybackMode();
            };
        }
        // Throttled with a pending flag: this helper runs on every meter tick (125 ms),
        // and firing a fresh resume() each time would pile up promises while the
        // context stays suspended. The flag is cleared by resumeVoiceAudioContext's
        // deadline even when WebKit never answers — otherwise one refused resume
        // latches it forever and no later user gesture is ever able to retry.
        const now = Date.now();
        if (this.voice.audioContext.state === 'suspended'
            && !this.voice.audioResumePending
            && now >= Number(this.voice.audioResumeNextAttemptAt || 0)) {
            this.voice.audioResumePending = true;
            this.resumeVoiceAudioContext(this.voice.audioContext).then(resumed => {
                this.voice.audioResumePending = false;
                // Each refused attempt abandons a promise WebKit will never settle, and
                // this runs on the 125 ms meter tick — back off so a context that stays
                // suspended for a whole call doesn't accumulate hundreds of them.
                this.voice.audioResumeNextAttemptAt = resumed ? 0 : Date.now() + 5000;
                this.syncRemoteAudioPlaybackMode();
            });
        }
        return this.voice.audioContext;
    }

    // Autoplay policy can refuse audio.play() outright, and when it does the element
    // simply stays paused: RTP arrives, the WebRTC layer reports a healthy connection,
    // and the call is silent with nothing in it to blame. Only a user gesture lifts
    // the refusal, and the call is not guaranteed to have started with one on this
    // device — a call answered from a notification, a page restored mid-call, or a
    // gesture credit already spent elsewhere all end up here. Nothing retried the
    // playback afterwards, so the silence lasted until the call was restarted.
    // Capture-phase listeners, dropped together with the call.
    ensureVoicePlaybackGestureHook() {
        if (this.voice.playbackGestureHook) return;
        if (typeof document === 'undefined' || typeof document.addEventListener !== 'function') return;
        const events = ['pointerdown', 'touchend', 'keydown', 'click'];
        const handler = () => {
            void this.unlockVoicePlayback();
            this.syncRemoteAudioPlaybackMode();
        };
        for (const type of events) {
            try { document.addEventListener(type, handler, true); } catch (e) {}
        }
        this.voice.playbackGestureHook = () => {
            for (const type of events) {
                try { document.removeEventListener(type, handler, true); } catch (e) {}
            }
        };
    }

    releaseVoicePlaybackGestureHook() {
        const release = this.voice.playbackGestureHook;
        this.voice.playbackGestureHook = null;
        if (typeof release === 'function') {
            try { release(); } catch (e) {}
        }
    }

    // Remote audio has exactly one sink: the per-peer <audio> element. This keeps it
    // unmuted, at the configured volume and actually playing. Called whenever
    // something could have disturbed it (a user gesture, an AudioContext state
    // change, a fresh attach, a health sample that found it paused) — autoplay policy
    // pauses these elements silently. The WebAudio graph drives the level meters
    // only; playback deliberately does not depend on it.
    syncRemoteAudioPlaybackMode() {
        for (const [peer, audio] of this.voice.remoteAudios) {
            if (!audio) continue;
            if ((audio.muted || audio.defaultMuted) && !this.voice.deafened) {
                this.voiceDiag('remote-audio-unmute', { peer }, 'WARN');
            }
            audio.muted = !!this.voice.deafened;
            audio.defaultMuted = false;
            audio.volume = this.effectiveRemoteVolume(peer);
            if (audio.paused) {
                audio.play?.().catch(error => this.voiceDiag('remote-audio-play-failed', {
                    peer, error: error?.message || String(error),
                }, 'WARN'));
            }
        }
    }

    ensureVoiceMeterLoop() {
        if (this.voice.meterRaf) return;
        const tick = async () => {
            if (!this.voice.roomId && !this.voice.localStream && this.voice.peerConnections.size === 0) {
                this.voice.meterRaf = 0;
                return;
            }
            if (document.hidden) {
                this.voice.meterRaf = setTimeout(tick, 1000);
                return;
            }
            try {
                await this.updateVoiceMeters();
            } catch (error) {
                this.voiceTrace('meter-update-error', { error: error?.message || String(error) }, 'WARN');
            }
            this.voice.meterRaf = setTimeout(tick, 125);
        };
        this.voice.meterRaf = setTimeout(tick, 0);
    }

    stopVoiceMeterLoop() {
        if (this.voice.meterRaf) {
            clearTimeout(this.voice.meterRaf);
            this.voice.meterRaf = 0;
        }
    }

    // `buffer` is the per-meter scratch array allocated once in ensureMeterEntry.
    // This used to allocate a fresh Uint8Array(512) on every call, and the loop runs
    // 8×/s for the local mic plus once per remote peer — a steady stream of
    // short-lived typed arrays whose only visible effect was GC pauses during calls.
    // The for-of over a typed array also allocated an iterator per call; an index
    // loop reads the same samples with no allocation at all.
    computeAnalyserLevel(analyser, buffer = null) {
        if (!analyser) return 0;
        const bufferLength = analyser.fftSize;
        const data = (buffer && buffer.length === bufferLength) ? buffer : new Uint8Array(bufferLength);
        analyser.getByteTimeDomainData(data);
        let sum = 0;
        for (let i = 0; i < bufferLength; i++) {
            const normalized = (data[i] - 128) / 128;
            sum += normalized * normalized;
        }
        const rms = Math.sqrt(sum / bufferLength);
        return Math.max(0, Math.min(1, rms * 2.8));
    }

    ensureMeterEntry(key, stream) {
        const ctx = this.ensureVoiceAudioContext();
        if (!ctx || !stream) return null;
        if (key === 'local') {
            const currentId = stream.id || '';
            if (!this.voice.meterLocal || this.voice.meterLocal.streamId !== currentId) {
                try {
                    if (this.voice.meterLocal?.source) this.voice.meterLocal.source.disconnect?.();
                    if (this.voice.meterLocal?.analyser) this.voice.meterLocal.analyser.disconnect?.();
                } catch (e) {}
                const source = ctx.createMediaStreamSource(stream);
                const analyser = ctx.createAnalyser();
                analyser.fftSize = 512;
                analyser.smoothingTimeConstant = 0.8;
                source.connect(analyser);
                this.voice.meterLocal = {
                    streamId: currentId,
                    source,
                    analyser,
                    data: new Uint8Array(analyser.fftSize),
                };
                this.voiceTrace('meter-local-ready', { streamId: currentId, tracks: stream.getTracks().length });
            }
            return this.voice.meterLocal;
        }

        const peer = String(key || '').trim();
        if (!peer) return null;
        const currentId = stream.id || '';
        const existing = this.voice.meterRemote.get(peer);
        if (!existing || existing.streamId !== currentId) {
            try {
                if (existing?.source) existing.source.disconnect?.();
                if (existing?.analyser) existing.analyser.disconnect?.();
            } catch (e) {}
            const source = ctx.createMediaStreamSource(stream);
            const analyser = ctx.createAnalyser();
            analyser.fftSize = 512;
            analyser.smoothingTimeConstant = 0.8;
            source.connect(analyser);
            const next = {
                streamId: currentId,
                source,
                analyser,
                data: new Uint8Array(analyser.fftSize),
            };
            this.voice.meterRemote.set(peer, next);
            this.voiceTrace('meter-remote-ready', { peer, streamId: currentId, tracks: stream.getTracks().length });
            return next;
        }
        return existing;
    }

    updateVoiceMeterDom(kind, percent) {
        const fill = document.getElementById(kind === 'local' ? 'voiceMicLevelFill' : 'voiceServerLevelFill');
        const text = document.getElementById(kind === 'local' ? 'voiceMicLevelText' : 'voiceServerLevelText');
        const row = document.getElementById(kind === 'local' ? 'voiceMicMeter' : 'voiceServerMeter');
        const next = Math.max(0, Math.min(100, Math.round(percent || 0)));
        if (fill) {
            fill.style.width = `${next}%`;
        }
        if (text) {
            text.textContent = `${next}%`;
        }
        if (row) {
            row.dataset.level = String(next);
        }
    }

    async updateVoiceMeters() {
        const localMeter = this.voice.localStream ? this.ensureMeterEntry('local', this.voice.localStream) : null;
        const remoteStreams = [];
        for (const [peer, audio] of this.voice.remoteAudios.entries()) {
            const stream = audio?.srcObject;
            if (stream instanceof MediaStream) {
                remoteStreams.push({ peer, stream });
            }
        }
        const remoteMeters = remoteStreams
            .map(({ peer, stream }) => ({ peer, meter: this.ensureMeterEntry(peer, stream) }))
            .filter(item => item.meter);

        let localLevel = 0;
        if (localMeter?.analyser) {
            localLevel = this.computeAnalyserLevel(localMeter.analyser, localMeter.data);
        }

        let remoteLevel = 0;
        // Per-peer levels feed the tiles' speaking ring; the aggregate max still
        // feeds the single "с сервера" meter below them.
        const tileLevels = {};
        for (const item of remoteMeters) {
            const level = this.computeAnalyserLevel(item.meter.analyser, item.meter.data);
            remoteLevel = Math.max(remoteLevel, level);
            tileLevels[String(item.peer || '').trim().toLowerCase()] = Math.round(level * 100);
        }

        const nextLocal = Math.round(localLevel * 100);
        const nextRemote = Math.round(remoteLevel * 100);
        // A muted mic still produces analyser output on some platforms (the track
        // is disabled downstream), so never light our own ring while muted.
        tileLevels[String(this.myName() || '').trim().toLowerCase()] = this.voice.muted ? 0 : nextLocal;
        this.applyVoiceSpeakingState(tileLevels);
        const changed = nextLocal !== this.voice.meterLevels.local || nextRemote !== this.voice.meterLevels.remote;
        this.voice.meterLevels = { local: nextLocal, remote: nextRemote };
        if (changed || !this.voice.meterUiRenderedOnce) {
            this.updateVoiceMeterDom('local', nextLocal);
            this.updateVoiceMeterDom('remote', nextRemote);
            this.voice.meterUiRenderedOnce = true;
        }
    }

    // 512 kbit/s was not a limit, it was a decoration: Opus voice runs at 24–32
    // kbit/s and would never have reached it. 64 kbit/s is still twice what the
    // encoder asks for — no quality is given up — while actually bounding a runaway
    // encoder, which matters because in a mesh this is paid once PER PEER.
    async applyVoiceAudioBitrateLimit(sender) {
        if (!sender) return;
        try {
            const params = sender.getParameters();
            if (!params.encodings || !params.encodings.length) params.encodings = [{}];
            params.encodings[0].maxBitrate = 64000;
            await sender.setParameters(params);
        } catch (error) {
            this.voiceTrace('audio-bitrate-limit-failed', { error: error?.message || String(error) }, 'WARN');
        }
    }

    // Mesh means every video track is encoded and uploaded once per peer, and
    // nothing capped that at all: five people with cameras on asked each machine for
    // four unconstrained 720p encodes, i.e. 4–10 Mbit/s upstream. The browser's own
    // congestion control reacts to loss, which on an already-saturated uplink means
    // it reacts after the audio has started breaking up — and audio is the one thing
    // a call cannot lose. So the budget is fixed here and divided by the roster.
    //
    // degradationPreference is the other half: with a hard cap, something has to
    // give. Camera gives up resolution and keeps motion smooth; a shared screen is
    // mostly still and unreadable when downscaled, so it gives up frame rate instead.
    voiceVideoBudget(kind = 'camera') {
        const peers = Math.max(1, this.voice.peerConnections.size || 1);
        const total = kind === 'screen' ? 3000000 : 2500000;
        const ceiling = kind === 'screen' ? 2000000 : 1200000;
        const floor = kind === 'screen' ? 250000 : 150000;
        return Math.max(floor, Math.min(ceiling, Math.floor(total / peers)));
    }

    async applyVoiceVideoBitrateLimit(sender, kind = 'camera') {
        if (!sender) return;
        try {
            const params = sender.getParameters();
            if (!params.encodings || !params.encodings.length) params.encodings = [{}];
            const maxBitrate = this.voiceVideoBudget(kind);
            params.encodings[0].maxBitrate = maxBitrate;
            params.degradationPreference = kind === 'screen' ? 'maintain-resolution' : 'balanced';
            await sender.setParameters(params);
            this.voiceTrace('video-bitrate-limit', { kind, maxBitrate, peers: this.voice.peerConnections.size });
        } catch (error) {
            this.voiceTrace('video-bitrate-limit-failed', { kind, error: error?.message || String(error) }, 'WARN');
        }
    }

    // Re-divides the budget when the roster changes. A limit computed for a
    // two-person call is four times too generous once four more people join, and the
    // senders were created long before that happened.
    async refreshVoiceSenderLimits() {
        for (const entry of this.voice.peerConnections.values()) {
            if (entry.videoSender) await this.applyVoiceVideoBitrateLimit(entry.videoSender, 'camera');
            if (entry.screenSender) await this.applyVoiceVideoBitrateLimit(entry.screenSender, 'screen');
        }
    }

    // Returns true when tracks were actually added on this call, so callers can tell
    // "already attached" from "just attached" — an attach that happens after the
    // connection is established needs a renegotiation or the peer never receives it.
    async attachLocalVoiceTracks(peer) {
        const entry = this.getVoicePeerEntry(peer);
        if (!entry || !this.voice.localStream || entry.localTracksAttached) return false;
        const tracks = this.voice.localStream.getTracks();
        this.voiceTrace('attach-local-tracks', { peer, tracks: tracks.length, roomId: this.voice.roomId || '' });
        // The latch is taken, and every addTrack is done, BEFORE the first await —
        // the same discipline `entry.negotiating` needs, and for the same reason.
        // This used to set the flag only after awaiting the bitrate limit, so two
        // overlapping passes (they overlap on every call: voice_call_accepted and
        // voice_call_connected arrive back to back and are dispatched
        // fire-and-forget, and a mic that resolves late releases several waiters at
        // once) both walked past the guard and added the same track twice. A real
        // browser throws InvalidAccessError on the second one — and syncVoicePeers
        // does not guard this call, so the whole pass is abandoned: any peer after
        // this one gets no offer, and the late-track renegotiation never happens.
        entry.localTracksAttached = true;
        const added = [];
        try {
            for (const track of tracks) {
                const senderField = track.kind === 'video' ? 'videoSender' : 'audioSender';
                const sender = entry.pc.addTrack(track, this.voice.localStream);
                entry[senderField] = sender;
                added.push({ track, sender });
            }
        } catch (error) {
            // Nothing was added, so nothing can be double-added by a retry: release
            // the latch. A partial attach keeps it, since re-running would duplicate
            // whatever did land.
            if (!added.length) entry.localTracksAttached = false;
            this.voiceDiag('attach-local-tracks-failed', {
                peer,
                added: added.length,
                error: error?.message || String(error),
                name: error?.name || '',
            }, 'ERROR');
            throw error;
        }
        for (const { track, sender } of added) {
            if (track.kind === 'audio') {
                await this.applyVoiceAudioBitrateLimit(sender);
            } else if (track.kind === 'video') {
                await this.applyVoiceVideoBitrateLimit(sender, 'camera');
            }
            this.voiceTrace('attach-local-track-added', {
                peer,
                track: `${track.kind}:${track.readyState}:${track.enabled ? 'on' : 'off'}`,
                senderTrack: sender?.track ? `${sender.track.kind}:${sender.track.readyState}:${sender.track.enabled ? 'on' : 'off'}` : 'none',
            });
        }
        this.ensureMeterEntry('local', this.voice.localStream);
        this.ensureVoiceMeterLoop();
        return true;
    }

    attachRemoteVoiceStream(peer, stream) {
        const name = String(peer || '').trim();
        if (!name || !stream) return;
        let audio = this.voice.remoteAudios.get(name);
        if (!audio) {
            audio = document.createElement('audio');
            audio.autoplay = true;
            audio.playsInline = true;
            audio.hidden = true;
            audio.preload = 'auto';
            // The element is the PRIMARY sink, not a muted decoy. Remote audio used
            // to be rendered only by the WebAudio graph, and the fallback to the
            // element fired only when the context was not 'running' — so a graph that
            // is running but produces no sound had no fallback and no detection at
            // all. That is a single point of failure for the one thing a call is for.
            // Metering still runs on the graph; playback no longer depends on it.
            audio.muted = !!this.voice.deafened;
            audio.defaultMuted = false;
            audio.volume = this.effectiveRemoteVolume(name);
            audio.dataset.peer = name;
            audio.addEventListener('play', () => this.voiceTrace('remote-audio-play', { peer: name, muted: audio.muted, volume: audio.volume }, 'INFO'));
            audio.addEventListener('playing', () => this.voiceTrace('remote-audio-playing', { peer: name, muted: audio.muted, volume: audio.volume }, 'SUCCESS'));
            audio.addEventListener('pause', () => this.voiceTrace('remote-audio-pause', { peer: name }, 'WARN'));
            audio.addEventListener('ended', () => this.voiceTrace('remote-audio-ended', { peer: name }, 'WARN'));
            audio.addEventListener('error', () => this.voiceTrace('remote-audio-error', { peer: name, error: audio.error?.message || audio.error?.code || 'unknown' }, 'ERROR'));
            document.body.appendChild(audio);
            this.voice.remoteAudios.set(name, audio);
        }
        audio.srcObject = stream;
        this.ensureMeterEntry(name, stream);
        if (this.audioPrefs?.speakerDeviceId && typeof audio.setSinkId === 'function') {
            audio.setSinkId(this.audioPrefs.speakerDeviceId).catch(error => {
                this.voiceTrace?.('speaker-sink-failed', { peer: name, error: error?.message || String(error) }, 'WARN');
            });
        }
        this.syncRemoteAudioPlaybackMode();
        this.ensureVoicePlaybackGestureHook();
        this.ensureVoiceMeterLoop();
        this.attachRemoteVideoStream(name, stream);
        this.voiceTrace('remote-audio-attach', {
            peer: name,
            streamId: stream.id || '',
            tracks: stream.getTracks().map(t => `${t.kind}:${t.readyState}:${t.enabled ? 'on' : 'off'}`),
            readyState: audio.readyState,
            paused: audio.paused,
            muted: audio.muted,
        });
        const attemptPlay = () => audio.play?.().catch(error => this.voiceTrace('remote-audio-play-failed', { peer: name, error: error?.message || String(error) }, 'WARN'));
        attemptPlay();
        requestAnimationFrame(() => attemptPlay());
        setTimeout(attemptPlay, 250);
    }

    attachRemoteVideoStream(peer, stream) {
        const name = String(peer || '').trim();
        if (!name || !stream) return;
        // A track being muted (peer toggled their camera off) doesn't remove it
        // from the stream — only readyState 'ended' or a genuinely absent track
        // does. Treating a muted-but-present track as "no video" is what makes
        // toggling the camera off actually clear the frozen frame instead of
        // just leaving the last rendered picture on screen forever.
        const hasVideo = stream.getVideoTracks().some(t => t.readyState === 'live' && !t.muted);
        let video = this.voice.remoteVideos.get(name);
        if (!hasVideo) {
            if (video) {
                try { video.pause?.(); video.srcObject = null; video.remove?.(); } catch (e) {}
                this.voice.remoteVideos.delete(name);
                this.scheduleRenderVoicePanel();
            }
            return;
        }
        if (!video) {
            video = document.createElement('video');
            video.autoplay = true;
            video.playsInline = true;
            video.muted = true;
            video.dataset.peer = name;
            this.voice.remoteVideos.set(name, video);
        }
        // Always (re)assign + play, even if this exact stream object was already
        // set as srcObject before: a camera turned back on reuses the same local
        // MediaStream/transceiver, so the object reference here is often
        // unchanged even though the track just came back to life — skipping the
        // reassignment on a reference-equality check is what left a re-enabled
        // camera showing nothing for the peer.
        video.srcObject = stream;
        video.play?.().catch(error => this.voiceTrace('remote-video-play-failed', { peer: name, error: error?.message || String(error) }, 'WARN'));
        this.scheduleRenderVoicePanel();
    }

    attachRemoteScreenStream(peer, stream) {
        const name = String(peer || '').trim();
        if (!name || !stream) return;
        let video = this.voice.remoteScreens.get(name);
        if (!video) {
            video = document.createElement('video');
            video.autoplay = true;
            video.playsInline = true;
            video.muted = true;
            video.dataset.peer = name;
            this.voice.remoteScreens.set(name, video);
        }
        if (video.srcObject !== stream) {
            video.srcObject = stream;
        }
        video.play?.().catch(error => this.voiceTrace('remote-screen-play-failed', { peer: name, error: error?.message || String(error) }, 'WARN'));
        this.voiceTrace('remote-screen-attach', { peer: name, streamId: stream.id || '' });
        this.scheduleRenderVoicePanel();
    }

    detachRemoteScreenStream(peer) {
        const name = String(peer || '').trim();
        if (!name) return;
        const video = this.voice.remoteScreens.get(name);
        if (video) {
            try { video.pause?.(); video.srcObject = null; video.remove?.(); } catch (e) {}
            this.voice.remoteScreens.delete(name);
        }
        this.scheduleRenderVoicePanel();
    }
});


// --- MODULE: interface/voice_negotiation.js ---
// --- ZaliInterface: Жизненный цикл пира: offer/answer, рестарты, супервизор связи. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    // Not every rejected offer is a state problem. Once a connection has
    // negotiated a session it owns an immutable media layout, and an offer whose
    // m-sections are laid out differently is refused on those grounds alone —
    // the signaling state is perfectly legal. It happens whenever the peer
    // rebuilds its own RTCPeerConnection (our own dead-transport and
    // unapplicable-offer rebuilds both do exactly that) and the fresh one orders
    // its transceivers differently from the session we already hold:
    //   Failed to set remote offer sdp: The order of m-lines in subsequent offer
    //   doesn't match order from previous offer/answer.
    // Nothing about that is retryable — the layout on this side cannot be
    // reordered, so every redelivery of the same offer fails identically.
    isVoiceSessionShapeError(error) {
        const message = String(error?.message || error || '').toLowerCase();
        return message.includes('m-line') || message.includes('m-lines') || message.includes('media section');
    }

    closeVoicePeer(peer) {
        const name = String(peer || '').trim();
        if (!name) return;
        const entry = this.voice.peerConnections.get(name);
        if (entry) {
            this.voiceDiag('peer-close', { peer: name, roomId: this.voice.roomId || '', ...this.voicePeerSnapshot(name) });
            if (entry.reconnectTimer) {
                clearTimeout(entry.reconnectTimer);
                entry.reconnectTimer = null;
            }
            if (entry.healthTimer) {
                clearTimeout(entry.healthTimer);
                entry.healthTimer = null;
            }
            if (entry.statsTimer) {
                clearInterval(entry.statsTimer);
                entry.statsTimer = null;
            }
            this.clearVoiceAnswerWatchdog(entry);
            entry.audioSender = null;
            entry.videoSender = null;
            entry.screenSender = null;
            entry.remoteScreenStreamId = null;
            try { entry.pc.close(); } catch (e) {}
            this.voice.peerConnections.delete(name);
        }
        // The signal chain is deliberately NOT dropped here: closeVoicePeer can be
        // called from inside that peer's own chain (rebuilding a dead connection),
        // and deleting the entry there would let the next signal from this peer
        // start a second, concurrent chain. handleVoiceSignal already removes the
        // entry once it is the last queued signal, and resetVoiceState clears all.
        const audio = this.voice.remoteAudios.get(name);
        if (audio) {
            try {
                audio.pause?.();
                audio.srcObject = null;
                audio.remove?.();
            } catch (e) {}
            this.voice.remoteAudios.delete(name);
        }
        const video = this.voice.remoteVideos.get(name);
        if (video) {
            try {
                video.pause?.();
                video.srcObject = null;
                video.remove?.();
            } catch (e) {}
            this.voice.remoteVideos.delete(name);
        }
        this.detachRemoteScreenStream(name);
        if (this.voice.meterRemote.has(name)) {
            const meter = this.voice.meterRemote.get(name);
            try {
                meter?.source?.disconnect?.();
                meter?.analyser?.disconnect?.();
            } catch (e) {}
            this.voice.meterRemote.delete(name);
        }
        this.voice.meterLevels.remote = 0;
    }

    async sendVoiceOffer(peer) {
        const entry = this.getVoicePeerEntry(peer);
        if (!entry || !this.voice.localStream) return;
        if (entry.offerSent) return;
        // `negotiating` is checked and set synchronously, before any await. Every
        // room-state broadcast re-runs syncVoicePeers, and a group call produces one
        // per join/leave — two overlapping runs both saw offerSent=false and
        // signalingState='stable' (neither flips until setLocalDescription resolves)
        // and both offered the same peer. The peer answers both; the second answer
        // arrives in 'stable' and is discarded, so whichever offer it belonged to
        // stays half-negotiated and that link carries no audio.
        if (entry.negotiating || entry.pc.signalingState !== 'stable') {
            this.voiceTrace('send-offer-skipped', { peer, state: entry.pc.signalingState, negotiating: !!entry.negotiating }, 'WARN');
            return;
        }
        entry.negotiating = true;
        try {
            await this.sendVoiceOfferInner(entry, peer);
        } finally {
            entry.negotiating = false;
        }
    }

    async sendVoiceOfferInner(entry, peer) {
        this.voiceDiag('send-offer', { peer, roomId: this.voice.roomId || '', roomType: this.voice.roomType || '', iceRestart: !!entry.needsIceRestart });
        await this.attachLocalVoiceTracks(peer);
        const offer = await this.createVoiceOfferFor(entry);
        await entry.pc.setLocalDescription(offer);
        entry.offerSent = true;
        this.voiceDiag('offer-created', {
            peer,
            roomId: this.voice.roomId || '',
            sdpType: entry.pc.localDescription?.type || 'offer',
            sdpLength: entry.pc.localDescription?.sdp?.length || 0,
        });
        const delivered = this.sendVoiceEvent({
            type: 'voice_signal',
            roomId: this.voice.roomId,
            roomType: this.voice.roomType,
            serverId: this.voice.serverId,
            channelId: this.voice.channelId,
            to: peer,
            signal: {
                type: 'offer',
                sdp: {
                    type: entry.pc.localDescription?.type || 'offer',
                    sdp: entry.pc.localDescription?.sdp || '',
                },
            },
        });
        // offerSent used to latch true even when the signal never left the client
        // (socket reconnecting, native bridge refused) — nothing ever retried, so the
        // call sat there reporting "connected" with no media in either direction.
        if (!delivered) {
            entry.offerSent = false;
            this.voiceDiag('offer-send-failed', { peer, roomId: this.voice.roomId || '' }, 'WARN');
            this.scheduleVoiceNegotiationRetry('offer-send-failed');
            return;
        }
        this.armVoiceAnswerWatchdog(entry, peer);
    }

    // An offer that leaves the client but whose ANSWER never comes back leaves this
    // side in 'have-local-offer' with offerSent latched — syncVoicePeers then skips
    // the peer forever, and no other watchdog covers it: the reconnect/ICE-restart
    // path is driven by onconnectionstatechange, and a connection that never got a
    // remote description never starts ICE, so it never reaches 'disconnected' or
    // 'failed' to trigger anything. The peer that did answer sees a healthy call.
    // A single dropped answer frame is enough — the voice socket reconnects mid-call
    // routinely — and the result is a call that looks connected to both sides and is
    // silent for both. Found by scripts/voice_doctor with a 20 % signal drop rate.
    //
    // EVERY path that sets a local offer must arm this, not just the initial one.
    // An ICE restart and a mid-call renegotiation reach the same dead end, and are
    // worse: 'have-local-offer' also blocks every later renegotiation for that peer
    // (they queue on renegotiationPending, which only drains on a return to
    // 'stable' that can never come), so one lost frame freezes that link for the
    // rest of the call.
    armVoiceAnswerWatchdog(entry, peer) {
        if (!entry) return;
        this.clearVoiceAnswerWatchdog(entry);
        entry.answerWatchdog = setTimeout(() => {
            entry.answerWatchdog = null;
            if (!this.voice.roomId) return;
            if (!this.voice.peerConnections.has(peer)) return;
            if (entry.pc.signalingState !== 'have-local-offer') return;
            const attempt = Number(entry.answerRetries || 0) + 1;
            entry.answerRetries = attempt;
            this.voiceDiag('answer-never-arrived', {
                peer,
                roomId: this.voice.roomId || '',
                state: entry.pc.signalingState,
                attempt,
            }, 'WARN');
            // Roll back to 'stable' so the retry can build a fresh offer; without the
            // rollback sendVoiceOffer would refuse (it requires 'stable') and the peer
            // would stay stuck exactly as before.
            Promise.resolve()
                .then(() => entry.pc.setLocalDescription({ type: 'rollback' }))
                .catch(error => this.voiceTrace('answer-watchdog-rollback-failed', {
                    peer, error: error?.message || String(error),
                }, 'WARN'))
                .then(() => {
                    entry.offerSent = false;
                    entry.negotiating = false;
                    if (attempt > 4) {
                        // Bounded: a peer that answers nothing is gone, and re-offering
                        // it forever would keep one dead link renegotiating for the
                        // whole call. The connection-state paths still cover a link
                        // that later fails outright.
                        this.voiceDiag('answer-watchdog-exhausted', { peer, attempt }, 'WARN');
                        return;
                    }
                    // An offer sent on an ALREADY negotiated connection (ICE restart,
                    // track change) cannot be recovered through syncVoicePeers: that
                    // only offers on behalf of the offer owner, and either side may
                    // renegotiate. Re-offer this peer directly instead; the initial
                    // offer (no remote description yet) still goes through the shared
                    // retry so a missing mic is re-acquired on the way.
                    if (entry.pc.remoteDescription) {
                        this.renegotiateVoicePeer(peer).catch(() => {});
                    } else {
                        this.scheduleVoiceNegotiationRetry('answer-never-arrived');
                    }
                });
        }, 8000);
    }

    clearVoiceAnswerWatchdog(entry) {
        if (entry?.answerWatchdog) {
            clearTimeout(entry.answerWatchdog);
            entry.answerWatchdog = null;
        }
    }

    // Bounded re-run of the "get a mic, offer to whoever we owe an offer to" path.
    // Every step of call setup that can fail silently (mic denied while the peer is
    // already connected, a signal dropped by a reconnecting socket, an answer that
    // couldn't be applied) ends up here instead of leaving a live-looking call that
    // never carries audio.
    scheduleVoiceNegotiationRetry(reason = 'retry') {
        if (this.voice.negotiationRetryTimer) return;
        const attempt = Number(this.voice.negotiationRetries || 0) + 1;
        if (attempt > 8) {
            this.voiceDiag('negotiation-retry-exhausted', { reason, attempt, roomId: this.voice.roomId || '' }, 'WARN');
            return;
        }
        this.voice.negotiationRetries = attempt;
        this.voiceDiag('negotiation-retry-scheduled', { reason, attempt, roomId: this.voice.roomId || '' });
        this.voice.negotiationRetryTimer = setTimeout(async () => {
            this.voice.negotiationRetryTimer = null;
            if (!String(this.voice.roomId || '').trim()) return;
            if (!this.isInActiveCall()) return;
            try {
                await this.ensureVoiceLocalStream();
            } catch (error) {
                this.voiceTrace('negotiation-retry-mic-failed', { error: error?.message || String(error) }, 'WARN');
            }
            try {
                await this.syncVoicePeers();
            } catch (error) {
                this.voiceTrace('negotiation-retry-failed', { error: error?.message || String(error) }, 'WARN');
            }
        }, Math.min(1500 * attempt, 6000));
    }

    async restartVoicePeer(peer) {
        const name = String(peer || '').trim();
        if (!name || !this.voice.roomId) return;
        const entry = this.getVoicePeerEntry(name);
        if (!entry || !this.voice.localStream) return;
        // Marked before the queueing check, not after it: the queued request drains
        // through renegotiateVoicePeer, which used to build a plain offer and so
        // silently turned every deferred restart into a no-op on a dead transport.
        entry.needsIceRestart = true;
        // createOffer({iceRestart}) + setLocalDescription throws outside 'stable'.
        // Both ends of a pair arm their own reconnect/health timers, so in a group
        // call restarts land on top of an in-flight (re)negotiation routinely —
        // queue instead of throwing and leaving the pair broken.
        if (entry.negotiating || entry.pc.signalingState !== 'stable') {
            entry.renegotiationPending = true;
            this.voiceTrace('restart-queued', { peer: name, state: entry.pc.signalingState, negotiating: !!entry.negotiating }, 'WARN');
            return;
        }
        if (entry.healthTimer) {
            clearTimeout(entry.healthTimer);
            entry.healthTimer = null;
        }
        this.voiceDiag('restart-offer', { peer: name, roomId: this.voice.roomId || '', ...this.voicePeerSnapshot(name) });
        await this.attachLocalVoiceTracks(name);
        const offer = await this.createVoiceOfferFor(entry);
        await entry.pc.setLocalDescription(offer);
        entry.offerSent = true;
        this.voiceTrace('offer-restart-created', {
            peer: name,
            roomId: this.voice.roomId || '',
            sdpType: entry.pc.localDescription?.type || 'offer',
            sdpLength: entry.pc.localDescription?.sdp?.length || 0,
        });
        const delivered = this.sendVoiceEvent({
            type: 'voice_signal',
            roomId: this.voice.roomId,
            roomType: this.voice.roomType,
            serverId: this.voice.serverId,
            channelId: this.voice.channelId,
            to: name,
            signal: {
                type: 'offer',
                sdp: {
                    type: entry.pc.localDescription?.type || 'offer',
                    sdp: entry.pc.localDescription?.sdp || '',
                },
            },
        });
        if (!delivered) {
            // Same latch bug sendVoiceOfferInner already guards against: an offer that
            // never left the client must not count as sent. This path is worse — it
            // only runs on a link that is ALREADY broken, and the reconnect timer that
            // brought us here was cleared by the state change that armed it, so
            // nothing else would ever try again.
            entry.offerSent = false;
            this.voiceDiag('offer-restart-send-failed', { peer: name, roomId: this.voice.roomId || '' }, 'WARN');
        }
        // An ICE restart whose answer is lost is the worst case of all: the transport
        // is dead, the connection state does not change (it is already failed), so no
        // further reconnect timer is ever armed. Without this the peer is gone for the
        // rest of the call.
        this.armVoiceAnswerWatchdog(entry, name);
    }

    // Level-triggered supervision of the peer links, as opposed to everything else
    // in this file, which is edge-triggered off onconnectionstatechange.
    //
    // That distinction is the whole point. 'failed' is a terminal state: the event
    // fires once on the way in and never again, because there is nothing left to
    // transition to. Every recovery hung off that single edge therefore gets
    // exactly one attempt, and if that attempt is dropped — the offer never leaves
    // the socket, its answer is lost, the network is still down 8 s later — the
    // link is dead for the rest of the call while the panel keeps saying «В эфире».
    // Reachability, meanwhile, is not an edge at all: it comes back on its own
    // schedule, minutes later, with no event to announce it. Only something that
    // re-reads the actual state can act on that.
    //
    // Costs nothing on a healthy call: the timer is armed by the failure and stops
    // itself as soon as no link needs watching.
    ensureVoiceLinkSupervisor() {
        if (this.voice.linkSupervisorTimer) return;
        this.voice.linkSupervisorTimer = setInterval(() => {
            try {
                this.superviseVoiceLinks();
            } catch (error) {
                this.voiceTrace('link-supervisor-error', { error: error?.message || String(error) }, 'WARN');
            }
        }, 5000);
    }

    stopVoiceLinkSupervisor() {
        if (this.voice.linkSupervisorTimer) {
            clearInterval(this.voice.linkSupervisorTimer);
            this.voice.linkSupervisorTimer = null;
        }
    }

    superviseVoiceLinks() {
        if (!String(this.voice.roomId || '').trim()) {
            this.stopVoiceLinkSupervisor();
            return;
        }
        let watching = false;
        for (const [name, entry] of this.voice.peerConnections) {
            const state = String(entry?.pc?.connectionState || '');
            if (state === 'connected' || state === 'completed') {
                entry.needsIceRestart = false;
                entry.linkRecoveryAttempts = 0;
                entry.linkRecoverySkipTicks = 0;
                // Cleared here too, not only from onconnectionstatechange: the dead-call
                // detector below treats this flag as "this link is finished", so a link
                // that came back must not still be carrying it.
                entry.linkRecoveryExhausted = false;
                continue;
            }
            if (state !== 'failed' && state !== 'disconnected') continue;
            watching = true;
            entry.needsIceRestart = true;
            // Something is already trying: the reconnect timer armed by the state
            // change, a negotiation in flight, or an offer whose answer is still
            // within the watchdog's window. Doubling up here would only produce
            // glare on a link that is already struggling.
            if (entry.reconnectTimer || entry.negotiating || entry.answerWatchdog) continue;
            if (entry.pc.signalingState !== 'stable') continue;
            if (entry.linkRecoverySkipTicks > 0) {
                entry.linkRecoverySkipTicks -= 1;
                continue;
            }
            const attempt = Number(entry.linkRecoveryAttempts || 0) + 1;
            // Bounded, but generously: at a ceiling of one attempt per 25 s this is
            // roughly eight minutes of trying. Long enough to outlast a tunnel, a
            // lift or a Wi-Fi→LTE handover, and still not a link renegotiating for
            // the rest of a two-hour call.
            if (attempt > 20) {
                if (!entry.linkRecoveryExhausted) {
                    entry.linkRecoveryExhausted = true;
                    this.voiceDiag('link-recovery-exhausted', {
                        peer: name,
                        roomId: this.voice.roomId || '',
                        attempts: attempt - 1,
                        ...this.voicePeerSnapshot(name),
                    }, 'ERROR');
                }
                continue;
            }
            entry.linkRecoveryAttempts = attempt;
            // 5 s, 10 s, 15 s, 20 s, then 25 s from there on.
            entry.linkRecoverySkipTicks = Math.min(attempt, 4);
            this.voiceDiag('link-recovery', {
                peer: name,
                roomId: this.voice.roomId || '',
                state,
                ice: entry.pc.iceConnectionState || '',
                attempt,
            }, 'WARN');
            // Not awaited: the supervisor tick must not be held up by one peer, and
            // restartVoicePeer re-entrancy is already guarded by entry.negotiating.
            Promise.resolve(this.restartVoicePeer(name)).catch(error => {
                this.voiceTrace('link-recovery-failed', { peer: name, error: error?.message || String(error) }, 'WARN');
            });
        }
        if (!watching) this.stopVoiceLinkSupervisor();
        this.concludeDeadVoiceCallIfNeeded();
    }

    // A call whose every link has given up is over, and nothing said so. The
    // supervisor stopped after ~8 minutes of trying, the panel kept showing «В
    // эфире» with a participant list frozen at whoever was there when the network
    // went, and the only way out was for the user to guess that and press the red
    // button. Worse, no call record was written, so the conversation kept no trace
    // of a call that really happened.
    //
    // Deliberately conservative: it fires only when there IS at least one peer and
    // EVERY one of them has exhausted its recovery budget. A call still holding one
    // working link is not dead, and a room we have not managed to negotiate with yet
    // (no peer entries at all) is handled by the negotiation retry, not here.
    concludeDeadVoiceCallIfNeeded() {
        if (!String(this.voice.roomId || '').trim()) return;
        const entries = Array.from(this.voice.peerConnections.values());
        if (!entries.length) return;
        if (!entries.every(entry => entry.linkRecoveryExhausted)) return;
        this.voiceDiag('call-dead-all-links-exhausted', {
            roomId: this.voice.roomId || '',
            roomType: this.voice.roomType || '',
            peers: entries.length,
        }, 'ERROR');
        this.addLogEntry({
            type: 'ERROR',
            msg: 'Связь со всеми участниками потеряна — звонок завершён',
            ts: new Date().toLocaleTimeString(),
        });
        void this.leaveVoiceRoom({ announce: true, outcome: 'failed' });
    }

    // Same conclusion reached from the other direction: the server told us the room
    // we think we are in does not exist. Nothing can be signalled into a room that is
    // gone — no ICE restart, no re-offer — so the call is over whatever the panel
    // says. Before this, voice_error was written to the journal and otherwise
    // ignored, and the client sat in a room the server had forgotten, re-asserting
    // presence into the void every 8 s.
    concludeVanishedVoiceRoom(roomId, message = '') {
        const current = String(this.voice.roomId || '').trim();
        const reported = String(roomId || '').trim();
        if (!current || (reported && reported !== current)) return false;
        this.voiceDiag('call-dead-room-vanished', {
            roomId: current,
            roomType: this.voice.roomType || '',
            status: this.voice.status || '',
            message,
        }, 'ERROR');
        this.addLogEntry({
            type: 'ERROR',
            msg: 'Голосовая комната больше не существует на сервере — звонок завершён',
            ts: new Date().toLocaleTimeString(),
        });
        // announce:false — there is nothing to announce to, and voice_leave for a
        // missing room only earns another voice_error.
        void this.leaveVoiceRoom({ announce: false, outcome: 'failed' });
        return true;
    }

    // Re-asserts room membership. The server evicts a user from their voice room
    // 150 s after their WebSocket closes (the delayed cleanup in realtime.rs — the
    // window has been 12 s and 45 s in the past, and both were shorter than a real
    // reconnect; check realtime.rs before trusting a number written here), and
    // nothing ever re-joined afterwards: the browser voice socket's onopen doesn't
    // re-join, and on native shells the voice transport reconnects entirely inside
    // Swift/Rust (NetworkService.connectVoiceWebSocket / run_voice_transport) — JS
    // never even learns it happened. So any blip past 12 s (Wi-Fi roam, VPN re-key,
    // sleep) turned that one participant into a ghost: their UI still showed a live
    // call, but the server no longer routed signals to them (route_voice_signal
    // rejects a non-participant sender) and everyone else got a roster without them
    // and tore down the peer. voice_join is idempotent, so re-sending it is enough.
    sendVoiceRoomPresence() {
        const roomId = String(this.voice.roomId || '').trim();
        if (!roomId) return false;
        const status = String(this.voice.status || '');
        // Not while a DM invite is still ringing — the room is 'ringing' then and
        // joining it would make us a participant before the call is even accepted.
        if (status !== 'connecting' && status !== 'connected') return false;
        const roomType = String(this.voice.roomType || '').trim();
        if (roomType !== 'channel' && roomType !== 'dm') return false;
        return this.sendVoiceEvent({
            type: 'voice_join',
            roomId,
            roomType,
            serverId: this.voice.serverId,
            channelId: this.voice.channelId,
            // Marks this as a membership re-assert rather than a real join, so the
            // server treats it as non-destructive: it may put us back into a room we
            // were evicted from, but must never move us out of one we are still in.
            // Rooms are tracked per ACCOUNT, not per device — without this flag two
            // devices on the same account in two different rooms would evict each
            // other every keepalive tick and flap both calls forever.
            keepalive: true,
        });
    }

    ensureVoicePresenceKeepalive() {
        if (this.voice.presenceTimer) return;
        // Far shorter than the server's eviction window, so a reconnect that lands
        // inside it never costs the call; if it lands after, this is what brings the
        // participant back instead of leaving them silently dropped. Also the first
        // thing that runs after a transport reconnect (voice_transport_state), so in
        // practice membership is re-asserted immediately rather than up to 8 s later.
        this.voice.presenceTimer = setInterval(() => {
            if (!String(this.voice.roomId || '').trim()) {
                this.stopVoicePresenceKeepalive();
                return;
            }
            this.sendVoiceRoomPresence();
        }, 8000);
    }

    stopVoicePresenceKeepalive() {
        if (this.voice.presenceTimer) {
            clearInterval(this.voice.presenceTimer);
            this.voice.presenceTimer = null;
        }
    }

    async syncVoicePeers() {
        const participants = Array.isArray(this.voice.participants) ? this.voice.participants : [];
        const peers = participants
            .map(name => String(name || '').trim())
            .filter(Boolean)
            .filter(name => name !== this.myName());
        const nextPeers = new Set(peers);
        // The retry budget is a single global counter, so in a group call one peer
        // that keeps failing used to burn all 8 attempts and then nothing — for any
        // peer — could ever retry again. A changed roster is a genuinely new
        // situation (someone joined or left), so give it a fresh budget.
        const rosterKey = peers.slice().sort().join(' ');
        const rosterChanged = this.voice.peerRosterKey !== rosterKey;
        if (rosterChanged) {
            const previous = this.voice.peerRosterKey;
            this.voice.peerRosterKey = rosterKey;
            this.voice.negotiationRetries = 0;
            // Always-on: who is in the room, and when it changed, is the frame every
            // other voice line has to be read against — a peer that "never got an
            // offer" usually turns out to have joined after the pass that would have
            // sent it.
            this.voiceDiag('roster-changed', {
                roomId: this.voice.roomId || '',
                roomType: this.voice.roomType || '',
                status: this.voice.status || '',
                peers,
                count: peers.length,
                was: previous || '(none)',
            });
            if (peers.length > ZaliInterface.MAX_MESH_AUDIO_PEERS) {
                this.voiceDiag('mesh-size-over-comfort', {
                    roomId: this.voice.roomId || '',
                    peers: peers.length,
                    limit: ZaliInterface.MAX_MESH_AUDIO_PEERS,
                }, 'WARN');
            }
        }
        this.voiceTrace('sync-peers', {
            roomId: this.voice.roomId || '',
            roomType: this.voice.roomType || '',
            status: this.voice.status || '',
            me: this.myName(),
            peers,
            localStream: !!this.voice.localStream,
        });

        for (const peer of this.voice.peerConnections.keys()) {
            if (!nextPeers.has(peer)) {
                this.closeVoicePeer(peer);
            }
        }

        let offerPending = false;
        for (const peer of peers) {
            const entry = this.getVoicePeerEntry(peer);
            let attachedNow = false;
            try {
                attachedNow = await this.attachLocalVoiceTracks(peer);
            } catch (error) {
                // One connection refusing tracks must not abandon the pass for
                // everyone else: this loop is the only thing that offers to the
                // remaining peers, so an escaping exception here silences the whole
                // room to fix nothing. Retry covers the peer that failed.
                this.voiceDiag('sync-peer-attach-failed', {
                    peer,
                    roomId: this.voice.roomId || '',
                    error: error?.message || String(error),
                }, 'ERROR');
                this.scheduleVoiceNegotiationRetry('attach-failed');
                continue;
            }
            // A peer whose offer we answered before the microphone was ready got a
            // recvonly answer, and nothing renegotiated once the mic did arrive — so
            // that side of the call stayed permanently silent. Adding tracks to an
            // already-negotiated connection has no effect without a fresh offer.
            if (attachedNow && entry.pc.remoteDescription) {
                this.voiceTrace('late-local-tracks-renegotiate', { peer, roomId: this.voice.roomId || '' }, 'WARN');
                await this.renegotiateVoicePeer(peer);
            }
            this.attachLocalScreenTrackToPeer(peer);
            if (!this.shouldInitiateVoiceOffer(peer)) continue;
            if (!this.voice.localStream) {
                // We owe this peer an offer but have no mic yet (permission prompt
                // still open, device busy). Nothing else re-drove this before, so the
                // call just stayed silent forever.
                offerPending = true;
                continue;
            }
            if (entry.offerSent) continue;
            try {
                await this.sendVoiceOffer(peer);
            } catch (e) {
                this.addLogEntry({ type: 'ERROR', msg: `Не удалось начать голосовой обмен с ${peer}`, ts: new Date().toLocaleTimeString() });
            }
            if (!entry.offerSent) offerPending = true;
        }
        if (offerPending) {
            this.scheduleVoiceNegotiationRetry('offer-pending');
        } else if (peers.length) {
            this.voice.negotiationRetries = 0;
        }
        // The video budget is divided by the roster, and the roster just moved, so
        // limits computed for a smaller call are now several times too generous.
        // Done HERE rather than next to the roster-change detection at the top: the
        // peer connections the budget is divided by are created and closed by the
        // loop above, so up there the count is still the previous roster's and the
        // recomputed limit would be one roster behind.
        if (rosterChanged) void this.refreshVoiceSenderLimits();
        this.renderVoicePanel();
    }

    async joinVoiceChannel({ serverId = null, channelId = null } = {}) {
        const server = this.currentServer();
        const channel = server && channelId ? (server.channels || []).find(ch => ch.id === channelId) : this.currentChannel();
        const sid = String(serverId || server?.id || '').trim();
        const cid = String(channelId || channel?.id || '').trim();
        if (!sid || !cid) return;
        if (!this.isVoiceChannel(channel)) {
            return;
        }
        const roomId = this.voiceRoomKeyForChannel(sid, cid);
        if (!roomId) return;
        // Joining a voice channel used to overwrite live call state exactly the way
        // startDirectCall did: an in-progress DM call (or another voice channel) was
        // never left, so the server kept us in the old room while the UI showed the
        // new one. Same room = idempotent no-op instead of a redundant re-join.
        const activeRoomId = String(this.voice.roomId || '').trim();
        if (activeRoomId === roomId && this.isInActiveCall()) {
            this.renderVoicePanel();
            return;
        }
        if (activeRoomId && this.isInActiveCall()) {
            await this.endCurrentVoiceSession({ reason: 'join-voice-channel' });
        }
        void this.refreshVoiceTurnCredentials();
        // Channel joins never unlocked playback, so the AudioContext could stay
        // suspended for the whole session — this is a click handler, i.e. the one
        // moment the browser lets us resume it. Not awaited: see unlockVoicePlayback.
        void this.unlockVoicePlayback();
        // Capture the mic HERE, in the click handler, not only from the voice_room_state
        // that comes back over the WS. Both DM paths (startDirectCall /
        // performAcceptIncomingCall) already do this; the channel path was the one that
        // asked for the microphone from an async WS event instead — and Safari (desktop
        // and every iOS browser, including the installed PWA) rejects a getUserMedia
        // permission prompt that isn't tied to a user gesture. The result was a call
        // that joined the room, rendered as «В эфире», and never sent a single offer,
        // because syncVoicePeers has no tracks to offer with. Failure is non-fatal: the
        // room is still joined (the peer may be audible one way), micError explains why.
        try {
            await this.ensureVoiceLocalStream();
        } catch (error) {
            this.addLogEntry({
                type: 'WARN',
                msg: this.voice.micError || error?.message || 'Не удалось получить доступ к микрофону',
                ts: new Date().toLocaleTimeString(),
            });
        }
        this.voice.negotiationRetries = 0;
        this.voice.roomId = roomId;
        this.voice.roomType = 'channel';
        this.voice.serverId = sid;
        this.voice.channelId = cid;
        this.voice.status = 'connecting';
        this.voice.participants = [];
        this.sendVoiceEvent({
            type: 'voice_join',
            roomId,
            roomType: 'channel',
            serverId: sid,
            channelId: cid,
        });
        this.ensureVoicePresenceKeepalive();
        this.renderVoicePanel();
    }

    async leaveVoiceRoom({ announce = true, outcome = 'completed' } = {}) {
        const roomId = String(this.voice.roomId || '').trim();
        this.voiceDiag('leave-room', {
            roomId,
            roomType: this.voice.roomType || '',
            announce,
            outcome,
            participants: Array.isArray(this.voice.participants) ? this.voice.participants : [],
        });
        if (this.voice.roomType === 'dm' && roomId && this.voice.callTrack && !this.voice.callTrack.recorded) {
            this.recordVoiceCallHistory({ outcome, endedAt: Date.now() });
        }
        if (announce && roomId) {
            this.sendVoiceEvent({
                type: 'voice_leave',
                roomId,
                roomType: this.voice.roomType,
                serverId: this.voice.serverId,
                channelId: this.voice.channelId,
            });
        }
        this.resetVoiceState();
    }

    // Tears down whatever voice session is live right now, picking the signal its
    // state actually requires: a ringing *outgoing* invite must be cancelled, a
    // ringing *incoming* one rejected, an established room left. Starting a new
    // call used to just overwrite roomId/callTrack/participants in place, which
    // left the previous room alive on the server (nobody ever sent voice_leave)
    // and its RTCPeerConnections running headless — the "звонок поверх звонка"
    // the user hit by pressing a call button mid-call.
    async endCurrentVoiceSession({ reason = 'switch' } = {}) {
        const roomId = String(this.voice.roomId || '').trim();
        const status = String(this.voice.status || '');
        const outgoing = this.voice.outgoingInvite;
        const incoming = this.voice.incomingInvite;
        this.voiceTrace('end-current-session', { reason, roomId, status });
        if (status === 'incoming' && incoming?.roomId && incoming?.from) {
            await this.rejectIncomingCall();
            return;
        }
        if (status === 'calling' && outgoing?.roomId && outgoing?.target) {
            this.sendVoiceEvent({
                type: 'voice_call_cancel',
                roomId: outgoing.roomId,
                target: outgoing.target,
            });
            this.recordVoiceCallHistory({ outcome: 'cancelled', endedAt: Date.now() });
            this.resetVoiceState({ preserveInvite: false });
            return;
        }
        if (roomId) {
            await this.leaveVoiceRoom({ announce: true, outcome: 'completed' });
            return;
        }
        this.resetVoiceState({ preserveInvite: false });
    }
});


// --- MODULE: interface/voice_call.js ---
// --- ZaliInterface: Управление звонком и записи о звонках. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    async startDirectCall(peer, { video = false } = {}) {
        const target = String(peer || '').trim();
        if (!target) return;
        // Re-entrancy guard. startDirectCall awaits (playback unlock, getUserMedia),
        // so a double-click ran it twice before the first pass had any state to test
        // against — and makeDmCallRoomId stamps a *fresh* roomId each time, so the
        // server ended up with two ringing rooms for one pair. The callee auto-rejects
        // the second as busy, the caller's outgoingInvite by then points at that second
        // room, so the rejection wiped the caller's whole call state; the accept for the
        // first room then arrived with no callTrack, leaving a call that reports
        // "connected" while neither side ever sends an offer — a silent call.
        if (this.isVoiceCallSetupBusy('start-dm-call')) {
            this.voiceTrace('start-dm-call-ignored-busy-setup', { target }, 'WARN');
            return;
        }
        const activeRoomId = String(this.voice.roomId || '').trim();
        if (activeRoomId && this.isInActiveCall()) {
            const activePeer = String(this.voice.targetUser || this.voice.inviter || '').trim();
            if (activePeer === target) {
                this.voiceTrace('start-dm-call-ignored-same-peer', {
                    target,
                    roomId: activeRoomId,
                    status: this.voice.status || '',
                }, 'WARN');
                this.renderVoicePanel();
                return;
            }
        }
        // Latched before the teardown below, not after it: ending the previous call
        // awaits, and a second click landing in that window would otherwise sail past
        // the guard and start a parallel setup.
        this.voice.callSetupInFlight = true;
        this.voice.callSetupStartedAt = Date.now();
        try {
            if (activeRoomId && this.isInActiveCall()) {
                this.addLogEntry({
                    type: 'INFO',
                    msg: `Завершаем текущий звонок перед звонком ${target}`,
                    ts: new Date().toLocaleTimeString(),
                });
                await this.endCurrentVoiceSession({ reason: 'start-other-call' });
            }
            const me = String(this.myName() || '').trim();
            const roomId = this.makeDmCallRoomId(target);
            if (!roomId) return;
            this.voiceTrace('start-dm-call', { target, me, roomId, video });
            this.voice.videoEnabled = !!video;
            // Not awaited on purpose — see refreshVoiceTurnCredentials: a rotating
            // TURN credential is an optimisation over the static one, never a
            // precondition, so it must not be able to delay or fail a call.
            void this.refreshVoiceTurnCredentials();
            // Deliberately not awaited: the synchronous part (creating the context and
            // calling resume()) is what has to happen inside the user gesture, and the
            // rest is best-effort. Awaiting it put a promise WebKit may never settle in
            // front of the invite — see unlockVoicePlayback.
            void this.unlockVoicePlayback();
            this.voice.callTrack = {
                roomId,
                peer: target,
                roomType: 'dm',
                direction: 'outgoing',
                startedAt: Date.now(),
                connectedAt: 0,
                endedAt: 0,
                outcome: 'calling',
                recorded: false,
            };
            this.voice.outgoingInvite = {
                roomId,
                target,
            };
            this.voice.roomId = roomId;
            this.voice.roomType = 'dm';
            this.voice.targetUser = target;
            this.voice.inviter = me;
            this.voice.participants = [me, target].filter(Boolean);
            this.voice.status = 'calling';
            this.voice.negotiationRetries = 0;
            this.sendVoiceEvent({
                type: 'voice_call_invite',
                roomId,
                roomType: 'dm',
                target,
            });
            this.renderVoicePanel();
            try {
                await this.ensureVoiceLocalStream();
                await this.syncVoicePeers();
            } catch (error) {
                this.addLogEntry({
                    type: 'WARN',
                    msg: error?.message || 'Не удалось подготовить микрофон для звонка',
                    ts: new Date().toLocaleTimeString(),
                });
            }
        } finally {
            this.voice.callSetupInFlight = false;
            this.voice.callSetupStartedAt = 0;
        }
    }

    // The re-entrancy latch that guards call setup is released in a `finally`, so any
    // await inside setup that never settles disables calling entirely — «Позвонить»
    // and «Принять» just stop responding, with only a trace line to show for it, until
    // the app is restarted. A latch older than any plausible setup is treated as
    // abandoned rather than trusted: the worst case of being wrong is one redundant
    // setup, the worst case of trusting it is a client that can no longer call at all.
    isVoiceCallSetupBusy(reason = '') {
        if (!this.voice.callSetupInFlight) return false;
        const startedAt = Number(this.voice.callSetupStartedAt || 0);
        if (startedAt && Date.now() - startedAt > 30000) {
            this.voiceDiag('call-setup-latch-stale', {
                reason,
                ageMs: Date.now() - startedAt,
            }, 'WARN');
            this.voice.callSetupInFlight = false;
            this.voice.callSetupStartedAt = 0;
            return false;
        }
        return true;
    }

    async acceptIncomingCall() {
        const invite = this.voice.incomingInvite;
        if (!invite?.roomId || !invite?.from) return;
        // Same re-entrancy hazard as startDirectCall: this awaits before it clears
        // incomingInvite, so a double-tap on «Принять» sent two voice_call_accept
        // events and restarted the local setup mid-flight.
        if (this.isVoiceCallSetupBusy('accept-incoming')) {
            this.voiceTrace('accept-incoming-ignored-busy-setup', { roomId: invite.roomId }, 'WARN');
            return;
        }
        this.voice.callSetupInFlight = true;
        this.voice.callSetupStartedAt = Date.now();
        try {
            await this.performAcceptIncomingCall(invite);
        } finally {
            this.voice.callSetupInFlight = false;
            this.voice.callSetupStartedAt = 0;
        }
    }

    async performAcceptIncomingCall(invite) {
        const me = String(this.myName() || '').trim();
        this.voiceDiag('accept-incoming', { roomId: invite.roomId, from: invite.from, me });
        void this.refreshVoiceTurnCredentials();
        // Not awaited — see unlockVoicePlayback. Awaited here, a refused resume() left
        // the callee holding callSetupInFlight forever: the accept was never sent, and
        // «Принять» silently did nothing on every later call too.
        void this.unlockVoicePlayback();
        this.voice.roomId = String(invite.roomId || '').trim();
        this.voice.roomType = 'dm';
        this.voice.targetUser = String(invite.from || '').trim();
        this.voice.inviter = String(invite.from || '').trim();
        this.voice.participants = [me, String(invite.from || '').trim()].filter(Boolean);
        this.voice.status = 'connecting';
        this.voice.negotiationRetries = 0;
        this.voice.callTrack = {
            roomId: invite.roomId,
            peer: invite.from,
            roomType: 'dm',
            direction: 'incoming',
            startedAt: Date.now(),
            connectedAt: 0,
            endedAt: 0,
            outcome: 'connecting',
            recorded: false,
        };
        this.addLogEntry({
            type: 'INFO',
            msg: `Принимаем звонок ${this.voice.roomId} от ${invite.from}`,
            ts: new Date().toLocaleTimeString(),
        });
        this.renderVoicePanel();
        this.sendVoiceEvent({
            type: 'voice_call_accept',
            roomId: invite.roomId,
            inviter: invite.from,
        });
        this.renderVoicePanel();
        try {
            await this.ensureVoiceLocalStream();
            await this.syncVoicePeers();
        } catch (error) {
            this.addLogEntry({
                type: 'WARN',
                msg: error?.message || 'Не удалось подготовить микрофон для ответа на звонок',
                ts: new Date().toLocaleTimeString(),
            });
        }
    }

    async rejectIncomingCall() {
        const invite = this.voice.incomingInvite;
        if (!invite?.roomId || !invite?.from) return;
        this.voiceTrace('reject-incoming', { roomId: invite.roomId, from: invite.from });
        this.sendVoiceEvent({
            type: 'voice_call_reject',
            roomId: invite.roomId,
            inviter: invite.from,
        });
        this.recordVoiceCallHistory({ outcome: 'rejected', endedAt: Date.now() });
        this.resetVoiceState({ preserveInvite: false });
    }

    toggleVoiceMute() {
        const stream = this.voice.localStream;
        if (!stream) return;
        const nextMuted = !this.voice.muted;
        for (const track of stream.getAudioTracks()) {
            track.enabled = !nextMuted;
        }
        this.voice.muted = nextMuted;
        this.renderVoicePanel();
    }

    // "Deafen": silences everything coming FROM the call (remote mic + remote
    // camera audio track), independent of our own mic mute. Applied to every
    // live element immediately, and to each newly attached remote audio/video
    // element going forward (see attachRemoteAudioElement / mountVoiceVideoElements).
    toggleVoiceDeafen() {
        this.voice.deafened = !this.voice.deafened;
        this.applyVoiceDeafenState();
        this.renderVoicePanel();
    }

    // Remote <video> elements are always muted (see attachRemoteVoiceVideo) —
    // playback audio comes solely from the per-peer <audio> element created in
    // attachRemoteVoiceStream, so that's the only sink deafen needs to touch.
    applyVoiceDeafenState() {
        const deafened = !!this.voice.deafened;
        for (const audio of this.voice.remoteAudios.values()) {
            try { audio.muted = deafened; } catch (e) {}
        }
    }

    // Collapsed top bar <-> fullscreen grid. Purely a local UI toggle — it does
    // not touch tracks or connections, so it's safe to flip mid-call.
    toggleVoiceCallExpanded() {
        this.voice.expanded = !this.voice.expanded;
        this.renderVoicePanel();
    }

    // Called from every "the user navigated somewhere else" entry point
    // (switchChat, setActiveChannel, setActiveServer, and the Hub/ZaliCoin/
    // Settings tab openers) so the fullscreen call grid never keeps covering
    // the screen for a chat/channel/tab the user just left. The call itself
    // (and the collapsed bar) is untouched — only the expanded/collapsed flag.
    collapseActiveCallView() {
        if (!this.voice.expanded) return;
        this.voice.expanded = false;
        this.renderVoicePanel();
    }

    formatCallClock(ms) {
        const total = Math.max(0, Math.round(Number(ms) || 0) / 1000) | 0;
        const mm = Math.floor(total / 60);
        const ss = String(total % 60).padStart(2, '0');
        return `${mm}:${ss}`;
    }

    // Ticks the bar/expanded-header timer text once a second without going
    // through renderVoicePanel — a full innerHTML rebuild every second would
    // tear down and remount the <video> elements mid-call for no reason.
    startVoiceCallBarTimer() {
        if (this.voice.barTimerInterval) return;
        const tick = () => {
            const since = Number(this.voice.activeSince || 0);
            if (!since) return;
            const label = this.formatCallClock(Date.now() - since);
            const bar = document.getElementById('voiceCallTimer');
            if (bar) bar.textContent = label;
            const expanded = document.getElementById('voiceCallExpandedTimer');
            if (expanded) expanded.textContent = label;
        };
        tick();
        this.voice.barTimerInterval = setInterval(tick, 1000);
    }

    stopVoiceCallBarTimer() {
        if (this.voice.barTimerInterval) {
            clearInterval(this.voice.barTimerInterval);
            this.voice.barTimerInterval = 0;
        }
    }

    callRecordMessageId(roomId) {
        return `call-${String(roomId || '').trim()}`;
    }

    // Human-readable summary that also goes into `text`. Older clients (and any
    // client that does not understand the structured payload) show this instead of
    // an empty bubble, so the record degrades to a readable line rather than to
    // nothing.
    formatCallSummary(callInfo, direction) {
        const outcome = String(callInfo?.outcome || '').trim();
        const ms = Number(callInfo?.durationMs || 0);
        if (outcome === 'missed') return direction === 'outgoing' ? 'Вызов без ответа' : 'Пропущенный звонок';
        if (outcome === 'rejected') return direction === 'outgoing' ? 'Вызов отклонён' : 'Отклонённый звонок';
        // Written when the client gives up on a call it can no longer recover (every
        // link exhausted, or the room gone from the server). Without its own label it
        // rendered as an ordinary completed call whose duration counted the whole
        // dead stretch — "Исходящий звонок · 8:30" for eight minutes of silence.
        if (outcome === 'failed') {
            if (!ms) return 'Звонок прерван';
            const totalFailed = Math.round(ms / 1000);
            return `Звонок прерван · ${Math.floor(totalFailed / 60)}:${String(totalFailed % 60).padStart(2, '0')}`;
        }
        if (!ms) return direction === 'outgoing' ? 'Исходящий звонок' : 'Входящий звонок';
        const total = Math.round(ms / 1000);
        const mm = Math.floor(total / 60);
        const ss = String(total % 60).padStart(2, '0');
        const label = direction === 'outgoing' ? 'Исходящий звонок' : 'Входящий звонок';
        return `${label} · ${mm}:${ss}`;
    }

    sendCallRecordMessage(message) {
        const peer = String(message?.call?.peer || '').trim();
        if (!peer || !message?.call) return;
        let payload = '';
        try {
            payload = JSON.stringify(message.call);
        } catch (e) {
            return;
        }
        this.enqueuePendingOutbox({
            clientId: message.id,
            sender: this.myName(),
            receiver: peer,
            text: this.formatCallSummary(message.call, message.call.direction),
            call: payload,
            attachments: [],
            timestamp: message.timestamp,
        });
        this.flushPendingOutbox();
    }

    // Incoming counterpart. Direction is derived locally from who sent it rather
    // than trusted from the payload: the sender wrote 'outgoing' from its own point
    // of view, and for the receiver the very same call is incoming.
    parseCallRecordPayload(payload) {
        const raw = String(payload?.call || '').trim();
        if (!raw) return null;
        let parsed = null;
        try {
            parsed = JSON.parse(raw);
        } catch (e) {
            this.trace('parseCallRecordPayload invalid json');
            return null;
        }
        if (!parsed || typeof parsed !== 'object' || !String(parsed.roomId || '').trim()) return null;
        return parsed;
    }

    applyCallRecordMessage(callInfo, payload) {
        const me = String(this.myName() || '').trim();
        const sender = String(payload?.sender || '').trim();
        const receiver = String(payload?.receiver || '').trim();
        const peer = sender === me ? receiver : sender;
        if (!peer) return;
        const direction = sender === me ? 'outgoing' : 'incoming';
        const id = this.callRecordMessageId(callInfo.roomId);
        const message = {
            id,
            clientId: id,
            kind: 'call',
            sender,
            receiver,
            text: '',
            attachments: [],
            timestamp: String(payload?.timestamp || callInfo.endedAt || new Date().toISOString()),
            call: { ...callInfo, peer, direction },
        };
        this.initChat(peer);
        const arr = this.S.chats[peer];
        const index = arr.findIndex(m => String(m.id || '').trim() === id
            || String(m.clientId || '').trim() === id);
        if (index >= 0) arr[index] = { ...arr[index], ...message };
        else arr.push(message);
        arr.sort((a, b) => this.compareMessagesByTime(a, b));
        this.saveStoredMessageCache();
        this.trace(`applyCallRecordMessage peer=${peer} direction=${direction} roomId=${callInfo.roomId}`);
        this.renderContacts();
        if (this.S.navMode === 'dm' && this.S.current === peer) this.scheduleRenderMessages();
    }

    recordVoiceCallHistory({ outcome = 'completed', endedAt = Date.now() } = {}) {
        const call = this.voice.callTrack;
        if (!call || call.recorded || call.roomType === 'channel') return;
        const peer = String(call.peer || this.voice.targetUser || this.voice.inviter || '').trim();
        if (!peer) return;
        const direction = String(call.direction || '').trim() || 'outgoing';
        const startMs = Number(call.connectedAt || call.startedAt || endedAt) || endedAt;
        const endMs = Number(endedAt || Date.now()) || Date.now();
        const durationMs = Math.max(0, endMs - startMs);
        const message = {
            // Stable across both participants and all their devices: the room id
            // identifies one call, so the local row and the one that arrives over the
            // wire collapse into a single entry instead of duplicating.
            id: this.callRecordMessageId(call.roomId || `${peer}-${endMs}`),
            kind: 'call',
            sender: direction === 'outgoing' ? this.myName() : peer,
            receiver: direction === 'outgoing' ? peer : this.myName(),
            text: '',
            attachments: [],
            timestamp: new Date(endMs).toISOString(),
            call: {
                roomId: call.roomId || '',
                peer,
                direction,
                outcome,
                startedAt: new Date(startMs).toISOString(),
                connectedAt: call.connectedAt ? new Date(call.connectedAt).toISOString() : '',
                endedAt: new Date(endMs).toISOString(),
                durationMs,
            },
        };
        const convo = peer;
        this.initChat(convo);
        const arr = this.S.chats[convo];
        // Dedupe on the room-derived id, not on a rendered-content key: the same call
        // can be written here locally AND arrive over the wire from the other side,
        // and those two differ in text and sender casing while being the same call.
        const existingIndex = arr.findIndex(m => String(m.id || '').trim() === message.id
            || String(m.clientId || '').trim() === message.id);
        if (existingIndex >= 0) {
            arr[existingIndex] = { ...arr[existingIndex], ...message };
        } else {
            arr.push(message);
            arr.sort((a, b) => this.compareMessagesByTime(a, b));
        }
        call.recorded = true;
        this.voice.callTrack = null;
        this.saveStoredMessageCache();
        // The caller owns the record and is the one that sends it, so exactly one
        // copy travels. The callee keeps its local row for instant feedback and lets
        // the incoming copy upsert onto the same id. Until this existed the record
        // was never sent anywhere at all: it lived only in this device's cache, so
        // neither the peer nor the account's own other devices ever saw it.
        if (direction === 'outgoing') {
            this.sendCallRecordMessage(message);
        }
        this.renderContacts();
        if (this.S.navMode === 'dm' && this.S.current === convo) {
            this.scheduleRenderMessages();
        }
    }
});


// --- MODULE: interface/voice_signal.js ---
// --- ZaliInterface: Обработка входящих voice_* сигналов и событий. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    // handleVoiceEvent is dispatched fire-and-forget from both sockets, so signal
    // application used to interleave freely across its awaits (ensureVoiceLocalStream,
    // setRemoteDescription, createAnswer). With one peer that is mostly survivable;
    // in a group call every extra participant multiplies the traffic and two signals
    // for the SAME peer routinely overlapped — an ICE candidate reading
    // `pc.remoteDescription` as null mid-way through the offer handler got queued
    // into pendingIceCandidates *after* flushPendingVoiceIceCandidates had already
    // drained it, so those candidates sat there forever and that one pair never
    // completed ICE. Chain per peer: different peers still negotiate in parallel
    // (a blocked mic prompt for one must not stall the rest), signals for the same
    // peer apply strictly in order.
    async handleVoiceSignal(signal = {}) {
        const peer = String(signal.from || signal.sender || '').trim();
        if (!peer) return;
        const chains = this.voice.signalChains || (this.voice.signalChains = new Map());
        const previous = chains.get(peer) || Promise.resolve();
        const result = previous.then(() => this.applyVoiceSignal(signal));
        // The stored tail swallows rejections so one failed signal can't poison
        // every later signal from that peer; the caller still sees the real result.
        const tail = result.catch(() => {});
        chains.set(peer, tail);
        try {
            return await result;
        } finally {
            // Drop the entry once this was the last queued signal, so a long-lived
            // room doesn't retain a promise per peer that ever spoke to us.
            if (chains.get(peer) === tail) chains.delete(peer);
        }
    }

    async applyVoiceSignal(signal = {}) {
        const roomId = String(signal.roomId || '').trim();
        const from = String(signal.from || signal.sender || '').trim();
        const signalPayload = signal.signal || signal.payload || signal;
        if (!roomId || !from || !signalPayload) return;
        // Signals were applied no matter which room they belonged to, and the offer
        // branch below writes roomId/roomType/targetUser/inviter straight from the
        // signal — so one late offer/ICE packet from a room we already left (a
        // cancelled invite, a call the peer restarted) re-pointed the live session at
        // a dead room and killed the call in progress. Only the room we are actually
        // in may drive negotiation.
        const currentRoomId = String(this.voice.roomId || '').trim();
        if (currentRoomId && roomId !== currentRoomId) {
            this.voiceTrace('signal-foreign-room', {
                roomId,
                currentRoomId,
                from,
                signalType: signalPayload.type || '',
            }, 'WARN');
            return;
        }
        this.voiceTrace('signal-recv', {
            roomId,
            from,
            to: signal.to || '',
            signalType: signalPayload.type || '',
            roomType: signal.roomType || this.voice.roomType || '',
        });

        // Nothing may be negotiated into a call that has not been answered yet.
        //
        // The offer branch below captures the microphone (awaitVoiceLocalStream →
        // getUserMedia), attaches the local audio track and replies with a sendrecv
        // answer. It did that regardless of whether the user had accepted, and the
        // server permits an invite's initiator to send voice_signal into their own
        // ringing room — so a caller running a modified client could ring a contact
        // and be listening to them before the phone was answered, with the panel
        // flipping from «входящий звонок» to «connecting» as the only tell.
        //
        // The legitimate flow never lands here: the caller offers only once
        // voice_call_accepted has arrived, and by then this side set 'connecting'
        // inside performAcceptIncomingCall. So refusing outright costs nothing and
        // needs no queue — after the accept, syncVoicePeers negotiates from scratch.
        if (String(this.voice.status || '') === 'incoming') {
            this.voiceDiag('signal-before-accept-refused', {
                roomId,
                from,
                signalType: signalPayload.type || '',
                status: this.voice.status || '',
            }, 'WARN');
            return;
        }

        // Nor into a call this client is not in at all.
        //
        // Voice signals are addressed by USERNAME, and the server delivers every
        // one of them to all of that account's connections — so the second device
        // of an account whose first device answered a call receives the same offers.
        // With no room state of its own it used to sail through this handler,
        // capture its microphone and answer, and the caller then had two answers for
        // one offer with only the first applied: whichever device replied first won
        // the call, non-deterministically, and the other sat in a half-built session.
        //
        // Every legitimate path into a call sets roomId before any negotiation can
        // begin — startDirectCall, performAcceptIncomingCall, joinVoiceChannel and
        // the room-state snapshot the server sends on every WS connect — so an empty
        // roomId here means this client is not a participant. Fixing the underlying
        // ambiguity properly needs a device dimension in the signalling protocol
        // (see CLAUDE.md); this only stops a bystander device from answering.
        //
        // Worst case if a snapshot ever lost a race with the first offer: that offer
        // is refused once and the peer's answer watchdog re-offers 8 s later, with
        // this line in the log to say what happened.
        if (!currentRoomId) {
            this.voiceDiag('signal-outside-call-refused', {
                roomId,
                from,
                signalType: signalPayload.type || '',
                status: this.voice.status || '',
            }, 'WARN');
            return;
        }

        if (signalPayload.type === 'offer') {
            // A peer that was evicted and re-joined (or simply gave up on this link)
            // builds a brand-new RTCPeerConnection, so its offer carries new ICE
            // credentials and a new DTLS fingerprint. Feeding that to a pc whose
            // transport already died never recovers — the returning participant
            // stayed silently outside the call while everyone else reconnected fine.
            // Rebuild instead of trying to revive a terminal connection.
            const stale = this.voice.peerConnections.get(from);
            if (stale && (stale.pc.connectionState === 'failed' || stale.pc.signalingState === 'closed')) {
                this.voiceDiag('offer-on-dead-peer-rebuild', {
                    roomId,
                    from,
                    state: stale.pc.connectionState,
                    signaling: stale.pc.signalingState,
                }, 'WARN');
                this.countVoicePeerRebuild(from, 'dead-transport');
                this.closeVoicePeer(from);
            }
            let entry = this.getVoicePeerEntry(from);
            // Mid-call renegotiation (camera/screen-share toggles) means either
            // side can now send an offer at any time, not just once at call
            // setup — so two peers toggling near-simultaneously can each have a
            // local offer outstanding when the other's offer arrives ("glare").
            // A bare setRemoteDescription(offer) in that state throws. Resolve it
            // with a minimal polite/impolite split (mirrors shouldInitiateVoiceOffer's
            // tie-break): the polite side rolls back its own offer and accepts the
            // incoming one; the impolite side ignores the incoming offer and waits
            // for its own outgoing offer to be answered instead.
            const offerCollision = entry.pc.signalingState !== 'stable';
            if (offerCollision && !this.isPoliteVoicePeer(from)) {
                // We own the offer for this pair, so we keep it and let the peer
                // answer. Re-drive negotiation anyway: dropping an offer is only
                // safe while ours is genuinely still in flight, and if the answer
                // never arrives nothing else would ever notice.
                this.voiceDiag('offer-collision-ignored', { roomId, from, state: entry.pc.signalingState }, 'WARN');
                this.scheduleVoiceNegotiationRetry('offer-collision-ignored');
                return;
            }
            // We are going to accept this offer, so the connection has to be in a
            // state that can actually take one. 'stable' can; 'have-local-offer' can
            // once we roll our own offer back. Every other non-stable state
            // ('have-remote-offer', the pranswer pair) cannot — setRemoteDescription
            // throws InvalidStateError from there, and the old code walked straight
            // into it via an `else if (offerCollision)` branch that logged
            // "offer-collision-no-rollback" and carried on regardless.
            //
            // That is the failure in the production log, on three separate calls:
            //   ERROR [VOICE] offer-apply-error ... error=The object is in an invalid state.
            // The throw aborted the block before createAnswer(), so no answer was ever
            // built or sent, and the caller sat in have-local-offer until its watchdog
            // gave up — the matching "answer-never-arrived attempt=1/2" on the other side.
            //
            // A connection wedged in a state that cannot take an offer holds nothing
            // worth preserving, so rebuild it and let the offer land on a fresh
            // 'stable' one. Same reasoning as the dead-transport rebuild above.
            if (offerCollision && entry.pc.signalingState !== 'have-local-offer') {
                this.voiceTrace('offer-unapplicable-rebuild', {
                    roomId,
                    from,
                    state: entry.pc.signalingState,
                }, 'WARN');
                this.countVoicePeerRebuild(from, 'unapplicable-offer');
                this.closeVoicePeer(from);
                entry = this.getVoicePeerEntry(from);
            }
            this.voice.roomId = roomId;
            this.voice.roomType = signal.roomType || this.voice.roomType || 'dm';
            this.voice.serverId = signal.serverId || this.voice.serverId || '';
            this.voice.channelId = signal.channelId || this.voice.channelId || '';
            this.voice.targetUser = signal.target || this.voice.targetUser || '';
            this.voice.inviter = signal.from || this.voice.inviter || '';
            // Only downgrade to 'connecting' for the initial call setup offer.
            // Camera/screen-share toggles send a fresh offer to an already-
            // connected peer too (mid-call renegotiation) — RTCPeerConnection's
            // connectionState doesn't change for that (no ICE restart), so
            // onconnectionstatechange never fires again to bring status back to
            // 'connected'. Downgrading here unconditionally used to leave the
            // call stuck showing "connecting" after the very first toggle.
            if (this.voice.status !== 'connected') {
                this.voice.status = 'connecting';
            }
            // Answering is a negotiation too, and it holds the same latch offers use.
            // Per-peer signal chaining orders incoming signals, but syncVoicePeers is
            // driven independently by voice_room_state — which in a group call fires
            // on every join/leave. Without this, a sync landing in the window between
            // ensureVoiceLocalStream() and setRemoteDescription() still saw 'stable'
            // and sent its own offer, and the setRemoteDescription that followed threw
            // InvalidStateError, leaving that one link unnegotiated.
            entry.negotiating = true;
            try {
                // 'have-local-offer' is the only state a rollback is legal from.
                // Attempting it from any other non-stable state throws, and that
                // exception used to abort the whole block — so the answer this peer
                // was waiting for was never created or sent.
                // The only non-stable state that can still reach here: anything else
                // was rebuilt above, so there is no longer a path that tries to apply
                // an offer to a connection that cannot take one.
                if (entry.pc.signalingState === 'have-local-offer') {
                    this.voiceDiag('offer-collision-rollback', { roomId, from, state: entry.pc.signalingState }, 'WARN');
                    await entry.pc.setLocalDescription({ type: 'rollback' });
                }
                try {
                    // Bounded on purpose. getUserMedia() stays pending for as long as
                    // the permission dialog is open, and this await sits in front of
                    // the ANSWER — so while the callee reads that dialog the caller is
                    // not heard either, although receiving audio needs no permission
                    // whatsoever. Answering recvonly first turns "both sides silent
                    // until the dialog is dismissed" into "audible one way at once,
                    // both ways as soon as the mic lands". Well under the peer's 8 s
                    // answer watchdog, so the answer still arrives before it gives up.
                    if (!await this.awaitVoiceLocalStream(4000)) {
                        this.voiceDiag('answering-before-mic-ready', { roomId, from }, 'WARN');
                        this.scheduleVoiceNegotiationRetry('offer-before-mic-ready');
                    }
                } catch (error) {
                    this.addLogEntry({ type: 'WARN', msg: error?.message || 'Не удалось получить доступ к микрофону', ts: new Date().toLocaleTimeString() });
                    // Answering without local tracks produces a recvonly answer; retry
                    // so the mic can still join the call once it becomes available.
                    this.scheduleVoiceNegotiationRetry('offer-without-mic');
                }
                await this.attachLocalVoiceTracks(from);
                this.voiceDiag('signal-offer-apply', { roomId, from, localStream: !!this.voice.localStream, sdpLength: signalPayload.sdp?.sdp?.length || 0, ...this.voicePeerSnapshot(from) });
                try {
                    await entry.pc.setRemoteDescription(signalPayload.sdp);
                } catch (error) {
                    if (!this.isVoiceSessionShapeError(error)) throw error;
                    // The offer is fine; this connection's established media layout
                    // is what refuses it, and only a connection without one can
                    // accept it. Seen in production on 2026-08-03 in a channel call:
                    // the same offer failed twice in three seconds and the link went
                    // to 'disconnected' — the generic recovery below just re-armed a
                    // negotiation that replayed the identical mismatch.
                    this.voiceDiag('offer-sdp-shape-rebuild', {
                        roomId,
                        from,
                        error: error?.message || String(error),
                    }, 'WARN');
                    this.countVoicePeerRebuild(from, 'offer-sdp-shape');
                    this.closeVoicePeer(from);
                    entry = this.getVoicePeerEntry(from);
                    // The fresh entry needs the latch the old one was holding, or a
                    // syncVoicePeers pass landing in the awaits below sees 'stable'
                    // and starts offering into the middle of this answer.
                    entry.negotiating = true;
                    await this.attachLocalVoiceTracks(from);
                    await entry.pc.setRemoteDescription(signalPayload.sdp);
                }
                await this.flushPendingVoiceIceCandidates(entry, from);
                const answer = await entry.pc.createAnswer();
                await entry.pc.setLocalDescription(answer);
                this.voiceDiag('signal-answer-send', {
                    roomId,
                    from,
                    peer: from,
                    localDesc: entry.pc.localDescription?.type || 'answer',
                    sdpLength: entry.pc.localDescription?.sdp?.length || 0,
                });
                this.sendVoiceEvent({
                    type: 'voice_signal',
                    roomId,
                    roomType: this.voice.roomType,
                    serverId: this.voice.serverId,
                    channelId: this.voice.channelId,
                    to: from,
                    signal: {
                        type: 'answer',
                        sdp: {
                            type: entry.pc.localDescription?.type || 'answer',
                            sdp: entry.pc.localDescription?.sdp || '',
                        },
                    },
                });
                this.voice.participants = Array.from(new Set([this.myName(), from].concat(this.voice.participants || [])));
                if (offerCollision) {
                    // Rolling back discarded whatever WE were offering (a freshly
                    // added camera/screen track, an ICE restart) — the answer we just
                    // sent describes the peer's offer, not our pending change, so
                    // without re-offering, that change never reaches this peer.
                    this.voiceTrace('offer-collision-requeue', { roomId, from }, 'WARN');
                    entry.renegotiationPending = true;
                }
            } catch (error) {
                this.voiceDiag('offer-apply-error', { roomId, from, error: error?.message || String(error) }, 'ERROR');
                this.addLogEntry({ type: 'WARN', msg: error?.message || `Не удалось применить предложение звонка от ${from}`, ts: new Date().toLocaleTimeString() });
                // Recover, don't just report. Failing here means no answer was sent,
                // so this link is silent — and nothing else was watching it: the
                // answer watchdog only supervises offers WE sent, and the peer's own
                // retries land back in whatever state broke this attempt. The answer
                // branch below has had this recovery all along; the offer branch
                // ending in a bare log is why a single bad apply killed a call for
                // good instead of costing it one negotiation round.
                entry.offerSent = false;
                this.scheduleVoiceNegotiationRetry('offer-apply-failed');
            } finally {
                entry.negotiating = false;
                // onsignalingstatechange already fired for the answer while the latch
                // was still held, so it skipped the drain — do it here instead, or a
                // requeued renegotiation would sit until some unrelated state change.
                if (entry.renegotiationPending && entry.pc.signalingState === 'stable') {
                    entry.renegotiationPending = false;
                    this.renegotiateVoicePeer(from).catch(() => {});
                }
            }
            this.renderVoicePanel();
            return;
        }

        const entry = this.getVoicePeerEntry(from);
        if (signalPayload.type === 'answer') {
            // An answer is only applicable to an offer we still have outstanding.
            // Applying one in any other signaling state throws InvalidStateError —
            // and this used to be an unguarded await inside an async handler, so the
            // rejection aborted the rest of handleVoiceEvent and surfaced as an
            // unhandled rejection instead of a recoverable call. It happens for real:
            // a rolled-back offer (glare) or a peer that restarted its connection
            // leaves us 'stable' while its answer is still in flight.
            if (entry.pc.signalingState !== 'have-local-offer') {
                this.voiceDiag('signal-answer-ignored', {
                    roomId,
                    from,
                    state: entry.pc.signalingState,
                }, 'WARN');
                return;
            }
            this.voiceDiag('signal-answer-apply', {
                roomId,
                from,
                peer: from,
                remoteDesc: !!signalPayload.sdp,
                sdpType: signalPayload.sdp?.type || '',
                sdpLength: signalPayload.sdp?.sdp?.length || 0,
            });
            try {
                await entry.pc.setRemoteDescription(signalPayload.sdp);
                this.clearVoiceAnswerWatchdog(entry);
                // The budget is per stuck negotiation, not per call: a link that
                // answers again has proved it is alive, so a later loss gets the
                // full set of retries rather than the remainder of an old one.
                entry.answerRetries = 0;
                await this.flushPendingVoiceIceCandidates(entry, from);
                this.voice.status = 'connected';
            } catch (error) {
                this.voiceDiag('answer-apply-error', { roomId, from, error: error?.message || String(error) }, 'ERROR');
                if (this.isVoiceSessionShapeError(error)) {
                    // Same immutable-layout dead end as the offer branch, reached
                    // from the other side: our next offer would be built from the
                    // very layout the peer just refused to match, so the retry
                    // needs a connection that carries no layout at all.
                    this.voiceDiag('answer-sdp-shape-rebuild', { roomId, from }, 'WARN');
                    this.countVoicePeerRebuild(from, 'answer-sdp-shape');
                    this.closeVoicePeer(from);
                } else {
                    // The offer is dead — clear the latch so the negotiation retry below
                    // can produce a fresh one instead of leaving a mute call standing.
                    entry.offerSent = false;
                }
                this.scheduleVoiceNegotiationRetry('answer-apply-failed');
            }
            this.renderVoicePanel();
            return;
        }

        if (signalPayload.type === 'screen-meta') {
            if (signalPayload.action === 'start' && signalPayload.streamId) {
                entry.remoteScreenStreamId = String(signalPayload.streamId);
                // This id-announcement and the SDP offer carrying the actual
                // track are two independent signals — if ontrack already fired
                // before this arrived, the stream was filed as camera video
                // (attachRemoteVoiceStream) for lack of an id to match. Re-route
                // it now instead of leaving it stuck in the camera bubble.
                const misfiledVideo = this.voice.remoteVideos.get(from);
                if (misfiledVideo?.srcObject && misfiledVideo.srcObject.id === entry.remoteScreenStreamId) {
                    const misroutedStream = misfiledVideo.srcObject;
                    this.voice.remoteVideos.delete(from);
                    try { misfiledVideo.pause?.(); misfiledVideo.srcObject = null; misfiledVideo.remove?.(); } catch (e) {}
                    this.attachRemoteScreenStream(from, misroutedStream);
                }
                this.voiceTrace('screen-meta-start', { roomId, from, streamId: entry.remoteScreenStreamId });
            } else if (signalPayload.action === 'stop') {
                entry.remoteScreenStreamId = null;
                this.detachRemoteScreenStream(from);
                this.voiceTrace('screen-meta-stop', { roomId, from });
            }
            this.renderVoicePanel();
            return;
        }

        if (signalPayload.type === 'ice' && signalPayload.candidate) {
            try {
                entry.receivedIceCandidates = (entry.receivedIceCandidates || 0) + 1;
                const candidateInfo = this.describeIceCandidate(signalPayload.candidate.candidate || '');
                this.voiceTrace('signal-ice-recv', {
                    roomId,
                    from,
                    peer: from,
                    count: entry.receivedIceCandidates,
                    candidateType: candidateInfo.type,
                    protocol: candidateInfo.protocol,
                    address: candidateInfo.address,
                });
                if (entry.pc.remoteDescription) {
                    this.voiceTrace('signal-ice-apply', { roomId, from, peer: from, queued: false });
                    await entry.pc.addIceCandidate(signalPayload.candidate);
                } else {
                    entry.pendingIceCandidates = entry.pendingIceCandidates || [];
                    entry.pendingIceCandidates.push(signalPayload.candidate);
                    this.voiceTrace('signal-ice-queue', { roomId, from, peer: from, queued: true, queueSize: entry.pendingIceCandidates.length });
                }
            } catch (e) {
                console.warn('Failed to add ICE candidate', e);
                this.voiceTrace('signal-ice-error', { roomId, from, peer: from, error: e?.message || String(e) }, 'WARN');
            }
        }
    }

    // De-duplicates voice_* events that may now legitimately arrive twice — once
    // over the dedicated voice WebSocket, once over the more reliable main
    // message socket's fallback forwarding (see voiceEventPayload). Keeps a
    // small bounded window of recently-seen vids rather than growing forever.
    isDuplicateVoiceEvent(vid) {
        const id = String(vid || '').trim();
        if (!id) return false;
        const seen = this.voice.recentEventIds || (this.voice.recentEventIds = new Map());
        const now = Date.now();
        for (const [key, ts] of seen) {
            if (now - ts > 60000) seen.delete(key);
        }
        if (seen.has(id)) return true;
        seen.set(id, now);
        return false;
    }

    async handleVoiceEvent(payload = {}) {
        const eventType = String(payload?.type || '').trim();
        if (!eventType) return;
        if (this.isDuplicateVoiceEvent(payload.vid)) {
            this.voiceTrace('event-dedup', { eventType, vid: payload.vid || '' }, 'INFO');
            return;
        }
        this.voiceTrace('event-recv', {
            eventType,
            roomId: payload.roomId || '',
            roomType: payload.roomType || '',
            from: payload.from || '',
            target: payload.target || '',
        });

        if (eventType === 'voice_call_invite') {
            const from = String(payload.from || '').trim();
            const roomId = String(payload.roomId || '').trim();
            // Busy guard: an invite used to overwrite voice state unconditionally —
            // an incoming call from a third user mid-call clobbered callTrack /
            // incomingInvite and flipped the UI to "входящий звонок", killing the
            // active call's state (the RTCPeerConnections kept running headless).
            // Auto-reject instead; the server allows the target of a ringing room
            // to reject it, so the caller gets a normal voice_call_rejected.
            const activeRoomId = String(this.voice.roomId || '').trim();
            // Mutual invite is GLARE, not "busy". isInActiveCall() counts 'calling'
            // and 'incoming', so a merely ringing invite made us auto-reject anything
            // arriving — including the invite from the very person we were calling.
            // Both sides do it at once, both rooms die, and nobody ever answers: the
            // production log for 2026-08-02 shows 15 invites, 124 rejects and zero
            // answers for exactly this. It needs only both people to tap «Позвонить»
            // in the same few seconds, which is precisely what they do when a call
            // did not connect the first time.
            //
            // Resolve it the same way SDP glare is resolved — one deterministic owner
            // (compareVoicePeerNames is engine-independent, unlike localeCompare) —
            // and never reject: rejecting tears down the peer's room too, so the pair
            // ends up with no call at all instead of one.
            const activePeer = String(this.voice.targetUser || this.voice.inviter || '').trim();
            const samePeer = !!from && !!activePeer && from.toLowerCase() === activePeer.toLowerCase();
            const ringing = this.voice.status === 'calling' || this.voice.status === 'incoming';
            if (activeRoomId && activeRoomId !== roomId && samePeer && ringing) {
                const iOwnTheCall = this.compareVoicePeerNames(this.myName(), from) < 0;
                if (iOwnTheCall && this.voice.status === 'calling') {
                    // Keep our own invite; the peer drops theirs and answers ours.
                    this.voiceDiag('invite-glare-keep-ours', {
                        roomId, from, activeRoomId, status: this.voice.status,
                    }, 'WARN');
                    return;
                }
                // We do not own it: withdraw our invite and let theirs be the call.
                this.voiceDiag('invite-glare-adopt-theirs', {
                    roomId, from, activeRoomId, status: this.voice.status,
                }, 'WARN');
                const ourInvite = String(this.voice.outgoingInvite?.roomId || activeRoomId || '').trim();
                if (ourInvite && ourInvite !== roomId) {
                    this.sendVoiceEvent({
                        type: 'voice_call_cancel',
                        roomId: ourInvite,
                        target: from,
                    });
                    // Our own voice_call_outgoing / room_state for the withdrawn room
                    // are usually still in flight and would drag us back to 'calling',
                    // undoing the adoption a moment after it happened.
                    this.abandonVoiceRoom(ourInvite);
                }
                this.voice.outgoingInvite = null;
                // Fall through: the incoming invite below becomes the live call.
            } else if (activeRoomId && activeRoomId !== roomId && this.isInActiveCall()) {
                this.voiceTrace('incoming-invite-busy', { roomId, from, activeRoomId, status: this.voice.status }, 'WARN');
                this.sendVoiceEvent({
                    type: 'voice_call_reject',
                    roomId,
                    inviter: from,
                });
                this.addLogEntry({ type: 'INFO', msg: `Входящий звонок от ${from} отклонён: уже идёт другой звонок`, ts: new Date().toLocaleTimeString() });
                return;
            }
            this.voice.incomingInvite = {
                roomId,
                from,
                roomType: 'dm',
            };
            this.voice.inviter = from;
            this.voice.callTrack = {
                roomId,
                peer: from,
                roomType: 'dm',
                direction: 'incoming',
                startedAt: Date.now(),
                connectedAt: 0,
                endedAt: 0,
                outcome: 'incoming',
                recorded: false,
            };
            this.voice.outgoingInvite = null;
            this.voice.status = 'incoming';
            this.voiceTrace('incoming-invite', { roomId, from });
            this.renderVoicePanel();
            return;
        }

        if (eventType === 'voice_call_outgoing') {
            if (this.isAbandonedVoiceRoom(payload.roomId)) {
                this.voiceDiag('outgoing-ring-ignored-abandoned', { roomId: payload.roomId || '' }, 'WARN');
                return;
            }
            this.voice.outgoingInvite = {
                roomId: String(payload.roomId || '').trim(),
                target: String(payload.target || '').trim(),
            };
            this.voice.targetUser = String(payload.target || '').trim();
            this.voice.status = 'calling';
            this.voiceTrace('outgoing-ring', { roomId: this.voice.outgoingInvite.roomId, target: this.voice.targetUser });
            this.renderVoicePanel();
            return;
        }

        if (eventType === 'voice_signal') {
            this.voiceTrace('signal-event', {
                roomId: payload.roomId || '',
                from: payload.from || payload.sender || '',
                to: payload.to || '',
                signalType: payload.signal?.type || payload.payload?.type || '',
            });
            await this.handleVoiceSignal(payload);
            return;
        }

        if (eventType === 'voice_call_rejected') {
            if (this.voice.outgoingInvite?.roomId === String(payload.roomId || '').trim()) {
                this.voiceTrace('outgoing-rejected', { roomId: payload.roomId || '', from: payload.from || '' }, 'WARN');
                this.recordVoiceCallHistory({ outcome: 'rejected', endedAt: Date.now() });
                this.resetVoiceState({ preserveInvite: false });
            }
            return;
        }

        if (eventType === 'voice_call_cancelled') {
            if (this.voice.incomingInvite?.roomId === String(payload.roomId || '').trim()) {
                this.voiceTrace('incoming-cancelled', { roomId: payload.roomId || '', from: payload.from || '' }, 'WARN');
                this.recordVoiceCallHistory({ outcome: 'cancelled', endedAt: Date.now() });
                this.resetVoiceState({ preserveInvite: false });
            }
            return;
        }

        if (eventType === 'voice_call_missed') {
            const roomId = String(payload.roomId || '').trim();
            if (this.voice.incomingInvite?.roomId === roomId || this.voice.outgoingInvite?.roomId === roomId) {
                this.voiceTrace('call-missed', { roomId, from: payload.from || '', target: payload.target || '' }, 'WARN');
                this.recordVoiceCallHistory({ outcome: 'missed', endedAt: Date.now() });
                this.resetVoiceState({ preserveInvite: false });
            }
            return;
        }

        if (eventType === 'voice_call_accepted') {
            const roomId = String(payload.roomId || '').trim();
            const me = String(this.myName() || '').trim();
            const from = String(payload.from || '').trim();
            const target = String(payload.target || '').trim();
            const remotePeer = from && from !== me ? from : target;
            const callOwner = target || this.voice.inviter || '';
            const participants = Array.isArray(payload.participants)
                ? payload.participants.map(name => String(name || '').trim()).filter(Boolean)
                : [payload.from, payload.target].map(name => String(name || '').trim()).filter(Boolean);
            this.voice.roomId = roomId || this.voice.roomId;
            this.voice.roomType = 'dm';
            this.voice.targetUser = remotePeer || this.voice.targetUser || '';
            this.voice.inviter = callOwner || this.voice.inviter || '';
            this.voice.participants = participants.length ? participants : this.voice.participants;
            this.voice.status = 'connected';
            if (roomId && String(this.voice.outgoingInvite?.roomId || '').trim() === roomId) {
                this.voice.outgoingInvite = null;
            }
            if (roomId && String(this.voice.incomingInvite?.roomId || '').trim() === roomId) {
                this.voice.incomingInvite = null;
            }
            this.voiceTrace('call-accepted', { roomId, from, target, participants });
            if (this.voice.callTrack) {
                this.voice.callTrack.connectedAt = this.voice.callTrack.connectedAt || Date.now();
                this.voice.callTrack.outcome = 'connected';
            }
            this.renderVoicePanel();
            try {
                await this.ensureVoiceLocalStream();
            } catch (error) {
                this.addLogEntry({ type: 'WARN', msg: error?.message || 'Не удалось получить доступ к микрофону', ts: new Date().toLocaleTimeString() });
            }
            await this.syncVoicePeers();
            return;
        }

        if (eventType === 'voice_call_connected') {
            const roomId = String(payload.roomId || '').trim();
            const me = String(this.myName() || '').trim();
            const from = String(payload.from || '').trim();
            const target = String(payload.target || '').trim();
            const remotePeer = from && from !== me ? from : target;
            const callOwner = target || this.voice.inviter || '';
            const participants = Array.isArray(payload.participants)
                ? payload.participants.map(name => String(name || '').trim()).filter(Boolean)
                : [payload.from, payload.target].map(name => String(name || '').trim()).filter(Boolean);
            this.voice.roomId = roomId || this.voice.roomId;
            this.voice.roomType = 'dm';
            this.voice.targetUser = remotePeer || this.voice.targetUser || '';
            this.voice.inviter = callOwner || this.voice.inviter || '';
            this.voice.participants = participants.length ? participants : this.voice.participants;
            this.voice.status = 'connected';
            if (roomId && String(this.voice.outgoingInvite?.roomId || '').trim() === roomId) {
                this.voice.outgoingInvite = null;
            }
            if (roomId && String(this.voice.incomingInvite?.roomId || '').trim() === roomId) {
                this.voice.incomingInvite = null;
            }
            this.voiceTrace('call-connected', { roomId, from, target, participants }, 'SUCCESS');
            if (this.voice.callTrack) {
                this.voice.callTrack.connectedAt = this.voice.callTrack.connectedAt || Date.now();
                this.voice.callTrack.outcome = 'connected';
            }
            this.renderVoicePanel();
            try {
                await this.ensureVoiceLocalStream();
            } catch (error) {
                this.addLogEntry({ type: 'WARN', msg: error?.message || 'Не удалось получить доступ к микрофону', ts: new Date().toLocaleTimeString() });
            }
            await this.syncVoicePeers();
            return;
        }

        if (eventType === 'voice_error') {
            const code = String(payload.code || '').trim();
            const errorRoomId = String(payload.roomId || '').trim();
            this.voiceDiag('server-error', {
                code: code || '(none)',
                roomId: errorRoomId,
                currentRoomId: this.voice.roomId || '',
                status: this.voice.status || '',
                message: String(payload.message || ''),
            }, 'ERROR');
            this.addLogEntry({
                type: 'ERROR',
                msg: String(payload.message || 'Ошибка voice'),
                ts: new Date().toLocaleTimeString(),
            });
            // The server has no record of the room we believe we are in. Nothing can
            // be signalled into it any more — not an ICE restart, not a re-offer — so
            // the call is finished whatever the panel still shows. Matched on `code`,
            // never on the human-readable message, which is Russian prose that a
            // wording change would silently detach this from.
            if (code === 'room_not_found') {
                this.concludeVanishedVoiceRoom(errorRoomId, String(payload.message || ''));
            }
            return;
        }

        // Emitted by the native shells (macOS NetworkService, Windows
        // run_voice_transport), not by the server: the voice WebSocket lives inside
        // Swift/Rust and reconnects there, and JS never learned that it had happened.
        // The cost of not knowing was up to 8 s of being a ghost — evicted from the
        // room server-side, with the presence keepalive the only thing that would
        // eventually notice. Re-assert membership the instant the link is back, and
        // re-drive negotiation, since any signal sent while it was down is gone.
        if (eventType === 'voice_transport_state') {
            const state = String(payload.state || '').trim();
            this.voiceDiag('transport-state', {
                state,
                reason: String(payload.reason || ''),
                roomId: this.voice.roomId || '',
                status: this.voice.status || '',
                queued: payload.queued ?? '',
            }, state === 'up' ? 'INFO' : 'WARN');
            if (state === 'up' && String(this.voice.roomId || '').trim()) {
                this.sendVoiceRoomPresence();
                this.scheduleVoiceNegotiationRetry('voice-transport-reconnected');
            }
            return;
        }

        // A payload the shell could not deliver and will not retry (its outbound
        // queue overflowed, or the payload could not be serialised). On the browser
        // path sendVoiceEvent returns false and the caller unlatches offerSent
        // itself; over a native bridge the send is fire-and-forget, so this event is
        // the only way that failure ever becomes visible here.
        if (eventType === 'voice_send_failed') {
            const failedType = String(payload.eventType || '').trim();
            const failedSignal = String(payload.signalType || '').trim();
            const target = String(payload.to || '').trim();
            this.voiceDiag('transport-send-failed', {
                eventType: failedType,
                signalType: failedSignal,
                to: target,
                reason: String(payload.reason || ''),
                roomId: this.voice.roomId || '',
            }, 'WARN');
            const entry = target ? this.voice.peerConnections.get(target) : null;
            if (entry && failedType === 'voice_signal' && failedSignal === 'offer') {
                // Same reasoning as the browser path's `!delivered` branch: an offer
                // that never left the client must not stay latched as sent, or
                // syncVoicePeers skips this peer for the rest of the call. Only an
                // OFFER, though — a dropped ICE candidate leaves the offer perfectly
                // valid, and unlatching it there just forces a pointless
                // renegotiation on a link that is still converging.
                entry.offerSent = false;
            }
            this.scheduleVoiceNegotiationRetry('transport-send-failed');
            return;
        }

        if (eventType === 'voice_room_state') {
            const roomId = String(payload.roomId || '').trim();
            if (this.isAbandonedVoiceRoom(roomId)) {
                this.voiceDiag('room-state-ignored-abandoned', { roomId }, 'WARN');
                return;
            }
            const roomStatus = String(payload.status || '').trim().toLowerCase();
            const roomInitiator = String(payload.initiator || '').trim();
            const roomTarget = String(payload.target || '').trim();
            const participants = Array.isArray(payload.participants) ? payload.participants.map(name => String(name || '').trim()).filter(Boolean) : [];
            const currentRoomId = String(this.voice.roomId || '').trim();
            // Foreign-room guard for ANY active call, not just dm→dm: a user sitting in
            // a channel voice room is made a participant of a new ringing DM room the
            // moment someone invites them, so the broadcastVoiceRoomState for that new
            // room arrives here and used to overwrite roomId/participants/status of the
            // channel session. Only room states for the room we are actually in may
            // mutate live call state while a call is in progress.
            const inActiveCall = this.isInActiveCall();
            if (currentRoomId && roomId && roomId !== currentRoomId && (this.voice.roomType === 'dm' || inActiveCall)) {
                this.voiceTrace('room-state-stale', { roomId, currentRoomId }, 'INFO');
                return;
            }
            this.voice.roomId = roomId;
            this.voice.roomType = String(payload.roomType || this.voice.roomType || '').trim();
            this.voice.serverId = String(payload.serverId || this.voice.serverId || '').trim();
            this.voice.channelId = String(payload.channelId || this.voice.channelId || '').trim();
            this.voice.participants = participants;
            const me = String(this.myName() || '').trim();
            const amParticipant = participants.includes(me);
            if (roomStatus === 'ringing' || roomStatus === 'pending') {
                if (me && roomTarget && me === roomTarget) {
                    this.voice.incomingInvite = {
                        roomId,
                        from: roomInitiator || this.voice.inviter || '',
                        roomType: 'dm',
                    };
                    this.voice.inviter = roomInitiator || this.voice.inviter || '';
                    this.voice.targetUser = roomTarget || this.voice.targetUser || '';
                    this.voice.callTrack = this.voice.callTrack || {
                        roomId,
                        peer: roomInitiator || roomTarget || '',
                        roomType: 'dm',
                        direction: 'incoming',
                        startedAt: Date.now(),
                        connectedAt: 0,
                        endedAt: 0,
                        outcome: 'incoming',
                        recorded: false,
                    };
                    this.voice.status = 'incoming';
                } else if (me && roomInitiator && me === roomInitiator) {
                    this.voice.outgoingInvite = {
                        roomId,
                        target: roomTarget || this.voice.targetUser || '',
                    };
                    this.voice.targetUser = roomTarget || this.voice.targetUser || '';
                    this.voice.inviter = roomInitiator || this.voice.inviter || '';
                    this.voice.callTrack = this.voice.callTrack || {
                        roomId,
                        peer: roomTarget || roomInitiator || '',
                        roomType: 'dm',
                        direction: 'outgoing',
                        startedAt: Date.now(),
                        connectedAt: 0,
                        endedAt: 0,
                        outcome: 'calling',
                        recorded: false,
                    };
                    this.voice.status = 'calling';
                } else {
                    this.voice.status = amParticipant ? 'connecting' : 'idle';
                }
            } else {
                this.voice.status = amParticipant ? 'connected' : 'idle';
            }
            this.voiceTrace('room-state', { roomId, roomType: this.voice.roomType || '', participants });
            if (amParticipant && this.voice.callTrack && !this.voice.callTrack.connectedAt && roomStatus !== 'ringing' && roomStatus !== 'pending') {
                this.voice.callTrack.connectedAt = Date.now();
                this.voice.callTrack.outcome = 'connected';
            }
            if (roomStatus === 'missed') {
                if (this.voice.callTrack && !this.voice.callTrack.connectedAt) {
                    this.voice.callTrack.connectedAt = Date.now();
                    this.voice.callTrack.outcome = 'missed';
                }
                if (this.voice.incomingInvite?.roomId === roomId || this.voice.outgoingInvite?.roomId === roomId) {
                    this.recordVoiceCallHistory({ outcome: 'missed', endedAt: Date.now() });
                    this.resetVoiceState({ preserveInvite: false });
                }
                return;
            }
            if (roomStatus !== 'ringing' && roomStatus !== 'pending') {
                if (String(this.voice.outgoingInvite?.roomId || '').trim() === roomId) {
                    this.voice.outgoingInvite = null;
                }
                if (String(this.voice.incomingInvite?.roomId || '').trim() === roomId) {
                    this.voice.incomingInvite = null;
                }
            }
            if (amParticipant && roomStatus !== 'ringing' && roomStatus !== 'pending') {
                // Covers every way into a live room, not just joinVoiceChannel:
                // accepting a DM call, and a room restored from the server's
                // reconnect snapshot.
                this.ensureVoicePresenceKeepalive();
                try {
                    await this.ensureVoiceLocalStream();
                } catch (error) {
                    this.addLogEntry({ type: 'WARN', msg: error?.message || 'Не удалось получить доступ к микрофону', ts: new Date().toLocaleTimeString() });
                }
                await this.syncVoicePeers();
            } else if (roomStatus === 'ringing' || roomStatus === 'pending') {
                this.renderVoicePanel();
            } else if (this.voice.roomType === 'dm' && this.voice.roomId === roomId && this.voice.callTrack) {
                this.voice.status = this.voice.status === 'idle' ? 'connecting' : this.voice.status;
            } else {
                this.voiceTrace('room-state-reset', { roomId, participants }, 'WARN');
                this.resetVoiceState({ preserveInvite: true });
            }
            this.renderVoicePanel();
            return;
        }

        if (eventType === 'voice_call_ended') {
            const roomId = String(payload.roomId || '').trim();
            const currentRoomId = String(this.voice.roomId || '').trim();
            if (roomId && currentRoomId && roomId !== currentRoomId) {
                this.voiceTrace('call-ended-stale', { roomId, currentRoomId }, 'INFO');
                return;
            }
            this.voiceTrace('call-ended', { roomId, from: payload.from || '', currentRoomId });
            this.leaveVoiceRoom({ announce: false, outcome: 'completed' });
            return;
        }
    }
});


// --- MODULE: interface/voice_ui.js ---
// --- ZaliInterface: Отрисовка голосовой панели, плиток и развёрнутого звонка. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    voiceIcon(kind) {
        const phone = '<path d="M6.15 4.4c-.92.16-1.62.9-1.72 1.83-.67 6.32 6.98 13.97 13.3 13.3.93-.1 1.67-.8 1.83-1.72l.36-2.08a1.18 1.18 0 0 0-.76-1.32l-3.18-1.16a1.22 1.22 0 0 0-1.27.3l-1.1 1.06a10.4 10.4 0 0 1-4.22-4.22l1.06-1.1c.34-.35.45-.86.3-1.27L9.59 4.84a1.18 1.18 0 0 0-1.32-.76l-2.12.32Z" stroke="currentColor" stroke-width="2.1" stroke-linejoin="round"/>';
        const mic = '<rect x="9" y="3" width="6" height="10" rx="3" stroke="currentColor" stroke-width="1.8"/><path d="M5 11a7 7 0 0 0 14 0" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><path d="M12 18v3M9 21h6" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/>';
        const cam = '<rect x="3.5" y="6.5" width="12" height="11" rx="2.2" stroke="currentColor" stroke-width="1.8"/><path d="M15.5 10.4 20 7.6a.6.6 0 0 1 .92.51v7.78a.6.6 0 0 1-.92.51l-4.5-2.8" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/>';
        const screen = '<rect x="3" y="4.5" width="18" height="12" rx="2" stroke="currentColor" stroke-width="1.8"/><path d="M8.5 20h7M12 16.5v3.5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><path d="M12 6.5v6M9.5 10 12 7.5 14.5 10" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>';
        const headphones = '<path d="M4.5 13.5v-1.7a7.5 7.5 0 0 1 15 0v1.7" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><rect x="3" y="13" width="4" height="6.2" rx="1.7" stroke="currentColor" stroke-width="1.8"/><rect x="17" y="13" width="4" height="6.2" rx="1.7" stroke="currentColor" stroke-width="1.8"/>';
        const chevronDown = '<path d="M6 9l6 6 6-6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>';
        const slash = '<path d="M19.5 4.5l-15 15" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>';
        const icons = {
            phone,
            'phone-off': phone + slash,
            mic,
            'mic-off': mic + slash,
            cam,
            'cam-off': cam + slash,
            screen,
            'screen-off': screen + slash,
            video: cam,
            headphones,
            'headphones-off': headphones + slash,
            'chevron-down': chevronDown,
        };
"""#,
    #"""
        return `<svg class="call-ctrl-icon" viewBox="0 0 24 24" fill="none" aria-hidden="true" focusable="false">${icons[kind] || ''}</svg>`;
    }

    callCtrlBtn({ id, kind, label, active = false, danger = false }) {
        const cls = ['call-ctrl-btn', active ? 'active' : '', danger ? 'danger' : ''].filter(Boolean).join(' ');
        return `<button class="${cls}" type="button" id="${id}" title="${this.esc(label)}" aria-label="${this.esc(label)}">${this.voiceIcon(kind)}</button>`;
    }

    // Discord-style call stage: one rectangular tile per participant, avatar in
    // the middle, name badge at the bottom — the tile *is* the participant list,
    // and it's also where that participant's camera feed mounts (see
    // mountVoiceVideoElements, which fills `.voice-tile-media` by data-peer).
    // Keyed on the lowercased name because every other voice code path
    // (participants, remoteVideos, remoteAudios) normalises that way.
    renderVoiceTiles() {
        const seen = new Set();
        const participants = [];
        const push = name => {
            const raw = String(name || '').trim();
            if (!raw) return;
            const key = raw.toLowerCase();
            if (seen.has(key)) return;
            seen.add(key);
            participants.push(raw);
        };
        push(this.myName());
        for (const name of (Array.isArray(this.voice.participants) ? this.voice.participants : [])) push(name);
        // Someone whose media arrived before the room-state snapshot listing them
        // would otherwise have a video element with no tile to mount into.
        for (const name of this.voice.remoteVideos.keys()) push(name);
        for (const name of this.voice.remoteAudios.keys()) push(name);

        if (!participants.length) {
            return '<div class="voice-empty">Пока никого нет</div>';
        }
        const myName = String(this.myName() || '').trim().toLowerCase();
        return `<div class="voice-tiles" id="voiceTiles">` + participants.map(name => {
            const key = name.toLowerCase();
            const mine = key === myName;
            // Mute state is only known for ourselves — the protocol carries no
            // per-peer mic state, so no badge is drawn for remote participants
            // rather than a badge that would be a guess.
            const muted = mine && !!this.voice.muted;
            return `
                <div class="voice-tile ${mine ? 'mine' : ''}" data-peer="${this.esc(key)}">
                    <div class="voice-tile-media"></div>
                    <div class="voice-tile-avatar">${this.renderAvatarHTML(name, 'voice-tile-ava', name)}</div>
                    <div class="voice-tile-footer">
                        ${muted ? `<span class="voice-tile-mic muted" title="Микрофон выключен">${this.voiceIcon('mic-off')}</span>` : ''}
                        <span class="voice-tile-name">${this.esc(name)}</span>
                    </div>
                </div>
            `;
        }).join('') + `</div>`;
    }

    // Collapsed call UI: mute + deafen on the left, peer/channel name centered,
    // running timer on the right. Tapping anywhere on the bar except those two
    // buttons expands to renderVoiceCallExpanded (wired in the #voicePanel
    // click delegate).
    renderVoiceCallBar({ title }) {
        const muteLabel = this.voice.muted ? 'Включить микрофон' : 'Выключить микрофон';
        const deafenLabel = this.voice.deafened ? 'Включить звук' : 'Выключить звук';
        return `
            <div class="voice-callbar" id="voiceCallBar" role="button" tabindex="0" aria-label="Развернуть звонок">
                <div class="voice-callbar-controls">
                    <button class="voice-callbar-btn" type="button" id="voiceMuteBtn" title="${this.esc(muteLabel)}" aria-label="${this.esc(muteLabel)}">${this.voiceIcon(this.voice.muted ? 'mic-off' : 'mic')}</button>
                    <button class="voice-callbar-btn ${this.voice.deafened ? 'danger' : ''}" type="button" id="voiceDeafenBtn" title="${this.esc(deafenLabel)}" aria-label="${this.esc(deafenLabel)}">${this.voiceIcon(this.voice.deafened ? 'headphones-off' : 'headphones')}</button>
                </div>
                <div class="voice-callbar-title">${this.esc(title)}</div>
                <div class="voice-callbar-timer" id="voiceCallTimer">0:00</div>
            </div>
        `;
    }

    // Fullscreen (within the chat window) call view: dynamic grid of 16:9 tiles,
    // one per participant, reusing renderVoiceTiles()/mountVoiceVideoElements()
    // as-is so a participant's camera feed replaces their tile exactly like it
    // already does in the collapsed layout — nothing about tile mounting changes,
    // only where the tiles are shown.
    renderVoiceCallExpanded({ title, actionButtons }) {
        return `
            <div class="voice-call-expanded" id="voiceCallExpanded">
                <div class="voice-call-expanded-header" id="voiceCollapseBar" role="button" tabindex="0" aria-label="Свернуть звонок">
                    <button class="voice-call-collapse-btn" type="button" id="voiceCollapseBtn" title="Свернуть" aria-label="Свернуть">${this.voiceIcon('chevron-down')}</button>
                    <div class="voice-call-expanded-title">${this.esc(title)}</div>
                    <div class="voice-call-expanded-timer" id="voiceCallExpandedTimer">0:00</div>
                </div>
                ${this.voice.micError ? `<div class="voice-room-alert">${this.esc(this.voice.micError)}</div>` : ''}
                <div class="voice-stage" id="voiceStage"></div>
                <div class="voice-call-expanded-grid">${this.renderVoiceTiles()}</div>
                <div class="call-ctrl-bar voice-call-expanded-actions">${actionButtons.join('')}</div>
            </div>
        `;
    }

    renderVoiceRoomView() {
        const isVoice = this.isVoiceChannel(this.currentChannel());
        const me = String(this.myName() || '').trim().toLowerCase();
        const participants = Array.isArray(this.voice.participants)
            ? this.voice.participants.map(name => String(name || '').trim().toLowerCase()).filter(Boolean)
            : [];
        const participantMatch = me && participants.includes(me);
        // The server lists both sides as room "participants" the moment an invite is
        // created (voice.rs voice_call_invite handler), well before anyone accepts —
        // it models "who belongs to this ringing room", not "who is actually on the
        // call". Treating participantMatch alone as "active call" made the callee's
        // panel render as an already-connected call (only Завершить/mute, no
        // Принять/Отклонить) the instant the invite arrived, so the call could never
        // actually be accepted and the server's 60s ringing timeout later marked it
        // missed. Ringing/calling states must render as pending, not active.
        const pendingDmCall = this.voice.status === 'incoming' || this.voice.status === 'calling';
        const connectedDmRoom = this.voice.roomType === 'dm' && !!String(this.voice.roomId || '').trim() && !pendingDmCall && (this.voice.status === 'connected' || participantMatch);
        const activeRoom = isVoice ? !!this.voice.roomId && participantMatch : connectedDmRoom;
        const outgoingTarget = this.voice.outgoingInvite?.target || this.voice.targetUser || '';
        const incomingFrom = this.voice.incomingInvite?.from || this.voice.inviter || '';
        const voiceHealth = this.voiceTraceEnabled ? this.getVoiceHealthSnapshot() : [];
        const title = isVoice
            ? `Голосовой канал: ${this.currentChannel()?.name || 'room'}`
            : activeRoom
                ? `Активный звонок${outgoingTarget || incomingFrom ? ` с ${outgoingTarget || incomingFrom}` : ''}`
                : this.voice.status === 'incoming'
                    ? `Входящий звонок от ${incomingFrom}`
                    : this.voice.status === 'calling'
                        ? `Звонок ${outgoingTarget ? `к ${outgoingTarget}` : ''}`
                        : this.voice.status === 'connecting'
                            ? `Соединяемся${outgoingTarget || incomingFrom ? ` с ${outgoingTarget || incomingFrom}` : ''}`
                            : 'Голосовые вызовы';

        const actionButtons = [];
        if (isVoice) {
            if (activeRoom) {
                actionButtons.push(this.callCtrlBtn({ id: 'voiceLeaveBtn', kind: 'phone-off', label: 'Покинуть', danger: true }));
                actionButtons.push(this.callCtrlBtn({ id: 'voiceMuteBtn', kind: this.voice.muted ? 'mic-off' : 'mic', label: this.voice.muted ? 'Включить микрофон' : 'Выключить микрофон', active: !this.voice.muted }));
                actionButtons.push(this.callCtrlBtn({ id: 'voiceDeafenBtn', kind: this.voice.deafened ? 'headphones-off' : 'headphones', label: this.voice.deafened ? 'Включить звук' : 'Выключить звук', active: !this.voice.deafened, danger: this.voice.deafened }));
                actionButtons.push(this.callCtrlBtn({ id: 'voiceCameraBtn', kind: this.voice.cameraOn ? 'cam' : 'cam-off', label: this.voice.cameraOn ? 'Выключить камеру' : 'Включить камеру', active: this.voice.cameraOn }));
                actionButtons.push(this.callCtrlBtn({ id: 'voiceScreenShareBtn', kind: this.voice.screenSharing ? 'screen' : 'screen-off', label: this.voice.screenSharing ? 'Остановить показ экрана' : 'Показать экран', active: this.voice.screenSharing }));
            } else {
                actionButtons.push(`<button class="voice-btn" type="button" id="voiceJoinBtn">${this.voiceIcon('phone')}<span>Присоединиться</span></button>`);
            }
        } else if (this.S.navMode === 'dm' && this.S.current) {
            if (activeRoom) {
                actionButtons.push(this.callCtrlBtn({ id: 'voiceLeaveBtn', kind: 'phone-off', label: 'Завершить', danger: true }));
                actionButtons.push(this.callCtrlBtn({ id: 'voiceMuteBtn', kind: this.voice.muted ? 'mic-off' : 'mic', label: this.voice.muted ? 'Включить микрофон' : 'Выключить микрофон', active: !this.voice.muted }));
                actionButtons.push(this.callCtrlBtn({ id: 'voiceDeafenBtn', kind: this.voice.deafened ? 'headphones-off' : 'headphones', label: this.voice.deafened ? 'Включить звук' : 'Выключить звук', active: !this.voice.deafened, danger: this.voice.deafened }));
                actionButtons.push(this.callCtrlBtn({ id: 'voiceCameraBtn', kind: this.voice.cameraOn ? 'cam' : 'cam-off', label: this.voice.cameraOn ? 'Выключить камеру' : 'Включить камеру', active: this.voice.cameraOn }));
                actionButtons.push(this.callCtrlBtn({ id: 'voiceScreenShareBtn', kind: this.voice.screenSharing ? 'screen' : 'screen-off', label: this.voice.screenSharing ? 'Остановить показ экрана' : 'Показать экран', active: this.voice.screenSharing }));
            } else if (this.voice.status === 'incoming' && this.voice.incomingInvite?.from) {
                actionButtons.push(`<button class="voice-btn" type="button" id="voiceAcceptBtn">${this.voiceIcon('phone')}<span>Принять</span></button>`);
                actionButtons.push(`<button class="voice-btn danger" type="button" id="voiceRejectBtn">${this.voiceIcon('phone-off')}<span>Отклонить</span></button>`);
            } else if (this.voice.status === 'calling') {
                actionButtons.push(`<button class="voice-btn danger" type="button" id="voiceCancelBtn">${this.voiceIcon('phone-off')}<span>Отменить</span></button>`);
            } else {
                actionButtons.push(`<button class="voice-btn" type="button" id="voiceCallBtn">${this.voiceIcon('phone')}<span>Позвонить</span></button>`);
                actionButtons.push(`<button class="voice-btn" type="button" id="voiceVideoCallBtn">${this.voiceIcon('video')}<span>Видеозвонок</span></button>`);
            }
        }
        const actionsBarClass = activeRoom ? 'voice-room-actions call-ctrl-bar' : 'voice-room-actions';

        // A live call (as opposed to ringing/dialing/idle-selected) collapses to a
        // slim top bar by default and only shows the full participant grid when
        // the user taps it — the old always-expanded card ate half the chat
        // window for the entire duration of every call.
        if (activeRoom) {
            if (!this.voice.activeSince) {
                this.voice.activeSince = Number(this.voice.callTrack?.connectedAt) || Date.now();
            }
            this.startVoiceCallBarTimer();
            return this.voice.expanded
                ? this.renderVoiceCallExpanded({ title, actionButtons })
                : this.renderVoiceCallBar({ title });
        }
        this.voice.activeSince = 0;
        this.stopVoiceCallBarTimer();

        return `
            <div class="voice-room-card ${activeRoom ? 'active' : ''} ${isVoice ? 'voice-channel' : ''}">
                <div class="voice-room-top">
                    <div>
                        <div class="voice-room-title">${this.esc(title)}</div>
                        <div class="voice-room-sub">${this.esc(this.voice.status === 'connected' ? 'Собеседник поднял трубку' : this.voice.status === 'incoming' ? 'Входящий звонок' : this.voice.status === 'calling' ? 'Ожидание ответа' : this.voice.status === 'connecting' ? 'Соединяемся' : 'Голос готов')}</div>
                    </div>
                    <div class="voice-room-state">${this.esc(activeRoom ? 'В эфире' : isVoice ? 'Выбрано' : 'Ожидание')}</div>
                </div>
                ${this.voice.micError ? `<div class="voice-room-alert">${this.esc(this.voice.micError)}</div>` : ''}
                <div class="voice-stage" id="voiceStage"></div>
                ${this.renderVoiceTiles()}
                <div class="${actionsBarClass}">${actionButtons.join('')}</div>
                <div class="voice-meter-grid">
                    <div class="voice-meter" id="voiceMicMeter">
                        <div class="voice-meter-head">
                            <span class="voice-meter-name">Микрофон</span>
                            <span class="voice-meter-value" id="voiceMicLevelText">0%</span>
                        </div>
                        <div class="voice-meter-track">
                            <div class="voice-meter-fill" id="voiceMicLevelFill"></div>
                        </div>
                    </div>
                    <div class="voice-meter" id="voiceServerMeter">
                        <div class="voice-meter-head">
                            <span class="voice-meter-name">С сервера</span>
                            <span class="voice-meter-value" id="voiceServerLevelText">0%</span>
                        </div>
                        <div class="voice-meter-track">
                            <div class="voice-meter-fill remote" id="voiceServerLevelFill"></div>
                        </div>
                    </div>
                </div>
                ${voiceHealth.length ? `
                    <div class="voice-health">
                        <div class="voice-room-label">Voice health</div>
                        <div class="voice-health-grid">
                            ${voiceHealth.map(item => `
                                <div class="voice-health-card" data-tone="${this.esc(item.tone)}">
                                    <span class="voice-health-name">${this.esc(item.label)}</span>
                                    <strong class="voice-health-value">${this.esc(item.value)}</strong>
                                    <span class="voice-health-sub">${this.esc(item.sub || '')}</span>
                                </div>
                            `).join('')}
                        </div>
                    </div>
                ` : ''}
                ${Array.isArray(this.voice.traceLines) && this.voice.traceLines.length ? `
                    <div class="voice-trace">
                        <div class="voice-room-label">Трассировка</div>
                        <div class="voice-trace-list">
                            ${this.voice.traceLines.slice(-8).map(line => `
                                <div class="voice-trace-line voice-trace-${this.esc(line.level.toLowerCase())}">
                                    <span class="voice-trace-ts">[${this.esc(line.ts)}]</span>
                                    <span class="voice-trace-stage">${this.esc(line.stage)}</span>
                                </div>
                            `).join('')}
                        </div>
                    </div>
                ` : ''}
            </div>
        `;
    }

    // Coalesces bursts of voice-panel refreshes (ICE candidate storms, rapid state
    // flips) into one render per window instead of one innerHTML rebuild per event.
    scheduleRenderVoicePanel(delayMs = 100) {
        if (this._voicePanelRenderTimer) return;
        this._voicePanelRenderTimer = setTimeout(() => {
            this._voicePanelRenderTimer = null;
            this.renderVoicePanel();
        }, Math.max(0, Number(delayMs) || 0));
    }

    renderVoicePanel() {
        // Every voice-state transition (ringing → answered/declined/missed/ended)
        // calls renderVoicePanel(), so syncing the ringtone here — rather than at
        // each individual transition site — guarantees it always stops, including
        // paths that don't go through resetVoiceState (e.g. the caller cancelling).
        if (this.voice.status === 'incoming' && this.voice.incomingInvite) {
            this.startRingtone();
        } else {
            this.stopRingtone();
        }
        const panel = document.getElementById('voicePanel');
        if (!panel) return;
        const isServers = this.S.navMode === 'servers';
        const isVoiceChannel = isServers && this.isVoiceChannel(this.currentChannel());
        const hasDmCall = this.voice.roomType === 'dm' || this.voice.status === 'incoming' || this.voice.status === 'calling';
        const hasIncoming = this.voice.status === 'incoming';
        const showPanel = isVoiceChannel || hasDmCall || hasIncoming;
        panel.hidden = !showPanel;
        if (!showPanel) {
            panel.innerHTML = '';
            return;
        }
        // An active screen share needs more than the normal half-screen cap
        // (see .voice-panel.has-stage in style.css) — the stage tiles alone can
        // run well past that at their 16:9 aspect ratio.
        const hasStage = !!(this.voice.screenSharing || this.voice.remoteScreens?.size);
        panel.classList.toggle('has-stage', hasStage);
        if (isVoiceChannel || hasDmCall || hasIncoming || this.voice.roomType === 'dm') {
            panel.innerHTML = this.renderVoiceRoomView();
            // Bar/expanded modes need layout rules (fixed slim bar vs. a fullscreen
            // overlay) that don't fit the normal embedded-card sizing in
            // .voice-panel, hence dedicated classes rather than relying on
            // .has-stage/max-height alone.
            panel.classList.toggle('call-bar-mode', !!panel.querySelector('#voiceCallBar'));
            panel.classList.toggle('call-expanded-mode', !!panel.querySelector('#voiceCallExpanded'));
            this.mountVoiceVideoElements();
            return;
        }
        panel.classList.remove('call-bar-mode', 'call-expanded-mode');
        panel.innerHTML = '';
    }

    mountVoiceVideoElements() {
        const stage = document.getElementById('voiceStage');
        if (stage) {
            stage.replaceChildren();
            if (this.voice.localScreenVideoEl && this.voice.screenSharing) {
                const wrap = document.createElement('div');
                wrap.className = 'voice-stage-tile';
                wrap.appendChild(this.voice.localScreenVideoEl);
                const label = document.createElement('span');
                label.className = 'voice-video-label';
                label.textContent = 'Ваш экран';
                wrap.appendChild(label);
                stage.appendChild(wrap);
            }
            for (const [peer, video] of this.voice.remoteScreens.entries()) {
                const wrap = document.createElement('div');
                wrap.className = 'voice-stage-tile';
                wrap.appendChild(video);
                const label = document.createElement('span');
                label.className = 'voice-video-label';
                label.textContent = `Экран: ${peer}`;
                wrap.appendChild(label);
                stage.appendChild(wrap);
            }
        }
        const tiles = document.getElementById('voiceTiles');
        if (!tiles) {
            this._voiceTileNodes = null;
            return;
        }
        // Index the tiles once per panel render. The meter loop toggles the
        // speaking ring 8×/s and used to re-run querySelectorAll on every tick;
        // the tile set only ever changes when this function rebuilds it.
        const byPeer = new Map();
        for (const tile of tiles.querySelectorAll('.voice-tile')) {
            tile.classList.remove('has-video');
            const media = tile.querySelector('.voice-tile-media');
            if (media) media.replaceChildren();
            byPeer.set(tile.dataset.peer || '', tile);
        }
        this._voiceTileNodes = byPeer;
        const mountVideo = (peer, video) => {
            const key = String(peer || '').trim().toLowerCase();
            if (!key || !video) return;
            const tile = byPeer.get(key);
            const media = tile?.querySelector('.voice-tile-media');
            if (!media) return;
            media.appendChild(video);
            tile.classList.add('has-video');
        };
        if (this.voice.cameraOn) mountVideo(this.myName(), this.voice.localVideoEl);
        for (const [peer, video] of this.voice.remoteVideos.entries()) {
            mountVideo(peer, video);
        }
        this.applyVoiceSpeakingState();
    }

    // Discord's "green ring while talking". Driven straight from the meter loop
    // (updateVoiceMeters) by toggling a class on existing tiles — never by
    // re-rendering the panel, which would tear down and remount every <video>
    // element several times a second.
    applyVoiceSpeakingState(levels = this._voiceTileLevels) {
        this._voiceTileLevels = levels || {};
        const byPeer = this._voiceTileNodes;
        if (!byPeer || !byPeer.size) return;
        const SPEAKING_THRESHOLD = 12; // percent, same scale as the meters
        for (const [peer, tile] of byPeer) {
            const speaking = Number(this._voiceTileLevels[peer] || 0) >= SPEAKING_THRESHOLD;
            // classList.toggle with an explicit force flag still writes the
            // attribute every call, which dirties style on tiles that did not
            // change. Only touch the ones whose state actually flipped.
            if (tile.classList.contains('speaking') !== speaking) {
                tile.classList.toggle('speaking', speaking);
            }
        }
    }
});


// --- MODULE: interface/server_messages.js ---
// --- ZaliInterface: Загрузка сообщений серверов/каналов, синхронизация активного разговора. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    isOutgoingMessage(msg) {
        return String(msg?.sender || '').trim() === this.myName();
    }

    mergeServerChatMessages(key, incomingMessages) {
        const existing = Array.isArray(this.S.serverChats[key]) ? this.S.serverChats[key] : [];
        const merged = [];
        const mergedByKey = new Map();

        const makeIdentity = (msg) => {
            const normalized = {
                ...msg,
                id: String(msg?.id || '').trim(),
                clientId: String(msg?.clientId || '').trim(),
                serverId: msg?.serverId || msg?.server_id || null,
                channelId: msg?.channelId || msg?.channel_id || null,
            };
            const attachmentKey = this.normalizeAttachments(normalized.attachments)
                .map(att => `${att.name}:${att.kind}:${att.size}:${att.mimeType}`)
                .join('|');
            const identity = normalized.id || normalized.clientId || [
                normalized.sender || '',
                normalized.receiver || '',
                normalized.timestamp || '',
                normalized.text || '',
                attachmentKey,
            ].join('::');
            return { normalized, identity };
        };

        // Which identities were already known BEFORE this merge, so an incoming
        // message under a brand new identity can be told apart from a status/metadata
        // update to something we already had. Filled during the `existing` pass below
        // rather than by a separate map(): makeIdentity spreads the message object and
        // normalises its attachments, so precomputing the set ran that over the whole
        // channel history a second time — on every single incoming WS message.
        const existingIdentities = new Set();
        const newlyInserted = [];

        const upsert = (msg, { fromIncoming = false } = {}) => {
            const { normalized, identity } = makeIdentity(msg);
            const prev = mergedByKey.get(identity);
            const next = prev
                ? {
                    ...prev,
                    ...normalized,
                    attachments: this.normalizeAttachments(normalized.attachments ?? prev.attachments),
                    reactions: this.normalizeReactions(normalized.reactions ?? prev.reactions),
                    myReactions: this.normalizeMyReactions(normalized.myReactions ?? prev.myReactions),
                }
                : {
                    ...normalized,
                    attachments: this.normalizeAttachments(normalized.attachments),
                    reactions: this.normalizeReactions(normalized.reactions),
                    myReactions: this.normalizeMyReactions(normalized.myReactions),
                };
            mergedByKey.set(identity, next);
            if (!prev) merged.push(identity);
            if (fromIncoming) {
                if (!existingIdentities.has(identity)) newlyInserted.push(next);
            } else {
                // The `existing` pass runs to completion before any incoming message
                // is upserted, so the set is fully populated by the time it is read.
                existingIdentities.add(identity);
            }
        };

        existing.forEach(msg => upsert(msg));
        (Array.isArray(incomingMessages) ? incomingMessages : []).forEach(msg => upsert(msg, { fromIncoming: true }));

        const next = merged
            .map(identity => mergedByKey.get(identity))
            .sort((a, b) => this.compareMessagesByTime(a, b));
        this.S.serverChats[key] = next;
        this.saveStoredServerChats();

        // First time this channel is ever merged in this session (initial history
        // load / first open), just prime the baseline silently — otherwise opening a
        // channel with months of history would replay it all as notifications. Only
        // merges AFTER that baseline (reconnect catch-up, background refreshes)
        // notify for genuinely new messages, same rule as loadHistory() for DMs.
        const alreadyPrimed = this._historyPrimedChannels.has(key);
        if (!alreadyPrimed) {
            this._historyPrimedChannels.add(key);
        } else if (newlyInserted.length && !this.isServerChatVisible(key)) {
            newlyInserted.forEach(msg => {
                this.notifyBackgroundMessage({
                    sender: msg.sender,
                    text: msg.text,
                    attachmentCount: this.normalizeAttachments(msg.attachments).length,
                    serverId: msg.serverId,
                    channelId: msg.channelId,
                });
            });
            this.renderServerInterface();
            this.renderContacts();
        }
        return next;
    }

    ensureServerSelection() {
        this.ensureServersState();
        const servers = Array.isArray(this.S.servers) ? this.S.servers : [];
        if (servers.length === 0) {
            this.S.activeServer = null;
            this.S.activeChannel = null;
            this.S.activeConversationType = 'dm';
            return;
        }

        const storedServer = this.loadStoredActiveServer();
        if (storedServer && servers.some(s => s.id === storedServer)) {
            this.S.activeServer = storedServer;
        } else if (!this.S.activeServer || !servers.some(s => s.id === this.S.activeServer)) {
            this.S.activeServer = servers[0].id;
        }

        const server = this.currentServer();
        const storedChannel = this.loadStoredActiveChannel();
        if (server) {
            if (storedChannel && (server.channels || []).some(ch => ch.id === storedChannel)) {
                this.S.activeChannel = storedChannel;
            } else if (!this.S.activeChannel || !(server.channels || []).some(ch => ch.id === this.S.activeChannel)) {
                this.S.activeChannel = server.channels?.[0]?.id || null;
            }
        }
    }

    async loadServers({ silent = false } = {}) {
        try {
            if (!this.S.session?.token) {
                this.S.servers = [];
                this.ensureServerSelection();
                this.renderContacts();
                this.renderServerInterface();
                this.scheduleRenderMessages();
                return;
            }
            const res = await this.apiFetch(this.apiRoutes.servers.list);
            if (!res.ok) {
                this.S.servers = [];
                this.ensureServerSelection();
                this.renderContacts();
                this.renderServerInterface();
                this.scheduleRenderMessages();
                return;
            }
            const data = await res.json();
            this.S.servers = this.normalizeServers(Array.isArray(data?.servers) ? data.servers : []);
            this.ensureServerSelection();
            this.renderContacts();
            this.renderServerInterface();
            this.scheduleRenderMessages();
            if (this.S.activeServer && this.S.activeChannel) {
                this.loadServerMessages(this.S.activeServer, this.S.activeChannel, { silent: true });
            }
        } catch (e) {
            if (!silent) {
                this.addLogEntry({ type: 'WARN', msg: 'Не удалось загрузить серверы', ts: new Date().toLocaleTimeString() });
            }
            this.S.servers = [];
            this.ensureServerSelection();
            this.renderContacts();
            this.renderServerInterface();
            this.scheduleRenderMessages();
            if (this.S.activeServer && this.S.activeChannel) {
                this.loadServerMessages(this.S.activeServer, this.S.activeChannel, { silent: true });
            }
        }
    }

    async loadServerMessages(serverId, channelId, { silent = false } = {}) {
        const sid = String(serverId || '').trim();
        const cid = String(channelId || '').trim();
        if (!sid || !cid) return;
        this.trace(`loadServerMessages start server=${sid} channel=${cid} nativeHistory=${this.nativeSupports('serverHistory')}`);
        if (!this.S.session?.token) {
            this.scheduleRenderMessages();
            return;
        }
        const key = `${sid}:${cid}`;
        if (!Array.isArray(this.S.serverChats[key])) {
            this.S.serverChats[key] = [];
        }
        const channel = (this.currentServer()?.channels || []).find(item => item.id === cid) || null;
        if (this.isVoiceChannel(channel)) {
            this.scheduleRenderMessages();
            return;
        }
        this.scheduleRenderMessages();

        if (this.nativeSupports('serverHistory')) {
            const conversationKey = this.ensureConversationCryptoKey({
                serverId: sid,
                channelId: cid,
                reason: 'loadServerMessages',
            });
            this.postNativeMessage({
                type: NativeMessageTypes.LOAD_SERVER_HISTORY,
                serverId: sid,
                channelId: cid,
                key: conversationKey,
            });
            return;
        }

        // No native shell to decrypt channel history for us — each row here is just
        // server-known metadata (id/sender/receiver/filename/timestamp), same as a DM
        // history row. Route it through the same WASM download+unpack path used for
        // live-received messages instead of showing "encrypted, needs native bridge".
        if (!(await this.wasmAvailable())) {
            if (!silent) {
                this.addLogEntry({ type: 'WARN', msg: 'WASM недоступен: сообщения канала не будут расшифрованы', ts: new Date().toLocaleTimeString() });
            }
            return;
        }
        // See loadBrowserDmHistory: cleared before the walk, re-marked by any row this
        // pass still cannot open.
        this.clearBrowserDecryptGap({ serverId: sid, channelId: cid });
        try {
            const limit = 200;
            let offset = 0;
            let mergedCount = 0;
            while (true) {
                const res = await this.apiFetch(this.apiRoutes.servers.channelMessages(sid, cid, limit, offset));
                if (!res.ok) {
                    const text = await res.text().catch(() => '');
                    this.trace(`loadServerMessages failed server=${sid} channel=${cid} status=${res.status} offset=${offset} body=${text.slice(0, 300)}`);
                    if (!silent) {
                        this.addLogEntry({ type: 'WARN', msg: `Не удалось загрузить сообщения канала ${cid}`, ts: new Date().toLocaleTimeString() });
                    }
                    return;
                }
                const messages = await res.json();
                const batch = Array.isArray(messages) ? messages : [];
                this.trace(`loadServerMessages success server=${sid} channel=${cid} offset=${offset} count=${batch.length}`);
                for (const msg of batch) {
                    await this.handleIncomingBrowserMessage(msg);
                }
                mergedCount += batch.length;
                if (batch.length < limit) break;
                offset += limit;
            }
            this.trace(`loadServerMessages merged server=${sid} channel=${cid} count=${mergedCount}`);
        } catch (e) {
            if (!silent) {
                this.addLogEntry({ type: 'ERROR', msg: `Ошибка загрузки канала ${cid}: ${e?.message || e}`, ts: new Date().toLocaleTimeString() });
            }
        }
    }

    loadServerHistory(payload) {
        if (!payload || typeof payload !== 'object') return;
        const serverId = String(payload.serverId || payload.server_id || '').trim();
        const channelId = String(payload.channelId || payload.channel_id || '').trim();
        const messages = Array.isArray(payload.messages) ? payload.messages : [];
        if (!serverId || !channelId) return;
        const queue = messages.filter(msg => msg && typeof msg === 'object');
        this.trace(`loadServerHistory start server=${serverId} channel=${channelId} count=${queue.length}`);
        const key = `${serverId}:${channelId}`;
        const reconciled = [];
        const processBatch = (startIndex = 0) => {
            const startedAt = performance.now();
            let index = startIndex;
            for (; index < queue.length; index += 1) {
                if ((index - startIndex) >= 120) break;
                if ((performance.now() - startedAt) >= 8) break;
                const raw = queue[index];
                const msg = {
                    ...raw,
                    serverId: raw.serverId || raw.server_id || serverId,
                    channelId: raw.channelId || raw.channel_id || channelId,
                };
                const normalizedAttachments = this.normalizeAttachments(msg.attachments);
                const normalizedReactions = this.normalizeReactions(msg.reactions);
                const msgId = String(msg.id || '').trim();
                const clientId = String(msg.clientId || msg.client_id || '').trim();
                if (clientId && this.finalizePendingMessage(clientId, msg.id, { render: false })) {
                    this.dropPendingOutbox(clientId);
                    continue;
                }
                const incomingKey = this.messageRenderKey(msg);
                const existingIndex = msgId
                    ? reconciled.findIndex(m => String(m.id || '').trim() === msgId)
                    : reconciled.findIndex(m => this.messageRenderKey(m) === incomingKey);
                if (existingIndex >= 0) {
                    const prev = reconciled[existingIndex];
                    reconciled[existingIndex] = {
                        ...prev,
                        ...msg,
                        id: msgId || msg.id || prev.id || '',
                        attachments: normalizedAttachments.length ? normalizedAttachments : this.normalizeAttachments(prev.attachments),
                        reactions: normalizedReactions.length ? normalizedReactions : this.normalizeReactions(prev.reactions),
                        myReactions: this.normalizeMyReactions(msg.myReactions?.length ? msg.myReactions : prev.myReactions),
                        text: this.sanitizeDecryptionErrorText(msg.text) || prev.text || '',
                        status: 'sent',
                        serverId: msg.serverId || msg.server_id || serverId,
                        channelId: msg.channelId || msg.channel_id || channelId,
                    };
                } else {
                    reconciled.push({
                        ...msg,
                        id: msgId || msg.id || '',
                        attachments: normalizedAttachments,
                        reactions: normalizedReactions,
                        myReactions: this.normalizeMyReactions(msg.myReactions),
                        text: this.sanitizeDecryptionErrorText(msg.text),
                        status: 'sent',
                    });
                }
            }
            if (index < queue.length) {
                requestAnimationFrame(() => processBatch(index));
                return;
            }
            this.mergeServerChatMessages(key, reconciled);
            if (this.currentServerChatKey() === key) {
                this.scheduleRenderMessages();
            }
            this.scheduleFlushPendingOutbox(300);
            this.trace(`loadServerHistory done server=${serverId} channel=${channelId} merged=${reconciled.length}`);
        };
        processBatch(0);
    }

    async refreshAfterKey() {
        if (this._refreshAfterKeyInFlight) {
            this._refreshAfterKeyQueued = true;
            return;
        }
        this._refreshAfterKeyInFlight = true;
        try {
            await this._refreshAfterKeyImpl();
        } finally {
            this._refreshAfterKeyInFlight = false;
            if (this._refreshAfterKeyQueued) {
                this._refreshAfterKeyQueued = false;
                void this.refreshAfterKey();
            }
        }
    }

    async _refreshAfterKeyImpl() {
        if (!this.S.session?.token) {
            this.scheduleFlushPendingOutbox(300);
            return;
        }
        // Pull newly published key envelopes (e.g. after a key_envelope_available
        // WS notification) so a stale self-generated key can be replaced before we
        // resolve and re-decrypt the active conversation. triggerRefresh=false
        // avoids re-entering this method.
        await this.syncIncomingKeyEnvelopes({ reason: 'refreshAfterKey', triggerRefresh: false });
        if (this.S.navMode === 'servers') {
            this.ensureServerSelection();
        } else if (!this.S.current) {
            const storedCurrent = this.loadStoredCurrentContact();
            if (storedCurrent) {
                this.S.current = storedCurrent;
                this.ensureContact(storedCurrent);
                this.initChat(storedCurrent);
            }
        }

        if (this.S.navMode === 'servers' && this.S.activeServer && this.S.activeChannel) {
            const key = await this.resolveConversationCryptoKey({
                serverId: this.S.activeServer,
                channelId: this.S.activeChannel,
                reason: 'refreshAfterKey'
            });
            if (this.keyChangeCanRevealMore({ serverId: this.S.activeServer, channelId: this.S.activeChannel })) {
                this.loadServerMessages(this.S.activeServer, this.S.activeChannel, { silent: true });
            }
            this.scheduleFlushPendingOutbox(300);
            return;
        }

        if (this.S.current) {
            const key = await this.resolveConversationCryptoKey({ peer: this.S.current, reason: 'refreshAfterKey' });
            if (this.keyChangeCanRevealMore({ peer: this.S.current })) {
                if (this.nativeSupports('sendMessage')) {
                    this.postNativeMessage({ type: NativeMessageTypes.REFRESH_HISTORY, key, peer: this.S.current });
                } else {
                    void this.loadBrowserDmHistory(this.S.current, key);
                }
            }
        }
        this.scheduleFlushPendingOutbox(300);
    }

    keyChangeCanRevealMore({ peer = null, serverId = null, channelId = null } = {}) {
        const store = (serverId && channelId)
            ? this.S.serverChats[`${serverId}:${channelId}`]
            : this.S.chats[String(peer || '').trim()];
        if (!Array.isArray(store) || !store.length) return true;
        const scope = this.conversationScopeKey(peer, serverId, channelId);
        if (scope && this._browserDecryptGaps?.has(scope)) return true;
        return store.some(msg => this.detectSystemNotice(msg?.text) === 'decrypt-error');
    }

    // A message the browser client could not open, recorded against its conversation.
    // Unlike the native shells it renders no placeholder for these — the message is
    // simply absent — so without this the conversation would look complete and a key
    // arriving later would never trigger the reload that fetches it.
    markBrowserDecryptGap({ peer = null, serverId = null, channelId = null } = {}) {
        const scope = this.conversationScopeKey(peer, serverId, channelId);
        if (!scope) return;
        if (!this._browserDecryptGaps) this._browserDecryptGaps = new Set();
        this._browserDecryptGaps.add(scope);
    }

    /// Called at the START of a browser history load: the load itself re-marks
    /// anything it still cannot open, so whatever survives is a live gap.
    clearBrowserDecryptGap({ peer = null, serverId = null, channelId = null } = {}) {
        const scope = this.conversationScopeKey(peer, serverId, channelId);
        if (scope) this._browserDecryptGaps?.delete(scope);
    }


    async syncActiveConversation({ force = false } = {}) {
        if (!this.S.session?.token) return;
        if (!force && document.hidden) return;
        if (this.S.navMode === 'servers') {
            const serverId = this.S.activeServer;
            const channelId = this.S.activeChannel;
            if (serverId && channelId) {
                const syncKey = `server:${serverId}:${channelId}`;
                const now = Date.now();
                const lastSyncAt = this.conversationSyncAt.get(syncKey) || 0;
                if (!force && (now - lastSyncAt) < 30000) return;
                this.conversationSyncAt.set(syncKey, now);
                this.trace(`syncActiveConversation server=${serverId} channel=${channelId}`);
                await this.resolveConversationCryptoKey({
                    serverId,
                    channelId,
                    reason: 'syncActiveConversation',
                });
                this.loadServerMessages(serverId, channelId, { silent: true });
            }
            return;
        }

        const peer = String(this.S.current || '').trim();
        if (!peer) return;
        const syncKey = `dm:${peer}`;
        const now = Date.now();
        const lastSyncAt = this.conversationSyncAt.get(syncKey) || 0;
        if (!force && (now - lastSyncAt) < 60000) return;
        this.conversationSyncAt.set(syncKey, now);
        this.trace(`syncActiveConversation peer=${peer} force=${force}`);
        const key = await this.resolveConversationCryptoKey({ peer, reason: 'syncActiveConversation' });
        if (this.nativeSupports('sendMessage')) {
            this.postNativeMessage({ type: NativeMessageTypes.REFRESH_HISTORY, key, peer });
        } else {
            void this.loadBrowserDmHistory(peer, key);
        }
    }

    async syncConversationFromNative(payload = {}) {
        if (!this.S.session?.token) return;
        const serverId = String(payload?.serverId || '').trim();
        const channelId = String(payload?.channelId || '').trim();
        const peer = String(payload?.peer || '').trim();
        if (serverId && channelId) {
            await this.resolveConversationCryptoKey({ serverId, channelId, reason: 'syncConversationFromNative' });
            this.loadServerMessages(serverId, channelId, { silent: true });
            return;
        }
        if (peer) {
            const key = await this.resolveConversationCryptoKey({ peer, reason: 'syncConversationFromNative' });
            if (this.nativeSupports('sendMessage')) {
                this.postNativeMessage({ type: NativeMessageTypes.REFRESH_HISTORY, key, peer });
            }
            return;
        }
        this.syncActiveConversation({ force: !!payload?.force });
    }

    scheduleConversationRefresh({ peer = null, serverId = null, channelId = null, reason = 'message', delayMs = 250 } = {}) {
        if (!this.S.session?.token) return;
        const sid = String(serverId || '').trim();
        const cid = String(channelId || '').trim();
        const dmPeer = String(peer || '').trim();
        const key = sid && cid
            ? `server:${sid}:${cid}`
            : dmPeer
                ? `dm:${dmPeer}`
                : '';
        if (!key) return;

        if (this.conversationRefreshTimers.has(key)) {
            clearTimeout(this.conversationRefreshTimers.get(key));
        }

        this.conversationRefreshTimers.set(key, setTimeout(() => {
            this.conversationRefreshTimers.delete(key);
            if (sid && cid) {
                this.trace(`scheduleConversationRefresh fire reason=${reason} server=${sid} channel=${cid}`);
                this.resolveConversationCryptoKey({
                    serverId: sid,
                    channelId: cid,
                    reason: `refresh:${reason}`,
                });
                this.loadServerMessages(sid, cid, { silent: true });
                return;
            }

            if (!dmPeer) return;
            this.trace(`scheduleConversationRefresh fire reason=${reason} peer=${dmPeer}`);
            this.resolveConversationCryptoKey({ peer: dmPeer, reason: `refresh:${reason}` }).then((keyValue) => {
                if (this.nativeSupports('sendMessage')) {
                    this.postNativeMessage({ type: NativeMessageTypes.REFRESH_HISTORY, key: keyValue, peer: dmPeer });
                }
            });
        }, Math.max(100, Number(delayMs) || 250)));
    }

    renderServerInterface() {
        this.ensureServersState();
        this.ensureServerSelection();
        this.renderServerToolbar();
        this.updateSendButtonState();
    }

    renderServerToolbar() {
        const channelList = document.getElementById('serverChannelList');
        const chatHdr = document.getElementById('chatHdr');
        const chatHdrAva = document.getElementById('chatHdrAva');
        const chatHdrName = document.getElementById('chatHdrName');
        const chatHdrSub = document.getElementById('chatHdrSub');
        const chatCallBtn = document.getElementById('chatCallBtn');
        const chatVideoCallBtn = document.getElementById('chatVideoCallBtn');
        const serverSettingsBtn = document.getElementById('serverSettingsBtn');
        const tbChat = document.getElementById('tbChat');
        const server = this.currentServer();
        const channel = this.currentChannel();
        const isServers = this.S.navMode === 'servers';
        const canManage = this.canManageServer(server);

        if (chatHdr) chatHdr.classList.toggle('server-mode', isServers);
        if (channelList) channelList.hidden = !isServers;
        if (chatCallBtn) {
            chatCallBtn.hidden = isServers || !this.S.current;
        }
        if (chatVideoCallBtn) {
            chatVideoCallBtn.hidden = isServers || !this.S.current;
        }
        if (serverSettingsBtn) {
            serverSettingsBtn.hidden = !isServers || !server || !canManage;
            serverSettingsBtn.disabled = !canManage;
        }
        if (!isServers) {
            if (channelList) channelList.innerHTML = '';
            if (chatHdrAva) {
                chatHdrAva.style.background = '';
                const who = this.S.current || this.myName();
                this.setHTMLIfChanged(chatHdrAva, this.renderAvatarHTML(who, 'avatar-img', who));
            }
            if (chatHdrName) chatHdrName.textContent = this.S.current || 'Выберите чат';
            if (tbChat) tbChat.textContent = this.S.current || (this.S.contacts.length ? 'Выберите чат' : 'Нет контактов');
            if (chatHdrSub) {
                chatHdrSub.innerHTML = '';
                if (this.S.current) {
                    this.updateChatHeaderCryptoKey({ peer: this.S.current });
                } else {
                    chatHdrSub.textContent = 'Личное сообщение';
                }
            }
            return;
        }
        if (!server) {
            if (channelList) channelList.innerHTML = '';
            return;
        }

        if (chatHdrAva) {
            chatHdrAva.style.background = this.serverAvatarBackground(server);
            this.setHTMLIfChanged(chatHdrAva, this.serverAvatarInnerHTML(server));
        }
        if (chatHdrName) {
            const membersText = Number(server.memberCount || 0) > 0 ? `${Number(server.memberCount)} ${this.ruPlural(server.memberCount, 'участник', 'участника', 'участников')}` : '';
            const channelTitle = channel
                ? `${this.channelKindIcon(channel.kind, 'chat-hdr-channel-icon')}<span>${this.esc(channel.name)}</span>`
                : this.esc(server.name);
            this.setHTMLIfChanged(chatHdrName, `
                <span class="chat-hdr-title">${channelTitle}</span>
                ${membersText ? `<span class="chat-hdr-count">${this.esc(membersText)}</span>` : ''}
            `);
        }
        if (chatHdrSub) {
            chatHdrSub.textContent = channel
                ? `${server.name}${channel.topic ? ` · ${channel.topic}` : ''}`
                : (server.description || 'Сервер');
        }
        if (tbChat) {
            tbChat.textContent = channel
                ? `${server.name} / ${this.channelKindLabel(channel.kind)}: ${channel.name}`
                : server.name;
        }

        if (channelList) {
            const channels = Array.isArray(server.channels) ? server.channels : [];
            const channelsHTML = channels.map(ch => {
            const active = ch.id === this.S.activeChannel ? 'active' : '';
            const kind = String(ch.kind || 'text').trim().toLowerCase();
            const title = kind === 'voice' ? 'Голосовой канал' : 'Текстовый канал';
            const chKey = `${server.id}:${ch.id}`;
            const cnt = kind === 'voice' ? 0 : Number(this.S.channelUnread?.[chKey] || 0);
            const badge = cnt > 0 ? `<span class="badge">${cnt > 99 ? '99+' : cnt}</span>` : '';
            const muted = kind !== 'voice' && this.isChannelMuted(server.id, ch.id);
            const muteToggle = muted ? `<span class="channel-mute-indicator" title="Уведомления отключены" aria-label="Уведомления отключены">${this.uiIcon('bell-off')}</span>` : '';
            return `<div class="server-channel ${active}" data-server-id="${this.esc(server.id)}" data-channel-id="${this.esc(ch.id)}" data-channel-kind="${this.esc(kind)}" title="${this.esc(title)}">
                    <span class="server-channel-hash ${kind}">${this.channelKindIcon(kind, 'server-channel-list-icon')}</span>
                    <span class="server-channel-name">${this.esc(ch.name)}</span>
                    ${muteToggle}
                    ${badge}
                </div>`;
        }).join('');

            this.commitListHTML(channelList, `channels:${server.id}`, channelsHTML);

            // renderServerToolbar() runs on every avatar that finishes loading, every
            // nav refresh and every toolbar sync. Firing a *smooth* scrollIntoView on
            // each of those made the channel rail (and, since scrollIntoView walks
            // every scrollable ancestor, whatever else was scrollable around it) drift
            // on its own — the unexplained jumps while just reading a channel. Only
            // scroll when the selected channel actually changed.
            const activeChannelKey = `${server.id}:${String(this.S.activeChannel || '')}`;
            if (this._lastScrolledChannelKey !== activeChannelKey) {
                this._lastScrolledChannelKey = activeChannelKey;
                const activeChannel = channelList.querySelector('.server-channel.active');
                if (activeChannel && typeof activeChannel.scrollIntoView === 'function') {
                    requestAnimationFrame(() => {
                        activeChannel.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'nearest' });
                    });
                }
            }
        }
    }

    setActiveChannel(channelId, { persist = true } = {}) {
        const next = String(channelId || '').trim();
        const server = this.currentServer();
        if (!server || !next) return;
        const channel = (server.channels || []).find(ch => ch.id === next) || null;
        if (!channel) return;
        if (this.S.navMode === 'servers' && this.S.activeChannel === next) {
            // Nothing changes in state, but this may still be a click from
            // Hub/ZaliCoin/Settings asking to see the already-selected channel —
            // see ensureChatViewOpen().
            this.ensureChatViewOpen();
            return;
        }
        // Same reasoning as switchChat: the channel list in the sidebar stays
        // clickable outside the chat screen.
        this.ensureChatViewOpen();
        this.collapseActiveCallView();
        if (this.voice.roomType === 'channel' && this.voice.roomId) {
            const currentChannelId = String(this.voice.channelId || '').trim();
            if (currentChannelId && currentChannelId !== next) {
                this.leaveVoiceRoom({ announce: true });
            }
        }
        this.cancelComposerContext();
        this.S.activeChannel = next;
        // Selecting the channel makes it visible again — clear whatever unread
        // counter it accrued while it wasn't the active one, mirroring switchChat's
        // S.unread[peer] = 0 for DMs.
        this.S.channelUnread = this.S.channelUnread || {};
        this.S.channelUnread[`${server.id}:${next}`] = 0;
        this.syncTaskbarBadge();
        if (persist) this.saveStoredActiveChannel(next);
        this.saveStoredNavMode('servers');
        this.renderServerToolbar();
        this.requestMessagesScroll('bottom');
        this.scheduleRenderMessages();
        this.updateSendButtonState();
        if (this.isVoiceChannel(channel)) {
            // Selecting a voice channel only opens its panel (with a "Присоединиться"
            // button) — it must NOT auto-connect the call. Auto-joining on click also
            // left the panel stuck rendering the connected-call state after switching
            // to any other channel, since nothing ever re-rendered it away from there.
            this.renderVoicePanel();
            return;
        }
        this.requestMessagesScroll('bottom');
        this.loadServerMessages(server.id, next, { silent: true });
        this.closeMobileSidebar();
        this.syncMobileChrome();
        this.renderVoicePanel();
    }

    setNavMode(mode, { persist = true, refresh = true } = {}) {
        const next = mode === 'servers' ? 'servers' : 'dm';
        this.S.activeConversationType = next;
        if (next === 'servers') {
            this.ensureServersState();
            this.ensureServerSelection();
        } else {
            this.clearActiveServerSelection({ persist });
        }
        if (this.S.navMode === next) {
            this.updateNavModeButtons();
            if (next === 'dm') {
                this.renderServerInterface();
                this.updateSendButtonState();
            }
            return;
        }
        this.S.navMode = next;
        if (persist) {
            this.saveStoredNavMode(next);
        }
        // Returning to the DM view makes the selected chat visible again — clear the
        // unread counter it may have accrued while the servers view was covering it.
        if (next === 'dm' && this.S.current) {
            this.S.unread[this.S.current] = 0;
        }
        // Mirror for the servers view: the already-selected channel becomes visible
        // again, so clear whatever it accrued while the DM view was covering it.
        if (next === 'servers' && this.S.activeServer && this.S.activeChannel) {
            this.S.channelUnread = this.S.channelUnread || {};
            this.S.channelUnread[`${this.S.activeServer}:${this.S.activeChannel}`] = 0;
        }
        this.syncTaskbarBadge();
        this.updateNavModeButtons();
        if (!refresh) return;
        this.resetMessageWindow();
        this.renderServerInterface();
        this.renderContacts();
        this.requestMessagesScroll('bottom');
        this.scheduleRenderMessages();
        this.renderVoicePanel();
        if (next === 'servers' && this.S.activeServer && this.S.activeChannel) {
            this.requestMessagesScroll('bottom');
            this.loadServerMessages(this.S.activeServer, this.S.activeChannel, { silent: true });
        }
        this.syncMobileChrome();
    }
});


// --- MODULE: interface/avatars.js ---
// --- ZaliInterface: Аватары и ассеты серверов: кэш, загрузка, кроппер, даунскейл. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
// Пауза перед повторной попыткой скачать аватар/ассет сервера после
// НЕокончательной неудачи (сеть, таймаут, 5xx). Окончательные ответы
// (404, пустое тело) кэшируются как «нет картинки» и сюда не попадают.
const ZALI_ASSET_RETRY_COOLDOWN_MS = 30_000;

ZaliMixin(ZaliInterface, class {

    avatarCacheKey(username) {
        return String(username || '').trim().toLowerCase();
    }

    loadStoredAvatar(username) {
        const key = this.avatarCacheKey(username);
        if (!this.avatarCache.has(key)) return undefined;
        // Показ засчитывается здесь, потому что здесь он и происходит: это
        // единственное место, откуда аватарка попадает в разметку. Счётчик
        // дедуплицируется по времени (cacheNoteAssetUse), поэтому прокрутка
        // ленты не превращается в тысячу обращений — см. interface/cache.js.
        this.cacheNoteAssetUse('avatar', key);
        return this.avatarCache.get(key);
    }

    // The single place an avatar enters the cache, and therefore the single
    // place that decides what shape it is kept in.
    //
    // Whatever arrives here is normalised to a blob: URL, because this value is
    // inlined into the markup of every contact row and of every incoming message
    // that opens or closes a group. The native bridge hands avatars over as
    // data: URLs, and one 64 KB avatar measured 30 copies of its own base64 —
    // 2.5 MB — inside a single render of a 60-message conversation. A blob: URL
    // is ~40 characters and, unlike a data: URL rebuilt on each innerHTML write,
    // lets the browser reuse the image it already decoded, so avatars stop
    // blinking on unrelated re-renders. The network branch of
    // ensureAvatarLoaded() has always produced a blob: URL; this makes the
    // native branch agree instead of each caller deciding for itself.
    saveStoredAvatar(username, dataUrl) {
        const key = this.avatarCacheKey(username);
        const next = this.toAvatarObjectUrl(dataUrl);
        const prev = this.avatarCache.get(key);
        if (prev && typeof prev === 'string' && prev.startsWith('blob:') && prev !== next) {
            try { URL.revokeObjectURL(prev); } catch (e) {}
        }
        this.avatarFetchSeq.set(key, (this.avatarFetchSeq.get(key) || 0) + 1);
        this.avatarCache.set(key, next || null);
    }

    toAvatarObjectUrl(value) {
        const source = String(value || '');
        if (!source.startsWith('data:')) return value;
        const blob = this.dataUrlToBlob(source);
        if (!blob) return value;
        try {
            return URL.createObjectURL(blob);
        } catch (e) {
            return value;
        }
    }

    clearStoredAvatar(username) {
        const key = this.avatarCacheKey(username);
        const prev = this.avatarCache.get(key);
        if (prev && typeof prev === 'string' && prev.startsWith('blob:')) {
            try { URL.revokeObjectURL(prev); } catch (e) {}
        }
        this.avatarFetchSeq.set(key, (this.avatarFetchSeq.get(key) || 0) + 1);
        this.avatarCache.delete(key);
        // Инвалидация обязана доходить до диска: без этого handleAvatarUpdated()
        // сбрасывал бы только память, а перезагрузка возвращала прежнюю картинку.
        void this.cacheDelete('avatar', key);
    }

    avatarFallback(username) {
        const value = String(username || '').trim();
        return value ? value[0].toUpperCase() : 'Z';
    }

    renderAvatarHTML(username, className = 'ava', alt = '') {
        const src = this.loadStoredAvatar(username);
        const fallback = this.avatarFallback(username);
        const safeAlt = this.esc(alt || username || fallback);
        if (src === undefined) {
            this.ensureAvatarLoaded(username);
        } else if (src) {
            const classes = String(className || '')
                .split(/\s+/)
                .filter(Boolean)
                .concat('avatar-img')
                .filter((v, i, arr) => arr.indexOf(v) === i)
                .join(' ');
            return `<img class="${classes}" src="${this.esc(src)}" alt="${safeAlt}">`;
        }
        return `<span class="avatar-fallback">${this.esc(fallback)}</span>`;
    }

    serverAssetCacheKey(serverId, kind) {
        return `${String(serverId || '').trim()}:${kind}`;
    }

    async loadServerAsset(serverId, kind, { force = false } = {}) {
        const sid = String(serverId || '').trim();
        if (!sid) return null;
        const key = this.serverAssetCacheKey(sid, kind);
        if (!force && this.serverAssetCache.has(key)) {
            this.cacheNoteAssetUse('server_asset', key);
            return this.serverAssetCache.get(key);
        }
        if (this.serverAssetRequests.has(key) && !force) {
            return this.serverAssetRequests.get(key);
        }
        // Неудача, после которой в кэше ничего не остаётся, — это приглашение
        // спросить снова на следующей же отрисовке. А отрисовка вызывается из
        // .then() этого самого запроса, так что один упавший ассет
        // раскручивает бесконечный цикл «отрисовка → запрос → отрисовка»,
        // ограниченный только временем ответа сервера. Пауза разрывает его,
        // не превращая временную ошибку в вечное «картинки нет».
        if (!force) {
            const retryAt = this.serverAssetRetryAt.get(key) || 0;
            if (retryAt && Date.now() < retryAt) return null;
        }

        const seq = (this.serverAssetFetchSeq.get(key) || 0) + 1;
        this.serverAssetFetchSeq.set(key, seq);

        const request = (async () => {
            try {
                // Диск раньше сети — та же логика, что у аватарок. Иконка и
                // баннер сервера рисуются в рейле, в шапке чата и в модалке
                // публичных серверов, то есть на каждой отрисовке; тянуть их
                // по сети на каждом запуске незачем.
                if (!force) {
                    const cached = await this.cacheGet('server_asset', key);
                    if (cached) {
                        if (this.serverAssetFetchSeq.get(key) !== seq) return null;
                        const cachedUrl = URL.createObjectURL(cached);
                        this.serverAssetRetryAt.delete(key);
                        this.serverAssetCache.set(key, cachedUrl);
                        if (this.cacheIsStale('server_asset', key)) {
                            setTimeout(() => { void this.loadServerAsset(sid, kind, { force: true }); }, 0);
                        }
                        return cachedUrl;
                    }
                }

                // Binary body — see TRANSFER_REQUEST_TIMEOUT_MS.
                const res = await this.apiFetch(this.apiRoutes.servers.assets(sid, kind), {
                    timeoutMs: TRANSFER_REQUEST_TIMEOUT_MS,
                });
                if (this.serverAssetFetchSeq.get(key) !== seq) return null;
                if (res.status === 404) {
                    this.serverAssetRetryAt.delete(key);
                    this.serverAssetCache.set(key, null);
                    void this.cacheDelete('server_asset', key);
                    return null;
                }
                if (!res.ok) {
                    this.serverAssetRetryAt.set(key, Date.now() + ZALI_ASSET_RETRY_COOLDOWN_MS);
                    return null;
                }
                const blob = await res.blob();
                if (!blob || blob.size === 0) {
                    this.serverAssetRetryAt.delete(key);
                    this.serverAssetCache.set(key, null);
                    void this.cacheDelete('server_asset', key);
                    return null;
                }
                const url = await this.blobToObjectUrl(blob);
                this.serverAssetRetryAt.delete(key);
                this.serverAssetCache.set(key, url);
                void this.cachePut('server_asset', key, blob);
                return url;
            } catch (e) {
                this.serverAssetRetryAt.set(key, Date.now() + ZALI_ASSET_RETRY_COOLDOWN_MS);
                return null;
            } finally {
                if (this.serverAssetRequests.get(key) === request) {
                    this.serverAssetRequests.delete(key);
                }
            }
        })();

        this.serverAssetRequests.set(key, request);
        return request;
    }

    clearServerAssetCache(serverId, kind) {
        const key = this.serverAssetCacheKey(serverId, kind);
        const prev = this.serverAssetCache.get(key);
        if (prev && typeof prev === 'string' && prev.startsWith('blob:')) {
            try { URL.revokeObjectURL(prev); } catch (e) {}
        }
        this.serverAssetFetchSeq.set(key, (this.serverAssetFetchSeq.get(key) || 0) + 1);
        this.serverAssetRetryAt.delete(key);
        this.serverAssetCache.delete(key);
        void this.cacheDelete('server_asset', key);
    }

    serverAssetFallback(server, kind) {
        if (kind === 'avatar') {
            return this.esc(server?.icon || server?.name?.[0] || 'S');
        }
        return this.esc((server?.name || 'BAN').slice(0, 3).toUpperCase());
    }

    serverAvatarBackground(server) {
        return this.safeCssColor(server?.color) || 'linear-gradient(180deg, #cbff00, #8c8c8c)';
    }

    // Shared by the server rail, the public-servers modal, and the chat header —
    // those used to fall back to the icon/color forever and never rendered the
    // uploaded server avatar image; only the settings-modal preview did.
    serverAvatarInnerHTML(server) {
        const id = String(server?.id || '').trim();
        const fallback = () => this.esc(server?.icon || server?.name?.[0] || 'S');
        if (!id) return fallback();
        const key = this.serverAssetCacheKey(id, 'avatar');
        if (!this.serverAssetCache.has(key)) {
            // Перерисовываем, только когда картинка реально приехала. Раньше
            // .then() дёргал отрисовку на ЛЮБОМ исходе, включая неудачу, —
            // а отрисовка снова звала загрузку: вторая половина того же цикла.
            this.loadServerAsset(id, 'avatar').then(url => { if (url) this.scheduleServerAssetRefresh(); });
            return fallback();
        }
        const cached = this.serverAssetCache.get(key);
        if (!cached) return fallback();
        this.cacheNoteAssetUse('server_asset', key);
        return `<img class="avatar-img" src="${this.esc(cached)}" alt="${this.esc(server?.name || '')}">`;
    }

    renderServerAvatarHTML(server, extraClass = '') {
        const classes = `server-avatar${extraClass ? ` ${extraClass}` : ''}`;
        return `<span class="${classes}" style="background:${this.serverAvatarBackground(server)}">${this.serverAvatarInnerHTML(server)}</span>`;
    }

    // Защёлка снимается ТЕМ ЖЕ вызовом, который делает работу, и работа
    // назначена двумя путями: requestAnimationFrame не срабатывает, пока окно
    // скрыто или свёрнуто, а защёлка ставится до него — один кадр, пришедший
    // в скрытом окне, оставлял её взведённой навсегда, и после возврата к
    // приложению аватарки серверов больше не обновлялись до перезагрузки.
    scheduleServerAssetRefresh() {
        if (this.serverAssetRefreshScheduled) return;
        this.serverAssetRefreshScheduled = true;
        const run = () => {
            if (!this.serverAssetRefreshScheduled) return;
            this.serverAssetRefreshScheduled = false;
            this.renderServers();
            this.renderServerToolbar();
        };
        requestAnimationFrame(run);
        setTimeout(run, 250);
    }

    resetServerAssetPreview() {
        const avatarBox = document.getElementById('serverAvatarPreview');
        const bannerBox = document.getElementById('serverBannerPreview');
        if (avatarBox) {
            avatarBox.innerHTML = '';
            avatarBox.style.backgroundImage = '';
            avatarBox.textContent = 'S';
        }
        if (bannerBox) {
            bannerBox.innerHTML = '';
            bannerBox.style.backgroundImage = '';
            bannerBox.style.backgroundSize = '';
            bannerBox.style.backgroundPosition = '';
            bannerBox.textContent = 'BAN';
        }
    }

    async syncServerAssetPreview(serverId) {
        const sid = String(serverId || '').trim();
        const avatar = await this.loadServerAsset(serverId, 'avatar');
        const banner = await this.loadServerAsset(serverId, 'banner');
        const avatarBox = document.getElementById('serverAvatarPreview');
        const bannerBox = document.getElementById('serverBannerPreview');
        const server = (this.S.servers || []).find(item => item.id === sid) || null;
        if (avatarBox) {
            avatarBox.style.backgroundImage = '';
            if (avatar) {
                avatarBox.innerHTML = `<img class="avatar-img" src="${this.esc(avatar)}" alt="server avatar">`;
            } else {
                avatarBox.innerHTML = '';
                avatarBox.textContent = this.serverAssetFallback(server, 'avatar');
            }
        }
        if (bannerBox) {
            if (banner) {
                bannerBox.innerHTML = '';
                bannerBox.style.backgroundImage = `url('${this.esc(banner)}')`;
                bannerBox.style.backgroundSize = 'cover';
                bannerBox.style.backgroundPosition = 'center';
            } else {
                bannerBox.style.backgroundImage = '';
                bannerBox.innerHTML = '';
                bannerBox.textContent = this.serverAssetFallback(server, 'banner');
            }
        }
    }

    // Тот же двойной путь, что и у scheduleServerAssetRefresh: иначе аватарка,
    // доехавшая в скрытом окне, взводит защёлку навсегда.
    scheduleAvatarRefresh() {
        if (this.avatarRefreshScheduled) return;
        this.avatarRefreshScheduled = true;
        const run = () => {
            if (!this.avatarRefreshScheduled) return;
            this.avatarRefreshScheduled = false;
            this.renderSidebarProfile();
            this.renderContacts();
            // The chat header avatar (own avatar in the empty/DM state, peer avatar in a
            // DM) is rendered by renderServerToolbar; without refreshing it here it keeps
            // the fallback letter it drew before the avatar finished loading async.
            this.renderServerToolbar();
        };
        requestAnimationFrame(run);
        setTimeout(run, 250);
    }

    updateAvatarViews() {
        this.renderSidebarProfile();
        this.renderContacts();
        this.renderServerToolbar();
        this.scheduleRenderMessages();
    }

    refreshVisibleAvatars() {
        if (document.hidden) return;
        if (this.nativeSupports('serverHistory') && this.nativeSupports('voice') && this.nativeSupports('downloadAttachment')) return;
        const users = new Set([this.myName(), this.S.current, ...(this.S.contacts || [])].filter(Boolean));
        document.querySelectorAll('.avatar-img[alt]').forEach(img => {
            const name = String(img.getAttribute('alt') || '').trim();
            if (name) users.add(name);
        });
        users.forEach(username => {
            this.ensureAvatarLoaded(username);
        });
    }

    async blobToObjectUrl(blob) {
        return URL.createObjectURL(blob);
    }

    dataUrlToBlob(dataUrl) {
        const value = String(dataUrl || '').trim();
        if (!value.startsWith('data:')) return null;

        const commaIndex = value.indexOf(',');
        if (commaIndex < 0) return null;

        const meta = value.slice(5, commaIndex);
        const payload = value.slice(commaIndex + 1);
        const parts = meta.split(';').filter(Boolean);
        const mimeType = parts[0] || 'application/octet-stream';
        const isBase64 = parts.includes('base64');

        try {
            if (isBase64) {
                const binary = atob(payload);
                const bytes = new Uint8Array(binary.length);
                for (let i = 0; i < binary.length; i += 1) {
                    bytes[i] = binary.charCodeAt(i);
                }
                return new Blob([bytes], { type: mimeType });
            }

            return new Blob([decodeURIComponent(payload)], { type: mimeType });
        } catch (error) {
            console.error('Failed to decode data URL', error);
            return null;
        }
    }

    async downloadAttachmentFromHref(href, filename) {
        const source = String(href || '').trim();
        const safeName = String(filename || 'attachment').trim() || 'attachment';
        if (!source) return false;

        // Attachments are rendered through a blob: URL (attachmentDisplayUrl), so
        // the href on the link is no longer the payload. The native save bridge
        // wants the payload — recover it from the same map that minted the URL,
        // otherwise a native shell would silently fall through to the browser
        // `<a download>` path, which WKWebView/WebView2 do not honour.
        const nativePayload = source.startsWith('data:')
            ? source
            : (this._attachmentBlobPayloads?.get(source) || '');
        if (this.nativeSupports('downloadAttachment') && nativePayload) {
            this.postNativeMessage({
                type: NativeMessageTypes.DOWNLOAD_ATTACHMENT,
                dataUrl: nativePayload,
                filename: safeName,
            });
            return true;
        }

        let objectUrl = source;
        let shouldRevoke = false;

        try {
            if (source.startsWith('data:')) {
                const blob = this.dataUrlToBlob(source);
                if (!blob || blob.size === 0) {
                    throw new Error('Empty attachment payload');
                }
                objectUrl = URL.createObjectURL(blob);
                shouldRevoke = true;
            } else if (!source.startsWith('blob:')) {
                const response = await fetch(source);
                if (!response.ok) {
                    throw new Error(`Unexpected response while downloading attachment: ${response.status}`);
                }
                const blob = await response.blob();
                if (!blob || blob.size === 0) {
                    throw new Error('Empty attachment payload');
                }
                objectUrl = URL.createObjectURL(blob);
                shouldRevoke = true;
            }

            const link = document.createElement('a');
            link.href = objectUrl;
            link.download = safeName;
            link.rel = 'noopener';
            link.style.display = 'none';
            document.body.appendChild(link);
            link.click();
            link.remove();

            if (shouldRevoke) {
                setTimeout(() => {
                    try { URL.revokeObjectURL(objectUrl); } catch (e) {}
                }, 1000);
            }

            return true;
        } catch (error) {
            console.error('Failed to download attachment', error);
            return false;
        }
    }

    async ensureAvatarLoaded(username, { force = false } = {}) {
        const name = String(username || '').trim();
        if (!name) return null;
        const key = this.avatarCacheKey(name);
        if (!force && this.avatarCache.has(key)) {
            return this.avatarCache.get(key);
        }
        if (!force) {
            const retryAt = this.avatarRetryAt.get(key) || 0;
            if (retryAt && Date.now() < retryAt) return null;
        }
        if (this.avatarRequests.has(key)) {
            if (!force) {
                return this.avatarRequests.get(key);
            }
        }

        const seq = (this.avatarFetchSeq.get(key) || 0) + 1;
        this.avatarFetchSeq.set(key, seq);

        const request = (async () => {
            try {
                // Диск раньше сети. Это и есть лечение «аватарки требуют
                // подгрузки»: до этого кеш жил в Map и умирал вместе со
                // страницей, поэтому каждый запуск заново качал аватарку
                // каждого контакта. Запись при этом не считается свежей
                // навсегда — устаревшую перепроверяем в фоне, уже показав
                // картинку, а событие avatar_updated сбрасывает её сразу.
                if (!force) {
                    const cached = await this.cacheGet('avatar', key);
                    if (cached) {
                        if (this.avatarFetchSeq.get(key) !== seq) return null;
                        this.saveStoredAvatar(name, URL.createObjectURL(cached));
                        this.scheduleAvatarRefresh();
                        if (this.cacheIsStale('avatar', key)) {
                            setTimeout(() => { void this.ensureAvatarLoaded(name, { force: true }); }, 0);
                        }
                        return this.loadStoredAvatar(name);
                    }
                }

                if (this.nativeSupports('avatarFetch')) {
                    try {
                        const payload = await this.requestNativeAction({
                            type: NativeMessageTypes.LOAD_AVATAR_REQUEST,
                            username: name,
                        });
                        if (this.avatarFetchSeq.get(key) !== seq) {
                            return null;
                        }
                        const dataUrl = String(payload?.data?.dataUrl || '').trim();
                        if (!dataUrl) {
                            this.saveStoredAvatar(name, null);
                            this.scheduleAvatarRefresh();
                            return null;
                        }
                        // saveStoredAvatar() converts the bridge's data: URL to a
                        // blob: one and returns it through the cache — see the
                        // comment there for why the payload must not survive
                        // into the markup.
                        this.saveStoredAvatar(name, dataUrl);
                        void this.cachePut('avatar', key, dataUrl);
                        this.scheduleAvatarRefresh();
                        return this.loadStoredAvatar(name);
                    } catch (nativeError) {
                        this.trace(`ensureAvatarLoaded native failed username=${name} err=${nativeError?.message || nativeError}`);
                    }
                }

                // Binary body — see TRANSFER_REQUEST_TIMEOUT_MS.
                const res = await this.apiFetch(this.apiRoutes.avatar.byUsername(name), {
                    timeoutMs: TRANSFER_REQUEST_TIMEOUT_MS,
                });
                if (this.avatarFetchSeq.get(key) !== seq) {
                    return null;
                }
                if (res.status === 404) {
                    this.saveStoredAvatar(name, null);
                    // Аватарку сняли — снимаем и с диска, иначе следующий
                    // запуск поднял бы её из кеша и показывал бы удалённую
                    // картинку до самого истечения срока перепроверки.
                    void this.cacheDelete('avatar', key);
                    this.scheduleAvatarRefresh();
                    return null;
                }
                if (!res.ok) {
                    this.avatarRetryAt.set(key, Date.now() + ZALI_ASSET_RETRY_COOLDOWN_MS);
                    return null;
                }

                const blob = await res.blob();
                if (this.avatarFetchSeq.get(key) !== seq) {
                    return null;
                }
                if (!blob || blob.size === 0) {
                    this.saveStoredAvatar(name, null);
                    this.scheduleAvatarRefresh();
                    return null;
                }

                const url = await this.blobToObjectUrl(blob);
                if (this.avatarFetchSeq.get(key) !== seq) {
                    try { URL.revokeObjectURL(url); } catch (e) {}
                    return null;
                }
                this.avatarRetryAt.delete(key);
                this.saveStoredAvatar(name, url);
                void this.cachePut('avatar', key, blob);
                this.scheduleAvatarRefresh();
                return url;
            } catch (e) {
                this.avatarRetryAt.set(key, Date.now() + ZALI_ASSET_RETRY_COOLDOWN_MS);
                return null;
            } finally {
                if (this.avatarRequests.get(key) === request) {
                    this.avatarRequests.delete(key);
                }
            }
        })();

        this.avatarRequests.set(key, request);
        return request;
    }

    renderSidebarProfile() {
        const meName = document.getElementById('meName');
        const meSub = document.getElementById('meSub');
        const meAva = document.getElementById('meAva');
        const avatarPreview = document.getElementById('avatarPreview');
        const username = this.myName();
        if (meName) meName.textContent = username;
        if (meAva) this.setHTMLIfChanged(meAva, this.renderAvatarHTML(username, 'avatar-img', username));
        if (avatarPreview) {
            this.setHTMLIfChanged(avatarPreview, this.renderAvatarHTML(username, 'avatar-img', username));
            avatarPreview.title = `Ваш аватар: ${username}`;
        }
        this.ensureAvatarLoaded(username);
        if (meSub) {
            meSub.innerHTML = this.S.session?.token
                ? '<span class="online-dot"></span> В сети'
                : '<span class="online-dot guest"></span> Гостевой режим';
        }
        this.updateContactControls();
        this.renderContactSuggestions();
        this.updateNavModeButtons();
        this.ensureServersState();
    }

    readFileAsDataURL(file) {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => resolve(String(reader.result || ''));
            reader.onerror = () => reject(new Error('Не удалось прочитать файл'));
            reader.readAsDataURL(file);
        });
    }

    // Shared re-encode-to-JPEG core: iterates dimension/quality attempts down until the
    // encoded bytes fit targetBytes, keeping the largest/best-quality result that fits.
    // Best-effort: returns the original file if the canvas pipeline is unavailable or
    // nothing beats the original size.
    async downscaleImageFile(file, { targetBytes, attempts, baseNameFallback = 'image', traceLabel = 'downscaleImage' }) {
        try {
            if (typeof document === 'undefined' || typeof document.createElement !== 'function') return file;
            const dataUrl = await this.readFileAsDataURL(file);
            const img = await new Promise((resolve, reject) => {
                const im = new Image();
                im.onload = () => resolve(im);
                im.onerror = () => reject(new Error('decode failed'));
                im.src = dataUrl;
            });
            const w = img.naturalWidth || img.width;
            const h = img.naturalHeight || img.height;
            if (!w || !h) return file;
            const baseName = String(file.name || baseNameFallback).replace(/\.[^.]+$/, '') || baseNameFallback;
            const encode = async (dim, q) => {
                const scale = Math.min(1, dim / Math.max(w, h));
                const cw = Math.max(1, Math.round(w * scale));
                const ch = Math.max(1, Math.round(h * scale));
                const canvas = document.createElement('canvas');
                canvas.width = cw;
                canvas.height = ch;
                const ctx = canvas.getContext('2d');
                if (!ctx) return null;
                ctx.drawImage(img, 0, 0, cw, ch);
                return await new Promise((resolve) => canvas.toBlob(resolve, 'image/jpeg', q));
            };
            // Progressively smaller/lower-quality until under budget. Ordered largest→smallest
            // so we keep the best quality that still fits.
            let best = null;
            for (const [dim, q] of attempts) {
                const blob = await encode(dim, q);
                if (!blob || blob.size === 0) continue;
                best = blob;
                if (blob.size <= targetBytes) break;
            }
            if (!best || best.size >= file.size) {
                // Couldn't beat the original (already tiny, or encode unavailable).
                if (best && best.size < file.size) {
                    return new File([best], `${baseName}.jpg`, { type: 'image/jpeg' });
                }
                return file;
            }
            this.trace(`${traceLabel} ${file.size}B -> ${best.size}B`);
            return new File([best], `${baseName}.jpg`, { type: 'image/jpeg' });
        } catch (e) {
            this.trace(`${traceLabel} failed, using original: ${e?.message || e}`);
            return file;
        }
    }

    // Re-encode an avatar to a SMALL JPEG before upload, iterating dimension/quality
    // down until the encoded bytes fit a tight budget (~14 KB). Avatars render as tiny
    // circles, so this costs no visible quality — and it is the difference between the
    // avatar loading or not over a low-MTU / lossy path (e.g. a VPN with MTU 1280):
    // there the server's response stalls once it exceeds roughly the TCP initial window
    // (~12–30 KB with MSS 1240), so a 31 KB avatar never finishes downloading while a
    // ~10 KB one arrives in the first round-trip.
    async downscaleAvatarFile(file, targetBytes = 14 * 1024) {
        const attempts = [[256, 0.8], [224, 0.72], [192, 0.66], [160, 0.62], [128, 0.6], [96, 0.55]];
        return this.downscaleImageFile(file, { targetBytes, attempts, baseNameFallback: 'avatar', traceLabel: 'downscaleAvatar' });
    }

    // Same idea as downscaleAvatarFile but tuned for a wide server banner/cover image
    // instead of a tiny round avatar: much larger max dimension and byte budget, since a
    // banner needs to stay legible at full width. Server avatar/banner uploads used to
    // skip downscaling entirely and PUT the raw picked file (often several MB straight
    // off a camera) as a base64 JSON body through the generic API-request path, which
    // carries a fixed ~8-12s timeout meant for ordinary JSON calls — large enough images
    // (or a slow/VPN-throttled link) blew that budget and surfaced as a raw transport
    // error ("error sending request for url ...") instead of a real upload failure.
    async downscaleServerAssetFile(file, kind) {
        if (kind === 'avatar') {
            const attempts = [[512, 0.82], [384, 0.75], [256, 0.7], [192, 0.65]];
            return this.downscaleImageFile(file, { targetBytes: 60 * 1024, attempts, baseNameFallback: 'server-avatar', traceLabel: 'downscaleServerAvatar' });
        }
        const attempts = [[1600, 0.82], [1280, 0.78], [1024, 0.72], [768, 0.66], [512, 0.6]];
        return this.downscaleImageFile(file, { targetBytes: 300 * 1024, attempts, baseNameFallback: 'server-banner', traceLabel: 'downscaleServerBanner' });
    }

    // Interactive pan/zoom crop before upload. Without this, a fixed center-square
    // crop can slice straight through whatever the source photo happens to frame at
    // its edges (e.g. a vignette/fisheye shot), producing a circle avatar that reads
    // as "cropped into a strange shape" instead of a clean headshot. Resolves to a
    // square JPEG File, or null if the user cancels.
    openAvatarCropper(file) {
        return new Promise((resolve) => {
            const overlay = document.getElementById('avatarCropOverlay');
            const stage = document.getElementById('avatarCropStage');
            const img = document.getElementById('avatarCropImg');
            const circleGuide = document.getElementById('avatarCropCircleGuide');
            const zoomInput = document.getElementById('avatarCropZoom');
            const saveBtn = document.getElementById('avatarCropSaveBtn');
            const cancelBtn = document.getElementById('avatarCropCancelBtn');
            const closeBtn = document.getElementById('avatarCropCloseBtn');
            if (!overlay || !stage || !img || !circleGuide || !zoomInput || !saveBtn || !cancelBtn || !closeBtn) {
                resolve(null);
                return;
            }

            const objectUrl = URL.createObjectURL(file);
            // left/top position the image relative to the SQUARE stage, but coverage
            // is only required over the circle guide inset within it — the ring
            // between circle and stage edge is deliberately allowed to show
            // (dimmed) whatever part of the photo falls outside the crop.
            const state = { scale: 1, minScale: 1, maxScale: 1, left: 0, top: 0, naturalW: 0, naturalH: 0 };
            const listeners = [];
            const on = (el, type, handler, opts) => {
                el.addEventListener(type, handler, opts);
                listeners.push(() => el.removeEventListener(type, handler, opts));
            };

            let settled = false;
            const finish = (result) => {
                if (settled) return;
                settled = true;
                listeners.forEach(off => off());
                overlay.classList.remove('visible');
                setTimeout(() => { overlay.hidden = true; }, 180);
                URL.revokeObjectURL(objectUrl);
                img.removeAttribute('src');
                resolve(result);
            };

            const clamp = (value, min, max) => Math.min(max, Math.max(min, value));

            const circleBounds = () => {
                const stageSize = stage.clientWidth;
                const circleSize = circleGuide.clientWidth || stageSize;
                const margin = (stageSize - circleSize) / 2;
                return { stageSize, circleSize, margin };
            };

            const applyTransform = () => {
                img.style.width = `${state.naturalW * state.scale}px`;
                img.style.height = `${state.naturalH * state.scale}px`;
                img.style.left = `${state.left}px`;
                img.style.top = `${state.top}px`;
            };

            const clampPosition = () => {
                const { circleSize, margin } = circleBounds();
                const displayedW = state.naturalW * state.scale;
                const displayedH = state.naturalH * state.scale;
                state.left = clamp(state.left, margin + circleSize - displayedW, margin);
                state.top = clamp(state.top, margin + circleSize - displayedH, margin);
            };

            const setScale = (nextScale, focalStageX, focalStageY) => {
                const { stageSize } = circleBounds();
                const fx = focalStageX ?? stageSize / 2;
                const fy = focalStageY ?? stageSize / 2;
                const prevScale = state.scale;
                // Keep the point under the focal coordinate stable while zooming.
                const naturalFocalX = (fx - state.left) / prevScale;
                const naturalFocalY = (fy - state.top) / prevScale;
                state.scale = clamp(nextScale, state.minScale, state.maxScale);
                state.left = fx - naturalFocalX * state.scale;
                state.top = fy - naturalFocalY * state.scale;
                clampPosition();
                applyTransform();
            };

            img.onload = () => {
                // Unhide first — stage/circleGuide report clientWidth 0 while
                // display:none, which would collapse every size computed below.
                overlay.hidden = false;

                state.naturalW = img.naturalWidth || 1;
                state.naturalH = img.naturalHeight || 1;
                const { stageSize, circleSize } = circleBounds();
                state.minScale = circleSize / Math.min(state.naturalW, state.naturalH);
                state.maxScale = state.minScale * 3;
                state.scale = state.minScale;
                state.left = (stageSize - state.naturalW * state.scale) / 2;
                state.top = (stageSize - state.naturalH * state.scale) / 2;
                applyTransform();
                zoomInput.min = '0';
                zoomInput.max = '1000';
                zoomInput.value = '0';

                requestAnimationFrame(() => overlay.classList.add('visible'));
            };
            img.onerror = () => finish(null);
            img.src = objectUrl;

            on(zoomInput, 'input', () => {
                const t = Number(zoomInput.value) / 1000;
                setScale(state.minScale + t * (state.maxScale - state.minScale));
            });

            let dragging = false;
            let dragStartX = 0;
            let dragStartY = 0;
            let dragStartLeft = 0;
            let dragStartTop = 0;

            on(stage, 'pointerdown', (e) => {
                dragging = true;
                stage.classList.add('dragging');
                stage.setPointerCapture?.(e.pointerId);
                dragStartX = e.clientX;
                dragStartY = e.clientY;
                dragStartLeft = state.left;
                dragStartTop = state.top;
            });
            on(stage, 'pointermove', (e) => {
                if (!dragging) return;
                state.left = dragStartLeft + (e.clientX - dragStartX);
                state.top = dragStartTop + (e.clientY - dragStartY);
                clampPosition();
                applyTransform();
            });
            const stopDrag = (e) => {
                dragging = false;
                stage.classList.remove('dragging');
                if (e && stage.releasePointerCapture) {
                    try { stage.releasePointerCapture(e.pointerId); } catch (err) { /* noop */ }
                }
            };
            on(stage, 'pointerup', stopDrag);
            on(stage, 'pointercancel', stopDrag);
            on(stage, 'wheel', (e) => {
                e.preventDefault();
                const rect = stage.getBoundingClientRect();
                const focalX = e.clientX - rect.left;
                const focalY = e.clientY - rect.top;
                const factor = Math.exp(-e.deltaY * 0.0015);
                setScale(state.scale * factor, focalX, focalY);
                const t = (state.scale - state.minScale) / (state.maxScale - state.minScale || 1);
                zoomInput.value = String(Math.round(clamp(t, 0, 1) * 1000));
            }, { passive: false });

            on(cancelBtn, 'click', () => finish(null));
            on(closeBtn, 'click', () => finish(null));
            on(document, 'keydown', (e) => {
                if (e.key === 'Escape') finish(null);
            });
            on(saveBtn, 'click', () => {
                const { circleSize, margin } = circleBounds();
                const OUTPUT_SIZE = 512;
                const sx = (margin - state.left) / state.scale;
                const sy = (margin - state.top) / state.scale;
                const sSize = circleSize / state.scale;
                const canvas = document.createElement('canvas');
                canvas.width = OUTPUT_SIZE;
                canvas.height = OUTPUT_SIZE;
                const ctx = canvas.getContext('2d');
                if (!ctx) { finish(file); return; }
                ctx.drawImage(img, sx, sy, sSize, sSize, 0, 0, OUTPUT_SIZE, OUTPUT_SIZE);
                canvas.toBlob((blob) => {
                    if (!blob) { finish(file); return; }
                    const baseName = String(file.name || 'avatar').replace(/\.[^.]+$/, '') || 'avatar';
                    finish(new File([blob], `${baseName}.jpg`, { type: 'image/jpeg' }));
                }, 'image/jpeg', 0.92);
            });
        });
    }

    async setProfileAvatar(inputFile) {
        if (!inputFile) return;
        const target = String(this.myName()).trim();
        if (!inputFile.type || !inputFile.type.startsWith('image/')) {
            throw new Error('Нужен файл изображения');
        }
        const MAX_AVATAR_BYTES = 2 * 1024 * 1024;
        if (inputFile.size > MAX_AVATAR_BYTES) {
            throw new Error('Аватар слишком большой. Выберите изображение до 2 МБ');
        }
        const file = await this.downscaleAvatarFile(inputFile);
        if (this.hasNativeAvatarBridge()) {
            const dataUrl = await this.readFileAsDataURL(file);
            await this.requestNativeAction({
                type: NativeMessageTypes.UPLOAD_AVATAR_REQUEST,
                dataUrl,
                mimeType: file.type || 'image/png',
                filename: file.name || 'avatar.png',
            });
            const objectUrl = URL.createObjectURL(file);
            this.saveStoredAvatar(target, objectUrl);
            this.updateAvatarViews();
            return;
        }
        const formData = new FormData();
        formData.append('file', file, file.name || 'avatar.png');
        const res = await this.apiFetch(this.apiRoutes.avatar.base, {
            method: 'POST',
            body: formData,
        });
        if (!res.ok) {
            throw new Error(await res.text() || 'Не удалось сохранить аватар на сервере');
        }
        const objectUrl = URL.createObjectURL(file);
        this.saveStoredAvatar(target, objectUrl);
        this.updateAvatarViews();
    }

    async resetProfileAvatar() {
        const target = String(this.myName()).trim();
        if (this.hasNativeAvatarBridge()) {
            await this.requestNativeAction({
                type: NativeMessageTypes.DELETE_AVATAR_REQUEST,
            });
            this.saveStoredAvatar(target, null);
            this.updateAvatarViews();
            return;
        }
        const res = await this.apiFetch(this.apiRoutes.avatar.base, { method: 'DELETE' });
        if (!res.ok && res.status !== 204) {
            throw new Error(await res.text() || 'Не удалось удалить аватар на сервере');
        }
        this.saveStoredAvatar(target, null);
        this.updateAvatarViews();
    }
});


// --- MODULE: interface/api.js ---
// --- ZaliInterface: HTTP-конвейер: заголовки, слоты параллелизма, apiFetch. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    apiHeaders(extra = {}, { includeDeviceId = false } = {}) {
        const headers = { ...extra };
        if (this.S.session?.token && !headers.Authorization) {
            headers.Authorization = `Bearer ${this.S.session.token}`;
        }
        const deviceId = includeDeviceId ? this.currentDeviceId() : '';
        if (deviceId) {
            headers['X-Zali-Device-ID'] = deviceId;
        }
        return headers;
    }

    /**
     * Ответ нативного моста в оболочке, совместимой с `fetch`.
     *
     * **Почему у ответа два тела.** Мост — это JSON-канал, по нему ходят строки.
     * Пока бинарные ответы ехали тем же полем `body`, что и текстовые, они
     * необратимо портились: на macOS `String(data:encoding:.utf8)` возвращает nil
     * на первом же байте PNG, который не является валидным UTF-8, — тело
     * приезжало ПУСТЫМ; на Android `body.string()` подставляет replacement-символы
     * — тело приезжало битым. `res.blob()` при этом честно заворачивал строку в
     * Blob, и картинка не открывалась. Так на всех нативных оболочках молча не
     * работали иконки и баннеры серверов (`loadServerAsset`) — единственное место,
     * где через мост шёл настоящий бинарь, — а `res.arrayBuffer()` вообще
     * отсутствовал, из-за чего браузерный путь скачивания архива был на нативе
     * нерабочим в принципе.
     *
     * Теперь оболочка сама решает по Content-Type: текст едет в `body`, всё
     * остальное — в `bodyBase64`. Старое поле осталось на месте, поэтому свежий
     * веб на старой оболочке ведёт себя ровно как раньше.
     */
    nativeApiResponse(payload) {
        const data = payload?.data && typeof payload.data === 'object' ? payload.data : {};
        const status = Number(data.status || 0) || 0;
        const body = String(data.body || '');
        const bodyBase64 = typeof data.bodyBase64 === 'string' ? data.bodyBase64 : '';
        const headers = data.headers && typeof data.headers === 'object' ? data.headers : {};
        const contentType = String(headers['content-type'] || headers['Content-Type'] || 'application/octet-stream');

        // Декодируется один раз и лениво: у текстовых ответов (то есть почти у всех)
        // этот путь не исполняется вовсе.
        let bytes = null;
        const asBytes = () => {
            if (bytes) return bytes;
            if (bodyBase64) {
                try {
                    const binary = atob(bodyBase64);
                    const out = new Uint8Array(binary.length);
                    for (let i = 0; i < binary.length; i += 1) out[i] = binary.charCodeAt(i);
                    bytes = out;
                } catch (e) {
                    bytes = new Uint8Array(0);
                }
            } else {
                bytes = new TextEncoder().encode(body);
            }
            return bytes;
        };
        const asText = () => (bodyBase64 ? new TextDecoder().decode(asBytes()) : body);

        return {
            ok: !!data.ok || (status >= 200 && status < 300),
            status,
            headers,
            text: async () => asText(),
            json: async () => JSON.parse(asText() || 'null'),
            arrayBuffer: async () => {
                const view = asBytes();
                return view.buffer.slice(view.byteOffset, view.byteOffset + view.byteLength);
            },
            blob: async () => new Blob([asBytes()], { type: contentType }),
        };
    }

    async nativeApiFetch(path, { method = 'GET', headers = {}, body = null, includeDeviceId = false, timeoutMs = API_REQUEST_TIMEOUT_MS } = {}) {
        // Native owns the per-attempt timeout AND the retry, because only it can force a
        // brand-new connection (a half-open HTTP/2 connection is otherwise reused and
        // stalls again). Give the JS bridge a generous abandon timeout so it does not
        // give up before native has finished its short retries.
        const payload = await this.requestNativeAction({
            type: NativeMessageTypes.API_REQUEST,
            method,
            path,
            headers,
            body: typeof body === 'string' ? body : '',
            includeDeviceId: !!includeDeviceId,
            timeoutMs,
        }, timeoutMs + 5000);
        return this.nativeApiResponse(payload);
    }

    async _acquireApiSlot(interactive = false) {
        const MAX = 5;
        if (!this._apiWaiters) this._apiWaiters = [];
        if (!this._apiWaitersHigh) this._apiWaitersHigh = [];
        if ((this._apiInFlight || 0) < MAX) {
            this._apiInFlight = (this._apiInFlight || 0) + 1;
            return;
        }
        // Interactive (user-clicked) requests jump ahead of queued background
        // maintenance calls (contacts/users/servers refresh, key republish, cloud
        // vault backup — all fired in bursts from postAuthSetup) instead of waiting
        // behind however many of those already queued first. Without this, clicking
        // "add contact" during that startup burst could sit queued long enough to
        // look like the click did nothing, when it was really just stuck in line.
        const queue = interactive ? this._apiWaitersHigh : this._apiWaiters;
        await new Promise(resolve => queue.push(resolve));
        // The slot was handed to us by _releaseApiSlot (count already reserved).
    }

    _releaseApiSlot() {
        const next = (this._apiWaitersHigh && this._apiWaitersHigh.length)
            ? this._apiWaitersHigh.shift()
            : (this._apiWaiters && this._apiWaiters.length) ? this._apiWaiters.shift() : null;
        if (next) {
            next(); // hand the in-flight slot straight to the next waiter
        } else {
            this._apiInFlight = Math.max(0, (this._apiInFlight || 0) - 1);
        }
    }

    // Global concurrency limit. On macOS every apiFetch goes through the native
    // URLSession pool (≈6 connections/host); a burst of background requests (cloud
    // vault tickets, key republish) would exhaust it and make the NEXT request stall
    // for the full 12s timeout. Capping in-flight requests keeps the pool healthy.
    async apiFetch(path, options = {}) {
        await this._acquireApiSlot(!!options.interactive);
        try {
            return await this._apiFetchImpl(path, options);
        } finally {
            this._releaseApiSlot();
        }
    }

    async _apiFetchImpl(path, options = {}) {
        const method = String(options?.method || 'GET').toUpperCase();
        const requestId = this.newRequestId();
        this.trace(`apiFetch request method=${method} path=${path} request_id=${requestId} auth=${!!this.S.session?.token}`);
        const {
            includeDeviceId = false,
            allowSessionInvalidation = false,
            timeoutMs = 0,
            interactive = false,
            headers: optionHeaders,
            ...fetchOptions
        } = options || {};
        const headers = this.apiHeaders(
            { 'X-Request-ID': requestId, ...(optionHeaders || {}) },
            { includeDeviceId: !!includeDeviceId },
        );
        if (options.body && typeof options.body === 'string' && !headers['Content-Type']) {
            headers['Content-Type'] = 'application/json';
        }
        if (this.nativeSupports('apiRequest') && !(options.body instanceof FormData)) {
            const res = await this.nativeApiFetch(path, {
                method,
                headers,
                body: options.body,
                includeDeviceId,
                timeoutMs: timeoutMs || API_REQUEST_TIMEOUT_MS,
            });
            this.trace(`apiFetch native response method=${method} path=${path} request_id=${requestId} status=${res.status} ok=${res.ok}`);
            this.handleUnauthorizedApiResponse(res, headers, { allowSessionInvalidation });
            return res;
        }
        // The native path has always bounded itself (nativeApiFetch above falls back to
        // API_REQUEST_TIMEOUT_MS); the browser path only had a timeout when a caller
        // remembered to ask for one, and almost none did. `fetch` has no timeout of its
        // own, so one stalled request sat in an apiFetch concurrency slot until the
        // browser gave up minutes later — including the deliberately-prioritised
        // envelope sync, which is the one call that can repair a wrong key.
        //
        // Bulk transfers get their own, much larger budget rather than the request
        // default: a multi-megabyte attachment legitimately outlives it, and cutting
        // those off would trade a rare stall for a routine failure. Uploads are
        // detected here by their multipart body; DOWNLOADS cannot be detected from the
        // request, so the handful of call sites that pull binary (message archives,
        // avatars, server assets) pass TRANSFER_REQUEST_TIMEOUT_MS explicitly.
        //
        // An explicit `timeoutMs` from the caller always wins; anything falsy means
        // "use the default for this kind of request", which is what every existing
        // call site was silently getting as "none at all".
        const isMultipartBody = typeof FormData !== 'undefined' && options.body instanceof FormData;
        const effectiveTimeoutMs = timeoutMs > 0
            ? timeoutMs
            : (isMultipartBody ? TRANSFER_REQUEST_TIMEOUT_MS : API_REQUEST_TIMEOUT_MS);
        let timeoutId = null;
        let abortController = null;
        let abortForwarder = null;
        const originalSignal = fetchOptions.signal;
        if (effectiveTimeoutMs > 0 && typeof AbortController !== 'undefined') {
            abortController = new AbortController();
            fetchOptions.signal = abortController.signal;
            timeoutId = setTimeout(() => abortController.abort(), effectiveTimeoutMs);
            if (originalSignal) {
                if (originalSignal.aborted) {
                    abortController.abort();
                } else {
                    abortForwarder = () => abortController.abort();
                    originalSignal.addEventListener('abort', abortForwarder, { once: true });
                }
            }
        }
        try {
            const res = await fetch(this.apiUrl(path), {
                ...fetchOptions,
                headers,
            });
            this.trace(`apiFetch response method=${method} path=${path} request_id=${requestId} status=${res.status} ok=${res.ok}`);
            this.handleUnauthorizedApiResponse(res, headers, { allowSessionInvalidation });
            return res;
        } catch (error) {
            this.trace(`apiFetch transport_error method=${method} path=${path} request_id=${requestId} err=${error?.message || error}`);
            throw error;
        } finally {
            if (timeoutId) clearTimeout(timeoutId);
            if (originalSignal && abortForwarder) {
                originalSignal.removeEventListener('abort', abortForwarder);
            }
        }
    }

    handleUnauthorizedApiResponse(res, headers = {}, { allowSessionInvalidation = false } = {}) {
        const status = Number(res?.status || 0);
        if (status === 403) {
            this.trace('apiFetch forbidden status=403 keep_session=true');
            return;
        }
        if (status !== 401) return;
        if (!allowSessionInvalidation) {
            this.trace('apiFetch unauthorized status=401 keep_session=true');
            return;
        }
        const currentToken = String(this.S.session?.token || '').trim();
        const headerToken = String(headers?.Authorization || '').replace(/^Bearer\s+/i, '').trim();
        if (!currentToken || headerToken !== currentToken || this.sessionBootstrapInProgress) return;
        if (this.sessionInvalidationInProgress) return;
        this.sessionInvalidationInProgress = true;
        this.forgetRecentAccountEntry(this.S.session?.username, currentToken);
        this.clearStoredSession();
        this.S.auth.dismissed = false;
        this.S.auth.error = 'Сессия истекла. Войдите заново.';
        this.applySession({ username: '', token: null, guest: true }, {
            persist: false,
            syncNative: true,
            connectVoiceSocket: false,
        });
        this.addLogEntry({
            type: 'WARN',
            msg: 'Сессия истекла или токен стал недействительным. Выполните вход заново.',
            ts: new Date().toLocaleTimeString()
        });
        setTimeout(() => {
            this.sessionInvalidationInProgress = false;
        }, 1000);
    }
});


// --- MODULE: interface/auth.js ---
// --- ZaliInterface: Бутстрап сессии, вход/регистрация, контакты. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    async bootstrapSession() {
        this.trace('bootstrapSession start');
        this.sessionBootstrapInProgress = true;
        try {
            const stored = this.loadStoredSession();
            const lastStored = this.loadStoredSession(this.lastAuthStorageKey());
            const injected = this.loadInjectedSession();
            const seenTokens = new Set();
            const candidates = [stored, lastStored, injected]
                .map(s => this.normalizeSession(s))
                .filter(s => {
                    const token = String(s?.token || '').trim();
                    if (!token || seenTokens.has(token)) return false;
                    // Skip already-expired tokens. Otherwise an expired stored token
                    // was applied as a "fallback" session and every request hit the
                    // server's "невалидный JWT" rejection — manifesting as 12s timeouts
                    // and empty history instead of a clean re-login prompt.
                    if (this.isTokenExpired(token)) {
                        this.trace(`bootstrapSession skip expired token username=${s?.username || ''}`);
                        return false;
                    }
                    seenTokens.add(token);
                    return true;
                });
            const hasCandidates = candidates.length > 0;
            // If we had a saved session but every token was expired, tell the user why
            // they are back at the login screen and clear the dead tokens.
            const hadStoredToken = !!(String(stored?.token || '').trim() || String(lastStored?.token || '').trim());
            if (!hasCandidates && hadStoredToken) {
                this.clearStoredSession();
                this.clearLastStoredSession();
                this.S.auth.error = 'Сессия истекла. Войдите заново.';
                this.addLogEntry({ type: 'WARN', msg: 'Сохранённая сессия истекла — войдите заново', ts: new Date().toLocaleTimeString() });
            }

            let restored = false;
            let invalidateStoredSession = false;
            for (const candidate of candidates) {
                const result = await this.restoreSession(candidate);
                restored = !!result?.ok;
                invalidateStoredSession = invalidateStoredSession || !!result?.invalidate;
                if (restored) break;
            }

            if (!restored) {
                if (invalidateStoredSession && stored?.token) this.clearStoredSession();
                if (invalidateStoredSession && lastStored?.token) this.clearLastStoredSession();
                if (hasCandidates && !invalidateStoredSession) {
                    const fallback = candidates[0];
                    this.trace(`bootstrapSession fallback session username=${fallback?.username || ''} tokenSet=${!!fallback?.token}`);
                    this.applySession(fallback, { persist: false, syncNative: false });
                    this.startPostAuthSetup({
                        reason: 'bootstrapSession-fallback',
                        restoreStoredUnlockSecret: true,
                        resetVault: true,
                    });
                    this.S.auth.error = 'Не удалось проверить последний вход сейчас. Сессия будет восстановлена при следующей попытке.';
                    this.updateAuthView();
                } else {
                    this.applySession({ username: '', token: null, guest: true }, { persist: false });
                }
            }

            this.clearAuthInputs();
            this.S.auth.fieldsCleared = true;

            if (this.S.session?.token) {
                this.startPostAuthSetup({
                    reason: 'bootstrapSession',
                    restoreStoredUnlockSecret: true,
                });
            } else {
                this.S.contacts = [];
                this.S.users = [];
                this.S.servers = [];
                this.ensureServerSelection();
                this.renderContacts();
                this.renderServerInterface();
                this.scheduleRenderMessages();
            }
            this.updateAuthView();
            this.applyNetworkConfigToInputs();
            this.syncNativeNetworkConfig();
            this.updateSendButtonState();
            if (this.nativeSupports('sessionSync')) {
                this.syncNativeSession();
            }
            if (this.S.session?.token) {
                this.checkForAppUpdate();
            }
        } finally {
            this.sessionBootstrapInProgress = false;
            this.rehydratePendingOutbox();
            this.scheduleFlushPendingOutbox(300);
            // Whatever the outcome (restored / login form / guest), updateAuthView()
            // above already rendered it — safe to reveal now. `success` mirrors the
            // same predicate updateAuthView() uses to decide whether the login
            // overlay shows: a token means we're entering the app, so the splash
            // gets to say "Готово"; no token means the login form is what's under
            // it, and "Готово" there would just be a lie.
            this.hideBootSplash(!!this.S.session?.token);
            this.trace('bootstrapSession done');
        }
    }

    /**
     * Resolves #bootSplash's looping "Авторизация..." status (see the inline
     * script in index.html) once bootstrapSession() has decided what to show.
     * `success` true scrambles the status into "Готово" before fading; false
     * just stops the loop and fades. Removed from layout after the fade so it
     * can't eat clicks or show up in the accessibility tree.
     */
    hideBootSplash(success) {
        if (typeof window.__resolveBootScreen === 'function') {
            window.__resolveBootScreen(!!success);
            return;
        }
        // Fallback in case the inline boot script didn't run for some reason —
        // still guarantees the splash doesn't get stuck covering the app.
        const splash = document.getElementById('bootSplash');
        if (!splash || splash.hidden) return;
        splash.classList.add('fade-out');
        setTimeout(() => { splash.hidden = true; }, 400);
    }

    async restoreSession(session) {
        try {
            const token = session?.token || null;
            if (!token) return false;
            this.trace(`restoreSession start username=${session?.username || ''} tokenSet=${!!token}`);
            const res = await this.apiFetch(this.apiRoutes.auth.me, {
                allowSessionInvalidation: true,
                timeoutMs: SESSION_RESTORE_TIMEOUT_MS,
                headers: {
                    Authorization: `Bearer ${token}`,
                },
            });
            if (!res.ok) {
                const status = Number(res.status || 0);
                if (status === 401 || status === 403) {
                    this.trace(`restoreSession unauthorized status=${status}`);
                    return { ok: false, invalidate: true };
                }
                this.trace(`restoreSession retryable status=${status}`);
                return { ok: false, invalidate: false };
            }
            const data = await res.json();
            this.trace(`restoreSession success username=${data.username || session.username || ''}`);
            this.applySession({
                username: data.username || session.username || '',
                token,
                guest: false,
            }, { persist: true, syncNative: true });
            if (typeof data.cloudVaultSyncEnabled !== 'undefined') {
                this.applyVaultCloudSyncEnabled(!!data.cloudVaultSyncEnabled, { persistLocal: true });
            }
            return {
                ok: true,
                invalidate: false,
                username: data.username || session.username || '',
                token,
            };
        } catch (e) {
            this.trace(`restoreSession failed error=${e?.message || e}`);
            return { ok: false, invalidate: false };
        }
    }

    applySession(session, { persist = true, syncNative = true, connectVoiceSocket = true } = {}) {
        const previousUsername = this.S.session?.username;
        const previousToken = this.S.session?.token;
        const username = session?.username || '';
        const token = session?.token || null;
        const guest = !!session?.guest || !token;
        this.trace(`applySession username=${username} tokenSet=${!!token} guest=${guest} persist=${persist} syncNative=${syncNative}`);

        if (previousUsername !== username || previousToken !== token) {
            // A deferred cache save scheduled under the OLD account must land now,
            // while _userSuffix() still resolves to that account — once the session
            // switches, the debounced timer would write the old user's chats under
            // the new user's storage key.
            this.flushPendingMessageCacheSave();
            // The one-shot cloud-vault fetch guard is per-account: without resetting it,
            // the next account logged in during this page session would skip its own
            // on-demand vault fetch and mint a temporary key instead of adopting the
            // real key from its vault (key divergence on the account-switch flow).
            this._cloudVaultResolveFetchDone = false;
            // Memo of key envelopes this session has already opened, keyed by envelope
            // id. Envelope ids are per-account, and the incoming account must open its
            // own from scratch — a stale hit here would skip an import it needs.
            this._openedEnvelopeStamps = null;
            // Same story for the "no key of ours opens this message" memo: message ids
            // are per-account and the incoming account must judge them for itself.
            this._failedBrowserUnpacks = null;
            this._decodedBrowserMessageIds = null;
            // Storage keys are per-account, so what the previous account had on disk
            // says nothing about the incoming one — the read path must write its own
            // merge through at least once.
            this._lastConversationKeysEncoded = null;
            // Registry answers are per-account; carrying "this scope has no claim"
            // across a switch could let the new account skip a wait it never made.
            this._canonicalLookupAnswered = null;
            this._browserDecryptGaps = null;
            this.S.current = null;
            this.S.activeServer = null;
            this.S.activeChannel = null;
            this.S.activeConversationType = 'dm';
            this.S.draftAttachments = [];
            this.resetVoiceState({ preserveInvite: false });
            this.disconnectBrowserVoiceSocket();
            this.S.auth.vaultPassphrase = '';
            this.setServerModalState({
                mode: 'create',
                serverId: null,
                members: [],
                loading: false,
                saving: false,
                error: '',
            });
            this.closeServerOverlay();
        }

        this.S.session = { username, token, guest };
        if (username && username !== previousUsername) {
            const userCachedMessages = this.loadStoredMessageCache();
            this.S.chats = userCachedMessages.chats && typeof userCachedMessages.chats === 'object'
                ? userCachedMessages.chats
                : {};
            this.S.serverChats = userCachedMessages.serverChats && typeof userCachedMessages.serverChats === 'object'
                ? userCachedMessages.serverChats
                : {};
            const cachedContacts = this.loadStoredContacts();
            const localContacts = this.localConversationContacts();
            this.S.contacts = Array.from(new Set([...cachedContacts, ...localContacts]))
                .filter(contact => contact !== username);
            this.S.contacts.forEach(contact => this.initChat(contact));
            this.lastNativeConversationKeySignature = '';
            this.syncNativeConversationKeys(this.loadStoredConversationKeys());
            // Per-account, not per-instance: the sweep's coalescing window belongs to
            // the account that opened it, so switching users must not make the new
            // account wait out the previous one's cooldown before publishing its keys.
            this._lastKeyPublishSweepAt = 0;
            if (this._keyPublishSweepTrailing) {
                clearTimeout(this._keyPublishSweepTrailing);
                this._keyPublishSweepTrailing = null;
            }
        }
        if (token) {
            this.S.auth.dismissed = true;
        }
        if (persist) {
            if (token) {
                this.saveStoredSession(this.S.session);
            } else {
                this.clearStoredSession();
            }
        }

        // Аватарки и иконки серверов поднимаются с диска ДО первого кадра —
        // ради этого постоянный кеш и существует. Прогрев идёт по текущему
        // аккаунту, поэтому его место здесь, где S.session уже переставлен,
        // и до renderSidebarProfile()/renderContacts() ниже.
        void this.primeAssetCacheFromDisk();
        void this.hydrateAttachmentPayloadsFromCache();

        this.updateAuthView();
        const overlay = document.getElementById('authOverlay');
        if (overlay && token) {
            overlay.classList.remove('visible');
        }
        this.normalizeDmChatStore();
        this.renderSidebarProfile();
        this.renderRecentAccounts();
        this.updateContactControls();
        this.renderContacts();
        this.scheduleRenderMessages();
        this.updateSendButtonState();
        if (syncNative) {
            this.syncNativeSession();
        }
        if (connectVoiceSocket && !this.nativeSupports('voice')) {
            this.connectBrowserVoiceSocket();
        }
        if (token && !this.hasNativeBridge()) {
            this.subscribeWebPush();
        }
        if (!this.sessionBootstrapInProgress) {
            this.rehydratePendingOutbox();
            this.recoverOrphanSendingMessages();
            this.scheduleFlushPendingOutbox(300);
        }
    }

    clearAuthInputs() {
        const usernameInput = document.getElementById('authUsername');
        const passwordInput = document.getElementById('authPassword');
        if (usernameInput) usernameInput.value = '';
        if (passwordInput) passwordInput.value = '';
    }

    updateContactControls() {
        const enabled = !!this.S.session?.token;
        const contactAddBtn = document.getElementById('contactAddBtn');
        if (contactAddBtn) {
            contactAddBtn.disabled = !enabled;
        }
        if (!enabled) {
            this.exitContactAddMode({ restoreSearch: false });
            this.setContactStatus('');
        }
        this.updateContactAddButtonState();
    }

    enterContactAddMode() {
        if (!this.S.session?.token) return;
        this.S.contactAddMode = true;
        this._searchQBeforeContactAdd = this.S.searchQ || '';
        const input = document.getElementById('searchInput');
        if (input) {
            input.value = '';
            input.placeholder = 'Логин контакта';
            input.focus();
        }
        this.setContactStatus('');
        this.updateContactAddButtonState();
        this.renderContactSuggestions(true);
        void this.loadUsers('').then(() => this.renderContactSuggestions(true));
    }

    exitContactAddMode({ restoreSearch = true } = {}) {
        if (!this.S.contactAddMode) return;
        this.S.contactAddMode = false;
        const input = document.getElementById('searchInput');
        const restoredQuery = restoreSearch ? (this._searchQBeforeContactAdd || '') : '';
        if (input) {
            input.value = restoredQuery;
            input.placeholder = 'Поиск...';
        }
        this.S.searchQ = restoredQuery;
        this._searchQBeforeContactAdd = '';
        this.hideContactSuggestions();
        this.setContactStatus('');
        this.updateContactAddButtonState();
        this.renderContacts();
    }

    updateContactAddButtonState() {
        const contactAddBtn = document.getElementById('contactAddBtn');
        const input = document.getElementById('searchInput');
        if (!contactAddBtn) return;
        const enabled = !!this.S.session?.token;
        const addMode = !!this.S.contactAddMode;
        const hasText = addMode && !!String(input?.value || '').trim();
        contactAddBtn.disabled = !enabled;
        contactAddBtn.classList.toggle('is-empty', addMode && !hasText);
        contactAddBtn.classList.toggle('is-active', addMode);
        contactAddBtn.title = !enabled
            ? 'Войдите, чтобы добавить контакт'
            : (!addMode ? 'Добавить контакт' : (hasText ? 'Добавить контакт' : 'Введите логин контакта'));
    }

    setContactStatus(message = '', tone = '') {
        const status = document.getElementById('contactStatus');
        if (!status) return;
        const text = String(message || '').trim();
        status.textContent = text;
        if (tone) {
            status.dataset.tone = tone;
        } else {
            delete status.dataset.tone;
        }
        status.hidden = !text;
    }

    resolveContactInputUsername(rawValue) {
        const query = String(rawValue || '').trim();
        if (!query) return '';
        const lower = query.toLowerCase();
        const users = Array.isArray(this.S.users) ? this.S.users.filter(Boolean) : [];
        const exactUser = users.find(user => String(user || '').trim().toLowerCase() === lower);
        if (exactUser) return String(exactUser).trim();
        const suggestions = this.getContactSuggestions(query);
        if (suggestions.length === 1) {
            return String(suggestions[0]).trim();
        }
        return query;
    }

    getContactSuggestions(query = '') {
        const q = String(query || '').trim().toLowerCase();
        const me = this.myName();
        const existing = new Set((this.S.contacts || []).map(contact => String(contact).toLowerCase()));
        return (this.S.users || [])
            .filter(Boolean)
            .filter(contact => contact !== me)
            .filter(contact => !existing.has(String(contact).toLowerCase()))
            .filter(contact => !q || String(contact).toLowerCase().includes(q))
            .slice(0, 8);
    }

    hideContactSuggestions() {
        const outer = document.getElementById('contactSuggestionsWrap');
        const wrap = document.getElementById('contactSuggestions');
        if (outer) outer.hidden = true;
        if (!wrap) return;
        wrap.hidden = true;
        wrap.innerHTML = '';
    }

    renderContactSuggestions(force = false) {
        const outer = document.getElementById('contactSuggestionsWrap');
        const wrap = document.getElementById('contactSuggestions');
        const input = document.getElementById('searchInput');
        if (!outer || !wrap || !input) return;

        if (!this.S.session?.token || !this.S.contactAddMode) {
            this.hideContactSuggestions();
            return;
        }

        const query = input.value || '';
        const list = this.getContactSuggestions(query);
        const hasFocus = document.activeElement === input;
        const shouldShow = force || hasFocus || query.trim().length > 0;

        if (!shouldShow) {
            outer.hidden = true;
            wrap.hidden = true;
            wrap.innerHTML = '';
            return;
        }

        if (list.length === 0) {
            outer.hidden = false;
            wrap.hidden = false;
            wrap.innerHTML = `
                <div class="contact-suggest-empty">
                    Ничего не найдено
                </div>
            `;
            return;
        }

        outer.hidden = false;
        wrap.hidden = false;
        wrap.innerHTML = list.map(username => {
            return `
                <button class="contact-suggest-item" type="button" data-username="${this.esc(username)}">
                    <div class="contact-suggest-ava">${this.renderAvatarHTML(username, 'avatar-img', username)}</div>
                    <div class="contact-suggest-meta">
                        <div class="contact-suggest-name">${this.esc(username)}</div>
                        <div class="contact-suggest-hint">Добавить и начать чат</div>
                    </div>
                    <div class="contact-suggest-plus">+</div>
                </button>
            `;
        }).join('');
    }

    setAuthMode(mode, { clearInputs = true, focus = true } = {}) {
        this.S.auth.mode = mode === 'register' ? 'register' : 'login';
        this.S.auth.error = '';
        this.S.auth.loading = false;
        this.S.auth.fieldsCleared = false;
        if (clearInputs) {
            this.clearAuthInputs();
            this.S.auth.fieldsCleared = true;
        }
        this.updateAuthView();
        if (focus) {
            const usernameInput = document.getElementById('authUsername');
            if (usernameInput) usernameInput.focus();
        }
    }

    syncNativeSession() {
        if (!this.nativeSupports('sessionSync')) return;
        const deviceId = this.currentDeviceId();
        const username = this.S.session.username;
        const token = this.S.session.token || '';
        const guest = this.S.session.guest;
        // Skip redundant SET_SESSION: startup/auth calls applySession several times,
        // and every identical re-send made native tear down and re-open the WebSocket,
        // which showed up as the connection flapping (connect/disconnect repeatedly)
        // and left the client briefly offline — so real-time messages were missed.
        const signature = `${username}|${token}|${guest ? 1 : 0}|${deviceId}`;
        if (signature === this._lastNativeSessionSignature) {
            this.trace(`syncNativeSession skip duplicate username=${username}`);
            return;
        }
        this._lastNativeSessionSignature = signature;
        this.trace(`syncNativeSession username=${username} tokenSet=${!!token} deviceId=${deviceId || 'none'}`);
        this.postNativeMessage({
            type: NativeMessageTypes.SET_SESSION,
            username,
            token,
            guest,
            deviceId,
        });
    }

    async loadContacts() {
        try {
            this.trace(`loadContacts start user=${this.myName()} tokenSet=${!!this.S.session?.token}`);
            if (!this.S.session?.token) {
                this.S.contacts = [];
                this.renderContacts();
                return;
            }
            const res = await this.apiFetch(this.apiRoutes.contacts.list);
            if (!res.ok) {
                const text = await res.text().catch(() => '');
                this.trace(`loadContacts failed status=${res.status} body=${text.slice(0, 300)}`);
                if (!this.S.contacts.length) {
                    const cachedContacts = this.loadStoredContacts();
                    if (cachedContacts.length) this.setContacts(cachedContacts);
                }
                this.renderContacts();
                return;
            }
            const data = await res.json();
            const contacts = Array.isArray(data?.contacts) ? data.contacts : [];
            this.trace(`loadContacts success count=${contacts.length} contacts=${contacts.join(',')}`);
            this.setContacts(contacts);
        } catch (e) {
            this.trace(`loadContacts error=${e?.message || e}`);
            this.renderContacts();
        }
    }

    // Debounced user search for the contact-add field. Typing "alexander" used
    // to fire nine searches, one per keystroke, none of them cancelled — so the
    // suggestion list also flickered through stale results whenever an earlier
    // response overtook a later one. One request per pause in typing, and
    // loadUsers() below drops any answer that is no longer the newest.
    scheduleUserSearch(query, { delayMs = 220, onDone = null } = {}) {
        const value = String(query || '');
        if (this._userSearchTimer) clearTimeout(this._userSearchTimer);
        this._userSearchTimer = setTimeout(() => {
            this._userSearchTimer = 0;
            void this.loadUsers(value).then(() => { if (onDone) onDone(); });
        }, Math.max(0, Number(delayMs) || 0));
    }

    async loadUsers(query = '', { interactive = false } = {}) {
        const seq = (this._loadUsersSeq = (this._loadUsersSeq || 0) + 1);
        try {
            this.trace(`loadUsers start user=${this.myName()} tokenSet=${!!this.S.session?.token}`);
            if (!this.S.session?.token) {
                this.S.users = [];
                return;
            }
            const search = String(query || '').trim();
            const res = await this.apiFetch(this.apiRoutes.users.search(search), { interactive });
            // A slower earlier query must never overwrite a newer answer.
            if (seq !== this._loadUsersSeq) return;
            if (!res.ok) {
                const text = await res.text().catch(() => '');
                this.trace(`loadUsers failed status=${res.status} body=${text.slice(0, 300)}`);
                return;
            }
            const users = await res.json();
            this.trace(`loadUsers success count=${Array.isArray(users) ? users.length : 0} users=${Array.isArray(users) ? users.join(',') : 'invalid'}`);
            this.setUsers(users);
        } catch (e) {
            this.trace(`loadUsers error=${e?.message || e}`);
        }
    }

    startPostAuthSetup({
        passphrase = '',
        reason = 'login',
        saveUnlockSecret = false,
        restoreStoredUnlockSecret = false,
        resetVault = false,
    } = {}) {
        const token = String(this.S.session?.token || '').trim();
        if (!token) return;
        const runId = ++this.postAuthSetupRunId;
        void (async () => {
            // A newer run supersedes this one. bootstrapSession can fire two setups
            // back-to-back (fallback + token branch); without a real guard both ran
            // the full request set concurrently, doubling load and causing 12s
            // timeouts. Bail at each checkpoint if a newer run started.
            const superseded = () => this.postAuthSetupRunId !== runId;
            this.postAuthSetupInFlight = true;
            const tStart = this.nowMs();
            try {
                let code = String(passphrase || this.S.auth?.vaultPassphrase || '').trim();
                if (!code && restoreStoredUnlockSecret) {
                    code = await this.timeStage('loadVaultUnlockSecret', () => this.loadVaultUnlockSecret(token));
                    if (code) {
                        this.S.auth.vaultPassphrase = code;
                    }
                }
                if (superseded()) { this.trace(`postAuthSetup superseded reason=${reason} run=${runId}`); return; }
                if (saveUnlockSecret && code) {
                    await this.timeStage('saveVaultUnlockSecret', () => this.saveVaultUnlockSecret(code, token));
                }
                if (resetVault) {
                    await this.timeStage('ensureServerVaultReset', () => this.ensureServerVaultReset({ reason }));
                }
                // Contacts/users/servers are independent of device registration, so fire
                // them NOW in parallel with bootstrapDeviceTrust instead of after it —
                // they all multiplex over the single HTTP/2 connection. Key envelopes do
                // need the device registered, so they wait for bootstrap.
                const uiLoads = Promise.allSettled([
                    this.timeStage('loadContacts', () => this.loadContacts()),
                    this.timeStage('loadUsers', () => this.loadUsers()),
                    this.timeStage('loadServers', () => this.loadServers({ silent: true })),
                    // Заявки в друзья нужны здесь, а не при открытии профиля:
                    // без них бейдж на своей аватарке остался бы пустым до
                    // первого захода в профиль, то есть о заявке никто бы не узнал.
                    this.timeStage('loadFriendRequests', () => this.loadFriendRequests()),
                ]);
                await this.timeStage('bootstrapDeviceTrust', () => this.bootstrapDeviceTrust());
                await this.timeStage('restoreCloudVaultSnapshot', () => this.restoreCloudVaultSnapshot({ reason }));
                if (superseded()) { this.trace(`postAuthSetup superseded reason=${reason} run=${runId}`); return; }
                await Promise.allSettled([
                    this.timeStage('syncIncomingKeyEnvelopes', () => this.syncIncomingKeyEnvelopes({ reason })),
                    uiLoads,
                ]);
                this.addLogEntry({ type: 'INFO', msg: `⏱ postAuthSetup ВСЕГО (reason=${reason}): ${Math.round(this.nowMs() - tStart)} мс`, ts: new Date().toLocaleTimeString() });
                this.trace(`postAuthSetup done reason=${reason} run=${runId}`);
                // Background, OFF the critical path. These are slow (cloud vault backup
                // POSTs a package + a history ticket per scope; key republish sends one
                // request per peer device) but none are needed to render the chat, so
                // they must not block or starve the loads above.
                if (!superseded()) {
                    if (code) {
                        void this.timeStage('syncCloudVaultPackage(bg)', () => this.syncCloudVaultPackage({ passphrase: code, reason }));
                    } else if (this.isVaultCloudSyncEnabled()) {
                        // No passphrase means the cloud vault is off for this whole
                        // session: syncCloudVaultPackage bails without one and so does
                        // scheduleCloudVaultSync, so nothing this device learns can ever
                        // reach the account's other devices through the vault, and
                        // nothing they publish reaches it. That is a real, load-bearing
                        // failure — a restored session whose stored unlock secret was
                        // lost (cleared storage, or a blob sealed with a since-rotated
                        // token) hits it — and until now it happened without a single
                        // word anywhere. Say so; a password login re-seals the secret.
                        this.addLogEntry({
                            type: 'WARN',
                            msg: 'Облачная синхронизация ключей недоступна: не восстановлена парольная фраза vault. Войдите по паролю, чтобы включить её снова.',
                            ts: new Date().toLocaleTimeString(),
                        });
                        this.trace(`postAuthSetup cloud vault disabled reason=${reason} no_passphrase=true`);
                    }
                    void this.timeStage('retryPublishConversationKeys(bg)', () => this.retryPublishConversationKeys({ reason }));
                }
            } catch (e) {
                this.trace(`postAuthSetup failed reason=${reason} run=${runId} error=${e?.message || e}`);
            } finally {
                if (runId === this.postAuthSetupRunId) {
                    this.postAuthSetupInFlight = false;
                }
            }
        })();
    }

    async executeAuth(mode, username, password, { logAttempt = true } = {}) {
        const errorBox = document.getElementById('authError');
        this.S.auth.loading = true;
        this.updateAuthView();

        try {
            if (this.isWindowsNativeAuth()) {
                return await this.executeNativeAuth(mode, username, password, { logAttempt });
            }

            const endpoint = mode === 'register' ? this.apiRoutes.auth.register : this.apiRoutes.auth.login;
            if (mode === 'register' && logAttempt) {
                this.addLogEntry({
                    type: 'INFO',
                    msg: `Попытка регистрации: ${username}`,
                    ts: new Date().toLocaleTimeString()
                });
            }

            const requestAuth = async () => {
                return await this.apiFetch(endpoint, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ username, password }),
                    timeoutMs: AUTH_REQUEST_TIMEOUT_MS,
                    interactive: true,
                });
            };

            let res;
            let lastError = null;
            for (let attempt = 0; attempt < 2; attempt++) {
                try {
                    res = await requestAuth();
                    lastError = null;
                    break;
                } catch (err) {
                    lastError = err;
                    const msg = String(err?.message || err || '');
                    if (!/load failed|failed to fetch|network error|abort/i.test(msg) || attempt === 1) {
                        break;
                    }
                    await new Promise(resolve => setTimeout(resolve, 250));
                }
            }

            if (!res) {
                throw lastError || new Error('Не удалось связаться с сервером');
            }

            if (mode === 'register') {
                if (!res.ok) {
                    const text = await res.text();
                    if (res.status === 409 || /Пользователь уже существует/i.test(text)) {
                        this.addLogEntry({
                            type: 'INFO',
                            msg: `Аккаунт ${username} уже есть, пробуем войти с этим паролем`,
                            ts: new Date().toLocaleTimeString()
                        });

                        const recovered = await this.executeAuth('login', username, password, { logAttempt: false });
                        if (recovered) {
                            this.addLogEntry({
                                type: 'SUCCESS',
                                msg: `Вход восстановлен для ${username}`,
                                ts: new Date().toLocaleTimeString()
                            });
                            return true;
                        }
                    }

                    this.addLogEntry({
                        type: 'WARN',
                        msg: `Регистрация отклонена для ${username}: ${text || res.status}`,
                        ts: new Date().toLocaleTimeString()
                    });
                    throw new Error(text || 'Не удалось зарегистрироваться');
                }

                const data = await res.json();
                this.applySession({
                    username: data.username || username,
                    token: data.token,
                    guest: false,
                });
                if (typeof data.cloudVaultSyncEnabled !== 'undefined') {
                    this.applyVaultCloudSyncEnabled(!!data.cloudVaultSyncEnabled, { persistLocal: true });
                }
                this.S.auth.vaultPassphrase = String(password || '').trim();
                this.setAuthMode('login', { clearInputs: true, focus: false });
                this.startPostAuthSetup({
                    passphrase: password,
                    reason: 'register',
                    saveUnlockSecret: true,
                    resetVault: true,
                });

                this.addLogEntry({
                    type: 'SUCCESS',
                    msg: `Регистрация успешна, вход выполнен как ${this.myName()}`,
                    ts: new Date().toLocaleTimeString()
                });
                this.clearAuthInputs();
                return true;
            }

            if (!res.ok) {
                const text = await res.text();
                throw new Error(text || 'Не удалось войти');
            }

            const data = await res.json();
            this.applySession({
                username: data.username || username,
                token: data.token,
                guest: false,
            });
            if (typeof data.cloudVaultSyncEnabled !== 'undefined') {
                this.applyVaultCloudSyncEnabled(!!data.cloudVaultSyncEnabled, { persistLocal: true });
            }
            this.S.auth.vaultPassphrase = String(password || '').trim();
            this.setAuthMode('login', { clearInputs: true, focus: false });
            this.startPostAuthSetup({
                passphrase: password,
                reason: 'login',
                saveUnlockSecret: true,
                resetVault: true,
            });
            this.clearAuthInputs();
            this.addLogEntry({ type: 'SUCCESS', msg: `Вход выполнен как ${this.myName()}`, ts: new Date().toLocaleTimeString() });
            return true;
        } catch (e) {
            const raw = e.message || 'Ошибка входа';
            const apiBaseUrl = this.getApiBaseUrl();
            const friendly = /load failed|failed to fetch|network error|abort/i.test(raw)
                ? `Не удалось связаться с сервером (${apiBaseUrl}). Проверь адрес или запусти backend.`
                : raw;
            this.S.auth.error = friendly;
            if (errorBox) errorBox.textContent = friendly;
            if (mode === 'register') {
                this.addLogEntry({
                    type: 'ERROR',
                    msg: `Ошибка регистрации для ${username}: ${friendly}`,
                    ts: new Date().toLocaleTimeString()
                });
            }
            return false;
        } finally {
            this.S.auth.loading = false;
            this.updateAuthView();
        }
    }

    async executeNativeAuth(mode, username, password, { logAttempt = true } = {}) {
        const requestId = `auth-${Date.now()}-${Math.random().toString(16).slice(2)}`;
        const request = {
            type: NativeMessageTypes.AUTH_REQUEST,
            mode,
            username,
            password,
            requestId,
        };

        if (mode === 'register' && logAttempt) {
            this.addLogEntry({
                type: 'INFO',
                msg: `Попытка регистрации: ${username}`,
                ts: new Date().toLocaleTimeString()
            });
        }

        const nativeAuthTimeoutMs = mode === 'register'
            ? AUTH_REQUEST_TIMEOUT_MS * 2
            : AUTH_REQUEST_TIMEOUT_MS;
        const payload = await new Promise((resolve, reject) => {
            const timeoutId = setTimeout(() => {
                this.nativeAuthRequests.delete(requestId);
                reject(new Error('Не удалось связаться с сервером'));
            }, nativeAuthTimeoutMs);

            this.nativeAuthRequests.set(requestId, { resolve, reject, timeoutId });

            if (!this.postNativeMessage(request)) {
                clearTimeout(timeoutId);
                this.nativeAuthRequests.delete(requestId);
                reject(new Error('Не удалось связаться с сервером'));
            }
        });

        const data = payload?.data || payload;
        this.applySession({
            username: data.username || username,
            token: data.token,
            guest: false,
        });
        if (typeof data.cloudVaultSyncEnabled !== 'undefined') {
            this.applyVaultCloudSyncEnabled(!!data.cloudVaultSyncEnabled, { persistLocal: true });
        }
        this.S.auth.vaultPassphrase = String(password || '').trim();
        this.setAuthMode('login', { clearInputs: true, focus: false });
        this.startPostAuthSetup({
            passphrase: password,
            reason: 'native-auth',
            saveUnlockSecret: true,
            resetVault: true,
        });
        this.clearAuthInputs();
        this.addLogEntry({
            type: 'SUCCESS',
            msg: mode === 'register'
                ? `Регистрация успешна, вход выполнен как ${this.myName()}`
                : `Вход выполнен как ${this.myName()}`,
            ts: new Date().toLocaleTimeString()
        });
        return true;
    }

    async requestNativeAction(payload, timeoutMs = 15000) {
        const requestId = String(payload?.requestId || `native-${Date.now()}-${Math.random().toString(16).slice(2)}`);
        const request = { ...payload, requestId };
        return await new Promise((resolve, reject) => {
            const timeoutId = setTimeout(() => {
                this.nativeRequests.delete(requestId);
                reject(new Error('Не удалось связаться с сервером'));
            }, timeoutMs);

            this.nativeRequests.set(requestId, { resolve, reject, timeoutId });

            if (!this.postNativeMessage(request)) {
                clearTimeout(timeoutId);
                this.nativeRequests.delete(requestId);
                reject(new Error('Не удалось связаться с сервером'));
            }
        });
    }

    onNativeResponse(payload) {
        if (!payload || typeof payload !== 'object') return;
        const requestId = String(payload.requestId || '').trim();
        if (!requestId) return;
        const pending = this.nativeRequests.get(requestId);
        if (!pending) return;
        clearTimeout(pending.timeoutId);
        this.nativeRequests.delete(requestId);
        if (payload.ok) {
            pending.resolve(payload);
        } else {
            pending.reject(new Error(payload.error || 'Операция не удалась'));
        }
    }

    onNativeAuthResponse(payload) {
        if (!payload || typeof payload !== 'object') return;
        const requestId = String(payload.requestId || '').trim();
        if (!requestId) return;
        const pending = this.nativeAuthRequests.get(requestId);
        if (!pending) return;
        clearTimeout(pending.timeoutId);
        this.nativeAuthRequests.delete(requestId);
        if (payload.ok) {
            pending.resolve(payload);
        } else {
            pending.reject(new Error(payload.error || 'Не удалось войти'));
        }
    }

    async submitAuth(mode) {
        if (this.S.auth.loading) {
            return;
        }

        const usernameInput = document.getElementById('authUsername');
        const passwordInput = document.getElementById('authPassword');
        const username = (usernameInput?.value || '').trim();
        const password = passwordInput?.value || '';
        const errorBox = document.getElementById('authError');

        if (errorBox) errorBox.textContent = '';
        this.S.auth.error = '';
        if (!username || !password) {
            const msg = 'Введите логин и пароль';
            this.S.auth.error = msg;
            if (errorBox) errorBox.textContent = msg;
            return;
        }

        if (mode === 'register') {
            if (username.length > 64) {
                const msg = 'Логин слишком длинный: максимум 64 символа';
                this.S.auth.error = msg;
                if (errorBox) errorBox.textContent = msg;
                this.addLogEntry({ type: 'WARN', msg: `Регистрация отклонена для ${username}: ${msg}`, ts: new Date().toLocaleTimeString() });
                return;
            }

            if (password.length < 6) {
                const msg = 'Пароль должен быть не менее 6 символов';
                this.S.auth.error = msg;
                if (errorBox) errorBox.textContent = msg;
                this.addLogEntry({ type: 'WARN', msg: `Регистрация отклонена для ${username}: ${msg}`, ts: new Date().toLocaleTimeString() });
                return;
            }
        }

        const authApiBaseUrl = document.getElementById('authApiBaseUrl');
        const typedApiBaseUrl = String(authApiBaseUrl?.value || '').trim();
        if (typedApiBaseUrl) {
            try {
                const current = this.loadNetworkConfig();
                const typedWsBaseUrl = this.deriveWsBaseUrl(typedApiBaseUrl);
                if (typedApiBaseUrl !== current.apiBaseUrl || typedWsBaseUrl !== current.wsBaseUrl) {
                    this.setNetworkConfig({
                        apiBaseUrl: typedApiBaseUrl,
                        wsBaseUrl: typedWsBaseUrl,
                        iceServers: current.iceServers,
                    });
                }
            } catch (e) {
                const msg = e?.message || 'Не удалось сохранить адрес сервера';
                this.S.auth.error = msg;
                if (errorBox) errorBox.textContent = msg;
                return;
            }
        }

        return this.executeAuth(mode, username, password);
    }

    continueAsGuest() {
        this.S.auth.dismissed = true;
        this.S.auth.error = '';
        this.clearAuthInputs();
        this.S.auth.fieldsCleared = true;
        this.applySession({ username: '', token: null, guest: true }, { persist: false });
        this.loadContacts();
        this.updateAuthView();
    }

    async logout() {
        this.S.auth.dismissed = false;
        this.S.auth.error = '';
        this.setAuthMode('login', { clearInputs: true, focus: false });
        this.clearStoredSession();
        this.applySession({ username: '', token: null, guest: true }, { persist: false, syncNative: false, connectVoiceSocket: false });
        this.S.contacts = [];
        this.S.users = [];
        this.S.current = null;
        this.S.unread = {};
        this.S.channelUnread = {};
        this.syncTaskbarBadge();
        this.resetVoiceState({ preserveInvite: false });
        this.disconnectBrowserVoiceSocket();
        // A rotating TURN credential encodes the account it was issued to, so the
        // next person to sign in on this device must not inherit it.
        this._voiceTurnCredentials = null;
        this._voiceTurnFetchInFlight = null;
        this.renderContacts();
        this.scheduleRenderMessages();
        this.updateAuthView();
        this.addLogEntry({ type: 'WARN', msg: 'Сеанс завершён', ts: new Date().toLocaleTimeString() });
    }

    async addContactFromInput(usernameOverride = null) {
        if (!this.S.session?.token) {
            const msg = 'Сначала войдите в аккаунт, чтобы добавлять контакты';
            this.addLogEntry({ type: 'WARN', msg, ts: new Date().toLocaleTimeString() });
            this.S.auth.error = msg;
            this.setContactStatus(msg, 'error');
            this.updateAuthView();
            return;
        }

        const input = document.getElementById('searchInput');
        const rawUsername = (usernameOverride ?? input?.value ?? '').trim();
        if (!rawUsername) {
            const msg = 'Введите логин контакта';
            this.setContactStatus(msg);
            if (input) {
                input.focus();
                input.select?.();
            }
            this.renderContactSuggestions(true);
            return;
        }

        this.setContactStatus('');
        const lowerRawUsername = rawUsername.toLowerCase();
        const exactInCache = Array.isArray(this.S.users)
            ? this.S.users.some(user => String(user || '').trim().toLowerCase() === lowerRawUsername)
            : false;
        let username = this.resolveContactInputUsername(rawUsername);

        if (!exactInCache && rawUsername.length >= 3) {
            await this.loadUsers(rawUsername, { interactive: true });
            const exactAfterLoad = Array.isArray(this.S.users)
                ? this.S.users.find(user => String(user || '').trim().toLowerCase() === lowerRawUsername)
                : null;
            if (exactAfterLoad) {
                username = String(exactAfterLoad).trim();
            } else {
                const suggestions = this.getContactSuggestions(rawUsername);
                if (suggestions.length === 1) {
                    username = String(suggestions[0]).trim();
                } else if (suggestions.length > 1) {
                    const msg = 'Выберите контакт из списка';
                    this.setContactStatus(msg, 'error');
                    this.renderContactSuggestions(true);
                    if (input) input.focus();
                    return;
                }
            }
        }

        if (!username) {
            const msg = 'Введите логин контакта';
            this.setContactStatus(msg);
            if (input) input.focus();
            return;
        }

        if (this.S.contacts?.some?.(u => String(u || '').trim().toLowerCase() === username.toLowerCase())) {
            const msg = `Контакт уже добавлен: ${username}`;
            this.setContactStatus(msg, 'success');
            this.addLogEntry({ type: 'INFO', msg, ts: new Date().toLocaleTimeString() });
            if (input) {
                input.value = '';
                input.focus();
            }
            this.updateContactAddButtonState();
            this.hideContactSuggestions();
            return;
        }

        try {
            if (this.isWindowsNativeAuth()) {
                const payload = await this.requestNativeAction({
                    type: NativeMessageTypes.ADD_CONTACT_REQUEST,
                    username,
                });
                this.setContacts(Array.isArray(payload?.data?.contacts) ? payload.data.contacts : []);
                if (input) input.value = '';
                this.updateContactAddButtonState();
                this.hideContactSuggestions();
                this.setContactStatus(`Контакт добавлен: ${username}`, 'success');
                this.addLogEntry({ type: 'SUCCESS', msg: `Контакт добавлен: ${username}`, ts: new Date().toLocaleTimeString() });
                return;
            }
            const requestAddContact = async () => {
                return await this.apiFetch(this.apiRoutes.contacts.list, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ username }),
                    interactive: true,
                });
            };

            let res = null;
            let lastError = null;
            for (let attempt = 0; attempt < 2; attempt += 1) {
                try {
                    res = await requestAddContact();
                    lastError = null;
                    break;
                } catch (err) {
                    lastError = err;
                    const msg = String(err?.message || err || '');
                    if (!/load failed|failed to fetch|network error|abort/i.test(msg) || attempt === 1) {
                        break;
                    }
                    await new Promise(resolve => setTimeout(resolve, 250));
                }
            }
            if (!res) {
                throw lastError || new Error('Не удалось добавить контакт');
            }
            if (!res.ok) {
                const text = await res.text();
                throw new Error(text || 'Не удалось добавить контакт');
            }
            const data = await res.json();
            this.setContacts(Array.isArray(data?.contacts) ? data.contacts : []);
            if (input) input.value = '';
            this.updateContactAddButtonState();
            this.hideContactSuggestions();
            this.setContactStatus(`Контакт добавлен: ${username}`, 'success');
            this.addLogEntry({ type: 'SUCCESS', msg: `Контакт добавлен: ${username}`, ts: new Date().toLocaleTimeString() });
        } catch (e) {
            const apiBase = this.getApiBaseUrl();
            const rawMessage = String(e?.message || 'Не удалось добавить контакт');
            const message = /load failed|failed to fetch|network error|abort/i.test(rawMessage)
                ? `Не удалось добавить контакт на ${apiBase}. Проверь адрес сервера и попробуй ещё раз.`
                : rawMessage;
            this.setContactStatus(message, 'error');
            if (/пользователь не найден/i.test(message)) {
                this.renderContactSuggestions(true);
            }
            this.addLogEntry({ type: 'ERROR', msg: message, ts: new Date().toLocaleTimeString() });
        }
    }

    async removeContact(username) {
        if (!this.S.session?.token) {
            this.addLogEntry({ type: 'WARN', msg: 'Удаление контактов доступно только после входа', ts: new Date().toLocaleTimeString() });
            return;
        }
        try {
            if (this.isWindowsNativeAuth()) {
                const payload = await this.requestNativeAction({
                    type: NativeMessageTypes.REMOVE_CONTACT_REQUEST,
                    username,
                });
                this.setContacts(Array.isArray(payload?.data?.contacts) ? payload.data.contacts : []);
                return;
            }
            const res = await this.apiFetch(this.apiRoutes.contacts.byUsername(username), { method: 'DELETE', interactive: true });
            if (!res.ok) {
                const text = await res.text();
                throw new Error(text || 'Не удалось удалить контакт');
            }
            const data = await res.json();
            this.setContacts(Array.isArray(data?.contacts) ? data.contacts : []);
        } catch (e) {
            this.addLogEntry({ type: 'ERROR', msg: e.message || 'Не удалось удалить контакт', ts: new Date().toLocaleTimeString() });
        }
    }

    updateAuthView() {
        const overlay = document.getElementById('authOverlay');
        if (overlay) {
            const shouldShow = !this.S.session?.token && !this.S.auth.dismissed;
            overlay.classList.toggle('visible', shouldShow);
            // The overlay covers whichever view is active underneath, so a
            // native bottom bar must come back while it is up and re-hide once
            // it closes onto the chat screen (notifyNativeMobileNav reads it).
            this.syncNativeMobileNav();
        }

        const authTitle = document.getElementById('authTitle');
        const authHint = document.getElementById('authHint');
        const authError = document.getElementById('authError');
        const loginBtn = document.getElementById('authLoginBtn');
        const regBtn = document.getElementById('authRegisterBtn');
        const guestBtn = document.getElementById('authGuestBtn');
        const vaultSyncNote = document.getElementById('authVaultSyncNote');
        if (authTitle) authTitle.textContent = this.S.auth.mode === 'register' ? 'Создание аккаунта' : 'Вход в аккаунт';
        if (authHint) authHint.textContent = this.S.auth.mode === 'register'
            ? 'Зарегистрируйтесь, чтобы сохранить контакты и историю.'
            : 'Войдите, чтобы синхронизировать сообщения и контакты.';
        if (vaultSyncNote) {
            vaultSyncNote.textContent = this.isVaultCloudSyncEnabled()
                ? 'Ключи переписки будут подгружены из облака при входе.'
                : 'Ключи переписки останутся только на этом устройстве.';
        }
        if (authError) authError.textContent = this.S.auth.error || '';
        if (loginBtn) loginBtn.textContent = this.S.auth.loading
            ? 'Входим...'
            : (this.S.auth.mode === 'register' ? 'Создать аккаунт' : 'Войти');
        if (regBtn) regBtn.textContent = this.S.auth.mode === 'register' ? 'Уже есть аккаунт' : 'Создать аккаунт';
        if (loginBtn) loginBtn.disabled = this.S.auth.loading;
        if (regBtn) regBtn.disabled = this.S.auth.loading;
        if (guestBtn) guestBtn.disabled = this.S.auth.loading;
        this.syncAuthNetworkInput();
        this.renderVaultCloudSyncControls();
        if (!this.S.session?.token && overlay && overlay.classList.contains('visible') && !this.S.auth.fieldsCleared && !this.S.auth.loading) {
            this.clearAuthInputs();
            this.S.auth.fieldsCleared = true;
        }
        this.renderSidebarProfile();
    }

    initChat(name) { 
        if (!this.S.chats[name]) this.S.chats[name] = []; 
    }

    ensureContact(name) {
        if (!name || name === this.myName()) return;
        if (!this.S.contacts.includes(name)) {
            this.S.contacts = [name, ...this.S.contacts];
        }
        this.initChat(name);
    }
});


// --- MODULE: interface/attachments.js ---
// --- ZaliInterface: Вложения, Tenor, предпросмотр медиа. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    // A .tgs is a gzipped Lottie animation (Telegram animated sticker). Peers and
    // older builds of this app label it anything from application/gzip to
    // application/octet-stream, so detection leans on the filename too — see
    // ZaliTgs.isTgsAttachment in web/src/modules/tgs.js.
    isStickerAttachment(att) {
        if (window.ZaliTgs?.isTgsAttachment) return window.ZaliTgs.isTgsAttachment(att);
        const name = String(att?.name || att?.archivePath || att?.archive_path || '');
        const mimeType = String(att?.mimeType || att?.mime_type || '').toLowerCase();
        return att?.kind === 'sticker' || mimeType === 'application/x-tgsticker' || /\.tgs$/i.test(name.trim());
    }

    attachmentKindFor(att) {
        if (this.isStickerAttachment(att)) return 'sticker';
        const mimeType = String(att?.mimeType || att?.mime_type || '');
        if (mimeType.startsWith('video/')) return 'video';
        if (mimeType === 'image/gif') return 'gif';
        if (mimeType.startsWith('image/')) return 'image';
        if (mimeType.startsWith('audio/')) return 'audio';
        return '';
    }

    // The extension shown on the generic file icon when there's no richer preview
    // for a type (a .docx, .zip, .py, ...). Capped at 4 chars so it still fits the
    // icon glyph — long "extensions" past that are usually not real extensions
    // (a dotted version number, a filename with no extension at all) anyway.
    fileExtensionLabel(name) {
        const clean = String(name || '').trim();
        const dot = clean.lastIndexOf('.');
        if (dot <= 0 || dot === clean.length - 1) return '';
        return clean.slice(dot + 1).toUpperCase().slice(0, 4);
    }

    renderFileIcon(name) {
        const ext = this.fileExtensionLabel(name);
        return `<span class="file-icon" aria-hidden="true">${ext ? this.esc(ext) : ''}</span>`;
    }

    // The URL an attachment is RENDERED with. A `data:` URL is swapped for a
    // `blob:` one once and reused from then on.
    //
    // This is not micro-tuning. The native shells hand attachments to the WebView
    // as `data:` URLs (WebView.swift makeDataURL / native/util.rs make_data_url),
    // and that value used to go straight into the message-list HTML. Measured on a
    // 60-message conversation with 6 MB of photos: the rendered string was 10.5 MB
    // for 1070 characters of text, all of it base64 — scanned five times by esc()
    // on the way in and held a second time in _lastMessagesHTML. A `blob:` URL is
    // ~40 characters, and unlike a data: URL rebuilt from scratch on each
    // innerHTML write, the browser can reuse the image it already decoded behind
    // it, so media stops flickering on unrelated re-renders. See
    // scripts/perf_doctor.
    //
    // Called from renderAttachmentPreview() and nowhere else, deliberately: doing
    // it in normalizeAttachment() would also fire from saveStoredMessageCache(),
    // which walks EVERY attachment of EVERY conversation and would then hold a
    // Blob copy of an archive most of which is not on screen and may never be.
    //
    // Keyed by the payload string rather than by the attachment object: the same
    // photo appears as several distinct objects (state, a normalised copy, an
    // outbox entry), and one decoded copy should serve all of them.
    attachmentDisplayUrl(rawUrl) {
        const value = String(rawUrl || '');
        if (!value.startsWith('data:')) return value;
        if (!this._attachmentBlobUrls) this._attachmentBlobUrls = new Map();
        if (!this._attachmentBlobPayloads) this._attachmentBlobPayloads = new Map();
        const cached = this._attachmentBlobUrls.get(value);
        if (cached) return cached;
        const blob = this.dataUrlToBlob(value);
        if (!blob) return value;
        let url;
        try {
            url = URL.createObjectURL(blob);
        } catch (e) {
            return value;
        }
        this._attachmentBlobUrls.set(value, url);
        // Reverse lookup: the native download bridge needs the payload back — see
        // downloadAttachmentFromHref().
        this._attachmentBlobPayloads.set(url, value);
        return url;
    }

    normalizeAttachment(att = {}) {
        // Already normalised — hand it straight back. renderMessageBody() maps an
        // array that normalizeAttachments() has just produced, and
        // renderAttachmentPreview() normalises each element again, so every
        // attachment was rebuilt (and its sticker-detection regex re-run) one
        // extra time per bubble per frame.
        if (att && att.__zaliNormalizedShape === true) return att;
        const mimeType = att.mimeType || att.mime_type || '';
        // Stickers override an incoming `kind` on purpose: a peer that predates
        // .tgs support labels them 'file', and honouring that would render an
        // animated sticker as a download chip.
        const kind = this.isStickerAttachment(att)
            ? 'sticker'
            : (att.kind || this.attachmentKindFor(att) || 'file');
        const dataUrl = att.dataUrl || att.data_url || att.url || '';
        const normalized = {
            id: att.id || `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
            name: att.name || 'attachment',
            mimeType,
            kind,
            size: Number(att.size || 0),
            // The payload. Sending, editing, persistence and the renderer all
            // read this one; the renderer passes it through
            // attachmentDisplayUrl() first.
            dataUrl,
            archivePath: att.archivePath || att.archive_path || '',
        };
        // Non-enumerable: this object is spread into the persisted cache and into
        // the native bridge payload, and the marker has no business in either.
        Object.defineProperty(normalized, '__zaliNormalizedShape', { value: true });
        return normalized;
    }

    // Memoised against the exact array it was given. Rendering one message calls
    // this three times — messageHasMedia(), messageIsGifOnly()/
    // messageIsImageCaption() and renderMessageBody() each normalise the same
    // attachments independently — so every bubble used to rebuild its attachment
    // objects and re-run the sticker-detection regex three times per frame.
    //
    // The cache is validated, not trusted: it is discarded unless every source
    // object and every payload string is still the identical reference. That
    // covers the one in-place mutation that exists (restoreAttachmentPayloads
    // filling `dataUrl` back in at load time) without needing to know about it.
    normalizeAttachments(attachments) {
        if (!Array.isArray(attachments)) return [];
        if (!attachments.length) return [];
        const cached = attachments.__zaliNormalized;
        if (cached
            && cached.raw.length === attachments.length
            && cached.raw.every((att, i) => att === attachments[i] && cached.payloads[i] === (attachments[i]?.dataUrl || attachments[i]?.data_url || attachments[i]?.url || ''))) {
            return cached.value;
        }
        const value = attachments.map(att => this.normalizeAttachment(att));
        try {
            Object.defineProperty(attachments, '__zaliNormalized', {
                value: {
                    raw: attachments.slice(),
                    payloads: attachments.map(att => att?.dataUrl || att?.data_url || att?.url || ''),
                    value,
                },
                writable: true,
                configurable: true,
                enumerable: false,
            });
        } catch (e) { /* frozen array — just skip the memo */ }
        return value;
    }

    formatFileSize(bytes) {
        const size = Number(bytes || 0);
        if (!Number.isFinite(size) || size <= 0) return '0 B';
        const units = ['B', 'KB', 'MB', 'GB', 'TB'];
        let value = size;
        let unitIndex = 0;
        while (value >= 1024 && unitIndex < units.length - 1) {
            value /= 1024;
            unitIndex += 1;
        }
        const precision = unitIndex === 0 ? 0 : value < 10 ? 1 : 0;
        return `${value.toFixed(precision)} ${units[unitIndex]}`;
    }

    inferMimeType(file) {
        if (file && file.type) return file.type;
        const name = (file && file.name || '').toLowerCase();
        if (name.endsWith('.png')) return 'image/png';
        if (name.endsWith('.jpg') || name.endsWith('.jpeg')) return 'image/jpeg';
        if (name.endsWith('.webp')) return 'image/webp';
        if (name.endsWith('.gif')) return 'image/gif';
        if (name.endsWith('.mp4')) return 'video/mp4';
        if (name.endsWith('.webm')) return 'video/webm';
        // The OS has no mapping for .tgs, so `file.type` arrives empty and the
        // extension is the only signal. Stamping the real type here is what lets
        // the receiving side recognise the sticker without re-sniffing the name.
        if (name.endsWith('.tgs')) return window.ZaliTgs?.TGS_MIME || 'application/x-tgsticker';
        return 'application/octet-stream';
    }

    fileToDataUrl(file) {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => resolve(String(reader.result || ''));
            reader.onerror = () => reject(reader.error || new Error('Не удалось прочитать файл'));
            reader.readAsDataURL(file);
        });
    }

    async fileToAttachment(file) {
        const mimeType = this.inferMimeType(file);
        const kind = this.attachmentKindFor({ name: file.name, mimeType }) || 'file';
        const dataUrl = await this.fileToDataUrl(file);
        return this.normalizeAttachment({
            name: file.name,
            mimeType,
            kind,
            size: file.size,
            dataUrl,
        });
    }

    async handleFiles(fileList) {
        const files = Array.from(fileList || []);
        if (files.length === 0) return;
        const attachments = await Promise.all(files.map(file => this.fileToAttachment(file)));
        this.S.draftAttachments = this.S.draftAttachments.concat(attachments);
        this.renderDraftAttachments();
        this.updateSendButtonState();
    }

    clearDraftAttachments() {
        this.S.draftAttachments = [];
        this.renderDraftAttachments();
        this.updateSendButtonState();
    }

    renderDraftAttachments() {
        const wrap = document.getElementById('draftAttachments');
        if (!wrap) return;

        if (!this.S.draftAttachments.length) {
            wrap.innerHTML = '';
            wrap.classList.remove('has-items');
            // Reaps the sticker animation that was just detached, so its rAF loop
            // stops instead of running against an orphaned node.
            window.ZaliTgs?.hydrate(wrap);
            return;
        }

        wrap.classList.add('has-items');
        wrap.innerHTML = this.S.draftAttachments.map(att => {
            const thumb = this.renderAttachmentPreview(att, true);
            return `<div class="draft-att" data-att-id="${this.esc(att.id)}">
                <button class="draft-att-remove" type="button" data-att-id="${this.esc(att.id)}" title="Удалить вложение">×</button>
                ${thumb}
                <div class="draft-att-name">${this.esc(att.name)}</div>
            </div>`;
        }).join('');

        window.ZaliTgs?.hydrate(wrap);
    }

    resizeComposer() {
        const inp = document.getElementById('msgInput');
        if (!inp) return;
        inp.style.height = 'auto';
        inp.style.height = `${Math.min(inp.scrollHeight, 140)}px`;
    }

    extractUrls(text) {
        if (!text) return [];
        const re = /https?:\/\/[^\s<>()"]+/gi;
        return String(text).match(re) || [];
    }

    isTenorUrl(url) {
        try {
            const u = new URL(url);
            return /(^|\.)tenor\.com$/.test(u.hostname) || /(^|\.)media\d*\.tenor\.com$/.test(u.hostname) || /(^|\.)c\.tenor\.com$/.test(u.hostname);
        } catch (e) {
            return false;
        }
    }

    tenorCacheKey(url) {
        return `tenor:${url}`;
    }

    requestTenorResolution(url) {
        const key = this.tenorCacheKey(url);
        if (this.tenorCache.has(key) || this.tenorPending.has(key)) return;
        this.tenorPending.add(key);

        if (this.nativeSupports('tenor')) {
            this.postNativeMessage({
                type: NativeMessageTypes.RESOLVE_TENOR,
                url,
                requestId: key,
            });
        } else {
            this.tenorPending.delete(key);
        }
    }

    onTenorResolved(payload) {
        let data = payload;
        if (typeof payload === 'string') {
            try {
                data = JSON.parse(payload);
            } catch (e) {
                return;
            }
        }

        if (!data || !data.sourceUrl) return;
        const key = this.tenorCacheKey(data.sourceUrl);
        this.tenorPending.delete(key);

        if (data.mediaUrl) {
            this.tenorCache.set(key, {
                mediaUrl: data.mediaUrl,
                mimeType: data.mimeType || '',
                kind: data.kind || '',
            });
            this.scheduleRenderMessages();
            this.renderContacts();
        }
    }

    isDirectMediaUrl(url) {
        try {
            const u = new URL(url);
            return /\.(gif|png|jpe?g|webp|mp4|webm)(\?.*)?$/i.test(u.pathname);
        } catch (e) {
            return false;
        }
    }

    renderMessageText(text) {
        const urls = this.extractUrls(text);
        if (!urls.length) {
            return this.esc(text).replace(/\n/g, '<br>');
        }

        const escaped = this.esc(text).replace(/\n/g, '<br>');
        return escaped.replace(/https?:\/\/[^\s<>()"]+/gi, (match) => {
            const rawUrl = match.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"');
            const safeHref = this.esc(rawUrl);
            return `<a href="${safeHref}" target="_blank" rel="noopener noreferrer">${match}</a>`;
        });
    }

    mediaShellStyle(src, { gifLike = false, fallbackAspectRatio = '16 / 9' } = {}) {
        if (gifLike) return '';
        const cached = src ? this.mediaSizeCache.get(src) : null;
        const width = Number(cached?.width || 0);
        const height = Number(cached?.height || 0);
        const ratio = width > 0 && height > 0 ? `${width} / ${height}` : fallbackAspectRatio;
        return ratio ? ` style="aspect-ratio: ${ratio};"` : '';
    }

    safeAttachmentUrl(url) {
        const value = String(url || '').trim();
        if (!value) return '';
        if (/^(data|blob):/i.test(value)) return value;
        try {
            const parsed = new URL(value, window.location.href);
            return ['http:', 'https:'].includes(parsed.protocol) ? parsed.href : '';
        } catch (e) {
            return '';
        }
    }

    renderAttachmentPreview(att, compact = false, options = {}) {
        const attachment = this.normalizeAttachment(att);
        // Through attachmentDisplayUrl(): the payload never belongs in the markup.
        const src = this.safeAttachmentUrl(
            this.attachmentDisplayUrl(attachment.dataUrl || attachment.url || ''),
        );
        const gifLike = !!options.gifLike || attachment.kind === 'gif' || attachment.mimeType === 'image/gif';
        const showControls = options.controls !== undefined ? !!options.controls : !gifLike;
        if (!src) {
            return `<div class="media-unknown">${this.esc(attachment.name)}</div>`;
        }

        // Animated stickers are decoded and played by web/src/modules/tgs.js after
        // the message list is in the DOM — all this renders is the stage plus a
        // download link that stays hidden unless the animation fails to load.
        if (attachment.kind === 'sticker') {
            const sizeLabel = this.formatFileSize(attachment.size);
            return `<div class="media media-sticker${compact ? ' compact' : ''}" data-tgs-src="${this.esc(src)}">
                <div class="media-sticker-stage" aria-label="${this.esc(attachment.name)}" role="img"></div>
                <a class="file-chip media-sticker-fallback${compact ? ' compact' : ''}" href="${this.esc(src)}" download="${this.esc(attachment.name)}" hidden>
                    <span class="file-chip-name">${this.esc(attachment.name)}</span>
                    <span class="file-chip-size">${this.esc(sizeLabel)}</span>
                </a>
            </div>`;
        }

        if (attachment.kind === 'video' || (attachment.mimeType || '').startsWith('video/')) {
            const shellClass = `discord-media-shell discord-media-shell-video${gifLike ? ' discord-media-shell-gif' : ''}${compact ? ' compact' : ''}`;
            const shellStyle = this.mediaShellStyle(src, { gifLike });
            // autoplay/loop/muted belong to gif-like clips only. They used to be
            // set unconditionally, so every ordinary video message in the window
            // decoded and looped at once, forever, whether or not anyone had
            // asked it to play — and, being muted by default, an actual video
            // also started silent. A real video now waits for the play button.
            const gifPlayback = gifLike ? ' autoplay loop muted' : '';
            return `<div class="${shellClass}"${shellStyle}>
                <video class="media media-video${compact ? ' compact' : ''}${gifLike ? ' media-gif-like' : ''}" data-gif-like="${gifLike ? '1' : '0'}" src="${this.esc(src)}"${showControls ? ' controls' : ''}${gifPlayback} playsinline preload="${gifLike ? 'auto' : 'metadata'}"></video>
            </div>`;
        }

        if (attachment.kind === 'gif' || attachment.mimeType === 'image/gif' || (attachment.mimeType || '').startsWith('image/')) {
            const gifClass = gifLike ? ' media-gif-like' : '';
            const shellGifClass = gifLike ? ' discord-media-shell-gif' : '';
            const shellStyle = this.mediaShellStyle(src, { gifLike });
            return `<div class="discord-media-shell discord-media-shell-image${shellGifClass}${compact ? ' compact' : ''}"${shellStyle}>
                <img class="media media-img${compact ? ' compact' : ''}${gifClass}" src="${this.esc(src)}" alt="${this.esc(attachment.name)}" loading="lazy" decoding="async" fetchpriority="low">
            </div>`;
        }

        // Audio has no visual frame to preview, but it's the one remaining kind
        // that can still play inline rather than falling back to a download link.
        if (attachment.kind === 'audio' || (attachment.mimeType || '').startsWith('audio/')) {
            const sizeLabel = this.formatFileSize(attachment.size);
            return `<div class="media-audio${compact ? ' compact' : ''}">
                <audio class="media-audio-player" controls preload="metadata" src="${this.esc(src)}"></audio>
                <div class="media-audio-meta">
                    <span class="media-audio-name">${this.esc(attachment.name)}</span>
                    <span class="media-audio-size">${this.esc(sizeLabel)}</span>
                </div>
            </div>`;
        }

        // No format-specific preview (a .pdf, .docx, .zip, ...) — a neutral icon
        // carrying the extension stands in for one, same idea as Telegram/Slack's
        // file glyphs, so the type is readable at a glance instead of only in the
        // filename text.
        const sizeLabel = this.formatFileSize(attachment.size);
        const fileIcon = this.renderFileIcon(attachment.name);
        if (compact) {
            // No name here: this is only ever used by the draft-attachment
            // thumbnail, which already prints the filename underneath
            // (.draft-att-name) — repeating it inside the chip too just wrapped
            // ugly in the narrow thumbnail.
            return `<a class="file-chip${compact ? ' compact' : ''}" href="${this.esc(src)}" download="${this.esc(attachment.name)}">
                ${fileIcon}
                <span class="file-chip-size">${this.esc(sizeLabel)}</span>
            </a>`;
        }

        return `<a class="file-message" href="${this.esc(src)}" download="${this.esc(attachment.name)}">
            ${fileIcon}
            <span class="file-message-info">
                <span class="file-message-name">${this.esc(attachment.name)}</span>
                <span class="file-message-size">${this.esc(sizeLabel)}</span>
            </span>
        </a>`;
    }
});


// --- MODULE: interface/message_render.js ---
// --- ZaliInterface: Отрисовка тела сообщения, реакции, статусы. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    sanitizeDecryptionErrorText(text) {
        const value = String(text || '').trim();
        if (!value) return '';
        if (/^(?:🚨\s*)?\[Ошибка расшифрования:[^\]]*\]$/.test(value)) {
            return '';
        }
        return text;
    }

    // Recognizes the fixed-format strings the app itself generates for a message
    // body — a ZaliCoin transfer notice (submitCoinTransfer) or a native-layer
    // decryption/download placeholder (WebView.swift / native.rs) — so they can be
    // rendered as a distinct system pill instead of a normal chat bubble. This is a
    // *display-only* affordance, not an authenticity guarantee: it matches on exact
    // wording, so a peer could type the identical string and see the same styling.
    // Good enough to tell "the app posted this" apart from an ordinary message at a
    // glance, not to prove provenance.
    detectSystemNotice(text) {
        const value = String(text || '').trim();
        if (!value) return null;
        // Accepts both the current "💰 <name> перевёл(а) N ZaliCoin" wording and the
        // older nameless one (submitCoinTransfer used to omit the sender), so a
        // transfer notice sent before that changed still renders as a pill instead
        // of reverting to a plain bubble.
        if (/^💰\s*(?:\S+\s+)?[Пп]еревёл\(а\)\s+\d+(?:[.,]\d+)?\s+ZaliCoin$/.test(value)) return 'transfer';
        if (
            /^🔒\s*Сообщение зашифровано другим ключом$/.test(value) ||
            /^🔑\s*Получение ключа…?$/.test(value) ||
            /^📦\s*Файл сообщения превышает допустимый размер$/.test(value) ||
            /^⚠️\s*Не удалось загрузить сообщение$/.test(value) ||
            // The Windows/Rust shell writes its own wording (native/messages.rs's
            // undecryptable_placeholder) and carries no emoji marker. It was missing
            // from this list entirely, so on Windows a message that would not decrypt
            // rendered as an ordinary chat bubble and — far worse — never reached
            // queueDecryptFailureReport, which is what asks the holders to republish.
            // The one mechanism that repairs an unreadable conversation was therefore
            // unreachable on that platform, exactly as it was on Android before the
            // key_republish_request routing was split out.
            /^Не удалось расшифровать сообщение:/.test(value) ||
            /^(?:🚨\s*)?\[Ошибка расшифрования:[^\]]*\]$/.test(value)
        ) return 'decrypt-error';
        return null;
    }

    // Maps a decrypt-error placeholder to a short, stable slug for
    // reportDecryptFailure()'s `reason` field — grouping reports by cause
    // instead of leaving the server to parse (and re-translate) free text.
    decryptFailureReasonSlug(text) {
        const value = String(text || '');
        if (/зашифровано другим ключом/.test(value)) return 'wrong-key';
        if (/Получение ключа/.test(value)) return 'awaiting-key';
        if (/превышает допустимый размер/.test(value)) return 'oversized';
        if (/Не удалось загрузить/.test(value)) return 'download-failed';
        // Windows shell wording; the cause is the same as 'wrong-key' — no key this
        // device holds opened the archive.
        if (/Не удалось расшифровать сообщение/.test(value)) return 'wrong-key';
        if (/Ошибка расшифрования/.test(value)) return 'legacy-decrypt-error';
        return 'unknown';
    }

    // Phones home with everything locally available that could explain a
    // decryption failure — added while chasing "переписки пропадают, растёт
    // число ошибок расшифровки" (2026-07-31). Deliberately best-effort: never
    // throws, never blocks rendering, and is skipped entirely while logged
    // out (the server can't attribute an unauthenticated report to anyone).
    // Only a SHA-256 fingerprint of any key is ever sent — see
    // conversationKeyId() — never the key itself.
    // Render-loop entry point for a decryption failure.
    //
    // _renderMessagesNow() hits one of these per undecryptable message, so a
    // screenful of unreadable history used to fire, from inside the render
    // frame, one POST *and* one canonical-key lookup per message — the lookup
    // has no cache shortcut of its own, so fifty placeholders meant a hundred
    // requests leaving at once, plus a DOM read of the log panel for each. The
    // reports are worth keeping; doing them during the frame is not.
    //
    // Deferred out of the frame, and the whole batch shares a single canonical
    // lookup instead of repeating it per message.
    queueDecryptFailureReport(details = {}) {
        if (!this._decryptFailureQueue) this._decryptFailureQueue = [];
        // Bounded: a very long unreadable history should cost a fixed amount of
        // telemetry, not one request per row.
        if (this._decryptFailureQueue.length >= 50) return;
        this._decryptFailureQueue.push(details);
        if (this._decryptFailureFlushTimer) return;
        this._decryptFailureFlushTimer = setTimeout(() => {
            this._decryptFailureFlushTimer = 0;
            void this.flushDecryptFailureReports();
        }, 300);
    }

    async flushDecryptFailureReports() {
        const batch = this._decryptFailureQueue || [];
        this._decryptFailureQueue = [];
        if (!batch.length) return;
        const scopes = Array.from(new Set(batch
            .map(details => details.scope || this.conversationScopeKey(
                details.sender === this.myName() ? details.receiver : details.sender,
                details.serverId,
                details.channelId,
            ))
            .filter(Boolean)));
        // One lookup for the whole batch; each report below then reads it from
        // the cache instead of asking again.
        try { await this.fetchCanonicalKeyIds(scopes); } catch (e) {}
        for (const details of batch) {
            await this.reportDecryptFailure({ ...details, useCachedCanonicalKeyIds: true });
        }
    }

    async reportDecryptFailure(details = {}) {
        if (!this.S.session?.token) return;
        const key = [
            details.messageId || details.clientId || '',
            details.sender || '',
            details.receiver || '',
            details.serverId || '',
            details.channelId || '',
        ].join('|');
        if (!this._reportedDecryptFailures) this._reportedDecryptFailures = new Set();
        if (key && this._reportedDecryptFailures.has(key)) return;
        if (key) {
            this._reportedDecryptFailures.add(key);
            // Bounded so a long-lived tab doesn't grow this forever.
            if (this._reportedDecryptFailures.size > 500) {
                this._reportedDecryptFailures.delete(this._reportedDecryptFailures.values().next().value);
            }
        }
        try {
            const scope = details.scope || this.conversationScopeKey(
                details.sender === this.myName() ? details.receiver : details.sender,
                details.serverId,
                details.channelId,
            );
            const localKey = scope ? this.getStoredConversationKey(scope) : '';
            const localKeyId = localKey ? await this.conversationKeyId(localKey) : '';
            let canonicalKeyId = '';
            if (scope) {
                try {
                    const canonical = await this.fetchCanonicalKeyIds([scope], {
                        allowCached: !!details.useCachedCanonicalKeyIds,
                    });
                    canonicalKeyId = canonical.get(scope) || '';
                } catch (e) { /* best-effort — see fetchCanonicalKeyIds's own fallback */ }
            }
            const logBody = document.getElementById('logBody');
            const recentLog = logBody
                ? Array.from(logBody.children).slice(-30).map(el => String(el.textContent || '').slice(0, 300))
                : [];
            const payload = {
"""#,
    #"""
                reason: details.reason || this.decryptFailureReasonSlug(details.placeholderText || ''),
                placeholderText: String(details.placeholderText || '').slice(0, 200),
                clientError: String(details.clientError || '').slice(0, 500),
                messageId: details.messageId || '',
                clientId: details.clientId || '',
                sender: details.sender || '',
                receiver: details.receiver || '',
                serverId: details.serverId || '',
                channelId: details.channelId || '',
                scope,
                messageTimestamp: details.messageTimestamp || '',
                hasLocalKey: !!localKey,
                localKeyId,
                canonicalKeyId,
                keyMatches: (localKeyId && canonicalKeyId) ? (localKeyId === canonicalKeyId) : null,
                deviceId: this.currentDeviceId(),
                platform: this.hasNativeBridge() ? 'native' : 'browser',
                userAgent: (typeof navigator !== 'undefined' && navigator.userAgent) || '',
                recentLog,
                reportedAt: new Date().toISOString(),
            };
            await this.apiFetch(this.apiRoutes.diagnostics.decryptFailure, {
                method: 'POST',
                body: JSON.stringify(payload),
            });
            // Telemetry alone changed nothing for the user: this reported that a
            // message was unreadable and then stopped, while the one mechanism that
            // could fix it — asking the holders to republish — was only ever
            // triggered when a scope had NO key at all. A message that fails to
            // decrypt while we do hold a key for the scope is the exact signal that
            // we are missing some OTHER key of that scope, so ask.
            // Explicitly caught: every helper it calls swallows its own errors today,
            // but this is fire-and-forget from a render path — one future throw in
            // that chain would surface as an unhandled rejection instead of a trace.
            if (scope) {
                this.requestKeyRepublishForDecryptFailure(scope)
                    .catch(err => this.trace(`requestKeyRepublishForDecryptFailure failed error=${err?.message || err}`));
            }
        } catch (e) {
            this.trace(`reportDecryptFailure failed error=${e?.message || e}`);
        }
    }

    // Rate-limited per scope: a screenful of undecryptable history would otherwise
    // fire one request per message, and every request fans out to every device of
    // every participant.
    async requestKeyRepublishForDecryptFailure(scope, { cooldownMs = 60000 } = {}) {
        const scoped = this.canonicalConversationScope(String(scope || '').trim());
        if (!scoped) return false;
        if (!this._republishAskedAt) this._republishAskedAt = new Map();
        const last = Number(this._republishAskedAt.get(scoped) || 0);
        if (last && Date.now() - last < cooldownMs) return false;
        this._republishAskedAt.set(scoped, Date.now());
        const ok = await this.requestKeyRepublish(scoped, { reason: 'decrypt_failure' });
        if (ok) {
            // The answer arrives as envelopes; pick them up without waiting for the
            // next scheduled sync, then re-render so the message stops being a
            // placeholder.
            await this.syncIncomingKeyEnvelopes({ reason: 'decrypt_failure', triggerRefresh: true });
        }
        return ok;
    }

    hydrateGifMedia(root = document) {
        // Animated stickers need the same treatment as GIF-like videos — they can
        // only be booted once their node is in the document — so they piggyback on
        // the single post-render hook every message list already calls.
        window.ZaliTgs?.hydrate(root);

        const videos = root.querySelectorAll?.('video.media-gif-like[data-gif-like="1"]') || [];
        videos.forEach(video => {
            if (!(video instanceof HTMLMediaElement)) return;
            if (video.dataset.gifBound === '1') return;

            video.dataset.gifBound = '1';
            video.loop = true;
            video.muted = true;
            video.playsInline = true;
            video.preload = 'auto';
            video.style.backgroundColor = 'transparent';
            video.style.objectFit = 'contain';
            video.style.width = '100%';
            video.style.height = '100%';
            video.style.removeProperty('aspect-ratio');

            const shell = video.closest('.discord-media-shell');
            const src = video.currentSrc || video.src || video.getAttribute('src') || '';
            const cacheSize = (width, height) => {
                if (!src || !width || !height) return;
                this.mediaSizeCache.set(src, { width, height });
            };

            const ensurePlaying = () => {
                if (video.dataset.userPaused === '1') return;
                if (video.paused) {
                    video.play?.().catch(() => {});
                }
            };

            const syncFromMetadata = () => {
                const width = Number(video.videoWidth || 0);
                const height = Number(video.videoHeight || 0);
                cacheSize(width, height);
                ensurePlaying();
            };

            video.addEventListener('loadedmetadata', syncFromMetadata, { once: true });
            video.addEventListener('loadeddata', syncFromMetadata, { once: true });

            if (window.IntersectionObserver) {
                const observer = new IntersectionObserver((entries) => {
                    const entry = entries[0];
                    if (!entry) return;
                    if (video.dataset.userPaused === '1') return;
                    if (entry.isIntersecting) {
                        ensurePlaying();
                        return;
                    }
                    // Symmetric pause. Without it this observer could only ever
                    // start playback, so a looping clip scrolled out of the
                    // window kept decoding frames for the rest of the session —
                    // in a media-heavy chat, several of them at once. Animated
                    // stickers already do exactly this (modules/tgs.js); a
                    // paused element keeps its current frame, so nothing about
                    // the picture changes, only the work behind it.
                    if (!video.paused) video.pause?.();
                }, { root: null, threshold: 0.15, rootMargin: '160px' });
                observer.observe(video);
                video.dataset.gifObserver = '1';
                return;
            }

            ensurePlaying();
        });

        // Covers every message-attachment image (not just gif-like ones): the shell's
        // box-shaping aspect-ratio is set from mediaSizeCache at render time, but on
        // first render nothing is cached yet, so it falls back to a hardcoded 16:9 box.
        // If the real photo isn't 16:9, its actual (height:auto) box disagrees with that
        // fallback and the shell's `overflow:hidden` crops it. Once the image decodes we
        // know its true size — cache it AND correct the already-rendered shell in place
        // so the crop clears immediately instead of waiting for an unrelated re-render.
        const images = root.querySelectorAll?.('img.media-img:not([data-size-bound="1"])') || [];
        images.forEach(img => {
            if (!(img instanceof HTMLImageElement)) return;
            img.dataset.sizeBound = '1';
            const shell = img.closest('.discord-media-shell');
            const src = img.currentSrc || img.src || img.getAttribute('src') || '';
            const syncFromImage = () => {
                const width = Number(img.naturalWidth || 0);
                const height = Number(img.naturalHeight || 0);
                if (!src || !width || !height) return;
                this.mediaSizeCache.set(src, { width, height });
                if (shell && !img.classList.contains('media-gif-like')) {
                    shell.style.aspectRatio = `${width} / ${height}`;
                }
            };
            if (img.complete) {
                syncFromImage();
            } else {
                img.addEventListener('load', syncFromImage, { once: true });
            }
        });
    }

    renderUrlPreview(url) {
        if (!url) return '';
        let path = '';
        try {
            path = new URL(url).pathname.toLowerCase();
        } catch (e) {
            path = url.toLowerCase();
        }

        if (this.isTenorUrl(url)) {
            if (this.isDirectMediaUrl(url)) {
                return this.renderAttachmentPreview({
                    name: 'Tenor',
                    mimeType: path.endsWith('.mp4') ? 'video/mp4' : path.endsWith('.webm') ? 'video/webm' : 'image/gif',
                    kind: path.endsWith('.mp4') || path.endsWith('.webm') ? 'video' : 'gif',
                    dataUrl: url
                }, false, { gifLike: true });
            }

            const cached = this.tenorCache.get(this.tenorCacheKey(url));
            if (cached?.mediaUrl) {
                const mimeType = cached.mimeType || (path.endsWith('.mp4') ? 'video/mp4' : 'image/gif');
                const kind = cached.kind || (mimeType.startsWith('video/') ? 'video' : 'gif');
                return this.renderAttachmentPreview({
                    name: 'Tenor',
                    mimeType,
                    kind,
                    dataUrl: cached.mediaUrl
                }, false, { gifLike: true });
            }

            this.requestTenorResolution(url);
            return `<div class="media media-tenor media-tenor-pending">
                <div class="tenor-badge">Tenor GIF</div>
                <div class="tenor-hint">Загружаем анимацию...</div>
            </div>`;
        }

        if (this.isDirectMediaUrl(url)) {
            return this.renderAttachmentPreview({
                name: url.split('/').pop() || 'media',
                mimeType: path.endsWith('.mp4') ? 'video/mp4' : path.endsWith('.webm') ? 'video/webm' : path.endsWith('.gif') ? 'image/gif' : 'image/*',
                kind: path.endsWith('.mp4') || path.endsWith('.webm') ? 'video' : 'image',
                dataUrl: url
            });
        }

        return '';
    }

    renderMessageBody(msg) {
        if (msg?.kind === 'call') {
            return this.renderCallMessage(msg);
        }
        const attachments = this.normalizeAttachments(msg.attachments);
        const urls = this.extractUrls(msg.text);
        const isOnlyUrl = (msg.text || '').trim() && urls.length === 1 && (msg.text || '').trim() === urls[0];
        const previewBlocks = urls.map(url => this.renderUrlPreview(url)).filter(Boolean);
        const bodyParts = [];

        // Always first in the bubble — the quote is context for everything below it.
        const quoteBlock = this.renderReplyQuote(msg);
        if (quoteBlock) bodyParts.push(quoteBlock);

        if (!isOnlyUrl || previewBlocks.length === 0 || (msg.text || '').trim() !== urls[0]) {
            if (msg.text) {
                bodyParts.push(`<div class="msg-text">${this.renderMessageText(msg.text)}</div>`);
            }
        }

        if (attachments.length) {
            bodyParts.push(`<div class="msg-attachments">${attachments.map(att => this.renderAttachmentPreview(att)).join('')}</div>`);
        }

        if (previewBlocks.length) {
            bodyParts.push(`<div class="msg-attachments msg-link-previews">${previewBlocks.join('')}</div>`);
        }

        return bodyParts.join('');
    }

    renderCallMessage(msg) {
        const call = msg?.call || {};
        const direction = String(call.direction || '').trim() || (this.isOutgoingMessage(msg) ? 'outgoing' : 'incoming');
        const outcome = String(call.outcome || '').trim() || 'completed';
        const peer = String(call.peer || msg.receiver || msg.sender || '').trim();
        const startedAt = call.connectedAt || call.startedAt || msg.timestamp;
        const endedAt = call.endedAt || msg.timestamp;
        const durationMs = Number(call.durationMs || 0) || 0;
        const whenLabel = this.fmtDate(startedAt);
        const timeLabel = this.fmtTime(startedAt || endedAt);
        const durationLabel = this.formatDuration(durationMs);
        const title = outcome === 'missed'
            ? `Пропущенный звонок`
            : outcome === 'rejected'
                ? `Звонок отклонён`
                : outcome === 'cancelled'
                    ? `Звонок отменён`
                    // The client gave up on a call it could no longer recover — see
                    // concludeDeadVoiceCallIfNeeded. Without this it read as an
                    // ordinary completed call, which is the one thing it was not.
                    : outcome === 'failed'
                        ? `Звонок прерван`
                        : direction === 'outgoing'
                            ? `Исходящий звонок`
                            : `Входящий звонок`;
        const subject = direction === 'outgoing'
            ? `К ${peer || 'контакту'}`
            : `От ${peer || 'контакта'}`;
        const durationText = durationLabel === '00:00' && outcome !== 'completed'
            ? '00:00'
            : durationLabel;
        return `
            <div class="call-card ${this.esc(outcome)} ${this.esc(direction)}">
                <div class="call-card-top">
                    <div class="call-card-icon">${outcome === 'completed' ? this.uiIcon('phone') : this.uiIcon('close')}</div>
                    <div class="call-card-copy">
                        <div class="call-card-title">${this.esc(title)}</div>
                        <div class="call-card-sub">${this.esc(subject)}</div>
                    </div>
                </div>
                <div class="call-card-meta">
                    <span>Когда: ${this.esc(whenLabel ? `${whenLabel}, ${timeLabel}` : timeLabel)}</span>
                    <span>Длительность: ${this.esc(durationText)}</span>
                </div>
            </div>
        `;
    }

    messageHasMedia(msg) {
        const attachments = this.normalizeAttachments(msg.attachments);
        if (attachments.some(att => att.kind === 'image' || att.kind === 'video' || att.kind === 'gif' || att.kind === 'sticker' || (att.mimeType || '').startsWith('image/') || (att.mimeType || '').startsWith('video/'))) {
            return true;
        }
        const urls = this.extractUrls(msg.text);
        return urls.some(url => this.isTenorUrl(url) || this.isDirectMediaUrl(url));
    }

    messageIsGifOnly(msg) {
        const text = (msg.text || '').trim();
        if (text) return false;

        const attachments = this.normalizeAttachments(msg.attachments);
        if (attachments.length > 0) {
            // Stickers ride along here so a lone sticker gets the same
            // chrome-less `media-only` treatment a lone GIF does.
            return attachments.every(att =>
                att.kind === 'gif' ||
                att.kind === 'sticker' ||
                att.mimeType === 'image/gif' ||
                (att.mimeType || '').startsWith('image/')
            );
        }

        const urls = this.extractUrls(msg.text);
        if (urls.length !== 1) return false;

        const url = urls[0];
        if (!this.isTenorUrl(url) && !this.isDirectMediaUrl(url)) return false;
        const path = (() => {
            try { return new URL(url).pathname.toLowerCase(); }
            catch (e) { return url.toLowerCase(); }
        })();
        return path.endsWith('.gif') || this.isTenorUrl(url);
    }

    // A photo/gif/sticker sent with a caption: same "is every attachment
    // image-like" test as messageIsGifOnly(), but for the text-present case that
    // method deliberately excludes. Kept attachment-only (no Tenor/URL-preview
    // variant) — a caption on a bare pasted link is a rarer, lower-value case not
    // worth the extra branching.
    messageIsImageCaption(msg) {
        const text = (msg.text || '').trim();
        if (!text) return false;
        const attachments = this.normalizeAttachments(msg.attachments);
        if (!attachments.length) return false;
        return attachments.every(att =>
            att.kind === 'gif' ||
            att.kind === 'sticker' ||
            att.mimeType === 'image/gif' ||
            (att.mimeType || '').startsWith('image/')
        );
    }

    messageSummary(msg) {
        if (msg?.kind === 'call') {
            const call = msg.call || {};
            const direction = String(call.direction || '').trim();
            const outcome = String(call.outcome || '').trim();
            const peer = String(call.peer || msg.receiver || msg.sender || '').trim();
            const duration = this.formatDuration(call.durationMs || 0);
            if (outcome === 'missed') return `Пропущенный звонок${peer ? ` · ${peer}` : ''}`;
            if (outcome === 'rejected') return `Отклонённый звонок${peer ? ` · ${peer}` : ''}`;
            if (outcome === 'cancelled') return `Отменённый звонок${peer ? ` · ${peer}` : ''}`;
            return `Звонок${peer ? ` · ${peer}` : ''}${duration ? ` · ${duration}` : ''}`;
        }
        const attachments = this.normalizeAttachments(msg.attachments);
        if (attachments.length) {
            const first = attachments[0];
            if (first.kind === 'sticker') return 'Стикер';
            if (first.kind === 'video' || first.mimeType.startsWith('video/')) return 'Видео';
            if (first.kind === 'gif' || first.mimeType === 'image/gif') return 'GIF';
            if (first.mimeType.startsWith('image/')) return 'Фото';
            if (first.kind === 'audio' || first.mimeType.startsWith('audio/')) return 'Аудио';
            return 'Файл';
        }

        const urls = this.extractUrls(msg.text);
        if (urls.some(url => this.isTenorUrl(url))) {
            return 'Tenor GIF';
        }

        const text = (msg.text || '').trim();
        if (!text) return 'Сообщение';
        return text.length > 32 ? `${text.slice(0, 32)}…` : text;
    }

    messageRenderKey(msg) {
        if (!msg || typeof msg !== 'object') return '';
        if (msg.clientId) return `cid:${msg.clientId}`;
        if (msg.id) return `id:${msg.id}`;
        const attachments = this.normalizeAttachments(msg.attachments);
        const attachmentKey = attachments
            .map(att => `${att.name}:${att.kind}:${att.size}:${att.mimeType}`)
            .join('|');
        const call = msg.kind === 'call' ? msg.call || {} : {};
        return [
            msg.kind || '',
            msg.sender || '',
            msg.receiver || '',
            msg.timestamp || '',
            msg.text || '',
            call.roomId || '',
            call.direction || '',
            call.outcome || '',
            call.peer || '',
            call.durationMs || '',
            attachmentKey,
        ].join('::');
    }

    normalizeReactions(reactions) {
        if (!reactions) return [];
        const list = Array.isArray(reactions)
            ? reactions
            : Object.entries(reactions).map(([emoji, count]) => ({ emoji, count }));
        return list
            .map(item => ({
                emoji: String(item?.emoji || '').trim(),
                count: Number(item?.count || 0) || 0,
            }))
            .filter(item => item.emoji && item.count > 0)
            .sort((a, b) => b.count - a.count || a.emoji.localeCompare(b.emoji));
    }

    // A user can react to a message with several distinct emoji at once
    // (Discord-style) — myReactions is a set, not a single slot.
    normalizeMyReactions(value) {
        const list = Array.isArray(value) ? value : (value ? [value] : []);
        return Array.from(new Set(list.map(v => String(v || '').trim()).filter(Boolean)));
    }

    findMessageById(messageId) {
        const id = String(messageId || '').trim();
        if (!id) return null;
        for (const [peer, msgs] of Object.entries(this.S.chats)) {
            const index = msgs.findIndex(msg => String(msg.id || '').trim() === id || String(msg.clientId || '').trim() === id);
            if (index >= 0) {
                return { peer, msg: msgs[index], index };
            }
        }
        for (const [key, msgs] of Object.entries(this.S.serverChats || {})) {
            const index = msgs.findIndex(msg => String(msg.id || '').trim() === id || String(msg.clientId || '').trim() === id);
            if (index >= 0) {
                return { peer: key, msg: msgs[index], index, serverKey: key };
            }
        }
        return null;
    }

    renderMessageReactions(msg) {
        const messageId = String(msg?.id || '').trim();
        if (!messageId) return '';

        const reactions = this.normalizeReactions(msg.reactions);
        const myReactions = this.normalizeMyReactions(msg.myReactions);
        return reactions.length
            ? `<div class="reaction-row">
                ${reactions.map(reaction => {
                    const mine = myReactions.includes(reaction.emoji) ? ' mine' : '';
                    return `<span class="reaction-chip${mine}" title="${this.esc(reaction.emoji)}" data-message-id="${this.esc(messageId)}" data-message-reaction="${this.esc(reaction.emoji)}">
                        <span class="reaction-emoji">${this.esc(reaction.emoji)}</span>
                        <span class="reaction-count">${reaction.count}</span>
                    </span>`;
                }).join('')}
            </div>`
            : '';
    }

    ensureReactionMenu() {
        let menu = document.getElementById('reactionMenu');
        if (menu) return menu;
        menu = document.createElement('div');
        menu.id = 'reactionMenu';
        menu.className = 'reaction-menu';
        menu.setAttribute('aria-hidden', 'true');
        menu.innerHTML = this.reactionOptions.map(emoji => (
            `<button class="reaction-btn" type="button" data-menu-reaction="${this.esc(emoji)}" aria-label="${this.esc(emoji)}"><span class="reaction-btn-emoji">${this.esc(emoji)}</span></button>`
        )).join('')
            // Действия — иконки общего набора (uiIcon), а не глифы ↩ ✎ 🗑:
            // последние рисуются шрифтом ОС и рядом с цветными эмодзи
            // выглядели то бледной палочкой, то ещё одним эмодзи, причём
            // по-разному на macOS, Windows и Android.
            + `<span class="reaction-menu-sep" aria-hidden="true"></span>`
            + `<button class="reaction-btn reaction-btn-action" type="button" data-menu-reply title="Ответить" aria-label="Ответить на сообщение">${this.uiIcon('reply')}</button>`
            + `<button class="reaction-btn reaction-btn-action" type="button" data-menu-edit title="Изменить" aria-label="Изменить сообщение" hidden>${this.uiIcon('pencil')}</button>`
            + `<button class="reaction-btn reaction-btn-delete" type="button" data-menu-delete title="Удалить" aria-label="Удалить сообщение" hidden>${this.uiIcon('trash')}</button>`;
        document.body.appendChild(menu);

        menu.addEventListener('click', (e) => {
            const replyBtn = e.target.closest('[data-menu-reply]');
            if (replyBtn) {
                const messageId = menu.getAttribute('data-message-id');
                this.hideReactionMenu();
                if (messageId) this.startReplyToMessage(messageId);
                return;
            }
            const editBtn = e.target.closest('[data-menu-edit]');
            if (editBtn) {
                const messageId = menu.getAttribute('data-message-id');
                this.hideReactionMenu();
                if (messageId) this.startEditMessage(messageId);
                return;
            }
            const deleteBtn = e.target.closest('[data-menu-delete]');
            if (deleteBtn) {
                const messageId = menu.getAttribute('data-message-id');
                this.hideReactionMenu();
                if (messageId) {
                    void this.deleteMessage(messageId);
                }
                return;
            }
            const btn = e.target.closest('[data-menu-reaction]');
            if (!btn) return;
            const emoji = btn.getAttribute('data-menu-reaction');
            const messageId = menu.getAttribute('data-message-id');
            if (messageId && emoji) {
                this.addReaction(messageId, emoji);
            }
            this.hideReactionMenu();
        });

        return menu;
    }

    showReactionMenu(messageEl, messageId, x, y) {
        const menu = this.ensureReactionMenu();
        if (!menu || !messageEl) return;
        menu.setAttribute('data-message-id', messageId);
        const found = this.findMessageById(messageId);
        const deleteBtn = menu.querySelector('[data-menu-delete]');
        if (deleteBtn) {
            deleteBtn.hidden = !this.canDeleteMessage(found?.msg);
        }
        const editBtn = menu.querySelector('[data-menu-edit]');
        if (editBtn) {
            editBtn.hidden = !this.canEditMessage(found?.msg);
        }
        const replyBtn = menu.querySelector('[data-menu-reply]');
        if (replyBtn) {
            // A call record is not something you can quote meaningfully, and a
            // message still in the outbox has no id for the quote to point at.
            replyBtn.hidden = !found?.msg || found.msg.kind === 'call';
        }
        menu.classList.add('visible');
        menu.setAttribute('aria-hidden', 'false');
        menu.style.left = '0px';
        menu.style.top = '0px';
        // Размер берём из layout-бокса, а не из getBoundingClientRect():
        // у скрытого состояния меню есть transform: scale(...), и
        // прямоугольник в момент показа возвращает уменьшенную копию —
        // погрешность уходит прямо в расчёт края экрана.
        const menuRect = { width: menu.offsetWidth, height: menu.offsetHeight };
        const anchor = messageEl.querySelector('.bwrap') || messageEl;
        const anchorRect = anchor.getBoundingClientRect();
        const pad = 12;
        const gap = 10;
        const maxLeft = window.innerWidth - menuRect.width - pad;
        const maxTop = window.innerHeight - menuRect.height - pad;
        const preferredLeft = anchorRect.left + (anchorRect.width - menuRect.width) / 2;
        const fallbackLeft = Number.isFinite(x) ? x - menuRect.width / 2 : preferredLeft;
        const left = Math.max(pad, Math.min(Number.isFinite(preferredLeft) ? preferredLeft : fallbackLeft, maxLeft));
        // On mobile the chat app-bar is sticky over the message list, so the
        // menu must never be placed under it — clamp to just below its bottom
        // edge instead of the plain viewport padding.
        const headerBottom = this.isMobileLayout()
            ? (document.querySelector('#viewChat .chat-hdr')?.getBoundingClientRect().bottom || 0) + 8
            : 0;
        const topInset = Math.max(pad, headerBottom);
        const topAbove = anchorRect.top - menuRect.height - gap;
        const topBelow = anchorRect.bottom + gap;
        const preferredTop = topAbove >= topInset ? topAbove : topBelow;
        const fallbackTop = Number.isFinite(y) ? y - menuRect.height - gap : preferredTop;
        const top = Math.max(topInset, Math.min(Number.isFinite(preferredTop) ? preferredTop : fallbackTop, maxTop));
        menu.style.left = `${left}px`;
        menu.style.top = `${top}px`;
    }

    hideReactionMenu() {
        const menu = document.getElementById('reactionMenu');
        if (!menu) return;
        menu.classList.remove('visible');
        menu.setAttribute('aria-hidden', 'true');
        menu.removeAttribute('data-message-id');
    }

    markMessageSeen(msg) {
        const key = this.messageRenderKey(msg);
        if (key) this.messageAnimSeen.add(key);
    }

    dmSidebarSignature() {
        const q = String(this.S.searchQ || '').toLowerCase();
        const me = this.myName();
        return (this.S.contacts || [])
            .filter(contact => contact !== me && (!q || String(contact || '').toLowerCase().includes(q)))
            .map((contact, index) => ({
                name: contact,
                lastMessageAt: this.conversationLastMessageAt(contact),
                unread: Number(this.S.unread?.[contact] || 0),
                lastKey: this.messageRenderKey((this.S.chats?.[contact] || []).slice(-1)[0] || {}),
                active: contact === this.S.current ? 1 : 0,
                index,
            }))
            .sort((a, b) => b.lastMessageAt - a.lastMessageAt || a.name.localeCompare(b.name, 'ru', { sensitivity: 'base' }) || a.index - b.index)
            .map(item => `${item.name}:${item.lastMessageAt}:${item.unread}:${item.lastKey}:${item.active}`)
            .join('|');
    }

    messageStableSignature(msg = {}) {
        if (!msg || typeof msg !== 'object') return '';
        const reactions = Array.isArray(msg.reactions) ? msg.reactions.length : 0;
        const attachments = Array.isArray(msg.attachments) ? msg.attachments.length : 0;
        return [
            this.messageRenderKey(msg),
            String(msg.status || ''),
            String(msg.text || '').length,
            // messageRenderKey collapses to `id:<id>` once a message is stored and
            // the text is only sampled by LENGTH above, so an edit that keeps the
            // length would otherwise render as no change at all.
            Number(msg.editRev || 0),
            String(msg.reply || '').length,
            reactions,
            attachments,
            this.normalizeMyReactions(msg.myReactions).slice().sort().join(','),
        ].join(':');
    }

    activeMessagesSignature() {
        if (this.S.navMode === 'servers') {
            const key = this.serverChatKey();
            return (this.S.serverChats?.[key] || []).map(msg => this.messageStableSignature(msg)).join('|');
        }
        const peer = this.S.current;
        return (this.S.chats?.[peer] || []).map(msg => this.messageStableSignature(msg)).join('|');
    }

    markMessageStatus(clientId, status) {
        if (!clientId) return;
        let updated = false;
        for (const peer of Object.keys(this.S.chats)) {
            const msgs = this.S.chats[peer];
            for (let i = msgs.length - 1; i >= 0; i--) {
                if (msgs[i].clientId === clientId) {
                    msgs[i].status = status;
                    if (status === 'error') msgs[i].error = true;
                    updated = true;
                    break;
                }
            }
            // No visible status badges in the message UI, so avoid full rerender.
            // The data is still updated for persistence / history consistency.
            if (updated) break;
        }
        if (!updated) {
            for (const key of Object.keys(this.S.serverChats || {})) {
                const msgs = this.S.serverChats[key];
                for (let i = msgs.length - 1; i >= 0; i--) {
                    if (msgs[i].clientId === clientId) {
                        msgs[i].status = status;
                        if (status === 'error') msgs[i].error = true;
                        updated = true;
                        break;
                    }
                }
                if (updated) break;
            }
        }
    }

    finalizePendingMessage(clientId, messageId, { render = true } = {}) {
        const pendingId = String(clientId || '').trim();
        if (!pendingId) return false;
        const serverId = String(messageId || '').trim();
        let updated = false;
        for (const peer of Object.keys(this.S.chats)) {
            const msgs = this.S.chats[peer];
            for (let i = msgs.length - 1; i >= 0; i--) {
                if (String(msgs[i].clientId || '').trim() === pendingId) {
                    msgs[i].status = 'sent';
                    delete msgs[i].error;
                    if (serverId) msgs[i].id = serverId;
                    updated = true;
                    break;
                }
            }
            if (updated) break;
        }
        if (!updated) {
            for (const key of Object.keys(this.S.serverChats || {})) {
                const msgs = this.S.serverChats[key];
                for (let i = msgs.length - 1; i >= 0; i--) {
                    if (String(msgs[i].clientId || '').trim() === pendingId) {
                        msgs[i].status = 'sent';
                        delete msgs[i].error;
                        if (serverId) msgs[i].id = serverId;
                        updated = true;
                        break;
                    }
                }
                if (updated) break;
            }
        }
        if (updated && render) {
            this.scheduleRenderMessages();
        }
        return updated;
    }

    applyLocalReaction(found, emoji) {
        if (!found || !found.msg) return;
        const message = found.msg;
        const mine = new Set(this.normalizeMyReactions(message.myReactions));
        const wasMine = mine.has(emoji);
        const map = new Map(this.normalizeReactions(message.reactions).map(item => [item.emoji, item.count]));

        if (wasMine) {
            mine.delete(emoji);
            const nextCount = (map.get(emoji) || 0) - 1;
            if (nextCount > 0) map.set(emoji, nextCount);
            else map.delete(emoji);
        } else {
            mine.add(emoji);
            map.set(emoji, (map.get(emoji) || 0) + 1);
        }

        message.myReactions = Array.from(mine);
        message.reactions = Array.from(map.entries())
            .map(([reactionEmoji, count]) => ({ emoji: reactionEmoji, count }))
            .sort((a, b) => b.count - a.count || a.emoji.localeCompare(b.emoji));

        const shouldRender = found.serverKey
            ? found.serverKey === this.currentServerChatKey()
            : found.peer === this.S.current;
        if (shouldRender) {
            this.scheduleRenderMessages();
        }
    }

    // Toggles a single emoji for the current user on a message — it stacks
    // alongside any other emoji they've already reacted with, rather than
    // replacing them (Discord-style, not a single reaction slot per user).
    async addReaction(messageId, emoji) {
        const id = String(messageId || '').trim();
        const reaction = String(emoji || '').trim();
        if (!id || !reaction) return;

        const found = this.findMessageById(id);
        if (!found) return;

        const hasRealServerId = !!found.msg.id && (!found.msg.clientId || String(found.msg.id) !== String(found.msg.clientId));
        if (!hasRealServerId) {
            this.applyLocalReaction(found, reaction);
            return;
        }

        if (this.nativeSupports('setReaction')) {
            const sent = this.postNativeMessage({
                type: NativeMessageTypes.SET_MESSAGE_REACTION,
                messageId: found.msg.id,
                emoji: reaction,
            });
            if (sent) {
                return;
            }
        }

        try {
            const res = await this.apiFetch(this.apiRoutes.messages.reaction(found.msg.id), {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ emoji: reaction }),
            });

            if (!res.ok) {
                throw new Error(await res.text() || 'Не удалось поставить реакцию');
            }

            const payload = await res.json();
            this.onReactionUpdated(payload);
        } catch (e) {
            this.addLogEntry({ type: 'ERROR', msg: `Реакция не отправлена: ${e.message || e}`, ts: new Date().toLocaleTimeString() });
            this.applyLocalReaction(found, reaction);
        }
    }
});


// --- MODULE: interface/render_shell.js ---
// --- ZaliInterface: Отрисовка списков контактов, хаба и серверов. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    // --- DOM Rendering Methods ---

    renderContacts() {
        const el = document.getElementById('contacts');
        if (!el) return;
        this.updateSidebarModeLabel();
        if (this.S.navMode === 'servers') {
            this.renderServers(el);
            return;
        }
        const q = this.S.searchQ.toLowerCase();
        const list = this.S.contacts
            .filter(contact => contact !== this.myName() && (!q || contact.toLowerCase().includes(q)))
            .map((contact, index) => ({
                name: contact,
                lastMessageAt: this.conversationLastMessageAt(contact),
                index,
            }))
            .sort((a, b) => b.lastMessageAt - a.lastMessageAt || a.name.localeCompare(b.name, 'ru', { sensitivity: 'base' }) || a.index - b.index)
            .map(item => item.name);

        if (list.length === 0) {
            this.commitListHTML(el, 'contacts', `<div style="text-align:center;color:var(--text3);font-size:11px;padding:24px 0">${q ? 'Ничего не найдено' : 'Добавьте первый контакт'}</div>`);
            return;
        }

        const html = list.map(contact => {
            this.initChat(contact);
            const msgs = this.S.chats[contact];
            const last = msgs[msgs.length-1];
            let preview = '<span style="color:var(--text3);font-style:italic;font-size:10px">Начните диалог...</span>';
            if (last) {
                const who = last.sender === this.myName() ? 'Вы: ' : '';
                preview = who + this.esc(this.messageSummary(last));
            }
            const cnt = this.S.unread[contact] || 0;
            const badge = cnt > 0 ? `<div class="badge">${cnt > 99 ? '99+' : cnt}</div>` : '';
            const active = contact === this.S.current ? 'active' : '';
            const muted = this.isPeerMuted(contact);
            // Last-message time for the row's right column (hidden on desktop via
            // CSS, shown on the mobile Telegram-style list). Today → time,
            // otherwise a short date — same helpers the message list uses.
            let timeLabel = '';
            if (last && last.timestamp) {
                const d = new Date(last.timestamp);
                const now = new Date();
                timeLabel = d.toDateString() === now.toDateString()
                    ? this.fmtTime(last.timestamp)
                    : this.fmtDate(last.timestamp);
            }
            return `<div class="contact ${active}" data-name="${this.esc(contact)}">
                <div class="ava" data-profile-open="${this.esc(contact)}" title="${this.esc(`Профиль: ${contact}`)}">${this.renderAvatarHTML(contact, 'avatar-img', contact)}</div>
                <div class="contact-info">
                    <div class="contact-name">${this.esc(contact)}</div>
                    <div class="contact-prev">${preview}</div>
                </div>
                <div class="contact-actions">
                    ${timeLabel ? `<span class="contact-time">${this.esc(timeLabel)}</span>` : ''}
                    ${badge}
                    ${muted ? `<span class="contact-mute-indicator" title="Уведомления отключены" aria-label="Уведомления отключены">${this.uiIcon('bell-off')}</span>` : ''}
                    <button class="contact-remove" type="button" data-remove-contact="${this.esc(contact)}" title="Удалить контакт">×</button>
                </div>
            </div>`;
        }).join('');
        this.commitListHTML(el, 'contacts', html);
    }

    // renderContacts()/renderServers() are called from ~30 places (every incoming
    // message, every async avatar that finishes loading, every nav change), and each
    // call used to reassign innerHTML unconditionally. That rebuilt every row's DOM
    // and re-fired the CSS entry animations (.contact/.server-item `contact-in`,
    // .badge `badge-pop`), which is what made the sidebar visibly twitch and flash
    // avatars while chatting. Writing only on a real content change makes the common
    // case a string compare.
    /**
     * Закрывает то, что накрывает панель чата (профиль, настройки сервера).
     *
     * Модальные слои живут внутри .main и больше не гасят левую навигацию —
     * по контакту или серверу можно щёлкнуть, не закрывая диалог. Без этого
     * переключение происходило бы ЗА окном: чат сменился, а поверх него
     * по-прежнему висит чужой профиль, и человек этого не видит. Поэтому
     * выбор в навигации закрывает модальный слой.
     *
     * Вызывается только из веток навигации в bindContactListEvents(); плитки
     * «создать/присоединиться», которые сами открывают окно, сюда не заходят.
     */
    closeChatPanelModals() {
        if (this.ensureProfileState().open) this.closeProfile();
        const serverOverlay = document.getElementById('serverOverlay');
        if (serverOverlay && !serverOverlay.hidden) this.closeServerOverlay();
    }

    commitListHTML(el, slot, html) {
        if (!el) return false;
        this._listHTMLCache = this._listHTMLCache || new Map();
        const key = `${slot}`;
        const unchanged = this._listHTMLCache.get(key) === html
            && el.dataset.listSlot === key
            // Guard against the container having been emptied/replaced by something
            // else since we cached — never let the cache hide an empty list.
            && (el.childElementCount > 0 || !html);
        if (unchanged) {
            return false;
        }
        el.dataset.listSlot = key;
        el.innerHTML = html;
        this._listHTMLCache.set(key, html);
        return true;
    }

    // Avatars are <img> tags rebuilt from a cached blob/data URL. Reassigning the
    // same markup drops the decoded image and makes the browser decode it again,
    // which is what made avatars blink on every unrelated re-render.
    setHTMLIfChanged(el, html) {
        if (!el) return false;
        const next = String(html == null ? '' : html);
        // WeakMap, not a data-attribute: avatar markup embeds full data: URLs on the
        // native shells, and stashing those in the DOM would double their memory.
        this._htmlSigCache = this._htmlSigCache || new WeakMap();
        // The childElementCount check is load-bearing, not just an empty-list guard:
        // some paths (switchChat, the DM branch of renderServerToolbar) write these
        // same elements with textContent, which leaves no element children and never
        // touches this cache. Without the check, a later HTML write matching the
        // cached signature would be skipped and the plain-text value would stick.
        if (this._htmlSigCache.get(el) === next && (el.childElementCount > 0 || !next)) return false;
        this._htmlSigCache.set(el, next);
        el.innerHTML = next;
        return true;
    }

    componentRegistry() {
        const componentVersion = (track, update, serverCompat, moduleVersion) =>
            `${track}0.1.${update}s${serverCompat}l${moduleVersion}`;
        return [
            {
                name: 'Zali Interface',
                version: componentVersion('b', 1, 1, 1),
                layer: 'Web UI',
                description: 'Основной интерфейс: чаты, хаб, настройки, контакты, серверы и composer.',
                dependencies: ['ZaliBus', 'ZaliStyler', 'NetworkService', 'Rust Core'],
            },
            {
                name: 'Zali Styler',
                version: componentVersion('b', 1, 1, 1),
                layer: 'Web UI',
                description: 'Темы, CSS-переменные, радиусы, сохранение выбранной схемы и динамическая кастомизация.',
                dependencies: ['localStorage', 'Swift UserDefaults bridge'],
            },
            {
                name: 'ZaliBus',
                version: componentVersion('b', 1, 1, 1),
                layer: 'Runtime',
                description: 'Командная шина между веб-модулями, Swift WebView и нативными обработчиками.',
                dependencies: ['bootstrap.js', 'native_types.js'],
            },
            {
                name: 'Messaging Module',
                version: componentVersion('b', 1, 1, 1),
                layer: 'Web UI',
                description: 'Отправка сообщений, вложения, реакции, история, локальная очередь и realtime-обновления.',
                dependencies: ['api_routes.js', 'NetworkService', 'Rust Core', 'WebSocket'],
            },
            {
                name: 'Contacts Module',
                version: componentVersion('b', 1, 1, 1),
                layer: 'Web UI',
                description: 'Список диалогов, поиск пользователей, добавление контактов и аватары.',
                dependencies: ['api_routes.js', 'Avatar API', 'Message Cache'],
            },
            {
                name: 'Servers Module',
                version: componentVersion('b', 1, 1, 1),
                layer: 'Web UI',
                description: 'Серверы, каналы, роли, участники, публичные серверы и настройки сервера.',
                dependencies: ['api_routes.js', 'Server API', 'Roles API'],
            },
            {
                name: 'Voice Module',
                version: componentVersion('b', 1, 1, 1),
                layer: 'Realtime',
                description: 'Голосовые комнаты и прямые звонки через WebRTC-сигналинг.',
                dependencies: ['WebRTC', 'Voice WebSocket', 'TURN config'],
            },
            {
                name: 'Rust Core',
                version: componentVersion('b', 1, 1, 1),
                layer: 'Core',
                description: 'Шифрование, упаковка сообщений, файловые операции и нативная core-логика.',
                dependencies: ['Swift bridge', 'ZaliCrypto', 'FileManager'],
            },
            {
                name: 'NetworkService',
                version: componentVersion('b', 1, 1, 1),
                layer: 'macOS Native',
                description: 'HTTP/WebSocket-клиент macOS, загрузка вложений, realtime и связка с сервером.',
                dependencies: ['URLSession', 'UserDefaults', 'Zali Server API'],
            },
            {
                name: 'Windows Native Shell',
                version: componentVersion('b', 2, 1, 2),
                layer: 'Windows Native',
                description: 'Wry/Tao оболочка Windows, WebView2, AppUserModelID, native bridge и сборка exe.',
                dependencies: ['WebView2', 'windows-sys', 'ZaliBus', 'Rust Core'],
            },
            {
                name: 'Native Notifications',
                version: componentVersion('b', 1, 1, 1),
                layer: 'macOS Native',
                description: 'Права macOS, доставка уведомлений и перепроверка статуса при активации приложения.',
                dependencies: ['UNUserNotificationCenter', 'ZaliMessenger.app bundle'],
            },
            {
                name: 'Zali Server',
                version: componentVersion('b', 1, 1, 1),
                layer: 'Backend',
                description: 'REST API, WebSocket realtime, SQLite-хранилище, авторизация и uploads.',
                dependencies: ['axum 0.7', 'tokio 1.0', 'sqlx 0.7', 'jsonwebtoken 9.0'],
            },
        ];
    }

    renderHubComponents() {
        const box = document.getElementById('hubComponents');
        if (!box) return;
        const components = this.componentRegistry();
        box.innerHTML = `
            <div class="hub-components-head">
                <div>
                    <span class="settings-kicker">Components</span>
                    <h3>Компоненты приложения</h3>
                </div>
                <span>${components.length} модулей</span>
            </div>
            <div class="hub-components-list">
                ${components.map(component => `
                    <article class="hub-component-item">
                        <div class="hub-component-main">
                            <div class="hub-component-top">
                                <strong>${this.esc(component.name)}</strong>
                                <span>${this.esc(component.layer)}</span>
                            </div>
                            <p>${this.esc(component.description)}</p>
                        </div>
                        <div class="hub-component-meta">
                            <span class="hub-component-version">${this.esc(component.version)}</span>
                            <small>${component.dependencies.map(dep => this.esc(dep)).join(' / ')}</small>
                        </div>
                    </article>
                `).join('')}
            </div>
        `;
    }

    renderHub() {
        const grid = document.getElementById('hubGrid');
        if (!grid) return;
        const unreadTotal = Object.values(this.S.unread || {}).reduce((sum, value) => sum + Number(value || 0), 0);
        const contactsCount = Array.isArray(this.S.contacts) ? this.S.contacts.length : 0;
        const serversCount = Array.isArray(this.S.servers) ? this.S.servers.length : 0;
        const onlineLabel = this.S.wsOn ? 'WebSocket активен' : 'WebSocket не подключён';
        const cards = [
            {
                kind: 'news',
                title: 'Главные новости',
                value: 'UI v2',
                body: 'Новая сегментная навигация живёт отдельно от протокола сообщений.',
                action: 'Открыть ЛС',
                segment: 'dm',
            },
            {
                kind: 'notifications',
                title: 'Уведомления',
                value: unreadTotal ? `${unreadTotal}` : '0',
                body: unreadTotal ? 'Есть непрочитанные сообщения.' : 'Новых уведомлений пока нет.',
                action: 'К диалогам',
                segment: 'dm',
            },
            (() => {
                const status = this.S.updateStatus || {};
                if (status.available) {
                    return {
                        kind: 'updates',
                        title: 'Обновления',
                        value: `v${status.version}`,
                        body: status.readyToInstall
                            ? 'Загружено — установите и перезапустите приложение.'
                            : (status.downloading
                                ? `Загрузка… ${Math.round((status.progress || 0) * 100)}%`
                                : 'Доступна новая версия приложения.'),
                        action: status.readyToInstall ? 'Установить и перезапустить' : 'Скачать',
                        actionId: 'update',
                    };
                }
                return {
                    kind: 'updates',
                    title: 'Обновления',
                    value: 'Актуально',
                    body: `${onlineLabel}. Контактов: ${contactsCount}. Серверов: ${serversCount}.`,
                    action: 'Сервера',
                    segment: 'servers',
                };
            })(),
            {
                kind: 'apps',
                title: 'Подприложения',
                value: 'Плитки',
                body: 'Будущий дом для мини-модулей, виджетов и быстрых действий.',
                action: 'Открыть хаб',
                segment: 'hub',
            },
            {
                kind: 'components',
                title: 'Компоненты',
                value: 'Модули',
                body: 'Список частей приложения, их версий, зависимостей и зон ответственности.',
                action: 'Смотреть список',
                actionId: 'components',
            },
            {
                kind: 'settings',
                title: 'Настройки',
                value: 'Control',
                body: 'Профиль, тема, ключи, быстрые аккаунты и журнал событий.',
                action: 'Открыть настройки',
                segment: 'settings',
            },
        ];
        grid.innerHTML = cards.map(card => `
            <button class="hub-card hub-card--${this.esc(card.kind)}" type="button"${card.segment ? ` data-hub-segment="${this.esc(card.segment)}"` : ''}${card.actionId ? ` data-hub-action="${this.esc(card.actionId)}"` : ''}>
                <span class="hub-card-kicker">${this.esc(card.title)}</span>
                <strong>${this.esc(card.value)}</strong>
                <span>${this.esc(card.body)}</span>
                <em>${this.esc(card.action)}</em>
            </button>
        `).join('');
        this.renderHubComponents();
    }

    renderServers(el = null) {
        const target = el || document.getElementById('contacts');
        if (!target) return;
        this.ensureServersState();
        const q = this.S.searchQ.toLowerCase();
        const list = (this.S.servers || [])
            .filter(Boolean)
            .filter(server => {
                const haystack = `${server.name || ''} ${server.description || server.hint || ''}`.toLowerCase();
                return !q || haystack.includes(q);
            });

        const createTile = `
            <button class="server-item server-create" type="button" id="createServerBtn" title="Создать сервер" aria-label="Создать сервер">
                <span class="server-avatar server-create-plus">+</span>
                <div class="server-meta">
                    <div class="server-name">Создать сервер</div>
                    <div class="server-prev">Новый сервер, команда или сообщество</div>
                </div>
            </button>
        `;
        const joinTile = `
            <button class="server-item server-join" type="button" id="joinServerBtn" title="Войти по коду" aria-label="Войти по коду">
                <span class="server-avatar server-create-plus">↗</span>
                <div class="server-meta">
                    <div class="server-name">Войти по коду</div>
                    <div class="server-prev">Введите код или ссылку сервера</div>
                </div>
            </button>
        `;
        const publicTile = `
            <button class="server-item server-public" type="button" id="publicServersBtn" title="Открыть публичные серверы" aria-label="Открыть публичные серверы">
                <span class="server-avatar server-create-plus">☰</span>
                <div class="server-meta">
                    <div class="server-name">Публичные серверы</div>
                    <div class="server-prev">Просмотр и вход из меню</div>
                </div>
            </button>
        `;

        const html = `
            <div class="server-list">
                ${list.length === 0 ? `<div class="server-empty">
                    <div class="empty-ttl">Сервера не найдены</div>
                    <div class="empty-sub">Попробуйте другой запрос</div>
                </div>` : list.map(server => {
                    const active = server.id === this.S.activeServer ? 'active' : '';
                    // server.unread is never populated by the backend — the real
                    // per-channel counts live in S.channelUnread, so sum those up
                    // for the aggregate badge instead of reading a field that's
                    // always undefined.
                    const serverUnreadCount = (server.channels || []).reduce(
                        (sum, ch) => sum + Number(this.S.channelUnread?.[`${server.id}:${ch.id}`] || 0),
                        0
                    );
                    const badge = serverUnreadCount > 0
                        ? `<div class="badge server-badge">${serverUnreadCount > 99 ? '99+' : serverUnreadCount}</div>`
                        : '';
                    const preview = server.description || server.hint || 'Сервер';
                    return `
                        <button class="server-item ${active}" type="button" data-server-id="${this.esc(server.id)}" title="${this.esc(server.name)}" aria-label="${this.esc(server.name)}">
                            ${this.renderServerAvatarHTML(server)}
                            <div class="server-meta">
                                <div class="server-name">${this.esc(server.name)}</div>
                                <div class="server-prev">${this.esc(preview)}</div>
                            </div>
                            ${badge}
                        </button>
                    `;
                }).join('')}
                ${createTile}
                ${joinTile}
                ${publicTile}
            </div>
        `;
        this.commitListHTML(target, 'servers', html);
    }

    updateServerSelection() {
        const rows = document.querySelectorAll('.server-item[data-server-id]');
        rows.forEach(row => {
            const serverId = row.getAttribute('data-server-id');
            row.classList.toggle('active', serverId === this.S.activeServer);
        });
    }

    setActiveServer(serverId, { persist = true } = {}) {
        const next = String(serverId || '').trim();
        if (!next) return;
        this.ensureServersState();
        if (!this.S.servers.some(server => server.id === next)) return;
        const previousVoiceServer = String(this.voice.serverId || '').trim();
        const previousVoiceChannel = String(this.voice.channelId || '').trim();
        const current = this.currentServer();
        const currentChannel = this.currentChannel();
        if (this.S.navMode === 'servers' && this.S.activeServer === next && current && currentChannel) {
            // Same reasoning as setActiveChannel's identical guard: state is
            // already correct, but the click may be asking to return to the chat
            // screen from Hub/ZaliCoin/Settings — see ensureChatViewOpen().
            this.ensureChatViewOpen();
            return;
        }
        // The server list in the sidebar stays clickable outside the chat screen
        // too (see switchChat's identical call for the DM list).
        this.ensureChatViewOpen();
        this.collapseActiveCallView();
        this.S.activeServer = next;
        this.S.activeConversationType = 'servers';
        this.S.navMode = 'servers';
        const server = this.currentServer();
        if (server) {
            const storedChannel = this.loadStoredActiveChannel();
            const fallbackChannel = (server.channels || [])[0]?.id || null;
            this.S.activeChannel = storedChannel && (server.channels || []).some(ch => ch.id === storedChannel)
                ? storedChannel
                : fallbackChannel;
        }
        if (persist) {
            this.saveStoredNavMode('servers');
            this.saveStoredActiveServer(next);
            this.saveStoredActiveChannel(this.S.activeChannel);
        }
        if (this.voice.roomType === 'channel' && previousVoiceServer && previousVoiceChannel) {
            const nextVoiceChannel = String(this.S.activeChannel || '').trim();
            if (previousVoiceServer !== next || previousVoiceChannel !== nextVoiceChannel) {
                this.leaveVoiceRoom({ announce: true });
            }
        }
        this.updateNavModeButtons();
        this.renderServerToolbar();
        this.requestMessagesScroll('bottom');
        this.resetMessageWindow();
        this.scheduleRenderMessages();
        this.updateSendButtonState();
        this.updateServerSelection();
        if (this.S.activeServer && this.S.activeChannel) {
            this.requestMessagesScroll('bottom');
            this.loadServerMessages(this.S.activeServer, this.S.activeChannel, { silent: true });
        }
        this.closeMobileSidebar();
        this.syncMobileChrome();
    }
});


// --- MODULE: interface/updates.js ---
// --- ZaliInterface: Встроенный апдейтер клиента. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    // --- App updates (macOS/Windows native shells only — see nativeSupports('appUpdate')) ---

    updateDeclinedStorageKey() {
        return 'zali_update_declined_version';
    }

    updateInstallAttemptsStorageKey() {
        return 'zali_update_install_attempts_v1';
    }

    // An install that silently doesn't take (Windows: the new .exe cannot be copied
    // over an installation in Program Files without elevation — the old binary is
    // restarted and the reason goes to updates/install.log) leaves the client on the
    // previous version, so the very next login finds the same "newer" release and
    // opens the same modal again. That is an unbreakable loop from the user's side:
    // accepting is what triggers it. Counting attempts per version turns the second
    // failure into a visible error instead of a third prompt.
    loadUpdateInstallAttempts() {
        try {
            const parsed = JSON.parse(localStorage.getItem(this.updateInstallAttemptsStorageKey()) || '{}');
            return {
                version: String(parsed?.version || ''),
                count: Number(parsed?.count) || 0,
            };
        } catch (e) {
            return { version: '', count: 0 };
        }
    }

    recordUpdateInstallAttempt(version) {
        const target = String(version || '').trim();
        if (!target) return;
        const previous = this.loadUpdateInstallAttempts();
        const next = {
            version: target,
            count: previous.version === target ? previous.count + 1 : 1,
        };
        try {
            localStorage.setItem(this.updateInstallAttemptsStorageKey(), JSON.stringify(next));
        } catch (e) {}
    }

    clearUpdateInstallAttempts() {
        try { localStorage.removeItem(this.updateInstallAttemptsStorageKey()); } catch (e) {}
    }

    // App version scheme: MAJOR.MINOR{a|b|r}BUILD, e.g. "0.2b9" (r=release >
    // b=beta > a=alpha at the same MAJOR.MINOR). Falls back to plain dotted
    // numeric versions (e.g. legacy "1.1.3") for compatibility with whatever the
    // server already has published in app_releases — those are treated as the
    // top ("release") channel so they compare purely by major.minor.patch.
    parseAppVersion(v) {
        const str = String(v || '').trim();
        const channeled = str.match(/^(\d+)\.(\d+)([abr])(\d+)$/i);
        if (channeled) {
            const channelRank = { a: 0, b: 1, r: 2 };
            return {
                major: parseInt(channeled[1], 10) || 0,
                minor: parseInt(channeled[2], 10) || 0,
                channel: channelRank[channeled[3].toLowerCase()],
                build: parseInt(channeled[4], 10) || 0,
            };
        }
        const parts = str.split('.').map(n => parseInt(n, 10) || 0);
        return {
            major: parts[0] || 0,
            minor: parts[1] || 0,
            channel: 2,
            build: parts[2] || 0,
        };
    }

    compareVersions(a, b) {
        const va = this.parseAppVersion(a);
        const vb = this.parseAppVersion(b);
        if (va.major !== vb.major) return va.major > vb.major ? 1 : -1;
        if (va.minor !== vb.minor) return va.minor > vb.minor ? 1 : -1;
        if (va.channel !== vb.channel) return va.channel > vb.channel ? 1 : -1;
        if (va.build !== vb.build) return va.build > vb.build ? 1 : -1;
        return 0;
    }

    isNewSchemeVersion(v) {
        return /^\d+\.\d+[abr]\d+$/i.test(String(v || '').trim());
    }

    // Unix-seconds cutoff for the one-time version-scheme migration: the
    // "1.1.4" release (first published 2026-07-27) exists only so pre-migration
    // clients (running the OLD compareVersions, which just splits on "." and
    // compares numbers) see a numeric bump and update — its actual bundled code
    // is build 0.2b9. Once a client is running that new code (and so already
    // understands MAJOR.MINOR{a|b|r}BUILD), a plain-numeric "latest" published
    // at or before this cutoff is that same legacy compatibility bump, not a
    // real newer release — comparing it via major-number alone (1 > 0) would
    // otherwise look newer than 0.2b9 forever and loop the update prompt.
    // Deliberately set days out (not pinned to that release's exact
    // publishedAt) — republishing "1.1.4" to fix e.g. its sha256 bumps
    // publishedAt each time, which would slip past an exact-timestamp cutoff.
    // Real post-migration releases (version matching the new scheme, or
    // published well after this date) are compared normally regardless.
    static VERSION_SCHEME_MIGRATION_CUTOFF_UNIX = 1785542400; // 2026-08-01T00:00:00Z

    async checkForAppUpdate() {
        if (!this.hasNativeBridge() || !this.nativeSupports('appUpdate')) return;
        const platform = String(window.__ZALI_NATIVE_PLATFORM || '').trim();
        const currentVersion = String(window.__ZALI_NATIVE_APP_VERSION || '').trim();
        if (!platform || !currentVersion) return;
        try {
            const res = await this.apiFetch(`/api/version?platform=${encodeURIComponent(platform)}`);
            if (!res.ok) return;
            const data = await res.json();
            const latestVersion = String(data?.version || '').trim();
            const publishedAt = Number(data?.publishedAt) || 0;
            const isLegacyMigrationBump = latestVersion
                && !this.isNewSchemeVersion(latestVersion)
                && publishedAt > 0
                && publishedAt <= ZaliInterface.VERSION_SCHEME_MIGRATION_CUTOFF_UNIX;
            if (isLegacyMigrationBump && this.isNewSchemeVersion(currentVersion)) {
                return;
            }
            if (!latestVersion || this.compareVersions(latestVersion, currentVersion) <= 0) {
                // We are running it — any earlier failed-install bookkeeping is stale.
                this.clearUpdateInstallAttempts();
                return;
            }
            // Reaching here after having already installed this exact version means the
            // install did not take. Keep the update reachable from the Hub, but stop
            // reopening the modal on every login.
            const attempts = this.loadUpdateInstallAttempts();
            const installKeepsFailing = attempts.version === latestVersion && attempts.count >= 2;
            this.S.updateStatus = {
                available: true,
                version: latestVersion,
                notes: String(data?.notes || ''),
                downloadUrl: String(data?.downloadUrl || ''),
                sha256: String(data?.sha256 || ''),
                mandatory: !!data?.mandatory,
                downloading: false,
                progress: 0,
                readyToInstall: false,
                error: installKeepsFailing
                    ? `Обновление ${latestVersion} уже устанавливалось, но версия не сменилась. Установите его вручную (на Windows — запустите приложение от имени администратора либо скачайте .exe по ссылке ниже).`
                    : '',
            };
            this.renderHub();
            const declined = (() => {
                try { return localStorage.getItem(this.updateDeclinedStorageKey()); } catch (e) { return null; }
            })();
            if (installKeepsFailing) {
                this.trace(`checkForAppUpdate install keeps failing version=${latestVersion} attempts=${attempts.count}`);
                return;
            }
            if (this.S.updateStatus.mandatory || declined !== latestVersion) {
                this.openUpdateModal();
            }
        } catch (e) {
            this.trace(`checkForAppUpdate failed err=${e?.message || e}`);
        }
    }

    openUpdateModal() {
        const modal = document.getElementById('updateAvailableModal');
        if (!modal || !this.S.updateStatus?.available) return;
        this.renderUpdateModal();
        modal.hidden = false;
    }

    closeUpdateModal() {
        const modal = document.getElementById('updateAvailableModal');
        if (modal) modal.hidden = true;
    }

    declineAppUpdate() {
        if (this.S.updateStatus?.mandatory) return;
        const version = String(this.S.updateStatus?.version || '').trim();
        if (version) {
            try { localStorage.setItem(this.updateDeclinedStorageKey(), version); } catch (e) {}
        }
        this.closeUpdateModal();
    }

    renderUpdateModal() {
        const modal = document.getElementById('updateAvailableModal');
        if (!modal) return;
        const status = this.S.updateStatus || {};
        const titleEl = modal.querySelector('#updateModalVersion');
        const notesEl = modal.querySelector('#updateModalNotes');
        const progressWrap = modal.querySelector('#updateModalProgressWrap');
        const progressBar = modal.querySelector('#updateModalProgressBar');
        const errorEl = modal.querySelector('#updateModalError');
        const acceptBtn = modal.querySelector('#updateModalAcceptBtn');
        const declineBtn = modal.querySelector('#updateModalDeclineBtn');
        if (titleEl) titleEl.textContent = `Доступно обновление v${status.version || ''}`;
        if (notesEl) notesEl.textContent = status.notes || 'Новая версия готова к загрузке.';
        if (errorEl) {
            errorEl.hidden = !status.error;
            errorEl.textContent = status.error || '';
        }
        if (declineBtn) declineBtn.hidden = !!status.downloading || !!status.readyToInstall || !!status.mandatory;
        if (progressWrap) progressWrap.hidden = !status.downloading;
        if (progressBar) progressBar.style.width = `${Math.round((status.progress || 0) * 100)}%`;
        if (acceptBtn) {
            if (status.readyToInstall) {
                acceptBtn.textContent = 'Перезапустить и установить';
                acceptBtn.disabled = false;
            } else if (status.downloading) {
                acceptBtn.textContent = `Загрузка… ${Math.round((status.progress || 0) * 100)}%`;
                acceptBtn.disabled = true;
            } else {
                acceptBtn.textContent = 'Обновить';
                acceptBtn.disabled = false;
            }
        }
    }

    async acceptAppUpdate() {
        const status = this.S.updateStatus || {};
        if (!status.available) return;
        if (status.readyToInstall) {
            this.recordUpdateInstallAttempt(status.version);
            this.requestNativeAction({ type: NativeMessageTypes.INSTALL_UPDATE_REQUEST }, 5000).catch(() => {});
            return;
        }
        if (status.downloading || !status.downloadUrl) return;
        this.S.updateStatus = { ...status, downloading: true, progress: 0, error: '' };
        this.renderUpdateModal();
        this.renderHub();
        try {
            await this.requestNativeAction({
                type: NativeMessageTypes.DOWNLOAD_UPDATE_REQUEST,
                url: status.downloadUrl,
                sha256: status.sha256,
            }, 10 * 60 * 1000);
            this.S.updateStatus = { ...this.S.updateStatus, downloading: false, progress: 1, readyToInstall: true };
        } catch (e) {
            this.S.updateStatus = { ...this.S.updateStatus, downloading: false, error: String(e?.message || e) };
        }
        this.renderUpdateModal();
        this.renderHub();
    }

    handleUpdateEvent(payload) {
        if (String(payload?.kind || '') !== 'progress') return;
        const status = this.S.updateStatus || {};
        if (!status.downloading) return;
        this.S.updateStatus = { ...status, progress: Number(payload?.progress || 0) };
        this.renderUpdateModal();
    }

    handleHubUpdateAction() {
        const status = this.S.updateStatus || {};
        if (!status.available) return;
        this.openUpdateModal();
    }
});


// --- MODULE: interface/message_list.js ---
// --- ZaliInterface: Окно сообщений, рендер списка, переключение чата. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    getCurrentMessages() {
        if (this.S.navMode === 'servers') {
            const key = this.currentServerChatKey();
            return this.S.serverChats[key] || [];
        }
        return this.S.chats[this.S.current] || [];
    }

    // Fast negative answer to "is this peer present in the persisted cache?".
    //
    // ensureConversationLoaded runs inside the message-render frame, and its
    // loadStoredMessageCache() call JSON.parses the ENTIRE persisted store — every
    // conversation, not just this one — rebuilding the whole object graph. For an
    // account with real history that is a main-thread stall on every render of an
    // empty chat, and it almost always ends in "peer not found" anyway: the chat is
    // usually empty because it genuinely has no cached history.
    //
    // The raw text is scanned for the peer's own quoted JSON key first. A miss there
    // is conclusive (the key would have to appear verbatim if it were stored), and
    // a raw string scan is cheaper than a parse by orders of magnitude. A hit falls
    // through to the real parse, so nothing that used to be found stops being found.
    // Misses are additionally memoised against the exact raw string, so repeated
    // renders of the same empty chat cost nothing at all until the cache is rewritten.
    persistedCacheMightHavePeer(raw, peer) {
        if (!raw) return false;
        if (this._msgCacheMissRaw !== raw) {
            this._msgCacheMissRaw = raw;
            this._msgCacheMissPeers = new Set();
        }
        if (this._msgCacheMissPeers.has(peer)) return false;
        if (raw.indexOf(JSON.stringify(peer)) !== -1) return true;
        this._msgCacheMissPeers.add(peer);
        return false;
    }

    ensureConversationLoaded(peer = null) {
        const currentPeer = String(peer || this.S.current || '').trim();
        if (!currentPeer) return false;
        const currentMsgs = this.S.chats[currentPeer];
        if (Array.isArray(currentMsgs) && currentMsgs.length > 0) {
            return true;
        }

        let rawCache = null;
        try {
            rawCache = localStorage.getItem(this.messageCacheStorageKey());
        } catch (e) {
            rawCache = null;
        }
        // No persisted store at all still has to go through the loader below, which
        // falls back to the native-injected cache (window.__ZALI_MESSAGE_CACHE).
        if (rawCache && !this.persistedCacheMightHavePeer(rawCache, currentPeer)) {
            return false;
        }

        const cache = this.loadStoredMessageCache();
        const cachedMsgs = Array.isArray(cache?.chats?.[currentPeer]) ? cache.chats[currentPeer] : [];
        if (cachedMsgs.length === 0) return false;

        this.S.chats[currentPeer] = cachedMsgs.filter(msg => msg && typeof msg === 'object');
        this.trace(`ensureConversationLoaded peer=${currentPeer} restored=${this.S.chats[currentPeer].length}`);
        return true;
    }

    scheduleRenderMessages() {
        if (this.messageRenderRaf) return;
        this.messageRenderRaf = requestAnimationFrame(() => {
            this.messageRenderRaf = 0;
            this._renderMessagesNow();
        });
    }

    renderMessages() {
        this.scheduleRenderMessages();
    }

    _renderMessagesNow() {
        const box = document.getElementById('msgs');
        if (!box) return;
        this.hideReactionMenu();
        const isServers = this.S.navMode === 'servers';
        const conversationKey = isServers ? this.currentServerChatKey() : String(this.S.current || '').trim();
        const previousConversationKey = this.lastRenderedConversationKey || '';
        const conversationChanged = previousConversationKey !== conversationKey;
        const previousScrollTop = box.scrollTop;
        const previousScrollHeight = box.scrollHeight;
        const stickToBottom = this.isMessagesNearBottom(box);
        // Capturing the anchor walks message nodes reading getBoundingClientRect() —
        // a forced layout per node. It is only ever consumed by the `preserveScroll`
        // branch below, so skip the work outright in the cases that branch can't run
        // (conversation switch, queued scroll, or we're pinned to the bottom).
        const scrollAnchor = (conversationChanged || this.pendingMessagesScroll || stickToBottom)
            ? null
            : this.captureMessageScrollAnchor(box);
        const msgs = this.getCurrentMessages();
        const channel = this.currentChannel();
        const server = this.currentServer();

        if (!isServers && (!Array.isArray(msgs) || msgs.length === 0) && !this.S.loading) {
            const restored = this.ensureConversationLoaded(this.S.current);
            if (restored) {
                this.trace(`renderMessages rerender restored peer=${String(this.S.current || '').trim()}`);
                this.scheduleRenderMessages();
                return;
            }
        }

        if (isServers && channel && this.isVoiceChannel(channel)) {
            this._lastMessagesHTML = null;
            // The call UI lives in #voicePanel (renderVoicePanel(), called below) —
            // this used to ALSO render the identical renderVoiceRoomView() into the
            // message box, so a voice channel showed two full copies of the same
            // call card stacked on top of each other, together consuming the whole
            // screen and then some. Voice channels have no text chat of their own
            // (sendInputMessage() no-ops for them), so this box just says that
            // instead of duplicating the call view.
            box.innerHTML = '<div class="voice-empty voice-channel-no-chat">Голосовые каналы не поддерживают текстовые сообщения</div>';
            if (isServers && server) {
                const chatHdrAva = document.getElementById('chatHdrAva');
                const chatHdrName = document.getElementById('chatHdrName');
                const chatHdrSub = document.getElementById('chatHdrSub');
                if (chatHdrAva) {
                    chatHdrAva.style.background = this.serverAvatarBackground(server);
                    this.setHTMLIfChanged(chatHdrAva, this.serverAvatarInnerHTML(server));
                }
                if (chatHdrName) this.setHTMLIfChanged(chatHdrName, `<span class="chat-hdr-title">${this.channelKindIcon('voice', 'chat-hdr-channel-icon')}<span>${this.esc(channel.name)}</span></span><span class="chat-hdr-count">${this.esc(`Голосовой канал`)}</span>`);
                if (chatHdrSub) chatHdrSub.textContent = `${server.name}${channel.topic ? ` · ${channel.topic}` : ''}`;
                this.updateChatHeaderCryptoKey({
                    serverId: server.id,
                    channelId: channel?.id || null,
                });
            }
            this.renderVoicePanel();
            return;
        }

        if (msgs.length === 0 && !this.S.loading) {
            this._lastMessagesHTML = null;
            this.lastRenderedConversationKey = conversationKey;
            if (isServers) {
                box.innerHTML = `<div class="empty-state">
                    <div class="empty-ttl">Нет сообщений в канале</div>
                    <div class="empty-sub">${channel ? `#${this.esc(channel.name)}` : 'Выберите канал'}</div>
                </div>`;
                return;
            }
            box.innerHTML = `<div class="empty-state">
                <div class="empty-ttl">Нет сообщений</div>
                <div class="empty-sub">Начните разговор</div>
            </div>`;
            return;
        }

        const windowInfo = this.computeMessageWindow(msgs, box, {
            conversationChanged,
            stickToBottom,
        });
        const renderedMsgs = windowInfo.useWindow ? msgs.slice(windowInfo.start, windowInfo.end) : msgs;
        let html = '';
        if (windowInfo.useWindow && windowInfo.topSpacer > 0) {
            html += `<div class="msg-window-spacer" aria-hidden="true" style="height:${Math.round(windowInfo.topSpacer)}px"></div>`;
        }
        const GROUP_WINDOW_MS = 5 * 60 * 1000;
        const items = renderedMsgs.map(msg => {
            const ts = msg.timestamp ? new Date(msg.timestamp).getTime() : 0;
            const dayKey = ts ? new Date(ts).toDateString() : '';
            return { msg, ts, dayKey, groupPos: 'single' };
        });

        let activeGroup = null;
        items.forEach((item) => {
            const isGroupable = item.msg?.kind !== 'call' && !this.detectSystemNotice(item.msg?.text) && !!item.ts && !!item.dayKey && !!String(item.msg?.sender || '').trim();
            const sameSender = !!(activeGroup && activeGroup.sender === item.msg.sender);
            const sameDay = !!(activeGroup && activeGroup.dayKey === item.dayKey);
            const withinWindow = !!(activeGroup && item.ts && activeGroup.lastTs && (item.ts - activeGroup.lastTs) <= GROUP_WINDOW_MS);

            if (isGroupable && sameSender && sameDay && withinWindow) {
                item.groupPos = 'end';
                if (activeGroup.items.length === 1) {
                    activeGroup.items[0].groupPos = 'start';
                } else if (activeGroup.items.length > 1) {
                    activeGroup.items[activeGroup.items.length - 1].groupPos = 'mid';
                }
                activeGroup.items.push(item);
                activeGroup.lastTs = item.ts;
                return;
            }

            item.groupPos = 'single';
            if (isGroupable) {
                activeGroup = {
                    sender: String(item.msg.sender || '').trim(),
                    dayKey: item.dayKey,
                    lastTs: item.ts,
                    items: [item],
                };
            } else {
                activeGroup = null;
            }
        });

        let lastDate = null;
        items.forEach(item => {
            const msg = item.msg;
            const isOut = this.isOutgoingMessage(msg);
            const isCall = msg.kind === 'call';
            const noticeType = !isCall ? this.detectSystemNotice(msg.text) : null;
            const isNotice = !!noticeType;
            const isImageCaption = !isCall && !isNotice && this.messageIsImageCaption(msg);
            const dateStr = this.fmtDate(msg.timestamp);
            const mediaCard = !isCall && this.messageHasMedia(msg) ? 'media-card' : '';
            const gifOnly = !isCall && this.messageIsGifOnly(msg);
            const isSending = isOut && msg.status === 'sending';
            const messageId = String(msg.id || '').trim();
            const hoverTimeLabel = !isCall ? this.messageHoverTimeLabel(msg) : '';
            const showInlineTime = !isCall && (item.groupPos === 'single' || item.groupPos === 'end');
            const inlineTimeLabel = !isCall ? this.messageInlineTimeLabel(msg) : '';
            const dir = isCall ? (isOut ? 'out' : 'in') : (isOut ? 'out' : 'in');
            const showAvatar = !isCall && !isOut && (item.groupPos === 'single' || item.groupPos === 'end');
            if (dateStr && dateStr !== lastDate) {
                html += `<div class="date-sep"><span>${this.esc(dateStr)}</span></div>`;
                lastDate = dateStr;
            }

            // System notices (a ZaliCoin transfer receipt, a decryption/download
            // placeholder) are generated by the app itself, not typed by either
            // party — render them as a centered pill instead of a left/right chat
            // bubble so they read as distinct from a human-written message with the
            // same wording. See detectSystemNotice() for the caveat on what this
            // does and doesn't guarantee.
            if (isNotice) {
                if (noticeType === 'decrypt-error') {
                    // Queued, not awaited-and-fired here: see
                    // queueDecryptFailureReport() for why this must not happen
                    // inside the render frame.
                    this.queueDecryptFailureReport({
                        placeholderText: msg.text,
                        messageId: msg.id,
                        clientId: msg.clientId,
                        sender: msg.sender,
                        receiver: msg.receiver,
                        serverId: msg.serverId,
                        channelId: msg.channelId,
                        messageTimestamp: msg.timestamp,
                    });
                }
                html += `<div class="msg notice notice-${noticeType}"${messageId ? ` data-message-id="${this.esc(messageId)}"` : ''}>
                    <div class="notice-pill"${hoverTimeLabel ? ` title="${this.esc(hoverTimeLabel)}"` : ''}>
                        <span class="notice-icon" aria-hidden="true">${noticeType === 'transfer' ? '💸' : '🔐'}</span>
                        <span class="notice-text">${this.renderMessageText(msg.text)}</span>
                    </div>
                </div>`;
                return;
            }

            // A photo (or gif/sticker) with a caption: the image stands on its own,
            // chrome-less and square-bottomed, and the caption sits below it in a
            // separate bubble sized to match — a small gap between the two instead
            // of both crammed into one padded card (the old `bubble media-card`
            // layout, still used below for mixed/file attachments).
            if (isImageCaption) {
                const attachments = this.normalizeAttachments(msg.attachments);
                const mediaHtml = attachments.map(att => this.renderAttachmentPreview(att)).join('');
                html += `<div class="msg ${dir} image-caption group-${item.groupPos} ${isSending ? 'sending' : ''} ${showInlineTime ? 'time-visible' : 'time-hidden'}"${messageId ? ` data-message-id="${this.esc(messageId)}"` : ''}>`;
                if (!isOut && showAvatar) {
                    html += `<div class="msg-ava" data-profile-open="${this.esc(msg.sender)}" title="${this.esc(`Профиль: ${msg.sender}`)}">${this.renderAvatarHTML(msg.sender, 'avatar-img', msg.sender)}</div>`;
                } else if (!isOut) {
                    html += `<div class="msg-ava msg-ava-spacer" aria-hidden="true"></div>`;
                }
                html += `<div class="bwrap image-caption-wrap">
                    <div class="image-caption-media">${mediaHtml}</div>
                    <div class="bubble image-caption-text msg-time-anchor"${hoverTimeLabel ? ` title="${this.esc(hoverTimeLabel)}"` : ''}>${this.renderMessageText(msg.text)}${inlineTimeLabel ? `<span class="msg-time" aria-hidden="true">${this.esc(inlineTimeLabel)}</span>` : ''}</div>
                    ${this.renderMessageReactions(msg)}
                </div></div>`;
                return;
            }

            const bubbleClass = isCall ? '' : (gifOnly ? 'media-only msg-time-anchor' : `bubble ${mediaCard} msg-time-anchor`);

            html += `<div class="msg ${dir} ${isCall ? 'call-msg' : `group-${item.groupPos}`} ${isSending ? 'sending' : ''} ${gifOnly ? 'gif-only' : ''} ${showInlineTime ? 'time-visible' : 'time-hidden'}"${messageId ? ` data-message-id="${this.esc(messageId)}"` : ''}>`;
            if (!isCall && !isOut && showAvatar) {
                html += `<div class="msg-ava" data-profile-open="${this.esc(msg.sender)}" title="${this.esc(`Профиль: ${msg.sender}`)}">${this.renderAvatarHTML(msg.sender, 'avatar-img', msg.sender)}</div>`;
            } else if (!isCall && !isOut) {
                html += `<div class="msg-ava msg-ava-spacer" aria-hidden="true"></div>`;
            }
            html += `<div class="bwrap ${isCall ? 'call-wrap' : ''}">
                ${isCall ? this.renderMessageBody(msg) : `<div class="${bubbleClass}"${hoverTimeLabel ? ` title="${this.esc(hoverTimeLabel)}"` : ''}>${this.renderMessageBody(msg)}${inlineTimeLabel ? `<span class="msg-time" aria-hidden="true">${this.esc(inlineTimeLabel)}</span>` : ''}</div>`}
                ${!isCall ? this.renderMessageReactions(msg) : ''}
            </div></div>`;
        });

        if (this.S.loading) {
            html += `<div class="sk sk-bubble sk-w2"></div>
                     <div class="sk sk-bubble sk-w3 sk-self"></div>
                     <div class="sk sk-bubble sk-w1"></div>
                     <div class="sk sk-bubble sk-w2 sk-self"></div>`;
        }

        if (windowInfo.useWindow && windowInfo.bottomSpacer > 0) {
            html += `<div class="msg-window-spacer" aria-hidden="true" style="height:${Math.round(windowInfo.bottomSpacer)}px"></div>`;
        }

        // Redundant re-renders are common (an avatar finishing its fetch, an unrelated
        // state sync). Reassigning identical innerHTML would still destroy and rebuild
        // every bubble, restart the media hydration and re-run the height probe — and
        // on WebKit it also resets scrollTop mid-scroll. Compare first.
        const htmlChanged = this._lastMessagesHTML !== html || conversationChanged || box.childElementCount === 0;
        if (htmlChanged) {
            box.innerHTML = html;
            this._lastMessagesHTML = html;
            this.hydrateGifMedia(box);

            // Sampling the whole list meant one forced layout per message node on
            // every render. A dozen evenly spread samples give the same running
            // average for the virtual-window estimate at a fraction of the cost.
            const msgNodes = box.querySelectorAll('.msg');
            if (msgNodes.length) {
                const SAMPLES = 12;
                const step = Math.max(1, Math.floor(msgNodes.length / SAMPLES));
                let total = 0;
                let counted = 0;
                for (let i = 0; i < msgNodes.length && counted < SAMPLES; i += step) {
                    const height = Number(msgNodes[i].offsetHeight || 0);
                    if (height > 0) {
                        total += height;
                        counted += 1;
                    }
                }
                if (counted > 0) {
                    const avgHeight = total / counted;
                    const current = Number(this.messageWindow?.avgHeight || 92);
                    this.messageWindow.avgHeight = Math.max(56, Math.min(160, current * 0.7 + avgHeight * 0.3));
                }
            }
        }
        this.messageWindow.conversationKey = conversationKey;
        this.messageWindow.start = windowInfo.useWindow ? windowInfo.start : 0;
        this.messageWindow.end = windowInfo.useWindow ? windowInfo.end : msgs.length;
        this.messageWindow.count = msgs.length;
        this.messageWindow.useWindow = !!windowInfo.useWindow;

        const preserveScroll = !conversationChanged && !this.pendingMessagesScroll && !stickToBottom;
        if (preserveScroll && previousScrollHeight > 0 && htmlChanged) {
            // Holding a position in history is the opposite of following the bottom.
            this._bottomIntent = false;
            this.markProgrammaticScroll();
            const restored = this.restoreMessageScrollAnchor(box, scrollAnchor);
            if (!restored) {
                const scrollDelta = box.scrollHeight - previousScrollHeight;
                const nextScrollTop = Math.max(0, previousScrollTop + scrollDelta);
                box.scrollTop = nextScrollTop;
            }
        }

        if (this.pendingMessagesScroll === 'top') {
            this.applyPendingMessagesScroll(box);
        } else if (this.pendingMessagesScroll === 'bottom') {
            const shouldAutoScroll = conversationChanged || stickToBottom || previousScrollHeight <= box.clientHeight;
            if (shouldAutoScroll) {
                this.applyPendingMessagesScroll(box);
            } else {
                this.pendingMessagesScroll = null;
            }
        } else if (!conversationChanged && stickToBottom && htmlChanged) {
            this.markProgrammaticScroll();
            box.scrollTop = box.scrollHeight;
            this.pinToBottomAfterLayout(box);
        } else if (conversationChanged) {
            // A conversation switch with no queued scroll used to leave the old
            // chat's scrollTop in place over freshly written content — the classic
            // "opened a chat somewhere in the middle of last week" jump. Opening at
            // the newest message is the only correct default here.
            this.markProgrammaticScroll();
            box.scrollTop = box.scrollHeight;
            this.pinToBottomAfterLayout(box);
        }

        if (isServers && server) {
            const chatHdrAva = document.getElementById('chatHdrAva');
            const chatHdrName = document.getElementById('chatHdrName');
            const chatHdrSub = document.getElementById('chatHdrSub');
            if (chatHdrAva) {
                chatHdrAva.style.background = this.serverAvatarBackground(server);
                this.setHTMLIfChanged(chatHdrAva, this.serverAvatarInnerHTML(server));
            }
            if (chatHdrName) {
                const membersText = Number(server.memberCount || 0) > 0 ? `${Number(server.memberCount)} ${this.ruPlural(server.memberCount, 'участник', 'участника', 'участников')}` : '';
                const channelTitle = channel
                    ? `${this.channelKindIcon(channel.kind, 'chat-hdr-channel-icon')}<span>${this.esc(channel.name)}</span>`
                    : this.esc(server.name);
                this.setHTMLIfChanged(chatHdrName, `
                    <span class="chat-hdr-title">${channelTitle}</span>
                    ${membersText ? `<span class="chat-hdr-count">${this.esc(membersText)}</span>` : ''}
                `);
            }
            if (chatHdrSub) {
                chatHdrSub.textContent = channel
                    ? `${server.name}${channel.topic ? ` · ${channel.topic}` : ''}`
                    : (server.description || 'Сервер');
            }
        }
        this.lastRenderedConversationKey = conversationKey;
    }

    switchChat(name) {
        const peer = String(name || '').trim();
        if (!peer) return;
        this.trace(`switchChat peer=${peer}`);
        // A contact row in the sidebar is clickable from Hub/ZaliCoin/Settings too
        // (the sidebar never hides) — bring the chat screen back if one of those
        // was open, otherwise picking a conversation from there looked like a
        // no-op.
        this.ensureChatViewOpen();
        this.collapseActiveCallView();
        this.clearActiveServerSelection();
        // A reply quote and an edit both point at a message in the conversation
        // being left; carrying them over would send the reply into the wrong chat
        // (or, worse, apply the edit to a message the composer no longer shows).
        this.cancelComposerContext();
        this.S.current = peer;
        // NB: lastRenderedConversationKey must NOT be pre-set to the new peer here.
        // _renderMessagesNow() derives `conversationChanged` from it, and that flag
        // drives (a) the virtual-window reset, (b) whether the pending
        // "scroll to bottom" is honoured and (c) whether the *previous* chat's
        // scroll anchor gets restored. Pre-setting it made every chat switch look
        // like an in-place update: the new conversation opened at whatever scroll
        // offset the old one had, i.e. the random jumps between chats.
        this.S.unread[peer] = 0;
        this.syncTaskbarBadge();
        this.initChat(peer);
        this.ensureConversationCryptoKey({ peer, reason: 'switchChat' });
        this.saveStoredCurrentContact(peer);
        this.requestMessagesScroll('bottom');
        const wasServers = this.S.navMode === 'servers';
        this.setNavMode('dm', { refresh: !wasServers });
        this.resetMessageWindow();

        const set = (id, v) => { const e = document.getElementById(id); if (e) e.textContent = v; };
        set('tbChat',       peer);
        set('chatHdrName',  peer);
        this.updateChatHeaderCryptoKey({ peer });
        const chatHdrAva = document.getElementById('chatHdrAva');
        if (chatHdrAva) {
            chatHdrAva.style.background = '';
            this.setHTMLIfChanged(chatHdrAva, this.renderAvatarHTML(peer, 'avatar-img', peer));
        }
        const chatCallBtn = document.getElementById('chatCallBtn');
        if (chatCallBtn) chatCallBtn.hidden = !this.S.current;
        const chatVideoCallBtn = document.getElementById('chatVideoCallBtn');
        if (chatVideoCallBtn) chatVideoCallBtn.hidden = !this.S.current;
        const serverSettingsBtn = document.getElementById('serverSettingsBtn');
        if (serverSettingsBtn) serverSettingsBtn.hidden = true;

        if (wasServers) {
            this.renderServerInterface();
            this.renderContacts();
            this.scheduleRenderMessages();
            this.renderVoicePanel();
        } else {
            this.renderContacts();
            this.scheduleRenderMessages();
        }
        this.updateSendButtonState();
        this.syncActiveConversation({ force: true });
        this.closeMobileSidebar();
        this.syncMobileChrome();
    }
});


// --- MODULE: interface/message_send.js ---
// --- ZaliInterface: Отправка сообщений и приём в браузерном режиме. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    async sendInputMessage() {
        // Editing takes over the composer, so the send control saves instead of
        // sending a new message.
        if (this.S.editDraft) {
            await this.submitMessageEdit();
            return;
        }
        const inp = document.getElementById('msgInput');
        const textValue = (inp && inp.value) || '';
        const text = textValue.trim();
        const attachments = this.normalizeAttachments(this.S.draftAttachments);
        if (!text && attachments.length === 0) return;

        // Snapshotted before the first await: the user can dismiss the reply bar
        // (or start another reply) while the key resolution below is in flight.
        const replyQuote = this.S.replyDraft;
        const replyPayload = replyQuote ? JSON.stringify(replyQuote) : '';

        const clientId = (window.crypto && window.crypto.randomUUID) ? window.crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
        const payloadAttachments = attachments.map(att => ({ ...att }));
        const ts = new Date().toISOString();
        const activeMode = this.currentConversationMode();
        const isServers = activeMode === 'servers';
        const server = isServers ? this.currentServer() : null;
        const channel = isServers ? this.currentChannel() : null;
        const conversationKey = isServers ? this.currentServerChatKey() : this.S.current;
        if (isServers && (!server || !channel)) return;
        if (isServers && this.isVoiceChannel(channel)) return;
        if (!isServers && !this.S.current) return;
        this.trace(`sendInputMessage context mode=${activeMode} navMode=${this.S.navMode} activeType=${String(this.S.activeConversationType || 'nil')} current=${String(this.S.current || 'nil')} activeServer=${String(this.S.activeServer || 'nil')} activeChannel=${String(this.S.activeChannel || 'nil')} rendered=${String(this.lastRenderedConversationKey || 'nil')} serverKey=${String(this.currentServerChatKey() || 'nil')}`);
        // Fast path, and the whole point of it: when this device already holds the
        // conversation key — the overwhelmingly common case — nothing between
        // pressing Enter and the message appearing is allowed to await. The old
        // code awaited resolveConversationCryptoKey() unconditionally, and since
        // the composer is only cleared after that point, the typed text sat in the
        // input box for a network round trip and Enter read as not having worked.
        //
        // resolveConversationCryptoKey() returns this exact value on its own fast
        // path; it is still called, unawaited, for the side effects that path has
        // (key display, background reconciliation with the server registry).
        const sendScope = this.conversationScopeKey(
            isServers ? null : this.S.current,
            isServers ? server.id : null,
            isServers ? channel.id : null,
        );
        const storedConversationKey = sendScope ? this.getStoredConversationKey(sendScope) : '';
        const cryptoKey = storedConversationKey || await this.resolveConversationCryptoKey({
            peer: isServers ? null : this.S.current,
            serverId: isServers ? server.id : null,
            channelId: isServers ? channel.id : null,
            reason: 'sendInputMessage'
        });
        if (storedConversationKey) {
            void this.resolveConversationCryptoKey({
                peer: isServers ? null : this.S.current,
                serverId: isServers ? server.id : null,
                channelId: isServers ? channel.id : null,
                reason: 'sendInputMessage:background'
            });
        }
        const keyVersion = 2;
        this.trace(`sendInputMessage start clientId=${clientId} mode=${activeMode} sender=${this.myName()} receiver=${isServers ? channel.id : this.S.current} server=${isServers ? server.id : 'dm'} channel=${isServers ? channel.id : 'dm'} attachments=${payloadAttachments.length} textBytes=${text.length} keySet=${!!cryptoKey} tokenSet=${!!this.S.session?.token}`);

        const outgoingMessage = {
            id: clientId,
            sender: this.myName(),
            receiver: isServers ? channel.id : this.S.current,
            text,
            attachments: payloadAttachments,
            timestamp: ts,
            status: 'sending',
            clientId,
            serverId: isServers ? server.id : null,
            channelId: isServers ? channel.id : null,
            keyVersion,
            // Same JSON string the archive carries, so the optimistic bubble and
            // the one rebuilt from history render identically.
            reply: replyPayload,
        };

        if (!this.S.session?.token) {
            this.trace(`sendInputMessage missingToken clientId=${clientId}`);
            this.addLogEntry({ type: 'ERROR', msg: 'Для отправки сообщения нужно войти в аккаунт', ts: new Date().toLocaleTimeString() });
            return;
        }

        // Recover the E2E key from the cloud vault BEFORE giving up. A fresh device
        // (or one whose in-memory key was cleared) can still have a recoverable vault
        // snapshot. This used to live after an early `if (!cryptoKey) return`, which
        // made it dead code — sends failed with "нужен E2E-ключ" even when recovery
        // would have succeeded.
        if (!cryptoKey) {
            const recoveredVaultPassphrase = await this.loadVaultUnlockSecret(this.S.session?.token);
            if (recoveredVaultPassphrase) {
                this.S.auth.vaultPassphrase = recoveredVaultPassphrase;
                await this.restoreCloudVaultSnapshot({ reason: 'sendInputMessage' });
                await this.syncCloudVaultPackage({ passphrase: recoveredVaultPassphrase, reason: 'sendInputMessage' });
            }
        }
        const effectiveCryptoKey = cryptoKey || this.loadStoredCryptoKey();
        if (!effectiveCryptoKey) {
            this.trace(`sendInputMessage missingKey clientId=${clientId}`);
            this.addLogEntry({ type: 'ERROR', msg: 'Для отправки сообщения нужен E2E-ключ', ts: new Date().toLocaleTimeString() });
            return;
        }

        if (!isServers && String(this.S.current || '').trim() !== this.myName()) {
            const scope = this.conversationScopeKey(this.S.current);
            if (!this._publishedKeyScopes) this._publishedKeyScopes = new Set();
            if (!this._publishedKeyScopes.has(scope)) {
                this._publishedKeyScopes.add(scope);
                void this.publishConversationKeyToPeer({
                    peer: this.S.current,
                    scope,
                    key: effectiveCryptoKey,
                    reason: 'sendInputMessage',
                }).then(published => {
                    if (published !== true) {
                        // false = transport/server failure, 'no_devices' = peer has no
                        // registered devices yet. Either way the envelope was not
                        // delivered, so allow a retry on the next send.
                        this._publishedKeyScopes.delete(scope);
                        this.trace(`sendInputMessage keyPublishPending peer=${this.S.current} scope=${scope} result=${published}`);
                        if (published === false) {
                            this.addLogEntry({ type: 'WARN', msg: 'E2E-ключ не доставлен собеседнику, повтор при следующей отправке', ts: new Date().toLocaleTimeString() });
                        }
                    }
                });
            }
        }

        const bridgeAvailable = this.nativeSupports('sendMessage');
        if (!bridgeAvailable) {
            this.trace(`sendInputMessage noNativeBridge clientId=${clientId}`);
            if (isServers) {
                if (!this.S.serverChats[conversationKey]) this.S.serverChats[conversationKey] = [];
                this.S.serverChats[conversationKey].push(outgoingMessage);
            } else {
                this.ensureContact(this.S.current);
                this.initChat(this.S.current);
                this.S.chats[this.S.current].push(outgoingMessage);
            }
            this.scheduleSaveStoredMessageCache();
            this.scheduleRenderMessages();
            this.renderContacts();
            this.renderServerInterface();
            if (inp) {
                inp.value = '';
                this.resizeComposer();
            }
            this.clearDraftAttachments();
            this.clearComposerReply(replyQuote);
            this.updateSendButtonState();
            inp && inp.focus();

            // No native shell (macOS/Windows) around this WebView — we're running as a
            // plain browser tab. Pack the .zali archive ourselves via the WASM build of
            // core/ (see web/src/modules/wasm_bridge.js) and upload it straight to the
            // server over fetch, instead of just stranding the message locally.
            const sent = await this.browserSendMessage({
                text,
                key: effectiveCryptoKey,
                keyVersion,
                sender: this.myName(),
                receiver: isServers ? channel.id : this.S.current,
                serverId: isServers ? server.id : '',
                channelId: isServers ? channel.id : '',
                clientId,
                attachments: payloadAttachments,
                reply: replyPayload,
            }).catch(error => {
                this.trace(`sendInputMessage browserSendMessage error clientId=${clientId} error=${error?.message || error}`);
                return false;
            });
            if (sent) {
                this.trace(`sendInputMessage browserSendMessage ok clientId=${clientId}`);
                this.addLogEntry({ type: 'SUCCESS', msg: 'Отправлено из браузера (WASM)', ts: new Date().toLocaleTimeString() });
            } else {
                // Queue it for retry instead of stranding it. This branch used to just
                // log and return, so a browser send that failed (offline, server hiccup)
                // was never attempted again — the bubble stayed on "sending" forever and
                // the message was silently lost on the next reload. flushPendingOutbox()
                // now handles browser sends too, so the same backoff/attempt-cap applies.
                this.cachePendingOutboxAttachments(clientId, payloadAttachments);
                this.enqueuePendingOutbox({
                    ...outgoingMessage,
                    key: effectiveCryptoKey,
                    keyVersion,
                    attemptCount: 1,
                    lastAttemptAt: Date.now(),
                    nextRetryAt: Date.now() + 2000,
                    inFlight: false,
                });
                this.scheduleFlushPendingOutbox(2000);
                this.addLogEntry({ type: 'WARN', msg: 'Не удалось отправить сообщение из браузера, оставлено в очереди повтора', ts: new Date().toLocaleTimeString() });
            }
            return;
        }

        if (isServers) {
            if (!this.S.serverChats[conversationKey]) this.S.serverChats[conversationKey] = [];
            this.S.serverChats[conversationKey].push(outgoingMessage);
        } else {
            this.ensureContact(this.S.current);
            this.initChat(this.S.current);
            this.S.chats[this.S.current].push(outgoingMessage);
        }
        this.scheduleSaveStoredMessageCache();

        this.scheduleRenderMessages();
        this.renderContacts();
        this.renderServerInterface();

        if (inp) {
            inp.value = '';
            this.resizeComposer();
        }

        this.clearDraftAttachments();
        this.clearComposerReply(replyQuote);
        this.updateSendButtonState();
        inp && inp.focus();

        this.cachePendingOutboxAttachments(clientId, payloadAttachments);
        this.enqueuePendingOutbox({
            ...outgoingMessage,
            key: effectiveCryptoKey,
            keyVersion,
            attemptCount: 1,
            lastAttemptAt: Date.now(),
            nextRetryAt: Date.now() + 20000,
            inFlight: true,
        });
        this.scheduleSendWatchdog(outgoingMessage, effectiveCryptoKey);
        this.trace(`sendInputMessage queued clientId=${clientId}`);

        const sentToNative = this.postNativeMessage({
            type: NativeMessageTypes.SEND_MESSAGE,
            text: text,
            reply: replyPayload,
            recipient: isServers ? channel.id : this.S.current,
            serverId: isServers ? server.id : '',
            channelId: isServers ? channel.id : '',
            sender: this.myName(),
            key: effectiveCryptoKey,
            keyVersion,
            clientId,
            attachments: payloadAttachments.map(att => ({
                name: att.name,
                mimeType: att.mimeType,
                kind: att.kind,
                size: att.size,
                dataUrl: att.dataUrl,
            }))
        });
        if (!sentToNative) {
            this.trace(`sendInputMessage native bridge rejected clientId=${clientId}`);
            this.updatePendingOutboxItem(clientId, {
                inFlight: false,
                nextRetryAt: Date.now() + 1000,
            });
            this.addLogEntry({ type: 'WARN', msg: 'Native bridge не принял сообщение, оставлено в очереди повтора', ts: new Date().toLocaleTimeString() });
            this.scheduleFlushPendingOutbox(1000);
        }
    }

    // --- Browser-only (no native shell) send/receive path, backed by the WASM build
    // of core/ (web/src/modules/wasm_bridge.js packs/unpacks the .zali archive format
    // entirely in-browser — same wire format as the native macOS/Windows clients use).

    async wasmAvailable() {
        return !!(window.ZaliWasm && await window.ZaliWasm.isAvailable());
    }

    async dataUrlToBytes(dataUrl) {
        const res = await fetch(dataUrl);
        const buf = await res.arrayBuffer();
        return new Uint8Array(buf);
    }

    async browserSendMessage({ text, key, keyVersion, sender, receiver, serverId, channelId, clientId, attachments, reply }) {
        if (!key || !receiver) return false;
        if (!(await this.wasmAvailable())) return false;

        const wasmAttachments = [];
        for (const att of (attachments || [])) {
            if (!att?.dataUrl) continue;
            try {
                const bytes = await this.dataUrlToBytes(att.dataUrl);
                wasmAttachments.push({
                    name: att.name || 'attachment',
                    archivePath: `attachments/${att.name || 'attachment'}`,
                    mimeType: att.mimeType || 'application/octet-stream',
                    kind: att.kind || 'file',
                    bytes,
                });
            } catch (e) {
                this.trace(`browserSendMessage attachment decode failed name=${att?.name} error=${e?.message || e}`);
            }
        }

        const archiveBytes = await window.ZaliWasm.packMessage(sender, text, key, keyVersion, wasmAttachments, '', reply || '');
        if (!archiveBytes || !archiveBytes.length) return false;

        const formData = new FormData();
        formData.append('sender', sender || '');
        formData.append('receiver', receiver);
        if (serverId) formData.append('server_id', serverId);
        if (channelId) formData.append('channel_id', channelId);
        if (clientId) formData.append('client_id', clientId);
        formData.append('key_version', String(keyVersion || ''));
        formData.append('file', new Blob([archiveBytes], { type: 'application/octet-stream' }), 'message.zali');

        const res = await this.apiFetch(this.apiRoutes.messages.upload, {
            method: 'POST',
            body: formData,
        });
        return res.ok;
    }

    /**
     * Browser/PWA counterpart of the native EDIT_MESSAGE bridge: re-packs the
     * whole message (text + attachments + quote) into a fresh `.zali` via WASM
     * and PUTs it over the existing one.
     */
    async browserEditMessage({ messageId, text, key, keyVersion, attachments, reply }) {
        const id = String(messageId || '').trim();
        if (!id || !key) return false;
        if (!(await this.wasmAvailable())) {
            this.addLogEntry({ type: 'ERROR', msg: 'Редактирование недоступно: WASM-модуль не загружен', ts: new Date().toLocaleTimeString() });
            return false;
        }

        const wasmAttachments = [];
        for (const att of (attachments || [])) {
            if (!att?.dataUrl) continue;
            try {
                const bytes = await this.dataUrlToBytes(att.dataUrl);
                wasmAttachments.push({
                    name: att.name || 'attachment',
                    archivePath: att.archivePath || `attachments/${att.name || 'attachment'}`,
                    mimeType: att.mimeType || 'application/octet-stream',
                    kind: att.kind || 'file',
                    bytes,
                });
            } catch (e) {
                // Losing an attachment to a decode error would silently strip it
                // from the message, since the edit replaces the archive wholesale.
                this.trace(`browserEditMessage attachment decode failed name=${att?.name} error=${e?.message || e}`);
                throw new Error(`Не удалось перечитать вложение «${att?.name || ''}»`);
            }
        }

        const archiveBytes = await window.ZaliWasm.packMessage(
            this.myName(), text, key, keyVersion, wasmAttachments, '', reply || ''
        );
        if (!archiveBytes || !archiveBytes.length) return false;

        const formData = new FormData();
        formData.append('key_version', String(keyVersion || 2));
        formData.append('file', new Blob([archiveBytes], { type: 'application/octet-stream' }), 'message.zali');

        const res = await this.apiFetch(this.apiRoutes.messages.edit(id), {
            method: 'PUT',
            body: formData,
        });
        if (!res.ok) {
            throw new Error(await res.text().catch(() => '') || `HTTP ${res.status}`);
        }
        return true;
    }

    // Handles a raw `Message` row pushed over the WS connection (no `type` field —
    // see server/src/realtime.rs deliver_to_user/deliver_server_message). Downloads
    // the .zali archive and decrypts it in-browser via WASM, then feeds the result
    // into the same receiveMessage() path the native shells use.
    async handleIncomingBrowserMessage(payload) {
        const id = String(payload?.id || '').trim();
        const sender = String(payload?.sender || '').trim();
        const receiver = String(payload?.receiver || '').trim();
        if (!id || !sender || !receiver) return;

        // Already decoded in THIS page session — skip the whole round trip.
        //
        // loadBrowserDmHistory feeds every history row through here on every sync,
        // and a sync happens on each refreshAfterKey (one per key_envelope_available
        // push), each syncActiveConversation and each reconnect. Without this guard
        // every one of them re-downloaded the archive, re-ran the WASM unpack and
        // wrapped each attachment in a FRESH Blob + object URL — and nothing ever
        // revoked the previous one, so the browser pinned the entire conversation
        // again per sync. Measured by scripts/memory_doctor: 11 syncs of a 20-message
        // 5 MB conversation retained 55 MB and issued 220 downloads. A real session
        // logged 1097 refreshAfterKey calls.
        //
        // Session-scoped on purpose, rather than a lookup in the message cache: a
        // cached `blob:` URL is already dead after a page reload (see the comment in
        // saveStoredMessageCache), and re-fetching is exactly what repairs it. A
        // fresh Set per page load keeps that repair while killing the in-session churn.
        if (!this._decodedBrowserMessageIds) this._decodedBrowserMessageIds = new Set();
        if (this._decodedBrowserMessageIds.has(id)) return;

        if (!(await this.wasmAvailable())) return;

        const serverId = payload?.server_id || null;
        const channelId = payload?.channel_id || null;
        const peer = sender === this.myName() ? receiver : sender;

        let key = this.ensureConversationCryptoKey({
            peer: serverId ? null : peer,
            serverId,
            channelId,
            reason: 'handleIncomingBrowserMessage',
        });
        for (let attempt = 0; !key && attempt < 5; attempt++) {
            await new Promise(resolve => setTimeout(resolve, 400));
            key = await this.resolveConversationCryptoKey({
                peer: serverId ? null : peer,
                serverId,
                channelId,
                reason: 'handleIncomingBrowserMessage',
            });
        }
        if (!key) {
            this.trace(`handleIncomingBrowserMessage missingKey id=${id} peer=${peer}`);
            // Dropped, not placeholdered — record it so a key arriving later still
            // triggers the reload that fetches this message.
            this.markBrowserDecryptGap({ peer: serverId ? null : peer, serverId, channelId });
            return;
        }

        const candidates = this.browserDecryptCandidates({
            peer: serverId ? null : peer,
            serverId,
            channelId,
            activeKey: key,
        });
        if (this.browserUnpackKnownToFail(id, candidates)) {
            this.trace(`handleIncomingBrowserMessage skipped id=${id} reason=known_undecryptable_with_current_keys`);
            this.markBrowserDecryptGap({ peer: serverId ? null : peer, serverId, channelId });
            return;
        }

        try {
            // A `.zali` archive carries the message's attachments, so this is a bulk
            // transfer, not an API round trip — the general request timeout would
            // abort a large but perfectly healthy download.
            const res = await this.apiFetch(this.apiRoutes.messages.download(id), {
                timeoutMs: TRANSFER_REQUEST_TIMEOUT_MS,
            });
            if (!res.ok) return;
            const archiveBytes = new Uint8Array(await res.arrayBuffer());
            const unpacked = await this.unpackBrowserMessageWithCandidates(archiveBytes, candidates, id);
            const attachments = (unpacked.attachments || []).map(att => ({
                name: att.name,
                mimeType: att.mimeType,
                kind: att.kind,
                size: att.bytes?.length || 0,
                // `new Uint8Array(...)` is load-bearing, not defensive tidiness:
                // wasm-bindgen hands `bytes` back as a plain JS **Array** of numbers,
                // and the Blob constructor stringifies any array-like that isn't an
                // ArrayBuffer view. `new Blob([[137,80,78,71,...]])` therefore produced
                // the ASCII text "137,80,78,71,..." instead of the bytes — every
                // attachment received in the browser client came out corrupt and
                // roughly 3x oversized (a 70-byte PNG became 198 bytes of digits).
                dataUrl: att.bytes?.length
                    ? URL.createObjectURL(new Blob(
                        [att.bytes instanceof Uint8Array ? att.bytes : new Uint8Array(att.bytes)],
                        { type: att.mimeType || 'application/octet-stream' },
                    ))
                    : '',
                archivePath: att.archivePath,
            }));
            this.bus.send('zali_interface:receive_message', {
                id,
                // Both spellings on purpose: the live WS payload is a serialized
                // `Message` (snake_case `client_id`), while history rows from
                // GET /api/messages/:user are `MessageResponse`, which renames the
                // field to `clientId`. Reading only the snake_case one left every
                // history row without a clientId, so finalizePendingMessage() never
                // reconciled the locally-echoed copy — after a reload your own sent
                // message showed twice, one of them stuck on "sending" forever.
                clientId: payload?.clientId || payload?.client_id || '',
                sender: unpacked.sender || sender,
                receiver,
                text: unpacked.text,
                // Decrypted by the WASM core alongside the body; without this the
                // browser client would render replies as ordinary messages.
                reply: unpacked.reply || '',
                timestamp: unpacked.timestamp ? unpacked.timestamp * 1000 : payload?.timestamp,
                attachments,
                reactions: payload?.reactions || [],
                myReactions: payload?.myReactions || payload?.my_reactions || [],
                serverId,
                channelId,
            });
            // Only after a delivery that actually succeeded: a message marked here
            // on a failed attempt would never be retried once its key arrives.
            this._decodedBrowserMessageIds.add(id);
            // Ids only (no payload), but a long-lived tab in a busy channel should
            // still not grow this without bound. Dropping the oldest entry costs at
            // most one redundant re-fetch of a message that far back in history.
            if (this._decodedBrowserMessageIds.size > 5000) {
                this._decodedBrowserMessageIds.delete(this._decodedBrowserMessageIds.values().next().value);
            }
        } catch (e) {
            this.trace(`handleIncomingBrowserMessage failed id=${id} error=${e?.message || e}`);
            this.markBrowserDecryptGap({ peer: serverId ? null : peer, serverId, channelId });
            // Unlike the native shells, this path fails silently otherwise — there
            // is no placeholder message for the render-time hook in
            // detectSystemNotice() to catch, so this is the only place a
            // browser-client decrypt/unpack failure ever gets reported at all.
            void this.reportDecryptFailure({
                reason: 'browser-unpack-failed',
                clientError: `${e?.name || 'Error'}: ${e?.message || e}`,
                messageId: id,
                clientId: payload?.clientId || payload?.client_id || '',
                sender,
                receiver,
                serverId,
                channelId,
                messageTimestamp: payload?.timestamp,
            });
        }
    }

    // Opens a downloaded archive with every key this device could plausibly have
    // encrypted it under, not just the scope's current active key.
    //
    // The native shells have always done this — macOS `renderHistoryRecord` and
    // Windows `candidate_message_keys` both try the scope key, then every other key
    // the account holds — and the whole `alt:` mechanism exists to keep a superseded
    // key usable for decryption after it has been demoted. The browser path ignored
    // all of it and passed one key to unpackMessage(), so in a browser tab or the
    // PWA every message written before a conversation converged was permanently
    // unreadable, with no placeholder and no retry: exactly the messages the
    // candidate pool was built to rescue.
    //
    // Ordering matters for cost, not correctness: each failed attempt is a full
    // PBKDF2-SHA256 210 000 derivation, so the key most likely to work goes first
    // and the account-wide sweep last.
    browserDecryptCandidates({ peer = null, serverId = null, channelId = null, activeKey = '' } = {}) {
        const scope = this.conversationScopeKey(peer, serverId, channelId);
        const stored = this.loadStoredConversationKeys();
        const candidates = [];
        const push = (value) => {
            const key = String(value || '').trim();
            if (key && !candidates.includes(key)) candidates.push(key);
        };
        push(activeKey);
        if (scope) this.conversationKeyCandidates(stored, scope).forEach(push);
        // Last resort, mirroring both native shells: a message whose scope→key
        // mapping is stale or missing may still open under a key filed elsewhere.
        Object.values(stored).forEach(push);

        // Bounded for the same reason the native shells bound theirs: every candidate
        // that does not fit costs two PBKDF2-SHA256 passes at 210 000 iterations, and
        // `alt:` keys accumulate for the life of a conversation. The scoped candidates
        // come first and are the ones that can realistically work; the account-wide
        // tail is a heuristic and does not deserve an unbounded budget.
        return candidates.slice(0, ZaliInterface.MAX_DECRYPT_CANDIDATES);
    }

    // Has this exact message already been tried against exactly this candidate list?
    //
    // Checked BEFORE the archive is fetched, not just before the sweep: a message
    // nothing can open is re-encountered on every history load, and re-downloading it
    // to re-derive the same failures is the larger half of the waste. The memo is
    // keyed on the candidate list itself, so the first new key changes it and the
    // retry — download included — happens immediately.
    browserUnpackKnownToFail(messageId, candidates) {
        const id = String(messageId || '').trim();
        if (!id || !this._failedBrowserUnpacks) return false;
        return this._failedBrowserUnpacks.get(id) === candidates.join('|');
    }

    rememberBrowserUnpackFailure(messageId, candidates) {
        const id = String(messageId || '').trim();
        if (!id) return;
        if (!this._failedBrowserUnpacks) this._failedBrowserUnpacks = new Map();
        this._failedBrowserUnpacks.set(id, candidates.join('|'));
        if (this._failedBrowserUnpacks.size > 4000) {
            this._failedBrowserUnpacks.delete(this._failedBrowserUnpacks.keys().next().value);
        }
    }

    async unpackBrowserMessageWithCandidates(archiveBytes, candidates, messageId = '') {
        let lastError = null;
        for (const candidate of candidates) {
            try {
                const unpacked = await window.ZaliWasm.unpackMessage(archiveBytes, candidate);
                if (messageId && this._failedBrowserUnpacks) {
                    this._failedBrowserUnpacks.delete(String(messageId).trim());
                }
                return unpacked;
            } catch (e) {
                lastError = e;
            }
        }
        this.rememberBrowserUnpackFailure(messageId, candidates);
        throw lastError || new Error('Нет ключа для расшифровки сообщения');
    }

    // Fallback for loading DM history from a plain browser tab (no native shell to do
    // it via REFRESH_HISTORY). Downloads + decrypts each message metadata row returned
    // by GET /api/messages/:user and feeds it through receiveMessage(), same as above.
    async loadBrowserDmHistory(peer, key) {
        if (!peer || !key) return;
        if (!(await this.wasmAvailable())) return;
        // Cleared before the walk, not after: every row is fed through
        // handleIncomingBrowserMessage below, which re-marks the gap for anything it
        // still cannot open. A gap that survives this load is therefore a real one,
        // and a conversation that has been repaired stops asking for reloads.
        this.clearBrowserDecryptGap({ peer });
        try {
            const res = await this.apiFetch(this.apiRoutes.messages.direct(peer));
            if (!res.ok) return;
            const rows = await res.json();
            if (!Array.isArray(rows)) return;
            // Bounded concurrency instead of one strictly serial pass. Each row is an
            // independent download plus a WASM unpack, and doing them one after another
            // made a history load take the sum of every round trip. Kept small on
            // purpose: the requests still share the five-slot apiFetch pool, and going
            // wider here would starve the envelope sync and the live message path
            // behind a history load rather than speed anything up.
            const HISTORY_CONCURRENCY = 4;
            let next = 0;
            const worker = async () => {
                while (next < rows.length) {
                    const row = rows[next++];
                    await this.handleIncomingBrowserMessage(row);
                }
            };
            await Promise.all(
                Array.from({ length: Math.min(HISTORY_CONCURRENCY, rows.length) }, worker)
            );
        } catch (e) {
            this.trace(`loadBrowserDmHistory failed peer=${peer} error=${e?.message || e}`);
        }
    }

    _getKey() {
        try {
            return this.ensureConversationCryptoKey({
                peer: this.currentConversationMode() === 'servers' ? null : this.S.current,
                serverId: this.currentConversationMode() === 'servers' ? this.currentServer()?.id || null : null,
                channelId: this.currentConversationMode() === 'servers' ? this.currentChannel()?.id || null : null,
                reason: '_getKey'
            });
        } catch (e) {
            return '';
        }
    }

    updateSendButtonState() {
        const btn = document.getElementById('sendBtn');
        const inp = document.getElementById('msgInput');
        const hasText = !!(inp && inp.value.trim().length);
        const hasAttachments = this.S.draftAttachments.length > 0;
        const channel = this.currentChannel();
        const canSend = this.currentConversationMode() === 'servers'
            ? !!(this.currentServer() && channel && !this.isVoiceChannel(channel))
            : !!this.S.current;
        if (btn) btn.disabled = !(hasText || hasAttachments) || !canSend;
    }

    // --- Bus Command Handlers ---

    receiveMessage(payload = {}) {
        // Call records are not chat text and DM-only, so they take their own path
        // instead of being threaded through both branches of the logic below.
        const callRecord = this.parseCallRecordPayload(payload);
        if (callRecord) {
            const clientId = String(payload?.clientId || payload?.client_id || '').trim();
            if (clientId) this.dropPendingOutbox(clientId);
            this.applyCallRecordMessage(callRecord, payload);
            return;
        }
        const {
            id,
            sender,
            receiver,
            text,
            timestamp,
            attachments,
            reactions,
            myReactions,
        } = payload || {};
        // Opaque quote string straight from the archive. This handler rebuilds the
        // stored message field by field (it does not spread the payload), so a
        // field left out here is silently lost on live delivery and only reappears
        // after the next history reload.
        const reply = String(payload?.reply || '');
        const serverId = payload?.serverId || payload?.server_id || null;
        const channelId = payload?.channelId || payload?.channel_id || null;
        const clientId = String(payload?.clientId || payload?.client_id || '').trim();
        this.trace(`receiveMessage id=${String(id || '').trim()} clientId=${clientId || 'none'} sender=${String(sender || '').trim()} receiver=${String(receiver || '').trim()} server=${serverId || 'dm'} channel=${channelId || 'dm'} textBytes=${String(text || '').length} attachments=${Array.isArray(attachments) ? attachments.length : 0} reactions=${Array.isArray(reactions) ? reactions.length : 0}`);
        if (clientId) {
            const reconciled = this.finalizePendingMessage(clientId, id);
            if (reconciled) {
                this.dropPendingOutbox(clientId);
                // The one thing reconciliation must still take from the incoming
                // copy — see adoptAttachmentPayloads().
                const peer = String(sender || '').trim() === this.myName()
                    ? String(receiver || '').trim()
                    : String(sender || '').trim();
                const store = (serverId && channelId)
                    ? this.S.serverChats[`${serverId}:${channelId}`]
                    : this.S.chats[peer];
                this.adoptAttachmentPayloads(store, {
                    msgId: id,
                    clientId,
                    attachments: this.normalizeAttachments(attachments),
                });
                if (serverId && channelId) {
                    this.renderServerInterface();
                } else {
                    this.scheduleRenderMessages();
                    this.renderContacts();
                }
                this.addLogEntry({ type: 'SUCCESS', msg: `Сообщение подтверждено сервером: ${sender}`, ts: new Date().toLocaleTimeString() });
                return;
            }
        }
        if (serverId && channelId) {
            const key = `${serverId}:${channelId}`;
            const msgs = this.S.serverChats[key] || (this.S.serverChats[key] = []);
            const incomingAttachments = this.normalizeAttachments(attachments);
            const incomingReactions = this.normalizeReactions(reactions);
            const incomingText = this.sanitizeDecryptionErrorText(text);
            const messageId = String(id || '').trim();
            const attachmentKey = incomingAttachments.map(att => `${att.name}:${att.kind}:${att.size}`).join('|');
            const ts = timestamp || new Date().toISOString();
            const existingIndex = messageId
                ? msgs.findIndex(m => String(m.id || '').trim() === messageId)
                : msgs.findIndex(m =>
                    m.sender === sender &&
                    m.text === incomingText &&
                    this.normalizeAttachments(m.attachments).map(att => `${att.name}:${att.kind}:${att.size}`).join('|') === attachmentKey
                );
            if (existingIndex >= 0) {
                const prev = msgs[existingIndex];
                msgs[existingIndex] = {
                    ...prev,
                    id: messageId || prev.id || '',
                    clientId: clientId || prev.clientId || '',
                    sender: sender || prev.sender || '',
                    receiver: receiver || prev.receiver || '',
                    text: incomingText || prev.text || '',
                    attachments: incomingAttachments.length ? incomingAttachments : this.normalizeAttachments(prev.attachments),
                    reactions: incomingReactions.length ? incomingReactions : this.normalizeReactions(prev.reactions),
                    myReactions: this.normalizeMyReactions(myReactions?.length ? myReactions : prev.myReactions),
                    timestamp: ts || prev.timestamp || new Date().toISOString(),
                    reply: reply || prev.reply || '',
                    serverId: serverId || prev.serverId || '',
                    channelId: channelId || prev.channelId || '',
                };
            } else {
                msgs.push({
                    id: messageId,
                    clientId,
                    sender,
                    receiver,
                    text: incomingText,
                    attachments: incomingAttachments,
                    reactions: incomingReactions,
                    myReactions: this.normalizeMyReactions(myReactions),
                    timestamp: ts,
                    reply,
                    serverId,
                    channelId,
                });
                // "Visible" requires both the matching channel AND the servers view being
                // active — currentServerChatKey() keeps returning the selected channel
                // even while the user is looking at DMs, which used to swallow the
                // notification for messages arriving in that channel.
                const channelVisible = this.isServerChatVisible(key);
                if (!channelVisible) {
                    this.notifyBackgroundMessage({ sender, text: incomingText, attachmentCount: incomingAttachments.length, serverId, channelId });
                }
            }
            this.scheduleSaveStoredMessageCache();
            // Only render the channel's message list when it is actually the visible view.
            // currentServerChatKey() still returns the selected channel while the user is
            // in the DM view, so rendering on that alone painted channel messages into the
            // DM pane (and wasted work). Mirror the notification-visibility check above.
            if (this.isServerChatVisible(key)) {
                this.scheduleRenderMessages();
            } else {
                this.renderServerInterface();
                this.renderContacts();
            }
            this.scheduleConversationRefresh({
                serverId,
                channelId,
                reason: 'receiveMessageServer',
            });
            this.addLogEntry({ type: 'SUCCESS', msg: `Получено в канале ${serverId}/${channelId}: ${sender}`, ts: new Date().toLocaleTimeString() });
            return;
        }

        const peer = sender === this.myName() ? receiver : sender;
        this.ensureContact(peer);
        this.initChat(peer);
        const msgs = this.S.chats[peer];
        const incomingAttachments = this.normalizeAttachments(attachments);
        const incomingReactions = this.normalizeReactions(reactions);
        const incomingText = this.sanitizeDecryptionErrorText(text);
        const messageId = String(id || '').trim();
        const attachmentKey = incomingAttachments.map(att => `${att.name}:${att.kind}:${att.size}`).join('|');
        const ts = timestamp || new Date().toISOString();
        const existingIndex = messageId
            ? msgs.findIndex(m => String(m.id || '').trim() === messageId)
            : msgs.findIndex(m =>
                m.sender === sender &&
                m.text === incomingText &&
                this.normalizeAttachments(m.attachments).map(att => `${att.name}:${att.kind}:${att.size}`).join('|') === attachmentKey
            );
        if (existingIndex >= 0) {
            const prev = msgs[existingIndex];
            msgs[existingIndex] = {
                ...prev,
                id: messageId || prev.id || '',
                clientId: clientId || prev.clientId || '',
                sender: sender || prev.sender || '',
                receiver: receiver || prev.receiver || '',
                text: incomingText || prev.text || '',
                attachments: incomingAttachments.length ? incomingAttachments : this.normalizeAttachments(prev.attachments),
                reactions: incomingReactions.length ? incomingReactions : this.normalizeReactions(prev.reactions),
                myReactions: this.normalizeMyReactions(myReactions?.length ? myReactions : prev.myReactions),
                timestamp: ts || prev.timestamp || new Date().toISOString(),
                reply: reply || prev.reply || '',
            };
        } else {
            msgs.push({
                id: messageId,
                clientId,
                sender,
                receiver,
                text: incomingText,
                attachments: incomingAttachments,
                reactions: incomingReactions,
                myReactions: this.normalizeMyReactions(myReactions),
                timestamp: ts,
                reply,
            });
            // A DM is only truly visible when its chat is selected AND the DM view is
            // active — while the user is in the servers view the selected DM peer is
            // off-screen, and this notification used to be swallowed for it.
            const dmVisible = this.isDmChatVisible(peer);
            if (!dmVisible) {
                this.notifyBackgroundMessage({ sender, text: incomingText, attachmentCount: incomingAttachments.length, peer });
            }
        }
        this.scheduleSaveStoredMessageCache();
        if (!this.S.current) {
            this.switchChat(peer);
        }
        if (this.isDmChatVisible(peer)) {
            this.scheduleRenderMessages();
        } else {
            // Unread/notification bookkeeping (own-echo filtering included) already
            // happened above via notifyBackgroundMessage; just refresh the sidebar.
            this.renderContacts();
        }
        this.addLogEntry({ type: 'SUCCESS', msg: `Получено: ${sender} → ${receiver}`, ts: new Date().toLocaleTimeString() });
    }
});


// --- MODULE: interface/notifications.js ---
// --- ZaliInterface: Мьюты, звуки, уведомления, бейдж непрочитанного. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    handleAvatarUpdated({ username, deleted = false } = {}) {
        const name = String(username || '').trim();
        if (!name) return;

        if (deleted) {
            this.saveStoredAvatar(name, null);
            // saveStoredAvatar() правит только память — в отличие от
            // clearStoredAvatar() она не трогает диск. Без этой строки снятая
            // аватарка оставалась в постоянном кеше, и следующий запуск
            // поднимал её обратно прогревом: renderAvatarHTML находил значение,
            // ensureAvatarLoaded() не вызывался, и удалённая картинка висела
            // бы бессрочно — перепроверять её было бы просто некому.
            void this.cacheDelete('avatar', this.avatarCacheKey(name));
        } else {
            this.clearStoredAvatar(name);
            this.ensureAvatarLoaded(name, { force: true });
        }

        this.scheduleAvatarRefresh();
    }

    // Single source of truth for "is this conversation currently on screen". The
    // notification-suppression, render, and unread-clear paths must all agree on this;
    // spelling it out inline at each site is how they drifted apart before.
    isServerChatVisible(key) {
        return this.currentServerChatKey() === key && this.S.navMode === 'servers';
    }

    isDmChatVisible(peer) {
        if (!peer || peer !== this.S.current) return false;
        if (this.S.navMode === 'servers') return false;
        // The Hub and Settings screens are full-view overlays, not a navMode — so a DM
        // that is "selected" is still completely off-screen while either is open. Only
        // the servers view was excluded here, which meant an incoming message for the
        // selected peer produced no notification AND no unread increment for as long as
        // the user sat on the Hub. Same class of bug as the servers-view fix above it.
        if (document.getElementById('viewHub')?.classList.contains('active')) return false;
        if (document.getElementById('viewSettings')?.classList.contains('active')) return false;
        return true;
    }

    isPeerMuted(peer) {
        return !!(this.S.mutedChats || {})[String(peer || '').trim()];
    }

    isChannelMuted(serverId, channelId) {
        const sid = String(serverId || '').trim();
        const cid = String(channelId || '').trim();
        if (!sid || !cid) return false;
        return !!(this.S.mutedChats || {})[`${sid}:${cid}`];
    }

    toggleMutePeer(peer) {
        const key = String(peer || '').trim();
        if (!key) return;
        this.S.mutedChats = this.S.mutedChats || {};
        if (this.S.mutedChats[key]) {
            delete this.S.mutedChats[key];
        } else {
            this.S.mutedChats[key] = true;
        }
        this.saveStoredMutedChats();
        this.renderContacts();
    }

    closeContactContextMenu() {
        const existing = document.getElementById('contactContextMenu');
        if (existing) existing.remove();
        if (this._contactContextMenuOutsideHandler) {
            document.removeEventListener('click', this._contactContextMenuOutsideHandler);
            document.removeEventListener('contextmenu', this._contactContextMenuOutsideHandler);
            this._contactContextMenuOutsideHandler = null;
        }
        if (this._contactContextMenuKeyHandler) {
            document.removeEventListener('keydown', this._contactContextMenuKeyHandler, true);
            this._contactContextMenuKeyHandler = null;
        }
    }

    // Right-click on a contact — notification mute (existing behavior) plus
    // per-contact call volume, applied live to that peer's WebAudio gain node
    // (see ensureRemotePlaybackNode/applyPeerVolume) when they're in a call,
    // and persisted for future calls either way.
    openContactContextMenu(peer, x, y) {
        this.closeContactContextMenu();
        const name = String(peer || '').trim();
        if (!name) return;
        const muted = !!(this.S.mutedChats || {})[name];
        const percent = this.getPeerVolumePercent(name);
        const isSelf = name === this.myName();
        const menu = document.createElement('div');
        menu.id = 'contactContextMenu';
        menu.className = 'peer-context-menu';
        // Подписка и дружба идут первыми: это то, ради чего сюда чаще всего
        // и жмут ПКМ. Их подписи зависят от текущих отношений, которых мы ещё
        // не знаем, — они уточняются ниже, когда придёт профиль. До ответа
        // пункты показывают нейтральное действие, а не мигают пустотой.
        menu.setAttribute('role', 'menu');
        menu.tabIndex = -1;
        menu.innerHTML = `
            <button type="button" class="peer-context-menu-item" role="menuitem" data-action="profile">
                ${this.uiIcon('user')}<span>Открыть профиль</span>
            </button>
            ${isSelf ? '' : `
            <button type="button" class="peer-context-menu-item" role="menuitem" data-action="follow">
                ${this.uiIcon('eye')}<span id="contactFollowLabel">Отслеживать</span>
            </button>
            <button type="button" class="peer-context-menu-item" role="menuitem" data-action="friend">
                ${this.uiIcon('user-plus')}<span id="contactFriendLabel">Попроситься в друзья</span>
            </button>`}
            <div class="peer-context-menu-sep" aria-hidden="true"></div>
            <button type="button" class="peer-context-menu-item" role="menuitem" data-action="mute">
                ${this.uiIcon(muted ? 'bell' : 'bell-off')}<span>${muted ? 'Включить уведомления' : 'Заглушить уведомления'}</span>
            </button>
            <div class="peer-context-menu-volume">
                <div class="peer-context-menu-volume-head"><span>Громкость</span><strong id="contactVolumeValue">${percent}%</strong></div>
                <input type="range" min="0" max="200" step="5" value="${percent}" id="contactVolumeRange"
                       class="peer-context-menu-range" aria-label="Громкость собеседника">
            </div>
        `;
        document.body.appendChild(menu);

        // Меню разворачивается ОТ курсора, а не на ближайший свободный край:
        // раньше оно только зажималось в окно, поэтому у нижней или правой
        // границы накрывало собой ту самую строку, по которой щёлкнули.
        // offsetWidth/Height, а не getBoundingClientRect(): меню в этот момент
        // на первом кадре анимации появления, то есть под scale(.965), и
        // прямоугольник вернул бы размер на 3,5 % меньше настоящего — ровно
        // столько меню потом и вылезало бы за край экрана.
        const width = menu.offsetWidth;
        const height = menu.offsetHeight;
        const pad = 8;
        const flipX = x + width + pad > window.innerWidth && x - width > pad;
        const flipY = y + height + pad > window.innerHeight && y - height > pad;
        const left = Math.max(pad, Math.min(flipX ? x - width : x, window.innerWidth - width - pad));
        const top = Math.max(pad, Math.min(flipY ? y - height : y, window.innerHeight - height - pad));
        menu.style.left = `${left}px`;
        menu.style.top = `${top}px`;
        menu.style.setProperty('--menu-origin', `${flipY ? 'bottom' : 'top'} ${flipX ? 'right' : 'left'}`);

        menu.querySelector('[data-action="profile"]')?.addEventListener('click', () => {
            this.closeContactContextMenu();
            void this.openProfile(name);
        });
        menu.querySelector('[data-action="follow"]')?.addEventListener('click', () => {
            const following = menu.dataset.following === '1';
            this.closeContactContextMenu();
            void this.followUserDirect(name, following);
        });
        menu.querySelector('[data-action="friend"]')?.addEventListener('click', () => {
            // Уже друзья — вести в профиль: удалять из друзей одним нажатием
            // в контекстном меню слишком легко промахнуться.
            if (menu.dataset.friend === '1') {
                this.closeContactContextMenu();
                void this.openProfile(name);
                return;
            }
            this.closeContactContextMenu();
            void this.requestFriendship(name);
        });
        menu.querySelector('[data-action="mute"]')?.addEventListener('click', () => {
            this.toggleMutePeer(name);
            this.closeContactContextMenu();
        });
        const range = menu.querySelector('#contactVolumeRange');
        const label = menu.querySelector('#contactVolumeValue');
        // Шкала 0–200 %, поэтому доля закрашенной части — это value/200,
        // а не value: без пересчёта 100 % заливало бы ползунок целиком.
        const paintRange = (value) => range?.style.setProperty('--fill', `${Math.max(0, Math.min(100, value / 2))}%`);
        paintRange(percent);
        range?.addEventListener('input', () => {
            const value = Number(range.value) || 100;
            if (label) label.textContent = `${value}%`;
            paintRange(value);
            this.setPeerVolumePercent(name, value);
        });

        if (!isSelf) void this.decorateContactContextMenu(menu, name);

        // Меню, которое нельзя закрыть с клавиатуры, приходится закрывать
        // мышью «куда-нибудь мимо» — а мимо здесь означает по контакту или
        // по сообщению, то есть случайное действие. Escape закрывает,
        // стрелки ходят по пунктам.
        const items = () => Array.from(menu.querySelectorAll('.peer-context-menu-item'));
        const keyHandler = (evt) => {
            if (!menu.isConnected) return;
            if (evt.key === 'Escape') {
                evt.preventDefault();
                this.closeContactContextMenu();
                return;
            }
            if (evt.key !== 'ArrowDown' && evt.key !== 'ArrowUp') return;
            const list = items();
            if (!list.length) return;
            evt.preventDefault();
            const current = list.indexOf(document.activeElement);
            const step = evt.key === 'ArrowDown' ? 1 : -1;
            const next = current < 0
                ? (step > 0 ? 0 : list.length - 1)
                : (current + step + list.length) % list.length;
            list[next].focus();
        };
        this._contactContextMenuKeyHandler = keyHandler;
        document.addEventListener('keydown', keyHandler, true);
        // Фокус на самом меню, а не на первом пункте: подсвеченный пункт
        // сразу после ПКМ читается как уже выбранное действие.
        menu.focus({ preventScroll: true });

        const outsideHandler = (evt) => {
            if (menu.contains(evt.target)) return;
            this.closeContactContextMenu();
        };
        this._contactContextMenuOutsideHandler = outsideHandler;
        // Deferred a tick so the contextmenu event that opened this menu
        // doesn't immediately bubble into the same listener and close it.
        setTimeout(() => {
            document.addEventListener('click', outsideHandler);
            document.addEventListener('contextmenu', outsideHandler);
        }, 0);
    }

    /**
     * Дотягивает в открытое контекстное меню реальное состояние отношений.
     * Отдельным запросом и после показа меню: тянуть профиль ДО открытия
     * значило бы задержку между нажатием ПКМ и появлением меню на всю дорогу
     * до сервера. Если меню успели закрыть — ответ просто выбрасывается.
     */
    async decorateContactContextMenu(menu, name) {
        try {
            const res = await this.apiFetch(this.apiRoutes.profiles.byUsername(name), { interactive: true });
            if (!res.ok) return;
            if (!menu.isConnected) return;
            const data = await res.json();
            menu.dataset.following = data?.isFollowing ? '1' : '0';
            menu.dataset.friend = data?.isFriend ? '1' : '0';
            const followLabel = menu.querySelector('#contactFollowLabel');
            if (followLabel) followLabel.textContent = data?.isFollowing ? 'Не отслеживать' : 'Отслеживать';
            const followIcon = menu.querySelector('[data-action="follow"] .ui-icon');
            if (followIcon) followIcon.outerHTML = this.uiIcon(data?.isFollowing ? 'eye-off' : 'eye');
            const friendLabel = menu.querySelector('#contactFriendLabel');
            if (friendLabel) {
                if (data?.isFriend) friendLabel.textContent = 'Вы друзья';
                else if (data?.friendRequest?.direction === 'outgoing') friendLabel.textContent = 'Заявка отправлена';
                else if (data?.friendRequest?.direction === 'incoming') friendLabel.textContent = 'Принять заявку в друзья';
                else friendLabel.textContent = 'Попроситься в друзья';
            }
            if (data?.friendRequest?.direction === 'incoming') {
                menu.querySelector('[data-action="friend"]')?.setAttribute('data-request-id', data.friendRequest.id);
            }
        } catch (e) {
            // Подписи останутся нейтральными — меню всё равно рабочее.
        }
    }

    toggleMuteChannel(serverId, channelId) {
        const sid = String(serverId || '').trim();
        const cid = String(channelId || '').trim();
        if (!sid || !cid) return;
        const key = `${sid}:${cid}`;
        this.S.mutedChats = this.S.mutedChats || {};
        if (this.S.mutedChats[key]) {
            delete this.S.mutedChats[key];
        } else {
            this.S.mutedChats[key] = true;
        }
        this.saveStoredMutedChats();
        this.renderServerInterface();
        this.renderContacts();
    }

    // Registers a one-time listener on the very first user gesture (click/key/touch)
    // to create+resume a persistent AudioContext. Browsers require AudioContext to be
    // resumed from within a user-gesture call stack at least once per page load —
    // it doesn't have to be the same gesture that later triggers a sound, so doing
    // this once up front means playMessageChime/startRingtone can fire later from an
    // async WS event (no gesture of their own) and still be audible.
    installSoundUnlock() {
        const unlock = () => {
            if (this.sound.unlocked) return;
            const AudioCtx = window.AudioContext || window.webkitAudioContext;
            if (!AudioCtx) return;
            try {
                this.sound.ctx = this.sound.ctx || new AudioCtx();
                this.sound.ctx.resume?.().catch(() => {});
                this.sound.unlocked = true;
            } catch (e) {}
            document.removeEventListener('click', unlock, true);
            document.removeEventListener('keydown', unlock, true);
            document.removeEventListener('touchstart', unlock, true);
        };
        document.addEventListener('click', unlock, true);
        document.addEventListener('keydown', unlock, true);
        document.addEventListener('touchstart', unlock, true);
    }

    ensureSoundContext() {
        const AudioCtx = window.AudioContext || window.webkitAudioContext;
        if (!AudioCtx) return null;
        if (!this.sound.ctx || this.sound.ctx.state === 'closed') {
            this.sound.ctx = new AudioCtx();
            this.sound.bus = null;
        }
        if (this.sound.ctx.state === 'suspended') {
            this.sound.ctx.resume?.().catch(() => {});
        }
        return this.sound.ctx;
    }

    // Shared output bus: master gain → compressor → destination. The compressor
    // is what makes these sounds actually loud — summed partials peak well past
    // 0 dBFS otherwise, and simply lowering per-voice gain to avoid that (what
    // the first version did) is exactly why they came out quiet and thin. Here
    // the peaks get tamed instead, so average level can sit much higher.
    soundBus(ctx) {
        if (this.sound.bus && this.sound.bus.ctx === ctx) return this.sound.bus.input;
        const master = ctx.createGain();
        master.gain.value = 0.9;
        const compressor = ctx.createDynamicsCompressor();
        compressor.threshold.setValueAtTime(-18, ctx.currentTime);
        compressor.knee.setValueAtTime(20, ctx.currentTime);
        compressor.ratio.setValueAtTime(6, ctx.currentTime);
        compressor.attack.setValueAtTime(0.003, ctx.currentTime);
        compressor.release.setValueAtTime(0.25, ctx.currentTime);
        master.connect(compressor);
        compressor.connect(ctx.destination);
        this.sound.bus = { ctx, input: master };
        return master;
    }

    // One struck-bell/marimba note built additively: a set of partials above the
    // fundamental, each with its own level and its own (shorter) decay, under a
    // lowpass that closes as the note rings out. That per-partial decay is what
    // reads as a real struck instrument — the highs die away first, leaving the
    // fundamental humming. Envelopes are exponential (not linear) because
    // amplitude decay is perceived logarithmically; a linear fade sounds like a
    // synthetic bleep cut short, which was the other half of the "плохие звуки".
    playBellVoice(ctx, { frequency, startTime, duration, gain = 0.3, partials, brightness = 7 }) {
        const bus = this.soundBus(ctx);
        const voice = ctx.createGain();
        voice.gain.value = gain;
        const filter = ctx.createBiquadFilter();
        filter.type = 'lowpass';
        filter.Q.value = 0.7;
        filter.frequency.setValueAtTime(Math.min(frequency * brightness, 14000), startTime);
        filter.frequency.exponentialRampToValueAtTime(
            Math.max(frequency * 1.6, 300),
            startTime + duration
        );
        voice.connect(filter);
        filter.connect(bus);

        const voicePartials = partials || [
            { ratio: 1, gain: 1, decay: 1 },
            { ratio: 2, gain: 0.42, decay: 0.62 },
            { ratio: 3, gain: 0.2, decay: 0.42 },
            { ratio: 4.16, gain: 0.11, decay: 0.28 },
            { ratio: 5.43, gain: 0.05, decay: 0.19 },
        ];
        for (const partial of voicePartials) {
            const osc = ctx.createOscillator();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(frequency * partial.ratio, startTime);
            const env = ctx.createGain();
            const partialDuration = Math.max(duration * partial.decay, 0.05);
            // exponentialRampToValueAtTime can't touch zero, hence the epsilons.
            env.gain.setValueAtTime(0.0001, startTime);
            env.gain.exponentialRampToValueAtTime(partial.gain, startTime + 0.006);
            env.gain.exponentialRampToValueAtTime(0.0001, startTime + partialDuration);
            osc.connect(env);
            env.connect(voice);
            osc.start(startTime);
            osc.stop(startTime + partialDuration + 0.05);
        }
    }

    // Incoming message: a warm two-note rise (B5 → E6, a perfect fourth). Rising
    // intervals read as "new/arrived"; falling ones read as dismissal or error.
    // Synthesized (no audio asset) so it ships to every platform — macOS,
    // Windows, Android, browser — through bundle_web.py with nothing to bundle.
    playMessageChime() {
        const ctx = this.ensureSoundContext();
        if (!ctx) return;
        const now = ctx.currentTime + 0.02;
        this.playBellVoice(ctx, { frequency: 987.77, startTime: now, duration: 0.55, gain: 0.38 });
        this.playBellVoice(ctx, { frequency: 1318.51, startTime: now + 0.11, duration: 0.9, gain: 0.34 });
    }

    // Looping ringtone for an incoming call — started/stopped from the single
    // choke point renderVoicePanel() based on this.voice.status, so it tracks
    // every way a call stops ringing (answered, declined, missed, caller hung up)
    // without needing to be threaded into each of those call sites separately.
    //
    // Musical phrase (an E-major arpeggio played twice) rather than the usual
    // two-tone warble: it stays recognizable at low volume and doesn't turn
    // grating on the tenth repeat, while the silence between phrases is what
    // actually makes a ringtone read as urgent.
    startRingtone() {
        if (this.sound.ringing) return;
        const ctx = this.ensureSoundContext();
        if (!ctx) return;
        this.sound.ringing = true;
        const phrase = () => {
            if (!this.sound.ringing) return;
            const liveCtx = this.ensureSoundContext();
            if (!liveCtx) return;
            const now = liveCtx.currentTime + 0.02;
            const notes = [659.25, 987.77, 1318.51, 987.77]; // E5 B5 E6 B5
            for (const passOffset of [0, 0.78]) {
                notes.forEach((frequency, index) => {
                    this.playBellVoice(liveCtx, {
                        frequency,
                        startTime: now + passOffset + index * 0.15,
                        duration: 0.7,
                        gain: 0.4,
                        brightness: 8,
                    });
                });
            }
        };
        phrase();
        // Phrase runs ~1.8 s; a 3 s period leaves the ~1.2 s gap that makes it
        // sound like a phone ringing rather than a continuous alarm.
        this.sound.ringTimer = setInterval(phrase, 3000);
    }

    stopRingtone() {
        this.sound.ringing = false;
        if (this.sound.ringTimer) {
            clearInterval(this.sound.ringTimer);
            this.sound.ringTimer = null;
        }
    }

    // Single choke point for "a message arrived in a chat the user isn't currently
    // looking at". Both the live WS push path AND the reconnect / background
    // history-catch-up paths (loadHistory, mergeServerChatMessages) route through
    // here — those catch-up paths used to update S.chats/S.serverChats silently with
    // no notification and no unread badge, which was the root cause of notifications
    // being rare and arriving with a huge delay: most messages land via catch-up
    // after a WS drop, not via the live push that used to be the only notify trigger.
    notifyBackgroundMessage({ sender, text, attachmentCount = 0, serverId = null, channelId = null, peer = null }) {
        const from = String(sender || '').trim();
        if (!from || from === this.myName()) return;
        const isChannel = !!(serverId && channelId);
        const muteKey = isChannel ? `${serverId}:${channelId}` : String(peer || '').trim();
        if (!muteKey) return;
        if (isChannel) {
            this.S.channelUnread = this.S.channelUnread || {};
            this.S.channelUnread[muteKey] = (this.S.channelUnread[muteKey] || 0) + 1;
        } else {
            this.S.unread[muteKey] = (this.S.unread[muteKey] || 0) + 1;
        }
        this.syncTaskbarBadge();
        if ((this.S.mutedChats || {})[muteKey]) return;
        // Native OS notifications (UNUserNotificationCenter / toast / Android
        // channel) already carry their own default sound when granted — but that
        // depends on OS-level permission the user may never have granted, and the
        // browser/PWA client (no native bridge at all) gets no sound whatsoever
        // from postNativeMessage below. This chime is unconditional so a message
        // is always audible while its chat isn't the one on screen, independent
        // of native notification permission state, including when the window is
        // minimized or not frontmost (see playMessageChime).
        this.playMessageChime();
        this.postNativeMessage({
            type: NativeMessageTypes.SHOW_NOTIFICATION,
            sender: from,
            text,
            attachmentCount,
            serverId: serverId || null,
            channelId: channelId || null,
        });
        this.showBrowserNotification({
            sender: from,
            text,
            attachmentCount,
            serverId,
            channelId,
        });
    }

    // Mirror of the native shells' notification_body (apps/windows/src/native/transport.rs,
    // and the same precedence on macOS): message text wins, then an attachment count,
    // then a generic fallback.
    notificationBodyFor(text, attachmentCount = 0) {
        const trimmed = String(text || '').trim();
        if (trimmed) return Array.from(trimmed).slice(0, 180).join('');
        if (attachmentCount === 1) return 'Вложение';
        if (attachmentCount > 1) return `Вложения: ${attachmentCount}`;
        return 'Новое сообщение';
    }

    // Browser/PWA only — the one notification path nothing else covered.
    // postNativeMessage(SHOW_NOTIFICATION) above returns false immediately when there
    // is no native bridge, and the server only sends a Web Push when deliver_to_user
    // finds ZERO live WS connections. A tab that is merely *hidden* (backgrounded,
    // minimized, screen locked) has a live WS, so it fell straight through the gap
    // between the two and produced no notification at all — just the chime, which
    // browsers throttle in background tabs anyway.
    //
    // Only fires while the document is hidden: with the app actually on screen the
    // in-app unread badges already cover it. Notifications are tagged per conversation
    // with renotify, so a long-backgrounded tab alerts on each message without piling
    // up one entry per message in the OS notification centre.
    showBrowserNotification({ sender, text, attachmentCount = 0, serverId = null, channelId = null }) {
        if (this.hasNativeBridge()) return;
        if (typeof Notification === 'undefined' || Notification.permission !== 'granted') return;
        if (typeof document !== 'undefined' && document.visibilityState !== 'hidden') return;

        const from = String(sender || '').trim();
        if (!from) return;
        const isChannel = !!(serverId && channelId);
        const title = isChannel ? `${from} в канале` : from;
        const options = {
            body: this.notificationBodyFor(text, attachmentCount),
            icon: './icon-192.png',
            badge: './icon-192.png',
            tag: isChannel ? `zali:${serverId}:${channelId}` : `zali:dm:${from}`,
            renotify: true,
            data: { sender: from, serverId: serverId || null, channelId: channelId || null },
        };

        try {
            // registration.showNotification() rather than `new Notification()`: the
            // latter throws on Android Chrome, where only the service-worker form is
            // allowed, and it is also what the installed PWA needs.
            if (navigator.serviceWorker?.ready) {
                navigator.serviceWorker.ready
                    .then(registration => registration.showNotification(title, options))
                    .catch(e => this.trace(`showBrowserNotification failed: ${e?.message || e}`));
            } else {
                new Notification(title, options);
            }
        } catch (e) {
            this.trace(`showBrowserNotification failed: ${e?.message || e}`);
        }
    }

    // Total unread count across DMs and server channels — feeds the Windows
    // taskbar overlay badge (see syncTaskbarBadge). Mirrors the per-surface sums
    // already used by renderHub()/renderServers() for their own badges.
    computeTotalUnreadCount() {
        const dmTotal = Object.values(this.S.unread || {}).reduce((sum, value) => sum + Number(value || 0), 0);
        const channelTotal = Object.values(this.S.channelUnread || {}).reduce((sum, value) => sum + Number(value || 0), 0);
        return dmTotal + channelTotal;
    }

    syncTaskbarBadge() {
        if (!this.nativeSupports('taskbarBadge')) return;
        this.postNativeMessage({
            type: NativeMessageTypes.SET_UNREAD_BADGE,
            count: this.computeTotalUnreadCount(),
        });
    }

    // The set of statuses that mean "a call is live and must not be clobbered". Both the
    // incoming-invite busy-guard and the foreign-room-state guard key off this exact set;
    // inlining it twice risks one copy going stale and silently re-opening the
    // active-call-clobber bug.
    // Rooms this client deliberately walked away from (invite glare). Events for
    // them are already in flight when we leave, and applying those would restore
    // state for a call that no longer exists. Bounded: a handful per session.
    abandonVoiceRoom(roomId) {
        const id = String(roomId || '').trim();
        if (!id) return;
        if (!this._abandonedVoiceRooms) this._abandonedVoiceRooms = new Set();
        this._abandonedVoiceRooms.add(id);
        if (this._abandonedVoiceRooms.size > 32) {
            this._abandonedVoiceRooms.delete(this._abandonedVoiceRooms.values().next().value);
        }
    }

    isAbandonedVoiceRoom(roomId) {
        const id = String(roomId || '').trim();
        return !!id && !!this._abandonedVoiceRooms?.has(id);
    }

    isInActiveCall(status = this.voice?.status) {
        return ['connected', 'connecting', 'calling', 'incoming'].includes(String(status || ''));
    }
});


// --- MODULE: interface/state_sync.js ---
// --- ZaliInterface: Приём состояния от нативного слоя: пользователи, история, статус связи. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    // Fills the attachment bytes back into a locally cached copy of a message you
    // sent yourself.
    //
    // Reconciling your own message (finalizePendingMessage) matches it by
    // clientId and stops — right for everything except the payload. After a
    // reload the local copy has the attachment's name, size and type but no
    // bytes: a browser tab never had anything to persist (a blob: URL dies with
    // the page), and a native shell can be running the payload-free cache. The
    // history row being reconciled against was just downloaded, unpacked and
    // re-blobbed — it IS the repair, and discarding it left your own photos as
    // name-only chips for good.
    //
    // Only ever fills a gap: a local copy that already has its bytes is left
    // alone, so this can never replace a payload with a different one.
    adoptAttachmentPayloads(store, { msgId = '', clientId = '', attachments = [] } = {}) {
        if (!Array.isArray(store) || !store.length) return false;
        if (!attachments.length || !attachments.some(att => att.dataUrl)) return false;
        const id = String(msgId || '').trim();
        const cid = String(clientId || '').trim();
        const index = store.findIndex(m => (id && String(m.id || '').trim() === id)
            || (cid && String(m.clientId || '').trim() === cid));
        if (index < 0) return false;
        const local = this.normalizeAttachments(store[index].attachments);
        if (!local.length || local.some(att => att.dataUrl)) return false;
        store[index] = { ...store[index], attachments };
        return true;
    }

    /**
     * Единый маршрутизатор WS-событий, общий для браузера и нативных оболочек.
     *
     * Зачем он вообще: раньше каждый новый тип события с сервера приходилось
     * вписывать в четыре места — в ветку onmessage браузера и в аллоулисты
     * macOS/Windows/Android. Пропустить одно из них ничего не стоило, и ровно
     * так фичи «выходили на десктопе и молча минова́ли Android». Теперь оболочка
     * отдаёт нераспознанный кадр как есть (window.receiveRealtimeEvent), а
     * решает, что с ним делать, только этот метод.
     *
     * Неизвестный тип молча игнорируется — это и есть требуемое поведение для
     * старого клиента, которому прилетело событие из более новой версии сервера.
     *
     * @returns {boolean} true, если событие распознано и обработано.
     */
    dispatchRealtimeEvent(payload) {
        if (!payload || typeof payload !== 'object') return false;
        const type = String(payload.type || '').trim();
        if (!type) return false;

        if (type === 'titlebar_announcement') {
            this.showTitlebarAnnouncement(payload);
            return true;
        }

        if (ZaliInterface.PROFILE_EVENT_TYPES.includes(type)) {
            // На нативе живут ДВА сокета (сообщения и голос), и сервер шлёт
            // событие в каждое соединение аккаунта. Голосовой сокет пропускает
            // только voice_*, так что дублей быть не должно — но реконнект с
            // повтором кадра стоил бы человеку двух одинаковых уведомлений,
            // поэтому проверка всё равно дешевле, чем разбирательство потом.
            if (this.isDuplicateRealtimeEvent(type, payload)) return true;
            this.handleProfileEvent(payload);
            return true;
        }

        this.trace(`realtime event ignored type=${type}`);
        return false;
    }

    /**
     * Окно подавления повторов — 10 секунд по (тип + идентификатор события).
     * У части событий своего id нет (profile_follow), для них ключом служит
     * отправитель: два разных подписчика за одну секунду — случай, которого в
     * жизни не бывает, а вот один и тот же кадр дважды — бывает.
     */
    isDuplicateRealtimeEvent(type, payload) {
        const key = `${type}:${payload?.id || ''}:${payload?.from || ''}:${payload?.wall || ''}`;
        const now = this.nowMs();
        if (!this._realtimeEventSeen) this._realtimeEventSeen = new Map();
        const seen = this._realtimeEventSeen;
        const previous = seen.get(key);
        if (previous && now - previous < 10000) return true;
        seen.set(key, now);
        // Чистка тут же, по месту: без неё Map рос бы всю сессию.
        if (seen.size > 200) {
            for (const [oldKey, ts] of seen) {
                if (now - ts >= 10000) seen.delete(oldKey);
            }
        }
        return false;
    }

    /**
     * Показывает объявление сервера в титлбаре вместо бренда/имени чата —
     * см. server/src/realtime.rs::publish_announcement (POST /api/announcement,
     * тот же RELEASE_ADMIN_TOKEN, что и у /api/version) и dispatchRealtimeEvent
     * выше. Живёт только на этом устройстве и только пока открыта вкладка:
     * сервер не хранит состояние «показано/скрыто по крестику», рассылка
     * чисто разовая — новый коннект после неё объявления уже не увидит.
     */
    showTitlebarAnnouncement(payload) {
        const text = String(payload?.text || '').trim();
        if (!text) return;
        const titlebar = document.getElementById('titlebar');
        const textEl = document.getElementById('tbAnnounceText');
        if (!titlebar || !textEl) return;
        textEl.textContent = text;
        document.getElementById('tbAnnounce')?.removeAttribute('hidden');
        titlebar.classList.add('has-announcement');
    }

    /** Крестик у объявления — прячет его локально, .tb-chat/.tb-brand возвращаются. */
    hideTitlebarAnnouncement() {
        document.getElementById('titlebar')?.classList.remove('has-announcement');
        document.getElementById('tbAnnounce')?.setAttribute('hidden', '');
    }

    setUsers(users) {
        this.S.users = Array.isArray(users) ? users : [];
        this.S.users.forEach(contact => this.initChat(contact));
        const others = this.S.users.filter(contact => contact !== this.myName());
        if (this.S.navMode !== 'servers' && !this.S.current && this.S.contacts.length > 0) this.switchChat(this.S.contacts[0]);
        this.trace(`setUsers count=${this.S.users.length} others=${others.join(',')}`);
        this.addLogEntry({ type: 'INFO', msg: `Загружен список пользователей: ${others.join(', ')}`, ts: new Date().toLocaleTimeString() });
        this.renderContactSuggestions();
    }

    setContacts(contacts) {
        const me = this.myName();
        const remoteContacts = Array.isArray(contacts) ? contacts.filter(Boolean) : [];
        const localContacts = this.localConversationContacts();
        this.S.contacts = Array.from(new Set([...remoteContacts, ...localContacts]))
            .filter(contact => contact !== me);
        this.saveStoredContacts(this.S.contacts);
        this.S.contacts.forEach(contact => this.initChat(contact));
        this.trace(`setContacts count=${this.S.contacts.length} me=${me} contacts=${this.S.contacts.join(',')}`);
        if (this.S.navMode !== 'servers') {
            const storedCurrent = this.loadStoredCurrentContact();
            const currentValid = !!(this.S.current && this.S.contacts.includes(this.S.current));
            const storedValid = !!(storedCurrent && this.S.contacts.includes(storedCurrent));

            if (storedValid && (!currentValid || this.S.current !== storedCurrent)) {
                this.switchChat(storedCurrent);
            } else if (currentValid) {
                this.scheduleRenderMessages();
                this.renderContacts();
            } else if (this.S.contacts.length > 0) {
                this.switchChat(this.S.contacts[0]);
            } else {
                this.S.current = null;
                this.saveStoredCurrentContact(null);
                const set = (id, v) => { const e = document.getElementById(id); if(e) e.textContent = v; };
                set('tbChat', 'Нет контактов');
                // Render the user's own avatar here (same as renderServerToolbar's empty
                // state) rather than hard-coding the fallback letter — otherwise this
                // clobbers the just-loaded avatar image and it flashes then disappears.
                const avaEl = document.getElementById('chatHdrAva');
                if (avaEl) avaEl.innerHTML = this.renderAvatarHTML(this.myName(), 'avatar-img', this.myName());
                set('chatHdrName', 'Добавьте контакт');
            }
            if (this.S.current) {
                this.ensureConversationCryptoKey({ peer: this.S.current, reason: 'setContacts' });
                this.syncActiveConversation({ force: true });
            }
        }
        this.renderContacts();
        this.scheduleRenderMessages();
        this.renderContactSuggestions();
    }

    setSession(session) {
        if (!session || typeof session !== 'object') return;
        this.applySession({
            username: session.username || '',
            token: session.token || null,
            guest: !!session.guest || !session.token,
        }, { persist: false, syncNative: false });
        this.loadContacts();
        this.loadUsers();
        this.loadServers({ silent: true });
        this.renderContactSuggestions();
        this.refreshAfterKey();
    }

    loadHistory(messages) {
        const queue = Array.isArray(messages) ? messages.filter(msg => msg && typeof msg === 'object') : [];
        const seq = ++this.historyLoadSeq;
        const sidebarBefore = this.dmSidebarSignature();
        const activeMessagesBefore = this.activeMessagesSignature();
        const currentBefore = this.S.current;
        this.trace(`loadHistory count=${queue.length}`);
        this.addLogEntry({ type: 'INFO', msg: `Загрузка истории чата: ${queue.length} сообщений`, ts: new Date().toLocaleTimeString() });
        const touchedPeers = new Set();
        // Snapshot taken once for the whole call (not re-checked per message): a
        // peer's first-ever loadHistory batch can span many messages across several
        // requestAnimationFrame slices, and re-checking _historyPrimedPeers per
        // message would treat everything after the first message of a brand new
        // peer as "already primed" and notify for the rest of that same initial load.
        const peersPrimedBeforeThisCall = new Set(this._historyPrimedPeers);
        const processBatch = (startIndex = 0) => {
            if (seq !== this.historyLoadSeq) {
                this.trace(`loadHistory stale seq=${seq} current=${this.historyLoadSeq}`);
                return;
            }
            const startedAt = performance.now();
            let index = startIndex;
            for (; index < queue.length; index += 1) {
                if ((index - startIndex) >= 120) break;
                if ((performance.now() - startedAt) >= 8) break;
                const msg = queue[index];
                const peer = msg.kind === 'call'
                    ? String(msg.call?.peer || msg.receiver || msg.sender || '').trim()
                    : (msg.sender === this.myName() ? msg.receiver : msg.sender);
                if (!peer) continue;
                touchedPeers.add(peer);
                const peerAlreadyPrimed = peersPrimedBeforeThisCall.has(peer);
                this._historyPrimedPeers.add(peer);
                this.ensureContact(peer);
                this.initChat(peer);
                const arr = this.S.chats[peer];
                const normalizedAttachments = this.normalizeAttachments(msg.attachments);
                const normalizedReactions = this.normalizeReactions(msg.reactions);
                const msgId = String(msg.id || '').trim();
                const clientId = String(msg.clientId || msg.client_id || '').trim();
                if (clientId && this.finalizePendingMessage(clientId, msgId, { render: false })) {
                    this.dropPendingOutbox(clientId);
                    this.adoptAttachmentPayloads(arr, { msgId, clientId, attachments: normalizedAttachments });
                    this.markMessageSeen(msg);
                    continue;
                }
                const incoming = {
                    ...msg,
                    attachments: normalizedAttachments,
                    reactions: normalizedReactions,
                    myReactions: this.normalizeMyReactions(msg.myReactions),
                    text: this.sanitizeDecryptionErrorText(msg.text),
                };
                const incomingKey = this.messageRenderKey(incoming);
                const existingIndex = msgId
                    ? arr.findIndex(m => String(m.id || '').trim() === msgId)
                    : arr.findIndex(m => this.messageRenderKey(m) === incomingKey);
                if (existingIndex >= 0) {
                    const prev = arr[existingIndex];
                    arr[existingIndex] = {
                        ...prev,
                        ...msg,
                        id: msgId || msg.id || prev.id || '',
                        attachments: normalizedAttachments.length ? normalizedAttachments : this.normalizeAttachments(prev.attachments),
                        reactions: normalizedReactions.length ? normalizedReactions : this.normalizeReactions(prev.reactions),
                        myReactions: this.normalizeMyReactions(msg.myReactions?.length ? msg.myReactions : prev.myReactions),
                        text: this.sanitizeDecryptionErrorText(msg.text) || prev.text || '',
                        status: 'sent'
                    };
                } else {
                    arr.push({
                        ...msg,
                        id: msgId || msg.id || '',
                        attachments: normalizedAttachments,
                        reactions: normalizedReactions,
                        myReactions: this.normalizeMyReactions(msg.myReactions),
                        text: this.sanitizeDecryptionErrorText(msg.text),
                        status: 'sent'
                    });
                    // Catch-up sweeps (reconnect, background contact refresh) land here
                    // too, not just the live WS push — this is the root fix for
                    // notifications that used to silently vanish whenever a message
                    // arrived while the socket was down. Skip the peer's very first
                    // sync this session (peerAlreadyPrimed=false) so opening a chat
                    // with existing history doesn't replay it as a notification flood.
                    if (peerAlreadyPrimed && msg.kind !== 'call' && !this.isDmChatVisible(peer)) {
                        this.notifyBackgroundMessage({
                            sender: msg.sender,
                            text: this.sanitizeDecryptionErrorText(msg.text),
                            attachmentCount: normalizedAttachments.length,
                            peer,
                        });
                    }
                }
                this.markMessageSeen(msg);
            }
            if (index < queue.length) {
                requestAnimationFrame(() => processBatch(index));
                return;
            }
            touchedPeers.forEach(peer => {
                const arr = this.S.chats[peer];
                if (Array.isArray(arr)) {
                    arr.sort((a, b) => this.compareMessagesByTime(a, b));
                }
            });
            this.normalizeDmChatStore();
            this.saveStoredMessageCache();
            if (this.S.navMode !== 'servers') {
                const storedCurrent = this.loadStoredCurrentContact();
                const pendingPeers = this.loadPendingOutbox()
                    .filter(item => String(item?.sender || '').trim() === this.myName())
                    .map(item => String(item?.receiver || '').trim())
                    .filter(Boolean);
                const preferredPeer = (() => {
                    if (storedCurrent && (this.S.chats[storedCurrent] || []).length) return storedCurrent;
                    for (let i = pendingPeers.length - 1; i >= 0; i -= 1) {
                        const peer = pendingPeers[i];
                        if ((this.S.chats[peer] || []).length) return peer;
                    }
                    const populated = Object.entries(this.S.chats)
                        .filter(([, msgs]) => Array.isArray(msgs) && msgs.length > 0)
                        .sort((a, b) => this.messageTimestampValue(b[1][b[1].length - 1]?.timestamp) - this.messageTimestampValue(a[1][a[1].length - 1]?.timestamp));
                    return populated[0]?.[0] || null;
                })();

                if (!this.S.current && preferredPeer && preferredPeer !== this.S.current) {
                    this.switchChat(preferredPeer);
                }
            }
            const sidebarAfter = this.dmSidebarSignature();
            const activeMessagesAfter = this.activeMessagesSignature();
            const currentChanged = currentBefore !== this.S.current;
            const sidebarChanged = sidebarBefore !== sidebarAfter;
            const activeMessagesChanged = activeMessagesBefore !== activeMessagesAfter || currentChanged;
            if (activeMessagesChanged) {
                this.scheduleRenderMessages();
            }
            if (sidebarChanged) {
                this.renderContacts();
            }
            if (!this.S.current && this.S.contacts.length > 0) {
                this.switchChat(this.S.contacts[0]);
            }
            this.scheduleFlushPendingOutbox(300);
            this.trace(`loadHistory done current=${this.S.current || 'none'} chats=${Object.keys(this.S.chats).length}`);
        };
        processBatch(0);
    }

    setLoading(on) {
        this.S.loading = !!on;
        this.scheduleRenderMessages();
    }

    setConnectionStatus(connected) {
        const wasOn = !!this.S.wsOn;
        this.S.wsOn = !!connected;
        const pill = document.getElementById('wsPill');
        const lbl  = document.getElementById('wsLabel');
        if (pill) pill.className = 'ws-pill' + (connected ? ' on' : '');
        if (lbl)  lbl.textContent = connected ? 'Подключено' : 'Переподключение...';
        // Body-level flag so the mobile shell can surface a slim reconnect strip
        // (the desktop #wsPill is hidden on mobile). Only marks "not connected"
        // once a first status has arrived, so the strip doesn't flash on boot.
        document.body?.classList.toggle('ws-offline', !connected);
        this.addLogEntry({ type: connected ? 'SUCCESS' : 'WARN', msg: connected ? 'WebSocket соединение установлено' : 'WebSocket соединение разорвано', ts: new Date().toLocaleTimeString() });
        if (connected) {
            // Connection (re)established — drain the outbox immediately instead of
            // waiting out each message's retry backoff (which grows up to 30s). This
            // was the cause of the long send delay after an account switch / blip.
            this.kickPendingOutboxNow('reconnect');
            // Don't wait out the keepalive tick to get back into the voice room: if
            // the blip outlasted the server's 12 s eviction window we are already out
            // of it, and every second here is a second of one-sided silence.
            if (!wasOn) this.sendVoiceRoomPresence();
            // The server only PUSHES messages in real time; anything that arrived
            // while we were offline is never re-sent. So on (re)connect we must pull
            // the active conversation to catch up — otherwise a message sent while the
            // recipient was disconnected is confirmed on the sender but never shows
            // here. Debounced so WS flapping collapses into a single refresh.
            if (!wasOn || !this._reconnectCaughtUp) {
                this._reconnectCaughtUp = true;
                if (this._reconnectRefreshTimer) clearTimeout(this._reconnectRefreshTimer);
                this._reconnectRefreshTimer = setTimeout(() => {
                    this._reconnectRefreshTimer = null;
                    void this.syncActiveConversation({ force: true });
                    // Only the ACTIVE conversation was ever caught up above — a message
                    // sent to any OTHER contact while we were offline had nothing pulling
                    // it in: no WS push (we were offline when it fired) and no history
                    // refresh (only the open chat gets one). It sat on the server
                    // forever, invisible, until the user happened to click that exact
                    // contact — which also explains "contact doesn't appear when someone
                    // writes to you first" for a brand-new sender. Confirmed live
                    // 2026-07-04: a message server-confirmed as delivered to test1 never
                    // reached test3 across a reconnect because test3's client never had
                    // that DM open. Catch up every other known contact too, same as the
                    // active one; loadHistory() is peer-generic (ensureContact + merge
                    // into S.chats[peer]) so this is safe for any contact, not just the
                    // open one.
                    // Throttle the full-sweep catch-ups: each walks every contact and
                    // every channel of every server with sequential history refreshes.
                    // On a flaky link that flaps repeatedly, running the whole sweep on
                    // every reconnect saturates the connection pool ("чат не грузит").
                    // At most once per window is enough to catch up missed history.
                    const catchUpNow = Date.now();
                    if (catchUpNow - (this._lastReconnectCatchUpAt || 0) >= 20000) {
                        this._lastReconnectCatchUpAt = catchUpNow;
                        void this.catchUpBackgroundContactsAfterReconnect();
                        // Same class of bug as the DM catch-up above, for server channels:
                        // deliver_server_message (src/main.rs) only pushes to currently
                        // connected viewers via WS — a channel message posted while this
                        // client was offline, or simply in a channel/server you weren't
                        // looking at, has nothing pulling it in afterwards. Only the
                        // actively open channel got a history refresh; every other channel
                        // in every other server the user belongs to stayed stale until
                        // manually clicked.
                        void this.catchUpBackgroundChannelsAfterReconnect();
                    }
                }, 500);
            }
        } else {
            this._reconnectCaughtUp = false;
        }
    }

    async catchUpBackgroundContactsAfterReconnect() {
        if (!this.S.session?.token) return;
        // this.S.contacts may still be empty here: bootstrapSession's own loadContacts()
        // is an independent async call racing against this reconnect timer, and on a
        // fresh launch/reconnect right after login it hadn't necessarily resolved yet —
        // an empty list made this whole catch-up silently iterate zero peers. Refresh
        // it ourselves first so the contact list is authoritative regardless of timing.
        await this.loadContacts();
        const activePeer = String(this.S.current || '').trim();
        const peers = (this.S.contacts || []).filter(peer => peer && peer !== activePeer);
        for (const peer of peers) {
            try {
                const key = await this.resolveConversationCryptoKey({ peer, reason: 'reconnectCatchUp' });
                // Browser/PWA has no native shell to service REFRESH_HISTORY, so this
                // whole catch-up used to be gated off for it: after a WS drop, chats
                // other than the open one never re-synced, leaving their sidebar preview
                // and unread badge stuck on pre-disconnect state until you clicked in.
                if (this.nativeSupports('sendMessage')) {
                    this.postNativeMessage({ type: NativeMessageTypes.REFRESH_HISTORY, key, peer });
                } else {
                    await this.loadBrowserDmHistory(peer, key);
                }
            } catch (e) {
                this.trace(`catchUpBackgroundContactsAfterReconnect failed peer=${peer} error=${e?.message || e}`);
            }
        }
    }

    async catchUpBackgroundChannelsAfterReconnect() {
        if (!this.S.session?.token) return;
        // Same staleness-on-launch race as loadContacts() above: refresh the server
        // list ourselves rather than trusting whatever bootstrapSession's independent
        // loadServers() call has resolved by now.
        await this.loadServers({ silent: true });
        const activeServer = String(this.S.activeServer || '').trim();
        const activeChannel = String(this.S.activeChannel || '').trim();
        for (const server of this.S.servers || []) {
            const sid = String(server?.id || '').trim();
            if (!sid) continue;
            for (const channel of server.channels || []) {
                const cid = String(channel?.id || '').trim();
                if (!cid || this.isVoiceChannel(channel)) continue;
                if (sid === activeServer && cid === activeChannel) continue;
                try {
                    await this.loadServerMessages(sid, cid, { silent: true });
                } catch (e) {
                    this.trace(`catchUpBackgroundChannelsAfterReconnect failed server=${sid} channel=${cid} error=${e?.message || e}`);
                }
            }
        }
    }

    kickPendingOutboxNow(reason = 'manual') {
        const pending = this.loadPendingOutbox();
        if (!pending.length) return;
        const now = Date.now();
        let changed = false;
        for (const item of pending) {
            if (!item || typeof item !== 'object') continue;
            // Any in-flight request was tied to the old connection and is now dead;
            // clear it and the backoff so the item is sent right away. The server
            // deduplicates by client_id, so an accidental resend is harmless.
            if (item.inFlight || Number(item.nextRetryAt || 0) > now) {
                item.inFlight = false;
                item.nextRetryAt = 0;
                changed = true;
            }
        }
        if (changed) this.savePendingOutbox(pending);
        this.trace(`kickPendingOutboxNow reason=${reason} count=${pending.length}`);
        this.scheduleFlushPendingOutbox(50);
    }

    onSendSuccess(payload) {
        if (payload && typeof payload === 'object') {
            this.trace(`onSendSuccess clientId=${String(payload.clientId || '').trim()} messageId=${String(payload.messageId || '').trim()}`);
            this.finalizePendingMessage(payload.clientId, payload.messageId);
            this.dropPendingOutbox(payload.clientId);
        } else {
            this.trace(`onSendSuccess payload=${String(payload || '').trim()}`);
            this.markMessageStatus(payload, 'sent');
            this.dropPendingOutbox(payload);
        }
        this.addLogEntry({ type: 'SUCCESS', msg: 'Сообщение подтверждено сервером', ts: new Date().toLocaleTimeString() });
    }

    onSendError(payload) {
        const clientId = String(payload?.clientId || payload || '').trim();
        const statusCode = Number(payload?.statusCode || 0);
        const responseBody = String(payload?.responseBody || '').trim();
        const permanentError = statusCode >= 400 && statusCode < 500;
"""#,
    #"""
        this.trace(`onSendError clientId=${clientId} status=${statusCode || 'n/a'} body=${responseBody.slice(0, 120)}`);
        if (clientId) {
            if (permanentError) {
                this.markMessageStatus(clientId, 'error');
                this.dropPendingOutbox(clientId);
            } else {
                this.markMessageStatus(clientId, 'sending');
                this.updatePendingOutboxItem(clientId, {
                    inFlight: false,
                    nextRetryAt: Date.now() + 2000,
                });
                this.scheduleFlushPendingOutbox(2000);
            }
        } else if (!permanentError) {
            this.scheduleFlushPendingOutbox(2000);
        }
        const networkError = !statusCode || statusCode <= 0;
        this.addLogEntry({
            type: permanentError ? 'ERROR' : 'WARN',
            msg: permanentError
                ? 'Сообщение отклонено сервером без ретрая'
                : (networkError
                    ? 'Сбой сети при отправке, повтор автоматически'
                    : 'Сервер временно недоступен, повтор отправки'),
            ts: new Date().toLocaleTimeString()
        });
    }

    onReactionUpdated(payload) {
        if (!payload || typeof payload !== 'object') return;
        const messageId = String(payload.messageId || payload.message_id || '').trim();
        if (!messageId) return;

        const normalizedReactions = this.normalizeReactions(payload.reactions);
        const normalizedMyReactions = this.normalizeMyReactions(payload.myReactions || payload.my_reactions);
        let updated = false;

        const applyToList = (list) => {
            if (!Array.isArray(list)) return;
            for (const msg of list) {
                if (!msg || typeof msg !== 'object') continue;
                const sameId = String(msg.id || '').trim() === messageId;
                const sameClientId = String(msg.clientId || '').trim() === messageId;
                if (!sameId && !sameClientId) continue;
                msg.reactions = normalizedReactions;
                msg.myReactions = normalizedMyReactions;
                updated = true;
            }
        };

        for (const msgs of Object.values(this.S.chats || {})) {
            applyToList(msgs);
        }
        for (const msgs of Object.values(this.S.serverChats || {})) {
            applyToList(msgs);
        }

        if (updated) {
            this.scheduleSaveStoredMessageCache();
            const currentServerKey = this.currentServerChatKey();
            const currentPeer = String(this.S.current || '').trim();
            const payloadServerKey = String(payload.serverId || payload.server_id || '').trim() && String(payload.channelId || payload.channel_id || '').trim()
                ? `${String(payload.serverId || payload.server_id).trim()}:${String(payload.channelId || payload.channel_id).trim()}`
                : '';
            const shouldRender = payloadServerKey
                ? payloadServerKey === currentServerKey
                : currentPeer && (
                    currentPeer === String(payload.sender || '').trim() ||
                    currentPeer === String(payload.receiver || '').trim()
                );
            if (shouldRender) {
                this.scheduleRenderMessages();
            }
            return;
        }

        const serverId = String(payload.serverId || payload.server_id || '').trim();
        const channelId = String(payload.channelId || payload.channel_id || '').trim();
        const peer = String(payload.sender || payload.receiver || '').trim();
        if (serverId && channelId) {
            this.scheduleConversationRefresh({
                serverId,
                channelId,
                reason: 'reaction-miss',
                delayMs: 150,
            });
        } else if (peer) {
            this.scheduleConversationRefresh({
                peer,
                reason: 'reaction-miss',
                delayMs: 150,
            });
        }
    }

    // Whether the current user is allowed to delete `msg` — mirrors the
    // server's can_delete_message (server/src/messages.rs): always the
    // author, plus anyone with manage rights on the server a channel message
    // belongs to. The server is the actual authority (this only gates
    // whether the UI offers the button); a wrong "yes" here just means the
    // request 403s.
    canDeleteMessage(msg) {
        if (!msg) return false;
        if (String(msg.sender || '').trim() === this.myName()) return true;
        const serverId = String(msg.serverId || msg.server_id || '').trim();
        if (!serverId) return false;
        const server = (this.S.servers || []).find(s => s.id === serverId) || this.currentServer();
        return this.canManageServer(server);
    }

    // Removes a message from whichever bucket (DM or server chat) holds it and
    // re-renders only if that conversation is the one currently on screen.
    // Shared by the local "I just deleted this" path (deleteMessage) and the
    // message_deleted broadcast arriving for the peer/another device.
    removeMessageFromState(messageId) {
        const id = String(messageId || '').trim();
        if (!id) return false;
        const found = this.findMessageById(id);
        if (!found) return false;
        const list = found.serverKey ? this.S.serverChats[found.serverKey] : this.S.chats[found.peer];
        if (!Array.isArray(list)) return false;
        list.splice(found.index, 1);
        this.scheduleSaveStoredMessageCache();
        this.hideReactionMenu();
        const shouldRender = found.serverKey
            ? found.serverKey === this.currentServerChatKey()
            : found.peer === this.S.current;
        if (shouldRender) {
            this.scheduleRenderMessages();
        }
        return true;
    }

    onMessageDeleted(payload) {
        if (!payload || typeof payload !== 'object') return;
        const messageId = String(payload.messageId || payload.message_id || '').trim();
        if (!messageId) return;
        this.removeMessageFromState(messageId);
    }
});


// --- MODULE: interface/message_edit.js ---
// --- ZaliInterface: Ответы, редактирование и удаление сообщений. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    // ---- Reply quotes -------------------------------------------------
    //
    // A quote is a *snapshot* taken at send time and carried inside the
    // encrypted archive (MessageContent.reply in core/src/net.rs), not a
    // pointer resolved at render time. That is what lets a reply still show
    // what it answered after the original is deleted, edited, or simply scrolled
    // out of the loaded history window.

    /** Longest quote excerpt carried in an archive. */
    static get REPLY_QUOTE_MAX_CHARS() { return 280; }

    /** Builds the payload stored in the archive for a reply to `msg`. */
    buildReplyQuote(msg) {
        if (!msg || typeof msg !== 'object') return null;
        const id = String(msg.id || msg.clientId || '').trim();
        const sender = String(msg.sender || '').trim();
        if (!id || !sender) return null;
        const attachments = this.normalizeAttachments(msg.attachments);
        const text = String(msg.text || '').trim().slice(0, ZaliInterface.REPLY_QUOTE_MAX_CHARS);
        return { id, sender, text, attachmentCount: attachments.length };
    }

    /**
     * Parses the archive's `reply` field. Accepts an already-parsed object too,
     * because the local echo of our own outgoing message never round-trips
     * through JSON.
     */
    normalizeReplyQuote(value) {
        if (!value) return null;
        let parsed = value;
        if (typeof value === 'string') {
            const raw = value.trim();
            if (!raw) return null;
            try {
                parsed = JSON.parse(raw);
            } catch (e) {
                // A malformed quote must not take the whole bubble down with it.
                this.trace('normalizeReplyQuote invalid json');
                return null;
            }
        }
        if (!parsed || typeof parsed !== 'object') return null;
        const sender = String(parsed.sender || '').trim();
        if (!sender) return null;
        return {
            id: String(parsed.id || '').trim(),
            sender,
            text: String(parsed.text || '').slice(0, ZaliInterface.REPLY_QUOTE_MAX_CHARS),
            attachmentCount: Number(parsed.attachmentCount || 0) || 0,
        };
    }

    /** One-line preview of a quoted message, for both the bubble and the composer bar. */
    replyQuotePreview(quote) {
        const text = String(quote?.text || '').replace(/\s+/g, ' ').trim();
        if (text) return text;
        const count = Number(quote?.attachmentCount || 0) || 0;
        if (count > 0) return count === 1 ? 'Вложение' : `Вложения (${count})`;
        return 'Сообщение';
    }

    renderReplyQuote(msg) {
        const quote = this.normalizeReplyQuote(msg?.reply);
        if (!quote) return '';
        // data-reply-target drives the click-to-scroll below; absent when the
        // original is not in this client's history at all.
        const target = quote.id ? ` data-reply-target="${this.esc(quote.id)}"` : '';
        return `<div class="msg-quote"${target} role="button" tabindex="0">
            <span class="msg-quote-author">${this.esc(quote.sender)}</span>
            <span class="msg-quote-text">${this.esc(this.replyQuotePreview(quote))}</span>
        </div>`;
    }

    startReplyToMessage(messageId) {
        const found = this.findMessageById(messageId);
        if (!found) return;
        const quote = this.buildReplyQuote(found.msg);
        if (!quote) return;
        // Replying while editing would be ambiguous — the edit wins its own bar,
        // so starting a reply ends the edit.
        this.S.editDraft = null;
        this.S.replyDraft = quote;
        this.renderComposerContext();
        const input = document.getElementById('msgInput');
        if (input) input.focus();
    }

    /** Scrolls to the quoted original and flashes it, when it is still loaded. */
    scrollToMessage(messageId) {
        const id = String(messageId || '').trim();
        if (!id) return false;
        const box = document.getElementById('msgs');
        const node = box?.querySelector(`.msg[data-message-id="${CSS.escape(id)}"]`);
        if (!node) {
            this.addLogEntry({ type: 'INFO', msg: 'Исходное сообщение не загружено в этом чате', ts: new Date().toLocaleTimeString() });
            return false;
        }
        node.scrollIntoView({ block: 'center', behavior: 'smooth' });
        node.classList.remove('msg-flash');
        // Reading offsetWidth forces the class removal to take effect before it is
        // re-added, so a second click on the same quote replays the animation
        // instead of doing nothing.
        void node.offsetWidth;
        node.classList.add('msg-flash');
        setTimeout(() => node.classList.remove('msg-flash'), 1600);
        return true;
    }

    // ---- Editing ------------------------------------------------------

    /**
     * Only the author edits, and only a message the server actually has.
     * Channel managers can *delete* other people's messages (canDeleteMessage),
     * but rewriting someone's words under their name is forgery — the server
     * refuses it too (PUT /api/message/:id checks the sender).
     */
    canEditMessage(msg) {
        if (!msg || msg.kind === 'call') return false;
        if (String(msg.sender || '').trim() !== this.myName()) return false;
        const id = String(msg.id || '').trim();
        if (!id) return false;
        // Still in the outbox (id === clientId) — there is nothing on the server
        // to replace yet.
        return !msg.clientId || id !== String(msg.clientId).trim();
    }

    startEditMessage(messageId) {
        const found = this.findMessageById(messageId);
        if (!found || !this.canEditMessage(found.msg)) return;
        this.S.replyDraft = null;
        this.S.editDraft = {
            id: String(found.msg.id || '').trim(),
            originalText: String(found.msg.text || ''),
        };
        const input = document.getElementById('msgInput');
        if (input) {
            input.value = String(found.msg.text || '');
            this.resizeComposer();
            input.focus();
            // Caret to the end — the common intent is to append or fix a typo,
            // not to overwrite from the start.
            const end = input.value.length;
            try { input.setSelectionRange(end, end); } catch (e) {}
        }
        this.renderComposerContext();
        this.updateSendButtonState();
    }

    /**
     * Clears the reply bar after a send, but only if it still holds the quote
     * that send used — the user may have started replying to something else
     * while the send was in flight, and clearing that would lose their intent.
     */
    clearComposerReply(usedQuote) {
        if (!usedQuote) return;
        if (this.S.replyDraft && this.S.replyDraft.id !== usedQuote.id) return;
        this.S.replyDraft = null;
        this.renderComposerContext();
    }

    cancelComposerContext({ restoreInput = true } = {}) {
        const wasEditing = !!this.S.editDraft;
        this.S.replyDraft = null;
        this.S.editDraft = null;
        if (wasEditing && restoreInput) {
            const input = document.getElementById('msgInput');
            if (input) {
                input.value = '';
                this.resizeComposer();
            }
        }
        this.renderComposerContext();
        this.updateSendButtonState();
    }

    /** Renders the reply/edit bar sitting above the composer. */
    renderComposerContext() {
        const wrap = document.getElementById('composerContext');
        if (!wrap) return;
        const reply = this.S.replyDraft;
        const edit = this.S.editDraft;
        if (!reply && !edit) {
            wrap.hidden = true;
            wrap.innerHTML = '';
            return;
        }
        const title = edit ? 'Редактирование' : `Ответ ${this.esc(reply.sender)}`;
        const preview = edit
            ? this.replyQuotePreview({ text: edit.originalText })
            : this.replyQuotePreview(reply);
        wrap.hidden = false;
        wrap.innerHTML = `<div class="composer-context-body">
                <span class="composer-context-title">${title}</span>
                <span class="composer-context-text">${this.esc(preview)}</span>
            </div>
            <button class="composer-context-close" type="button" data-composer-context-cancel aria-label="Отменить">✕</button>`;
    }

    /**
     * Applies an edit to local state right away, so the bubble updates without
     * waiting for the server round-trip and the following history refresh.
     */
    applyLocalMessageEdit(messageId, text) {
        const found = this.findMessageById(messageId);
        if (!found) return false;
        const list = found.serverKey ? this.S.serverChats[found.serverKey] : this.S.chats[found.peer];
        if (!Array.isArray(list)) return false;
        list[found.index] = {
            ...list[found.index],
            text,
            // messageRenderKey collapses to `id:<id>` for a stored message and
            // messageStableSignature only samples the text *length*, so an edit
            // that keeps the length would otherwise never trigger a re-render.
            editRev: Number(list[found.index].editRev || 0) + 1,
            editedAt: new Date().toISOString(),
        };
        this.scheduleSaveStoredMessageCache();
        const shouldRender = found.serverKey
            ? found.serverKey === this.currentServerChatKey()
            : found.peer === this.S.current;
        if (shouldRender) this.scheduleRenderMessages();
        return true;
    }

    /**
     * Sends the edit. The archive is replaced wholesale server-side, so the
     * message's attachments have to be re-packed along with the new text —
     * omitting them here would silently strip them from the message.
     */
    async submitMessageEdit() {
        const draft = this.S.editDraft;
        if (!draft) return false;
        const input = document.getElementById('msgInput');
        const text = String((input && input.value) || '').trim();
        const found = this.findMessageById(draft.id);
        if (!found) {
            this.cancelComposerContext();
            return false;
        }
        const attachments = this.normalizeAttachments(found.msg.attachments);
        if (!text && attachments.length === 0) {
            this.addLogEntry({ type: 'WARN', msg: 'Пустое сообщение нельзя сохранить — удалите его', ts: new Date().toLocaleTimeString() });
            return false;
        }
        if (text === String(found.msg.text || '')) {
            // Nothing changed — don't burn a chain version on a no-op edit.
            this.cancelComposerContext();
            return true;
        }

        const isServers = !!found.msg.serverId;
        const cryptoKey = await this.resolveConversationCryptoKey({
            peer: isServers ? null : (found.msg.sender === this.myName() ? found.msg.receiver : found.msg.sender),
            serverId: found.msg.serverId || null,
            channelId: found.msg.channelId || null,
            reason: 'submitMessageEdit',
        }) || this.loadStoredCryptoKey();
        if (!cryptoKey) {
            this.addLogEntry({ type: 'ERROR', msg: 'Для редактирования нужен E2E-ключ', ts: new Date().toLocaleTimeString() });
            return false;
        }

        const keyVersion = Number(found.msg.keyVersion || 2) || 2;
        // The quote and the call record ride along unchanged: an edit changes the
        // text, not what the message was a reply to.
        const replyPayload = found.msg.reply
            ? (typeof found.msg.reply === 'string' ? found.msg.reply : JSON.stringify(found.msg.reply))
            : '';

        const previousText = String(found.msg.text || '');
        // Optimistic, then rolled back on failure — an edit that silently did
        // nothing is worse than one that visibly reverts.
        this.applyLocalMessageEdit(draft.id, text);
        this.cancelComposerContext();

        try {
            if (this.nativeSupports('editMessage')) {
                await this.requestNativeAction({
                    type: NativeMessageTypes.EDIT_MESSAGE,
                    messageId: draft.id,
                    text,
                    key: cryptoKey,
                    keyVersion,
                    // Автор кладётся в архив и именно оттуда потом читается при
                    // отрисовке. Оболочка не обязана знать его в том же регистре, в
                    // каком его показывает UI: Android, например, хранит последнего
                    // вошедшего в нижнем регистре, и правка переименовала бы автора.
                    // SEND_MESSAGE передаёт `sender` ровно по этой же причине.
                    sender: this.myName(),
                    reply: replyPayload,
                    attachments: attachments.map(att => ({
                        name: att.name,
                        mimeType: att.mimeType,
                        kind: att.kind,
                        size: att.size,
                        dataUrl: att.dataUrl,
                    })),
                }, 30000);
            } else {
                const ok = await this.browserEditMessage({
                    messageId: draft.id,
                    text,
                    key: cryptoKey,
                    keyVersion,
                    reply: replyPayload,
                    attachments,
                });
                if (!ok) throw new Error('Не удалось отправить изменения');
            }
            this.addLogEntry({ type: 'SUCCESS', msg: 'Сообщение изменено', ts: new Date().toLocaleTimeString() });
            return true;
        } catch (e) {
            this.applyLocalMessageEdit(draft.id, previousText);
            this.addLogEntry({ type: 'ERROR', msg: `Не удалось изменить сообщение: ${e?.message || e}`, ts: new Date().toLocaleTimeString() });
            return false;
        }
    }

    /**
     * Reaction to someone else's edit (or our own from another device). The event
     * carries no plaintext, so the only thing to do is re-fetch and re-decrypt
     * that conversation — exactly the path a newly received message takes.
     */
    onMessageEdited(payload) {
        if (!payload || typeof payload !== 'object') return;
        const messageId = String(payload.messageId || payload.message_id || '').trim();
        if (!messageId) return;
        const found = this.findMessageById(messageId);
        if (!found) return;
        this.trace(`onMessageEdited id=${messageId} peer=${found.serverKey || found.peer}`);
        // Bumped so the render signature changes even if the new text happens to
        // be the same length as the old one.
        const list = found.serverKey ? this.S.serverChats[found.serverKey] : this.S.chats[found.peer];
        if (Array.isArray(list)) {
            list[found.index] = {
                ...list[found.index],
                editRev: Number(list[found.index].editRev || 0) + 1,
            };
        }
        // syncActiveConversation only ever refreshes whatever is on screen, so
        // there is nothing to do for an edit in a conversation the user is not
        // looking at — it is re-fetched when they open it.
        const isVisible = found.serverKey
            ? found.serverKey === this.currentServerChatKey()
            : found.peer === this.S.current;
        if (isVisible) {
            void this.syncActiveConversation({ force: true });
        }
    }

    async deleteMessage(messageId) {
        const id = String(messageId || '').trim();
        if (!id) return;
        const found = this.findMessageById(id);
        if (!found || !this.canDeleteMessage(found.msg)) return;
        if (!confirm('Удалить сообщение?')) return;

        const hasRealServerId = !!found.msg.id && (!found.msg.clientId || String(found.msg.id) !== String(found.msg.clientId));
        if (!hasRealServerId) {
            // Never made it past the outbox (still pending/failed to upload) —
            // nothing exists server-side to delete, just drop it locally.
            this.removeMessageFromState(id);
            return;
        }

        try {
            const res = await this.apiFetch(this.apiRoutes.messages.remove(found.msg.id), { method: 'DELETE' });
            if (!res.ok && res.status !== 204) {
                throw new Error(await res.text() || 'Не удалось удалить сообщение');
            }
            this.removeMessageFromState(id);
        } catch (e) {
            this.addLogEntry({ type: 'ERROR', msg: `Не удалось удалить сообщение: ${e.message || e}`, ts: new Date().toLocaleTimeString() });
        }
    }
});


// --- MODULE: interface/profiles.js ---
// --- ZaliInterface: Профили людей: состояние, загрузка, подписки, дружба, комментарии. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Здесь только модель и
// сетевой слой профиля; отрисовка живёт в profile_ui.js, а векторная стена —
// в autographs.js.
//
// Как это устроено:
//
//   - Профиль открывается поверх всего (оверлей), а не как ещё один "view":
//     на профиль тыкают из списка контактов, из шапки чата и прямо из ленты
//     сообщений, и в каждом из этих мест возвращаться нужно ровно туда, откуда
//     пришёл. Оверлей это даёт бесплатно, отдельный экран — нет.
//
//   - Всё состояние профиля лежит в S.profile одним объектом. Комментарии,
//     автографы и очередь модерации грузятся отдельными запросами, но живут
//     в одном месте, чтобы перерисовка была одна на всех.
//
//   - Данные всегда перезапрашиваются при открытии — и это не изменилось.
//     Изменилось то, ЧТО видно, пока запрос идёт: карточка из постоянного
//     кеша (interface/cache.js) вместо скелетона. Прежнее возражение —
//     «показать вчерашнее «вы не друзья» хуже, чем моргнуть» — снято тем,
//     что вчерашнее живёт на экране ровно столько, сколько идёт запрос,
//     после чего затирается свежим ответом. См. refreshProfile().
ZaliMixin(ZaliInterface, class {

    /** Пустое состояние. Одна точка правды для конструктора и для закрытия. */
    static get emptyProfileState() {
        return {
            open: false,
            username: '',
            loading: false,
            error: '',
            data: null,
            tab: 'wall',
            editing: false,
            /** Черновик формы редактирования — правки видны сразу, но не уходят на сервер до «Сохранить». */
            draft: null,
            saving: false,
            comments: [],
            commentsLoading: false,
            commentDraft: '',
            commentError: '',
            autographs: [],
            pendingAutographs: [],
            autographsLoading: false,
            /** Режим рисования: см. autographs.js. */
            drawing: null,
            friendRequests: { incoming: [], outgoing: [] },
            friends: [],
            inviteDraft: '',
            inviteStatus: '',
            busy: '',
        };
    }

    /**
     * Типы WS-событий профиля. Список держится здесь, а разбор — в
     * handleProfileEvent: транспорт (voice_transport.js) должен уметь отличить
     * «наше» событие от чужого, не зная, что с ним делать.
     */
    static get PROFILE_EVENT_TYPES() {
        return ['friend_request', 'friend_accepted', 'profile_comment', 'profile_autograph', 'profile_follow', 'autograph_approved'];
    }

    /** Варианты аудитории — один список для всех трёх селекторов политики. */
    static get audienceOptions() {
        return [
            { value: 'anyone', label: 'Любые' },
            { value: 'contacts', label: 'Контакты' },
            { value: 'followers', label: 'Отслеживающие' },
            { value: 'friends', label: 'Друзья' },
        ];
    }

    /** То же плюс «решаю сам» — только для автоодобрения автографов. */
    static get autoApproveOptions() {
        return ZaliInterface.audienceOptions.concat([{ value: 'nobody', label: 'Одобряю сам' }]);
    }

    ensureProfileState() {
        if (!this.S.profile) this.S.profile = ZaliInterface.emptyProfileState;
        return this.S.profile;
    }

    setProfileState(partial = {}) {
        this.S.profile = { ...this.ensureProfileState(), ...partial };
        this.renderProfileOverlay();
    }

    audienceLabel(value) {
        const found = ZaliInterface.autoApproveOptions.find(option => option.value === value);
        return found ? found.label : 'Любые';
    }

    // ------------------------------------------------------------
    // Открытие / закрытие
    // ------------------------------------------------------------

    /**
     * Единственная точка входа в профиль. Все клики по аватаркам ведут сюда.
     * @param {string} username
     * @param {{editing?: boolean, tab?: string}} options
     */
    async openProfile(username, { editing = false, tab = '' } = {}) {
        const name = String(username || '').trim();
        if (!name) return;
        if (!this.S.session?.token) {
            this.addLogEntry({ type: 'WARN', msg: 'Профили доступны только после входа', ts: new Date().toLocaleTimeString() });
            return;
        }

        const isSelf = name === this.myName();
        this.setProfileState({
            ...ZaliInterface.emptyProfileState,
            open: true,
            username: name,
            loading: true,
            editing: editing && isSelf,
            tab: tab || 'wall',
        });
        this.showProfileOverlay();
        await this.refreshProfile();
        // Свои заявки в друзья нужны и на чужом профиле: именно там видно
        // «вам уже написали» и есть чем ответить, не уходя со страницы.
        if (isSelf) void this.loadFriendRequests();
        void this.loadProfileComments();
        void this.loadProfileAutographs();
    }

    closeProfile() {
        // Незавершённый рисунок отменяется вместе с оверлеем: держать его в
        // состоянии до следующего открытия — верный способ показать человеку
        // чужие штрихи на другой стене.
        this.cancelAutographDrawing({ silent: true });
        this.hideProfileOverlay();
        this.S.profile = ZaliInterface.emptyProfileState;
    }

    /**
     * Карточка профиля с диска. Хранится JSON-ответом целиком: он маленький
     * (единицы килобайт), а разбирать его на части значило бы держать вторую
     * схему рядом с серверной.
     */
    async loadCachedProfile(name) {
        try {
            const blob = await this.cacheGet('profile', String(name || '').trim().toLowerCase());
            if (!blob) return null;
            const parsed = JSON.parse(await this.blobToText(blob));
            return parsed && typeof parsed === 'object' ? parsed : null;
        } catch (e) {
            return null;
        }
    }

    /**
     * Профиль показывается из кеша сразу и обновляется под рукой.
     *
     * Раньше здесь было записано обратное решение — «данные всегда
     * перезапрашиваются, показать вчерашнее хуже, чем моргнуть скелетоном».
     * Возражение верное, но оно про КЕШ ВМЕСТО ЗАПРОСА. Запрос никуда не
     * делся: он уходит в той же строке, а кешированная карточка просто
     * занимает место скелетона на те 100–300 мс, что он идёт. Счётчик
     * подписчиков и статус дружбы приезжают ровно так же быстро, как
     * раньше, — но вместо пустой рамки человек всё это время видит профиль.
     */
    async refreshProfile() {
        const state = this.ensureProfileState();
        const name = state.username;
        if (!name) return;
        // Запрос уходит ПЕРВЫМ, до чтения кеша. Чтение с диска может оказаться
        // первым обращением к базе за сеанс, то есть включать в себя открытие
        // IndexedDB — а оно в патологическом случае длится до
        // ZALI_CACHE_OPEN_TIMEOUT_MS. Дожидаться его перед отправкой запроса
        // значит превратить ускорение в задержку: профиль начинал бы грузиться
        // на секунды позже, чем до появления кеша.
        let request;
        try {
            request = this.apiFetch(this.apiRoutes.profiles.byUsername(name), { interactive: true });
        } catch (e) {
            request = Promise.reject(e);
        }
        const cached = state.data ? null : await this.loadCachedProfile(name);
        if (cached && this.ensureProfileState().username === name && !this.ensureProfileState().data) {
            this.setProfileState({
                loading: false,
                error: '',
                data: cached,
                draft: this.ensureProfileState().editing ? this.ensureProfileState().draft : this.profileDraftFrom(cached),
            });
            this.ensureAvatarLoaded(name);
        }
        try {
            const res = await request;
            if (this.ensureProfileState().username !== name) return;
            if (res.status === 404) {
                // Профиля больше нет — кешированная карточка обязана уйти
                // вместе с ним, иначе следующее открытие снова покажет её.
                void this.cacheDelete('profile', String(name).trim().toLowerCase());
                this.setProfileState({ loading: false, error: 'Пользователь не найден', data: null });
                return;
            }
            if (!res.ok) {
                // Сеть отвалилась, а карточка из кеша уже на экране — она
                // лучше, чем ошибка на пустом месте; ошибку показываем только
                // когда показывать больше нечего.
                if (this.ensureProfileState().data) {
                    this.setProfileState({ loading: false });
                    return;
                }
                this.setProfileState({ loading: false, error: 'Не удалось загрузить профиль' });
                return;
            }
            const data = await res.json();
            void this.cachePut('profile', String(name).trim().toLowerCase(), JSON.stringify(data), { contentType: 'application/json' });
            this.setProfileState({
                loading: false,
                error: '',
                data,
                // Черновик пересобирается из свежих данных только когда форма не
                // открыта — иначе ответ сервера затёр бы то, что человек печатает.
                draft: this.ensureProfileState().editing ? this.ensureProfileState().draft : this.profileDraftFrom(data),
            });
            this.ensureAvatarLoaded(name);
        } catch (e) {
            if (this.ensureProfileState().data) {
                this.setProfileState({ loading: false });
                return;
            }
            this.setProfileState({ loading: false, error: 'Не удалось загрузить профиль' });
        }
    }

    profileDraftFrom(data) {
        return {
            displayName: data?.displayName || '',
            bio: data?.bio || '',
            status: data?.status || '',
            location: data?.location || '',
            accentColor: data?.accentColor || '',
            commentPolicy: data?.commentPolicy || 'anyone',
            autographPolicy: data?.autographPolicy || 'anyone',
            autographAutoApprove: data?.autographAutoApprove || 'nobody',
            links: Array.isArray(data?.links) ? data.links.map(link => ({ ...link })) : [],
        };
    }

    setProfileTab(tab) {
        const next = String(tab || '').trim();
        if (!next) return;
        this.setProfileState({ tab: next });
        if (next === 'moderation') void this.loadPendingAutographs();
        if (next === 'friends') void this.loadFriendRequests();
    }

    // ------------------------------------------------------------
    // Редактирование своего профиля
    // ------------------------------------------------------------

    startProfileEditing() {
        const state = this.ensureProfileState();
        if (!state.data?.isSelf) return;
        this.setProfileState({ editing: true, draft: this.profileDraftFrom(state.data) });
    }

    cancelProfileEditing() {
        const state = this.ensureProfileState();
        this.setProfileState({ editing: false, draft: this.profileDraftFrom(state.data) });
    }

    updateProfileDraft(field, value) {
        const state = this.ensureProfileState();
        const draft = { ...(state.draft || this.profileDraftFrom(state.data)) };
        draft[field] = value;
        // Без перерисовки: поле уже содержит то, что напечатали, а повторный
        // рендер увёл бы каретку в конец строки на каждом символе.
        this.S.profile = { ...state, draft };
    }

    updateProfileDraftLink(index, field, value) {
        const state = this.ensureProfileState();
        const draft = { ...(state.draft || this.profileDraftFrom(state.data)) };
        const links = Array.isArray(draft.links) ? draft.links.map(link => ({ ...link })) : [];
        if (!links[index]) return;
        links[index][field] = value;
        draft.links = links;
        this.S.profile = { ...state, draft };
    }

    addProfileDraftLink() {
        const state = this.ensureProfileState();
        const draft = { ...(state.draft || this.profileDraftFrom(state.data)) };
        const links = Array.isArray(draft.links) ? draft.links.map(link => ({ ...link })) : [];
        if (links.length >= 6) return;
        links.push({ label: '', url: '', color: '' });
        this.setProfileState({ draft: { ...draft, links } });
    }

    removeProfileDraftLink(index) {
        const state = this.ensureProfileState();
        const draft = { ...(state.draft || this.profileDraftFrom(state.data)) };
        const links = (Array.isArray(draft.links) ? draft.links : []).filter((_, i) => i !== index);
        this.setProfileState({ draft: { ...draft, links } });
    }

    /**
     * «vk.com/имя» — это https://vk.com/имя, а не мусор. Голый адрес получает
     * схему; то, что уже несёт какую-то схему (в том числе javascript:),
     * возвращается как есть — решение принимает сервер, а не эта функция.
     */
    normalizeProfileLinkUrl(value) {
        const raw = String(value || '').trim();
        if (!raw) return '';
        if (/^[a-z][a-z0-9+.-]*:/i.test(raw)) return raw;
        if (raw.startsWith('//')) return `https:${raw}`;
        return `https://${raw}`;
    }

    async saveProfile() {
        const state = this.ensureProfileState();
        if (!state.data?.isSelf || state.saving) return;
        const draft = state.draft || this.profileDraftFrom(state.data);
        this.setProfileState({ saving: true, error: '' });
        try {
            // Сервер принимает только http/https (sanitize_links в profiles.rs) и
            // всё остальное выбрасывает МОЛЧА: человек вводил «vk.com/имя»,
            // сохранял, и ссылка просто не появлялась в профиле — ни ошибки,
            // ни следа. Голый адрес — это https, дописываем схему за него;
            // явную чужую схему не трогаем, её отклонит сервер, и об этом
            // ниже будет сказано вслух.
            const outgoingLinks = (draft.links || [])
                .map(link => ({ ...link, url: this.normalizeProfileLinkUrl(link.url) }))
                .filter(link => link.url);
            const res = await this.apiFetch(this.apiRoutes.profiles.update, {
                method: 'PUT',
                interactive: true,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    displayName: draft.displayName || '',
                    bio: draft.bio || '',
                    status: draft.status || '',
                    location: draft.location || '',
                    accentColor: draft.accentColor || '',
                    commentPolicy: draft.commentPolicy || 'anyone',
                    autographPolicy: draft.autographPolicy || 'anyone',
                    autographAutoApprove: draft.autographAutoApprove || 'nobody',
                    links: outgoingLinks,
                }),
            });
            if (!res.ok) {
                const message = await res.text().catch(() => '');
                this.setProfileState({ saving: false, error: message || 'Не удалось сохранить профиль' });
                return;
            }
            const data = await res.json();
            const kept = Array.isArray(data?.links) ? data.links.length : 0;
            const dropped = outgoingLinks.length - kept;
            if (dropped > 0) {
                // Редактор НЕ закрываем: иначе единственным следом отказа
                // осталось бы отсутствие ссылки в профиле — ровно то, на что
                // и жаловались.
                this.setProfileState({
                    saving: false,
                    data,
                    draft: this.profileDraftFrom(data),
                    error: `Профиль сохранён, но ${dropped} ${this.ruPlural(dropped, 'ссылка отклонена', 'ссылки отклонены', 'ссылок отклонено')}: принимаются только http/https-адреса.`,
                });
                return;
            }
            this.setProfileState({ saving: false, editing: false, data, draft: this.profileDraftFrom(data), error: '' });
            this.addLogEntry({ type: 'SUCCESS', msg: 'Профиль сохранён', ts: new Date().toLocaleTimeString() });
        } catch (e) {
            this.setProfileState({ saving: false, error: 'Не удалось сохранить профиль' });
        }
    }

    // ------------------------------------------------------------
    // Подписки и дружба
    // ------------------------------------------------------------

    /**
     * Подписка/отписка. Ответ сервера — уже готовый профиль со свежими
     * счётчиками, поэтому локально ничего досчитывать не надо (и разъехаться
     * с сервером на гонке двух кликов тоже не получится).
     */
    async toggleFollow(username = '') {
        const state = this.ensureProfileState();
        const name = String(username || state.username || '').trim();
        if (!name || state.busy === 'follow') return;
        const following = name === state.username ? !!state.data?.isFollowing : false;
        this.setProfileState({ busy: 'follow' });
        try {
            const res = await this.apiFetch(this.apiRoutes.profiles.follow(name), {
                method: following ? 'DELETE' : 'POST',
                interactive: true,
            });
            if (!res.ok) {
                this.setProfileState({ busy: '', error: 'Не удалось изменить подписку' });
                return;
            }
            const data = await res.json();
            if (this.ensureProfileState().username === name) {
                this.setProfileState({ busy: '', data, error: '' });
            } else {
                this.setProfileState({ busy: '' });
            }
            this.addLogEntry({
                type: 'INFO',
                msg: following ? `Вы отписались от ${name}` : `Вы подписались на ${name}`,
                ts: new Date().toLocaleTimeString(),
            });
        } catch (e) {
            this.setProfileState({ busy: '', error: 'Не удалось изменить подписку' });
        }
    }

    /** Подписка из контекстного меню — вне профиля, без его состояния. */
    async followUserDirect(username, unfollow = false) {
        const name = String(username || '').trim();
        if (!name) return;
        try {
            const res = await this.apiFetch(this.apiRoutes.profiles.follow(name), {
                method: unfollow ? 'DELETE' : 'POST',
                interactive: true,
            });
            this.addLogEntry({
                type: res.ok ? 'SUCCESS' : 'ERROR',
                msg: res.ok
                    ? (unfollow ? `Вы отписались от ${name}` : `Вы подписались на ${name}`)
                    : `Не удалось изменить подписку на ${name}`,
                ts: new Date().toLocaleTimeString(),
            });
            if (res.ok && this.ensureProfileState().username === name) await this.refreshProfile();
        } catch (e) {
            this.addLogEntry({ type: 'ERROR', msg: `Не удалось изменить подписку на ${name}`, ts: new Date().toLocaleTimeString() });
        }
    }

    /**
     * Отправить заявку в друзья. Сервер сам сводит встречные заявки в дружбу,
     * поэтому здесь достаточно различить два его ответа.
     */
    async requestFriendship(username = '') {
        const state = this.ensureProfileState();
        const name = String(username || state.username || '').trim();
        if (!name || state.busy === 'friend') return;
        this.setProfileState({ busy: 'friend' });
        try {
            const res = await this.apiFetch(this.apiRoutes.friends.requests, {
                method: 'POST',
                interactive: true,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ to: name }),
            });
            if (!res.ok) {
                const message = await res.text().catch(() => '');
                this.setProfileState({ busy: '', error: message || 'Не удалось отправить заявку' });
                return;
            }
            const body = await res.json().catch(() => ({}));
            this.addLogEntry({
                type: 'SUCCESS',
                msg: body?.status === 'accepted' ? `Теперь вы друзья с ${name}` : `Заявка в друзья отправлена: ${name}`,
                ts: new Date().toLocaleTimeString(),
            });
            this.setProfileState({ busy: '' });
            if (this.ensureProfileState().username === name) await this.refreshProfile();
            void this.loadFriendRequests();
        } catch (e) {
            this.setProfileState({ busy: '', error: 'Не удалось отправить заявку' });
        }
    }

    async respondFriendRequest(requestId, action) {
        const id = String(requestId || '').trim();
        if (!id) return;
        try {
            const res = await this.apiFetch(this.apiRoutes.friends.request(id), {
                method: 'POST',
                interactive: true,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action }),
            });
            if (!res.ok) {
                this.setProfileState({ error: 'Не удалось обработать заявку' });
                return;
            }
            const body = await res.json().catch(() => ({}));
            if (body?.status === 'accepted' && body?.friend) {
                this.addLogEntry({ type: 'SUCCESS', msg: `Теперь вы друзья с ${body.friend}`, ts: new Date().toLocaleTimeString() });
            }
            await this.loadFriendRequests();
            if (this.ensureProfileState().username) await this.refreshProfile();
        } catch (e) {
            this.setProfileState({ error: 'Не удалось обработать заявку' });
        }
    }

    async removeFriend(username) {
        const name = String(username || '').trim();
        if (!name) return;
        try {
            const res = await this.apiFetch(this.apiRoutes.friends.byUsername(name), {
                method: 'DELETE',
                interactive: true,
            });
            if (!res.ok) return;
            await this.loadFriendRequests();
            if (this.ensureProfileState().username) await this.refreshProfile();
        } catch (e) {
            // Молча: список всё равно перечитается при следующем открытии.
        }
    }

    async loadFriendRequests() {
        try {
            const [requestsRes, friendsRes] = await Promise.all([
                this.apiFetch(this.apiRoutes.friends.requests),
                this.apiFetch(this.apiRoutes.friends.list),
            ]);
            const requests = requestsRes.ok ? await requestsRes.json() : { incoming: [], outgoing: [] };
            const friends = friendsRes.ok ? await friendsRes.json() : { friends: [] };
            this.setProfileState({
                friendRequests: {
                    incoming: Array.isArray(requests?.incoming) ? requests.incoming : [],
                    outgoing: Array.isArray(requests?.outgoing) ? requests.outgoing : [],
                },
                friends: Array.isArray(friends?.friends) ? friends.friends : [],
            });
            this.updateFriendRequestBadge();
        } catch (e) {
            // Не критично: заявки перечитаются при следующем открытии вкладки.
        }
    }

    /** Отправить приглашение в друзья по имени из формы «Пригласить». */
    async submitFriendInvite() {
        const state = this.ensureProfileState();
        const name = String(state.inviteDraft || '').trim();
        if (!name) return;
        if (name === this.myName()) {
            this.setProfileState({ inviteStatus: 'Нельзя пригласить самого себя' });
            return;
        }
        this.setProfileState({ inviteStatus: 'Отправляем...' });
        try {
            const res = await this.apiFetch(this.apiRoutes.friends.requests, {
                method: 'POST',
                interactive: true,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ to: name }),
            });
            if (!res.ok) {
                const message = await res.text().catch(() => '');
                this.setProfileState({ inviteStatus: message || 'Не удалось отправить приглашение' });
                return;
            }
            const body = await res.json().catch(() => ({}));
            this.setProfileState({
                inviteDraft: '',
                inviteStatus: body?.status === 'accepted' ? `Теперь вы друзья с ${name}` : `Приглашение отправлено: ${name}`,
            });
            await this.loadFriendRequests();
        } catch (e) {
            this.setProfileState({ inviteStatus: 'Не удалось отправить приглашение' });
        }
    }

    /**
     * Бейдж «есть входящие заявки» на кнопке своего профиля. Считается по уже
     * загруженному списку, отдельного запроса не делает.
     */
    updateFriendRequestBadge() {
        const badge = document.getElementById('meFriendBadge');
        if (!badge) return;
        const count = (this.ensureProfileState().friendRequests?.incoming || []).length;
        badge.textContent = count > 99 ? '99+' : String(count);
        badge.hidden = count === 0;
    }

    // ------------------------------------------------------------
    // Комментарии
    // ------------------------------------------------------------

    async loadProfileComments() {
        const name = this.ensureProfileState().username;
        if (!name) return;
        this.setProfileState({ commentsLoading: true });
        try {
            const res = await this.apiFetch(this.apiRoutes.profiles.comments(name));
            if (this.ensureProfileState().username !== name) return;
            if (!res.ok) {
                this.setProfileState({ commentsLoading: false, comments: [] });
                return;
            }
            const body = await res.json();
            this.setProfileState({
                commentsLoading: false,
                comments: Array.isArray(body?.comments) ? body.comments : [],
            });
            (body?.comments || []).forEach(comment => this.ensureAvatarLoaded(comment.author));
        } catch (e) {
            this.setProfileState({ commentsLoading: false });
        }
    }

    async submitProfileComment() {
        const state = this.ensureProfileState();
        const name = state.username;
        const body = String(state.commentDraft || '').trim();
        if (!name || !body || state.busy === 'comment') return;
        this.setProfileState({ busy: 'comment', commentError: '' });
        try {
            const res = await this.apiFetch(this.apiRoutes.profiles.comments(name), {
                method: 'POST',
                interactive: true,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ body }),
            });
            if (res.status === 403) {
                this.setProfileState({ busy: '', commentError: 'Владелец закрыл комментарии для вас' });
                return;
            }
            if (!res.ok) {
                this.setProfileState({ busy: '', commentError: 'Не удалось отправить комментарий' });
                return;
            }
            const payload = await res.json();
            this.setProfileState({
                busy: '',
                commentDraft: '',
                commentError: '',
                comments: Array.isArray(payload?.comments) ? payload.comments : state.comments,
            });
        } catch (e) {
            this.setProfileState({ busy: '', commentError: 'Не удалось отправить комментарий' });
        }
    }

    async deleteProfileComment(commentId) {
        const id = String(commentId || '').trim();
        if (!id) return;
        const state = this.ensureProfileState();
        // Оптимистично: строка исчезает сразу, при ошибке список перечитывается.
        this.setProfileState({ comments: (state.comments || []).filter(comment => comment.id !== id) });
        try {
            const res = await this.apiFetch(this.apiRoutes.profiles.comment(id), {
                method: 'DELETE',
                interactive: true,
            });
            if (!res.ok) await this.loadProfileComments();
        } catch (e) {
            await this.loadProfileComments();
        }
    }

    // ------------------------------------------------------------
    // Живые события с сервера
    // ------------------------------------------------------------

    /**
     * WS-события профиля (заявка в друзья, новый комментарий, новый автограф).
     * Вызывается из общего разбора входящих событий; неизвестные типы сюда
     * не доходят.
     */
    handleProfileEvent(event = {}) {
        const type = String(event?.type || '');
        const from = String(event?.from || '').trim();
        const state = this.ensureProfileState();

        if (type === 'friend_request') {
            this.addLogEntry({ type: 'INFO', msg: `Заявка в друзья от ${from}`, ts: new Date().toLocaleTimeString() });
            void this.loadFriendRequests();
        } else if (type === 'friend_accepted') {
            this.addLogEntry({ type: 'SUCCESS', msg: `${from} теперь ваш друг`, ts: new Date().toLocaleTimeString() });
            void this.loadFriendRequests();
        } else if (type === 'autograph_approved') {
            this.addLogEntry({ type: 'SUCCESS', msg: `Ваш автограф одобрен: ${event?.wall || ''}`, ts: new Date().toLocaleTimeString() });
        }

        if (!state.open) return;
        // Открыт как раз тот профиль, которого касается событие — обновляем.
        const mine = state.username === this.myName();
        if (type === 'profile_comment' && mine) void this.loadProfileComments();
        if (type === 'profile_autograph' && mine) {
            void this.refreshProfile();
            void this.loadPendingAutographs();
        }
        if ((type === 'profile_follow' || type === 'friend_accepted' || type === 'friend_request') && mine) {
            void this.refreshProfile();
        }
    }

});


// --- MODULE: interface/profile_ui.js ---
// --- ZaliInterface: Отрисовка профиля: шапка, вкладки, комментарии, друзья, модерация. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Модель и сеть — в
// profiles.js, векторная стена — в autographs.js.
//
// Оверлей перерисовывается целиком, но через setHTMLIfChanged: одинаковая
// разметка не вызывает записи в DOM. Это важно во время рисования — черновые
// штрихи живут в отдельном слое и в эту разметку не попадают, поэтому каждый
// новый штрих НЕ пересоздаёт поверхность рисования и не срывает захват
// указателя (см. bindAutographSurface).
//
// Поля ввода намеренно не перерисовываются на каждый символ: обработчики input
// пишут в черновик мимо рендера (updateProfileDraft), иначе каретка прыгала бы
// в конец строки на каждой букве.
ZaliMixin(ZaliInterface, class {

    showProfileOverlay() {
        const overlay = document.getElementById('profileOverlay');
        if (!overlay) return;
        overlay.hidden = false;
        requestAnimationFrame(() => overlay.classList.add('visible'));
        this.renderProfileOverlay();
    }

    hideProfileOverlay() {
        const overlay = document.getElementById('profileOverlay');
        if (!overlay) return;
        overlay.classList.remove('visible');
        setTimeout(() => {
            if (!this.ensureProfileState().open) overlay.hidden = true;
        }, 180);
    }

    /**
     * SQLite отдаёт CURRENT_TIMESTAMP как «YYYY-MM-DD HH:MM:SS» без указания
     * зоны, а это UTC. Без явного «Z» браузер прочитал бы её как местное время
     * и сдвинул бы все даты на смещение часового пояса.
     */
    profileTimestampLabel(raw) {
        const value = String(raw || '').trim();
        if (!value) return '';
        const iso = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(value)
            ? `${value.replace(' ', 'T')}Z`
            : value;
        const date = this.fmtDate(iso);
        const time = this.fmtTime(iso);
        if (!date && !time) return '';
        return date ? `${date}, ${time}` : time;
    }

    renderProfileOverlay() {
        const overlay = document.getElementById('profileOverlay');
        if (!overlay) return;
        const state = this.ensureProfileState();
        if (!state.open) {
            this.hideProfileOverlay();
            return;
        }
        const body = document.getElementById('profileBody');
        if (!body) return;
        this.setHTMLIfChanged(body, this.renderProfileBody(state));
        // Порядок обязателен: сначала черновые штрихи в свежий слой, потом
        // подписка на указатель — на тот элемент, который сейчас в документе.
        this.renderAutographDraft();
        this.bindAutographSurface();
    }

    renderProfileBody(state) {
        if (state.loading && !state.data) {
            return `<div class="profile-loading"><div class="sk sk-contact"></div><div class="sk sk-contact"></div></div>`;
        }
        if (state.error && !state.data) {
            return `<div class="profile-error">${this.esc(state.error)}</div>`;
        }
        const data = state.data;
        if (!data) return '';

        // Пока открыт редактор, вкладки не соответствуют ничему конкретному
        // («О себе» больше нет — её место в шапке, см. renderProfileHeader) —
        // показывать их подсвеченными на случайной вкладке хуже, чем не
        // показывать вовсе.
        const editingSelf = state.editing && data.isSelf;
        return `
            ${this.renderProfileHeader(state, data)}
            ${editingSelf ? '' : this.renderProfileTabs(state, data)}
            <div class="profile-tab-body">${this.renderProfileTabContent(state, data)}</div>
        `;
    }

    // ------------------------------------------------------------
    // Шапка
    // ------------------------------------------------------------

    renderProfileHeader(state, data) {
        const username = data.username || '';
        const accent = this.safeCssColor(data.accentColor) || '';
        const title = data.displayName || username;
        const counters = [
            { key: 'followers', value: data.followers, label: this.ruPlural(data.followers, 'подписчик', 'подписчика', 'подписчиков') },
            { key: 'following', value: data.following, label: 'подписок' },
            { key: 'friends', value: data.friends, label: this.ruPlural(data.friends, 'друг', 'друга', 'друзей') },
        ];

        return `<header class="profile-head"${accent ? ` style="--profile-accent:${this.esc(accent)}"` : ''}>
            <div class="profile-head-ava">${this.renderAvatarHTML(username, 'avatar-img', username)}</div>
            <div class="profile-head-copy">
                <h2 class="profile-name" id="profileModalName">${this.esc(title)}</h2>
                <div class="profile-handle">@${this.esc(username)}</div>
                ${data.bio ? `<div class="profile-bio-inline">${this.esc(data.bio)}</div>` : ''}
                ${this.renderProfileLinks(data)}
                <div class="profile-counters">
                    ${counters.map(counter => `
                        <span class="profile-counter">
                            <strong>${Number(counter.value) || 0}</strong>
                            <span>${this.esc(counter.label)}</span>
                        </span>
                    `).join('')}
                </div>
            </div>
            <div class="profile-head-actions">${this.renderProfileActions(state, data)}</div>
        </header>`;
    }

    // The editor (renderProfileEditor below) has always let you add/edit these,
    // and the server has always saved and returned them (sanitize_links in
    // profiles.rs enforces http/https there) — but nothing ever rendered
    // `data.links` back out anywhere in the read view, so a saved link was
    // simply invisible to everyone, including the owner looking at their own
    // profile. Shown in the header (like bio) so it's on every tab, not tied
    // to one.
    renderProfileLinks(data) {
        const links = (Array.isArray(data.links) ? data.links : [])
            .filter(link => String(link?.url || '').trim());
        if (!links.length) return '';
        return `<div class="profile-links">
            ${links.map(link => {
                const url = String(link.url || '').trim();
                // Server-enforced already (sanitize_links), but a link chip is an
                // <a href> about to be handed to the browser — re-checking the
                // scheme here means this can't be made to emit a bad href just
                // because some future write path forgets to sanitize.
                if (!/^https?:\/\//i.test(url)) return '';
                const label = String(link.label || '').trim()
                    || url.replace(/^https?:\/\//i, '').replace(/\/+$/, '');
                // Same double-check pattern as accentColor in renderProfileHeader:
                // server-sanitised already (sanitize_links -> sanitize_color), but
                // this becomes an inline style attribute, so it's re-validated here
                // too rather than trusted blind.
                const color = this.safeCssColor(link.color);
                const styleAttr = color ? ` style="color:${this.esc(color)};border-color:${this.esc(color)}"` : '';
                return `<a class="profile-link-chip" href="${this.esc(url)}" target="_blank" rel="noopener noreferrer" title="${this.esc(url)}"${styleAttr}>${this.esc(label)}</a>`;
            }).join('')}
        </div>`;
    }

    renderProfileActions(state, data) {
        if (data.isSelf) {
            if (state.editing) {
                return `
                    <button class="auth-btn primary" type="button" data-profile-action="save"${state.saving ? ' disabled' : ''}>${state.saving ? 'Сохраняем...' : 'Сохранить'}</button>
                    <button class="btn-flat" type="button" data-profile-action="cancel-edit">Отмена</button>
                `;
            }
            return `<button class="auth-btn primary" type="button" data-profile-action="edit">Редактировать профиль</button>`;
        }

        const followLabel = data.isFollowing ? 'Вы отслеживаете' : 'Отслеживать';
        const busy = state.busy;

        // Кнопка дружбы — одна, но с четырьмя разными состояниями. Показывать
        // «Добавить в друзья» тому, кто уже прислал вам заявку, значило бы
        // отправить встречную вместо простого «принять».
        let friendButton;
        if (data.isFriend) {
            friendButton = `<button class="btn-flat profile-friend-btn is-friend" type="button" data-profile-action="remove-friend">Вы друзья</button>`;
        } else if (data.friendRequest?.direction === 'incoming') {
            friendButton = `
                <button class="auth-btn primary" type="button" data-profile-action="accept-friend" data-request-id="${this.esc(data.friendRequest.id)}">Принять заявку</button>
                <button class="btn-flat" type="button" data-profile-action="decline-friend" data-request-id="${this.esc(data.friendRequest.id)}">Отклонить</button>
            `;
        } else if (data.friendRequest?.direction === 'outgoing') {
            friendButton = `<button class="btn-flat" type="button" data-profile-action="cancel-friend" data-request-id="${this.esc(data.friendRequest.id)}">Заявка отправлена</button>`;
        } else {
            friendButton = `<button class="btn-flat profile-friend-btn" type="button" data-profile-action="add-friend"${busy === 'friend' ? ' disabled' : ''}>Попроситься в друзья</button>`;
        }

        return `
            <button class="auth-btn primary profile-follow-btn${data.isFollowing ? ' following' : ''}" type="button" data-profile-action="toggle-follow"${busy === 'follow' ? ' disabled' : ''}>${this.esc(followLabel)}</button>
            ${friendButton}
            <button class="btn-flat" type="button" data-profile-action="message">Написать</button>
        `;
    }

    // ------------------------------------------------------------
    // Вкладки
    // ------------------------------------------------------------

    profileTabsFor(state, data) {
        const tabs = [
            { key: 'wall', label: 'Стена' },
            { key: 'comments', label: 'Комментарии' },
        ];
        if (data.isSelf) {
            const pending = Number(data.pendingAutographs) || 0;
            tabs.push({ key: 'moderation', label: 'Модерация', badge: pending });
            tabs.push({ key: 'friends', label: 'Друзья', badge: (state.friendRequests?.incoming || []).length });
        }
        return tabs;
    }

    renderProfileTabs(state, data) {
        const tabs = this.profileTabsFor(state, data);
        const active = tabs.some(tab => tab.key === state.tab) ? state.tab : 'wall';
        return `<nav class="profile-tabs" role="tablist">
            ${tabs.map(tab => `
                <button class="profile-tab${tab.key === active ? ' active' : ''}" type="button" role="tab" aria-selected="${tab.key === active}" data-profile-tab="${this.esc(tab.key)}">
                    <span>${this.esc(tab.label)}</span>
                    ${tab.badge ? `<span class="profile-tab-badge">${Number(tab.badge)}</span>` : ''}
                </button>
            `).join('')}
        </nav>`;
    }

    renderProfileTabContent(state, data) {
        // Редактор больше не привязан к вкладке «О себе» (она убрана — см.
        // profileTabsFor) и проверяется первым, до маршрутизации по вкладкам.
        if (state.editing && data.isSelf) return this.renderProfileEditor(state);
        const tabs = this.profileTabsFor(state, data).map(tab => tab.key);
        const active = tabs.includes(state.tab) ? state.tab : 'wall';
        if (active === 'comments') return this.renderProfileCommentsTab(state, data);
        if (active === 'moderation') return this.renderProfileModerationTab(state, data);
        if (active === 'friends') return this.renderProfileFriendsTab(state, data);
        return this.renderProfileWallTab(state, data);
    }

    /** Ряд из нескольких кнопок вместо системного `<select>` — активный вариант подсвечен акцентом. */
    renderAudienceGroup(name, value, options) {
        return `<div class="profile-audience-group" role="group">
            ${options.map(option => `
                <button type="button" class="profile-audience-btn${option.value === value ? ' active' : ''}" data-profile-audience-field="${this.esc(name)}" data-profile-audience-value="${this.esc(option.value)}" aria-pressed="${option.value === value}">${this.esc(option.label)}</button>
            `).join('')}
        </div>`;
    }

    renderProfileEditor(state) {
        const draft = state.draft || this.profileDraftFrom(state.data);
        const links = Array.isArray(draft.links) ? draft.links : [];
        return `<div class="profile-editor">
            ${state.error ? `<p class="profile-error">${this.esc(state.error)}</p>` : ''}

            <section class="profile-editor-section">
                <div class="profile-editor-section-head">
                    <span class="profile-editor-kicker">Основное</span>
                    <h3 class="profile-editor-title">Публичный профиль</h3>
                </div>
                <div class="profile-editor-row">
                    <label class="profile-field">
                        <span>Отображаемое имя</span>
                        <input type="text" maxlength="64" data-profile-field="displayName" value="${this.esc(draft.displayName || '')}" placeholder="${this.esc(state.username)}">
                    </label>
                    <label class="profile-field">
                        <span>Статус</span>
                        <input type="text" maxlength="120" data-profile-field="status" value="${this.esc(draft.status || '')}" placeholder="Чем занимаетесь">
                    </label>
                </div>
                <label class="profile-field">
                    <span>О себе</span>
                    <textarea rows="4" maxlength="600" data-profile-field="bio" placeholder="Пара слов о вас">${this.esc(draft.bio || '')}</textarea>
                </label>
                <div class="profile-editor-row">
                    <label class="profile-field">
                        <span>Где вы</span>
                        <input type="text" maxlength="64" data-profile-field="location" value="${this.esc(draft.location || '')}" placeholder="Город">
                    </label>
                    <label class="profile-field profile-field-color">
                        <span>Акцентный цвет</span>
                        <input type="color" data-profile-field="accentColor" value="${this.esc(this.safeCssColor(draft.accentColor) || '#cbff00')}">
                    </label>
                </div>
                <div class="profile-field">
                    <span>Аватар</span>
                    <div class="profile-avatar-editor">
                        <div class="ava profile-avatar-preview">${this.renderAvatarHTML(state.username, 'avatar-img', state.username)}</div>
                        <button class="btn-flat" type="button" data-profile-action="change-avatar">Сменить картинку</button>
                    </div>
                </div>
            </section>

            <section class="profile-editor-section">
                <div class="profile-editor-section-head">
                    <span class="profile-editor-kicker">Ссылки</span>
                    <h3 class="profile-editor-title">Сайты и соцсети</h3>
                </div>
                <div class="profile-links-editor">
                    ${links.map((link, index) => `
                        <div class="profile-link-row">
                            <input type="text" maxlength="48" placeholder="Название" data-profile-link-field="label" data-profile-link-index="${index}" value="${this.esc(link.label || '')}">
                            <input type="url" maxlength="300" placeholder="https://" data-profile-link-field="url" data-profile-link-index="${index}" value="${this.esc(link.url || '')}">
                            <input type="color" class="profile-link-color-input" title="Цвет ссылки" aria-label="Цвет ссылки" data-profile-link-field="color" data-profile-link-index="${index}" value="${this.esc(this.safeCssColor(link.color) || '#cbff00')}">
                            <button class="profile-link-remove" type="button" data-profile-action="remove-link" data-profile-link-index="${index}" aria-label="Удалить ссылку">${this.uiIcon('close')}</button>
                        </div>
                    `).join('')}
                    ${links.length < 6 ? `<button class="btn-flat" type="button" data-profile-action="add-link">Добавить ссылку</button>` : ''}
                </div>
                <small class="profile-help">Принимаются только http/https-ссылки. Цвет — необязательно, без выбора ссылка отображается акцентным цветом.</small>
            </section>

            <section class="profile-editor-section">
                <div class="profile-editor-section-head">
                    <span class="profile-editor-kicker">Приватность</span>
                    <h3 class="profile-editor-title">Кто что может</h3>
                </div>
                <div class="profile-audience-field">
                    <span>Кто может комментировать</span>
                    ${this.renderAudienceGroup('commentPolicy', draft.commentPolicy, ZaliInterface.audienceOptions)}
                </div>
                <div class="profile-audience-field">
                    <span>Кто может оставлять автографы</span>
                    ${this.renderAudienceGroup('autographPolicy', draft.autographPolicy, ZaliInterface.audienceOptions)}
                </div>
                <div class="profile-audience-field">
                    <span>Чьи автографы публиковать сразу</span>
                    ${this.renderAudienceGroup('autographAutoApprove', draft.autographAutoApprove, ZaliInterface.autoApproveOptions)}
                    <small class="profile-help">«Одобряю сам» — каждый автограф ждёт вашего «да» на вкладке «Модерация».</small>
                </div>
            </section>
        </div>`;
    }

    // ------------------------------------------------------------
    // Вкладка «Стена»
    // ------------------------------------------------------------

    renderProfileWallTab(state, data) {
        const drawing = state.drawing;
        const canDraw = !!data.canAutograph;

        const toolbar = drawing
            ? `<div class="autograph-toolbar">
                <div class="autograph-colors" role="group" aria-label="Цвет">
                    ${ZaliInterface.autographPalette.map(color => `
                        <button class="autograph-color${color === drawing.color ? ' active' : ''}" type="button" data-autograph-color="${this.esc(color)}" style="--swatch:${this.esc(color)}" aria-label="Цвет ${this.esc(color)}"></button>
                    `).join('')}
                </div>
                <label class="autograph-width">
                    <span>Толщина</span>
                    <input type="range" min="1" max="24" step="1" value="${Number(drawing.width) || 4}" data-autograph-width class="settings-range">
                </label>
                <div class="autograph-tool-actions">
                    <button class="btn-flat" type="button" data-profile-action="undo-stroke">Отменить штрих</button>
                    <button class="btn-flat" type="button" data-profile-action="clear-strokes">Очистить</button>
                    <button class="btn-flat" type="button" data-profile-action="cancel-drawing">Выйти</button>
                    <button class="auth-btn primary" type="button" data-profile-action="submit-autograph"${drawing.submitting ? ' disabled' : ''}>${drawing.submitting ? 'Отправляем...' : 'Оставить автограф'}</button>
                </div>
                ${drawing.error ? `<p class="profile-error">${this.esc(drawing.error)}</p>` : ''}
                <p class="profile-help">Рисуйте прямо на стене в любом месте — автограф сохранится вектором.</p>
            </div>`
            : `<div class="autograph-toolbar">
                ${canDraw
                    ? `<button class="auth-btn primary" type="button" data-profile-action="start-drawing">Оставить автограф</button>`
                    : `<p class="profile-help">${this.esc(data.isSelf ? 'Это ваша стена — здесь появляются автографы других людей.' : 'Владелец закрыл автографы для вас.')}</p>`}
                ${canDraw && !data.isSelf && data.autographAutoApprove === 'nobody'
                    ? `<span class="profile-policy-chip">Автографы публикуются после одобрения владельца</span>`
                    : ''}
            </div>`;

        return `<div class="profile-wall">
            ${toolbar}
            ${this.renderAutographWall()}
            ${this.renderWallLegend(state)}
        </div>`;
    }

    /** Подписи под стеной: кто оставил автограф и чем его можно убрать. */
    renderWallLegend(state) {
        const list = Array.isArray(state.autographs) ? state.autographs : [];
        if (!list.length) return '';
        return `<ul class="autograph-legend">
            ${list.map(item => `
                <li>
                    <span class="autograph-legend-author">${this.esc(item.author || '')}</span>
                    <span class="autograph-legend-date">${this.esc(this.profileTimestampLabel(item.createdAt))}</span>
                    ${item.canRemove ? `<button class="profile-link-remove" type="button" data-profile-action="remove-autograph" data-autograph-id="${this.esc(item.id)}" aria-label="Убрать автограф">${this.uiIcon('close')}</button>` : ''}
                </li>
            `).join('')}
        </ul>`;
    }

    // ------------------------------------------------------------
    // Вкладка «Комментарии»
    // ------------------------------------------------------------

    renderProfileCommentsTab(state, data) {
        const comments = Array.isArray(state.comments) ? state.comments : [];
        const composer = data.canComment
            ? `<div class="profile-comment-composer">
                <textarea rows="3" maxlength="2000" data-profile-field="commentDraft" placeholder="Написать комментарий">${this.esc(state.commentDraft || '')}</textarea>
                <div class="profile-comment-actions">
                    ${state.commentError ? `<span class="profile-error">${this.esc(state.commentError)}</span>` : '<span></span>'}
                    <button class="auth-btn primary" type="button" data-profile-action="submit-comment"${state.busy === 'comment' ? ' disabled' : ''}>Отправить</button>
                </div>
            </div>`
            : `<p class="profile-help">Владелец разрешил комментарии только для группы «${this.esc(this.audienceLabel(data.commentPolicy))}».</p>`;

        return `<div class="profile-comments">
            ${composer}
            ${state.commentsLoading && !comments.length ? '<div class="sk sk-contact"></div>' : ''}
            ${comments.length
                ? `<ul class="profile-comment-list">${comments.map(comment => `
                    <li class="profile-comment" data-comment-id="${this.esc(comment.id)}">
                        <div class="profile-comment-ava" data-profile-open="${this.esc(comment.author)}">${this.renderAvatarHTML(comment.author, 'avatar-img', comment.author)}</div>
                        <div class="profile-comment-body">
                            <div class="profile-comment-head">
                                <span class="profile-comment-author" data-profile-open="${this.esc(comment.author)}">${this.esc(comment.author)}</span>
                                <span class="profile-comment-date">${this.esc(this.profileTimestampLabel(comment.createdAt))}</span>
                                ${comment.canDelete ? `<button class="profile-link-remove" type="button" data-profile-action="delete-comment" data-comment-id="${this.esc(comment.id)}" aria-label="Удалить комментарий">${this.uiIcon('close')}</button>` : ''}
                            </div>
                            <p class="profile-comment-text">${this.esc(comment.body)}</p>
                        </div>
                    </li>
                `).join('')}</ul>`
                : (!state.commentsLoading ? '<p class="profile-help">Комментариев пока нет.</p>' : '')}
        </div>`;
    }

    // ------------------------------------------------------------
    // Вкладка «Модерация» (только владелец)
    // ------------------------------------------------------------

    renderProfileModerationTab(state) {
        const pending = Array.isArray(state.pendingAutographs) ? state.pendingAutographs : [];
        if (!pending.length) {
            return `<p class="profile-help">Неодобренных автографов нет. Всё, что приходит, появится здесь — по одному, с кнопками «да» и «нет».</p>`;
        }
        return `<div class="profile-moderation">
            <p class="profile-help">Ниже — автографы, ждущие вашего решения. Одобренные попадут на стену, отклонённые исчезнут.</p>
            <ul class="moderation-list">
                ${pending.map(item => `
                    <li class="moderation-card">
                        <div class="moderation-preview">${this.renderAutographPreview(item)}</div>
                        <div class="moderation-meta">
                            <span class="moderation-author">${this.esc(item.author || '')}</span>
                            <span class="moderation-date">${this.esc(this.profileTimestampLabel(item.createdAt))}</span>
                        </div>
                        <div class="moderation-actions">
                            <button class="auth-btn primary" type="button" data-profile-action="approve-autograph" data-autograph-id="${this.esc(item.id)}">Да</button>
                            <button class="btn-flat" type="button" data-profile-action="reject-autograph" data-autograph-id="${this.esc(item.id)}">Нет</button>
                        </div>
                    </li>
                `).join('')}
            </ul>
        </div>`;
    }

    // ------------------------------------------------------------
    // Вкладка «Друзья» (только свой профиль)
    // ------------------------------------------------------------

    renderProfileFriendsTab(state) {
        const incoming = state.friendRequests?.incoming || [];
        const outgoing = state.friendRequests?.outgoing || [];
        const friends = state.friends || [];

        return `<div class="profile-friends">
            <section class="profile-friends-block">
                <h3>Пригласить в друзья</h3>
                <div class="profile-invite">
                    <input type="text" placeholder="Имя пользователя" data-profile-field="inviteDraft" value="${this.esc(state.inviteDraft || '')}" autocomplete="off">
                    <button class="auth-btn primary" type="button" data-profile-action="send-invite">Отправить</button>
                </div>
                ${state.inviteStatus ? `<p class="profile-help">${this.esc(state.inviteStatus)}</p>` : ''}
            </section>

            <section class="profile-friends-block">
                <h3>Входящие заявки${incoming.length ? ` (${incoming.length})` : ''}</h3>
                ${incoming.length
                    ? `<ul class="profile-people">${incoming.map(request => `
                        <li class="profile-person">
                            <div class="profile-person-ava" data-profile-open="${this.esc(request.requester)}">${this.renderAvatarHTML(request.requester, 'avatar-img', request.requester)}</div>
                            <div class="profile-person-copy">
                                <span class="profile-person-name" data-profile-open="${this.esc(request.requester)}">${this.esc(request.requester)}</span>
                                ${request.message ? `<span class="profile-person-note">${this.esc(request.message)}</span>` : ''}
                            </div>
                            <div class="profile-person-actions">
                                <button class="auth-btn primary" type="button" data-profile-action="accept-friend" data-request-id="${this.esc(request.id)}">Принять</button>
                                <button class="btn-flat" type="button" data-profile-action="decline-friend" data-request-id="${this.esc(request.id)}">Отклонить</button>
                            </div>
                        </li>
                    `).join('')}</ul>`
                    : '<p class="profile-help">Новых заявок нет.</p>'}
            </section>

            <section class="profile-friends-block">
                <h3>Отправленные заявки${outgoing.length ? ` (${outgoing.length})` : ''}</h3>
                ${outgoing.length
                    ? `<ul class="profile-people">${outgoing.map(request => `
                        <li class="profile-person">
                            <div class="profile-person-ava" data-profile-open="${this.esc(request.target)}">${this.renderAvatarHTML(request.target, 'avatar-img', request.target)}</div>
                            <div class="profile-person-copy">
                                <span class="profile-person-name" data-profile-open="${this.esc(request.target)}">${this.esc(request.target)}</span>
                                <span class="profile-person-note">Ждём ответа</span>
                            </div>
                            <div class="profile-person-actions">
                                <button class="btn-flat" type="button" data-profile-action="cancel-friend" data-request-id="${this.esc(request.id)}">Отозвать</button>
                            </div>
                        </li>
                    `).join('')}</ul>`
                    : '<p class="profile-help">Вы никому не отправляли заявок.</p>'}
            </section>

            <section class="profile-friends-block">
                <h3>Друзья${friends.length ? ` (${friends.length})` : ''}</h3>
                ${friends.length
                    ? `<ul class="profile-people">${friends.map(friend => `
                        <li class="profile-person">
                            <div class="profile-person-ava" data-profile-open="${this.esc(friend)}">${this.renderAvatarHTML(friend, 'avatar-img', friend)}</div>
                            <div class="profile-person-copy">
                                <span class="profile-person-name" data-profile-open="${this.esc(friend)}">${this.esc(friend)}</span>
                            </div>
                            <div class="profile-person-actions">
                                <button class="btn-flat" type="button" data-profile-action="remove-friend-named" data-username="${this.esc(friend)}">Удалить</button>
                            </div>
                        </li>
                    `).join('')}</ul>`
                    : '<p class="profile-help">Пока никого.</p>'}
            </section>
        </div>`;
    }

    // ------------------------------------------------------------
    // События оверлея
    // ------------------------------------------------------------

    /**
     * Один делегированный слушатель на весь оверлей — разметка перерисовывается
     * целиком, и вешать обработчики на кнопки поштучно значило бы перевешивать
     * их после каждого рендера (и терять при первом же пропущенном вызове).
     * Вызывается один раз из bindEvents().
     */
    bindProfileEvents() {
        const overlay = document.getElementById('profileOverlay');
        if (!overlay || overlay.dataset.profileBound === '1') return;
        overlay.dataset.profileBound = '1';

        overlay.addEventListener('click', (event) => {
            // Клик по затемнению, а не по карточке — закрыть.
            if (event.target === overlay) {
                this.closeProfile();
                return;
            }
            if (event.target.closest('#profileCloseBtn')) {
                this.closeProfile();
                return;
            }

            const openTarget = event.target.closest('[data-profile-open]');
            if (openTarget) {
                const name = openTarget.getAttribute('data-profile-open');
                if (name) void this.openProfile(name);
                return;
            }

            const tabBtn = event.target.closest('[data-profile-tab]');
            if (tabBtn) {
                this.setProfileTab(tabBtn.getAttribute('data-profile-tab'));
                return;
            }

            const colorBtn = event.target.closest('[data-autograph-color]');
            if (colorBtn) {
                this.setAutographColor(colorBtn.getAttribute('data-autograph-color'));
                return;
            }

            // Кнопки-сегменты вместо системного <select> для полей аудитории
            // (кто может комментировать/оставлять автографы/автоодобрение).
            const audienceBtn = event.target.closest('[data-profile-audience-field]');
            if (audienceBtn) {
                const field = audienceBtn.getAttribute('data-profile-audience-field');
                const value = audienceBtn.getAttribute('data-profile-audience-value');
                if (field && value) {
                    const state = this.ensureProfileState();
                    const draft = { ...(state.draft || this.profileDraftFrom(state.data)) };
                    draft[field] = value;
                    this.setProfileState({ draft });
                }
                return;
            }

            const actionBtn = event.target.closest('[data-profile-action]');
            if (!actionBtn) return;
            this.handleProfileAction(actionBtn.getAttribute('data-profile-action'), actionBtn);
        });

        // input — для текста и ползунков, change — для select и палитры цвета
        // (в них input тоже приходит, но change гарантирован везде).
        overlay.addEventListener('input', (event) => this.handleProfileInput(event));
        overlay.addEventListener('change', (event) => this.handleProfileInput(event));

        overlay.addEventListener('keydown', (event) => {
            if (event.key === 'Escape') {
                this.closeProfile();
                return;
            }
            // Ctrl/Cmd+Enter отправляет комментарий, как и в композере чата.
            if (event.key === 'Enter' && (event.metaKey || event.ctrlKey)) {
                const field = event.target.getAttribute?.('data-profile-field');
                if (field === 'commentDraft') void this.submitProfileComment();
            }
            if (event.key === 'Enter' && event.target.getAttribute?.('data-profile-field') === 'inviteDraft') {
                event.preventDefault();
                void this.submitFriendInvite();
            }
        });
    }

    handleProfileInput(event) {
        const target = event.target;
        if (!target) return;

        const linkIndex = target.getAttribute?.('data-profile-link-index');
        const linkField = target.getAttribute?.('data-profile-link-field');
        if (linkIndex !== null && linkIndex !== undefined && linkField) {
            this.updateProfileDraftLink(Number(linkIndex), linkField, target.value);
            return;
        }

        if (target.hasAttribute?.('data-autograph-width')) {
            this.setAutographWidth(target.value);
            return;
        }

        const field = target.getAttribute?.('data-profile-field');
        if (!field) return;

        if (field === 'commentDraft') {
            // Мимо setProfileState: перерисовка увела бы каретку в конец.
            this.S.profile = { ...this.ensureProfileState(), commentDraft: target.value };
            return;
        }
        if (field === 'inviteDraft') {
            this.S.profile = { ...this.ensureProfileState(), inviteDraft: target.value };
            return;
        }
        this.updateProfileDraft(field, target.value);
    }

    handleProfileAction(action, element) {
        const state = this.ensureProfileState();
        const requestId = element?.getAttribute('data-request-id') || '';
        const autographId = element?.getAttribute('data-autograph-id') || '';

        switch (action) {
            case 'edit': this.startProfileEditing(); break;
            // Выбор файла живёт в bindSettingsEvents (там же, где кроппер и
            // загрузка); здесь мы только зовём его, чтобы не заводить второй
            // конвейер обработки картинки.
            case 'change-avatar': this.openAvatarPicker?.(); break;
            case 'cancel-edit': this.cancelProfileEditing(); break;
            case 'save': void this.saveProfile(); break;
            case 'add-link': this.addProfileDraftLink(); break;
            case 'remove-link':
                this.removeProfileDraftLink(Number(element?.getAttribute('data-profile-link-index')));
                break;
            case 'toggle-follow': void this.toggleFollow(); break;
            case 'add-friend': void this.requestFriendship(); break;
            case 'accept-friend': void this.respondFriendRequest(requestId, 'accept'); break;
            case 'decline-friend': void this.respondFriendRequest(requestId, 'decline'); break;
            case 'cancel-friend': void this.respondFriendRequest(requestId, 'cancel'); break;
            case 'remove-friend': void this.removeFriend(state.username); break;
            case 'remove-friend-named': void this.removeFriend(element?.getAttribute('data-username')); break;
            case 'send-invite': void this.submitFriendInvite(); break;
            case 'message':
                // Переход в диалог — это уход с профиля, оверлей должен закрыться.
                this.closeProfile();
                this.switchChat(state.username);
                break;
            case 'submit-comment': void this.submitProfileComment(); break;
            case 'delete-comment': void this.deleteProfileComment(element?.getAttribute('data-comment-id')); break;
            case 'start-drawing': this.startAutographDrawing(); break;
            case 'cancel-drawing': this.cancelAutographDrawing(); break;
            case 'undo-stroke': this.undoAutographStroke(); break;
            case 'clear-strokes': this.clearAutographStrokes(); break;
            case 'submit-autograph': void this.submitAutograph(); break;
            case 'approve-autograph': void this.moderateAutograph(autographId, 'approve'); break;
            case 'reject-autograph': void this.moderateAutograph(autographId, 'reject'); break;
            case 'remove-autograph': void this.removeAutograph(autographId); break;
            default: break;
        }
    }

});


// --- MODULE: interface/autographs.js ---
// --- ZaliInterface: Векторная стена автографов: рисование, публикация, модерация. ---
// Часть класса ZaliInterface (см. web/src/interface.js).
//
// Всё здесь — вектор, и это не стилистическое предпочтение, а требование к
// формату: автограф хранится списком путей SVG (`d`, цвет, толщина) и
// положением на стене в ДОЛЯХ её ширины/высоты. Ни на одном шаге не возникает
// растра — ни при рисовании (никакого canvas.toDataURL), ни при хранении, ни
// при показе. Поэтому стена одинаково раскладывается на телефоне и на 5K,
// масштабируется без мыла и весит килобайты, а не мегабайты.
//
// Система координат
// -----------------
// Внутри стены всё меряется в её собственных единицах: WALL_W × WALL_H. Указатель
// переводится в них линейно (`preserveAspectRatio="none"` + фиксированный
// aspect-ratio у контейнера дают точное соответствие в обе стороны). При
// публикации рисунок обрезается по своей bbox: штрихи сдвигаются в начало
// координат, bbox становится собственным viewBox автографа, а место на стене
// уезжает в доли. Обратно это собирается вложенным <svg x y width height
// viewBox>, то есть один в один — без накопления ошибок масштабирования.
//
// Производительность
// ------------------
// Во время рисования НИЧЕГО не перерисовывается через innerHTML: на pointerdown
// создаётся один <path>, на pointermove ему меняется атрибут `d`. Полная
// перерисовка оверлея на каждое движение мыши подвесила бы вкладку и заодно
// сорвала бы захват указателя.
ZaliMixin(ZaliInterface, class {

    /** Единицы измерения стены. Отношение фиксировано и совпадает с CSS aspect-ratio. */
    static get WALL_W() { return 1000; }
    static get WALL_H() { return 600; }

    /** Палитра рисования. Совпадает по духу с брендовыми цветами интерфейса. */
    static get autographPalette() {
        return ['#cbff00', '#ffffff', '#ff5c8a', '#4fc3ff', '#ffb347', '#b48cff', '#4be08a', '#111111'];
    }

    static get AUTOGRAPH_MIN_POINT_DISTANCE() { return 1.6; }
    static get AUTOGRAPH_MAX_STROKES() { return 400; }
    static get AUTOGRAPH_MAX_POINTS_PER_STROKE() { return 1200; }

    // ------------------------------------------------------------
    // Загрузка
    // ------------------------------------------------------------

    async loadProfileAutographs() {
        const name = this.ensureProfileState().username;
        if (!name) return;
        this.setProfileState({ autographsLoading: true });
        try {
            const res = await this.apiFetch(this.apiRoutes.profiles.autographs(name, 'approved'));
            if (this.ensureProfileState().username !== name) return;
            if (!res.ok) {
                this.setProfileState({ autographsLoading: false, autographs: [] });
                return;
            }
            const body = await res.json();
            this.setProfileState({
                autographsLoading: false,
                autographs: Array.isArray(body?.autographs) ? body.autographs : [],
            });
        } catch (e) {
            this.setProfileState({ autographsLoading: false });
        }
    }

    /** Очередь модерации. Сервер отдаёт её только владельцу стены. */
    async loadPendingAutographs() {
        const state = this.ensureProfileState();
        const name = state.username;
        if (!name || !state.data?.isSelf) return;
        try {
            const res = await this.apiFetch(this.apiRoutes.profiles.autographs(name, 'pending'));
            if (this.ensureProfileState().username !== name) return;
            if (!res.ok) return;
            const body = await res.json();
            this.setProfileState({
                pendingAutographs: Array.isArray(body?.autographs) ? body.autographs : [],
            });
        } catch (e) {
            // Не критично: очередь перечитается при следующем заходе на вкладку.
        }
    }

    async moderateAutograph(autographId, action) {
        const id = String(autographId || '').trim();
        if (!id) return;
        const state = this.ensureProfileState();
        // Оптимистично убираем карточку из очереди — ответ «да/нет» должен
        // ощущаться мгновенным, а список всё равно перечитывается следом.
        this.setProfileState({
            pendingAutographs: (state.pendingAutographs || []).filter(item => item.id !== id),
        });
        try {
            const res = await this.apiFetch(this.apiRoutes.profiles.autographModeration(id), {
                method: 'POST',
                interactive: true,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action }),
            });
            if (!res.ok) {
                await this.loadPendingAutographs();
                return;
            }
            if (action === 'approve') await this.loadProfileAutographs();
            await this.refreshProfile();
        } catch (e) {
            await this.loadPendingAutographs();
        }
    }

    /** Убрать чужой автограф со стены (владелец) или свой (автор). */
    async removeAutograph(autographId) {
        const id = String(autographId || '').trim();
        if (!id) return;
        const state = this.ensureProfileState();
        this.setProfileState({ autographs: (state.autographs || []).filter(item => item.id !== id) });
        try {
            await this.apiFetch(this.apiRoutes.profiles.autographModeration(id), {
                method: 'POST',
                interactive: true,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: 'delete' }),
            });
        } catch (e) {
            await this.loadProfileAutographs();
        }
    }

    // ------------------------------------------------------------
    // Отрисовка
    // ------------------------------------------------------------

    /** Округление до 0.1 единицы: экономит байты и не влияет на вид. */
    autographRound(value) {
        return Math.round((Number(value) || 0) * 10) / 10;
    }

    /**
     * Гладкая кривая по точкам: середины отрезков как опорные точки, сами
     * точки — как контрольные. Ломаная из `L` на подписи выглядит рублеными
     * гранями, особенно на медленном движении мыши.
     * Алфавит — только `M`/`Q`/`L`, числа и разделители, то есть ровно то, что
     * пропускает валидатор на сервере.
     */
    autographPathData(points) {
        const list = Array.isArray(points) ? points : [];
        if (!list.length) return '';
        const r = (n) => this.autographRound(n);
        if (list.length === 1) {
            // Точка-клик: нулевой длины путь не рисуется вообще, поэтому даём
            // ему микроскопическую длину — с круглым linecap это ровная точка.
            const p = list[0];
            return `M ${r(p.x)} ${r(p.y)} L ${r(p.x + 0.1)} ${r(p.y)}`;
        }
        let d = `M ${r(list[0].x)} ${r(list[0].y)}`;
        for (let i = 1; i < list.length - 1; i++) {
            const mx = (list[i].x + list[i + 1].x) / 2;
            const my = (list[i].y + list[i + 1].y) / 2;
            d += ` Q ${r(list[i].x)} ${r(list[i].y)} ${r(mx)} ${r(my)}`;
        }
        const last = list[list.length - 1];
        d += ` L ${r(last.x)} ${r(last.y)}`;
        return d;
    }

    /** Один автограф как вложенный <svg>: своя система координат внутри бокса на стене. */
    renderAutographNode(autograph, { interactive = true } = {}) {
        const W = ZaliInterface.WALL_W;
        const H = ZaliInterface.WALL_H;
        const x = this.autographRound((Number(autograph?.x) || 0) * W);
        const y = this.autographRound((Number(autograph?.y) || 0) * H);
        const width = Math.max(1, this.autographRound((Number(autograph?.width) || 0) * W));
        const height = Math.max(1, this.autographRound((Number(autograph?.height) || 0) * H));
        const rotation = Number(autograph?.rotation) || 0;
        const viewBox = this.esc(String(autograph?.viewBox || '0 0 100 100'));
        const author = String(autograph?.author || '');
        const paths = (Array.isArray(autograph?.strokes) ? autograph.strokes : []).map(stroke => (
            `<path d="${this.esc(stroke?.d || '')}" fill="none" stroke="${this.esc(this.safeCssColor(stroke?.color) || '#cbff00')}" stroke-width="${Number(stroke?.width) || 2}" stroke-linecap="round" stroke-linejoin="round"></path>`
        )).join('');

        const inner = `<svg x="${x}" y="${y}" width="${width}" height="${height}" viewBox="${viewBox}" preserveAspectRatio="none" overflow="visible">${paths}</svg>`;
        const rotated = rotation
            ? `<g transform="rotate(${this.autographRound(rotation)} ${this.autographRound(x + width / 2)} ${this.autographRound(y + height / 2)})">${inner}</g>`
            : inner;

        if (!interactive) return rotated;
        return `<g class="autograph-node" data-autograph-id="${this.esc(autograph?.id || '')}" data-autograph-author="${this.esc(author)}">
            <title>${this.esc(`Автограф: ${author}`)}</title>
            ${rotated}
        </g>`;
    }

    /** Сетка фона — тоже вектор, паттерном, а не картинкой. */
    renderAutographWallDefs() {
        return `<defs>
            <pattern id="autographGrid" width="50" height="50" patternUnits="userSpaceOnUse">
                <path d="M 50 0 L 0 0 0 50" fill="none" stroke="currentColor" stroke-width="1" opacity="0.10"></path>
            </pattern>
        </defs>`;
    }

    renderAutographWall() {
        const state = this.ensureProfileState();
        const W = ZaliInterface.WALL_W;
        const H = ZaliInterface.WALL_H;
        const drawing = state.drawing;
        const approved = Array.isArray(state.autographs) ? state.autographs : [];

        const nodes = approved.map(item => this.renderAutographNode(item)).join('');
        const empty = !approved.length && !drawing
            ? `<text x="${W / 2}" y="${H / 2}" text-anchor="middle" dominant-baseline="middle" class="autograph-wall-empty-text">Стена пуста — оставьте первый автограф</text>`
            : '';

        return `<div class="autograph-wall${drawing ? ' drawing' : ''}" id="autographWall">
            <svg class="autograph-wall-svg" id="autographWallSvg" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="Стена автографов">
                ${this.renderAutographWallDefs()}
                <rect x="0" y="0" width="${W}" height="${H}" fill="url(#autographGrid)"></rect>
                <g class="autograph-wall-nodes">${nodes}</g>
                ${empty}
                <g class="autograph-draft-layer" id="autographDraftLayer"></g>
            </svg>
        </div>`;
    }

    /** Маленький превью-SVG для карточки в очереди модерации. */
    renderAutographPreview(autograph) {
        const viewBox = this.esc(String(autograph?.viewBox || '0 0 100 100'));
        const paths = (Array.isArray(autograph?.strokes) ? autograph.strokes : []).map(stroke => (
            `<path d="${this.esc(stroke?.d || '')}" fill="none" stroke="${this.esc(this.safeCssColor(stroke?.color) || '#cbff00')}" stroke-width="${Number(stroke?.width) || 2}" stroke-linecap="round" stroke-linejoin="round"></path>`
        )).join('');
        return `<svg class="autograph-preview-svg" viewBox="${viewBox}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Автограф">${paths}</svg>`;
    }

    // ------------------------------------------------------------
    // Рисование
    // ------------------------------------------------------------

    startAutographDrawing() {
        const state = this.ensureProfileState();
        if (!state.data?.canAutograph) return;
        this.setProfileState({
            tab: 'wall',
            drawing: {
                strokes: [],
                color: ZaliInterface.autographPalette[0],
                width: 4,
                submitting: false,
                error: '',
            },
        });
    }

    cancelAutographDrawing({ silent = false } = {}) {
        const state = this.S.profile;
        if (!state?.drawing) return;
        this._autographActiveStroke = null;
        this._autographActivePath = null;
        if (silent) {
            // Закрытие оверлея: перерисовывать нечего и незачем.
            this.S.profile = { ...state, drawing: null };
            return;
        }
        this.setProfileState({ drawing: null });
    }

    setAutographColor(color) {
        const state = this.ensureProfileState();
        if (!state.drawing) return;
        const safe = this.safeCssColor(color) || ZaliInterface.autographPalette[0];
        this.setProfileState({ drawing: { ...state.drawing, color: safe } });
    }

    setAutographWidth(width) {
        const state = this.ensureProfileState();
        if (!state.drawing) return;
        const value = Math.min(40, Math.max(1, Number(width) || 4));
        this.setProfileState({ drawing: { ...state.drawing, width: value } });
    }

    undoAutographStroke() {
        const state = this.ensureProfileState();
        if (!state.drawing) return;
        const strokes = (state.drawing.strokes || []).slice(0, -1);
        this.setProfileState({ drawing: { ...state.drawing, strokes } });
    }

    clearAutographStrokes() {
        const state = this.ensureProfileState();
        if (!state.drawing) return;
        this.setProfileState({ drawing: { ...state.drawing, strokes: [] } });
    }

    /**
     * Клиентские координаты → единицы стены. Внешний svg объявлен с
     * `preserveAspectRatio="none"`, поэтому отображение линейно по обеим осям
     * и обратимо без поправок на «letterbox».
     */
    autographPointFromEvent(svg, event) {
        const rect = svg.getBoundingClientRect();
        if (!rect.width || !rect.height) return null;
        const x = ((event.clientX - rect.left) / rect.width) * ZaliInterface.WALL_W;
        const y = ((event.clientY - rect.top) / rect.height) * ZaliInterface.WALL_H;
        return {
            x: Math.min(ZaliInterface.WALL_W, Math.max(0, x)),
            y: Math.min(ZaliInterface.WALL_H, Math.max(0, y)),
        };
    }

    /**
     * Навешивает обработчики указателя на свежеотрисованную стену. Вызывается
     * из рендера профиля: узлы заменяются целиком, поэтому слушатели каждый раз
     * ставятся заново — на новый элемент, а не на выброшенный старый.
     */
    bindAutographSurface() {
        const svg = document.getElementById('autographWallSvg');
        if (!svg || svg.dataset.autographBound === '1') return;
        svg.dataset.autographBound = '1';

        const draftLayer = () => document.getElementById('autographDraftLayer');

        const beginStroke = (event) => {
            const state = this.ensureProfileState();
            if (!state.drawing) return;
            if (event.button !== undefined && event.button !== 0) return;
            if ((state.drawing.strokes || []).length >= ZaliInterface.AUTOGRAPH_MAX_STROKES) return;
            const point = this.autographPointFromEvent(svg, event);
            if (!point) return;
            event.preventDefault();
            try { svg.setPointerCapture(event.pointerId); } catch (e) {}

            this._autographActiveStroke = {
                points: [point],
                color: state.drawing.color,
                width: state.drawing.width,
            };
            const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            path.setAttribute('fill', 'none');
            path.setAttribute('stroke', this._autographActiveStroke.color);
            path.setAttribute('stroke-width', String(this._autographActiveStroke.width));
            path.setAttribute('stroke-linecap', 'round');
            path.setAttribute('stroke-linejoin', 'round');
            path.setAttribute('d', this.autographPathData(this._autographActiveStroke.points));
            draftLayer()?.appendChild(path);
            this._autographActivePath = path;
        };

        const extendStroke = (event) => {
            const stroke = this._autographActiveStroke;
            if (!stroke || !this._autographActivePath) return;
            const point = this.autographPointFromEvent(svg, event);
            if (!point) return;
            const last = stroke.points[stroke.points.length - 1];
            const dx = point.x - last.x;
            const dy = point.y - last.y;
            // Прореживание по расстоянию: указатель сыплет событиями чаще, чем
            // это различимо глазом, а каждая лишняя точка — байты в базе и
            // работа при каждом показе стены.
            if (dx * dx + dy * dy < ZaliInterface.AUTOGRAPH_MIN_POINT_DISTANCE ** 2) return;
            if (stroke.points.length >= ZaliInterface.AUTOGRAPH_MAX_POINTS_PER_STROKE) return;
            stroke.points.push(point);
            this._autographActivePath.setAttribute('d', this.autographPathData(stroke.points));
        };

        const endStroke = (event) => {
            const stroke = this._autographActiveStroke;
            this._autographActiveStroke = null;
            this._autographActivePath = null;
            if (event?.pointerId !== undefined) {
                try { svg.releasePointerCapture(event.pointerId); } catch (e) {}
            }
            if (!stroke || !stroke.points.length) return;
            const state = this.ensureProfileState();
            if (!state.drawing) return;
            // Штрих переезжает в состояние, и перерисовка стены показывает его
            // уже из общего списка — черновой слой при этом очищается.
            this.setProfileState({
                drawing: { ...state.drawing, strokes: [...(state.drawing.strokes || []), stroke], error: '' },
            });
        };

        svg.addEventListener('pointerdown', beginStroke);
        svg.addEventListener('pointermove', extendStroke);
        svg.addEventListener('pointerup', endStroke);
        svg.addEventListener('pointercancel', endStroke);
        // Уход указателя за пределы окна без pointerup (частый случай при
        // быстром росчерке к краю) иначе оставил бы штрих незакрытым навсегда.
        svg.addEventListener('pointerleave', (event) => {
            if (this._autographActiveStroke) endStroke(event);
        });
    }

    /** Черновые штрихи рисуются из состояния — вызывается после каждой перерисовки стены. */
    renderAutographDraft() {
        const layer = document.getElementById('autographDraftLayer');
        if (!layer) return;
        const drawing = this.ensureProfileState().drawing;
        if (!drawing) {
            layer.innerHTML = '';
            return;
        }
        layer.innerHTML = (drawing.strokes || []).map(stroke => (
            `<path d="${this.esc(this.autographPathData(stroke.points))}" fill="none" stroke="${this.esc(this.safeCssColor(stroke.color) || '#cbff00')}" stroke-width="${Number(stroke.width) || 4}" stroke-linecap="round" stroke-linejoin="round"></path>`
        )).join('');
    }

    /**
     * Обрезает рисунок по его собственной bbox и отправляет.
     *
     * Сдвиг в начало координат — не косметика: без него viewBox автографа был бы
     * размером со всю стену, и рисунок в углу занимал бы прямоугольник во всю
     * стену, перекрывая соседей своей (пустой) областью.
     */
    async submitAutograph() {
        const state = this.ensureProfileState();
        const drawing = state.drawing;
        const owner = state.username;
        if (!drawing || !owner || drawing.submitting) return;
        const strokes = (drawing.strokes || []).filter(stroke => stroke.points?.length);
        if (!strokes.length) {
            this.setProfileState({ drawing: { ...drawing, error: 'Сначала нарисуйте что-нибудь' } });
            return;
        }

        let minX = Infinity;
        let minY = Infinity;
        let maxX = -Infinity;
        let maxY = -Infinity;
        strokes.forEach(stroke => {
            // Половина толщины с каждой стороны: иначе край штриха обрезался бы
            // границей viewBox, и вся линия выглядела бы «съеденной».
            const pad = (Number(stroke.width) || 4) / 2 + 1;
            stroke.points.forEach(point => {
                minX = Math.min(minX, point.x - pad);
                minY = Math.min(minY, point.y - pad);
                maxX = Math.max(maxX, point.x + pad);
                maxY = Math.max(maxY, point.y + pad);
            });
        });
        const boxWidth = Math.max(1, maxX - minX);
        const boxHeight = Math.max(1, maxY - minY);

        const payloadStrokes = strokes.map(stroke => ({
            d: this.autographPathData(stroke.points.map(point => ({ x: point.x - minX, y: point.y - minY }))),
            color: this.safeCssColor(stroke.color) || '#cbff00',
            width: Number(stroke.width) || 4,
        }));

        this.setProfileState({ drawing: { ...drawing, submitting: true, error: '' } });
        try {
            const res = await this.apiFetch(this.apiRoutes.profiles.autographs(owner), {
                method: 'POST',
                interactive: true,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    strokes: payloadStrokes,
                    viewBox: `0 0 ${this.autographRound(boxWidth)} ${this.autographRound(boxHeight)}`,
                    x: minX / ZaliInterface.WALL_W,
                    y: minY / ZaliInterface.WALL_H,
                    width: boxWidth / ZaliInterface.WALL_W,
                    height: boxHeight / ZaliInterface.WALL_H,
                    rotation: 0,
                }),
            });
            if (res.status === 403) {
                this.setProfileState({ drawing: { ...this.ensureProfileState().drawing, submitting: false, error: 'Владелец закрыл автографы для вас' } });
                return;
            }
            if (!res.ok) {
                const message = await res.text().catch(() => '');
                this.setProfileState({ drawing: { ...this.ensureProfileState().drawing, submitting: false, error: message || 'Не удалось отправить автограф' } });
                return;
            }
            const body = await res.json().catch(() => ({}));
            this.setProfileState({ drawing: null });
            this.addLogEntry({
                type: 'SUCCESS',
                msg: body?.status === 'approved'
                    ? 'Автограф добавлен на стену'
                    : 'Автограф отправлен на одобрение владельцу',
                ts: new Date().toLocaleTimeString(),
            });
            await this.loadProfileAutographs();
        } catch (e) {
            const current = this.ensureProfileState().drawing;
            if (current) {
                this.setProfileState({ drawing: { ...current, submitting: false, error: 'Не удалось отправить автограф' } });
            }
        }
    }

});


// --- MODULE: interface/diagnostics.js ---
// --- ZaliInterface: Журнал диагностики и голосовая телеметрия. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    addLogEntry({ type, msg, ts }) {
        // Mirror to console so the native console-hook persists the full in-app
        // journal to zali-debug.log on disk (readable without the UI).
        try { console.log(`[ZALI][JOURNAL] ${type}: ${msg}`); } catch (e) {}
        const body = document.getElementById('logBody');
        if (body) {
            const div = document.createElement('div');
            div.className = `log-entry log-${type}`;
            div.innerHTML = `<span class="ts">[${ts}]</span>${this.esc(type)}: ${this.esc(msg)}`;
            body.appendChild(div);
            body.scrollTop = body.scrollHeight;
            if (body.childElementCount > 300) body.removeChild(body.firstElementChild);
        }
    }

    // Always-on counterpart of voiceTrace, for the handful of facts that decide
    // whether a call carries audio: ICE/connection state, which candidate pair won
    // (host/srflx/relay), and why a link died. voiceTrace is gated behind a dev
    // toggle nobody has enabled *before* a call goes wrong, which is exactly when
    // the data is needed — every failed call so far had to be diagnosed from the
    // server's signalling log alone, which cannot see ICE at all. A handful of lines
    // per call; on macOS they land in zali-debug.log via the console mirror.
    voiceDiag(stage, details = {}, level = 'INFO') {
        const ts = new Date().toLocaleTimeString();
        const compact = this.formatVoiceDetails(details);
        const message = compact ? `${stage} ${compact}` : stage;
        // Kept whatever the dev trace toggle says, and kept ACROSS calls: the
        // question asked after a bad call is always "what happened", and by then
        // voice.traceLines has been wiped by resetVoiceState and the 14-line window
        // was long gone anyway. This ring is the record that survives to be read.
        this.pushVoiceDiagLine({ ts, level, stage, message });
        if (this.voiceTraceEnabled) {
            // Trace prints the same line with the full detail objects; printing it
            // twice would only double the journal.
            this.voiceTrace(stage, details, level);
            return;
        }
        this.addLogEntry({ type: level, msg: `[VOICE] ${message}`, ts });
        try {
            const fn = level === 'ERROR' ? console.error : level === 'WARN' ? console.warn : console.log;
            fn?.('[VOICE]', message);
        } catch (e) {}
    }

    // One formatter for both voiceDiag and voiceTrace, so a line reads the same
    // whichever of the two produced it — a log where the same fact is spelled two
    // ways cannot be grepped, and grepping it is the entire point.
    formatVoiceDetails(details = {}) {
        return Object.entries(details)
            .filter(([, value]) => value !== undefined && value !== null && value !== '')
            .map(([key, value]) => {
                if (Array.isArray(value)) {
                    const hasObjects = value.some(item => item !== null && typeof item === 'object');
                    if (hasObjects) {
                        try { return `${key}=${JSON.stringify(value)}`; } catch (e) { return `${key}=[object]`; }
                    }
                    return `${key}=[${value.join(',')}]`;
                }
                if (typeof value === 'object') {
                    try { return `${key}=${JSON.stringify(value)}`; } catch (e) { return `${key}=[object]`; }
                }
                return `${key}=${String(value)}`;
            })
            .join(' ');
    }

    // Bounded and deliberately NOT part of this.voice: resetVoiceState clears voice
    // state at the exact moment the interesting call ends, so anything kept there is
    // erased before anyone can look at it. 400 lines is a couple of full calls with
    // per-peer health sampling, and each line is a short string — no payloads, no
    // MediaStream references, nothing that can pin memory (see the perf invariants
    // in CLAUDE.md).
    pushVoiceDiagLine(line) {
        const ring = this._voiceDiagRing || (this._voiceDiagRing = []);
        ring.push(line);
        if (ring.length > 400) ring.splice(0, ring.length - 400);
    }

    // A rebuilt peer connection loses every counter it was carrying, so the tally
    // lives on the call instead of the entry. Rebuilds are the loudest signal that a
    // link was fighting the session state rather than the network: one is routine
    // recovery, five in a call means something upstream keeps producing offers this
    // side cannot take.
    countVoicePeerRebuild(peer, reason = '') {
        this.voice.rebuilds = Number(this.voice.rebuilds || 0) + 1;
        this.voiceDiag('peer-rebuild', {
            peer,
            reason,
            roomId: this.voice.roomId || '',
            total: this.voice.rebuilds,
            ...this.voicePeerSnapshot(peer),
        }, 'WARN');
    }

    // The whole ring as text, newest last — what to paste into a bug report. Also
    // what the "скопировать диагностику" control in the voice panel hands over.
    dumpVoiceDiagnostics() {
        const ring = Array.isArray(this._voiceDiagRing) ? this._voiceDiagRing : [];
        return ring.map(line => `[${line.ts}] ${line.level} ${line.message}`).join('\n');
    }

    // Compact, always-cheap description of one peer link. Every diagnostic that
    // names a peer includes it, so a single line answers "in what state did this
    // happen" without cross-referencing three others.
    voicePeerSnapshot(peer) {
        const entry = this.voice.peerConnections.get(String(peer || '').trim());
        if (!entry?.pc) return {};
        return {
            pcState: entry.pc.connectionState || '',
            ice: entry.pc.iceConnectionState || '',
            gathering: entry.pc.iceGatheringState || '',
            signaling: entry.pc.signalingState || '',
            offerSent: !!entry.offerSent,
            negotiating: !!entry.negotiating,
            renegPending: !!entry.renegotiationPending,
            needsIceRestart: !!entry.needsIceRestart,
            answerWatchdog: !!entry.answerWatchdog,
            answerRetries: Number(entry.answerRetries || 0),
            linkRecovery: Number(entry.linkRecoveryAttempts || 0),
            candOut: Number(entry.generatedIceCandidates || 0),
            candIn: Number(entry.receivedIceCandidates || 0),
            candTypes: entry.gatheredCandidateTypes ? Array.from(entry.gatheredCandidateTypes).join('/') : '',
            pendingIce: entry.pendingIceCandidates?.length || 0,
        };
    }

    // Answers "connected but silent" without guesswork, on a real call: does RTP
    // actually arrive, and is the sink able to play it? Every silent call so far had
    // to be argued about from first principles because nothing recorded these two
    // facts together. One line per peer every 10 s, always on.
    async reportVoiceAudioHealth(peer) {
        const entry = this.voice.peerConnections.get(peer);
        if (!entry?.pc?.getStats) return;
        try {
            const stats = await entry.pc.getStats();
            let inPackets = 0;
            let inBytes = 0;
            let inLost = 0;
            let inJitter = null;
            let level = null;
            let concealed = null;
            let outPackets = 0;
            let outBytes = 0;
            let outLevel = null;
            // remote-inbound-rtp is what the PEER reports about OUR stream. It is the
            // only view of the upstream direction we have: local outbound counters
            // rise happily while every packet is dropped in the network, so "we are
            // sending" and "they are receiving" are different questions and only this
            // report answers the second one.
            let remoteLost = null;
            let remoteJitter = null;
            let rtt = null;
            let availableOut = null;
            stats.forEach(report => {
                const isAudio = report.kind === 'audio' || report.mediaType === 'audio';
                if (report.type === 'inbound-rtp' && isAudio) {
                    inPackets = report.packetsReceived ?? inPackets;
                    inBytes = report.bytesReceived ?? inBytes;
                    inLost = report.packetsLost ?? inLost;
                    if (typeof report.jitter === 'number') inJitter = report.jitter;
                    if (typeof report.audioLevel === 'number') level = report.audioLevel;
                    if (typeof report.concealedSamples === 'number') concealed = report.concealedSamples;
                }
                if (report.type === 'outbound-rtp' && isAudio) {
                    outPackets = report.packetsSent ?? outPackets;
                    outBytes = report.bytesSent ?? outBytes;
                }
                if (report.type === 'media-source' && isAudio && typeof report.audioLevel === 'number') {
                    outLevel = report.audioLevel;
                }
                if (report.type === 'remote-inbound-rtp' && isAudio) {
                    if (typeof report.packetsLost === 'number') remoteLost = report.packetsLost;
                    if (typeof report.jitter === 'number') remoteJitter = report.jitter;
                    if (typeof report.roundTripTime === 'number') rtt = report.roundTripTime;
                }
                if (report.type === 'candidate-pair' && (report.selected || (report.state === 'succeeded' && report.nominated))) {
                    if (typeof report.currentRoundTripTime === 'number') rtt = report.currentRoundTripTime;
                    if (typeof report.availableOutgoingBitrate === 'number') availableOut = report.availableOutgoingBitrate;
                }
            });
            const audio = this.voice.remoteAudios.get(peer);
            const prevIn = entry.lastInboundBytes || 0;
            const prevOut = entry.lastOutboundBytes || 0;
            entry.lastInboundBytes = inBytes;
            entry.lastOutboundBytes = outBytes;
            const arriving = inBytes > prevIn;
            // A dead upstream is as silent as a dead downstream and used to be
            // invisible here: the old line reported only what we RECEIVE, so "он меня
            // не слышит" had no evidence at all. A muted mic legitimately stops the
            // byte counter, so mute is reported next to it rather than mixed into the
            // verdict.
            const sending = outBytes > prevOut;
            const localTrack = this.voice.localStream?.getAudioTracks?.()[0] || null;
            // This used to only *report* a paused or muted sink. Reporting it is the
            // hard part, but doing nothing about it means the one condition we can
            // actually fix is the one we watch go by every 10 s — retry the playback
            // as well. It costs a play() call and is a no-op when the sink is healthy.
            if (audio && (audio.paused || (audio.muted && !this.voice.deafened))) {
                this.syncRemoteAudioPlaybackMode();
            }
            const snapshot = this.voicePeerSnapshot(peer);
            // "No RTP" is only a fault once the link claims to be up. Before that it
            // is just a call in the middle of connecting, and a WARN on every single
            // call — several per peer in a group — is how a diagnostic line stops
            // being read at all. The failure of a link that never connects is
            // reported by pc-state and link-recovery, which are about that.
            const live = snapshot.pcState === 'connected' || snapshot.pcState === 'completed';
            const healthy = arriving
                && (sending || this.voice.muted)
                && !!audio && !audio.paused && (!audio.muted || this.voice.deafened);
            this.voiceDiag('audio-health', {
                peer,
                roomId: this.voice.roomId || '',
                rx: arriving ? 'flowing' : 'STALLED',
                tx: sending ? 'flowing' : (this.voice.muted ? 'muted' : 'STALLED'),
                pcState: snapshot.pcState || '',
                ice: snapshot.ice || '',
                signaling: snapshot.signaling || '',
                inPackets,
                inBytes,
                inLost,
                inJitter: inJitter === null ? '' : inJitter.toFixed(4),
                concealed: concealed === null ? '' : concealed,
                outPackets,
                outBytes,
                peerLost: remoteLost === null ? '' : remoteLost,
                peerJitter: remoteJitter === null ? '' : remoteJitter.toFixed(4),
                rtt: rtt === null ? '' : rtt.toFixed(3),
                availOutKbps: availableOut === null ? '' : Math.round(availableOut / 1000),
                rxLevel: level === null ? '' : level.toFixed(3),
                txLevel: outLevel === null ? '' : outLevel.toFixed(3),
                sink: audio ? (audio.muted ? 'MUTED' : audio.paused ? 'PAUSED' : 'playing') : 'NO ELEMENT',
                volume: audio ? audio.volume : '',
                ctx: this.voice.audioContext?.state || 'none',
                mic: localTrack ? `${localTrack.readyState}:${localTrack.enabled ? 'on' : 'off'}` : 'none',
                muted: !!this.voice.muted,
                deafened: !!this.voice.deafened,
                candTypes: snapshot.candTypes || '',
            }, (healthy || !live) ? 'INFO' : 'WARN');
        } catch (error) {
            this.voiceDiag('audio-health-failed', { peer, error: error?.message || String(error) }, 'WARN');
        }
    }

    // Written once when a call ends, from resetVoiceState, while the peer entries
    // still exist. Answers "how did that call actually go" in one line per peer —
    // without it the only record is a scattering of per-event lines whose totals
    // nobody reconstructs by hand.
    logVoiceCallSummary(reason = 'end') {
        const roomId = String(this.voice.roomId || '').trim();
        if (!roomId && !this.voice.peerConnections.size) return;
        const track = this.voice.callTrack || null;
        const startedAt = Number(track?.startedAt || 0);
        const connectedAt = Number(track?.connectedAt || 0);
        this.voiceDiag('call-summary', {
            reason,
            roomId,
            roomType: this.voice.roomType || '',
            status: this.voice.status || '',
            peers: this.voice.peerConnections.size,
            participants: Array.isArray(this.voice.participants) ? this.voice.participants : [],
            setupMs: startedAt && connectedAt ? connectedAt - startedAt : '',
            talkMs: connectedAt ? Date.now() - connectedAt : '',
            outcome: track?.outcome || '',
            micError: this.voice.micError || '',
            negotiationRetries: Number(this.voice.negotiationRetries || 0),
            peerRebuilds: Number(this.voice.rebuilds || 0),
            ctx: this.voice.audioContext?.state || 'none',
            playbackUnlocked: !!this.voice.playbackUnlocked,
        }, 'INFO');
        for (const [peer, entry] of this.voice.peerConnections) {
            const stats = entry.lastStats || {};
            this.voiceDiag('call-summary-peer', {
                peer,
                ...this.voicePeerSnapshot(peer),
                inBytes: stats.inBytes ?? entry.lastInboundBytes ?? '',
                outBytes: stats.outBytes ?? entry.lastOutboundBytes ?? '',
                inPackets: stats.inPackets ?? '',
                outPackets: stats.outPackets ?? '',
                selectedPair: stats.candidatePair
                    ? `${stats.candidatePair.localLabel || ''}<->${stats.candidatePair.remoteLabel || ''}`
                    : '',
                iceRestarts: Number(entry.iceRestartCount || 0),
                exhausted: !!entry.linkRecoveryExhausted,
            }, entry.linkRecoveryExhausted ? 'WARN' : 'INFO');
        }
    }

    // Names the candidate pair actually carrying media, which is the difference
    // between "ICE said connected" and "audio has a path". Read once per successful
    // connect, so it costs one getStats() call per peer per call.
    async reportVoiceSelectedPair(peer) {
        const entry = this.voice.peerConnections.get(peer);
        if (!entry?.pc?.getStats) return;
        try {
            const stats = await entry.pc.getStats();
            const byId = new Map();
            let pair = null;
            stats.forEach(report => {
                byId.set(report.id, report);
                if (report.type === 'candidate-pair' && (report.selected || report.state === 'succeeded' && report.nominated)) {
                    pair = report;
                }
            });
            if (!pair) return;
            const local = byId.get(pair.localCandidateId);
            const remote = byId.get(pair.remoteCandidateId);
            this.voiceDiag('selected-pair', {
                peer,
                local: local ? `${local.candidateType}/${local.protocol}` : '?',
                remote: remote ? `${remote.candidateType}/${remote.protocol}` : '?',
                rtt: pair.currentRoundTripTime ?? '',
                bytesIn: pair.bytesReceived ?? '',
                bytesOut: pair.bytesSent ?? '',
            }, 'SUCCESS');
        } catch (error) {
            this.voiceDiag('selected-pair-failed', { peer, error: error?.message || String(error) }, 'WARN');
        }
    }

    voiceTrace(stage, details = {}, level = 'INFO') {
        if (!this.voiceTraceEnabled) return;
        const ts = new Date().toLocaleTimeString();
        const compact = this.formatVoiceDetails(details);
        const message = compact ? `${stage} ${compact}` : stage;
        this.voice.traceLines = Array.isArray(this.voice.traceLines) ? this.voice.traceLines : [];
        this.voice.traceLines.push({ ts, level, stage, message });
        if (this.voice.traceLines.length > 14) {
            this.voice.traceLines.splice(0, this.voice.traceLines.length - 14);
        }
        this.addLogEntry({ type: level, msg: `[VOICE] ${message}`, ts });
        try {
            const fn = level === 'ERROR' ? console.error : level === 'WARN' ? console.warn : console.debug;
            fn?.('[VOICE]', stage, details);
        } catch (e) {}
    }
});


// --- MODULE: interface/events.js ---
// --- ZaliInterface: Привязка DOM-событий и инерция прокрутки. ---
// Часть класса ZaliInterface (см. web/src/interface.js). Тела методов
// перенесены сюда дословно; ZaliMixin копирует дескрипторы на прототип,
// поэтому поведение и неперечисляемость методов те же, что у class-тела.
ZaliMixin(ZaliInterface, class {

    // --- UI Event Binding ---

    bindEvents() {
        // Метод был на 1512 строк. Разложен по назначению; порядок вызовов —
        // порядок исходных блоков, поэтому очерёдность регистрации слушателей
        // на одном и том же элементе не изменилась.
        this.bindContactListEvents();                     // списки контактов и каналов сервера
        this.bindVoicePanelEvents();                      // голосовая панель и плитки участников
        this.bindChatHeaderEvents();                      // шапка чата: звонок, видео, кнопка «назад»
        this.bindMessageListEvents();                     // список сообщений: реакции, ссылки, контекстное меню
        this.bindContactAddEvents();                      // добавление контакта и подсказки
        this.bindComposerEvents();                        // композер, вложения, перевод ZaliCoin, модалка обновления
        this.bindMessageInputEvents();                    // поле ввода: ввод, вставка, drag-and-drop
        this.bindSearchAndModeEvents();                   // поиск, переключение режима и сегментов хаба
        this.bindAuthEvents();                            // экран входа: форма, сеть, гость
        this.bindSettingsEvents();                        // настройки, сетевая конфигурация и модалка сервера
        this.bindStylerEvents();                          // выбор темы и селекторы стилизатора
        this.bindStyleSliderEvents();                     // слайдеры оформления
        this.bindCryptoKeyEvents();                       // ручной ввод ключа шифрования
        this.bindWindowChromeEvents();                    // перетаскивание окна, ресайз, горячие клавиши
        this.bindProfileEvents();                         // оверлей профиля: вкладки, комментарии, стена автографов
    }

    /** Списки контактов и каналов сервера. Вызывается только из bindEvents(). */
    bindContactListEvents() {
        // 1. Click on contacts
        const contactsEl = document.getElementById('contacts');
        if (contactsEl) {
            contactsEl.addEventListener('click', (e) => {
                const serverBtn = e.target.closest('.server-item[data-server-id]');
                if (serverBtn) {
                    const serverId = serverBtn.getAttribute('data-server-id');
                    if (serverId) {
                        this.closeChatPanelModals();
                        this.setActiveServer(serverId);
                    }
                    e.stopPropagation();
                    return;
                }
                const createBtn = e.target.closest('.server-create');
                if (createBtn) {
                    this.openServerModal('create');
                    e.stopPropagation();
                    return;
                }
                const joinBtn = e.target.closest('.server-join');
                if (joinBtn) {
                    this.openJoinCodeModal();
                    e.stopPropagation();
                    return;
                }
                const publicBtn = e.target.closest('.server-public');
                if (publicBtn) {
                    this.openPublicServersModal();
                    e.stopPropagation();
                    return;
                }
                const removeBtn = e.target.closest('.contact-remove');
                if (removeBtn) {
                    const username = removeBtn.getAttribute('data-remove-contact');
                    if (username) this.removeContact(username);
                    e.stopPropagation();
                    return;
                }
                // Аватарка внутри строки — вход в профиль, а не в диалог.
                // Проверяется ДО строки, иначе клик по ней просто открыл бы чат.
                const avaTarget = e.target.closest('[data-profile-open]');
                if (avaTarget) {
                    const name = avaTarget.getAttribute('data-profile-open');
                    if (name) {
                        e.stopPropagation();
                        void this.openProfile(name);
                        return;
                    }
                }
                const row = e.target.closest('.contact');
                if (row && row.dataset.name) {
                    this.closeChatPanelModals();
                    this.switchChat(row.dataset.name);
                }
            });
            contactsEl.addEventListener('contextmenu', (e) => {
                const row = e.target.closest('.contact');
                if (!row || !row.dataset.name) return;
                e.preventDefault();
                this.openContactContextMenu(row.dataset.name, e.clientX, e.clientY);
            });
        }

        const serverChannelList = document.getElementById('serverChannelList');
        if (serverChannelList) {
            serverChannelList.addEventListener('click', (e) => {
                const channelBtn = e.target.closest('.server-channel[data-channel-id]');
                if (!channelBtn) return;
                const channelId = channelBtn.getAttribute('data-channel-id');
                if (channelId) this.setActiveChannel(channelId);
            });
            serverChannelList.addEventListener('contextmenu', (e) => {
                const channelBtn = e.target.closest('.server-channel[data-channel-id]');
                if (!channelBtn) return;
                const sid = channelBtn.getAttribute('data-server-id');
                const cid = channelBtn.getAttribute('data-channel-id');
                if (channelBtn.getAttribute('data-channel-kind') === 'voice') return;
                e.preventDefault();
                if (sid && cid) this.toggleMuteChannel(sid, cid);
            });
        }

    }

    /** Голосовая панель и плитки участников. Вызывается только из bindEvents(). */
    bindVoicePanelEvents() {
        const voicePanel = document.getElementById('voicePanel');
        if (voicePanel) {
            voicePanel.addEventListener('click', async (e) => {
                const callBtn = e.target.closest('#voiceCallBtn');
                if (callBtn) {
                    await this.startDirectCall(this.S.current);
                    return;
                }
                const videoCallBtn = e.target.closest('#voiceVideoCallBtn');
                if (videoCallBtn) {
                    await this.startDirectCall(this.S.current, { video: true });
                    return;
                }
                const joinBtn = e.target.closest('#voiceJoinBtn');
                if (joinBtn) {
                    await this.joinVoiceChannel();
                    return;
                }
                const leaveBtn = e.target.closest('#voiceLeaveBtn');
                if (leaveBtn) {
                    await this.leaveVoiceRoom({ announce: true });
                    return;
                }
                const muteBtn = e.target.closest('#voiceMuteBtn');
                if (muteBtn) {
                    this.toggleVoiceMute();
                    return;
                }
                const deafenBtn = e.target.closest('#voiceDeafenBtn');
                if (deafenBtn) {
                    this.toggleVoiceDeafen();
                    return;
                }
                const collapseBtn = e.target.closest('#voiceCollapseBar');
                if (collapseBtn) {
                    this.toggleVoiceCallExpanded();
                    return;
                }
                // Bar click anywhere outside its own mute/deafen buttons expands to
                // the fullscreen grid — checked last so those two buttons (already
                // handled above) never also trigger an expand.
                const bar = e.target.closest('#voiceCallBar');
                if (bar) {
                    this.toggleVoiceCallExpanded();
                    return;
                }
                const cameraBtn = e.target.closest('#voiceCameraBtn');
                if (cameraBtn) {
                    await this.setVoiceCameraEnabled(!this.voice.cameraOn);
                    return;
                }
                const screenShareBtn = e.target.closest('#voiceScreenShareBtn');
                if (screenShareBtn) {
                    this.toggleScreenShare();
                    return;
                }
                const acceptBtn = e.target.closest('#voiceAcceptBtn');
                if (acceptBtn) {
                    await this.acceptIncomingCall();
                    return;
                }
                const rejectBtn = e.target.closest('#voiceRejectBtn');
                if (rejectBtn) {
                    await this.rejectIncomingCall();
                    return;
                }
                const cancelBtn = e.target.closest('#voiceCancelBtn');
                if (cancelBtn) {
                    const invite = this.voice.outgoingInvite;
                    if (invite?.roomId && invite?.target) {
                        this.sendVoiceEvent({
                            type: 'voice_call_cancel',
                            roomId: invite.roomId,
                            target: invite.target,
                        });
                    }
                    this.recordVoiceCallHistory({ outcome: 'cancelled', endedAt: Date.now() });
                    this.resetVoiceState({ preserveInvite: false });
                }
            });
            voicePanel.addEventListener('keydown', (e) => {
                if (e.key !== 'Enter' && e.key !== ' ') return;
                if (e.target.closest('#voiceMuteBtn, #voiceDeafenBtn')) return;
                if (e.target.closest('#voiceCallBar, #voiceCollapseBar')) {
                    e.preventDefault();
                    this.toggleVoiceCallExpanded();
                }
            });
        }

    }

    /** Шапка чата: звонок, видео, кнопка «назад». Вызывается только из bindEvents(). */
    bindChatHeaderEvents() {
        const chatCallBtn = document.getElementById('chatCallBtn');
        if (chatCallBtn) {
            chatCallBtn.addEventListener('click', async () => {
                if (!this.S.current) return;
                await this.startDirectCall(this.S.current);
            });
        }

        const chatVideoCallBtn = document.getElementById('chatVideoCallBtn');
        if (chatVideoCallBtn) {
            chatVideoCallBtn.addEventListener('click', async () => {
                if (!this.S.current) return;
                await this.startDirectCall(this.S.current, { video: true });
            });
        }

        // Аватарка в шапке — вход в профиль собеседника (в DM) или ничего
        // (в канале сервера аватарка принадлежит серверу, а не человеку).
        const chatHdrAva = document.getElementById('chatHdrAva');
        if (chatHdrAva) {
            chatHdrAva.addEventListener('click', () => {
                if (this.S.navMode === 'servers') return;
                if (this.S.current) void this.openProfile(this.S.current);
            });
        }

        // Mobile chat app-bar back chevron: returns to the dialog list screen
        // via the same push-nav path a back-swipe uses.
        const chatBackBtn = document.getElementById('chatBackBtn');
        if (chatBackBtn) {
            chatBackBtn.addEventListener('click', () => this.openChatView({ showList: true }));
        }

    }

    /** Список сообщений: реакции, ссылки, контекстное меню. Вызывается только из bindEvents(). */
    bindMessageListEvents() {
        const msgsEl = document.getElementById('msgs');
        if (msgsEl) {
            msgsEl.addEventListener('scroll', () => this.onMessagesScroll(), { passive: true });
            msgsEl.addEventListener('click', (e) => {
                const avaTarget = e.target.closest('.msg-ava[data-profile-open]');
                if (avaTarget) {
                    e.preventDefault();
                    e.stopPropagation();
                    const name = avaTarget.getAttribute('data-profile-open');
                    if (name) void this.openProfile(name);
                    return;
                }
                const fileLink = e.target.closest('a.file-chip, a.file-message');
                if (fileLink) {
                    e.preventDefault();
                    e.stopPropagation();
                    const href = fileLink.getAttribute('href') || '';
                    const filename = fileLink.getAttribute('download') || fileLink.textContent || 'attachment';
                    this.downloadAttachmentFromHref(href, filename);
                    return;
                }
                const quote = e.target.closest('.msg-quote[data-reply-target]');
                if (quote) {
                    e.stopPropagation();
                    this.scrollToMessage(quote.getAttribute('data-reply-target'));
                    return;
                }
                const reactionBtn = e.target.closest('[data-message-reaction]');
                if (reactionBtn) {
                    const messageId = reactionBtn.getAttribute('data-message-id');
                    const emoji = reactionBtn.getAttribute('data-message-reaction');
                    if (messageId && emoji) {
                        this.addReaction(messageId, emoji);
                    }
                    e.stopPropagation();
                    return;
                }
                this.hideReactionMenu();
            });
            msgsEl.addEventListener('contextmenu', (e) => {
                // ПКМ по аватарке — меню человека (подписаться, в друзья),
                // а не меню сообщения: реакция к аватарке отношения не имеет.
                const avaTarget = e.target.closest('.msg-ava[data-profile-open]');
                if (avaTarget) {
                    const name = avaTarget.getAttribute('data-profile-open');
                    if (name) {
                        e.preventDefault();
                        e.stopPropagation();
                        this.openContactContextMenu(name, e.clientX, e.clientY);
                        return;
                    }
                }
                const msgEl = e.target.closest('.msg[data-message-id]');
                if (!msgEl) return;
                const messageId = msgEl.getAttribute('data-message-id');
                if (!messageId) return;
                e.preventDefault();
                this.showReactionMenu(msgEl, messageId, e.clientX, e.clientY);
                e.stopPropagation();
            });
        }

        document.addEventListener('click', (e) => {
            const menu = document.getElementById('reactionMenu');
            if (!menu || !menu.classList.contains('visible')) return;
            if (menu.contains(e.target)) return;
            if (e.target.closest('.msg[data-message-id]')) return;
            this.hideReactionMenu();
        });
        window.addEventListener('blur', () => this.hideReactionMenu());

        // Catches every auto-linked URL in message text (renderMessageText),
        // wherever it's rendered — not scoped to #msgs, so it also covers any
        // future spot that reuses the same target="_blank" markup. No-ops (and
        // lets the default navigation happen) outside a native shell.
        document.addEventListener('click', (e) => {
            const link = e.target.closest('a[target="_blank"]');
            if (!link) return;
            const href = link.getAttribute('href') || '';
            if (this.openExternalLink(href)) {
                e.preventDefault();
            }
        });

    }

    /** Добавление контакта и подсказки. Вызывается только из bindEvents(). */
    bindContactAddEvents() {
        const contactAddBtn = document.getElementById('contactAddBtn');
        if (contactAddBtn) {
            contactAddBtn.addEventListener('click', () => {
                if (!this.S.session?.token) return;
                if (!this.S.contactAddMode) {
                    this.enterContactAddMode();
                    return;
                }
                this.addContactFromInput();
            });
        }

        const contactSuggestions = document.getElementById('contactSuggestions');
        if (contactSuggestions) {
            contactSuggestions.addEventListener('pointerdown', (e) => {
                const item = e.target.closest('.contact-suggest-item');
                if (!item) return;
                e.preventDefault();
                const username = item.getAttribute('data-username');
                if (username) {
                    this.addContactFromInput(username);
                }
            });
        }

    }

    /** Композер, вложения, перевод ZaliCoin, модалка обновления. Вызывается только из bindEvents(). */
    bindComposerEvents() {
        // 2. Click send button & keyboard listener
        const sendBtn = document.getElementById('sendBtn');
        if (sendBtn) sendBtn.addEventListener('click', () => this.sendInputMessage());

        const composerContext = document.getElementById('composerContext');
        if (composerContext) {
            composerContext.addEventListener('click', (e) => {
                if (e.target.closest('[data-composer-context-cancel]')) {
                    this.cancelComposerContext();
                }
            });
        }

        const attachBtn = document.getElementById('attachBtn');
        const attachmentInput = document.getElementById('attachmentInput');
        if (attachBtn && attachmentInput) {
            attachBtn.addEventListener('click', () => attachmentInput.click());
            attachmentInput.addEventListener('change', (e) => {
                this.handleFiles(e.target.files || []);
                e.target.value = '';
            });
        }

        const coinTransferBtn = document.getElementById('coinTransferBtn');
        if (coinTransferBtn) {
            coinTransferBtn.addEventListener('click', () => {
                // In a DM the peer is the obvious recipient; in a server channel
                // (or with no active chat) there is no single peer — open the
                // wallet-style modal with a free recipient field instead of
                // silently doing nothing.
                const isDm = this.currentConversationMode() !== 'servers';
                this.openCoinTransferModal(isDm && this.S.current ? this.S.current : '');
            });
        }
        const zaliCoinSendBtn = document.getElementById('zaliCoinSendBtn');
        if (zaliCoinSendBtn) zaliCoinSendBtn.addEventListener('click', () => this.openCoinTransferModal());
        const coinTransferModal = document.getElementById('coinTransferModal');
        const coinTransferCloseBtn = document.getElementById('coinTransferCloseBtn');
        const coinTransferCancelBtn = document.getElementById('coinTransferCancelBtn');
        const coinTransferSubmitBtn = document.getElementById('coinTransferSubmitBtn');
        if (coinTransferCloseBtn) coinTransferCloseBtn.addEventListener('click', () => this.closeCoinTransferModal());
        if (coinTransferCancelBtn) coinTransferCancelBtn.addEventListener('click', () => this.closeCoinTransferModal());
        if (coinTransferSubmitBtn) coinTransferSubmitBtn.addEventListener('click', () => this.submitCoinTransfer());
        if (coinTransferModal) {
            coinTransferModal.addEventListener('click', (e) => {
                if (e.target === coinTransferModal) this.closeCoinTransferModal();
            });
        }
        const updateModalDeclineBtn = document.getElementById('updateModalDeclineBtn');
        const updateModalAcceptBtn = document.getElementById('updateModalAcceptBtn');
        if (updateModalDeclineBtn) updateModalDeclineBtn.addEventListener('click', () => this.declineAppUpdate());
        if (updateModalAcceptBtn) updateModalAcceptBtn.addEventListener('click', () => this.acceptAppUpdate());
        const coinTransferAmountInput = document.getElementById('coinTransferAmountInput');
        if (coinTransferAmountInput) {
            coinTransferAmountInput.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') { e.preventDefault(); this.submitCoinTransfer(); }
            });
        }
        const coinTransferRecipientInput = document.getElementById('coinTransferRecipientInput');
        if (coinTransferRecipientInput) {
            coinTransferRecipientInput.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') { e.preventDefault(); coinTransferAmountInput?.focus(); }
            });
        }

    }

    /** Поле ввода: ввод, вставка, drag-and-drop. Вызывается только из bindEvents(). */
    bindMessageInputEvents() {
        const msgInput = document.getElementById('msgInput');
        if (msgInput) {
            msgInput.addEventListener('input', () => {
                this.resizeComposer();
                this.updateSendButtonState();
            });
            msgInput.addEventListener('keydown', (e) => {
                // Escape backs out of a reply/edit without sending anything. Only
                // when one is active, so it keeps its usual meaning otherwise.
                if (e.key === 'Escape' && (this.S.replyDraft || this.S.editDraft)) {
                    e.preventDefault();
                    this.cancelComposerContext();
                    return;
                }
                if (e.key === 'Enter' && !e.shiftKey) { 
                    e.preventDefault(); 
                    this.sendInputMessage(); 
                }
            });
            msgInput.addEventListener('paste', (e) => {
                const files = Array.from(e.clipboardData?.files || []).filter(Boolean);
                if (files.length > 0) {
                    e.preventDefault();
                    this.handleFiles(files);
                }
            });
        }

        const inputBar = document.getElementById('inputBar');
        if (inputBar) {
            inputBar.addEventListener('dragover', (e) => {
                e.preventDefault();
                inputBar.classList.add('drop-active');
            });
            inputBar.addEventListener('dragleave', () => {
                inputBar.classList.remove('drop-active');
            });
            inputBar.addEventListener('drop', (e) => {
                e.preventDefault();
                inputBar.classList.remove('drop-active');
                const files = Array.from(e.dataTransfer?.files || []).filter(Boolean);
                if (files.length > 0) this.handleFiles(files);
            });
        }

        const draftAttachments = document.getElementById('draftAttachments');
        if (draftAttachments) {
            draftAttachments.addEventListener('click', (e) => {
                const btn = e.target.closest('.draft-att-remove');
                if (!btn) return;
                const id = btn.getAttribute('data-att-id');
                this.S.draftAttachments = this.S.draftAttachments.filter(att => att.id !== id);
                this.renderDraftAttachments();
                this.updateSendButtonState();
            });
        }

    }

    /** Поиск, переключение режима и сегментов хаба. Вызывается только из bindEvents(). */
    bindSearchAndModeEvents() {
        // 3. Search filter input (doubles as the contact-add input while contactAddMode is on)
        const searchInput = document.getElementById('searchInput');
        if (searchInput) {
            searchInput.addEventListener('input', (e) => {
                if (this.S.contactAddMode) {
                    const query = searchInput.value || '';
                    this.updateContactAddButtonState();
                    this.setContactStatus('');
                    this.renderContactSuggestions(true);
                    this.scheduleUserSearch(query, { onDone: () => this.renderContactSuggestions(true) });
                    return;
                }
                this.S.searchQ = e.target.value;
                this.renderContacts();
            });
            searchInput.addEventListener('focus', () => {
                if (!this.S.contactAddMode) return;
                const query = searchInput.value || '';
                this.setContactStatus('');
                this.renderContactSuggestions(true);
                void this.loadUsers(query).then(() => this.renderContactSuggestions(true));
            });
            searchInput.addEventListener('blur', () => {
                if (!this.S.contactAddMode) return;
                setTimeout(() => {
                    if (!this.S.contactAddMode) return;
                    if (!String(searchInput.value || '').trim()) {
                        this.exitContactAddMode();
                    } else {
                        this.hideContactSuggestions();
                    }
                }, 120);
            });
            searchInput.addEventListener('keydown', (e) => {
                if (!this.S.contactAddMode) return;
                if (e.key === 'Escape') {
                    e.preventDefault();
                    this.exitContactAddMode();
                    searchInput.blur();
                    return;
                }
                if (e.key === 'Enter') {
                    e.preventDefault();
                    this.addContactFromInput();
                }
            });
        }

        const modeDmBtn = document.getElementById('modeDmBtn');
        const modeServersBtn = document.getElementById('modeServersBtn');
        if (modeDmBtn) modeDmBtn.addEventListener('click', () => this.setNavMode('dm'));
        if (modeServersBtn) modeServersBtn.addEventListener('click', () => this.setNavMode('servers'));
        const hubSegmentNav = document.getElementById('hubSegmentNav');
        if (hubSegmentNav) {
            hubSegmentNav.addEventListener('click', (e) => {
                const btn = e.target.closest('[data-hub-segment]');
                if (!btn) return;
                this.handleHubSegment(btn.getAttribute('data-hub-segment'));
            });
        }

    }

    /** Экран входа: форма, сеть, гость. Вызывается только из bindEvents(). */
    bindAuthEvents() {
        const authForm = document.getElementById('authForm');
        const authLoginBtn = document.getElementById('authLoginBtn');
        if (authForm) {
            authForm.addEventListener('submit', (e) => {
                e.preventDefault();
                this.submitAuth(this.S.auth.mode);
            });
        }
        if (authLoginBtn) {
            authLoginBtn.addEventListener('click', (e) => {
                e.preventDefault();
                this.submitAuth(this.S.auth.mode);
            });
        }

        const authRegisterBtn = document.getElementById('authRegisterBtn');
        if (authRegisterBtn) authRegisterBtn.addEventListener('click', () => {
            this.setAuthMode(this.S.auth.mode === 'register' ? 'login' : 'register');
        });
        const inputVaultCloudSyncEnabled = document.getElementById('inputVaultCloudSyncEnabled');
        if (inputVaultCloudSyncEnabled) {
            inputVaultCloudSyncEnabled.addEventListener('change', () => {
                this.setVaultCloudSyncEnabled(!!inputVaultCloudSyncEnabled.checked);
            });
        }

        const authNetworkSaveBtn = document.getElementById('authNetworkSaveBtn');
        const authApiBaseUrl = document.getElementById('authApiBaseUrl');
        if (authApiBaseUrl) {
            authApiBaseUrl.addEventListener('input', () => {
                authApiBaseUrl.dataset.dirty = '1';
                const authNote = document.getElementById('authNetworkNote');
                const value = String(authApiBaseUrl.value || '').trim();
                if (authNote) {
                    authNote.textContent = value ? `Будет использован: ${value}` : 'Автоматически подставляется из настроек';
                }
            });
            authApiBaseUrl.addEventListener('blur', () => {
                this.syncAuthNetworkInput();
            });
        }
        if (authNetworkSaveBtn) {
            authNetworkSaveBtn.addEventListener('click', () => {
                const apiBaseUrl = String(authApiBaseUrl?.value || '').trim();
                if (!apiBaseUrl) {
                    this.addLogEntry({
                        type: 'ERROR',
                        msg: 'Укажите адрес API сервера',
                        ts: new Date().toLocaleTimeString(),
                    });
                    return;
                }
                const current = this.loadNetworkConfig();
                this.setNetworkConfig({
                    apiBaseUrl,
                    wsBaseUrl: this.deriveWsBaseUrl(apiBaseUrl),
                    iceServers: current.iceServers,
                });
                if (authApiBaseUrl) {
                    authApiBaseUrl.dataset.dirty = '0';
                }
                this.addLogEntry({
                    type: 'SUCCESS',
                    msg: `Адрес сервера обновлён: ${apiBaseUrl}`,
                    ts: new Date().toLocaleTimeString(),
                });
                this.updateAuthView();
            });
        }

        const authGuestBtn = document.getElementById('authGuestBtn');
        if (authGuestBtn) authGuestBtn.addEventListener('click', () => this.continueAsGuest());

        const authUsername = document.getElementById('authUsername');
        const authPassword = document.getElementById('authPassword');
        if (authUsername) {
            authUsername.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    this.submitAuth(this.S.auth.mode);
                }
            });
        }
        if (authPassword) {
            authPassword.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    this.submitAuth(this.S.auth.mode);
                }
            });
        }
        if (authApiBaseUrl) {
            authApiBaseUrl.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    authNetworkSaveBtn?.click();
                }
            });
        }

        this.initA2hsBanner();

        requestAnimationFrame(() => {
            this.clearAuthInputs();
            this.S.auth.fieldsCleared = true;
        });
        setTimeout(() => {
            this.clearAuthInputs();
            this.S.auth.fieldsCleared = true;
        }, 120);

    }

    /** Настройки, сетевая конфигурация и модалка сервера. Вызывается только из bindEvents(). */
    bindSettingsEvents() {
        const settingsBtn = document.getElementById('settingsBtn');
        const serverSettingsBtn = document.getElementById('serverSettingsBtn');
        const serverOverlay = document.getElementById('serverOverlay');
        const serverModalClose = document.getElementById('serverModalClose');
        const serverModalCancel = document.getElementById('serverModalCancel');
        const serverSaveBtn = document.getElementById('serverSaveBtn');
        const serverDeleteBtn = document.getElementById('serverDeleteBtn');
        const serverMemberAddBtn = document.getElementById('serverMemberAddBtn');
        const serverJoinLinkGenerateBtn = document.getElementById('serverJoinLinkGenerateBtn');
        const serverJoinLinkCopyBtn = document.getElementById('serverJoinLinkCopyBtn');
        const serverAvatarUploadBtn = document.getElementById('serverAvatarUploadBtn');
        const serverAvatarRemoveBtn = document.getElementById('serverAvatarRemoveBtn');
        const serverBannerUploadBtn = document.getElementById('serverBannerUploadBtn');
        const serverBannerRemoveBtn = document.getElementById('serverBannerRemoveBtn');
        const serverRoleCreateBtn = document.getElementById('serverRoleCreateBtn');
        const serverRoleNameInput = document.getElementById('serverRoleNameInput');
        const settingsLogoutBtn = document.getElementById('settingsLogoutBtn');
        const clearLogsBtn = document.getElementById('clearLogs');
        const closeSettings = document.getElementById('closeSettings');
        const resetEncryptionKeysBtn = document.getElementById('resetEncryptionKeysBtn');
        const networkConfigSaveBtn = document.getElementById('networkConfigSaveBtn');
        const networkConfigResetBtn = document.getElementById('networkConfigResetBtn');
        const networkTurnApplyBtn = document.getElementById('networkTurnApplyBtn');
        const networkTurnFillBtn = document.getElementById('networkTurnFillBtn');
        const inputApiBaseUrl = document.getElementById('inputApiBaseUrl');
        const inputWsBaseUrl = document.getElementById('inputWsBaseUrl');
        const inputIceServers = document.getElementById('inputIceServers');
        const deviceTrustRefreshBtn = document.getElementById('deviceTrustRefreshBtn');
        const deviceVaultExportBtn = document.getElementById('deviceVaultExportBtn');
        const deviceVaultImportBtn = document.getElementById('deviceVaultImportBtn');
        const deviceTrustList = document.getElementById('deviceTrustList');
        const avatarUploadBtn = document.getElementById('avatarUploadBtn');
        const avatarResetBtn = document.getElementById('avatarResetBtn');
        const meAva = document.getElementById('meAva');
        const inputUiV2Enabled = document.getElementById('inputUiV2Enabled');
        const inputExperimentalDesign = document.getElementById('inputExperimentalDesign');
        const designModeOptions = document.getElementById('designModeOptions');
        const cacheSettings = document.getElementById('cacheSettings');
        const inputVoiceTrace = document.getElementById('inputVoiceTrace');
        const hubSegmentSettings = document.getElementById('hubSegmentSettings');
        const recentAccounts = document.getElementById('recentAccounts');
        const inputAudioMic = document.getElementById('inputAudioMic');
        const inputAudioSpeaker = document.getElementById('inputAudioSpeaker');
        const inputMasterVolume = document.getElementById('inputMasterVolume');

        const openAvatarPicker = () => {
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = 'image/*';
            input.style.position = 'fixed';
            input.style.left = '-9999px';
            input.style.top = '0';
            input.style.width = '1px';
            input.style.height = '1px';
            input.style.opacity = '0';
            input.setAttribute('aria-hidden', 'true');
            document.body.appendChild(input);

            const cleanup = () => {
                input.removeEventListener('change', onChange);
                input.remove();
            };

            const onChange = async () => {
                const file = input.files && input.files[0];
                if (!file) {
                    cleanup();
                    return;
                }
                try {
                    const cropped = await this.openAvatarCropper(file);
                    if (!cropped) {
                        cleanup();
                        return;
                    }
                    await this.setProfileAvatar(cropped, this.myName());
                    this.addLogEntry({ type: 'SUCCESS', msg: `Аватар обновлён: ${this.myName()}`, ts: new Date().toLocaleTimeString() });
                } catch (err) {
                    this.addLogEntry({ type: 'ERROR', msg: err?.message || 'Не удалось обновить аватар', ts: new Date().toLocaleTimeString() });
                } finally {
                    cleanup();
                }
            };

            input.addEventListener('change', onChange, { once: true });
            input.click();
        };

        const showChatView = () => {
            this.openChatView();
        };

        const showSettingsView = () => {
            this.openSettingsView();
        };

        if (settingsBtn) settingsBtn.addEventListener('click', () => {
            this.applyNetworkConfigToInputs();
            this.renderUiV2Settings();
            this.renderAudioDeviceSettings();
            // Карточку кеша рисует openSettingsView() — там же, где остальные
            // разделы настроек. Здесь её быть не должно: в настройки попадают
            // ещё и через нижнюю панель и через сегмент Хаба, и карточка,
            // привязанная к одной этой кнопке, в тех двух путях оставалась
            // пустой.
            showSettingsView();
        });
        if (inputAudioMic) {
            inputAudioMic.addEventListener('change', () => {
                this.setAudioInputDevice(inputAudioMic.value);
            });
        }
        if (inputAudioSpeaker) {
            inputAudioSpeaker.addEventListener('change', () => {
                this.setAudioOutputDevice(inputAudioSpeaker.value);
            });
        }
        if (inputMasterVolume) {
            inputMasterVolume.addEventListener('input', () => {
                this.setMasterVolumePercent(inputMasterVolume.value);
            });
        }
        if (navigator.mediaDevices?.addEventListener) {
            navigator.mediaDevices.addEventListener('devicechange', () => this.refreshAudioDeviceOptions());
        }
        if (inputUiV2Enabled) {
            inputUiV2Enabled.addEventListener('change', () => {
                this.saveUiV2Enabled(!!inputUiV2Enabled.checked);
            });
        }
        if (inputExperimentalDesign) {
            inputExperimentalDesign.addEventListener('change', () => {
                this.saveExperimentalDesign(!!inputExperimentalDesign.checked);
            });
        }
        if (designModeOptions) {
            // Делегирование, а не слушатели на кнопках: renderDesignModeSettings()
            // переписывает контейнер через innerHTML при каждом применении режима.
            designModeOptions.addEventListener('click', (event) => {
                const btn = event.target?.closest?.('[data-design-mode]');
                if (!btn || !designModeOptions.contains(btn)) return;
                this.saveDesignMode(btn.getAttribute('data-design-mode'));
            });
        }
        if (inputVoiceTrace) {
            inputVoiceTrace.addEventListener('change', () => {
                this.saveVoiceTraceEnabled(!!inputVoiceTrace.checked);
            });
        }
        if (cacheSettings) {
            // Делегирование по той же причине, что и у designModeOptions:
            // renderCacheSettings() переписывает контейнер целиком каждый раз,
            // когда меняется сводка, — слушатели на кнопках не пережили бы это.
            cacheSettings.addEventListener('click', (event) => {
                const modeBtn = event.target?.closest?.('[data-cache-mode]');
                if (modeBtn && cacheSettings.contains(modeBtn)) {
                    this.saveCachePrefs({ mode: modeBtn.getAttribute('data-cache-mode') });
                    return;
                }
                if (event.target?.closest?.('#cacheClearBtn')) {
                    void this.clearAssetCache();
                }
            });
            // 'input' обновляет только подпись — слайдер тащат, и запускать на
            // каждый промежуточный шаг вытеснение значило бы стереть половину
            // кеша по дороге к 16 ГБ. Запись и применение — на 'change'.
            cacheSettings.addEventListener('input', (event) => {
                const slider = event.target;
                if (!slider || slider.id !== 'inputCacheLimit') return;
                // Пока жест идёт, карточку перерисовывать нельзя — иначе
                // слайдер заменят прямо под пальцем (см. cacheLimitSliderBusy).
                this._cacheLimitDragging = true;
                const label = document.getElementById('cacheLimitValue');
                const stop = ZaliInterface.cacheLimitStops[this.normalizeCacheLimitIndex(slider.value)];
                if (label && stop) label.textContent = stop.label;
            });
            cacheSettings.addEventListener('change', (event) => {
                const slider = event.target;
                if (!slider || slider.id !== 'inputCacheLimit') return;
                this._cacheLimitDragging = false;
                this.saveCachePrefs({ limitIndex: slider.value });
            });
        }
        if (hubSegmentSettings) {
            hubSegmentSettings.addEventListener('change', () => {
                const selected = Array.from(hubSegmentSettings.querySelectorAll('input[type="checkbox"]:checked'))
                    .map(input => String(input.value || '').trim())
                    .filter(Boolean);
                if (!selected.length) {
                    const first = hubSegmentSettings.querySelector('input[type="checkbox"]');
                    if (first) {
                        first.checked = true;
                        selected.push(String(first.value || 'dm'));
                    }
                }
                this.saveUiV2Segments(selected.slice(0, 3));
            });
        }
        if (deviceTrustRefreshBtn) {
            deviceTrustRefreshBtn.addEventListener('click', () => this.refreshDeviceTrust());
        }
        if (deviceVaultExportBtn) {
            deviceVaultExportBtn.addEventListener('click', () => this.exportCurrentVaultPackage());
        }
        if (deviceVaultImportBtn) {
            deviceVaultImportBtn.addEventListener('click', () => this.importVaultPackageFromInputs());
        }
        if (deviceTrustList) {
            deviceTrustList.addEventListener('click', (e) => {
                const approveBtn = e.target.closest('[data-device-approve]');
                if (approveBtn) {
                    this.approveDeviceAndExport(approveBtn.getAttribute('data-device-approve'));
                    return;
                }
                const revokeBtn = e.target.closest('[data-device-revoke]');
                if (revokeBtn) {
                    this.revokeTrustedDevice(revokeBtn.getAttribute('data-device-revoke'));
                }
            });
        }
        if (serverSettingsBtn) {
            serverSettingsBtn.addEventListener('click', () => {
                if (this.canManageServer()) {
                    this.openServerModal('edit', this.S.activeServer);
                }
            });
        }
        if (serverOverlay) {
            serverOverlay.addEventListener('click', (e) => {
                if (e.target === serverOverlay) {
                    this.closeServerOverlay();
                }
            });
        }
        const serverModalNav = document.getElementById('serverModalNav');
        if (serverModalNav) {
            serverModalNav.addEventListener('click', (e) => {
                const btn = e.target.closest('[data-server-modal-section]');
                if (!btn || btn.hidden) return;
                const section = btn.getAttribute('data-server-modal-section');
                this.setServerModalSection(section);
            });
        }
        const serverModal = document.getElementById('serverModal');
        if (serverModal) {
            serverModal.addEventListener('click', (e) => {
                const toggle = e.target.closest('[data-color-picker-toggle]');
                if (!toggle) return;
                const key = String(toggle.getAttribute('data-color-picker-toggle') || '').trim();
                if (!key) return;
                this.toggleServerModalColorPicker(key);
            });
        }
        const serverDiscoverQuery = document.getElementById('serverDiscoverQuery');
        if (serverDiscoverQuery) {
            serverDiscoverQuery.addEventListener('input', () => this.renderPublicServersModal());
        }
        const serverDiscoverRefreshBtn = document.getElementById('serverDiscoverRefreshBtn');
        if (serverDiscoverRefreshBtn) {
            serverDiscoverRefreshBtn.addEventListener('click', () => this.loadPublicServers({ silent: true }));
        }
        if (serverModalClose) serverModalClose.addEventListener('click', () => this.closeServerOverlay());
        if (serverModalCancel) serverModalCancel.addEventListener('click', () => this.closeServerOverlay());
        if (serverSaveBtn) serverSaveBtn.addEventListener('click', () => this.submitServerModal());
        if (serverDeleteBtn) {
            serverDeleteBtn.addEventListener('click', async () => {
                const serverId = this.S.serverModal.serverId || this.S.activeServer;
                const server = (this.S.servers || []).find(item => item.id === serverId);
                if (!server || this.normalizeMemberRole(server.myRole || server.my_role || '') !== 'owner') return;
                const confirmDelete = confirm(`Удалить сервер "${server.name}"?`);
                if (!confirmDelete) return;
                try {
                    const res = await this.apiFetch(this.apiRoutes.servers.byId(serverId), { method: 'DELETE' });
                    if (!res.ok && res.status !== 204) {
                        throw new Error(await res.text() || 'Не удалось удалить сервер');
                    }
                    this.closeServerOverlay();
                    await this.loadServers({ silent: true });
                } catch (e) {
                    this.setServerModalState({ error: e?.message || 'Не удалось удалить сервер' });
                    this.renderServerModal();
                }
            });
        }
        if (serverMemberAddBtn) {
            serverMemberAddBtn.addEventListener('click', async () => {
                const serverId = this.S.serverModal.serverId;
                const input = document.getElementById('serverMemberInput');
                const roleSelect = document.getElementById('serverMemberRole');
                const username = (input?.value || '').trim();
                const role = roleSelect?.value || 'member';
                if (!serverId || !username) return;
                try {
                    const res = await this.apiFetch(this.apiRoutes.servers.members(serverId), {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ username, role }),
                    });
                    if (!res.ok) {
                        throw new Error(await res.text() || 'Не удалось добавить участника');
                    }
                    if (input) input.value = '';
                    const data = await res.json();
                    this.setServerModalState({
                        members: Array.isArray(data?.members) ? data.members : this.S.serverModal.members,
                        error: '',
                    });
                    this.renderServerModal();
                    await this.loadServers({ silent: true });
                } catch (e) {
                    this.setServerModalState({ error: e?.message || 'Не удалось добавить участника' });
                    this.renderServerModal();
                }
            });
        }
        const serverChannelsList = document.getElementById('serverChannelsList');
        if (serverChannelsList) {
            serverChannelsList.addEventListener('click', async (e) => {
                const saveBtn = e.target.closest('[data-channel-save]');
                if (saveBtn) {
                    const channelId = saveBtn.getAttribute('data-channel-save');
                    try {
                        await this.saveServerChannel(channelId);
                    } catch (err) {
                        this.setServerModalState({ error: err?.message || 'Не удалось сохранить канал' });
                        this.renderServerModal();
                    }
                    return;
                }
                const deleteBtn = e.target.closest('[data-channel-delete]');
                if (deleteBtn) {
                    const channelId = deleteBtn.getAttribute('data-channel-delete');
                    if (!channelId) return;
                    try {
                        await this.deleteServerChannel(channelId);
                    } catch (err) {
                        this.setServerModalState({ error: err?.message || 'Не удалось удалить канал' });
                        this.renderServerModal();
                    }
                }
            });
        }
        if (serverJoinLinkGenerateBtn) {
            serverJoinLinkGenerateBtn.addEventListener('click', async () => {
                try {
                    const link = await this.generateServerJoinLink();
                    if (link) {
                        this.addLogEntry({ type: 'SUCCESS', msg: `Код сервера обновлён`, ts: new Date().toLocaleTimeString() });
                    }
                } catch (e) {
                    this.setServerModalState({ error: e?.message || 'Не удалось обновить код' });
                    this.renderServerModal();
                }
            });
        }
        if (serverJoinLinkCopyBtn) {
            serverJoinLinkCopyBtn.addEventListener('click', async () => {
                const text = this.S.serverModal.joinLink || '';
                if (!text) return;
                try {
                    await navigator.clipboard.writeText(text);
                    this.addLogEntry({ type: 'SUCCESS', msg: 'Код сервера скопирован', ts: new Date().toLocaleTimeString() });
                } catch (e) {
                    this.addLogEntry({ type: 'WARN', msg: 'Не удалось скопировать код сервера', ts: new Date().toLocaleTimeString() });
                }
            });
        }
        const serverDiscoverList = document.getElementById('serverDiscoverList');
        if (serverDiscoverList) {
            serverDiscoverList.addEventListener('click', async (e) => {
                const card = e.target.closest('[data-public-server-id]');
                if (card && card.classList.contains('server-discover-item')) {
                    const serverId = card.getAttribute('data-public-server-id');
                    if (!serverId) return;
                    const server = (this.S.publicServers || []).find(item => String(item.id || '') === serverId);
                    if (!server) return;
                    const role = this.normalizeMemberRole(server.myRole || server.my_role || '');
                    if (role === 'owner' || role === 'admin' || role === 'member') {
                        this.closeServerOverlay();
                        this.setActiveServer(serverId);
                    } else {
                        await this.enterPublicServer(server.joinLink || server.join_link || server.id);
                    }
                    return;
                }
                const openBtn = e.target.closest('[data-public-server-open]');
                if (openBtn) {
                    const serverId = openBtn.getAttribute('data-public-server-open');
                    if (!serverId) return;
                    const server = (this.S.publicServers || []).find(item => String(item.id || '') === serverId);
                    if (!server) return;
                    if (this.normalizeMemberRole(server.myRole || server.my_role || '') === 'owner'
                        || this.normalizeMemberRole(server.myRole || server.my_role || '') === 'admin'
                        || this.normalizeMemberRole(server.myRole || server.my_role || '') === 'member') {
                        this.closeServerOverlay();
                        this.setActiveServer(serverId);
                        return;
                    }
                    await this.enterPublicServer(server.joinLink || server.join_link || server.id);
                    return;
                }
                const joinBtn = e.target.closest('[data-public-server-join]');
                if (joinBtn) {
                    await this.enterPublicServer(joinBtn.getAttribute('data-public-server-join'));
                }
            });
        }
        if (serverRoleCreateBtn) {
            serverRoleCreateBtn.addEventListener('click', async () => {
                const roleCreateOpen = !this.S.serverModal.roleCreateOpen;
                this.setServerModalState({ roleCreateOpen });
                this.renderServerModal();
            });
        }
        const serverChannelCreateBtn = document.getElementById('serverChannelCreateBtn');
        if (serverChannelCreateBtn) {
            serverChannelCreateBtn.addEventListener('click', async () => {
                if (this.S.serverModal.mode !== 'edit') return;
                const channelCreateOpen = !this.S.serverModal.channelCreateOpen;
                this.setServerModalState({ channelCreateOpen, error: '' });
                this.renderServerModal();
            });
        }
        const serverChannelCreateSubmitBtn = document.getElementById('serverChannelCreateSubmitBtn');
        if (serverChannelCreateSubmitBtn) {
            serverChannelCreateSubmitBtn.addEventListener('click', async () => {
                try {
                    await this.createServerChannel();
                } catch (e) {
                    this.setServerModalState({ error: e?.message || 'Не удалось создать канал' });
                    this.renderServerModal();
                }
            });
        }
        const serverRoleCreateSubmitBtn = document.getElementById('serverRoleCreateSubmitBtn');
        if (serverRoleCreateSubmitBtn) {
            serverRoleCreateSubmitBtn.addEventListener('click', async () => {
                try {
                    const mode = this.S.serverModal.mode;
                    await this.createServerRole();
                    this.addLogEntry({
                        type: 'SUCCESS',
                        msg: mode === 'create' ? 'Черновик роли добавлен' : 'Роль создана',
                        ts: new Date().toLocaleTimeString(),
                    });
                } catch (e) {
                    this.setServerModalState({ error: e?.message || 'Не удалось создать роль' });
                    this.renderServerModal();
                }
            });
        }
        const pickServerAsset = (kind) => {
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = 'image/*';
            input.style.position = 'fixed';
            input.style.left = '-9999px';
            input.style.top = '0';
            document.body.appendChild(input);
            input.addEventListener('change', async () => {
                const file = input.files && input.files[0];
                if (!file) {
                    input.remove();
                    return;
                }
                try {
                    // Only the avatar renders as a circle (.server-avatar, border-radius:50%
                    // + object-fit:cover) — the banner is a wide rectangle, so there is no
                    // "wrong part got cropped" failure mode for it and it stays a plain
                    // resize. Without this, downscaleServerAssetFile only shrinks the image
                    // keeping its original aspect ratio; object-fit:cover then center-crops
                    // it to a circle with zero user control over which part survives, same
                    // class of bug the profile avatar's cropper (openAvatarPicker above)
                    // exists to avoid.
                    let toUpload = file;
                    if (kind === 'avatar') {
                        const cropped = await this.openAvatarCropper(file);
                        if (!cropped) {
                            input.remove();
                            return;
                        }
                        toUpload = cropped;
                    }
                    await this.uploadServerAsset(kind, toUpload);
                    this.addLogEntry({ type: 'SUCCESS', msg: `${kind === 'avatar' ? 'Аватар' : 'Баннер'} сервера обновлён`, ts: new Date().toLocaleTimeString() });
                } catch (e) {
                    this.setServerModalState({ error: e?.message || 'Не удалось обновить медиа сервера' });
                    this.renderServerModal();
                } finally {
                    input.remove();
                }
            }, { once: true });
            input.click();
        };
        if (serverAvatarUploadBtn) serverAvatarUploadBtn.addEventListener('click', () => pickServerAsset('avatar'));
        if (serverBannerUploadBtn) serverBannerUploadBtn.addEventListener('click', () => pickServerAsset('banner'));
        if (serverAvatarRemoveBtn) {
            serverAvatarRemoveBtn.addEventListener('click', async () => {
                try {
                    await this.removeServerAsset('avatar');
                } catch (e) {
                    this.setServerModalState({ error: e?.message || 'Не удалось удалить аватар' });
                    this.renderServerModal();
                }
            });
        }
        if (serverBannerRemoveBtn) {
            serverBannerRemoveBtn.addEventListener('click', async () => {
                try {
                    await this.removeServerAsset('banner');
                } catch (e) {
                    this.setServerModalState({ error: e?.message || 'Не удалось удалить баннер' });
                    this.renderServerModal();
                }
            });
        }
        if (settingsLogoutBtn) settingsLogoutBtn.addEventListener('click', () => this.logout());
        if (resetEncryptionKeysBtn) {
            const resetStatusEl = document.getElementById('resetEncryptionKeysStatus');
            const setResetStatus = (text, ok = true) => {
                if (!resetStatusEl) return;
                resetStatusEl.textContent = text;
                resetStatusEl.style.color = ok ? 'var(--lime)' : 'var(--red)';
                resetStatusEl.hidden = !text;
            };
            resetEncryptionKeysBtn.addEventListener('click', async () => {
                if (!confirm('Сбросить все ключи шифрования?\n\nВсе локальные ключи будут удалены, серверные энвелопы — тоже. После сброса ключи переустановятся автоматически при следующем сообщении.')) return;
                resetEncryptionKeysBtn.disabled = true;
                resetEncryptionKeysBtn.textContent = 'Сбрасываем…';
                setResetStatus('');
                try {
                    await this.resetEncryptionKeys();
                    setResetStatus('Ключи сброшены и перевыпущены');
                    this.addLogEntry({ type: 'SUCCESS', msg: 'Ключи шифрования сброшены и перевыпущены', ts: new Date().toLocaleTimeString() });
                } catch (e) {
                    setResetStatus(`Ошибка: ${e?.message || e}`, false);
                    this.addLogEntry({ type: 'ERROR', msg: `Сброс ключей не удался: ${e?.message || e}`, ts: new Date().toLocaleTimeString() });
                } finally {
                    resetEncryptionKeysBtn.disabled = false;
                    resetEncryptionKeysBtn.textContent = 'Сбросить ключи шифрования';
                    setTimeout(() => setResetStatus(''), 6000);
                }
            });
        }
        if (recentAccounts) {
            recentAccounts.addEventListener('click', (e) => {
                const target = e.target instanceof Element ? e.target : null;
                const switchBtn = target?.closest('[data-switch-account]');
                if (switchBtn && !switchBtn.disabled) {
                    this.switchRecentAccount(switchBtn.getAttribute('data-switch-account'));
                    return;
                }
                const removeBtn = target?.closest('[data-remove-recent-account]');
                if (removeBtn) {
                    this.forgetRecentAccount(removeBtn.getAttribute('data-remove-recent-account'));
                }
            });
        }
        if (avatarUploadBtn) {
            avatarUploadBtn.addEventListener('click', () => openAvatarPicker());
        }
        if (avatarResetBtn) {
            avatarResetBtn.addEventListener('click', async () => {
                try {
                    await this.resetProfileAvatar(this.myName());
                    this.addLogEntry({ type: 'SUCCESS', msg: 'Аватар профиля удалён', ts: new Date().toLocaleTimeString() });
                } catch (err) {
                    this.addLogEntry({ type: 'ERROR', msg: err?.message || 'Не удалось удалить аватар', ts: new Date().toLocaleTimeString() });
                }
            });
        }
        // Клик по своей аватарке слева снизу открывает СВОЙ профиль как обычный
        // просмотр — оттуда же доступны приглашения в друзья и кнопка
        // «Редактировать», если человек действительно хочет что-то поменять.
        // Сменить картинку можно кнопкой внутри редактора и здесь же в
        // настройках, поэтому прежний прямой вызов выбора файла не потерян.
        const meAvaBtn = document.getElementById('meAvaBtn');
        if (meAvaBtn) {
            meAvaBtn.addEventListener('click', () => {
                void this.openProfile(this.myName());
            });
        }
        // Открывает системный выбор файла для аватара. Замыкание объявлено
        // внутри этого метода, поэтому вешаем его на экземпляр — иначе
        // редактор профиля (profile_ui.js) до него не дотянется.
        this.openAvatarPicker = openAvatarPicker;
        if (meAva) meAva.title = 'Мой профиль';
        if (clearLogsBtn) {
            clearLogsBtn.addEventListener('click', () => {
                const logBody = document.getElementById('logBody');
                if (logBody) logBody.innerHTML = '';
            });
        }
        if (closeSettings) closeSettings.addEventListener('click', () => showChatView());
        const mobileMenuBtn = document.getElementById('mobileMenuBtn');
        if (mobileMenuBtn) {
            mobileMenuBtn.addEventListener('click', () => this.toggleMobileSidebar());
        }
        const mobileBackdrop = document.getElementById('mobileBackdrop');
        if (mobileBackdrop) {
            mobileBackdrop.addEventListener('click', () => this.closeMobileSidebar());
        }
        const mobileChatsBtn = document.getElementById('mobileChatsBtn');
        if (mobileChatsBtn) {
            mobileChatsBtn.addEventListener('click', () => {
                this.setNavMode('dm');
                this.openChatView({ showList: true });
            });
        }
        const mobileServersBtn = document.getElementById('mobileServersBtn');
        if (mobileServersBtn) {
            mobileServersBtn.addEventListener('click', () => {
                this.setNavMode('servers');
                this.openChatView({ showList: true });
            });
        }
        const mobileHubBtn = document.getElementById('mobileHubBtn');
        if (mobileHubBtn) {
            mobileHubBtn.addEventListener('click', () => this.openHubView());
        }
        const mobileSettingsBtn = document.getElementById('mobileSettingsBtn');
        if (mobileSettingsBtn) {
            mobileSettingsBtn.addEventListener('click', () => {
                this.applyNetworkConfigToInputs();
                showSettingsView();
            });
        }
        const hubGrid = document.getElementById('hubGrid');
        if (hubGrid) {
            hubGrid.addEventListener('click', (e) => {
                const actionCard = e.target.closest('[data-hub-action]');
                if (actionCard) {
                    const action = actionCard.getAttribute('data-hub-action');
                    if (action === 'components') {
                        document.getElementById('hubComponents')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
                    } else if (action === 'update') {
                        this.handleHubUpdateAction();
                    }
                    return;
                }
                const card = e.target.closest('[data-hub-segment]');
                if (!card) return;
                this.handleHubSegment(card.getAttribute('data-hub-segment'));
            });
        }
        if (networkConfigSaveBtn) {
            networkConfigSaveBtn.addEventListener('click', () => {
                let iceServers = [];
                try {
                    iceServers = this.parseIceServersText(inputIceServers?.value || '');
                } catch (error) {
                    this.addLogEntry({
                        type: 'ERROR',
                        msg: `Не удалось сохранить network config: ${error?.message || error}`,
                        ts: new Date().toLocaleTimeString(),
                    });
                    return;
                }
                const turnUrl = String(document.getElementById('inputTurnUrl')?.value || '').trim();
                if (turnUrl) {
                    try {
                        iceServers = this.appendTurnPresetToIceServers(iceServers);
                    } catch (error) {
                        this.addLogEntry({
                            type: 'ERROR',
                            msg: `Не удалось добавить TURN: ${error?.message || error}`,
                            ts: new Date().toLocaleTimeString(),
                        });
                        return;
                    }
                }
                this.setNetworkConfig({
                    apiBaseUrl: inputApiBaseUrl?.value || '',
                    wsBaseUrl: inputWsBaseUrl?.value || '',
                    iceServers,
                });
            });
        }
        if (networkConfigResetBtn) {
            networkConfigResetBtn.addEventListener('click', () => this.resetNetworkConfig());
        }
        if (networkTurnApplyBtn) {
"""#,
    #"""
            networkTurnApplyBtn.addEventListener('click', () => {
                try {
                    const nextIceServers = this.appendTurnPresetToIceServers(
                        this.parseIceServersText(inputIceServers?.value || '')
                    );
                    this.setNetworkConfig({
                        apiBaseUrl: inputApiBaseUrl?.value || '',
                        wsBaseUrl: inputWsBaseUrl?.value || '',
                        iceServers: nextIceServers,
                    });
                } catch (error) {
                    this.addLogEntry({
                        type: 'ERROR',
                        msg: `Не удалось добавить TURN: ${error?.message || error}`,
                        ts: new Date().toLocaleTimeString(),
                    });
                }
            });
        }
        if (networkTurnFillBtn) {
            networkTurnFillBtn.addEventListener('click', () => {
                const turnUrlInput = document.getElementById('inputTurnUrl');
                const turnUsernameInput = document.getElementById('inputTurnUsername');
                const turnCredentialInput = document.getElementById('inputTurnCredential');
                const turnRelayOnlyInput = document.getElementById('inputTurnRelayOnly');
                if (turnUrlInput) turnUrlInput.value = 'turns:turn.example.com:5349';
                if (turnUsernameInput) turnUsernameInput.value = 'user';
                if (turnCredentialInput) turnCredentialInput.value = 'pass';
                if (turnRelayOnlyInput) turnRelayOnlyInput.checked = true;
            });
        }

        this.bindColorWheel({
            wheelId: 'serverColorWheel',
            hiddenId: 'serverColorInput',
            hexId: 'serverColorHexInput',
            initialValue: '#cbff00',
        });
        this.bindColorWheel({
            wheelId: 'serverRoleColorWheel',
            hiddenId: 'serverRoleColorInput',
            hexId: 'serverRoleColorHexInput',
            initialValue: '#cbff00',
        });

    }

    /** Выбор темы и селекторы стилизатора. Вызывается только из bindEvents(). */
    bindStylerEvents() {
        // 6. Dynamic styler selector events
        document.querySelectorAll('.btn-theme').forEach(btn => {
            btn.addEventListener('click', (e) => {
                const themeName = e.currentTarget.getAttribute('data-theme');
                this.bus.send('zali_styler:set_theme', themeName);
            });
        });

        const serverMembersList = document.getElementById('serverMembersList');
        if (serverMembersList) {
            serverMembersList.addEventListener('change', async (e) => {
                const roleSelect = e.target.closest('select[data-member-role]');
                if (!roleSelect) return;
                const serverId = this.S.serverModal.serverId;
                const username = roleSelect.getAttribute('data-member-role');
                if (!serverId || !username) return;
                try {
                    const res = await this.apiFetch(this.apiRoutes.servers.member(serverId, username), {
                        method: 'PATCH',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ username, role: roleSelect.value }),
                    });
                    if (!res.ok) {
                        throw new Error(await res.text() || 'Не удалось изменить роль');
                    }
                    const data = await res.json();
                    this.setServerModalState({
                        members: Array.isArray(data?.members) ? data.members : this.S.serverModal.members,
                        error: '',
                    });
                    this.renderServerModal();
                    await this.loadServers({ silent: true });
                } catch (err) {
                    this.setServerModalState({ error: err?.message || 'Не удалось изменить роль' });
                    this.renderServerModal();
                }
            });

            serverMembersList.addEventListener('click', async (e) => {
                const removeBtn = e.target.closest('[data-member-remove]');
                if (!removeBtn) return;
                const serverId = this.S.serverModal.serverId;
                const username = removeBtn.getAttribute('data-member-remove');
                if (!serverId || !username) return;
                try {
                    const res = await this.apiFetch(this.apiRoutes.servers.member(serverId, username), {
                        method: 'DELETE',
                    });
                    if (!res.ok && res.status !== 204) {
                        throw new Error(await res.text() || 'Не удалось удалить участника');
                    }
                    if (res.status === 204) {
                        this.setServerModalState({
                            members: (this.S.serverModal.members || []).filter(member => String(member.username || '') !== username),
                            error: '',
                        });
                        this.renderServerModal();
                        await this.loadServers({ silent: true });
                        return;
                    }
                    const data = await res.json();
                    this.setServerModalState({
                        members: Array.isArray(data?.members) ? data.members : this.S.serverModal.members,
                        error: '',
                    });
                    this.renderServerModal();
                    await this.loadServers({ silent: true });
                } catch (err) {
                    this.setServerModalState({ error: err?.message || 'Не удалось удалить участника' });
                    this.renderServerModal();
                }
            });
        }

        const serverRolesList = document.getElementById('serverRolesList');
        if (serverRolesList) {
            serverRolesList.addEventListener('input', () => {
                if (this.S.serverModal.mode !== 'create') return;
                this.syncDraftServerRolesFromDom();
            });
            serverRolesList.addEventListener('click', async (e) => {
                const draftToggleBtn = e.target.closest('[data-draft-role-toggle]');
                if (draftToggleBtn) {
                    if (this.S.serverModal.mode !== 'create') return;
                    const draftId = String(draftToggleBtn.getAttribute('data-draft-role-toggle') || '').trim();
                    if (!draftId) return;
                    const nextRoles = this.syncDraftServerRolesFromDom().map(role => {
                        if (String(role.draftId || '') !== draftId) return role;
                        return {
                            ...role,
                            collapsed: !role.collapsed,
                        };
                    });
                    this.setServerModalState({ draftRoles: nextRoles, error: '' });
                    this.renderServerModal();
                    return;
                }
                const draftHead = e.target.closest('.server-role-head--draft');
                if (draftHead) {
                    if (this.S.serverModal.mode !== 'create') return;
                    const card = draftHead.closest('[data-draft-role-card]');
                    const draftId = String(card?.getAttribute('data-draft-role-card') || '').trim();
                    if (!draftId) return;
                    const nextRoles = this.syncDraftServerRolesFromDom().map(role => {
                        if (String(role.draftId || '') !== draftId) return role;
                        return {
                            ...role,
                            collapsed: !role.collapsed,
                        };
                    });
                    this.setServerModalState({ draftRoles: nextRoles, error: '' });
                    this.renderServerModal();
                    return;
                }
                const draftDeleteBtn = e.target.closest('[data-draft-role-delete]');
                if (draftDeleteBtn) {
                    if (this.S.serverModal.mode !== 'create') return;
                    const draftId = String(draftDeleteBtn.getAttribute('data-draft-role-delete') || '').trim();
                    if (!draftId) return;
                    const nextRoles = this.syncDraftServerRolesFromDom().filter(role => String(role.draftId || '') !== draftId);
                    this.setServerModalState({ draftRoles: nextRoles, error: '' });
                    this.renderServerModal();
                    return;
                }
                const saveBtn = e.target.closest('[data-role-save]');
                if (saveBtn) {
                    const roleId = saveBtn.getAttribute('data-role-save');
                    try {
                        await this.saveServerRole(roleId);
                        this.addLogEntry({ type: 'SUCCESS', msg: `Роль обновлена: ${roleId}`, ts: new Date().toLocaleTimeString() });
                    } catch (err) {
                        this.setServerModalState({ error: err?.message || 'Не удалось сохранить роль' });
                        this.renderServerModal();
                    }
                    return;
                }
                const deleteBtn = e.target.closest('[data-role-delete]');
                if (deleteBtn) {
                    const roleId = deleteBtn.getAttribute('data-role-delete');
                    if (!roleId) return;
                    const role = (this.S.serverModal.roles || []).find(item => String(item.roleId || '') === roleId);
                    const confirmDelete = confirm(`Удалить роль "${role?.name || roleId}"?`);
                    if (!confirmDelete) return;
                    try {
                        await this.deleteServerRole(roleId);
                        this.addLogEntry({ type: 'SUCCESS', msg: `Роль удалена: ${role?.name || roleId}`, ts: new Date().toLocaleTimeString() });
                    } catch (err) {
                        this.setServerModalState({ error: err?.message || 'Не удалось удалить роль' });
                        this.renderServerModal();
                    }
                }
            });
        }

    }

    /** Слайдеры оформления. Вызывается только из bindEvents(). */
    bindStyleSliderEvents() {
        const sliderSuggestHeight = document.getElementById('sliderSuggestHeight');
        if (sliderSuggestHeight) {
            sliderSuggestHeight.addEventListener('input', (e) => {
                const height = `${e.target.value}px`;
                const out = document.getElementById('suggestHeightVal');
                if (out) out.textContent = height;
                this.bus.send('zali_styler:set_variable', '--contact-suggest-max-h', height);
            });
        }

        const sliderSuggestContrast = document.getElementById('sliderSuggestContrast');
        if (sliderSuggestContrast) {
            sliderSuggestContrast.addEventListener('input', (e) => {
                const percent = Number(e.target.value) || 0;
                const bgAlpha = Math.min(0.98, Math.max(0.72, 0.58 + (percent / 100) * 0.32));
                const borderAlpha = Math.min(0.95, Math.max(0.18, 0.08 + (percent / 100) * 0.28));
                const shadowAlpha = Math.min(0.65, Math.max(0.24, 0.12 + (percent / 100) * 0.5));
                const bg = `rgba(8,10,14,${bgAlpha.toFixed(3)})`;
                const border = `rgba(255,255,255,${borderAlpha.toFixed(3)})`;
                const shadow = `0 22px 48px rgba(0,0,0,${shadowAlpha.toFixed(3)})`;
                const out = document.getElementById('suggestContrastVal');
                if (out) out.textContent = `${percent}%`;
                this.bus.send('zali_styler:set_variable', '--contact-suggest-bg', bg);
                this.bus.send('zali_styler:set_variable', '--contact-suggest-border', border);
                this.bus.send('zali_styler:set_variable', '--contact-suggest-shadow', shadow);
            });
        }

        const sliderSuggestDensity = document.getElementById('sliderSuggestDensity');
        if (sliderSuggestDensity) {
            sliderSuggestDensity.addEventListener('input', (e) => {
                const density = Number(e.target.value) || 0;
                const padY = Math.max(8, 16 - Math.round(density / 3));
                const padX = Math.max(10, 16 - Math.round(density / 4));
                const gap = Math.max(4, 12 - Math.round(density / 3));
                const font = Math.min(16, 13 + Math.round(density / 8));
                const hint = Math.max(0.34, Math.min(0.72, 0.42 + density / 60));
                const out = document.getElementById('suggestDensityVal');
                if (out) out.textContent = String(density);
                this.bus.send('zali_styler:set_variable', '--contact-suggest-item-pad-y', `${padY}px`);
                this.bus.send('zali_styler:set_variable', '--contact-suggest-item-pad-x', `${padX}px`);
                this.bus.send('zali_styler:set_variable', '--contact-suggest-gap', `${gap}px`);
                this.bus.send('zali_styler:set_variable', '--contact-suggest-font', `${font}px`);
                this.bus.send('zali_styler:set_variable', '--contact-suggest-hint', `rgba(255,255,255,${hint.toFixed(3)})`);
            });
        }

    }

    /** Ручной ввод ключа шифрования. Вызывается только из bindEvents(). */
    bindCryptoKeyEvents() {
        // 7. Cryptography setting custom key
        // Routes through zali_styler which proxies to Swift → Rust backend
        const inputCryptoKey = document.getElementById('inputCryptoKey');
        if (inputCryptoKey) {
            const storedKey = this.loadStoredCryptoKey();
            if (storedKey && !inputCryptoKey.value.trim()) {
                inputCryptoKey.value = storedKey;
            }
            inputCryptoKey.addEventListener('input', (e) => {
                const newKey = e.target.value.trim();
                this.saveStoredCryptoKey(newKey);
                this.bus.send('zali_styler:set_key', newKey);
            });
        }

    }

    /** Перетаскивание окна, ресайз, горячие клавиши. Вызывается только из bindEvents(). */
    bindWindowChromeEvents() {
        // 8. Title bar drag helper
        const titlebar = document.getElementById('titlebar');
        if (titlebar && this.nativeSupports('windowDrag')) {
            titlebar.addEventListener('mousedown', (e) => {
                if (!e.target.closest('.ws-pill') && !e.target.closest('.hdr-btn') && !e.target.closest('.win-controls') && !e.target.closest('.tb-announce-close')) {
                    this.postNativeMessage({ type: NativeMessageTypes.START_DRAG });
                }
            });
        }

        // 8a. Server-pushed titlebar announcement — dismissible locally only
        // (see showTitlebarAnnouncement()/hideTitlebarAnnouncement() in
        // state_sync.js). Button is always in the DOM, just hidden, so a
        // single static listener is enough — no delegation needed.
        document.getElementById('tbAnnounceClose')?.addEventListener('click', () => {
            this.hideTitlebarAnnouncement();
        });

        // 8b. In-app window controls (Windows only — native OS decorations are
        // switched off there in favor of this titlebar, see
        // NativeCapabilities::window_controls in apps/windows/src/native.rs).
        if (titlebar && this.nativeSupports('windowControls')) {
            titlebar.classList.add('has-window-controls');
            // Windows only: the connection pill moves to the left of the titlebar so
            // it doesn't crowd the window controls on the right. macOS/browser keep
            // it on the right (default DOM position, untouched here).
            const tbL = titlebar.querySelector('.tb-l');
            const wsPill = document.getElementById('wsPill');
            if (tbL && wsPill) {
                tbL.insertBefore(wsPill, tbL.firstChild);
            }
            document.getElementById('winMinBtn')?.addEventListener('click', () => {
                this.postNativeMessage({ type: NativeMessageTypes.MINIMIZE_WINDOW });
            });
            document.getElementById('winMaxBtn')?.addEventListener('click', () => {
                this.postNativeMessage({ type: NativeMessageTypes.MAXIMIZE_WINDOW });
            });
            document.getElementById('winCloseBtn')?.addEventListener('click', () => {
                this.postNativeMessage({ type: NativeMessageTypes.CLOSE_WINDOW });
            });
            titlebar.addEventListener('dblclick', (e) => {
                if (!e.target.closest('.ws-pill') && !e.target.closest('.hdr-btn') && !e.target.closest('.win-controls') && !e.target.closest('.mobile-menu-btn') && !e.target.closest('.tb-announce-close')) {
                    this.postNativeMessage({ type: NativeMessageTypes.MAXIMIZE_WINDOW });
                }
            });
        }

        // Report app loaded
        this.addLogEntry({ type: 'INFO', msg: 'ZaliMessenger v6.0 (Rust Backend) запущен — шифрование и сетевой стек работают в Rust', ts: new Date().toLocaleTimeString() });
        this.resizeComposer();
        this.syncMobileChrome();
        this.setupMobileNavGestures();
        this.setupMobileForwardNavGesture();
        this.setupMobileKeyboardAvoidance();
        this.setupMobileTouchGestures();
        this.applyUiV2Chrome();
        this.applyDesignMode();
        this.applyVoiceTraceEnabled();
        const mobileQuery = this.mobileLayoutQuery();
        if (mobileQuery) {
            const onMobileChange = () => {
                if (!this.isMobileLayout()) {
                    this.closeMobileSidebar();
                }
                this.syncMobileChrome();
            };
            if (typeof mobileQuery.addEventListener === 'function') {
                mobileQuery.addEventListener('change', onMobileChange);
            } else if (typeof mobileQuery.addListener === 'function') {
                mobileQuery.addListener(onMobileChange);
            }
        }
        // Resize fires continuously while a desktop window is dragged. Coalescing to
        // one frame keeps that from running the mobile-chrome sync (which reads
        // layout) dozens of times per second.
        window.addEventListener('resize', () => {
            if (this._resizeRaf) return;
            this._resizeRaf = requestAnimationFrame(() => {
                this._resizeRaf = 0;
                if (!this.isMobileLayout()) {
                    this.closeMobileSidebar();
                }
                this.syncMobileChrome();
                this.repinMessagesAfterViewportChange();
            });
        }, { passive: true });
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && this.isMobileLayout() && document.body?.classList.contains('mobile-sidebar-open')) {
                this.closeMobileSidebar();
            }
        });
        this.setupScrollInertia();
    }

    // Mouse-wheel scrolling has no native deceleration (unlike trackpad momentum,
    // which the OS/compositor handles without extra wheel events) — each notch just
    // jumps and stops dead. This adds a tiny residual glide after the wheel goes
    // idle, capped and decaying fast on purpose: it should read as "less abrupt",
    // never as a distinct animation. #msgs is included deliberately — the coast is
    // a continuation of the user's own gesture, so it must NOT go through
    // markProgrammaticScroll() (see the comment on that method): onMessagesScroll
    // needs to see it as real scrolling so _bottomIntent still clears correctly if
    // the glide carries the view away from the bottom.
    setupScrollInertia() {
        if (window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches) return;
        const SELECTOR = '.msgs, .contacts, .sidebar, .server-channel-list, .settings-body, .server-modal-content, .color-picker-body';
        const FRICTION = 0.72;
        const MIN_VELOCITY = 0.5;
        const MAX_VELOCITY = 6;
        const IDLE_MS = 70;
        const states = new WeakMap();

        const coast = (el, st) => {
            st.raf = requestAnimationFrame(() => {
                st.velocity *= FRICTION;
                if (Math.abs(st.velocity) < MIN_VELOCITY) {
                    st.raf = 0;
                    return;
                }
                const max = el.scrollHeight - el.clientHeight;
                const next = Math.max(0, Math.min(max, el.scrollTop + st.velocity));
                el.scrollTop = next;
                if (next <= 0 || next >= max) {
                    st.raf = 0;
                    return;
                }
                coast(el, st);
            });
        };

        document.addEventListener('wheel', (e) => {
            const el = e.target.closest?.(SELECTOR);
            if (!el || el.scrollHeight <= el.clientHeight) return;
            let st = states.get(el);
            if (!st) {
                st = { velocity: 0, raf: 0, idleTimer: 0 };
                states.set(el, st);
            }
            if (st.raf) {
                cancelAnimationFrame(st.raf);
                st.raf = 0;
            }
            const nudge = Math.max(-MAX_VELOCITY, Math.min(MAX_VELOCITY, e.deltaY * 0.12));
            st.velocity = st.velocity * 0.3 + nudge * 0.7;
            clearTimeout(st.idleTimer);
            st.idleTimer = setTimeout(() => {
                if (Math.abs(st.velocity) >= MIN_VELOCITY) coast(el, st);
            }, IDLE_MS);
        }, { passive: true });
    }
});


// --- MODULE: bootstrap.js ---
// @ts-check
(function() {
    'use strict';

    function createNativeBridge() {
        const macBridge = window.webkit?.messageHandlers?.nativeApp || null;
        const wryBridge = window.ipc?.postMessage ? window.ipc : null;
        const webView2Bridge = window.chrome?.webview?.postMessage ? window.chrome.webview : null;
        // Android's WebView.addJavascriptInterface() only exposes plain methods on a
        // named window object (not a .postMessage(obj) pattern that accepts arbitrary
        // JS objects like WKWebView's message handlers) — the native side only ever
        // sees strings, so payloads are always JSON-stringified first, same as wry/webview2.
        const androidBridge = window.ZaliAndroidBridge?.postMessage ? window.ZaliAndroidBridge : null;

        const transport = macBridge
            ? {
                kind: 'webkit',
                postMessage(payload) {
                    macBridge.postMessage(payload);
                    return true;
                },
            }
            : wryBridge
                ? {
                    kind: 'ipc',
                    postMessage(payload) {
                        const data = typeof payload === 'string' ? payload : JSON.stringify(payload);
                        wryBridge.postMessage(data);
                        return true;
                    },
                }
                : webView2Bridge
                    ? {
                        kind: 'webview2',
                        postMessage(payload) {
                            const data = typeof payload === 'string' ? payload : JSON.stringify(payload);
                            webView2Bridge.postMessage(data);
                            return true;
                        },
                    }
                    : androidBridge
                        ? {
                            kind: 'android',
                            postMessage(payload) {
                                const data = typeof payload === 'string' ? payload : JSON.stringify(payload);
                                androidBridge.postMessage(data);
                                return true;
                            },
                        }
                        : null;

        const defaultCaps = macBridge
            ? {
                sendMessage: true,
                sessionSync: true,
                networkConfig: true,
                setKey: true,
                saveStyle: true,
                saveMessageCache: true,
                downloadAttachment: true,
                serverHistory: true,
                avatarFetch: true,
                // The shell that serves this JS is the shell that handles it —
                // both ship from the same build, so there is no older-native case.
                editMessage: true,
                tenor: true,
                voice: true,
                windowDrag: true,
            }
            : transport
                ? {
                    sendMessage: true,
                sessionSync: true,
                networkConfig: true,
                setKey: true,
                saveStyle: true,
                saveMessageCache: true,
                downloadAttachment: false,
                serverHistory: false,
                // Mobile shells have no EDIT_MESSAGE handler; those fall back to
                // the in-browser WASM path (browserEditMessage).
                editMessage: false,
                tenor: false,
                voice: false,
                    windowDrag: false,
                }
                : {};

        const injectedCaps = window.__ZALI_NATIVE_CAPS__ && typeof window.__ZALI_NATIVE_CAPS__ === 'object'
            ? window.__ZALI_NATIVE_CAPS__
            : {};

        return {
            available: !!transport,
            transport: transport ? transport.kind : 'none',
            supports: { ...defaultCaps, ...injectedCaps },
            postMessage(payload) {
                if (!transport) return false;
                return transport.postMessage(payload);
            },
        };
    }

    window.__ZALI_NATIVE = createNativeBridge();

    // Register the app-shell service worker only in standalone browser/PWA mode — native
    // shells (macOS/Windows) load this HTML via loadHTMLString/a data string with no real
    // origin, where SW registration would be meaningless at best. See web/service-worker.js.
    if (!window.__ZALI_NATIVE?.available && 'serviceWorker' in navigator) {
        window.addEventListener('load', () => {
            navigator.serviceWorker.register('./service-worker.js').catch(() => {});
        });
    }

    // Create the minimal JS-side loader (only interface + styler)
    const loader = new ZaliLoader();

    // Register only frontend modules.
    // Crypto, Net, Bus logic live in the Rust backend (Core crate).
    loader.register(new ZaliStyler());
    loader.register(new ZaliInterface());

    // Initialize all registered modules
    loader.init();

    // Expose loader to window for native iOS/macOS WebView invocation
    window.loader = loader;
    
    // Legacy helper functions that native layer calls directly
    window.receiveMessage = function(...args) {
        if (args.length === 1 && args[0] && typeof args[0] === 'object') {
            loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.RECEIVE_MESSAGE || 'receive_message'}`, args[0]);
            return;
        }
        const [id, sender, receiver, text, attachments, serverId, channelId] = args;
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.RECEIVE_MESSAGE || 'receive_message'}`, { id, sender, receiver, text, attachments, serverId, channelId });
    };
    window.receiveReactionUpdate = function(payload) {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.REACTION_UPDATED || 'reaction_updated'}`, payload);
    };
    window.receiveMessageDeleted = function(payload) {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.MESSAGE_DELETED || 'message_deleted'}`, payload);
    };
    window.receiveMessageEdited = function(payload) {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.MESSAGE_EDITED || 'message_edited'}`, payload);
    };
    window.receiveVoiceEvent = function(payload) {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.VOICE_EVENT || 'voice_event'}`, payload);
    };
    // Общий приёмник WS-кадров от нативной оболочки. Оболочка зовёт его для
    // всего, что не разобрала сама, и передаёт кадр как есть — разбор целиком
    // на стороне JS (dispatchRealtimeEvent). Так новый тип события с сервера
    // не требует правок в macOS/Windows/Android по отдельности.
    window.receiveRealtimeEvent = function(payload) {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.REALTIME_EVENT || 'realtime_event'}`, payload);
    };
    window.setUsers = function(users) {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.SET_USERS || 'set_users'}`, users);
    };
    window.setContacts = function(contacts) {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.SET_CONTACTS || 'set_contacts'}`, contacts);
    };
    window.setSession = function(session) {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.SET_SESSION || 'set_session'}`, session);
    };
    window.loadHistory = function(messages) {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.LOAD_HISTORY || 'load_history'}`, messages);
    };
    window.refreshAfterKey = function() {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.REFRESH_AFTER_KEY || 'refresh_after_key'}`);
    };
    window.retryPublishKeys = function() {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.RETRY_PUBLISH_KEYS || 'retry_publish_keys'}`);
    };
    // Carries its payload, unlike retryPublishKeys: the scope decides which keys to
    // republish, and the answer includes historical candidates the sweep never sends.
    window.keyRepublishRequest = function(payload) {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.KEY_REPUBLISH_REQUEST || 'key_republish_request'}`, payload);
    };
    window.loadServerHistory = function(serverId, channelId, messages) {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.LOAD_SERVER_HISTORY || 'load_server_history'}`, { serverId, channelId, messages });
    };
    window.setLoading = function(on) {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.SET_LOADING || 'set_loading'}`, on);
    };
    window.setConnectionStatus = function(connected) {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.SET_CONNECTION_STATUS || 'set_connection_status'}`, connected);
    };
    window.avatarUpdated = function(username) {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.AVATAR_UPDATED || 'avatar_updated'}`, { username, deleted: false });
    };
    window.avatarDeleted = function(username) {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.AVATAR_UPDATED || 'avatar_updated'}`, { username, deleted: true });
    };
    window.addLog = function(type, msg) {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.ADD_LOG_ENTRY || 'add_log_entry'}`, { type, msg, ts: new Date().toLocaleTimeString() });
    };

    const hasNativeBridge = !!window.__ZALI_NATIVE?.available;
    if (!hasNativeBridge) {
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.SET_USERS || 'set_users'}`, ['Alice', 'Bob', 'Zalikus']);
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.SET_LOADING || 'set_loading'}`, false);
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.SET_CONNECTION_STATUS || 'set_connection_status'}`, false);
        loader.bus.send(`${'zali_interface'}:${window.ZaliBusEvents?.ADD_LOG_ENTRY || 'add_log_entry'}`, {
            type: 'WARN',
            msg: 'Запущен браузерный режим без native bridge: доступен просмотр интерфейса',
            ts: new Date().toLocaleTimeString()
        });
    }
})();

</script>
</body>
</html>

"""#,
    ]
}
